window.OPE_TESTS = {
1: {"tema": 1, "titulo": "Fundamentos de Enfermería, modelos teóricos y Constitución", "programa": "Fundamentos de la enfermería: historia, disciplina y profesión. Modelos teóricos de enfermería. La Constitución Española: derechos y deberes fundamentales. La organización territorial del Estado. El Estatuto de Autonomía de la Región de Murcia.", "preguntas": [{"q": "La primera escuela laica de enfermería, fundada por Florence Nightingale, fue la del:", "o": ["Instituto de Diaconisas de Kaiserswerth (1836)", "Hospital St. Thomas de Londres (1860)", "Hospital de Scutari (1854)", "Hôtel-Dieu de París (s. VII)"], "a": 1, "e": "La primera escuela laica fue la del Hospital St. Thomas (Londres, 1860). Kaiserswerth (1836) era un instituto protestante de diaconisas, donde se formó Nightingale."}, {"q": "El título de Enfermera se creó en España mediante:", "o": ["La Ley Moyano de 1857", "El RD 2128/1977", "Una Real Orden de 1915, a instancias de las Siervas de María", "La Ley General de Educación de 1970"], "a": 2, "e": "La Ley Moyano reguló practicantes y matronas, pero no enfermeras. El título de Enfermera llega con la Real Orden de 1915."}, {"q": "Los títulos de enfermera, practicante y matrona se unificaron en el título de ATS en el año:", "o": ["1944", "1953", "1970", "1977"], "a": 1, "e": "En 1953 se unifican en ATS. En 1977 la formación pasa a Escuelas Universitarias (diplomatura) y en 2007 llega el Grado."}, {"q": "¿Cuál de las siguientes NO es una especialidad de Enfermería del RD 450/2005?", "o": ["Enfermería de Salud Mental", "Enfermería Geriátrica", "Enfermería de Urgencias y Emergencias", "Enfermería del Trabajo"], "a": 2, "e": "Urgencias y Emergencias no es especialidad del RD 450/2005. Sí lo son: Obstétrico-Ginecológica, Salud Mental, Geriátrica, del Trabajo, Familiar y Comunitaria, Pediátrica y Cuidados Médico-Quirúrgicos."}, {"q": "Según Jacqueline Fawcett, NO forma parte del metaparadigma enfermero:", "o": ["Persona", "Entorno", "Salud", "Enfermedad"], "a": 3, "e": "Los 4 conceptos del metaparadigma son persona, entorno, salud y cuidado (enfermería). La enfermedad no es uno de ellos."}, {"q": "Según Kérouac, el modelo de Virginia Henderson pertenece al paradigma de:", "o": ["Categorización", "Integración", "Transformación", "Ninguno, por ser pionera"], "a": 1, "e": "Henderson se sitúa en el paradigma de Integración. La que no pertenece a ninguna escuela por ser pionera es Nightingale (paradigma de Categorización)."}, {"q": "¿Qué teórica pertenece a la escuela de los efectos deseables (\"¿por qué hacen las enfermeras lo que hacen?\")?", "o": ["Callista Roy", "Hildegard Peplau", "Virginia Henderson", "Jean Watson"], "a": 0, "e": "Efectos deseables: Johnson, Roy, Neuman y Levine. Peplau es de Interacción, Henderson de Necesidades y Watson del Caring."}, {"q": "¿Cuál de las siguientes NO es una fase de la relación enfermera-paciente según Peplau?", "o": ["Orientación", "Identificación", "Explotación o aprovechamiento", "Evaluación"], "a": 3, "e": "Las 4 fases de Peplau son Orientación, Identificación, Explotación y Resolución (O-I-E-R)."}, {"q": "Para Hildegard Peplau, el rol más importante de la enfermera es el de:", "o": ["Consejera", "Extraña", "Líder", "Sustituta"], "a": 0, "e": "Peplau describe 6 roles (extraño, persona recurso, docente, líder, sustituto y consejero), y el de consejero es el más importante."}, {"q": "Según Dorothea Orem, ante un paciente inconsciente la enfermera aplicará un sistema de enfermería:", "o": ["De apoyo-educación", "Parcialmente compensador", "Totalmente compensador", "De ayuda mutua"], "a": 2, "e": "Totalmente compensador: el paciente no puede realizar su autocuidado. Parcialmente compensador: se comparte. Apoyo-educación: el paciente puede, la enfermera enseña."}, {"q": "En el modelo de adaptación de Callista Roy, el estímulo que se enfrenta de manera inmediata es el:", "o": ["Focal", "Contextual", "Residual", "Regulador"], "a": 0, "e": "Focal = inmediato; contextuales = resto de estímulos presentes; residuales = de efecto incierto (creencias, experiencias). Regulador es un subsistema de afrontamiento."}, {"q": "El principio de homeodinámica de Martha Rogers que describe un cambio continuo, innovador e impredecible, en espiral, es la:", "o": ["Resonancia", "Integralidad", "Helicidad", "Reciprocidad"], "a": 2, "e": "Helicidad = cambio en espiral. Resonancia = cambios en los patrones de onda. Integralidad = interacción mutua persona-entorno."}, {"q": "Según Leininger, cuando la enfermera ayuda a cambiar una práctica cultural nociva para la salud, aplica el modo de acción de:", "o": ["Conservación", "Negociación", "Mantenimiento", "Reestructuración"], "a": 3, "e": "Conservación o mantenimiento: prácticas beneficiosas. Adaptación o negociación: ajustar. Reestructuración o reorientación: cambiar las prácticas nocivas."}, {"q": "Los 11 patrones funcionales de salud para la valoración se deben a:", "o": ["Marjory Gordon", "Faye G. Abdellah", "Roper, Logan y Tierney", "Dorothy Johnson"], "a": 0, "e": "Gordon = 11 patrones; Abdellah = 21 problemas; Roper-Logan-Tierney = 12 actividades de la vida; Johnson = 7 subsistemas."}, {"q": "El modelo \"De principiante a experta\" de Patricia Benner se basa en el modelo de adquisición de habilidades de:", "o": ["Maslow", "Dreyfus", "Bandura", "Erikson"], "a": 1, "e": "Benner aplica el modelo de Dreyfus y describe 5 niveles: principiante, principiante avanzada, competente, eficiente y experta."}, {"q": "El concepto central de la teoría de Florence Nightingale es:", "o": ["El autocuidado", "La adaptación", "El entorno", "La interacción"], "a": 2, "e": "En la Teoría del Entorno, la enfermera sitúa al paciente en las mejores condiciones (ventilación, luz, temperatura, ruido, dieta, higiene) para que la naturaleza actúe."}, {"q": "Según Virginia Henderson, las fuentes de dificultad que impiden satisfacer las necesidades son la falta de:", "o": ["Fuerza, conocimiento o voluntad", "Agencia de autocuidado", "Adaptación a los estímulos focales", "Líneas de defensa ante los estresores"], "a": 0, "e": "Henderson: falta de fuerza, conocimiento o voluntad. La agencia de autocuidado es de Orem, los estímulos de Roy y los estresores de Neuman."}, {"q": "¿Cuántos factores de cuidado (carative factors) describió Jean Watson?", "o": ["7", "10", "12", "14"], "a": 1, "e": "Watson describió 10 factores de cuidado, que después evolucionaron a los procesos caritas. 14 son las necesidades de Henderson."}, {"q": "La Constitución Española entró en vigor el:", "o": ["31 de octubre de 1978", "6 de diciembre de 1978", "27 de diciembre de 1978", "29 de diciembre de 1978"], "a": 3, "e": "Aprobada por las Cortes el 31/10, referéndum el 6/12, sanción el 27/12 y entrada en vigor con su publicación en el BOE el 29/12/1978."}, {"q": "¿Cuál de los siguientes NO es un valor superior del ordenamiento jurídico según el art. 1.1 de la Constitución?", "o": ["La libertad", "La justicia", "El pluralismo político", "La solidaridad"], "a": 3, "e": "Los valores superiores son solo cuatro: libertad, justicia, igualdad y pluralismo político."}, {"q": "El derecho a la protección de la salud (art. 43 CE) se encuentra en:", "o": ["La Sección 1ª del Capítulo II del Título I", "La Sección 2ª del Capítulo II del Título I", "El Título VIII", "El Capítulo III del Título I (principios rectores)"], "a": 3, "e": "El art. 43 es un principio rector de la política social y económica: no es exigible directamente ante el juez ni tiene recurso de amparo."}, {"q": "¿Cuál de los siguientes derechos está protegido por el recurso de amparo ante el Tribunal Constitucional?", "o": ["El derecho a una vivienda digna (art. 47)", "La objeción de conciencia (art. 30.2)", "La protección de la salud (art. 43)", "La propiedad privada (art. 33)"], "a": 1, "e": "El amparo protege el art. 14, los arts. 15-29 y el art. 30.2 (objeción de conciencia), aunque este esté en la Sección 2ª."}, {"q": "Según el art. 17 de la Constitución, la detención preventiva no podrá durar más de:", "o": ["24 horas", "48 horas", "72 horas", "96 horas"], "a": 2, "e": "Máximo 72 horas; después, libertad o puesta a disposición judicial. Existe además el procedimiento de habeas corpus."}, {"q": "Un decreto-ley debe ser convalidado o derogado:", "o": ["Por el Senado en 15 días", "Por el Senado en 30 días", "Por el Congreso en 2 meses", "Por el Congreso en 30 días"], "a": 3, "e": "El Congreso debe pronunciarse en los 30 días siguientes a su promulgación (art. 86). En el decreto-ley el control es posterior."}, {"q": "La moción de censura al Gobierno requiere para su aprobación:", "o": ["Mayoría absoluta del Congreso", "Mayoría simple del Congreso", "Tres quintos del Congreso", "Dos tercios de ambas Cámaras"], "a": 0, "e": "La propone al menos 1/10 de los diputados, es constructiva (incluye candidato) y exige mayoría absoluta (176). La cuestión de confianza se gana por mayoría simple."}, {"q": "Según el art. 149.1.16 de la Constitución, NO es competencia exclusiva del Estado:", "o": ["La sanidad exterior", "Las bases y coordinación general de la sanidad", "La legislación sobre productos farmacéuticos", "La gestión de los centros de salud y hospitales"], "a": 3, "e": "La gestión de la asistencia (hospitales, centros de salud) corresponde a las CC. AA. (art. 148.1.21), en Murcia a través del SMS."}, {"q": "El Estatuto de Autonomía de la Región de Murcia se aprobó el:", "o": ["9 de junio de 1982", "6 de diciembre de 1978", "26 de julio de 1994", "9 de junio de 1983"], "a": 0, "e": "Se aprobó el 9 de junio de 1982, fecha que coincide con el Día de la Región. Murcia accedió a la autonomía por el art. 143 CE."}, {"q": "La sede de la Asamblea Regional de Murcia está en:", "o": ["Murcia", "Lorca", "Cartagena", "Molina de Segura"], "a": 2, "e": "Murcia es la capital y sede de la Presidencia y del Consejo de Gobierno; la Asamblea Regional tiene su sede en Cartagena."}, {"q": "Tras la reforma de 2015, el sistema electoral de la Asamblea Regional de Murcia se caracteriza por:", "o": ["45 diputados, circunscripción única y barrera del 3%", "45 diputados, 5 circunscripciones y barrera del 5%", "55 diputados, circunscripción única y barrera del 3%", "45 diputados, circunscripción única y barrera del 5%"], "a": 0, "e": "45 diputados con mandato de 4 años, circunscripción única (antes 5) y barrera del 3% (antes 5%)."}, {"q": "Señale la afirmación correcta:", "o": ["Para ser Presidente del Gobierno de la Nación hay que ser diputado", "Para ser Presidente de la Región de Murcia hay que ser Diputado Regional", "Los Consejeros regionales se nombran tras votación de la Asamblea", "La moción de censura regional se aprueba por mayoría simple"], "a": 1, "e": "El candidato a Presidente de Murcia debe ser Diputado Regional; el del Gobierno de la Nación, no. Los Consejeros los nombra libremente el Presidente y la moción de censura exige mayoría absoluta."}]},
2: {"tema": 2, "titulo": "Organización de los cuidados en AP y AE. Ley General de Sanidad y Ley de Salud de la Región de Murcia", "programa": "Organización de los cuidados enfermeros en Atención Primaria y Atención Especializada: consulta de enfermería, enfermería de práctica avanzada, coordinación entre niveles, enfermera referente, escolar y gestora de casos. Ley 14/1986 General de Sanidad. Ley 4/1994 de Salud de la Región de Murcia.", "preguntas": [{"q": "Según la Ley 14/1986, General de Sanidad, las Áreas de Salud se delimitarán con carácter general para atender a una población:", "o": ["Entre 5.000 y 25.000 habitantes", "Entre 100.000 y 150.000 habitantes", "No inferior a 200.000 ni superior a 250.000 habitantes", "No inferior a 250.000 ni superior a 300.000 habitantes"], "a": 2, "e": "La LGS fija para el Área de Salud una horquilla de 200.000-250.000 habitantes (con excepciones). La de 5.000-25.000 corresponde a la Zona Básica de Salud."}, {"q": "El Consejo Interterritorial del Sistema Nacional de Salud está presidido por:", "o": ["El Presidente del Gobierno", "La persona titular del Ministerio de Sanidad", "Un consejero autonómico elegido por rotación anual", "El Director del Instituto de Salud Carlos III"], "a": 1, "e": "La presidencia del CISNS corresponde al titular del Ministerio de Sanidad. La vicepresidencia la ocupa un consejero autonómico elegido por y entre ellos."}, {"q": "La Ley 14/1986, General de Sanidad, entró en vigor el:", "o": ["25 de abril de 1986", "29 de abril de 1986", "19 de mayo de 1986", "1 de enero de 1987"], "a": 2, "e": "Se aprobó el 25 de abril, se publicó en el BOE el 29 de abril y entró en vigor a los 20 días, el 19 de mayo de 1986."}, {"q": "El atributo de la Atención Primaria que se refiere a la relación personal y continuada en el tiempo entre el paciente y su profesional, esté o no enfermo, es la:", "o": ["Longitudinalidad", "Continuidad asistencial", "Integralidad", "Accesibilidad"], "a": 0, "e": "La longitudinalidad es la relación a lo largo del tiempo con el profesional. La continuidad se refiere a que el proceso asistencial no se interrumpa entre niveles."}, {"q": "Si en un enunciado se describe el abordaje del paciente desde una perspectiva biopsicosocial, ¿a qué atributo de la Atención Primaria se refiere?", "o": ["Coordinación", "Accesibilidad", "Longitudinalidad", "Integralidad"], "a": 3, "e": "La integralidad supone atender a la persona en su dimensión biológica, psicológica y social, en su contexto."}, {"q": "¿Qué norma regula las vacaciones, permisos y carrera profesional de una enfermera del SMS?", "o": ["Ley 44/2003, de ordenación de las profesiones sanitarias", "Ley 16/2003, de cohesión y calidad del SNS", "Ley 55/2003, del Estatuto Marco del personal estatutario", "Ley 41/2002, básica reguladora de la autonomía del paciente"], "a": 2, "e": "El Estatuto Marco (Ley 55/2003) regula las condiciones de trabajo. La LOPS (44/2003) regula títulos y funciones, y la Ley 16/2003, la cartera de servicios."}, {"q": "Según la Ley 4/1994, de Salud de la Región de Murcia, el Defensor del Usuario:", "o": ["Se integra en la Dirección Gerencia del Servicio Murciano de Salud", "Se adscribe a la Consejería de Salud para garantizar su independencia", "Depende de la Asamblea Regional", "Es un órgano del Consejo de Administración del SMS"], "a": 1, "e": "El Defensor del Usuario no se adscribe al SMS, sino a la Consejería, para no actuar como juez y parte frente a las gerencias."}, {"q": "Según el mapa sanitario de la Región de Murcia, ¿cuántas Zonas Básicas de Salud y cuántos Centros de Salud existen?", "o": ["85 Zonas Básicas y 90 Centros de Salud", "90 Zonas Básicas y 85 Centros de Salud", "90 Zonas Básicas y 90 Centros de Salud", "85 Zonas Básicas y 85 Centros de Salud"], "a": 1, "e": "Hay 90 ZBS y 85 centros de salud, porque algunas zonas comparten infraestructura. Es falso que haya tantos centros como zonas."}, {"q": "¿Cuál es el Área de Salud de la Región de Murcia con mayor población asignada y mayor número de consultorios locales?", "o": ["Área I, Murcia Oeste", "Área VI, Vega Media del Segura", "Área III, Lorca", "Área II, Cartagena"], "a": 3, "e": "El Área II (Cartagena) tiene la mayor población (unas 249.700 tarjetas) y 44 consultorios. Lorca es la más extensa y Vega Alta la de menor población."}, {"q": "Tras el Decreto 343/2023, ¿cuál de las siguientes NO es una Dirección General del Servicio Murciano de Salud?", "o": ["Dirección General de Atención Primaria", "Dirección General de Salud Mental", "Dirección General de Asistencia Sanitaria", "Dirección General de Recursos Humanos"], "a": 2, "e": "La antigua DG de Asistencia Sanitaria desapareció. Las cuatro actuales son Atención Primaria, Atención Hospitalaria, Salud Mental y Recursos Humanos."}, {"q": "El Consejo de Administración del Servicio Murciano de Salud está presidido por:", "o": ["El Director Gerente del SMS", "El Consejero competente en materia de sanidad", "El Presidente de la Comunidad Autónoma", "El Secretario General Técnico"], "a": 1, "e": "La presidencia recae en el Consejero de Salud. El Director Gerente es la máxima autoridad ejecutiva unipersonal."}, {"q": "Según el Decreto 54/2016, la presidencia del Consejo de Salud de Área corresponde a:", "o": ["El alcalde del municipio más poblado del área", "El Delegado de Salud y Consumo", "La Dirección de Enfermería del Área", "El Gerente del Área de Salud"], "a": 3, "e": "El Consejo de Salud de Área lo preside de forma nata el Gerente del Área. No confundir con el Consejo de Administración del SMS (Consejero)."}, {"q": "En la composición del Consejo de Salud de Área, el bloque con mayor número de vocales es el de:", "o": ["La Administración sanitaria (SMS)", "Las organizaciones sindicales", "Las organizaciones empresariales", "La Administración local (ayuntamientos)"], "a": 3, "e": "Ayuntamientos: 4 vocales; SMS: 3; sindicatos: 2; empresarios: 2. El secretario tiene voz pero no voto."}, {"q": "Según el Decreto 54/2016, los Consejos de Salud de Zona:", "o": ["Son obligatorios en cada Zona Básica de Salud", "Están presididos por el Gerente del Área", "Tienen carácter facultativo", "Forman parte del Consejo de Administración del SMS"], "a": 2, "e": "Los Consejos de Área son obligatorios en las 9 áreas; los de Zona se constituyen solo \"en su caso\" (carácter facultativo)."}, {"q": "Según el RD 1302/2018, ¿qué experiencia profesional mínima se exige para acreditar a una enfermera en la indicación, uso y autorización de dispensación de medicamentos?", "o": ["6 meses", "1 año", "2 años", "3 años"], "a": 1, "e": "Se exige 1 año de experiencia profesional o, en su defecto, superar un curso de adaptación."}, {"q": "La acreditación de las enfermeras para la indicación de medicamentos la otorga:", "o": ["El Ministerio de Sanidad", "El Consejo General de Enfermería", "El Colegio Oficial de Enfermería provincial", "La Comunidad Autónoma correspondiente"], "a": 3, "e": "La acreditación la concede la Comunidad Autónoma (en Murcia, la Consejería de Salud), no el Ministerio ni los colegios."}, {"q": "Para que una enfermera acreditada indique un medicamento sujeto a prescripción médica (por ejemplo, una vacuna o una insulina) se requiere:", "o": ["Una orden escrita del médico para cada dispensación", "La existencia de protocolos o guías de práctica clínica y asistencial validados", "Ser especialista vía EIR", "Nada más: es una actuación autónoma"], "a": 1, "e": "Con medicamentos sujetos a prescripción la actuación es colaborativa: solo dentro de protocolos o guías validados. La autónoma se limita a productos sanitarios y medicamentos no sujetos a prescripción."}, {"q": "Una enfermera acreditada decide indicar un apósito de plata (producto sanitario) a un paciente. Esta actuación es:", "o": ["Autónoma", "Colaborativa, solo bajo protocolo del Ministerio", "Exclusiva de la enfermera especialista", "Exclusiva de Atención Especializada"], "a": 0, "e": "Los productos sanitarios y los medicamentos no sujetos a prescripción médica se indican de forma autónoma."}, {"q": "El modelo de Enfermería Primaria (enfermera referente) fue desarrollado por:", "o": ["Virginia Henderson", "Dorothea Orem", "Marie Manthey", "Barbara Starfield"], "a": 2, "e": "Marie Manthey lo desarrolló en EE. UU. en los años 70. Starfield describió los atributos de la Atención Primaria."}, {"q": "En una planta, la enfermera A reparte la medicación, la B hace las curas y la C toma las constantes de todos los pacientes. Se trata de un modelo de organización:", "o": ["Funcional o por tareas", "De enfermería primaria", "De enfermería en equipo", "De gestión de casos"], "a": 0, "e": "Repartir el trabajo por tareas es el modelo funcional, que genera una alta fragmentación de los cuidados."}, {"q": "En la pirámide de estratificación de Kaiser Permanente, la enfermera gestora de casos interviene en:", "o": ["El nivel 1: promoción y prevención", "El nivel 2: seguimiento protocolizado de crónicos estables", "La base de la pirámide (70-80% de la población)", "El nivel 3: pacientes de alta complejidad"], "a": 3, "e": "La gestión de casos corresponde al vértice de la pirámide (nivel 3, alrededor del 5% de la población, de alta complejidad)."}, {"q": "Para definir a un paciente como pluripatológico, susceptible de gestión de casos, se utilizan:", "o": ["Los criterios de Ollero", "El índice de Barthel", "La escala de Lawton y Brody", "El test de Pfeiffer"], "a": 0, "e": "Los criterios de Ollero agrupan las enfermedades crónicas en 8 categorías (A-H); es pluripatológico quien cumple 2 o más."}, {"q": "El programa informático de historia clínica utilizado mayoritariamente en las consultas de Atención Primaria del SMS es:", "o": ["Selene", "OMI-AP", "Diraya", "Ágora Plus"], "a": 1, "e": "En AP del SMS se usa OMI-AP; en Atención Especializada (hospital), Selene."}, {"q": "El objetivo fundamental de las vías clínicas compartidas es:", "o": ["Aumentar la autonomía de cada profesional", "Sustituir los informes de alta", "Eliminar la derivación entre niveles", "Reducir la variabilidad clínica"], "a": 3, "e": "Las vías clínicas estandarizan el itinerario asistencial basado en la evidencia y reducen la variabilidad clínica."}, {"q": "El médico de Atención Primaria puede consultar la analítica que se hizo a su paciente durante el ingreso hospitalario. Esto es un ejemplo de continuidad:", "o": ["De relación", "De gestión", "De información", "Longitudinal"], "a": 2, "e": "La continuidad de información garantiza que los datos clínicos estén disponibles. La de gestión evita solapamientos (mismo protocolo, no duplicar pruebas)."}, {"q": "Dentro de un servicio clínico hospitalario, la organización, planificación y evaluación de los cuidados enfermeros corresponde a:", "o": ["El Supervisor de Enfermería", "El Jefe de Servicio", "El Director Médico", "El Gerente del Área"], "a": 0, "e": "El Jefe de Servicio es el responsable médico. Los cuidados los organiza el Supervisor de Enfermería."}, {"q": "La duración orientativa de una consulta de enfermería programada es de:", "o": ["15-20 minutos", "10-15 minutos", "30-40 minutos", "5-10 minutos"], "a": 0, "e": "A demanda: 10-15 min; programada: 15-20 min; primera valoración integral: 30-40 min."}, {"q": "Sobre la enfermera escolar en la Región de Murcia, es correcto que:", "o": ["Está presente sobre todo en Centros de Educación Especial; en los colegios ordinarios la EpS la realiza la enfermera de AP de la zona", "Su presencia es obligatoria en todos los institutos según la Ley 33/2011", "Es una especialidad regulada por el RD 450/2005", "Depende orgánicamente de la Dirección General de Atención Hospitalaria"], "a": 0, "e": "No hay norma que obligue a su presencia. En Murcia está sobre todo en Centros de Educación Especial; el resto se cubre con enfermeras de AP."}, {"q": "Según la Ley General de Sanidad, quedan exceptuadas de la norma poblacional de las Áreas de Salud:", "o": ["Madrid y Cataluña", "Las comunidades autónomas uniprovinciales", "Murcia y La Rioja", "Baleares, Canarias, Ceuta y Melilla"], "a": 3, "e": "Por su carácter insular o geográficamente especial se exceptúan Baleares, Canarias, Ceuta y Melilla. Además, cada provincia tendrá al menos un Área."}, {"q": "Según el art. 26 de la Ley 4/1994, las normas de organización y funcionamiento de los Equipos de Atención Primaria en las Zonas Básicas de Salud se aprueban:", "o": ["Por Orden del Consejero de Salud", "Por Resolución del Director Gerente del SMS", "Por Decreto del Consejo de Gobierno", "Por Ley de la Asamblea Regional"], "a": 2, "e": "Corresponde al Consejo de Gobierno regional mediante Decreto."}]},
3: {"tema": 3, "titulo": "Proceso enfermero. Derechos y deberes de los usuarios (Ley 3/2009) y Ley de Transparencia de Murcia", "programa": "El proceso enfermero: conceptos, características, ventajas y fases (valoración, diagnóstico, planificación, ejecución y evaluación). Ley 3/2009, de 11 de mayo, de los derechos y deberes de los usuarios del sistema sanitario de la Región de Murcia. Ley 12/2014, de 16 de diciembre, de Transparencia y Participación Ciudadana de la Región de Murcia.", "preguntas": [{"q": "El orden correcto de las fases del proceso de atención de enfermería es:", "o": ["Valoración, diagnóstico, planificación, ejecución y evaluación", "Diagnóstico, valoración, planificación, ejecución y evaluación", "Valoración, planificación, diagnóstico, ejecución y evaluación", "Valoración, diagnóstico, ejecución, planificación y evaluación"], "a": 0, "e": "Son 5 fases cíclicas: valoración, diagnóstico, planificación, ejecución y evaluación; la evaluación retroalimenta una nueva valoración."}, {"q": "La definición de valoración como \"proceso organizado y sistemático de búsqueda de información realizado a partir de diversas fuentes\" para conocer el grado de satisfacción de las necesidades se atribuye a:", "o": ["Carpenito", "Phaneuf", "Alfaro-Lefevre", "Berman"], "a": 1, "e": "Es la definición de Margot Phaneuf. Carpenito y Alfaro destacan en la planificación de objetivos; Berman define los objetivos."}, {"q": "Para la valoración inicial, NANDA-I recomienda utilizar como guía:", "o": ["Los 13 dominios de la propia taxonomía NANDA-I", "Las 7 clases de la NIC", "Los 11 patrones funcionales de Marjory Gordon", "La pirámide de necesidades de Maslow"], "a": 2, "e": "NANDA-I recomienda la estructura de patrones funcionales de Gordon para la valoración, en lugar de los dominios de su taxonomía."}, {"q": "Un diagnóstico enfermero de riesgo se formula con el formato:", "o": ["PES", "PS", "P", "PE"], "a": 3, "e": "El diagnóstico de riesgo no tiene síntomas porque el problema aún no existe: Problema + Etiología (factores de riesgo)."}, {"q": "El formato PES para enunciar los diagnósticos enfermeros fue difundido por:", "o": ["Marjory Gordon", "Virginia Henderson", "Dorothea Orem", "Lynda Carpenito"], "a": 0, "e": "El formato Problema-Etiología-Síntomas lo publicó Marjory Gordon en su guía de diagnósticos."}, {"q": "Según la edición 2024-2026, la taxonomía II de NANDA-I se organiza en:", "o": ["11 dominios, 40 clases y 244 diagnósticos", "7 dominios, 30 clases y 614 diagnósticos", "13 dominios, 47 clases y 277 diagnósticos", "13 dominios, 32 clases y 540 diagnósticos"], "a": 2, "e": "NANDA-I 2024-2026: 13 dominios, 47 clases y 277 diagnósticos. 614 son las intervenciones NIC y unos 540 los resultados NOC."}, {"q": "Según Alfaro, el objetivo \"El paciente demostrará la técnica de inyección de insulina\" pertenece al dominio:", "o": ["Afectivo", "Psicomotor", "Cognitivo", "Conductual-emocional"], "a": 1, "e": "Psicomotor: habilidades motoras. Cognitivo: conocimientos (enumerar síntomas). Afectivo: actitudes y valores (aceptar la dieta)."}, {"q": "Según Carpenito, los objetivos de la enfermera (y no del paciente) se proponen para:", "o": ["Los diagnósticos de riesgo", "Los diagnósticos de promoción de la salud", "Los diagnósticos reales", "Los problemas de colaboración"], "a": 3, "e": "Para los diagnósticos de enfermería se plantean objetivos del paciente; para los problemas de colaboración, objetivos de la enfermera."}, {"q": "En la escala Likert de los indicadores NOC:", "o": ["1 es el peor estado y 5 el mejor estado", "1 es el mejor estado y 5 el peor estado", "Se puntúa de 0 a 10", "Solo se usa en la fase de valoración"], "a": 0, "e": "Escala de 5 puntos: 1 = gravemente comprometido o nunca demostrado; 5 = no comprometido o siempre demostrado. El objetivo es subir la puntuación."}, {"q": "La 8.ª edición de la Clasificación de Intervenciones de Enfermería (NIC, 2024) incluye:", "o": ["277 intervenciones", "540 intervenciones", "614 intervenciones", "700 intervenciones"], "a": 2, "e": "La NIC 2024 recoge 614 intervenciones en 7 dominios y 30 clases, con 60 nuevas y 11 eliminadas."}, {"q": "Según Alfaro-Lefevre, cuando la enfermera delega una tarea en un profesional competente:", "o": ["Transfiere también la responsabilidad de los resultados", "Queda exenta de supervisarla", "Solo puede delegar en otra enfermera", "Mantiene la responsabilidad de los resultados"], "a": 3, "e": "Delegar es traspasar la autoridad para hacer una tarea concreta manteniendo la responsabilidad final de los resultados."}, {"q": "En la fase de evaluación, si un objetivo no se ha alcanzado porque el plan inicial era inadecuado, la decisión correcta es:", "o": ["Continuar el plan sin cambios", "Modificar el plan de cuidados", "Finalizar el plan", "Dar de alta al paciente"], "a": 1, "e": "Se modifica (reformular diagnóstico, objetivos o intervenciones). Se continúa si es parcial y el plan es adecuado; se finaliza si se logró."}, {"q": "La Ley de derechos y deberes de los usuarios del sistema sanitario de la Región de Murcia es la:", "o": ["Ley 3/2009, de 11 de mayo", "Ley 3/2009, de 11 de marzo", "Ley 4/1994, de 26 de julio", "Ley 12/2014, de 16 de diciembre"], "a": 0, "e": "Ley 3/2009, de 11 de mayo. La Ley 4/1994 es la de Salud y la 12/2014 la de Transparencia."}, {"q": "El plazo máximo de demora garantizado en la Región de Murcia para una intervención quirúrgica es de:", "o": ["50 días", "90 días", "150 días", "180 días"], "a": 2, "e": "Cirugía 150 días, primeras consultas externas 50 días y primeras pruebas diagnósticas 30 días naturales."}, {"q": "El plazo máximo garantizado para las primeras pruebas diagnósticas en el SMS es de:", "o": ["30 días hábiles", "50 días naturales", "20 días hábiles", "30 días naturales"], "a": 3, "e": "Son 30 días naturales. Los \"días hábiles\" son el distractor típico."}, {"q": "Sobre la Tarjeta Sanitaria Individual, la Ley 3/2009 establece que:", "o": ["Puede cederse a familiares de primer grado", "Incorporará el sistema Braille de forma sistemática", "Incluirá Braille solo si el usuario acredita discapacidad visual", "Es opcional para acceder a las prestaciones"], "a": 1, "e": "La TSI es personal e intransferible y debe incorporar el Braille de forma sistemática, no a demanda."}, {"q": "Tras un parto eutócico, con un recién nacido vigoroso y estable, la actuación prioritaria de la enfermera o matrona según la Ley 3/2009 (reformada en 2018) es:", "o": ["Facilitar el contacto piel con piel inmediato e ininterrumpido", "Pesar y tallar al recién nacido en la cuna térmica", "Administrar la vitamina K y la profilaxis ocular de inmediato", "Trasladarlo al nido para su observación"], "a": 0, "e": "El art. 16, modificado por la Ley 12/2018, reconoce el derecho al piel con piel inmediato e ininterrumpido; las rutinas se posponen."}, {"q": "Durante una cura, un grupo de estudiantes no implicados en la atención desea estar presente. Esto afecta principalmente al derecho a la:", "o": ["Confidencialidad", "Información asistencial", "Intimidad", "Libre elección"], "a": 2, "e": "La intimidad protege el cuerpo, el pudor y el espacio. Se informa antes al paciente, que puede negarse sin perjuicio de su asistencia."}, {"q": "¿En cuál de estas situaciones cede el deber de confidencialidad según la Ley 3/2009?", "o": ["Cuando lo pide un familiar directo", "Cuando lo solicita la empresa del trabajador", "Cuando el paciente es mayor de 65 años", "Ante una enfermedad de declaración obligatoria"], "a": 3, "e": "Excepciones: salud pública (EDO, riesgo colectivo), mandato judicial o del Ministerio Fiscal y perjuicio grave e inminente a un tercero."}, {"q": "El llamado privilegio terapéutico o necesidad terapéutica:", "o": ["Lo ejerce el paciente cuando no quiere ser informado", "Lo ejerce el médico cuando informar causaría un daño grave al paciente", "Lo ejerce la familia para proteger al paciente", "Permite actuar sin consentimiento en urgencias"], "a": 1, "e": "La necesidad terapéutica la aplica el médico, justificándola en la historia. El derecho a no saber lo ejerce el paciente."}, {"q": "Según la Ley 3/2009, ¿cuál de estas actuaciones requiere consentimiento informado por escrito?", "o": ["Una intervención quirúrgica", "La toma de constantes vitales", "Una extracción de sangre rutinaria", "La canalización de una vía venosa periférica"], "a": 0, "e": "La regla general es el consentimiento verbal. Es escrito en cirugía, procedimientos invasivos, investigación y riesgos de notoria repercusión negativa."}, {"q": "En el consentimiento por sustitución, el primer lugar en el orden de prelación corresponde a:", "o": ["El cónyuge o pareja de hecho", "Los hijos mayores de edad", "La persona designada como representante en el documento de instrucciones previas", "El representante legal designado judicialmente"], "a": 2, "e": "Orden: representante de instrucciones previas, representante legal, cónyuge o pareja, y parientes más próximos (a igual grado, el mayor)."}, {"q": "Un paciente de 17 años, no incapacitado, necesita una cirugía de grave riesgo para su vida. El consentimiento:", "o": ["Lo otorga el propio menor y basta con informar a sus padres", "Lo otorga el juez", "Lo otorgan conjuntamente el menor y un médico ajeno al caso", "Lo otorga su representante legal, una vez oída y tenida en cuenta la opinión del menor"], "a": 3, "e": "Desde los 16 años hay mayoría de edad sanitaria, pero en las actuaciones de grave riesgo la Ley 41/2002 (reformada en 2015) atribuye el consentimiento al representante legal, tras oír al menor. El manual del tema 3 recoge la redacción antigua."}, {"q": "Si el documento de instrucciones previas se formaliza ante testigos, se requieren:", "o": ["Dos testigos sin parentesco", "Tres testigos, de los que al menos dos no tengan parentesco hasta el segundo grado ni relación patrimonial con el otorgante", "Tres testigos, ninguno de ellos familiar", "Cinco testigos mayores de edad"], "a": 1, "e": "Regla 3-2-2: tres testigos mayores de edad y capaces; al menos dos sin parentesco hasta el 2.º grado ni vínculo patrimonial. Uno sí puede ser familiar."}, {"q": "Según el manual, la documentación clínica en la Región de Murcia debe conservarse como mínimo:", "o": ["20 años desde la fecha del alta del último proceso asistencial", "5 años desde la creación de cada documento", "20 años desde el nacimiento del paciente", "15 años desde el primer ingreso"], "a": 0, "e": "Se cuentan 20 años desde el último alta, ampliando el mínimo de 5 años de la ley básica estatal."}, {"q": "El derecho del paciente a acceder a su historia clínica tiene como límites:", "o": ["Los informes de alta y las pruebas de imagen", "Los registros de enfermería", "Los datos de terceros y las anotaciones subjetivas de los profesionales", "Los resultados de laboratorio"], "a": 2, "e": "No puede ejercerse en perjuicio de la confidencialidad de terceros ni del derecho de reserva de los profesionales sobre sus anotaciones subjetivas."}, {"q": "Un paciente rechaza el tratamiento propuesto y además se niega a firmar el alta voluntaria. Según el art. 64 de la Ley 3/2009:", "o": ["Se le retiene en el hospital hasta que firme", "Se solicita autorización judicial para tratarle", "Se le aplica el tratamiento por estado de necesidad", "La dirección del centro, a propuesta del facultativo, dispondrá el alta forzosa"], "a": 3, "e": "Ante la doble negativa, la dirección del centro dispone el alta forzosa, dejando constancia en la historia clínica."}, {"q": "El SMS publica en su portal, sin que nadie lo haya solicitado, las retribuciones de sus altos cargos. Según la Ley 12/2014, esto es:", "o": ["Derecho de acceso", "Publicidad activa", "Participación ciudadana", "Valoración documental"], "a": 1, "e": "Cuando la Administración difunde por iniciativa propia es publicidad activa. El derecho de acceso se activa a petición del ciudadano."}, {"q": "Si la Administración no responde en plazo a una solicitud de acceso a información pública, el silencio tiene carácter:", "o": ["Negativo (desestimatorio)", "Positivo (estimatorio)", "Positivo solo si la información es sanitaria", "Suspensivo hasta que resuelva el juez"], "a": 0, "e": "El vencimiento del plazo (20 días hábiles, prorrogables) sin resolución expresa supone silencio negativo."}, {"q": "Según el manual, el órgano garante actual en materia de transparencia en la Región de Murcia es:", "o": ["El Consejo de la Transparencia, órgano colegiado", "El Defensor del Usuario", "El Comisionado de la Transparencia, órgano unipersonal", "La Asamblea Regional"], "a": 2, "e": "El antiguo Consejo de la Transparencia (colegiado) se suprimió; hoy lo sustituye el Comisionado de la Transparencia, con mandato de 4 años."}]},
4: {"tema": 4, "titulo": "Gestión de servicios sanitarios y de enfermería. Prestaciones del SNS (Ley 16/2003)", "programa": "Gestión de servicios sanitarios: tendencias actuales. Planificación: concepto. Planificación operativa: objetivos, actividades y recursos. La gestión de los servicios de enfermería. Producto sanitario y producto enfermero: concepto y sistemas de medición. Cartera de servicios. Gestión de recursos humanos: motivación, liderazgo, comunicación. Las prestaciones del SNS en la Ley 16/2003: ordenación, cartera, garantías, sistema de información sanitaria y Consejo Interterritorial.", "preguntas": [{"q": "La distribución del presupuesto, la adecuación de infraestructuras y la dotación de plantillas corresponde a la planificación:", "o": ["Estratégica", "Normativa", "Táctica", "Operativa"], "a": 2, "e": "La planificación táctica (mesogestión, 1-3 años) distribuye los recursos. La estratégica fija directrices y la operativa organiza las tareas."}, {"q": "El producto documental propio de la planificación estratégica es:", "o": ["El Plan de Salud", "El Programa de Salud", "El plan operativo anual", "El protocolo de unidad"], "a": 0, "e": "Estratégica = Plan; táctica = Programa; operativa = plan operativo y tareas."}, {"q": "El horizonte temporal habitual de la planificación táctica es de:", "o": ["Menos de 1 año", "1 a 3 años", "4 a 10 años", "Más de 10 años"], "a": 1, "e": "Estratégica: 4-10 años; táctica: 1-3 años; operativa: 1 año o menos."}, {"q": "En el método de priorización de Hanlon, el componente C (eficacia o vulnerabilidad) se puntúa entre:", "o": ["0 y 10", "0 y 1", "1 y 5", "0,5 y 1,5"], "a": 3, "e": "A (magnitud) y B (severidad) van de 0 a 10; C, de 0,5 a 1,5; D (PERLA) es 0 o 1."}, {"q": "En el método de Hanlon, si el factor de legalidad (L) del componente PERLA es 0:", "o": ["La puntuación total del problema es 0", "Se resta un punto a la puntuación total", "El componente D pasa a valer 0,5", "No afecta a la puntuación final"], "a": 0, "e": "La fórmula es (A+B) × C × D. Si cualquier factor PERLA es 0, D vale 0 y se anula la prioridad del problema."}, {"q": "Según Donabedian, el porcentaje de pacientes a los que se les realiza la escala de Braden al ingreso es un indicador de:", "o": ["Estructura", "Proceso", "Resultado", "Impacto"], "a": 1, "e": "Lo que la enfermera hace sobre el paciente es proceso. La prevalencia de UPP sería un indicador de resultado."}, {"q": "¿Cuál de los siguientes es un indicador de resultado según Donabedian?", "o": ["La ratio enfermera/paciente", "La existencia de un protocolo aprobado", "El porcentaje de pacientes con valoración del riesgo de caídas", "La tasa de bacteriemias relacionadas con catéter"], "a": 3, "e": "Resultado = efecto final en la salud. La ratio y el protocolo son estructura; la valoración del riesgo es proceso."}, {"q": "En la planificación operativa, los indicadores y criterios de evaluación deben diseñarse:", "o": ["Al terminar la ejecución, para ajustarlos a los resultados", "En la evaluación final", "En la fase de programación, antes de la ejecución", "Solo si el plan fracasa"], "a": 2, "e": "Las herramientas de evaluación se diseñan antes de actuar, en la programación; hacerlo al final introduce sesgos."}, {"q": "El recurso más importante, crítico y costoso en las organizaciones sanitarias es:", "o": ["El financiero", "El humano", "El material fungible", "La tecnología de alta complejidad"], "a": 1, "e": "El recurso humano es el más importante y el que más consume (habitualmente más del 65% del presupuesto)."}, {"q": "Para un paciente que ingresa para una artroplastia total de cadera programada, el instrumento de gestión de elección es:", "o": ["La vía o trayectoria clínica", "Un plan de cuidados individualizado y flexible NANDA-NOC-NIC", "La gestión de casos", "El sistema PRN"], "a": 0, "e": "Ante procesos homogéneos y predecibles se usa la trayectoria clínica: multidisciplinar, estandarizada y secuenciada en el tiempo."}, {"q": "En el CMBD, el diagnóstico principal es:", "o": ["El diagnóstico más grave del episodio", "El que más recursos ha consumido", "El primero anotado en urgencias", "La condición que, tras el estudio, se establece como causa del ingreso"], "a": 3, "e": "Es la causa del ingreso tras el estudio, aunque después aparezcan complicaciones más graves o costosas (que serán diagnósticos secundarios)."}, {"q": "El Registro de Actividad de Atención Sanitaria Especializada (RAE-CMBD) está regulado por:", "o": ["El RD 1030/2006", "El RD 1039/2011", "El RD 69/2015", "El RDL 16/2012"], "a": 2, "e": "El RD 69/2015 amplió el CMBD a la cirugía mayor ambulatoria, el hospital de día y la hospitalización a domicilio."}, {"q": "Los Grupos Relacionados por el Diagnóstico (GRD) fueron desarrollados por:", "o": ["Fetter y Thompson, en la Universidad de Yale", "Charles Tilquin, en Quebec", "Avedis Donabedian", "El INSALUD con el proyecto SIGNO"], "a": 0, "e": "Los GRD (Fetter y Thompson, Yale) agrupan pacientes con coherencia clínica e isoconsumo de recursos. Tilquin creó el PRN."}, {"q": "En el sistema PRN, 36 puntos equivalen a:", "o": ["36 minutos", "3 horas", "6 horas", "12 horas"], "a": 1, "e": "1 punto PRN = 5 minutos. 36 × 5 = 180 minutos = 3 horas."}, {"q": "En el sistema PRN, la suma de los Módulos I y II mide:", "o": ["La carga de trabajo total de la unidad", "El mantenimiento de la unidad", "El coste por Grupo Funcional Homogéneo", "La calidad de los cuidados individualizados"], "a": 3, "e": "I + II = calidad del cuidado individualizado; I + II + III = carga de trabajo real de la unidad."}, {"q": "El sistema SIIPS de medición del producto enfermero se basa en:", "o": ["Los patrones funcionales de Gordon", "Los GRD", "Las 14 necesidades de Virginia Henderson", "La taxonomía NIC"], "a": 2, "e": "El SIIPS (Francia) analiza los cuidados según las 14 necesidades de Henderson, en actos básicos, técnicos y de relación/educación."}, {"q": "En el proyecto SIGNO I, la unidad mínima de gestión económica era:", "o": ["El Grupo Funcional Homogéneo (coste por servicio)", "El coste por paciente y proceso", "La Norma de Enfermería", "El punto PRN"], "a": 0, "e": "SIGNO I calculaba el coste por servicio mediante el GFH; SIGNO II introdujo el coste por paciente y un catálogo de productos enfermeros."}, {"q": "El objetivo del proyecto NIPE fue:", "o": ["Sustituir los GRD por un sistema enfermero de facturación", "Integrar las intervenciones enfermeras (NANDA-NOC-NIC) en la lógica de los GRD", "Medir tiempos de cuidados en minutos", "Calcular el coste por servicio clínico"], "a": 1, "e": "NIPE (1997) definió Normas de Enfermería asociadas a los GRD más frecuentes, para costear la actividad enfermera por proceso."}, {"q": "El transporte sanitario no urgente (programado para diálisis o rehabilitación) pertenece a la cartera común:", "o": ["Básica, sin copago", "De servicios accesorios", "Complementaria autonómica", "Suplementaria, sujeta a aportación del usuario"], "a": 3, "e": "El transporte urgente está en la cartera básica (gratuito); el no urgente, en la suplementaria."}, {"q": "Según la teoría bifactorial de Herzberg, el salario es un factor:", "o": ["Motivador", "De logro", "Higiénico", "De autorrealización"], "a": 2, "e": "El salario es higiénico: su déficit causa insatisfacción, pero su presencia no motiva a largo plazo. Motivadores: reconocimiento, responsabilidad, autonomía."}, {"q": "Según Hersey y Blanchard, ante un colaborador que no sabe hacer la tarea pero está motivado (M2), el estilo indicado es:", "o": ["E2 Persuadir: alta tarea y alta relación", "E1 Dirigir: alta tarea y baja relación", "E3 Participar: baja tarea y alta relación", "E4 Delegar: baja tarea y baja relación"], "a": 0, "e": "M1 → dirigir; M2 → persuadir; M3 → participar; M4 → delegar. Solo M2 y M3 exigen alta relación."}, {"q": "Durante una parada cardiorrespiratoria, el estilo de liderazgo más adecuado para la enfermera coordinadora es el:", "o": ["Laissez-faire", "Autocrático o directivo", "Democrático", "Participativo"], "a": 1, "e": "En emergencias vitales se centraliza la decisión bajo una única voz de mando (estilo autocrático/directivo)."}, {"q": "Un directivo que cree que el trabajador evita el esfuerzo, carece de ambición y necesita control rígido aplica:", "o": ["La Teoría Y de McGregor", "Un liderazgo transformacional", "La necesidad de afiliación de McClelland", "La Teoría X de McGregor"], "a": 3, "e": "Teoría X: visión pesimista y control. Teoría Y: el trabajo es fuente de satisfacción y el trabajador se autodirige."}, {"q": "La Ley 16/2003 NO modifica el régimen de asistencia sanitaria de:", "o": ["El personal estatutario", "Los extranjeros residentes", "Los mutualistas de MUFACE, MUGEJU e ISFAS", "Los pensionistas"], "a": 2, "e": "Las mutualidades del Estado mantienen su régimen propio, que discurre por cauces paralelos."}, {"q": "La actualización de la cartera común de servicios del SNS se realiza mediante:", "o": ["Orden del Ministerio de Sanidad, previo acuerdo del Consejo Interterritorial", "Real Decreto del Gobierno, sin necesidad de acuerdo del CISNS", "Ley aprobada por las Cortes Generales", "Resolución de cada Comunidad Autónoma"], "a": 0, "e": "Art. 21: Orden ministerial con acuerdo previo del CISNS. Sin ese acuerdo la Orden no es válida."}, {"q": "¿Cuál de las siguientes intervenciones NO está incluida en la garantía de 180 días del RD 1039/2011?", "o": ["Extracción de cataratas", "Hernia inguinal", "Prótesis total de rodilla", "Cirugía cardiaca valvular"], "a": 1, "e": "Solo 5 cirugías: cardiaca valvular, cardiaca coronaria, cataratas, prótesis de cadera y prótesis de rodilla."}, {"q": "El tiempo máximo de acceso fijado por el RD 1039/2011 para esas intervenciones es de:", "o": ["150 días hábiles", "150 días naturales", "180 días hábiles", "180 días naturales"], "a": 3, "e": "180 días naturales desde la prescripción. En Murcia la garantía quirúrgica es más corta: 150 días naturales."}, {"q": "Un ciudadano de Albacete de vacaciones en La Manga es atendido en el SMS por una gastroenteritis. El coste se compensa a través del:", "o": ["Fondo de Cohesión Sanitaria", "Fondo Social Europeo", "Fondo de Garantía Asistencial (FOGA)", "Presupuesto del CISNS"], "a": 2, "e": "El FOGA compensa la asistencia ordinaria a desplazados temporales; el FCS se reserva para la alta complejidad (CSUR, trasplantes)."}, {"q": "El Código de Identificación Personal del SNS (CIP-SNS) lo genera:", "o": ["La Base de Datos de Población Protegida del Ministerio de Sanidad", "El Servicio Murciano de Salud al dar de alta al usuario", "El Instituto Nacional de Estadística", "La Tesorería General de la Seguridad Social"], "a": 0, "e": "El CIP-SNS es vitalicio y lo emite el Ministerio; la tarjeta sanitaria física la emite la Comunidad Autónoma."}, {"q": "Según el manual (RDL 11/2026), un funcionario jubilado de MUFACE con pensión baja aporta por sus medicamentos:", "o": ["El 10% con un tope mensual de 8,23 €", "El 30%, sin tope mensual", "El 40% con un tope de 18,52 €", "Nada, está exento"], "a": 1, "e": "Los mutualistas (MUFACE, ISFAS, MUGEJU) mantienen una aportación fija del 30% sin tope, con independencia de su renta."}]},
5: {"tema": 5, "titulo": "Derechos de los usuarios, igualdad y violencia de género. Personal estatutario del SMS", "programa": "Derechos y deberes de los usuarios del sistema sanitario de la Región de Murcia. Garantías de accesibilidad, derecho a la información, intimidad y confidencialidad, libre elección. Garantía y derecho de la persona en el proceso de muerte. Voluntad anticipada y su Registro. Igualdad entre mujeres y hombres y protección contra la violencia de género en la Región de Murcia. Personal estatutario: clasificación, situaciones, incompatibilidades, derechos, deberes y régimen disciplinario.", "preguntas": [{"q": "Los derechos de los \"primeros mil días\" (P1000D) introducidos en Murcia por la Ley 12/2018 abarcan:", "o": ["Desde el nacimiento hasta los 1.000 días de vida", "Desde la concepción hasta los 2 años de edad", "Los tres primeros años de vida", "Desde la semana 12 de gestación hasta los 2 años"], "a": 1, "e": "P1000D = 270 días de gestación + 365 días del primer año + 365 del segundo: desde la concepción hasta los 2 años."}, {"q": "Para facilitar el contacto piel con piel durante una cesárea, la enfermera debe colocar:", "o": ["Los electrodos en el tórax y el manguito en el brazo no dominante", "Los electrodos en la espalda y el manguito en el brazo", "Los electrodos en el tórax y el manguito en la pierna", "Los electrodos en la espalda y el manguito de tensión en la pierna"], "a": 3, "e": "ECG en la región interescapular y TA en la pantorrilla, para dejar libres el pecho y los brazos de la madre."}, {"q": "El derecho del paciente a no ser informado sobre su proceso:", "o": ["Debe expresarse de forma libre y quedar registrado en la historia clínica", "Se presume si el paciente no hace preguntas", "Puede ejercerlo la familia en nombre del paciente capaz", "Es absoluto, incluso si hay riesgo para terceros"], "a": 0, "e": "Debe ser libre, claro y voluntario, y documentarse en la historia, designando en su caso a un tercero. Cede si hay riesgo para terceros."}, {"q": "Un menor de 13 años va a someterse a un procedimiento y sus padres ya han firmado el consentimiento por representación. Respecto al menor:", "o": ["No es necesario informarle, porque ya han firmado sus padres", "Decide él, porque es mayor de 12 años", "Debe ser informado y escuchado obligatoriamente", "Decide el juez si hay discrepancias"], "a": 2, "e": "Por debajo de 16 años consienten los representantes, pero desde los 12 años (o si es maduro) el menor debe ser informado y oído."}, {"q": "El plazo máximo del SMS para emitir el informe de segunda opinión médica es de:", "o": ["15 días naturales", "15 días hábiles", "30 días hábiles", "1 mes"], "a": 1, "e": "Decreto 106/2007: 15 días hábiles. Si se incumple, el paciente puede acudir a otro centro con los gastos a cargo del SMS."}, {"q": "¿En cuál de estos casos NO procede solicitar segunda opinión médica en el SMS?", "o": ["Un proceso oncológico activo", "La confirmación de una enfermedad rara", "Una enfermedad neurológica degenerativa", "Una hipertensión arterial leve"], "a": 3, "e": "Se limita a procesos graves: cáncer, enfermedades neurológicas degenerativas o desmielinizantes, enfermedades raras y cirugías complejas de alto riesgo."}, {"q": "Un paciente en lista de espera quirúrgica pide aplazar voluntariamente su operación por un viaje. Respecto a la garantía de demora máxima:", "o": ["El cómputo del plazo se detiene", "Puede exigir que el SMS le pague una clínica privada", "El plazo garantizado pasa a ser de 180 días", "Pierde el derecho a ser operado en el SMS"], "a": 0, "e": "La garantía solo cubre la demora estructural. El aplazamiento voluntario o la contraindicación clínica suspenden el cómputo."}, {"q": "El cupo máximo de tarjetas sanitarias individuales para una enfermera de Atención Primaria del SMS es de:", "o": ["1.200", "1.500", "1.800", "2.000"], "a": 2, "e": "Enfermera: 1.800 TSI de todas las edades; médico de familia: 1.500 (≥ 14 años); pediatra: 1.200."}, {"q": "Para cambiar la enfermera o el pediatra asignados a un menor de 10 años, el SMS exige:", "o": ["La firma del progenitor que acude al centro", "La firma de ambos progenitores o tutores", "Un informe del pediatra", "La conformidad del propio menor"], "a": 1, "e": "La solicitud de cambio de profesional para menores debe ir firmada por ambos progenitores o representantes legales."}, {"q": "La Región de Murcia implantó la libre elección de enfermera en Atención Primaria mediante el programa:", "o": ["SIPS", "Selene", "OMI-AP", "Civitas Enfermera"], "a": 3, "e": "Civitas Enfermera (2013): el ciudadano elige a su enfermera de AP y su nombre figura en la TSI. El SIPS es el registro de datos de profesionales."}, {"q": "La organización y funcionamiento del Registro de Instrucciones Previas de la Región de Murcia se regula en el:", "o": ["Decreto 80/2005", "Decreto 25/2006", "Decreto 106/2007", "Decreto 339/2009"], "a": 0, "e": "Decreto 80/2005 (instrucciones previas); 25/2006 (demora máxima); 106/2007 (segunda opinión); 339/2009 (SIPS)."}, {"q": "Un paciente firma sus instrucciones previas ante tres testigos: su cónyuge, su hermano y un amigo. El documento:", "o": ["Es válido, porque hay tres testigos", "Es válido si después lo ratifica un notario", "No es válido, porque como máximo uno de los testigos puede tener parentesco hasta el 2.º grado o vínculo matrimonial", "Es válido si el representante lo acepta"], "a": 2, "e": "Dos de los tres testigos no pueden tener parentesco hasta el 2.º grado ni relación matrimonial, patrimonial o laboral con el otorgante."}, {"q": "La Comisión de Garantía y Evaluación de la eutanasia de la Región de Murcia está formada por:", "o": ["9 miembros, 3 de ellos enfermeras", "11 miembros, 2 de ellos enfermeras", "11 miembros, 3 de ellos enfermeras", "10 miembros, 2 de ellos enfermeras"], "a": 1, "e": "11 miembros: 5 médicos, 3 juristas, 2 enfermeras y 1 farmacéutico (Orden de 20 de mayo de 2021)."}, {"q": "Sobre la objeción de conciencia a la prestación de ayuda para morir (LO 3/2021):", "o": ["Un hospital puede objetar si lo hacen todos sus profesionales", "Puede manifestarse de forma verbal en el momento de la prestación", "Solo pueden ejercerla los médicos", "Es individual, se manifiesta de forma anticipada y por escrito, y el SMS debe garantizar la prestación"], "a": 3, "e": "La objeción es un derecho individual. Las instituciones no pueden objetar y deben reorganizarse para garantizar la prestación."}, {"q": "En el suicidio médicamente asistido:", "o": ["El profesional prescribe o facilita la sustancia y el paciente se la autoadministra", "La enfermera administra la sustancia letal", "El médico administra la sustancia por vía intravenosa", "Se retira el soporte vital a petición de la familia"], "a": 0, "e": "En la eutanasia el profesional administra la sustancia; en el suicidio asistido es el propio paciente quien se la administra."}, {"q": "La concentración masiva de mujeres en profesiones de cuidados con menor prestigio y salario se denomina:", "o": ["Techo de cristal", "Acción positiva", "Suelo pegajoso", "Transversalidad"], "a": 2, "e": "Suelo pegajoso = segregación horizontal. Techo de cristal = barrera vertical para acceder a puestos directivos."}, {"q": "Según la Ley 7/2007, las medidas de acción positiva son:", "o": ["Permanentes e incorporadas al estatuto del personal", "Temporales, y deben desaparecer cuando se alcance la igualdad", "Exclusivas de las empresas privadas", "Contrarias al principio de igualdad"], "a": 1, "e": "Son medidas compensatorias temporales para corregir una desigualdad de partida."}, {"q": "La evaluación del impacto por razón de género de las disposiciones de carácter general en la Región de Murcia:", "o": ["La realiza el Instituto de la Mujer tras su publicación", "Es opcional", "Solo se exige a las leyes estatales", "Es obligatoria y previa a su aprobación"], "a": 3, "e": "Debe acompañar a todo proyecto de disposición general antes de su aprobación; la elabora la Unidad de Igualdad de la Consejería."}, {"q": "El orden de las fases del ciclo de la violencia de Lenore Walker es:", "o": ["Acumulación de tensión, explosión y luna de miel", "Explosión, acumulación de tensión y luna de miel", "Luna de miel, explosión y acumulación de tensión", "Aislamiento, control y explosión"], "a": 0, "e": "Tensión → explosión (agresión aguda) → luna de miel (arrepentimiento). El ciclo se repite cada vez más rápido."}, {"q": "Una mujer acude a urgencias tras una agresión sexual por un desconocido en la vía pública. En la Región de Murcia:", "o": ["No es violencia de género, porque no hay relación de pareja", "Solo se activa el protocolo si presenta denuncia", "La Ley 7/2007 incluye este supuesto y se atiende con el protocolo de violencia de género", "Se deriva exclusivamente a la policía"], "a": 2, "e": "La LO 1/2004 exige vínculo de pareja, pero la ley murciana amplía la protección a cualquier agresión contra la mujer por el hecho de serlo."}, {"q": "Una paciente con lesiones compatibles con maltrato manifiesta que no quiere denunciar. La enfermera:", "o": ["No debe emitir el parte, por respeto a su confidencialidad", "Debe emitir de oficio el parte judicial de lesiones y remitirlo al Juzgado de Guardia", "Solo emitirá el parte si la paciente lo autoriza por escrito", "Solo avisará a la policía si las lesiones son graves"], "a": 1, "e": "El parte de lesiones es obligatorio y de oficio, independientemente de la voluntad de denunciar; prevalece sobre el secreto profesional."}, {"q": "Sobre la atención de menores de 18 años en los CAVI de la Región de Murcia:", "o": ["Está prohibida en todos los casos", "Se atiende a cualquier menor sin requisitos", "Solo si existe denuncia previa", "Es excepcional y requiere el consentimiento escrito de los progenitores o tutores"], "a": 3, "e": "Los CAVI atienden a mayores de 18 sin necesidad de denuncia; las menores, excepcionalmente, con consentimiento escrito de padres o tutores."}, {"q": "Según la Ley 5/2001, el personal de enfermería del SMS pertenece al:", "o": ["Grupo A, subgrupo A2", "Grupo A, subgrupo A1", "Grupo B", "Grupo C, subgrupo C1"], "a": 0, "e": "Enfermería = A2. El Grupo B exige título de Técnico Superior de FP; el C1, bachiller o técnico (TCAE)."}, {"q": "Tras el RDL 12/2022, un nombramiento de personal estatutario interino por exceso o acumulación de tareas no puede superar:", "o": ["3 años", "6 meses en un periodo de 12 meses", "9 meses en un periodo de 18 meses", "1 año"], "a": 2, "e": "Acumulación de tareas: 9 meses en 18. Vacante y programas temporales: 3 años. El nombramiento eventual desapareció."}, {"q": "Una enfermera estatutaria se encuentra de baja por incapacidad temporal. Su situación administrativa es:", "o": ["Suspensión de funciones", "Servicio activo", "Excedencia forzosa", "Servicios especiales"], "a": 1, "e": "La IT, las vacaciones, los permisos, la maternidad o paternidad y la huelga se consideran servicio activo."}, {"q": "Para solicitar la excedencia voluntaria por interés particular se exige haber prestado servicios efectivos durante al menos:", "o": ["1 año", "2 años", "3 años", "5 años"], "a": 3, "e": "Se exigen 5 años inmediatamente anteriores. La de agrupación familiar no exige tiempo previo."}, {"q": "En la excedencia por razón de violencia de género, la enfermera:", "o": ["Percibe las retribuciones íntegras durante los 2 primeros meses", "No percibe ninguna retribución", "Percibe las retribuciones durante 6 meses", "Tiene reserva de plaza solo 3 meses"], "a": 0, "e": "No exige tiempo previo; computa a todos los efectos; reserva de plaza 6 meses (prorrogable hasta 18) y retribuciones íntegras los 2 primeros meses."}, {"q": "Un supervisor de enfermería de UCI solicita reducir su complemento específico para trabajar los fines de semana en una UCI privada. Según la Ley 1/2025:", "o": ["Se le concede, porque renuncia a la exclusividad", "Se le concede si los horarios no se solapan", "Se le deniega, porque las plazas con funciones de dirección están excluidas", "Se le concede tras 5 años de antigüedad"], "a": 2, "e": "La Ley 1/2025 permite renunciar a la exclusividad para compatibilizar con la privada, salvo a quienes dirigen un servicio o unidad."}, {"q": "Según el Estatuto Marco, las faltas graves prescriben a los:", "o": ["6 meses", "2 años", "3 años", "4 años"], "a": 1, "e": "Regla 4-2-6: muy graves 4 años, graves 2 años, leves 6 meses (igual para faltas y sanciones)."}, {"q": "La sanción de apercibimiento en el Estatuto Marco:", "o": ["Puede ser verbal", "Se aplica a faltas graves", "Se aplica a faltas muy graves", "Se aplica a faltas leves y siempre por escrito"], "a": 3, "e": "El apercibimiento es la sanción de las faltas leves y debe constar por escrito; el apercibimiento oral no existe."}]},
6: {"tema": 6, "titulo": "Ley 44/2003 de ordenación de las profesiones sanitarias (LOPS)", "programa": "La Ley 44/2003, de 21 de noviembre, de ordenación de las profesiones sanitarias: profesiones sanitarias tituladas y profesionales del área sanitaria de formación profesional; el ejercicio de las profesiones sanitarias; formación especializada en ciencias de la salud.", "preguntas": [{"q": "La Ley de ordenación de las profesiones sanitarias es la Ley 44/2003, de:", "o": ["16 de diciembre", "28 de mayo", "21 de noviembre", "14 de noviembre"], "a": 2, "e": "LOPS: Ley 44/2003, de 21 de noviembre. La Ley 16/2003 es de 28 de mayo, la 55/2003 de 16 de diciembre y la 41/2002 de 14 de noviembre."}, {"q": "El ámbito de aplicación de la LOPS comprende:", "o": ["A todos los profesionales sanitarios, ejerzan en el sector público o en el privado", "Solo a los profesionales del Sistema Nacional de Salud", "Solo al personal estatutario de los servicios de salud", "Solo a los profesionales colegiados"], "a": 0, "e": "La LOPS tiene vocación de universalidad: obliga a todos los profesionales sanitarios, con independencia de que trabajen en la sanidad pública o privada."}, {"q": "¿Cuál de las siguientes es una profesión sanitaria de nivel licenciado según el art. 2 de la LOPS?", "o": ["Enfermería", "Fisioterapia", "Podología", "Veterinaria"], "a": 3, "e": "Nivel licenciado: Medicina, Farmacia, Odontología y Veterinaria. Enfermería, Fisioterapia y Podología son de nivel diplomado/grado."}, {"q": "El Técnico Superior en Higiene Bucodental se regula en la LOPS como:", "o": ["Profesión sanitaria titulada de nivel licenciado (art. 2)", "Profesional del área sanitaria de formación profesional (art. 3)", "Profesión sanitaria de nivel diplomado (art. 2)", "Personal no sanitario"], "a": 1, "e": "Los técnicos superiores y de grado medio (TCAE) se incluyen en el art. 3; no son titulados universitarios."}, {"q": "Según el art. 7.2.a de la LOPS, corresponde a los enfermeros:", "o": ["La ejecución de los cuidados bajo la indicación del médico", "La prescripción de los tratamientos farmacológicos", "La dirección, evaluación y prestación de los cuidados de enfermería", "La prestación de cuidados mediante agentes físicos"], "a": 2, "e": "La LOPS atribuye a Enfermería la dirección, evaluación y prestación de los cuidados, con autonomía técnica y funcional. Los agentes físicos son de Fisioterapia."}, {"q": "¿Cuál de los siguientes NO es un requisito para el ejercicio de una profesión sanitaria según el art. 4 de la LOPS?", "o": ["Estar en posesión del título oficial habilitante", "No estar inhabilitado ni suspendido", "Estar colegiado cuando una ley estatal lo establezca", "Acreditar dos años de experiencia previa"], "a": 3, "e": "Los requisitos son el título oficial, no estar inhabilitado y la colegiación cuando lo exija una ley estatal. No se exige experiencia previa."}, {"q": "Los Colegios Profesionales tienen la naturaleza jurídica de:", "o": ["Asociaciones privadas de libre adscripción", "Organismos autónomos del Ministerio de Sanidad", "Organizaciones sindicales", "Corporaciones de Derecho Público"], "a": 3, "e": "Son corporaciones de Derecho Público con funciones delegadas: control deontológico y de la buena praxis. Sus sanciones firmes impiden ejercer en cualquier ámbito."}, {"q": "Según el art. 13 de la LOPS, el número de plazas de acceso a los estudios sanitarios (numerus clausus):", "o": ["Se fija atendiendo a las necesidades del SNS y a la capacidad docente de los centros", "Lo decide libremente cada universidad según su demanda", "Lo fija cada hospital universitario", "Lo aprueba el Consejo General de Enfermería"], "a": 0, "e": "Lo planifican los Ministerios de Sanidad y Educación, oído el Foro Profesional, según las necesidades del país y la capacidad de los centros para las prácticas."}, {"q": "La figura en la que un mismo profesional ocupa, con un nombramiento único, una plaza asistencial en el servicio de salud y otra docente como profesor titular de universidad es:", "o": ["El profesor asociado de Ciencias de la Salud", "La plaza vinculada", "El tutor de residentes", "El colaborador docente"], "a": 1, "e": "Las plazas vinculadas (art. 14) unen de forma indisoluble la función asistencial y la docente universitaria. El profesor asociado mantiene su plaza y tiene un contrato temporal con la universidad."}, {"q": "La relación laboral especial de residencia para la formación de especialistas en Ciencias de la Salud se regula en el:", "o": ["RD 183/2008", "RD 450/2005", "RD 1146/2006", "RD 69/2015"], "a": 2, "e": "RD 1146/2006: contrato de residencia. El RD 183/2008 regula las unidades docentes y comisiones, y el RD 450/2005 las especialidades de enfermería."}, {"q": "Durante el primer año de residencia, la supervisión del residente es:", "o": ["Directa y presencial", "De respaldo, a demanda del residente", "Inexistente en las guardias", "Solo documental, a través del Libro del Residente"], "a": 0, "e": "La supervisión es decreciente: directa y presencial al inicio, después de proximidad y finalmente de respaldo."}, {"q": "El título oficial de especialista en Ciencias de la Salud lo expide:", "o": ["La Comunidad Autónoma donde se ha realizado la residencia", "El Ministerio de Sanidad", "La universidad de adscripción de la unidad docente", "La Comisión de Docencia del centro"], "a": 1, "e": "La competencia para expedir el título de especialista corresponde al Ministerio de Sanidad, en nombre del Rey."}, {"q": "¿Qué especialidad de enfermería del RD 450/2005 está pendiente de desarrollo y nunca se ha ofertado en el EIR?", "o": ["Enfermería Geriátrica", "Enfermería del Trabajo", "Enfermería de Salud Mental", "Enfermería de Cuidados Médico-Quirúrgicos"], "a": 3, "e": "Cuidados Médico-Quirúrgicos figura en la norma, pero no se ha desarrollado. Las otras seis están plenamente desarrolladas."}, {"q": "La formación de las especialidades de enfermería por el sistema de residencia tiene una duración de:", "o": ["1 año", "3 años", "2 años", "4 años"], "a": 2, "e": "Todas las especialidades EIR tienen una residencia de 2 años a tiempo completo en una unidad docente acreditada."}, {"q": "Para acceder a una segunda especialidad, el art. 23 de la LOPS exige acreditar en la primera un ejercicio profesional mínimo de:", "o": ["3 años", "5 años", "8 años", "10 años"], "a": 1, "e": "5 años de ejercicio en la especialidad que se posee. Para optar a una tercera deben transcurrir 8 años desde la segunda."}, {"q": "Superar la formación en un Área de Capacitación Específica (ACE) da derecho a:", "o": ["Un diploma de área de capacitación específica, no un nuevo título de especialista", "Un nuevo título de especialista", "Un máster universitario oficial", "El acceso directo a la carrera profesional"], "a": 0, "e": "Las ACE suponen una ultraespecialización sobre una especialidad base y otorgan un diploma, no un título nuevo."}, {"q": "La Comisión de Docencia de un centro está presidida por:", "o": ["El Director Gerente", "La Dirección de Enfermería", "El tutor de mayor antigüedad", "El Jefe de Estudios"], "a": 3, "e": "La preside el Jefe de Estudios, con voto de calidad. La integran vocales tutores, vocales residentes y un secretario sin voto."}, {"q": "Los vocales que representan a los residentes en la Comisión de Docencia se eligen:", "o": ["Por designación del Jefe de Estudios", "Por sorteo entre los residentes de último año", "Por voto directo y secreto de los propios residentes", "Por la Dirección del centro"], "a": 2, "e": "Su elección es democrática, por voto directo y secreto entre los residentes."}, {"q": "El programa formativo oficial de cada especialidad lo elabora:", "o": ["La Comisión de Docencia de cada hospital", "La Comisión Nacional de la Especialidad", "El Consejo Interterritorial", "El Foro Profesional"], "a": 1, "e": "Las Comisiones Nacionales de Especialidad (art. 28) elaboran los programas y criterios de evaluación; cada centro los aplica."}, {"q": "El Consejo Nacional de Especialidades en Ciencias de la Salud está integrado por:", "o": ["Los presidentes de las Comisiones Nacionales de cada especialidad", "Los jefes de estudios de todos los hospitales", "Los consejeros de sanidad de las CC. AA.", "Los presidentes de los colegios profesionales"], "a": 0, "e": "El Consejo Nacional (art. 30) reúne a los presidentes de las Comisiones Nacionales y asesora a los Ministerios en política de formación especializada."}, {"q": "Los créditos de formación continuada acreditados por la Comisión de Formación Continuada del SNS:", "o": ["Solo son válidos en la Comunidad Autónoma que los acredita", "Solo puntúan en la carrera profesional", "Solo tienen validez si se posee un Diploma de Acreditación", "Tienen validez en todo el Sistema Nacional de Salud"], "a": 3, "e": "Los criterios son comunes y los créditos CFC son válidos y baremables en todo el SNS, lo que facilita la movilidad."}, {"q": "Según el manual, los Diplomas de Acreditación (DA) y de Acreditación Avanzada (DAA) tienen una vigencia de:", "o": ["Carácter indefinido", "2 años", "5 años", "10 años"], "a": 2, "e": "Certifican competencias en áreas funcionales transversales (dolor, paliativos, trasplantes) y deben renovarse; no son vitalicios."}, {"q": "La carrera profesional regulada en el Título III de la LOPS se caracteriza por ser:", "o": ["Un reconocimiento horizontal del progreso del profesional sin necesidad de cambiar de puesto", "Un ascenso vertical a puestos de gestión", "Exclusiva del personal facultativo", "Un sistema de méritos solo para concursos de traslado"], "a": 0, "e": "Reconoce de forma pública e individual los conocimientos, la experiencia y el cumplimiento de objetivos, permitiendo progresar sin abandonar la asistencia."}, {"q": "Según el art. 38 de la LOPS, respecto a los grados de carrera profesional, las Comunidades Autónomas:", "o": ["Pueden no reconocer los de otras comunidades", "Deben establecer procedimientos de homologación entre ellas", "Solo los reconocen si hay convenio bilateral", "Los fijan de forma totalmente independiente sin efectos fuera de su territorio"], "a": 1, "e": "Las CC. AA. están obligadas a homologar los grados de carrera, de modo que el profesional conserva su nivel si se traslada a otro servicio de salud."}, {"q": "Según el art. 46 de la LOPS, para ejercer en el sector privado con asistencia directa a pacientes es obligatorio:", "o": ["Tener al menos 5 años de experiencia en el sector público", "Estar inscrito como empresario autónomo", "Disponer de autorización de la Comunidad Autónoma por cada paciente", "Contar con un seguro de responsabilidad civil, aval u otra garantía financiera"], "a": 3, "e": "El ejercicio privado exige una garantía financiera para cubrir la responsabilidad civil y los mismos controles de calidad que el SNS."}, {"q": "Entre las funciones del Foro Profesional (Título V de la LOPS) se encuentra:", "o": ["Expedir los títulos de especialista", "Acreditar los créditos de formación continuada", "Analizar los conflictos competenciales entre las distintas profesiones sanitarias", "Presidir las comisiones de docencia"], "a": 2, "e": "El Foro Profesional reúne a Ministerios, CC. AA., colegios y sindicatos; evalúa conflictos de competencias, participa en las normas y vela por la acreditación de la FSE."}, {"q": "Sobre el tutor de residentes, es correcto que:", "o": ["Puede ejercerlo cualquier especialista que esté de guardia", "Debe ser un especialista acreditado con nombramiento formal", "No necesita tiempo específico dentro de su jornada", "Lo eligen los propios residentes"], "a": 1, "e": "El tutor debe estar acreditado por méritos (no existe el tutor accidental) y tener tiempo protegido, formación y sustitución en caso de ausencia."}, {"q": "Para la válida constitución de la Comisión de Docencia en primera convocatoria se exige la presencia de:", "o": ["La mitad más uno de sus miembros", "Dos tercios de sus miembros", "Todos sus miembros", "Solo el presidente y el secretario"], "a": 0, "e": "Quórum de la mitad más uno; los acuerdos se adoptan por mayoría simple."}, {"q": "Cuando un hospital del SMS obtiene, mediante concierto con la universidad, la condición de Hospital Universitario:", "o": ["Pasa a depender orgánicamente de la universidad", "Pasa a depender del Ministerio de Educación", "Sigue perteneciendo al Servicio Murciano de Salud", "Se gestiona al 50% entre ambas administraciones"], "a": 2, "e": "El concierto le permite impartir docencia de grado, pero el centro sigue perteneciendo al servicio de salud."}, {"q": "El Registro Estatal de Profesionales Sanitarios (REPS):", "o": ["Es secreto y solo accesible a la inspección", "Solo incluye a los profesionales del sector público", "Lo gestionan exclusivamente los colegios profesionales", "Es público y permite al ciudadano verificar la titulación y especialidad de quien le atiende"], "a": 3, "e": "Es un registro público, alimentado por ministerios, CC. AA., colegios y centros públicos y privados, que ayuda a combatir el intrusismo."}]},
7: {"tema": 7, "titulo": "Investigación cuantitativa y cualitativa en enfermería. Ley 31/1995 de Prevención de Riesgos Laborales", "programa": "Fundamento y metodología de la investigación cuantitativa y cualitativa en enfermería. Ley 31/1995, de 8 de noviembre, de prevención de riesgos laborales: objeto, ámbito y definiciones; derechos y obligaciones; servicios de prevención; tipos de riesgos; Seguridad en el Trabajo, Higiene Industrial, Ergonomía y Psicosociología; actuación en supuestos de riesgo; precauciones universales: vacunación, higiene, equipos de protección, objetos cortopunzantes, esterilización y desinfección.", "preguntas": [{"q": "El orden correcto de las fases de la Enfermería Basada en la Evidencia (las \"5 Aes\") es:", "o": ["Averiguar, Analizar, Adquirir, Aplicar y Autoevaluar", "Averiguar, Adquirir, Analizar, Aplicar y Autoevaluar", "Adquirir, Averiguar, Analizar, Aplicar y Autoevaluar", "Averiguar, Adquirir, Aplicar, Analizar y Autoevaluar"], "a": 1, "e": "Primero se formula la pregunta, luego se busca la evidencia, se lee críticamente, se aplica y se evalúa el resultado."}, {"q": "En una búsqueda bibliográfica, el operador booleano OR:", "o": ["Reduce el número de resultados", "Excluye los documentos con ese término", "Amplía la búsqueda, recuperando documentos con cualquiera de los términos", "Obliga a que aparezcan ambos términos"], "a": 2, "e": "OR une (útil para sinónimos) y aumenta los resultados; AND interseca y los reduce; NOT excluye."}, {"q": "La investigación cualitativa utiliza fundamentalmente un razonamiento:", "o": ["Inductivo", "Deductivo", "Hipotético-deductivo", "Experimental"], "a": 0, "e": "La cualitativa parte de los datos para construir teoría (inductivo); la cuantitativa parte de la teoría para comprobar hipótesis (deductivo)."}, {"q": "El formato de pregunta de elección para un estudio de cohortes que analiza la exposición a un factor de riesgo laboral es:", "o": ["SPIDER", "ECLIPSE", "SPICE", "PECO"], "a": 3, "e": "PECO sustituye la Intervención por la Exposición en estudios observacionales analíticos. SPIDER y SPICE son cualitativos; ECLIPSE, de gestión."}, {"q": "En un ensayo clínico con diseño de doble ciego desconocen la asignación:", "o": ["Solo el paciente", "El paciente y el investigador que administra el tratamiento", "El investigador y el analista estadístico", "El paciente, el investigador y el analista"], "a": 1, "e": "Simple ciego: el paciente. Doble ciego: paciente e investigador/clínico. Triple ciego: además el analista."}, {"q": "Para estudiar una enfermedad rara o con un periodo de latencia muy largo, el diseño observacional de elección es:", "o": ["El estudio de cohortes prospectivo", "El ensayo clínico aleatorizado", "El estudio de casos y controles", "El estudio transversal"], "a": 2, "e": "Los casos y controles parten de los enfermos ya existentes y buscan la exposición previa; una cohorte exigiría seguir a muchísimas personas."}, {"q": "La medida de asociación propia de los estudios de cohortes es:", "o": ["El riesgo relativo (RR)", "La odds ratio (OR)", "La prevalencia", "La sensibilidad"], "a": 0, "e": "Las cohortes miden incidencia y calculan el RR; los casos y controles, al no poder calcular incidencias, usan la OR."}, {"q": "En un estudio de cohortes se obtiene un riesgo relativo de 0,5. Esto indica que la exposición:", "o": ["No tiene ninguna asociación con la enfermedad", "Duplica el riesgo de enfermar", "Es un factor de riesgo", "Es un factor protector"], "a": 3, "e": "El valor nulo es 1. RR > 1 = factor de riesgo; RR < 1 = factor protector."}, {"q": "Según Lincoln y Guba, el criterio de rigor cualitativo equivalente a la validez externa es la:", "o": ["Credibilidad", "Transferibilidad", "Dependencia", "Confirmabilidad"], "a": 1, "e": "Credibilidad = validez interna; transferibilidad = validez externa; dependencia = fiabilidad; confirmabilidad = objetividad."}, {"q": "El muestreo en el que se seleccionan al azar agrupaciones naturales internamente heterogéneas (hospitales, aulas) y se estudian todos sus individuos es el:", "o": ["Aleatorio simple", "Estratificado", "Por conglomerados", "Por cuotas"], "a": 2, "e": "En el estratificado los estratos son homogéneos; en los conglomerados, los grupos son naturales y heterogéneos."}, {"q": "La frecuencia cardiaca medida en latidos por minuto es una variable:", "o": ["Cuantitativa discreta", "Cuantitativa continua", "Cualitativa ordinal", "Cualitativa nominal"], "a": 0, "e": "Solo toma valores enteros, por lo que es discreta. El peso o la temperatura, que admiten decimales, son continuas."}, {"q": "El sesgo por el que las expectativas del investigador influyen inconscientemente en los resultados se denomina:", "o": ["Efecto Hawthorne", "Sesgo de Berkson", "Sesgo de Neyman", "Efecto Rosenthal o Pigmalión"], "a": 3, "e": "Rosenthal = expectativas del investigador (se evita con doble ciego). Hawthorne = el sujeto cambia su conducta al saberse observado."}, {"q": "El gráfico en embudo (funnel plot) se utiliza en los metaanálisis para detectar:", "o": ["Factores de confusión", "El sesgo de publicación", "El sesgo de memoria", "Las pérdidas de seguimiento"], "a": 1, "e": "La asimetría del embudo indica que faltan estudios (sobre todo pequeños con resultados negativos) que no se publicaron."}, {"q": "Una prueba destinada a un programa de cribado poblacional debe priorizar:", "o": ["Una alta especificidad", "Un alto valor predictivo positivo", "Una alta sensibilidad", "Una baja prevalencia de la enfermedad"], "a": 2, "e": "En el cribado interesa no dejar escapar enfermos (pocos falsos negativos): alta sensibilidad. La especificidad se prioriza en la confirmación."}, {"q": "Si la prevalencia de una enfermedad disminuye mucho en la población, se modifican:", "o": ["Los valores predictivos positivo y negativo", "La sensibilidad de la prueba", "La especificidad de la prueba", "La sensibilidad y la especificidad"], "a": 0, "e": "Sensibilidad y especificidad son propiedades intrínsecas de la prueba; VPP y VPN dependen de la prevalencia."}, {"q": "Para comparar una variable que no sigue la distribución normal entre tres o más grupos independientes se utiliza:", "o": ["El test de Wilcoxon", "La U de Mann-Whitney", "La prueba de Friedman", "La H de Kruskal-Wallis"], "a": 3, "e": "Kruskal-Wallis es la alternativa no paramétrica al ANOVA. Wilcoxon: 2 medidas relacionadas; Mann-Whitney: 2 grupos independientes; Friedman: medidas repetidas."}, {"q": "La guía de la Red EQUATOR para la publicación de ensayos clínicos aleatorizados es:", "o": ["STROBE", "CONSORT", "PRISMA", "STARD"], "a": 1, "e": "CONSORT = ECA; STROBE = observacionales; PRISMA = revisiones sistemáticas y metaanálisis; STARD = pruebas diagnósticas."}, {"q": "El instrumento AGREE II se utiliza para:", "o": ["Evaluar la calidad de las guías de práctica clínica", "Publicar ensayos clínicos", "Evaluar estudios cualitativos", "Calcular el tamaño muestral"], "a": 0, "e": "AGREE II evalúa guías de práctica clínica con 23 ítems agrupados en 6 dominios."}, {"q": "La Ley 31/1995 de Prevención de Riesgos Laborales es la transposición de la Directiva:", "o": ["2010/32/UE", "2013/59/Euratom", "89/391/CEE", "2004/37/CE"], "a": 2, "e": "La LPRL transpone la Directiva marco 89/391/CEE. La 2010/32/UE se refiere a lesiones por cortopunzantes."}, {"q": "¿Cuál de los siguientes colectivos queda excluido del ámbito de aplicación de la Ley 31/1995?", "o": ["El personal estatutario de los servicios de salud", "Las Fuerzas Armadas en sus actividades militares", "Los socios trabajadores de cooperativas", "Los trabajadores temporales"], "a": 1, "e": "Se excluyen actividades de soberanía y orden público (Fuerzas Armadas, policía, protección civil en emergencias). El personal del SMS sí está incluido."}, {"q": "¿Cuál de los siguientes NO se considera un Equipo de Protección Individual según la LPRL?", "o": ["Una mascarilla FFP3", "Un delantal plomado", "Unas gafas de protección frente a salpicaduras", "El uniforme ordinario de trabajo de la planta"], "a": 3, "e": "La ropa de trabajo ordinaria que no protege específicamente frente a un riesgo queda excluida del concepto de EPI."}, {"q": "La vigilancia de la salud de los trabajadores es voluntaria, pero pasa a ser obligatoria cuando:", "o": ["El estado de salud del trabajador puede constituir un peligro para terceros, como los pacientes", "El trabajador es temporal", "El centro tiene más de 50 trabajadores", "Lo decide el supervisor de la unidad"], "a": 0, "e": "Es obligatoria para evaluar los efectos del trabajo, si la salud del trabajador es un peligro para él o terceros, o si lo establece una ley."}, {"q": "El Comité de Seguridad y Salud debe constituirse obligatoriamente en centros de trabajo con:", "o": ["6 o más trabajadores", "25 o más trabajadores", "50 o más trabajadores", "250 o más trabajadores"], "a": 2, "e": "Es un órgano paritario obligatorio a partir de 50 trabajadores. En centros más pequeños actúan los Delegados de Prevención."}, {"q": "Ante un riesgo para una enfermera embarazada, la primera medida que debe adoptarse según el art. 26 de la LPRL es:", "o": ["La suspensión del contrato por riesgo durante el embarazo", "La adaptación de las condiciones o del tiempo de trabajo", "El cambio de puesto con las retribuciones del nuevo puesto", "La baja por incapacidad temporal"], "a": 1, "e": "Orden: 1.º adaptar el puesto o el horario; 2.º cambio de puesto manteniendo el 100% de las retribuciones; 3.º suspensión del contrato por riesgo."}, {"q": "Según el RD 39/1997, es obligatorio constituir un Servicio de Prevención Propio en empresas con:", "o": ["Más de 50 trabajadores", "Más de 100 trabajadores", "Más de 250 trabajadores en cualquier actividad", "Más de 500 trabajadores"], "a": 3, "e": "Más de 500 trabajadores; entre 250 y 500 solo si realizan actividades del Anexo I; o por decisión de la autoridad laboral."}, {"q": "El síndrome de burnout y el mobbing son objeto de la disciplina preventiva de:", "o": ["Psicosociología aplicada", "Higiene industrial", "Seguridad en el trabajo", "Ergonomía"], "a": 0, "e": "La psicosociología se ocupa de los factores organizativos: turnicidad, carga mental, estrés, burnout y acoso."}, {"q": "Según el RD 664/1997, el VIH, el virus de la hepatitis B y el bacilo de la tuberculosis son agentes biológicos del grupo:", "o": ["1", "2", "3", "4"], "a": 2, "e": "Grupo 3: enfermedad grave con riesgo de propagación, pero con profilaxis o tratamiento. El grupo 4 incluye el Ébola."}, {"q": "Ante un paciente con tuberculosis pulmonar activa, la enfermera aplicará:", "o": ["Precauciones de gotas con mascarilla quirúrgica", "Precauciones de contacto con guantes y bata", "Solo precauciones estándar", "Precauciones de transmisión aérea con mascarilla FFP2/FFP3 y habitación de presión negativa"], "a": 3, "e": "Tuberculosis, sarampión y varicela requieren aislamiento aéreo: presión negativa, filtros HEPA y protección respiratoria FFP2/FFP3."}, {"q": "Tras atender a un paciente con diarrea por Clostridioides difficile, la higiene de manos debe hacerse:", "o": ["Con solución hidroalcohólica durante 20-30 segundos", "Con agua y jabón, por arrastre mecánico", "No es necesaria si se han usado guantes", "Con alcohol de 70º"], "a": 1, "e": "El alcohol no es esporicida: ante esporas se lava con agua y jabón (40-60 s) para arrastrarlas. Los guantes nunca sustituyen la higiene de manos."}, {"q": "Según la clasificación de Spaulding, un laringoscopio es material:", "o": ["Crítico, que requiere esterilización", "No crítico, que requiere limpieza", "Semicrítico, que requiere desinfección de alto nivel", "Crítico, que requiere desinfección de bajo nivel"], "a": 2, "e": "Contacta con mucosas intactas: es semicrítico y requiere desinfección de alto nivel (glutaraldehído, ácido peracético)."}]},
8: {"tema": 8, "titulo": "Enfermería basada en la evidencia, guías y vías clínicas. Igualdad, violencia de género y derechos LGTBI", "programa": "Enfermería Basada en la Evidencia. Niveles de evidencia y grados de recomendación. Bases de datos bibliográficas, fuentes documentales y revisión bibliográfica. Lectura crítica. Formulación de preguntas y búsqueda de respuestas. Evaluación y síntesis de la revisión. Guías de Práctica Clínica, mapas de cuidados y vías clínicas. LO 3/2007 de igualdad efectiva, Ley 7/2007 de la Región de Murcia, LO 1/2004 de violencia de género y Ley 4/2023 de derechos LGTBI y trans.", "preguntas": [{"q": "El modelo de implementación de la EBE de enfoque organizacional que se inicia a partir de \"desencadenantes\" (triggers) es el modelo:", "o": ["De Iowa", "De Stetler", "ACE Star", "Del Instituto Joanna Briggs"], "a": 0, "e": "Iowa (Titler) es institucional y parte de desencadenantes; Stetler se centra en la enfermera individual."}, {"q": "En el modelo de Iowa, el aumento de la tasa de caídas en el turno de noche detectado en la propia unidad es un desencadenante:", "o": ["Enfocado en el conocimiento", "Normativo externo", "Enfocado en el problema", "De evaluación final"], "a": 2, "e": "Los datos internos (caídas, bacteriemias, quejas) son desencadenantes del problema; la publicación de una nueva guía o norma es del conocimiento."}, {"q": "El modelo de Stetler para la práctica basada en la evidencia se caracteriza por:", "o": ["Requerir un ensayo piloto institucional", "Estar dirigido al profesional individual y su pensamiento crítico", "Basarse en desencadenantes organizativos", "Estructurarse en las cinco puntas de una estrella"], "a": 1, "e": "Stetler guía a la enfermera de forma individual en 5 fases. La estrella es el modelo ACE Star de Stevens."}, {"q": "Una Guía de Práctica Clínica es una fuente documental:", "o": ["Primaria", "Terciaria", "De literatura gris", "Secundaria"], "a": 3, "e": "Las GPC, revisiones sistemáticas y metaanálisis sintetizan fuentes primarias: son fuentes secundarias."}, {"q": "Para resolver una pregunta básica (background), como el mecanismo de acción de la heparina, la enfermera debe consultar:", "o": ["Fuentes terciarias, como tratados y libros de texto", "PubMed mediante una pregunta PICO", "La Cochrane Library", "CINAHL con descriptores específicos"], "a": 0, "e": "Las preguntas básicas se responden con fuentes terciarias; el formato PICO y las bases de datos son para preguntas foreground."}, {"q": "La base de datos CUIDEN, de referencia en la enfermería iberoamericana, la elabora:", "o": ["La Universidad Complutense de Madrid", "La Universidad de La Rioja", "La Fundación Index de Granada", "BIREME (OPS)"], "a": 2, "e": "CUIDEN es de la Fundación Index (Granada). ENFISPO es de la Complutense, Dialnet de La Rioja y LILACS de BIREME."}, {"q": "El tesauro DeCS (Descriptores en Ciencias de la Salud) se utiliza en:", "o": ["PubMed/MEDLINE", "LILACS y BDENF", "CINAHL", "La Cochrane Library"], "a": 1, "e": "DeCS es trilingüe y se usa en la Biblioteca Virtual en Salud (LILACS, BDENF). PubMed usa MeSH."}, {"q": "En una búsqueda bibliográfica, el truncamiento con asterisco (por ejemplo, enferm*):", "o": ["Une sinónimos como el operador OR", "Excluye documentos", "Sustituye un único carácter en el interior de la palabra", "Sustituye una cadena de caracteres al final de la raíz"], "a": 3, "e": "Enferm* recupera enfermería, enfermera, enfermedad... El comodín (?) sustituye un solo carácter interior."}, {"q": "Para buscar artículos sobre el dolor en niños o en neonatos, la ecuación correcta es:", "o": ["dolor AND (niños OR neonatos)", "dolor AND niños OR neonatos", "dolor OR niños AND neonatos", "dolor NOT (niños OR neonatos)"], "a": 0, "e": "Los sinónimos de la población deben agruparse entre paréntesis con OR y cruzarse con AND."}, {"q": "El operador NEAR es un operador:", "o": ["Booleano de exclusión", "De truncamiento", "Posicional o de proximidad", "De etiqueta de campo"], "a": 2, "e": "NEAR, ADJ y NEXT son de proximidad: indican la distancia entre términos. Los booleanos son solo AND, OR y NOT."}, {"q": "En las plantillas de lectura crítica CASPe, las preguntas de eliminación son:", "o": ["Las dos últimas, sobre aplicabilidad", "Las dos primeras, sobre la validez del estudio", "Todas las del bloque de resultados", "Solo existen en los estudios cualitativos"], "a": 1, "e": "Las dos primeras preguntas (bloque A, validez) actúan de filtro: si no se superan, se descarta el artículo."}, {"q": "La lista de comprobación de la declaración PRISMA 2020 consta de:", "o": ["23 ítems", "10 ítems", "11 ítems", "27 ítems"], "a": 3, "e": "PRISMA 2020: 27 ítems y diagrama de flujo de 4 fases. AGREE II tiene 23 ítems; CASPe, 10-11 preguntas."}, {"q": "En un forest plot que compara la diferencia de medias en una escala de dolor, la línea de no efecto corresponde al valor:", "o": ["0", "1", "0,5", "100"], "a": 0, "e": "Para variables continuas (diferencia de medias) el efecto nulo es 0; para medidas relativas (RR, OR) es 1."}, {"q": "En la clasificación de Jovell y Navarro-Rubio, el grado de recomendación E significa:", "o": ["Evidencia insuficiente", "Evidencia aceptable para considerar el uso", "Buena evidencia para excluir o desaconsejar la intervención", "Recomendación basada en la opinión de expertos"], "a": 2, "e": "En Jovell la evidencia insuficiente es la C; la E indica que hay buena evidencia de daño o inutilidad y debe excluirse."}, {"q": "La clasificación de Jovell y Navarro-Rubio establece:", "o": ["5 niveles de evidencia", "9 niveles de evidencia", "4 niveles de evidencia", "3 niveles de evidencia"], "a": 1, "e": "Tiene 9 niveles (I a IX) y 5 grados de recomendación (A a E)."}, {"q": "En el sistema GRADE, un conjunto de estudios observacionales parte inicialmente de una calidad de la evidencia:", "o": ["Alta", "Moderada", "Muy baja", "Baja"], "a": 3, "e": "Los ECA parten de calidad alta y los observacionales de baja; después se ajustan hacia arriba o abajo."}, {"q": "El sistema de recomendación que valora la viabilidad, la adecuación, el significado para el paciente y la efectividad (FAME) es el del:", "o": ["Instituto Joanna Briggs", "SIGN", "GRADE", "CEBM de Oxford"], "a": 0, "e": "FAME (Feasibility, Appropriateness, Meaningfulness, Effectiveness) es propio del JBI."}, {"q": "GuíaSalud, el catálogo español de Guías de Práctica Clínica, es:", "o": ["Un servicio exclusivo del Ministerio de Sanidad", "Un proyecto de los Colegios de Enfermería", "Un organismo del Consejo Interterritorial con centro coordinador en el Instituto Aragonés de Ciencias de la Salud", "Una agencia de la OMS"], "a": 2, "e": "GuíaSalud pertenece al CISNS (participan todas las CC. AA.) y su centro coordinador está en el IACS."}, {"q": "La vía clínica es la herramienta que responde principalmente a:", "o": ["¿Qué hacer?", "¿Cuándo y quién lo hace?", "¿Cómo se realiza una técnica?", "¿Por qué enferma el paciente?"], "a": 1, "e": "GPC: qué hacer; vía clínica: cuándo y quién (matriz temporal multidisciplinar); protocolo: cómo hacerlo."}, {"q": "¿Cuál de los siguientes es un componente propio de una vía clínica?", "o": ["Un diagnóstico NANDA único para todos los pacientes", "La valoración por patrones de Gordon", "El método de priorización de Hanlon", "La hoja de variaciones"], "a": 3, "e": "La vía clínica incluye matriz temporal, hoja de variaciones, información al paciente y encuesta de satisfacción."}, {"q": "En el instrumento AGREE II, los ítems se puntúan mediante una escala:", "o": ["Likert de 1 a 7", "Likert de 1 a 5", "De 0 a 10", "Dicotómica sí/no"], "a": 0, "e": "AGREE II: 23 ítems en 6 dominios, escala de 1 (muy en desacuerdo) a 7 (muy de acuerdo), con 2 a 4 evaluadores."}, {"q": "Una convocatoria que exige una altura mínima de 1,75 m para trabajar en la UCI, sin justificación clínica, constituye según la LO 3/2007:", "o": ["Discriminación directa", "Acoso por razón de sexo", "Discriminación indirecta", "Una acción positiva"], "a": 2, "e": "Es una norma aparentemente neutra que perjudica de forma particular a las mujeres: discriminación indirecta (art. 6.2)."}, {"q": "Sobre el permiso por nacimiento y cuidado del menor (RDL 6/2019), es correcto que:", "o": ["La madre puede ceder semanas al otro progenitor", "Son 16 semanas para cada progenitor, individuales e intransferibles, con 6 semanas obligatorias tras el parto", "Son 10 semanas para cada progenitor", "Las 6 primeras semanas son voluntarias"], "a": 1, "e": "16 semanas por progenitor, intransferibles; las 6 primeras posteriores al parto son de descanso obligatorio."}, {"q": "Tras el RD 901/2020, los planes de igualdad son obligatorios en las empresas con:", "o": ["250 o más trabajadores", "100 o más trabajadores", "500 o más trabajadores", "50 o más trabajadores"], "a": 3, "e": "El umbral actual es de 50 personas trabajadoras; 250 y 100 son cifras antiguas usadas como distractores."}, {"q": "Según la LO 3/2007, existe presencia equilibrada de mujeres y hombres en un órgano cuando:", "o": ["Ningún sexo supera el 60% ni es inferior al 40%", "Hay exactamente el 50% de cada sexo", "Ningún sexo supera el 70%", "Las mujeres son mayoría"], "a": 0, "e": "Horquilla del 40-60%. Por ejemplo, en un tribunal de 5 miembros no puede haber más de 3 del mismo sexo."}, {"q": "La LO 1/2004 de protección integral contra la violencia de género se aplica a la violencia ejercida sobre la mujer por:", "o": ["Cualquier hombre, conocido o desconocido", "Solo su cónyuge", "Quien sea o haya sido su cónyuge o pareja, aun sin convivencia", "Su pareja, solo si conviven"], "a": 2, "e": "Exige vínculo de pareja actual o pasado, aunque no haya convivencia. Las agresiones de desconocidos se rigen por otras normas."}, {"q": "La Comisión contra la Violencia de Género del Consejo Interterritorial del SNS se crea en el artículo de la LO 1/2004:", "o": ["15", "16", "19", "1"], "a": 1, "e": "El art. 15 regula la formación del personal sanitario y el art. 16 crea la Comisión en el CISNS."}, {"q": "Ante una mujer víctima de violencia de género con riesgo vital inminente que acude a urgencias, el protocolo común indica:", "o": ["Darle el alta y derivarla al CAVI", "Emitir solo el parte de lesiones", "Esperar a que decida denunciar", "No permitir que abandone el centro y contactar de inmediato con las Fuerzas y Cuerpos de Seguridad"], "a": 3, "e": "En riesgo vital se protege a la mujer en el centro, se avisa a las fuerzas de seguridad (112, 091, 062) y se emite el parte."}, {"q": "Según la Ley 4/2023, las terapias de conversión de la orientación sexual o la identidad de género:", "o": ["Están prohibidas incluso con el consentimiento del interesado", "Están permitidas si la persona es mayor de edad", "Están permitidas con informe psicológico previo", "Solo están prohibidas en menores"], "a": 0, "e": "La prohibición (art. 17) es absoluta, aunque exista consentimiento; su práctica es infracción muy grave."}, {"q": "Según la Ley 4/2023, en una persona intersexual menor de 12 años, las prácticas de modificación genital:", "o": ["Están permitidas con el consentimiento de los padres", "Están prohibidas hasta los 16 años en cualquier caso", "Están prohibidas, salvo indicación médica para proteger su salud física", "Están permitidas si son de carácter estético"], "a": 2, "e": "Menores de 12: prohibidas salvo necesidad médica para la salud física. Entre 12 y 16: solo a petición del menor con madurez certificada."}]},
9: {"tema": 9, "titulo": "Bioética, inteligencia artificial, secreto profesional y protección de datos. Sistemas de información y registros", "programa": "Principios fundamentales de la Bioética: dilemas éticos; inteligencia artificial. El secreto profesional. Código deontológico. Protección de datos personales: Reglamento (UE) 2016/679 y LO 3/2018. Sistemas de información en Atención Primaria y Especializada: historia clínica digital, registros de enfermería, informe de enfermería al alta, CMBD, CIE-10 y clasificaciones NANDA, NIC y NOC.", "preguntas": [{"q": "El Informe Belmont (1978) estableció como principios éticos básicos para la investigación:", "o": ["Cuatro principios: autonomía, beneficencia, no maleficencia y justicia", "Tres principios: respeto a las personas, beneficencia y justicia", "Cinco principios, incluida la confidencialidad", "Dos principios: autonomía y justicia"], "a": 1, "e": "Belmont formuló 3 principios. En 1979 Beauchamp y Childress separaron la no maleficencia y consolidaron los 4 principios."}, {"q": "Una enfermera aplica el listado de verificación quirúrgica y comprueba los \"correctos\" antes de administrar un fármaco. Actúa guiada principalmente por el principio de:", "o": ["Beneficencia", "Justicia", "Autonomía", "No maleficencia"], "a": 3, "e": "Las acciones dirigidas a evitar daños y eventos adversos responden al principio de no maleficencia (primum non nocere)."}, {"q": "Según Diego Gracia, los principios que forman la ética de mínimos son:", "o": ["No maleficencia y justicia", "Autonomía y beneficencia", "Beneficencia y justicia", "Autonomía y no maleficencia"], "a": 0, "e": "Mínimos (nivel público, exigibles): no maleficencia y justicia. Máximos (nivel privado): autonomía y beneficencia. Los mínimos prevalecen."}, {"q": "En el método deliberativo, las pruebas de consistencia a las que se somete el curso de acción elegido son:", "o": ["Eficacia, eficiencia y efectividad", "Autonomía, beneficencia y justicia", "Legalidad, publicidad y tiempo", "Validez, fiabilidad y aplicabilidad"], "a": 2, "e": "¿Es legal? ¿Lo defenderíamos en público? ¿Tomaríamos la misma decisión tras un tiempo de reflexión?"}, {"q": "Los Comités de Ética Asistencial de la Región de Murcia están regulados por el:", "o": ["Decreto 80/2005", "Decreto 66/2005", "Decreto 25/2006", "Decreto 106/2007"], "a": 1, "e": "Decreto 66/2005, de 10 de junio. El 80/2005 regula las instrucciones previas; el 25/2006, la demora máxima; el 106/2007, la segunda opinión."}, {"q": "Según el Decreto 66/2005, ¿cuál de las siguientes NO es una función de los Comités de Ética Asistencial?", "o": ["Emitir informes consultivos sobre dilemas éticos", "Colaborar en la elaboración de protocolos con implicaciones éticas", "Promover la formación en bioética", "Evaluar proyectos de ensayos clínicos"], "a": 3, "e": "Los ensayos clínicos los evalúa el CEIm. Los CEA tampoco median en conflictos laborales ni tramitan quejas."}, {"q": "Los informes y recomendaciones de un Comité de Ética Asistencial son:", "o": ["No vinculantes", "Vinculantes para el profesional", "Vinculantes solo si son unánimes", "De obligado cumplimiento para la gerencia"], "a": 0, "e": "El CEA asesora; no sustituye la responsabilidad del profesional ni actúa como tribunal."}, {"q": "Un paciente inconsciente tiene registradas instrucciones previas que rechazan la ventilación mecánica, pero su familia exige que se le conecte. Debe prevalecer:", "o": ["La opinión unánime de la familia", "El criterio del Comité de Ética Asistencial", "Lo establecido en las instrucciones previas", "La decisión del juez de guardia en todo caso"], "a": 2, "e": "Las instrucciones previas expresan la autonomía del paciente; la familia no puede revocarlas."}, {"q": "Según el Reglamento europeo de Inteligencia Artificial, un sistema de IA de triaje automatizado en urgencias se clasifica como de:", "o": ["Riesgo mínimo", "Alto riesgo", "Uso prohibido", "Riesgo limitado"], "a": 1, "e": "La IA que guía decisiones clínicas o forma parte de productos sanitarios es de alto riesgo: exige evaluación de conformidad y supervisión humana."}, {"q": "En el Espacio Europeo de Datos de Salud, el uso secundario de los datos se refiere a:", "o": ["La asistencia sanitaria directa del paciente", "La receta electrónica transfronteriza", "La consulta del historial por un médico de otro país", "La investigación, la estadística y el entrenamiento de algoritmos con datos anonimizados"], "a": 3, "e": "Uso primario = asistencia directa; uso secundario = investigación, innovación, salud pública e IA, con anonimización o seudonimización."}, {"q": "El secreto que permite que la información del paciente circule entre los miembros del equipo asistencial implicados en su atención se denomina:", "o": ["Secreto compartido", "Secreto derivado", "Secreto absoluto", "Secreto relativo"], "a": 0, "e": "El derivado afecta al personal no sanitario; el relativo es el modelo vigente con excepciones; el absoluto es insostenible jurídicamente."}, {"q": "Según el art. 199.2 del Código Penal, el profesional que divulga los secretos de otra persona incumpliendo su deber de sigilo puede ser castigado con:", "o": ["Prisión de 6 meses a 1 año", "Prisión de 2 a 5 años", "Prisión de 1 a 4 años, multa e inhabilitación especial de 2 a 6 años", "Solo con multa"], "a": 2, "e": "Pena de prisión de 1 a 4 años, multa de 12 a 24 meses e inhabilitación especial para la profesión de 2 a 6 años."}, {"q": "El Código Deontológico de la Enfermería Española vigente fue aprobado mediante:", "o": ["Una Ley Orgánica de 1989", "La Resolución 32/89 del Consejo General de Enfermería", "Un Real Decreto del Ministerio de Sanidad", "Una Orden Ministerial de 1954"], "a": 1, "e": "Es una norma corporativa: Resolución 32/89 del Consejo General de Enfermería, que sustituyó al código de 1954."}, {"q": "El artículo 22 del Código Deontológico de la Enfermería Española regula:", "o": ["El secreto profesional", "La actuación en emergencias", "Las relaciones en los puestos de gestión", "La objeción de conciencia"], "a": 3, "e": "Art. 19: secreto; art. 22: objeción de conciencia; art. 38: emergencias; art. 39: gestión."}, {"q": "Según el art. 39 del Código Deontológico, la enfermera que ejerce un puesto de supervisión:", "o": ["Nunca reprenderá públicamente a un colega", "Puede amonestar en público para dar ejemplo", "Debe comunicar al Colegio cualquier error", "Puede delegar su responsabilidad deontológica"], "a": 0, "e": "Las correcciones deben hacerse de forma individual y privada, manteniendo una relación dialogante."}, {"q": "El Reglamento (UE) 2016/679 de protección de datos:", "o": ["Requiere una ley española de transposición para aplicarse", "Solo obliga a las empresas privadas", "Es de aplicación directa en todos los Estados miembros", "Es una recomendación sin efectos vinculantes"], "a": 2, "e": "Los reglamentos europeos se aplican directamente; las directivas son las que requieren transposición."}, {"q": "Una enfermera consulta por curiosidad la historia clínica de un vecino que no es su paciente. Vulnera especialmente el principio del RGPD de:", "o": ["Exactitud", "Minimización de datos", "Limitación del plazo de conservación", "Transparencia"], "a": 1, "e": "Solo se debe acceder a los datos estrictamente necesarios para la finalidad asistencial; además es una infracción muy grave."}, {"q": "Según el RGPD, para que el consentimiento sea válido:", "o": ["Basta con que el paciente no se oponga", "Puede presumirse si el paciente es atendido", "Se admiten casillas premarcadas", "Debe ser una manifestación inequívoca mediante una clara acción afirmativa"], "a": 3, "e": "Debe ser libre, específico, informado e inequívoco. Quedan prohibidos el consentimiento tácito, el silencio y las casillas premarcadas."}, {"q": "Los datos relativos a la salud tienen, según el art. 9 del RGPD, la consideración de:", "o": ["Categoría especial de datos, cuyo tratamiento está prohibido salvo excepciones", "Datos personales ordinarios", "Datos públicos", "Datos anónimos"], "a": 0, "e": "Son categoría especial; se permite su tratamiento, entre otras excepciones, para la asistencia sanitaria por profesionales sujetos a secreto."}, {"q": "Según la LOPDGDD, un menor puede consentir por sí mismo el tratamiento de sus datos personales a partir de:", "o": ["Los 12 años", "Los 16 años", "Los 14 años", "Los 18 años"], "a": 2, "e": "Art. 7 LOPDGDD: mayores de 14 años. No confundir con los 16 años del consentimiento clínico de la Ley 41/2002."}, {"q": "La obligación de designar un Delegado de Protección de Datos no se aplica a:", "o": ["Los hospitales públicos", "Los profesionales sanitarios que ejercen a título individual", "Los centros de salud", "Las clínicas privadas"], "a": 1, "e": "El art. 34 LOPDGDD obliga a los centros sanitarios que mantienen historias clínicas, salvo a los profesionales individuales."}, {"q": "Según el art. 5 de la LOPDGDD, el deber de confidencialidad de quienes tratan datos personales:", "o": ["Termina al jubilarse el profesional", "Termina al fallecer el paciente", "Solo afecta al personal sanitario", "Se mantiene aunque haya finalizado la relación con el responsable del tratamiento"], "a": 3, "e": "Afecta a todos los que intervienen en el tratamiento, sanitarios o no, y persiste tras finalizar la relación."}, {"q": "La supervisora de una planta quirúrgica gestiona el mapa de camas y los traslados internos con el aplicativo:", "o": ["SELENE", "OMI-AP", "Ágora Plus", "CIAP-2"], "a": 0, "e": "SELENE es el sistema de Atención Especializada; OMI-AP es de Primaria y Ágora Plus es un visor."}, {"q": "La herramienta del SMS que permite a una enfermera de Atención Primaria visualizar la analítica realizada a su paciente en el hospital es:", "o": ["SELENE", "OMI-AP", "Ágora Plus", "SIVA-CMBD"], "a": 2, "e": "Ágora Plus es el visor regional que integra informes, analíticas e imágenes de todos los niveles asistenciales."}, {"q": "Un paciente comete 9 errores en el cuestionario de Pfeiffer. Esto indica:", "o": ["Función cognitiva normal", "Deterioro cognitivo severo", "Deterioro cognitivo leve", "Deterioro cognitivo moderado"], "a": 1, "e": "Pfeiffer cuenta errores: 0-2 normal; 3-4 leve; 5-7 moderado; 8-10 severo."}, {"q": "En la escala de Braden, se considera riesgo alto de úlceras por presión una puntuación:", "o": ["Superior a 18", "Entre 15 y 18", "Entre 13 y 14", "Igual o inferior a 12"], "a": 3, "e": "En Braden (6-23), a menor puntuación mayor riesgo: ≤ 12 alto, 13-14 moderado, 15-18 bajo."}, {"q": "Las pérdidas insensibles en 24 horas de un paciente afebril de 70 kg son aproximadamente:", "o": ["840 ml", "1.680 ml", "420 ml", "1.400 ml"], "a": 0, "e": "Peso × horas / 2 = 70 × 24 / 2 = 840 ml (0,5 ml/kg/h). La fiebre y la taquipnea las aumentan."}, {"q": "Según el Anexo VII del RD 1093/2010, en el informe de cuidados de enfermería al alta es una variable del conjunto mínimo (obligatoria):", "o": ["Las intervenciones NIC", "Los resultados NOC", "Los diagnósticos de enfermería", "El cuidador principal"], "a": 2, "e": "Los diagnósticos (con texto y código) son CM; las intervenciones NIC, los resultados NOC y el cuidador principal son recomendados."}, {"q": "En la CIE-10-ES, los códigos de procedimientos (PCS) tienen:", "o": ["Entre 3 y 7 caracteres con punto decimal", "Siempre 7 caracteres alfanuméricos", "5 caracteres", "4 caracteres numéricos"], "a": 1, "e": "Los diagnósticos tienen de 3 a 7 caracteres con punto; los procedimientos, siempre 7 caracteres sin punto."}, {"q": "El número de dominios de NANDA-I, NOC y NIC es, respectivamente:", "o": ["7, 7 y 13", "13, 13 y 7", "11, 7 y 7", "13, 7 y 7"], "a": 3, "e": "Regla 13-7-7. Además, la escala Likert de 1 a 5 es exclusiva de los resultados NOC."}]},
10: {"tema": 10, "titulo": "Bioética, Código Deontológico, consentimiento informado y secreto profesional. Calidad en el SNS", "programa": "Principios fundamentales de la Bioética. Código deontológico de la enfermería española. El consentimiento informado. El secreto profesional: concepto, regulación jurídica y relevancia penal. Calidad en el SNS: dimensiones de la calidad, evaluación de estructura, proceso y resultados, mejora continua, modelo EFQM 2020, auditorías e indicadores de seguridad, Value Based Healthcare, PROMs y PREMs, programas de calidad, GPC (GRADE) y práctica basada en la evidencia.", "preguntas": [{"q": "La disciplina filosófica que analiza de forma crítica y racional el fundamento de las normas morales es:", "o": ["La moral", "El derecho", "La ética", "La deontología"], "a": 2, "e": "La moral es el conjunto práctico de normas y costumbres; la ética es su reflexión teórica; la deontología, los deberes de una profesión."}, {"q": "El incumplimiento del Código Deontológico de Enfermería da lugar a una sanción de tipo:", "o": ["Corporativo o disciplinario, impuesta por el Colegio Profesional", "Penal, con prisión", "Multa judicial", "Ninguna, es solo un reproche moral"], "a": 0, "e": "La deontología se sanciona en el ámbito colegial; las multas judiciales y la prisión corresponden al derecho."}, {"q": "El Código de Núremberg (1947) surgió como respuesta a:", "o": ["El experimento de Tuskegee", "La Declaración de Helsinki", "Una iniciativa de la Asociación Médica Mundial", "Los juicios contra los médicos nazis"], "a": 3, "e": "Núremberg consagró el consentimiento voluntario en investigación. El Informe Belmont fue la respuesta a Tuskegee."}, {"q": "El término \"bioética\" fue acuñado en 1970 por:", "o": ["David Sackett", "Van Rensselaer Potter", "Tom Beauchamp", "Diego Gracia"], "a": 1, "e": "Potter la concibió como un puente entre las ciencias biológicas y las humanidades."}, {"q": "Según Diego Gracia, los principios que pertenecen al nivel II (ética de máximos) son:", "o": ["No maleficencia y justicia", "Justicia y autonomía", "Autonomía y beneficencia", "Beneficencia y no maleficencia"], "a": 2, "e": "Nivel I (mínimos, exigibles): no maleficencia y justicia. Nivel II (máximos, privados): autonomía y beneficencia."}, {"q": "Aplicar un apósito en ambiente húmedo para cicatrizar una úlcera es una aplicación del principio de:", "o": ["Beneficencia", "No maleficencia", "Justicia", "Autonomía"], "a": 0, "e": "La beneficencia exige acciones positivas para hacer el bien; la no maleficencia, evitar daños."}, {"q": "Sobre la objeción de conciencia de la enfermera, es correcto que:", "o": ["Puede ejercerse de forma colectiva por todo un servicio", "Se manifiesta de forma verbal en el momento de la técnica", "Puede ejercerse en una urgencia vital aunque no haya otro profesional", "Es individual y se manifiesta de forma anticipada y por escrito"], "a": 3, "e": "Es un derecho individual, anticipado y escrito; decae ante una urgencia vital si no hay otro profesional disponible."}, {"q": "Según el art. 8 de la Ley 41/2002, ¿cuál de estas actuaciones requiere consentimiento informado por escrito?", "o": ["Una extracción de sangre rutinaria", "Una endoscopia digestiva", "Un electrocardiograma", "Una vacuna intramuscular"], "a": 1, "e": "Se exige por escrito en cirugía, procedimientos diagnósticos o terapéuticos invasores y riesgos de notoria repercusión negativa (regla C.I.R.)."}, {"q": "Cuando por razones de salud pública se adopta una medida que implica el internamiento obligatorio de un paciente, debe comunicarse a la autoridad judicial en un plazo máximo de:", "o": ["48 horas", "72 horas", "24 horas", "7 días"], "a": 2, "e": "Art. 9.2 de la Ley 41/2002: si hay internamiento obligatorio, se comunica al juez en 24 horas."}, {"q": "Según la Ley 41/2002 vigente, ante una actuación de grave riesgo para la vida o la salud de un paciente de 17 años, el consentimiento lo presta:", "o": ["Su representante legal, una vez oída y tenida en cuenta la opinión del menor", "El propio menor, sin necesidad de informar a sus padres", "El juez de guardia", "El médico responsable"], "a": 0, "e": "Desde los 16 años hay mayoría de edad sanitaria, salvo en grave riesgo, ensayos clínicos o reproducción asistida, donde consiente el representante tras oír al menor."}, {"q": "Tras la LO 1/2023, para la interrupción voluntaria del embarazo de una menor de 16 o 17 años:", "o": ["Es necesario el consentimiento de sus padres", "Basta con informar a uno de los padres", "Se requiere autorización judicial", "La menor puede consentir por sí sola, sin necesidad del consentimiento ni del conocimiento de los padres"], "a": 3, "e": "La LO 1/2023 modificó el art. 9 de la Ley 41/2002 y eliminó además los 3 días de reflexión."}, {"q": "Según la LO 3/2021 de regulación de la eutanasia, el paciente debe formular:", "o": ["Una única solicitud verbal", "Dos solicitudes por escrito, separadas al menos 15 días naturales", "Tres solicitudes con 7 días de separación", "Dos solicitudes separadas al menos 30 días"], "a": 1, "e": "Son dos solicitudes voluntarias y escritas con al menos 15 días naturales entre ellas."}, {"q": "Entre los requisitos de la LORE para solicitar la prestación de ayuda para morir figura, si no se tiene nacionalidad ni residencia legal, acreditar un empadronamiento superior a:", "o": ["6 meses", "24 meses", "12 meses", "3 meses"], "a": 2, "e": "Nacionalidad española, residencia legal o empadronamiento de más de doce meses, además de ser mayor de edad y capaz."}, {"q": "Según el art. 197 bis del Código Penal, acceder sin autorización a la historia clínica electrónica de un vecino, aunque no se divulgue nada, puede castigarse con:", "o": ["Prisión de 6 meses a 2 años", "Solo una sanción administrativa leve", "Prisión de 1 a 4 años e inhabilitación", "Una multa de 1 mes"], "a": 0, "e": "El mero acceso no autorizado a un sistema de información es delito consumado (197 bis). La revelación por el profesional se castiga en el art. 199.2."}, {"q": "El celador que revela un dato clínico conocido por razón de su trabajo puede ser castigado, según el art. 199.1 del Código Penal, con:", "o": ["Prisión de 1 a 4 años e inhabilitación especial de 2 a 6 años", "Prisión de 6 meses a 2 años", "Inhabilitación de 2 a 6 años sin prisión", "Prisión de 1 a 3 años y multa de 6 a 12 meses"], "a": 3, "e": "El 199.1 es el tipo básico (oficio o relaciones laborales); el 199.2 agrava la pena para el profesional con deber de sigilo."}, {"q": "Correr las cortinas durante el aseo de un paciente encamado protege principalmente su:", "o": ["Confidencialidad", "Privacidad", "Secreto compartido", "Autonomía"], "a": 1, "e": "La privacidad es el entorno físico o virtual; la intimidad, la esfera reservada (art. 18.1 CE); la confidencialidad, la garantía de no revelar."}, {"q": "La obligación de emitir el parte de lesiones ante la sospecha de un delito público se fundamenta en:", "o": ["El art. 18 de la Constitución", "El art. 199 del Código Penal", "El art. 262 de la Ley de Enjuiciamiento Criminal", "El art. 9 de la Ley 41/2002"], "a": 2, "e": "El art. 262 LECrim obliga a comunicarlo al juzgado; el secreto cede amparado por el art. 20.7 CP (cumplimiento de un deber)."}, {"q": "Según el manual, tras la Ley 2/1990 la autoridad sanitaria en la Región de Murcia corresponde a:", "o": ["La Consejería de Sanidad", "El Servicio Murciano de Salud", "Las gerencias de área", "El Ministerio de Sanidad"], "a": 0, "e": "La Consejería es la autoridad sanitaria; el SMS es el ente encargado de la gestión y provisión de los servicios."}, {"q": "La norma que introduce la calidad sistémica y crea la Agencia de Calidad del SNS es la:", "o": ["Ley 14/1986, General de Sanidad", "Ley 41/2002, de autonomía del paciente", "Ley 44/2003, de ordenación de las profesiones sanitarias", "Ley 16/2003, de cohesión y calidad del SNS"], "a": 3, "e": "La Ley 14/1986 crea el SNS; la Ley 16/2003 introduce la calidad sistémica y la Agencia de Calidad."}, {"q": "Un nuevo apósito reduce el tiempo de cicatrización en una planta ordinaria de hospitalización. Se está midiendo su:", "o": ["Eficacia", "Efectividad", "Eficiencia", "Adecuación"], "a": 1, "e": "Eficacia = condiciones ideales (ensayo clínico); efectividad = práctica real; eficiencia = relación con el coste."}, {"q": "El principio de equidad en la atención sanitaria consiste en:", "o": ["Dar exactamente los mismos recursos a todos los pacientes", "Distribuir los recursos según su coste", "Distribuir la atención según la necesidad clínica", "Atender por orden de llegada"], "a": 2, "e": "Dar lo mismo a todos es igualdad; equidad es dar más a quien más lo necesita."}, {"q": "En el ciclo de Deming (PDCA), la fase Do (hacer) debe realizarse preferentemente:", "o": ["Mediante una prueba piloto controlada en una unidad", "Implantando el cambio a la vez en todo el hospital", "Sin recoger datos", "Antes de planificar los objetivos"], "a": 0, "e": "Primero se planifica, luego se aplica de forma controlada (piloto), se verifica y finalmente se estandariza o corrige."}, {"q": "La expresión \"(número de gestantes con pulsera de identificación / total de gestantes ingresadas) × 100\" es un:", "o": ["Criterio", "Estándar", "Objetivo general", "Indicador"], "a": 3, "e": "Criterio = norma cualitativa; indicador = fórmula de medida; estándar = meta numérica (por ejemplo, 100%)."}, {"q": "El modelo EFQM 2020 se estructura en:", "o": ["9 criterios agentes y resultados", "3 bloques (dirección, ejecución y resultados) y 7 criterios", "5 criterios", "12 estrategias"], "a": 1, "e": "EFQM 2020 sustituyó los 9 criterios de 2013 por 3 bloques y 7 criterios, inspirados en el círculo dorado de Sinek."}, {"q": "En el modelo EFQM 2020, la tasa de bacteriemias en UCI o la estancia media se evalúan en el criterio:", "o": ["6. Percepción de los grupos de interés", "3. Implicar a los grupos de interés", "7. Rendimiento estratégico y operativo", "1. Propósito, visión y estrategia"], "a": 2, "e": "El criterio 6 recoge percepciones (PREMs, clima laboral); el 7, los datos duros de rendimiento."}, {"q": "El Análisis Modal de Fallos y Efectos (AMFE) es una herramienta de gestión de riesgos:", "o": ["Proactiva, que se aplica antes de que ocurra el fallo", "Reactiva, tras un evento centinela", "De evaluación económica", "De medida de la satisfacción"], "a": 0, "e": "El AMFE anticipa fallos en procesos nuevos; tras un evento adverso grave se aplica el análisis causa raíz (reactivo)."}, {"q": "Según el estudio ENEAS, la incidencia de eventos adversos en pacientes hospitalizados y su evitabilidad fueron aproximadamente:", "o": ["4%, de los que el 10% eran evitables", "20%, de los que el 80% eran evitables", "9%, de los que el 10% eran evitables", "9%, de los que más del 42% eran evitables"], "a": 3, "e": "ENEAS: alrededor del 9% de los ingresados, con más del 42% de eventos evitables. En AP se realizó el estudio APEAS."}, {"q": "Según el proyecto Neumonía Zero, en el paciente con ventilación mecánica hay que mantener:", "o": ["El cabecero a 0° y el neumotaponamiento a 50 cmH₂O", "El cabecero a 30-45° y el neumotaponamiento entre 20 y 30 cmH₂O", "El cabecero a 15° y el neumotaponamiento a 40 cmH₂O", "El cabecero a 90° y el neumotaponamiento a 10 cmH₂O"], "a": 1, "e": "Semiincorporación de 30-45° para evitar microaspiraciones y cuff a 20-30 cmH₂O (menos produce fugas; más, isquemia traqueal)."}, {"q": "Según el proyecto Bacteriemia Zero, en la inserción de un catéter venoso central se recomienda:", "o": ["Povidona yodada y acceso femoral", "Alcohol de 70° y acceso yugular", "Clorhexidina alcohólica > 0,5% y evitar el acceso femoral", "Povidona yodada y acceso subclavio"], "a": 2, "e": "Clorhexidina alcohólica > 0,5% (habitualmente al 2%), máximas barreras estériles, preferir la subclavia y evitar la femoral."}, {"q": "Un paciente intervenido de prótesis de rodilla rellena un cuestionario sobre su dolor y su capacidad para subir escaleras. Se trata de un:", "o": ["PROM (resultado reportado por el paciente)", "PREM (experiencia reportada por el paciente)", "Indicador de estructura", "Net Promoter Score"], "a": 0, "e": "Los PROMs miden resultados de salud (dolor, función); los PREMs, la experiencia con la atención (trato, esperas, información)."}]},
11: {"tema": 11, "titulo": "Atención domiciliaria. Epidemiología y vigilancia epidemiológica", "programa": "Atención domiciliaria: concepto, visita domiciliaria y etapas, coordinación entre Atención Primaria, Especializada y Servicios Sociales, programas específicos e informe de continuidad de cuidados. Epidemiología: concepto y método. Diseños epidemiológicos. Enfermedades transmisibles de mayor incidencia en España. Sistema Nacional de Vigilancia Epidemiológica, RENAVE y EDO. COVID-19, virus emergentes y enfoque One Health.", "preguntas": [{"q": "En la atención domiciliaria, el sujeto de atención es:", "o": ["Exclusivamente el paciente inmovilizado", "El binomio paciente y familia o cuidador", "Exclusivamente el cuidador principal", "La comunidad de la zona básica"], "a": 1, "e": "La atención domiciliaria se dirige al paciente y a su familia o cuidador; si una opción excluye al cuidador, es sospechosa."}, {"q": "El orden correcto de las etapas de la visita domiciliaria es:", "o": ["Valoración, captación, planificación, ejecución, registro y evaluación", "Captación, planificación, valoración, ejecución, evaluación y registro", "Planificación, captación, valoración, ejecución, evaluación y registro", "Captación, valoración, planificación, ejecución, evaluación y registro"], "a": 3, "e": "Regla \"Con Valor Puedo Ejecutar Este Reto\": captación, valoración, planificación, ejecución, evaluación y registro."}, {"q": "En un paciente inmovilizado estable en su domicilio, la valoración integral debe actualizarse al menos:", "o": ["Cada 6 meses", "Cada mes", "Cada año", "Cada 2 años"], "a": 0, "e": "Se recomienda al menos cada seis meses en pacientes estables y con más frecuencia si hay inestabilidad o deterioro."}, {"q": "La sobrecarga del cuidador principal se valora con:", "o": ["El índice de Barthel", "La escala de Yesavage", "El test de Zarit", "La escala de Lawton y Brody"], "a": 2, "e": "Zarit mide la percepción de sobrecarga del cuidador (22-110 puntos; > 55 sobrecarga intensa)."}, {"q": "La escala de Yesavage se utiliza para valorar:", "o": ["El riesgo de úlceras por presión", "La depresión en personas mayores", "Las actividades instrumentales", "El riesgo de caídas"], "a": 1, "e": "Yesavage es la escala de depresión geriátrica; en su versión de 15 ítems, más de 5 puntos sugiere depresión."}, {"q": "En el SMS, el Modelo 313 es:", "o": ["El informe de alta médica", "El informe de continuidad de cuidados", "El documento de consentimiento informado", "La plantilla electrónica de Valoración Integral de Enfermería para registrar la visita domiciliaria"], "a": 3, "e": "El Modelo 313, en OMI-AP/Ágora, estructura el registro y obliga a cumplimentar escalas como Barthel, Norton/Braden, Pfeiffer o Zarit."}, {"q": "Cuando un Equipo de Soporte de Atención Domiciliaria (ESAD) interviene en un domicilio:", "o": ["Apoya y asesora, pero la responsabilidad del paciente sigue siendo del equipo de Atención Primaria", "Asume la responsabilidad total del paciente", "Sustituye definitivamente al médico y la enfermera de cupo", "Solo actúa en el hospital"], "a": 0, "e": "Los equipos de soporte nunca sustituyen al equipo de referencia de AP, que mantiene la responsabilidad asistencial."}, {"q": "El momento de mayor riesgo para la continuidad asistencial del paciente es:", "o": ["La primera consulta en el centro de salud", "La visita domiciliaria programada", "El alta hospitalaria", "La revisión anual del plan de cuidados"], "a": 2, "e": "La transición entre niveles, especialmente el alta, concentra errores de medicación y pérdida de información."}, {"q": "La hospitalización a domicilio está indicada en:", "o": ["Ancianos frágiles estables que solo precisan seguimiento", "Pacientes con procesos agudos que requerirían ingreso pero pueden recibir cuidados hospitalarios en casa", "Pacientes que rechazan la atención primaria", "Cualquier paciente inmovilizado"], "a": 1, "e": "Proporciona atención de nivel hospitalario en el domicilio (p. ej., antibioterapia intravenosa o reagudización de EPOC), con criterios estrictos."}, {"q": "En la prevención de úlceras por presión de un paciente inmovilizado, los cambios posturales deben realizarse:", "o": ["Cada 8 horas", "Una vez por turno", "Cada 4-6 horas", "Cada 2-3 horas"], "a": 3, "e": "Cambios posturales cada 2-3 horas, superficies especiales, hidratación de la piel y no masajear prominencias óseas."}, {"q": "En el programa de atención al paciente en situación terminal, el pronóstico de vida es generalmente:", "o": ["Inferior a 6 meses", "Inferior a 1 mes", "Inferior a 2 años", "Superior a 1 año"], "a": 0, "e": "Enfermedad avanzada, progresiva e incurable con pronóstico limitado, generalmente inferior a seis meses."}, {"q": "En un paciente paliativo en su domicilio que ya no puede tragar, la vía alternativa de elección para administrar la medicación es la:", "o": ["Intramuscular", "Intravenosa", "Subcutánea", "Rectal"], "a": 2, "e": "La vía oral es la de elección; si no es posible, la subcutánea (palomillas o infusores). La intramuscular se evita en paliativos."}, {"q": "Al iniciar tratamiento con morfina en un paciente terminal, la enfermera debe:", "o": ["Suspender la hidratación oral", "Prevenir sistemáticamente el estreñimiento", "Evitar la vía subcutánea", "Retirar los laxantes"], "a": 1, "e": "Los opioides siempre estriñen: la prevención con laxantes es obligatoria."}, {"q": "La sedación paliativa tiene como finalidad:", "o": ["Provocar la muerte del paciente", "Tratar cualquier síntoma leve", "Responder a la petición de la familia", "Aliviar síntomas refractarios disminuyendo el nivel de consciencia"], "a": 3, "e": "Busca aliviar síntomas refractarios (disnea, delirium) con fármacos como el midazolam; la eutanasia busca provocar la muerte."}, {"q": "El informe de continuidad de cuidados (ICC) debe cumplimentarse:", "o": ["En cualquier transición asistencial: alta, derivación, traslado o ingreso en residencia", "Solo al alta hospitalaria", "Solo cuando lo solicita la familia", "Solo en pacientes oncológicos"], "a": 0, "e": "Es un documento médico-legal para cualquier transición; no es exclusivo del alta hospitalaria."}, {"q": "¿Cuál de las siguientes es una característica que debe reunir el informe de continuidad de cuidados?", "o": ["Extenso", "Exhaustivo, con toda la historia clínica", "Conciso", "Manuscrito"], "a": 2, "e": "Debe ser completo, claro, conciso, preciso, actualizado, accesible y estandarizado. Lo innegociable: alergias y medicación actualizada."}, {"q": "Según Leavell y Clark, en el periodo prepatogénico de la enfermedad:", "o": ["Aparecen los primeros síntomas", "Interactúan el agente, el huésped y el medio ambiente", "Se producen cambios tisulares silentes", "Se producen las secuelas"], "a": 1, "e": "En el prepatogénico interactúa la tríada ecológica; el patogénico se divide en fase subclínica y clínica."}, {"q": "La prevención cuaternaria, acuñada por Jamoulle, tiene como objetivo:", "o": ["Rehabilitar al paciente con secuelas", "Detectar precozmente la enfermedad", "Vacunar a la población", "Evitar la sobremedicalización y la iatrogenia"], "a": 3, "e": "Protege al paciente de intervenciones innecesarias (desprescripción, evitar pruebas redundantes). La rehabilitación es prevención terciaria."}, {"q": "Una mamografía de cribado en una mujer sana de 50 años es una actividad de prevención:", "o": ["Secundaria, que reduce la prevalencia", "Primaria, que reduce la incidencia", "Terciaria", "Cuaternaria"], "a": 0, "e": "El cribado actúa en la fase subclínica: es prevención secundaria y actúa sobre la prevalencia."}, {"q": "En la fiebre tifoidea:", "o": ["El reservorio y la fuente de infección son siempre el agua", "El reservorio es el agua y la fuente el ser humano", "El reservorio es el ser humano y la fuente de infección puede ser el agua contaminada", "No existe reservorio"], "a": 2, "e": "El reservorio (donde vive y se multiplica el agente) y la fuente de infección (de donde pasa al huésped) no siempre coinciden."}, {"q": "En un estudio de casos y controles, la medida de asociación que se calcula es:", "o": ["El riesgo relativo", "La odds ratio", "La incidencia acumulada", "El número necesario a tratar"], "a": 1, "e": "Al no conocer la población en riesgo no se puede calcular la incidencia ni el RR; se usa la OR (ad/bc)."}, {"q": "El número necesario a tratar (NNT) se calcula como:", "o": ["El riesgo relativo menos 1", "La incidencia del grupo tratado entre la del control", "La odds ratio multiplicada por 100", "1 dividido entre la reducción del riesgo absoluto"], "a": 3, "e": "NNT = 1/RRA; la RRA es la diferencia entre la incidencia del grupo control y la del grupo tratado."}, {"q": "La primera causa de gastroenteritis bacteriana transmitida por alimentos en España es:", "o": ["Campylobacter", "Salmonella", "Listeria", "Escherichia coli"], "a": 0, "e": "Según la RENAVE, Campylobacter (sobre todo por pollo poco cocinado); su complicación grave es el síndrome de Guillain-Barré."}, {"q": "La Red Nacional de Vigilancia Epidemiológica (RENAVE) fue creada por el:", "o": ["RD 1030/2006", "RD 664/1997", "RD 2210/1995", "RD 1093/2010"], "a": 2, "e": "RD 2210/1995. La coordina el Centro Nacional de Epidemiología del Instituto de Salud Carlos III."}, {"q": "Ante la sospecha clínica de una enfermedad meningocócica, la declaración epidemiológica debe hacerse:", "o": ["De forma semanal, tras la confirmación del laboratorio", "De forma urgente (en menos de 24 horas), ante la mera sospecha", "Solo si fallece el paciente", "De forma mensual"], "a": 1, "e": "Las EDO urgentes se notifican ante la sospecha, sin esperar a la confirmación microbiológica."}, {"q": "Un niño que convive con un caso confirmado de tos ferina comienza con tos compatible, sin prueba de laboratorio todavía. Se clasifica como caso:", "o": ["Confirmado", "Sospechoso", "Descartado", "Probable"], "a": 3, "e": "Probable = clínica compatible + nexo epidemiológico. Confirmado exige prueba de laboratorio."}, {"q": "Legalmente, se considera brote epidémico la aparición de:", "o": ["Dos o más casos asociados en tiempo y lugar con una sospecha de causa común", "Al menos 20 casos", "Al menos 50 casos simultáneos", "Un caso grave de cualquier enfermedad"], "a": 0, "e": "Basta con 2 o más casos relacionados; todo brote es de declaración urgente aunque sea leve."}, {"q": "En la Región de Murcia, el dengue se declara desde 2020 de forma:", "o": ["Semanal ordinaria", "Mensual", "Urgente, por la presencia del mosquito tigre", "No es enfermedad de declaración obligatoria"], "a": 2, "e": "Por la implantación de Aedes albopictus en la región, el dengue es de declaración urgente para controlar el vector."}, {"q": "Según SiVIRA, para registrar una infección respiratoria aguda leve en Atención Primaria, los síntomas deben haber comenzado en los últimos:", "o": ["5 días", "10 días", "14 días", "21 días"], "a": 1, "e": "Límite de 10 días en AP. En la IRAG hospitalaria no existe ese límite temporal."}, {"q": "Sobre la fiebre del Nilo Occidental, es correcto que:", "o": ["Requiere aislamiento aéreo del paciente", "Se transmite de persona a persona", "Su vector es el mosquito Aedes", "Se transmite por mosquitos Culex y el ser humano es un fondo de saco"], "a": 3, "e": "Las aves son el reservorio; humanos y caballos no alcanzan viremia suficiente para transmitirla, por lo que no se aísla al paciente."}]},
12: {"tema": 12, "titulo": "Hospitalización a domicilio y telemedicina. Metodología cuantitativa y bioestadística", "programa": "Hospitalización a domicilio: concepto, marco legal, modelos organizativos, cartera de servicios, criterios de inclusión y exclusión, papel de enfermería, seguimiento telefónico, telemedicina, telemonitorización e indicadores de calidad. Metodología de la investigación cuantitativa: diseños, muestreo, variables, sesgos, estadística descriptiva e inferencial, pruebas diagnósticas, revisiones sistemáticas y metaanálisis. Ley 14/2007 de Investigación Biomédica y protección de datos en investigación. Estructura IMRyD.", "preguntas": [{"q": "La Hospitalización a Domicilio (HAD) es una modalidad asistencial que depende de:", "o": ["Atención Primaria, a través de los equipos de los centros de salud", "Atención Especializada, como alternativa a la hospitalización convencional", "Los servicios sociales municipales", "Las mutuas colaboradoras con la Seguridad Social"], "a": 1, "e": "La HAD es una modalidad de Atención Especializada: presta cuidados de nivel hospitalario en el domicilio y depende del hospital. La atención domiciliaria de AP es distinta (crónica, preventiva)."}, {"q": "El principio según el cual la HAD debe ofrecer en el domicilio cuidados de la misma complejidad, intensidad y calidad que en el hospital se denomina:", "o": ["Principio de subsidiariedad", "Principio de continuidad asistencial", "Principio de proximidad", "Principio de equivalencia asistencial"], "a": 3, "e": "La equivalencia asistencial es la base de la HAD: el paciente recibe en casa un nivel de atención equivalente al de la planta hospitalaria."}, {"q": "La duración habitual de un episodio de hospitalización a domicilio es de:", "o": ["7 a 14 días", "24 a 72 horas", "1 a 3 meses", "Indefinida, mientras el paciente siga vivo"], "a": 0, "e": "La HAD atiende procesos agudos o reagudizaciones durante un periodo limitado, habitualmente de 7 a 14 días, tras el cual el paciente es dado de alta a Atención Primaria."}, {"q": "¿Qué modelo organizativo de HAD es el más implantado en el Servicio Murciano de Salud?", "o": ["El de evitación del ingreso exclusivamente", "El de alta precoz exclusivamente", "El modelo mixto", "El modelo de cuidados paliativos exclusivos"], "a": 2, "e": "En el SMS predomina el modelo mixto, que combina la evitación del ingreso (pacientes derivados desde urgencias, consultas o AP) y el alta precoz desde planta."}, {"q": "En la organización de una unidad de HAD, la carga de trabajo orientativa de cada enfermera es de:", "o": ["3-5 pacientes y 2-3 visitas al día", "20-25 pacientes y 12-14 visitas al día", "10-15 pacientes y 6-8 visitas al día", "30 pacientes y 10 visitas al día"], "a": 2, "e": "La ratio orientativa es de 10-15 pacientes por enfermera con 6-8 visitas diarias, y un médico por cada 2-3 enfermeras."}, {"q": "El proceso más frecuente dentro de la cartera de servicios de la HAD es:", "o": ["La antibioterapia parenteral domiciliaria (OPAT)", "La nutrición parenteral total", "La transfusión de hemoderivados", "La terapia de presión negativa (VAC)"], "a": 0, "e": "La OPAT (Outpatient Parenteral Antimicrobial Therapy) es la actividad más frecuente: endocarditis, osteomielitis, ITU complicadas, etc."}, {"q": "¿Cuál de las siguientes situaciones constituye un criterio de exclusión absoluto para la HAD?", "o": ["Paciente con EPOC reagudizada pero estable", "Residir en una zona rural incluida en el área de cobertura", "Necesitar antibioterapia intravenosa", "La negativa del paciente a ser atendido en su domicilio"], "a": 3, "e": "La HAD exige el consentimiento informado del paciente; su negativa es un criterio de exclusión absoluto. Las demás situaciones son compatibles con la HAD."}, {"q": "Un paciente con fiebre de origen desconocido que está en estudio, ¿es candidato a HAD?", "o": ["Sí, siempre que disponga de un cuidador", "No, porque no tiene un diagnóstico definido y requiere pruebas frecuentes", "Sí, mediante el modelo de alta precoz", "Sí, si se le aplica telemonitorización"], "a": 1, "e": "Un criterio de inclusión es tener un diagnóstico definido y un plan terapéutico claro. Los procesos en estudio con pruebas frecuentes, como la fiebre de origen desconocido, se excluyen."}, {"q": "En la educación sanitaria al cuidador en HAD, la técnica \"teach-back\" consiste en:", "o": ["Pedir al paciente o cuidador que explique con sus propias palabras lo que se le ha enseñado", "Entregar únicamente información escrita para que la lea en casa", "Repetir la enfermera la explicación tres veces seguidas", "Grabar en vídeo la técnica para que la vea más tarde"], "a": 0, "e": "En el teach-back el receptor repite la instrucción con sus palabras, lo que permite comprobar la comprensión y corregir errores."}, {"q": "Al iniciar una llamada de seguimiento telefónico estructurado, la enfermera debe en primer lugar:", "o": ["Formular preguntas cerradas sobre los síntomas", "Dar las recomendaciones de cuidados", "Identificarse y verificar la identidad del interlocutor", "Registrar la llamada en la historia clínica"], "a": 2, "e": "Tras planificar y revisar la historia, la llamada empieza identificando al profesional y verificando con quién se habla (paciente o cuidador). Después: preguntas abiertas y cerradas, decisión, comprobación de la comprensión y registro."}, {"q": "Es un ejemplo de telemedicina asincrónica:", "o": ["Una videoconsulta en tiempo real con el paciente", "El envío de fotografías de una herida que la enfermera revisa más tarde", "Una llamada telefónica de seguimiento", "Una visita domiciliaria presencial"], "a": 1, "e": "La telemedicina asincrónica (en diferido) se basa en el envío de datos o imágenes que se revisan después; la sincrónica es en tiempo real, como la videoconsulta."}, {"q": "En un paciente con insuficiencia cardiaca telemonitorizado en HAD, ¿qué dato sugiere retención hídrica?", "o": ["Una SatO₂ estable del 96%", "Una disminución de peso de 1 kg en una semana", "Una frecuencia cardiaca de 70 lpm", "Un aumento de peso de 2 kg en 3 días"], "a": 3, "e": "El peso es una variable clave en la IC: una ganancia de 2 kg en 3 días sugiere retención de líquidos y debe generar una alerta."}, {"q": "Según el modelo de Donabedian, ¿cuál de los siguientes es un indicador de resultado en HAD?", "o": ["La estancia media", "La ratio de pacientes por enfermera", "El número de visitas diarias", "La tasa de reingresos hospitalarios a 30 días"], "a": 3, "e": "La tasa de reingresos a 30 días es el indicador de resultado de referencia. La estancia media y la actividad son indicadores de proceso; las ratios, de estructura."}, {"q": "La temperatura corporal medida en grados Celsius es una variable cuantitativa medida en escala:", "o": ["De razón, porque tiene un cero absoluto", "De intervalo, porque su cero es arbitrario", "Ordinal", "Nominal"], "a": 1, "e": "En la escala de intervalo el cero es arbitrario (0 °C no significa ausencia de temperatura). En la de razón existe un cero absoluto (peso, edad, TA)."}, {"q": "El grado o categoría de una úlcera por presión es una variable:", "o": ["Cuantitativa discreta", "Cualitativa nominal", "Cualitativa ordinal", "Cuantitativa continua"], "a": 2, "e": "Las categorías de UPP tienen un orden jerárquico pero no una distancia medible entre ellas: es una variable cualitativa ordinal, como el estadio TNM."}, {"q": "Se quiere obtener por muestreo sistemático una muestra de 200 pacientes de una población de 2.000. El procedimiento correcto es:", "o": ["Calcular k = 10, elegir al azar un número entre 1 y 10 y seleccionar uno de cada 10", "Elegir a los 200 primeros pacientes del listado", "Dividir la población en estratos y elegir 200 de cada uno", "Seleccionar al azar varios hospitales y estudiar a todos sus pacientes"], "a": 0, "e": "En el muestreo sistemático k = N/n (2.000/200 = 10); se elige al azar el primer elemento entre 1 y k y después uno de cada k."}, {"q": "En el muestreo estratificado, la afijación que reparte la muestra teniendo en cuenta el tamaño y también la variabilidad de cada estrato es la:", "o": ["Afijación simple", "Afijación óptima de Neyman", "Afijación proporcional", "Afijación por conglomerados"], "a": 1, "e": "La afijación simple asigna el mismo número a cada estrato; la proporcional, según su tamaño; la óptima (de Neyman) considera también la varianza de cada estrato."}, {"q": "El muestreo en \"bola de nieve\":", "o": ["Es no probabilístico y útil para estudiar poblaciones ocultas o de difícil acceso", "Es probabilístico y el más representativo", "Exige disponer de un listado completo de la población", "Es un tipo de muestreo por conglomerados"], "a": 0, "e": "En la bola de nieve unos participantes captan a otros; es un muestreo no probabilístico, útil en poblaciones ocultas (p. ej., personas sin hogar o consumidores de drogas)."}, {"q": "Respecto al aumento del tamaño de la muestra en un estudio, es correcto que:", "o": ["Elimina cualquier sesgo de selección", "Corrige el efecto Hawthorne", "Aumenta el error aleatorio", "Reduce el error aleatorio, pero no corrige los sesgos"], "a": 3, "e": "El error aleatorio disminuye al aumentar la muestra; el sesgo es un error sistemático que no se corrige con más sujetos, sino con un buen diseño."}, {"q": "El efecto Hawthorne es un sesgo de información que consiste en que:", "o": ["El investigador interpreta los datos según sus expectativas", "Los sujetos con enfermedad grave fallecen antes de ser incluidos", "Los participantes modifican su conducta al saberse observados", "Los pacientes recuerdan peor las exposiciones antiguas"], "a": 2, "e": "Hawthorne: cambio de conducta al saberse observado. Rosenthal (efecto Pigmalión): influencia de las expectativas del investigador. Neyman: sesgo de selección por prevalencia. Recuerdo: sesgo de memoria."}, {"q": "¿Cuál de las siguientes características impide considerar a una variable como factor de confusión?", "o": ["Estar asociada a la exposición estudiada", "Ser factor de riesgo del desenlace", "Ser un eslabón intermedio en la cadena causal entre la exposición y el efecto", "Poder controlarse mediante la aleatorización"], "a": 2, "e": "Un factor de confusión debe ser factor de riesgo del desenlace, estar asociado a la exposición y no ser un paso intermedio de la cadena causal. Se controla con aleatorización, restricción, emparejamiento o análisis estratificado y multivariante."}, {"q": "Un estudio obtiene un riesgo relativo de 1,12 con un intervalo de confianza del 95% de 0,85 a 1,32. Se puede concluir que:", "o": ["La exposición es un factor de riesgo estadísticamente significativo", "La exposición es un factor protector significativo", "El resultado es clínicamente relevante", "El resultado no es estadísticamente significativo porque el intervalo incluye el 1"], "a": 3, "e": "Para RR y OR el valor nulo es el 1 (para diferencias de medias, el 0). Si el IC incluye el valor nulo, el resultado no es estadísticamente significativo."}, {"q": "La distribución normal o de Gauss queda completamente definida por:", "o": ["La media y la desviación típica", "La mediana y el rango intercuartílico", "La moda y el rango", "El valor p y el intervalo de confianza"], "a": 0, "e": "La normal es simétrica (media = mediana = moda) y se define por dos parámetros: la media (μ) y la desviación típica (σ)."}, {"q": "Si aumenta la prevalencia de la enfermedad en la población en la que se aplica una prueba diagnóstica:", "o": ["Aumentan la sensibilidad y la especificidad", "Aumenta el valor predictivo positivo y disminuye el valor predictivo negativo", "Disminuye el valor predictivo positivo y aumenta el negativo", "No varía ningún parámetro de la prueba"], "a": 1, "e": "Sensibilidad y especificidad son propias de la prueba. Los valores predictivos dependen de la prevalencia: al aumentar esta, sube el VPP [VP/(VP+FP)] y baja el VPN [VN/(VN+FN)]."}, {"q": "En un metaanálisis se obtiene un índice I² de Higgins del 75%. ¿Qué modelo de análisis está indicado?", "o": ["El modelo de efectos aleatorios", "El modelo de efectos fijos", "No se puede calcular ningún efecto combinado en ningún caso", "Basta con aplicar la escala de Jadad"], "a": 0, "e": "Una heterogeneidad alta (I² elevado) aconseja el modelo de efectos aleatorios, más conservador y con IC más ancho; con heterogeneidad baja se usa el de efectos fijos."}, {"q": "La declaración PRISMA 2020 para la publicación de revisiones sistemáticas consta de:", "o": ["12 ítems en 3 secciones", "22 ítems en 5 secciones", "25 ítems en 6 secciones", "27 ítems en 7 secciones"], "a": 3, "e": "PRISMA 2020 incluye una lista de comprobación de 27 ítems organizados en 7 secciones y un diagrama de flujo. Para revisiones panorámicas existe PRISMA-ScR."}, {"q": "Respecto a la escala de Jadad para valorar la calidad de los ensayos clínicos, es correcto que:", "o": ["Valora la calidad de los estudios cualitativos", "Su puntuación máxima es 5 y una puntuación de 2 o menos indica baja calidad", "Su puntuación máxima es 10 y se considera aceptable a partir de 5", "Solo valora el tamaño de la muestra"], "a": 1, "e": "Jadad puntúa de 0 a 5 la aleatorización, el cegamiento y la descripción de pérdidas; ≤ 2 indica baja calidad y ≥ 3, calidad aceptable."}, {"q": "En un metaanálisis, un gráfico en embudo (funnel plot) asimétrico sugiere la existencia de:", "o": ["Ausencia de heterogeneidad", "Un efecto global no significativo", "Sesgo de publicación", "Un modelo de efectos fijos correcto"], "a": 2, "e": "Si no hay sesgo, los estudios se distribuyen simétricamente en el embudo; la falta de estudios pequeños con resultados negativos (asimetría) sugiere sesgo de publicación."}, {"q": "Según la Ley 14/2007, de Investigación Biomédica, el consentimiento para participar en una investigación debe ser:", "o": ["Expreso y por escrito", "Verbal, dejando constancia en la historia clínica", "Tácito si el paciente no se opone", "Otorgado siempre por el Comité de Ética de la Investigación"], "a": 0, "e": "La Ley 14/2007 exige consentimiento expreso y por escrito, previa información adecuada. También establece la gratuidad de la donación de muestras y la responsabilidad solidaria de investigador, centro y promotor."}, {"q": "La disposición adicional 17.ª de la LOPDGDD (LO 3/2018) permite reutilizar datos de salud para investigación sin solicitar un nuevo consentimiento siempre que:", "o": ["El investigador sea a la vez el médico o la enfermera que atiende al paciente", "Los datos se publiquen identificados para garantizar su trazabilidad", "Lo autorice verbalmente el jefe de servicio", "Se seudonimicen y se separen técnica y funcionalmente los roles de investigador y de asistencial"], "a": 3, "e": "La D. A. 17.ª admite el uso de datos seudonimizados sin nuevo consentimiento, con garantías: separación entre quienes investigan y quienes atienden al paciente y compromiso de no reidentificación."}]},
13: {"tema": 13, "titulo": "Salud comunitaria y grupos vulnerables. Investigación cualitativa y práctica basada en la evidencia", "programa": "Salud comunitaria: conceptos, determinantes sociales de la salud, marco legal estatal y de la Región de Murcia, grupos excluidos y en riesgo de exclusión, barreras de acceso, prevención y fomento de la salud, participación comunitaria, datos epidemiológicos regionales y rol de la enfermería comunitaria. Investigación cualitativa: fundamentos, diseños, proceso y fases, técnicas (observación, entrevista, grupos de discusión y técnicas de consenso), análisis, criterios de rigor, software CAQDAS y práctica basada en la evidencia.", "preguntas": [{"q": "¿Qué declaración internacional renovó en 2018 los compromisos de la Atención Primaria, situando la Cobertura Sanitaria Universal y las tecnologías digitales como ejes del siglo XXI?", "o": ["Declaración de Alma-Ata", "Carta de Ottawa", "Declaración de Astaná", "Declaración de Yakarta"], "a": 2, "e": "Astaná (2018) reafirmó Alma-Ata (1978) adaptándola al siglo XXI: Cobertura Sanitaria Universal, cronicidad, tecnologías y ODS. Ottawa (1986) es la carta de la Promoción de la Salud."}, {"q": "La diferencia esencial entre la salud comunitaria y la salud pública tradicional es que la salud comunitaria:", "o": ["Planifica con la población, buscando su empoderamiento y participación", "Planifica para la población desde las instituciones", "Se limita a la atención individual en la consulta", "Excluye la participación de otros sectores"], "a": 0, "e": "La salud pública tiende a planificar \"para\" la población; la salud comunitaria lo hace \"con\" ella, con participación real y corresponsabilidad."}, {"q": "Las tres dimensiones del Sentido de Coherencia (SOC) de Antonovsky son:", "o": ["Eficacia, eficiencia y efectividad", "Autonomía, beneficencia y justicia", "Información, consulta y asociación", "Comprensibilidad, manejabilidad y significatividad"], "a": 3, "e": "El SOC es la base del modelo salutogénico: comprender lo que ocurre (comprensibilidad), disponer de recursos para afrontarlo (manejabilidad) y considerar que merece la pena (significatividad)."}, {"q": "Los cuatro campos determinantes de la salud descritos en el Informe Lalonde (1974) son:", "o": ["Edad, sexo, genética y clase social", "Biología humana, estilos de vida, medio ambiente y sistema sanitario", "Proximales, intermedios, distales y estructurales", "Vivienda, empleo, educación y renta"], "a": 1, "e": "Lalonde identificó biología humana, estilos de vida, medio ambiente y sistema de asistencia sanitaria, aunque no abordó a fondo las desigualdades estructurales."}, {"q": "En el modelo de Dahlgren y Whitehead (1991), el centro de las capas concéntricas lo ocupan:", "o": ["La edad, el sexo y los factores genéticos", "Las condiciones socioeconómicas, culturales y ambientales generales", "Las redes sociales y comunitarias", "Las condiciones de vida y de trabajo"], "a": 0, "e": "En el centro están los factores individuales no modificables (edad, sexo, genética); después, estilos de vida, redes sociales, condiciones de vida y trabajo y, en la capa externa, las condiciones socioeconómicas generales."}, {"q": "El hacinamiento en las viviendas de trabajadores agrícolas temporeros es, según la clasificación operativa, un determinante:", "o": ["Proximal", "Biológico", "Distal o estructural", "Intermedio"], "a": 3, "e": "Vivienda, empleo, educación, transporte o redes sociales son determinantes intermedios: conectan lo individual (proximal) con lo estructural (políticas, economía)."}, {"q": "El concepto de interseccionalidad aplicado a la vulnerabilidad social significa que:", "o": ["Cada factor de riesgo actúa de forma independiente", "La vulnerabilidad depende solo del nivel de renta", "Los factores de riesgo no se suman, sino que se multiplican al coincidir en una persona", "Solo afecta a la población inmigrante"], "a": 2, "e": "Una persona puede pertenecer a varios grupos vulnerables a la vez (p. ej., mujer, inmigrante, sin recursos): los riesgos se potencian y su riesgo sanitario crece exponencialmente."}, {"q": "La norma fundamental que organiza el Servicio Murciano de Salud y sitúa la Atención Primaria como puerta de entrada al sistema regional es:", "o": ["La Ley 33/2011, General de Salud Pública", "La Ley 4/1994, de Salud de la Región de Murcia", "La Ley 16/2003, de Cohesión y Calidad del SNS", "La Ley 39/2006, de Dependencia"], "a": 1, "e": "La Ley 4/1994, de 26 de julio, de Salud de la Región de Murcia, es la norma de cabecera del SMS. La Ley 33/2011 es estatal y regula la salud pública."}, {"q": "Según el modelo salutogénico, un \"activo para la salud\" es:", "o": ["Cualquier carencia que deba corregirse en la comunidad", "Cualquier recurso (persona, lugar, asociación o institución) que potencia la capacidad de mantener el bienestar", "Exclusivamente un recurso sanitario público", "Un indicador epidemiológico de morbilidad"], "a": 1, "e": "Frente al modelo de déficit, la salutogénesis busca lo que genera salud. Los activos (una asociación vecinal, un parque, una red de apoyo) se identifican mediante el mapeo de activos."}, {"q": "En la escalera de participación de Arnstein (1969), la participación real o poder ciudadano comienza en el peldaño de:", "o": ["La asociación", "La información", "La consulta", "El apaciguamiento"], "a": 0, "e": "Manipulación y terapia son no participación; información, consulta y apaciguamiento, participación simbólica; asociación, poder delegado y control ciudadano, participación real."}, {"q": "La llamada \"paradoja de género\" en salud se refiere a que las mujeres:", "o": ["Tienen menor esperanza de vida y mejor salud percibida", "Presentan menos trastornos de ansiedad y depresión", "Utilizan menos los servicios sanitarios", "Tienen mayor esperanza de vida, pero peor salud percibida y más años con discapacidad"], "a": 3, "e": "Las mujeres viven más, pero refieren peor salud percibida y más trastornos ansioso-depresivos, en relación con la doble carga de trabajo, la precariedad y los cuidados."}, {"q": "Ante una barrera lingüística con un paciente inmigrante, es una práctica desaconsejada:", "o": ["Recurrir a servicios de interpretación profesionales", "Utilizar materiales de educación sanitaria en varios idiomas", "Utilizar habitualmente a familiares, especialmente a menores, como traductores", "Apoyarse en agentes comunitarios de salud"], "a": 2, "e": "El uso inapropiado de familiares como intérpretes dificulta la comprensión de los tratamientos y compromete la confidencialidad. Intérpretes, materiales multiidioma y agentes comunitarios son estrategias recomendadas."}, {"q": "El tipo de razonamiento característico de la investigación cualitativa es:", "o": ["Inductivo: de los datos particulares a la construcción de patrones y teorías", "Deductivo: de la teoría general a la confirmación de hipótesis", "Exclusivamente estadístico", "Hipotético-deductivo con contraste de hipótesis"], "a": 0, "e": "Regla de oro: cualitativa = inductiva (particular → general); cuantitativa = deductiva (general → particular)."}, {"q": "La epojé o bracketing, que consiste en poner entre paréntesis los prejuicios del investigador, es propia de:", "o": ["La fenomenología hermenéutica de Heidegger", "La teoría fundamentada de Glaser y Strauss", "La fenomenología descriptiva de Husserl", "La investigación-acción de Lewin"], "a": 2, "e": "Husserl (descriptiva) propone la epojé. Heidegger (hermenéutica) la considera imposible: el investigador es un ser-en-el-mundo (Dasein) y usa su precomprensión en el círculo hermenéutico."}, {"q": "En un estudio etnográfico, la perspectiva \"emic\" corresponde a:", "o": ["La interpretación científica del investigador desde fuera", "La revisión bibliográfica previa", "El análisis estadístico de los datos", "La visión de los propios miembros del grupo, desde dentro"], "a": 3, "e": "Emic = visión desde dentro (nativa, local). Etic = interpretación desde fuera del investigador, con marcos teóricos de la disciplina."}, {"q": "Un diseño cualitativo basado en el interaccionismo simbólico, el método comparativo constante y el muestreo teórico, cuyo fin es generar teoría a partir de los datos, es:", "o": ["La fenomenología", "La teoría fundamentada (Grounded Theory)", "La etnografía", "El estudio de caso"], "a": 1, "e": "La teoría fundamentada (Glaser y Strauss, 1967) recoge y analiza los datos de forma simultánea, elige a los participantes según la teoría emergente y culmina en una categoría central."}, {"q": "Respecto a la investigación-acción, es correcto que:", "o": ["El investigador debe mantener una distancia fría y neutral", "Su fin es solo generar conocimiento teórico", "Sigue un proceso lineal con una única fase de análisis", "Los participantes son coinvestigadores y el proceso sigue una espiral de planificación, acción, observación y reflexión"], "a": 3, "e": "La investigación-acción (Kurt Lewin) busca transformar la realidad. Es colaborativa y cíclica: planificar, actuar, observar y reflexionar, lo que lleva a una nueva planificación."}, {"q": "Para estructurar una pregunta de búsqueda sobre el impacto de pasar de turnos rotatorios a turnos fijos en el burnout de la plantilla de enfermería, el formato más adecuado es:", "o": ["ECLIPSE", "PICO", "SPIDER", "SPICE"], "a": 0, "e": "ECLIPSE (Expectation, Client group, Location, Impact, Professionals, SErvice) está diseñado para preguntas de gestión y políticas sanitarias. PICO es para eficacia; SPICE y SPIDER, para preguntas cualitativas."}, {"q": "En investigación cualitativa, el tamaño de la muestra se determina:", "o": ["Mediante una fórmula con el nivel de confianza y las pérdidas esperadas", "Por saturación de los datos, cuando las nuevas entrevistas dejan de aportar información nueva", "Siempre con un mínimo de 100 participantes", "Por el comité de ética antes de iniciar el estudio"], "a": 1, "e": "No se usan fórmulas: la muestra es flexible y se cierra al alcanzar la saturación, cuando los discursos se vuelven redundantes y no surgen códigos ni categorías nuevas."}, {"q": "El tipo de muestreo de elección general en investigación cualitativa es:", "o": ["El aleatorio estratificado", "La bola de nieve", "El intencional o propositivo", "El sistemático"], "a": 2, "e": "Se eligen deliberadamente informantes ricos en información. La bola de nieve se reserva para poblaciones ocultas o estigmatizadas; el muestreo probabilístico no se usa."}, {"q": "En investigación cualitativa, los gatekeepers o \"porteros\" son:", "o": ["Los informantes que transcriben las entrevistas", "Los auditores externos del estudio", "Personas con poder para facilitar o bloquear el acceso del investigador al campo", "Los participantes con mayor nivel de estudios"], "a": 2, "e": "Son figuras estratégicas (p. ej., la supervisora de la unidad o un líder comunitario) que abren o cierran la entrada al escenario de estudio."}, {"q": "Según la tipología de Gold, el rol de \"participante completo\" en la observación se caracteriza por:", "o": ["Observar sin ninguna interacción con el grupo", "Ocultar su identidad investigadora, lo que plantea dilemas éticos y el riesgo de \"volverse nativo\"", "Ser un investigador externo con participación mínima", "Revelar abiertamente su rol de investigador desde el principio"], "a": 1, "e": "El participante completo se integra en el grupo ocultando su propósito: máxima inmersión, pero problemas éticos (engaño, falta de consentimiento) y riesgo de perder la capacidad crítica (going native)."}, {"q": "En relación con los grupos de discusión o grupos focales, es correcto que:", "o": ["Reúnen habitualmente a 6-12 personas homogéneas, y su fortaleza es el efecto sinérgico del grupo", "Deben mezclar participantes con distinto nivel de poder para enriquecer el debate", "Sustituyen a la entrevista individual con la suma de opiniones", "Se realizan de forma anónima y a distancia"], "a": 0, "e": "El grupo debe ser homogéneo para que todos hablen con libertad (las asimetrías de poder inhiben). Dura 60-120 minutos, con un moderador y un observador."}, {"q": "Una técnica de consenso con expertos geográficamente dispersos, que responden de forma anónima a cuestionarios sucesivos con retroalimentación estadística entre rondas, es:", "o": ["La técnica de grupo nominal", "La técnica de la pecera (fishbowl)", "El grupo focal", "El método Delphi"], "a": 3, "e": "El Delphi evita el contacto entre expertos y el efecto halo; suele tener 2-3 rondas. El grupo nominal, en cambio, es presencial."}, {"q": "En la técnica de grupo nominal, durante la ronda de exposición (round-robin):", "o": ["Los participantes debaten libremente cada idea", "Cada participante expone por turno una idea, que se anota sin debatirla ni criticarla", "Se realiza la votación final", "Se envían cuestionarios por correo"], "a": 1, "e": "Secuencia: generación silenciosa → exposición por turnos sin debate → clarificación (debate estructurado) → votación individual."}, {"q": "Devolver a los participantes las transcripciones e interpretaciones para que confirmen que su vivencia se ha recogido fielmente (member checking) asegura principalmente la:", "o": ["Credibilidad", "Transferibilidad", "Dependencia", "Confirmabilidad"], "a": 0, "e": "El member checking es la estrategia de elección para la credibilidad (equivalente a la validez interna). La confirmabilidad se asegura con la reflexividad."}, {"q": "El criterio de rigor de Lincoln y Guba equivalente a la fiabilidad, que se garantiza mediante la pista de auditoría (audit trail), es la:", "o": ["Credibilidad", "Transferibilidad", "Dependencia o consistencia", "Saturación"], "a": 2, "e": "Credibilidad = validez interna; transferibilidad = validez externa (descripción densa); dependencia = fiabilidad (pista de auditoría); confirmabilidad = objetividad (reflexividad)."}, {"q": "En un estudio sobre las demoras en urgencias se entrevista sobre el mismo hecho a un paciente, a la enfermera de triaje y al médico de guardia. Esta estrategia es una triangulación:", "o": ["Metodológica", "Teórica", "De investigadores", "De datos (de personas)"], "a": 3, "e": "Contrastar la perspectiva de distintos actores sobre un mismo hecho es triangulación de datos (de personas). La metodológica combina diferentes técnicas (p. ej., entrevista y grupo focal)."}, {"q": "Respecto al software de análisis cualitativo (CAQDAS) como ATLAS.ti o NVivo, es correcto que:", "o": ["Facilita la gestión, codificación y recuperación de los datos, pero la interpretación la hace el investigador", "Analiza de forma autónoma los discursos y extrae las conclusiones", "Sustituye la necesidad de triangulación", "No permite calcular la concordancia entre codificadores"], "a": 0, "e": "El CAQDAS es un soporte logístico: gestiona documentos, codifica, recupera fragmentos, aloja memos y calcula la concordancia entre codificadores (kappa de Cohen). El análisis es humano."}, {"q": "En los criterios FAME del Instituto Joanna Briggs para la evidencia cualitativa, la \"M\" (Meaningfulness) valora:", "o": ["La viabilidad económica de la intervención", "La efectividad clínica de la intervención", "La adecuación ética y cultural al contexto", "El significado que la intervención tiene para el paciente según su experiencia y valores"], "a": 3, "e": "F = Feasibility (viabilidad o factibilidad), A = Appropriateness (adecuación ética y cultural), M = Meaningfulness (significado para el paciente), E = Effectiveness (efectividad)."}]},
14: {"tema": 14, "titulo": "Educación para la salud y autocuidado. Salud pública, indicadores de salud y priorización", "programa": "Educación para la salud: concepto, marco legal y teorías; metodología individual, grupal y comunitaria; técnicas didácticas y materiales; fomento del autocuidado en paciente, cuidador y familia; elaboración, evaluación y sostenibilidad de programas; grupos de autoayuda y agentes de salud. Salud pública: concepto, niveles de prevención, modelos de salud y enfermedad, indicadores de morbilidad, mortalidad, letalidad y esperanza de vida, principales problemas de salud, métodos de priorización, determinantes sociales y práctica basada en la evidencia.", "preguntas": [{"q": "¿Qué artículo de la Ley 14/1986, General de Sanidad, establece que las actuaciones de las Administraciones Públicas Sanitarias estarán orientadas, entre otros fines, a la educación sanitaria de la población?", "o": ["Artículo 1", "Artículo 10", "Artículo 56", "Artículo 6"], "a": 3, "e": "El art. 6 orienta las actuaciones a la promoción de la salud y a la educación sanitaria; el art. 18 recoge la educación sanitaria como actuación prioritaria."}, {"q": "El modelo que explica la conducta preventiva a partir de la susceptibilidad y la gravedad percibidas y de los beneficios y barreras percibidos es el de:", "o": ["Bandura", "Rosenstock (modelo de creencias en salud)", "Prochaska y DiClemente", "Ausubel"], "a": 1, "e": "El modelo de creencias en salud (Rosenstock) se basa en la amenaza percibida (susceptibilidad y gravedad) y en el balance entre beneficios y barreras."}, {"q": "Según Bandura, la fuente más potente para aumentar la autoeficacia es:", "o": ["Las experiencias de dominio (logros propios)", "La persuasión verbal del profesional", "Las experiencias vicarias", "Los estados fisiológicos"], "a": 0, "e": "Los éxitos propios (experiencias de dominio) son la fuente más potente; por eso se recomiendan objetivos pequeños y alcanzables al inicio."}, {"q": "Un fumador afirma que el tabaco no le causa ningún problema y que no tiene intención de dejarlo. Según el modelo transteórico, se encuentra en la etapa de:", "o": ["Contemplación", "Preparación", "Precontemplación", "Mantenimiento"], "a": 2, "e": "En la precontemplación no hay intención de cambio porque la persona no percibe el problema. En la contemplación ya existe ambivalencia."}, {"q": "El autor que sostiene que, para que el aprendizaje sea real, la nueva información debe conectarse con los conocimientos previos del educando es:", "o": ["Knowles", "Ausubel", "Rosenstock", "Pender"], "a": 1, "e": "Ausubel describió el aprendizaje significativo. Knowles es el autor de la andragogía (educación de adultos)."}, {"q": "Según Dorothea Orem, el sistema de enfermería en el que se enmarca la educación para la salud es el:", "o": ["Totalmente compensatorio", "Parcialmente compensatorio", "De suplencia total", "De apoyo-educación"], "a": 3, "e": "Orem describe tres sistemas: totalmente compensatorio, parcialmente compensatorio y de apoyo-educación, que es el que fortalece la agencia de autocuidado mediante la EpS."}, {"q": "¿Cuál de los siguientes objetivos cumple los criterios SMART?", "o": ["Caminar 30 minutos, 5 días por semana, durante los próximos 3 meses", "Llevar una vida más saludable", "Mejorar la alimentación", "Hacer más ejercicio a partir de ahora"], "a": 0, "e": "Un objetivo SMART es específico, medible (cifra), alcanzable, relevante y temporalizado (plazo). Los demás son deseos sin cifra ni plazo."}, {"q": "La técnica teach-back evalúa principalmente:", "o": ["La capacidad intelectual del paciente", "La memoria a largo plazo del cuidador", "La claridad de la explicación del profesional", "El nivel de estudios del paciente"], "a": 2, "e": "Con el teach-back el paciente explica con sus palabras lo aprendido; si hay errores, el profesional reformula el mensaje. Evalúa la claridad de quien explica, no al paciente."}, {"q": "Un paciente sabe que fumar le perjudica, pero duda y no se decide a dejarlo. La técnica de elección es:", "o": ["La entrevista motivacional", "La charla informativa magistral", "El consejo autoritario", "La entrega de un folleto sin más"], "a": 0, "e": "La entrevista motivacional (Miller y Rollnick) está indicada ante la ambivalencia; usa la estrategia OARS: preguntas abiertas, afirmaciones, escucha reflexiva y resúmenes."}, {"q": "¿Cuál de las siguientes acciones NO forma parte del consejo breve estructurado de las \"5 aes\"?", "o": ["Averiguar", "Aconsejar", "Acordar", "Analizar"], "a": 3, "e": "Las 5 aes son: averiguar, aconsejar, acordar, ayudar y asegurar el seguimiento."}, {"q": "El tamaño óptimo orientativo de un grupo de educación para la salud en Atención Primaria es de:", "o": ["2-3 participantes", "20-25 participantes", "6-10 participantes", "Más de 30 participantes"], "a": 2, "e": "Entre 6 y 10 participantes se favorecen la participación activa y la cohesión, con sesiones de unos 60-90 minutos."}, {"q": "En un taller con adolescentes se quiere ensayar cómo rechazar la presión de los amigos para consumir alcohol. La técnica más adecuada es:", "o": ["La exposición teórica", "El role-playing o dramatización", "La lluvia de ideas", "La entrega de un folleto"], "a": 1, "e": "El role-playing permite practicar habilidades sociales y trabajar actitudes en un entorno seguro, con análisis posterior en grupo."}, {"q": "La técnica de fotovoz (photovoice), en la que los vecinos fotografían elementos de su entorno que afectan a su salud, es sobre todo una técnica de:", "o": ["Evaluación económica", "Diagnóstico participativo", "Educación individual", "Cierre de sesión"], "a": 1, "e": "La fotovoz es una técnica de diagnóstico participativo: la comunidad documenta sus problemas y activos para debatirlos y planificar acciones."}, {"q": "En la valoración familiar, el ecomapa permite visualizar:", "o": ["Las relaciones de la familia con sistemas y recursos externos (servicios, amigos, asociaciones)", "La herencia genética de las enfermedades", "La puntuación de funcionalidad familiar de 0 a 10", "El grado de sobrecarga del cuidador"], "a": 0, "e": "El genograma muestra la estructura y las relaciones internas; el ecomapa, las redes de apoyo externas. La funcionalidad se mide con el Apgar familiar y la sobrecarga con la escala de Zarit."}, {"q": "Un paciente de un grupo de autoayuda refiere un gran alivio al descubrir que otros miembros tienen sus mismos problemas. Según Yalom, este factor terapéutico es la:", "o": ["Catarsis", "Infusión de esperanza", "Altruismo", "Universalidad"], "a": 3, "e": "Universalidad: descubrir que el sufrimiento no es único. El altruismo es la mejora que produce ayudar a otros."}, {"q": "En un grupo de autoayuda, el papel de la enfermera es:", "o": ["Dirigir y liderar todas las sesiones", "Decidir quién puede hablar en cada sesión", "Facilitar y asesorar, respetando la horizontalidad del grupo", "Sustituir a los miembros en la toma de decisiones"], "a": 2, "e": "Los grupos de autoayuda son horizontales y autogestionados; la enfermera actúa como facilitadora o asesora técnica, nunca como líder."}, {"q": "En el método de priorización de Hanlon, el componente C (eficacia de la solución) se puntúa:", "o": ["De 0,5 a 1,5", "De 0 a 10", "De 0 a 20", "Solo con 0 o 1"], "a": 0, "e": "C actúa como multiplicador: 0,5 (baja eficacia), 1 (media) y 1,5 (alta). El componente D (factibilidad, PEARL) es el que se puntúa con 0 o 1."}, {"q": "Un problema de salud obtiene la máxima puntuación en magnitud, severidad y eficacia, pero la intervención no es legal (L = 0 en el PEARL). Según el método Hanlon:", "o": ["Mantiene una prioridad alta por el peso de los demás componentes", "Su prioridad final es 0 y el problema se descarta", "Su prioridad se reduce a la mitad", "Se suma 1 punto de penalización"], "a": 1, "e": "Fórmula: (A + B) × C × D. D vale 0 si cualquiera de los criterios PEARL (pertinencia, economía, aceptabilidad, recursos, legalidad) es 0, lo que anula la prioridad."}, {"q": "La herramienta de elección para representar el cronograma de un programa de EpS, con las tareas simultáneas y las dependencias entre actividades, es:", "o": ["La parrilla de Simplex", "El ecomapa", "El método Delphi", "El diagrama de Gantt"], "a": 3, "e": "El diagrama de Gantt sitúa las actividades en un eje temporal y permite identificar dependencias y la ruta crítica. La evaluación se planifica a la vez que el programa."}, {"q": "\"Reducir un 10% la incidencia de eventos cardiovasculares en la zona básica en 5 años\" es un objetivo de:", "o": ["Proceso", "Estructura", "Impacto", "Resultado"], "a": 2, "e": "Los objetivos de impacto se refieren a indicadores de salud poblacionales a largo plazo; los de resultado, a cambios en conductas o conocimientos; los de proceso, a las actividades; y los de estructura, a los recursos."}, {"q": "¿Qué autor actualizó la definición clásica de salud pública ampliándola a las enfermedades no infecciosas y añadiendo explícitamente la salud mental?", "o": ["Milton Terris", "Charles-Edward A. Winslow", "Piédrola Gil", "Marc Lalonde"], "a": 0, "e": "Winslow (1920) hablaba de enfermedades infecciosas y eficiencia física; Terris (1992) amplió la definición a las enfermedades en general y añadió la salud mental."}, {"q": "Una enfermera de AP pacta con un anciano polimedicado la retirada progresiva de benzodiacepinas para evitar caídas y efectos adversos. Esta actuación es prevención:", "o": ["Primaria", "Secundaria", "Terciaria", "Cuaternaria"], "a": 3, "e": "La prevención cuaternaria (Jamoulle) protege al paciente de la sobremedicalización y de intervenciones innecesarias, es decir, de la iatrogenia."}, {"q": "Un programa de cribado de cáncer colorrectal mediante sangre oculta en heces corresponde a la prevención:", "o": ["Primaria, cuyo objetivo es reducir la incidencia", "Secundaria, cuyo objetivo es reducir la prevalencia mediante el diagnóstico precoz", "Terciaria, cuyo objetivo es la rehabilitación", "Cuaternaria, cuyo objetivo es evitar la iatrogenia"], "a": 1, "e": "Los cribados detectan la enfermedad en fase subclínica: prevención secundaria. La primaria (vacunas, promoción) reduce la incidencia."}, {"q": "Es una de las críticas a la definición de salud de la OMS (1946):", "o": ["Ser demasiado dinámica", "Excluir la dimensión social", "Ser estática, utópica y difícil de medir objetivamente", "Limitarse a la ausencia de enfermedad"], "a": 2, "e": "Se critica que habla de un \"estado\" (estática), que el \"completo bienestar\" es inalcanzable (utópica) y que el bienestar es subjetivo y difícil de medir."}, {"q": "Si se introduce un tratamiento que prolonga la vida de los diabéticos pero no cura la enfermedad, manteniéndose igual la incidencia:", "o": ["Disminuye la prevalencia", "Disminuye la incidencia", "Aumenta la prevalencia", "No cambia ningún indicador"], "a": 2, "e": "En situación estable, P = I × D. Si aumenta la duración media de la enfermedad, aumenta la prevalencia aunque la incidencia no cambie."}, {"q": "Para comparar la mortalidad de la Región de Murcia con la de una comunidad mucho más envejecida, el indicador adecuado es:", "o": ["La tasa de mortalidad ajustada o estandarizada por edad", "La tasa bruta de mortalidad", "El número absoluto de defunciones", "La tasa de letalidad"], "a": 0, "e": "La tasa bruta depende de la estructura de edad; la estandarización elimina ese efecto y permite comparaciones justas entre poblaciones."}, {"q": "La letalidad de una enfermedad se calcula como:", "o": ["Defunciones totales / población total", "Casos nuevos / población en riesgo", "Defunciones por la enfermedad / población total", "Defunciones por la enfermedad / número de enfermos de esa enfermedad"], "a": 3, "e": "La letalidad mide la gravedad: su denominador son los enfermos. La mortalidad específica usa como denominador la población total."}, {"q": "Respecto al índice de Swaroop-Uemura, es correcto que:", "o": ["Mide la proporción de muertes infantiles", "Es el porcentaje de defunciones de personas de 50 años o más, y un valor alto indica mejor nivel de salud", "Un valor bajo indica un excelente nivel sanitario", "Mide los años de vida ajustados por calidad"], "a": 1, "e": "Un índice cercano al 100% indica que la mayoría de las personas fallece tras alcanzar la vejez, reflejo de buen desarrollo sanitario."}, {"q": "El virus del Nilo Occidental, enfermedad emergente en el sur y levante de España, se transmite principalmente por mosquitos del género:", "o": ["Culex", "Aedes", "Anopheles", "Phlebotomus"], "a": 0, "e": "Es una zoonosis de aves a humanos transmitida por mosquitos Culex (C. pipiens, C. perexiguus). No hay vacuna humana: la prevención es el control de vectores."}, {"q": "Según el análisis de Dever basado en los campos de salud de Lalonde, el determinante que más contribuye a la mortalidad es:", "o": ["El sistema de asistencia sanitaria", "La biología humana", "El medio ambiente", "El estilo de vida"], "a": 3, "e": "El estilo de vida explica alrededor del 43% de la mortalidad y el sistema sanitario solo el 11%, aunque este recibe en torno al 90% del gasto."}]},
15: {"tema": 15, "titulo": "Comunicación, relación de ayuda y entrevista clínica. Demografía sanitaria e indicadores demográficos", "programa": "Técnicas y habilidades de comunicación: relación enfermera-paciente, asertividad, modelo de Peplau, relación de ayuda (Rogers, Carkhuff, Chalifour, Cibanal), trabajo en equipo, entrevista clínica y entrevista motivacional; valoración de las necesidades de apoyo emocional del paciente, cuidador y familia mediante escalas. Demografía sanitaria: demografía estática y dinámica, fuentes, indicadores de natalidad, fecundidad, mortalidad, migraciones y crecimiento, índices de estructura poblacional, envejecimiento, cronicidad y equidad en salud.", "preguntas": [{"q": "Según la regla de Mehrabian, el componente que más peso tiene en el impacto emocional de un mensaje es:", "o": ["El no verbal (55%)", "El verbal (55%)", "El paraverbal (55%)", "Los tres componentes pesan lo mismo"], "a": 0, "e": "Verbal 7%, paraverbal 38% (tono, volumen, ritmo) y no verbal 55%. Ante una incongruencia, el receptor cree al mensaje no verbal."}, {"q": "Según la proxémica de Edward T. Hall, la distancia adecuada para realizar una entrevista clínica o una valoración de enfermería es la distancia personal, que abarca:", "o": ["De 0 a 45 cm", "De 1,20 a 3,60 m", "De 45 cm a 1,20 m", "Más de 3,60 m"], "a": 2, "e": "Íntima: 0-45 cm (procedimientos); personal: 45 cm-1,20 m (entrevista); social: 1,20-3,60 m; pública: más de 3,60 m."}, {"q": "En la ventana de Johari, el área ciega corresponde a:", "o": ["Lo que uno conoce de sí mismo y oculta a los demás", "Lo que los demás perciben de nosotros y nosotros desconocemos", "Lo que conocen tanto uno mismo como los demás", "Lo que nadie conoce"], "a": 1, "e": "El área ciega se reduce pidiendo feedback; el área oculta (lo que uno sabe y esconde), con la autoexposición. El objetivo es ampliar el área abierta."}, {"q": "Un familiar insiste en ver la historia clínica sin autorización y la enfermera responde: \"Es muy posible que tenga razón y que en otros centros se la enseñen, pero aquí no puedo hacerlo\". La técnica asertiva utilizada es:", "o": ["El disco rayado", "La aserción negativa", "La interrogación negativa", "El banco de niebla"], "a": 3, "e": "El banco de niebla da parte de razón al interlocutor sin cambiar la postura. El disco rayado consiste en repetir el mismo mensaje sin conceder nada."}, {"q": "En la pirámide de estratificación de Kaiser Permanente, el paciente crónico complejo o pluripatológico (3-5% de la población) debe recibir:", "o": ["Solo actividades de promoción de la salud", "Educación grupal como única intervención", "Gestión de la enfermedad (disease management) exclusivamente", "Gestión de casos por una enfermera gestora de casos"], "a": 3, "e": "Nivel 1 (70-80%): promoción y autocuidado; nivel 2 (15-20%): gestión de la enfermedad; nivel 3 (3-5%, consume más del 50% de los recursos): gestión de casos."}, {"q": "La técnica de los \"mensajes yo\" para expresar quejas o sentimientos negativos sin provocar una actitud defensiva fue formulada por:", "o": ["Thomas Gordon", "Carl Rogers", "Hildegard Peplau", "Robert Carkhuff"], "a": 0, "e": "Thomas Gordon. El mensaje yo describe la conducta de forma objetiva, expresa el propio sentimiento, explica la consecuencia y propone un cambio."}, {"q": "En el modelo de Peplau, la fase en la que el paciente obtiene el máximo beneficio de los servicios ofrecidos y que equivale a la ejecución del proceso enfermero es la:", "o": ["Orientación", "Identificación", "Explotación", "Resolución"], "a": 2, "e": "Orientación (valoración y diagnóstico), identificación (planificación), explotación o aprovechamiento (ejecución) y resolución (evaluación y alta)."}, {"q": "Según Hildegard Peplau, el rol de la enfermera de mayor importancia en la relación terapéutica es el de:", "o": ["Docente", "Consejero", "Persona recurso", "Sustituto"], "a": 1, "e": "Peplau describió seis roles (extraño, persona recurso, docente, líder, sustituto y consejero) y consideró el de consejero el más importante."}, {"q": "Las tres actitudes básicas de Carl Rogers para la relación de ayuda son:", "o": ["Simpatía, compasión y consejo", "Directividad, autoridad y control", "Aceptación positiva incondicional, empatía y congruencia", "Exploración, comprensión y acción"], "a": 2, "e": "Rogers considera necesarias y suficientes la aceptación incondicional, la empatía y la autenticidad o congruencia. Exploración, comprensión y acción son las fases de Carkhuff."}, {"q": "Ante un paciente oncológico que llora, la enfermera le dice: \"No se preocupe, verá como todo sale bien\". Según Carkhuff, es una respuesta no facilitadora del tipo:", "o": ["Florista", "Detective", "Juez", "Sargento"], "a": 0, "e": "El florista ofrece un falso consuelo que impide al paciente expresar su sufrimiento. Lo correcto es estar presente, escuchar y acompañar."}, {"q": "Respecto a la diferencia entre empatía y simpatía en la relación de ayuda, es correcto que:", "o": ["La simpatía es la actitud ideal porque la enfermera sufre junto al paciente", "La empatía permite comprender los sentimientos del paciente sin perder el \"como si\", mientras que la simpatía supone contagio emocional", "Son sinónimos", "La empatía supone identificarse totalmente con las emociones del paciente"], "a": 1, "e": "La simpatía implica contagio emocional, pérdida de objetividad y riesgo de burnout. La empatía comprende al otro manteniendo la distancia terapéutica."}, {"q": "Según el modelo de Tuckman, la etapa de desarrollo de un equipo caracterizada por luchas de poder y choques de personalidad es la de:", "o": ["Formación (forming)", "Normalización (norming)", "Desempeño (performing)", "Conflicto (storming)"], "a": 3, "e": "Forming (cortesía e incertidumbre) → storming (conflicto) → norming (cohesión y normas) → performing (máximo rendimiento) → adjourning (disolución, añadida en 1977)."}, {"q": "En la comunicación estructurada SBAR (SAER), la etapa de Evaluación (Assessment) incluye:", "o": ["El juicio clínico de la enfermera sobre lo que le ocurre al paciente, además de los datos", "Solo la lectura de las constantes vitales del monitor", "La fecha de ingreso y los antecedentes personales", "La petición concreta de una actuación al médico"], "a": 0, "e": "S: situación; A: antecedentes (ingreso, diagnóstico, alergias); E: evaluación con juicio clínico; R: recomendación o propuesta concreta de acción."}, {"q": "Según el modelo de gestión de conflictos de Thomas-Kilmann, durante una parada cardiorrespiratoria el estilo más adecuado del líder es el:", "o": ["Evitativo", "Acomodaticio", "De compromiso", "Competitivo"], "a": 3, "e": "En una emergencia vital el estilo competitivo (decisiones unilaterales e inmediatas) es el adecuado. En el día a día, el ideal es el colaborativo (ganar/ganar)."}, {"q": "El modelo de equipo en el que se difuminan las fronteras entre disciplinas, el paciente forma parte del equipo y existe liberación de roles (role release) es el:", "o": ["Multidisciplinar", "Transdisciplinar", "Interdisciplinar", "Jerárquico"], "a": 1, "e": "El multidisciplinar trabaja en paralelo; el interdisciplinar comparte un plan con objetivos comunes; el transdisciplinar es el máximo nivel de integración."}, {"q": "Según Borrell, para prevenir el \"síndrome del picaporte\" en la consulta se recomienda:", "o": ["Interrumpir al paciente desde el primer minuto con preguntas cerradas", "Citar siempre al paciente para otro día", "Preguntar al inicio si hay alguna otra cosa que le preocupe ese día", "Limitar la consulta a un solo motivo sin preguntar más"], "a": 2, "e": "Tras el vaciado de la información preelaborada, Borrell recomienda explorar las demandas añadidas (\"¿hay algo más que le preocupe hoy?\") y negociar prioridades."}, {"q": "NO es un principio de la entrevista motivacional:", "o": ["Expresar empatía", "Desarrollar la discrepancia", "Confrontar directamente la resistencia del paciente con argumentos", "Apoyar la autoeficacia"], "a": 2, "e": "Los cuatro principios son expresar empatía, desarrollar la discrepancia, rodar con la resistencia (no confrontarla) y apoyar la autoeficacia."}, {"q": "Una cuidadora obtiene 52 puntos en la escala de Zarit de 22 ítems (versión española, puntuación de 1 a 5 por ítem). El resultado indica:", "o": ["Sobrecarga leve", "Ausencia de sobrecarga", "Sobrecarga intensa", "Claudicación familiar confirmada"], "a": 0, "e": "Menos de 47: sin sobrecarga; 47-55: sobrecarga leve; más de 55: sobrecarga intensa. En la versión abreviada de 7 ítems, ≥ 17 indica sobrecarga."}, {"q": "La principal característica de la escala HAD (Hospital Anxiety and Depression Scale) es que:", "o": ["Es exclusiva de pacientes psiquiátricos institucionalizados", "Mide la sobrecarga del cuidador", "Valora la situación sociofamiliar del anciano", "Excluye los síntomas somáticos para evitar falsos positivos en pacientes con enfermedad física"], "a": 3, "e": "La HAD tiene 14 ítems (7 de ansiedad y 7 de depresión) y no incluye síntomas somáticos. En cada subescala: 0-7 normal, 8-10 dudoso, ≥ 11 caso probable."}, {"q": "Un anciano obtiene 12 puntos en la escala de valoración sociofamiliar de Gijón. Esto indica:", "o": ["Situación social normal", "Riesgo social", "Problema social grave", "Depresión geriátrica"], "a": 1, "e": "Gijón (5-25 puntos): 5-9 situación aceptable, 10-14 riesgo social y 15 o más problema social."}, {"q": "Una familia obtiene 5 puntos en el Apgar familiar de Smilkstein. Se interpreta como:", "o": ["Familia normofuncional", "Disfunción familiar leve", "Disfunción familiar grave", "Resultado no valorable"], "a": 1, "e": "Apgar familiar (0-10): 7-10 normofuncional, 4-6 disfunción leve y 0-3 disfunción grave."}, {"q": "La teoría que describe el paso del predominio de las enfermedades infecciosas al de las enfermedades crónicas y degenerativas es:", "o": ["La transición demográfica de Notestein", "La compresión de la morbilidad de Fries", "El modelo de Dahlgren y Whitehead", "La transición epidemiológica de Omran"], "a": 3, "e": "Omran (1971) describe el cambio de los patrones de enfermedad; Notestein (1945), el cambio de las tasas de natalidad y mortalidad."}, {"q": "Respecto al Padrón municipal, es correcto que:", "o": ["Lo gestionan los Ayuntamientos, se actualiza de forma continua y acredita la residencia para obtener la tarjeta sanitaria", "Lo elabora el INE cada 10 años en los años terminados en 1", "Está protegido por el secreto estadístico y no es público", "Solo recoge a la población de hecho"], "a": 0, "e": "El Censo lo elabora el INE cada 10 años con secreto estadístico; el Padrón es un registro administrativo público y continuo de los Ayuntamientos."}, {"q": "En un municipio hay 10.000 residentes presentes, 500 residentes ausentes y 200 transeúntes. Su población de derecho es:", "o": ["10.200", "10.700", "10.500", "10.000"], "a": 2, "e": "Población de derecho = residentes presentes + residentes ausentes (10.500). Población de hecho = residentes presentes + transeúntes (10.200)."}, {"q": "Una población con crecimiento vegetativo negativo puede tener un crecimiento real positivo si:", "o": ["El saldo migratorio positivo supera el déficit vegetativo", "La tasa de mortalidad aumenta", "La emigración es superior a la inmigración", "Nunca es posible"], "a": 0, "e": "Crecimiento real = crecimiento vegetativo (N − D) + saldo migratorio (I − E). Es la situación actual de España y de Murcia."}, {"q": "El denominador de la tasa de fecundidad general es:", "o": ["La población total", "El total de mujeres de la población", "Los nacidos vivos", "Las mujeres en edad fértil (15-49 años)"], "a": 3, "e": "La tasa bruta de natalidad usa la población total; la de fecundidad general se limita a las mujeres de 15 a 49 años."}, {"q": "La tasa de mortalidad materna se calcula dividiendo las defunciones maternas entre:", "o": ["Las mujeres en edad fértil, por 1.000", "Los partos totales, por 1.000", "Los nacidos vivos, por 100.000", "Las mujeres embarazadas, por 10.000"], "a": 2, "e": "Su denominador son los nacidos vivos y, por ser un hecho poco frecuente, se expresa por 100.000."}, {"q": "La mortalidad postneonatal comprende las defunciones ocurridas:", "o": ["En los primeros 7 días de vida, por causas obstétricas", "Desde los 28 días hasta antes de cumplir 1 año, predominantemente por causas exógenas", "Desde las 28 semanas de gestación hasta el 7.º día", "Entre el 1.º y el 5.º año de vida"], "a": 1, "e": "Neonatal: menos de 28 días (precoz, menos de 7 días; causas endógenas). Postneonatal: de 28 días a menos de 1 año (infecciones, accidentes, alimentación)."}, {"q": "El denominador de las tasas de dependencia es siempre:", "o": ["La población de 15 a 64 años", "La población mayor de 65 años", "La población menor de 15 años", "La población total"], "a": 0, "e": "Dependencia global = (menores de 15 + mayores de 64) / población de 15-64 años × 100; la senil solo incluye a los mayores en el numerador."}, {"q": "Respecto al coeficiente de Gini, es correcto que:", "o": ["Un valor de 1 indica igualdad perfecta", "Un valor de 0,85 indica un reparto muy equitativo", "Solo puede tomar valores negativos", "Un valor de 0 indica igualdad perfecta en el reparto"], "a": 3, "e": "Gini oscila entre 0 (igualdad perfecta) y 1 (desigualdad máxima). Se deriva de la curva de Lorenz."}]},
16: {"tema": 16, "titulo": "Prevención y promoción de la salud. Detección precoz y factores de riesgo por etapas de la vida", "programa": "Prevención y promoción de la salud: conceptos, niveles de prevención y Carta de Ottawa. Marco normativo y estratégico nacional y de la Región de Murcia. Detección precoz de problemas de salud: cribado, escalas y diagnósticos de riesgo. Factores de riesgo y cuidados enfermeros en la infancia, adolescencia, edad adulta y vejez. Programas y estrategias del SNS y del SMS.", "preguntas": [{"q": "\"El proceso que permite a las personas incrementar el control sobre su salud para mejorarla\" es la definición de promoción de la salud de:", "o": ["La Declaración de Alma-Ata (1978)", "La Carta de Ottawa (1986)", "El Informe Lalonde (1974)", "La Ley 33/2011, General de Salud Pública"], "a": 1, "e": "La Carta de Ottawa (1986) es el documento fundacional de la promoción de la salud. Alma-Ata (1978) estableció la APS como estrategia para la \"Salud para todos en el año 2000\"."}, {"q": "¿Cuál de las siguientes NO es una de las cinco áreas de acción de la Carta de Ottawa?", "o": ["Elaborar políticas públicas saludables", "Reorientar los servicios sanitarios", "Aumentar el número de camas hospitalarias de agudos", "Reforzar la acción comunitaria"], "a": 2, "e": "Las cinco áreas son: políticas públicas saludables, entornos favorables, acción comunitaria, desarrollo de aptitudes personales y reorientación de los servicios sanitarios."}, {"q": "Es un ejemplo de prevención cuaternaria:", "o": ["La vacunación antigripal", "La mamografía de cribado", "La rehabilitación cardiaca tras un infarto", "Evitar la prescripción de antibióticos en una infección vírica"], "a": 3, "e": "La prevención cuaternaria (Jamoulle) protege al paciente de la sobremedicalización y la iatrogenia: evitar pruebas innecesarias, desprescribir, no tratar lo que no lo requiere."}, {"q": "La exploración de la sensibilidad del pie con monofilamento en un paciente con diabetes diagnosticada es prevención:", "o": ["Terciaria", "Primaria", "Secundaria", "Cuaternaria"], "a": 0, "e": "Se busca precozmente una complicación de una enfermedad ya establecida: prevención terciaria. Detectar precozmente la diabetes en sanos sería secundaria."}, {"q": "La prueba del talón en el recién nacido es un ejemplo de prevención:", "o": ["Secundaria", "Primaria", "Terciaria", "Cuaternaria"], "a": 0, "e": "Es un cribado en población asintomática para detectar precozmente enfermedades (metabolopatías): prevención secundaria."}, {"q": "Respecto al PAPPS, es correcto que:", "o": ["Es una ley estatal de salud pública", "Es un decreto del Servicio Murciano de Salud", "Es un programa de la semFYC que establece qué actividades preventivas realizar según la edad, pero no es una norma legal", "Es una estrategia del Ministerio de Sanidad aprobada en 2013"], "a": 2, "e": "El Programa de Actividades Preventivas y de Promoción de la Salud es un documento de consenso de la semFYC, de referencia en Atención Primaria."}, {"q": "La Estrategia NAOS (2005) se centra en:", "o": ["La prevención del consumo de drogas", "La nutrición, la actividad física y la prevención de la obesidad", "El abordaje de la cronicidad en el anciano", "La salud mental en la adolescencia"], "a": 1, "e": "NAOS: Nutrición, Actividad física y prevención de la Obesidad, con especial atención a la población infantil y juvenil."}, {"q": "NO es un criterio de Wilson y Jungner para implantar un programa de cribado:", "o": ["Que la enfermedad sea un problema de salud importante", "Que exista una fase latente o asintomática reconocible", "Que el tratamiento precoz sea más eficaz que el tardío", "Que el programa se realice como una campaña puntual"], "a": 3, "e": "Además de los anteriores, la prueba debe ser válida, aceptable y coste-efectiva, deben existir recursos para tratar los positivos y el programa debe ser continuo, no puntual."}, {"q": "La sensibilidad de una prueba de cribado se define como:", "o": ["La capacidad de identificar correctamente a los sanos", "La probabilidad de estar sano si la prueba es negativa", "La capacidad de detectar a los enfermos, minimizando los falsos negativos", "El porcentaje de positivos que están enfermos"], "a": 2, "e": "Sensibilidad = detecta a los enfermos (evita falsos negativos); especificidad = identifica a los sanos (evita falsos positivos). Un buen cribado debe ser muy sensible."}, {"q": "La escala de valoración del riesgo de úlceras por presión que incluye específicamente la fricción y el cizallamiento es:", "o": ["Norton", "Downton", "Tinetti", "Braden"], "a": 3, "e": "Norton y Braden valoran el riesgo de UPP; Braden incluye la subescala de fricción y cizallamiento. Downton valora el riesgo de caídas y Tinetti la marcha y el equilibrio."}, {"q": "El MEC de Lobo es:", "o": ["La adaptación española del Mini-Mental State Examination para el cribado cognitivo", "Una escala de riesgo de caídas", "Un cuestionario de consumo de alcohol", "Una escala de depresión geriátrica"], "a": 0, "e": "El Mini Examen Cognoscitivo de Lobo es la versión española del Mini-Mental (35 puntos frente a los 30 del original)."}, {"q": "¿Cuál de los siguientes diagnósticos enfermeros está correctamente formulado?", "o": ["Riesgo de caídas r/c consumo de benzodiacepinas m/p fractura de cadera", "Riesgo de caídas r/c deterioro de la movilidad y consumo de benzodiacepinas", "Riesgo de caídas m/p inestabilidad en la marcha", "Caídas r/c riesgo de caídas"], "a": 1, "e": "Los diagnósticos de riesgo solo incluyen factores de riesgo (r/c); nunca llevan \"manifestado por\", porque el problema todavía no existe."}, {"q": "Un paciente inmovilizado obtiene una puntuación de alto riesgo en la escala de Norton. El diagnóstico NANDA prioritario es:", "o": ["Deterioro de la integridad cutánea m/p úlcera", "Riesgo de deterioro de la integridad cutánea", "Riesgo de caídas", "Deterioro de la movilidad física"], "a": 1, "e": "Norton valora el riesgo de UPP; si el riesgo es alto, el diagnóstico es de riesgo, sin manifestaciones, porque aún no hay lesión."}, {"q": "En los países desarrollados, la primera causa de mortalidad en niños a partir del primer año de vida son:", "o": ["Los accidentes o lesiones no intencionadas", "Las enfermedades infecciosas", "El cáncer infantil", "Las malformaciones congénitas"], "a": 0, "e": "Tráfico, ahogamientos, caídas, intoxicaciones y quemaduras. Por eso la educación para prevenir accidentes debe hacerse en cada contacto con la familia."}, {"q": "El principal factor protector frente a la obesidad infantil desde el nacimiento es:", "o": ["La introducción precoz de cereales", "La lactancia artificial enriquecida", "La lactancia materna", "La suplementación con vitamina D"], "a": 2, "e": "La lactancia materna está demostrada como el principal factor protector frente a la obesidad infantil."}, {"q": "Respecto al sueño y la obesidad infantil, es correcto que:", "o": ["Dormir menos aumenta el gasto calórico y protege de la obesidad", "El sueño no tiene relación con el peso", "Solo influye en adolescentes", "El déficit de sueño es un factor de riesgo de obesidad infantil"], "a": 3, "e": "Dormir menos de lo recomendado altera las hormonas del apetito y aumenta la fatiga diurna, lo que favorece la obesidad."}, {"q": "La OMS recomienda lactancia materna exclusiva durante:", "o": ["Los primeros 3 meses", "Los primeros 4 meses", "El primer año completo", "Los primeros 6 meses"], "a": 3, "e": "Exclusiva durante 6 meses y complementada al menos hasta los 2 años o hasta que madre e hijo lo deseen."}, {"q": "La droga ilegal más consumida por los adolescentes en España es:", "o": ["La cocaína", "El cannabis", "El éxtasis", "Los hipnosedantes"], "a": 1, "e": "El alcohol es la sustancia (legal) más consumida; el cannabis, la droga ilegal más consumida."}, {"q": "El término binge drinking se refiere a:", "o": ["El consumo intensivo de alcohol en un periodo corto de tiempo", "El consumo diario de pequeñas cantidades de alcohol", "La abstinencia total de alcohol", "El consumo de bebidas energéticas"], "a": 0, "e": "Es el \"atracón\" de alcohol, típico del botellón, el patrón de riesgo más preocupante en adolescentes."}, {"q": "Ante un adolescente de 16 años que consume cannabis, la técnica de comunicación más adecuada es:", "o": ["Prohibirle el consumo de forma directiva", "Informar inmediatamente a sus padres", "La entrevista motivacional", "Juzgar su conducta para que tome conciencia"], "a": 2, "e": "En la adolescencia funcionan los enfoques no directivos, confidenciales y basados en la autonomía, como la entrevista motivacional."}, {"q": "La recomendación de actividad física de la OMS para adultos es de al menos:", "o": ["30 minutos semanales de actividad moderada", "60 minutos semanales de actividad vigorosa", "150 minutos semanales de actividad moderada o 75 minutos de actividad vigorosa", "300 minutos diarios de actividad ligera"], "a": 2, "e": "Al menos 150 minutos semanales de actividad moderada, 75 de vigorosa o una combinación equivalente."}, {"q": "La medida antropométrica más predictiva del riesgo cardiovascular por obesidad central es:", "o": ["El perímetro abdominal", "El IMC", "El peso", "La talla"], "a": 0, "e": "El perímetro abdominal refleja la obesidad visceral, mayor predictor de riesgo metabólico y cardiovascular que el IMC."}, {"q": "La tabla de riesgo cardiovascular que es la adaptación de Framingham calibrada para la población española es:", "o": ["SCORE", "AUDIT", "Downton", "REGICOR"], "a": 3, "e": "REGICOR (Girona) adapta Framingham a la población española; SCORE estima la mortalidad cardiovascular a 10 años en Europa."}, {"q": "El cuestionario AUDIT se utiliza en Atención Primaria para el cribado de:", "o": ["La depresión", "El consumo de riesgo de alcohol", "El deterioro cognitivo", "El riesgo de caídas"], "a": 1, "e": "El AUDIT (y su versión corta AUDIT-C) detecta el consumo de riesgo de alcohol; tras él se realiza una intervención breve."}, {"q": "El cribado poblacional del cáncer colorrectal en la cartera común del SNS consiste en:", "o": ["Test de sangre oculta en heces cada 2 años entre los 50 y los 69 años", "Colonoscopia anual desde los 40 años", "Tacto rectal anual a partir de los 50 años", "Marcadores tumorales cada 5 años"], "a": 0, "e": "La enfermera tiene un papel clave en la captación, entrega y recogida del test de sangre oculta en heces, bienal entre los 50 y los 69 años."}, {"q": "En España no existe un programa de cribado poblacional del cáncer de próstata principalmente por:", "o": ["Su baja frecuencia en varones", "La falta de tratamiento eficaz", "El alto riesgo de sobrediagnóstico y sobretratamiento", "La inexistencia de una prueba disponible"], "a": 2, "e": "El cribado con PSA es controvertido: detecta muchos tumores que no causarían daño y lleva a tratamientos innecesarios."}, {"q": "El principal factor predictor de que un anciano sufra una caída es:", "o": ["Vivir en una zona rural", "El sexo masculino", "Tener una dieta pobre en calcio", "Haber sufrido una caída previa"], "a": 3, "e": "La caída previa es el mejor predictor. Otros factores son la sarcopenia, los déficits sensoriales, el deterioro cognitivo, las benzodiacepinas y el entorno."}, {"q": "En geriatría se considera polimedicación el consumo simultáneo de:", "o": ["2 o más fármacos", "5 o más fármacos", "8 o más fármacos", "10 o más fármacos"], "a": 1, "e": "El punto de corte habitual es 5 o más medicamentos. Los criterios STOPP/START ayudan a detectar prescripciones inadecuadas."}, {"q": "Un anciano hospitalizado se desorienta y se agita por la noche. La primera medida de enfermería es:", "o": ["Orientarle, ponerle sus gafas y audífonos, iluminar la habitación y facilitar el acompañamiento familiar", "Administrar haloperidol de forma inmediata", "Aplicar contención mecánica", "Administrar una benzodiacepina"], "a": 0, "e": "La prevención y el manejo inicial del delirium son no farmacológicos: orientación, corrección de déficits sensoriales, sueño, hidratación y movilización."}, {"q": "El instrumento considerado de referencia para valorar el estado nutricional del anciano es:", "o": ["La escala de Yesavage", "El test de Pfeiffer", "La escala de Tinetti", "El MNA (Mini Nutritional Assessment)"], "a": 3, "e": "El MNA valora IMC, pérdida de peso, movilidad y estrés agudo. Yesavage es para depresión, Pfeiffer para cognición y Tinetti para marcha y equilibrio."}]},
17: {"tema": 17, "titulo": "Inmunizaciones. Tipos de vacunas, contraindicaciones, complicaciones, conservación, administración y calendario", "programa": "Inmunizaciones: concepto, inmunidad activa, pasiva y de grupo. Clasificación y tipos de vacunas. Contraindicaciones verdaderas y falsas. Complicaciones y efectos adversos, anafilaxia. Conservación y cadena de frío. Administración, vías, analgesia e intervalos. Calendario de vacunaciones de la Región de Murcia 2025-2026, adultos, grupos de riesgo, personal sanitario y profilaxis antitetánica.", "preguntas": [{"q": "La única enfermedad humana declarada erradicada por la OMS mediante la vacunación es:", "o": ["La poliomielitis", "El sarampión", "La viruela", "La difteria"], "a": 2, "e": "La viruela fue declarada erradicada en 1980. La polio y el sarampión están eliminados en algunas regiones, pero el agente persiste en el mundo."}, {"q": "La administración de nirsevimab a lactantes frente al virus respiratorio sincitial es un ejemplo de:", "o": ["Inmunización pasiva artificial con un anticuerpo monoclonal", "Inmunización activa artificial con una vacuna viva", "Inmunización activa natural", "Inmunización pasiva natural"], "a": 0, "e": "El nirsevimab aporta anticuerpos ya formados: protección inmediata pero temporal, sin memoria inmunológica."}, {"q": "¿Cuál de las siguientes es una vacuna viva atenuada?", "o": ["Hepatitis B", "Virus del papiloma humano", "Tdpa", "Triple vírica"], "a": 3, "e": "Son vivas atenuadas la triple vírica, la varicela, el rotavirus oral, la fiebre amarilla, la gripe intranasal, la BCG y la tifoidea oral. Hepatitis B y VPH son recombinantes; la Tdpa contiene toxoides y fracciones."}, {"q": "Administrar la vacuna antineumocócica polisacarídica de 23 serotipos (VNP23) a un lactante de 6 meses:", "o": ["Es la opción de elección por tener más serotipos", "Es ineficaz, porque los polisacáridos inducen una respuesta T-independiente a la que no responden los menores de 2 años", "Produce una memoria inmunológica más duradera", "Está indicada en lugar de la conjugada"], "a": 1, "e": "En menores de 2 años deben usarse vacunas conjugadas (VNC13, VNC20), que convierten la respuesta en T-dependiente y generan memoria."}, {"q": "Durante el embarazo se recomienda administrar en cada gestación:", "o": ["La vacuna Tdpa entre las semanas 27 y 36", "La triple vírica en el primer trimestre", "La vacuna de la varicela", "La vacuna intranasal de la gripe"], "a": 0, "e": "La Tdpa en cada embarazo transfiere anticuerpos frente a la tos ferina al recién nacido. También se recomienda la gripe inyectable. Las vacunas vivas están contraindicadas."}, {"q": "Es una contraindicación permanente para el componente de tos ferina:", "o": ["Fiebre de 38,5 °C tras una dosis previa", "Una reacción local extensa previa", "Una encefalopatía aparecida a los 15 días de la vacuna", "Una encefalopatía de causa no filiada en los 7 días siguientes a una dosis"], "a": 3, "e": "La encefalopatía no filiada en los 7 días posteriores contraindica de forma permanente el componente pertúsico; las dosis siguientes se ponen con Td."}, {"q": "Un lactante de 2 meses acude a vacunarse con catarro, 37,5 °C y tratamiento con amoxicilina. La actuación correcta es:", "o": ["Posponer todas las vacunas hasta que acabe el antibiótico", "Administrar solo las vacunas inactivadas", "Vacunar según el calendario, porque no son contraindicaciones", "Esperar a que tenga 3 meses"], "a": 2, "e": "La infección leve con temperatura inferior a 38 °C y los antibióticos son falsas contraindicaciones. Posponer sería una oportunidad perdida."}, {"q": "Respecto a la alergia al huevo y la vacunación, es correcto que:", "o": ["Contraindica la triple vírica", "No contraindica la triple vírica ni la gripe; la vacuna que exige precaución especial es la de la fiebre amarilla", "Contraindica todas las vacunas inactivadas", "Obliga a vacunar siempre en el hospital"], "a": 1, "e": "La triple vírica y la gripe se administran en el centro de salud con la observación habitual. La fiebre amarilla contiene más ovoalbúmina y requiere precaución."}, {"q": "Un niño asmático en tratamiento diario con fluticasona inhalada debe recibir la vacuna de la varicela. Se debe:", "o": ["Vacunar con normalidad, porque los corticoides inhalados no son inmunosupresores sistémicos", "Suspender el inhalador 1 mes antes", "Contraindicar la vacuna de forma permanente", "Administrar inmunoglobulina antes de vacunar"], "a": 0, "e": "Solo contraindican las vacunas vivas los corticoides sistémicos a dosis altas (≥ 2 mg/kg/día o ≥ 20 mg/día de prednisona) durante 14 días o más."}, {"q": "Tras la administración reciente de inmunoglobulinas o hemoderivados:", "o": ["Deben retrasarse todas las vacunas inactivadas", "Puede administrarse la triple vírica de inmediato", "Debe retrasarse la triple vírica o la varicela entre 3 y 11 meses según el producto", "Está contraindicada la vacuna oral del rotavirus"], "a": 2, "e": "Los anticuerpos administrados neutralizan los virus vacunales vivos inyectables. No afecta a las inactivadas ni al rotavirus oral."}, {"q": "Tras la vacuna triple vírica, la fiebre y el exantema atribuibles a la vacuna aparecen típicamente:", "o": ["En las primeras 6 horas", "En las primeras 48 horas", "Al mes de la vacunación", "Entre el 5.º y el 12.º día"], "a": 3, "e": "Las vacunas vivas necesitan replicarse, por lo que la fiebre es tardía. La fiebre en las primeras 48 horas es típica de las inactivadas."}, {"q": "La reacción de Arthus tras la vacunación es:", "o": ["Una reacción de hipersensibilidad tipo I inmediata", "Una reacción de hipersensibilidad tipo III por inmunocomplejos, a las 4-12 horas, tras dosis repetidas de toxoide tetánico o diftérico", "Una reacción tardía tipo IV a los 7 días", "Un síncope vasovagal"], "a": 1, "e": "Produce edema y eritema extensos, es autolimitada y obliga a espaciar las dosis futuras de tétanos."}, {"q": "El tratamiento de primera elección de una anafilaxia tras una vacuna en el centro de salud es:", "o": ["Un antihistamínico oral", "Un corticoide intravenoso", "Adrenalina 1:1000 por vía intramuscular en la cara anterolateral del muslo", "Adrenalina en bolo intravenoso"], "a": 2, "e": "La adrenalina IM en el vasto externo es el tratamiento de elección; la vía IV directa está proscrita en AP por riesgo de arritmias. Antihistamínicos y corticoides van después."}, {"q": "La dosis de adrenalina 1:1000 en la anafilaxia pediátrica es:", "o": ["0,01 mg/kg (0,01 ml/kg), con un máximo de 0,5 mg por dosis", "0,1 mg/kg, con un máximo de 1 mg", "1 mg fijo en todos los niños", "0,5 mg/kg, con un máximo de 5 mg"], "a": 0, "e": "Puede repetirse cada 5-15 minutos si no hay mejoría. Si el paciente toma betabloqueantes y no responde, se usa glucagón."}, {"q": "Una adolescente se marea tras la vacuna del VPH: está pálida, sudorosa, con bradicardia, y se recupera al tumbarla con las piernas elevadas. Se trata de:", "o": ["Una anafilaxia", "Un síncope vasovagal", "Una reacción de Arthus", "Una crisis epiléptica"], "a": 1, "e": "La anafilaxia cursa con taquicardia, urticaria, angioedema o broncoespasmo y requiere adrenalina; el síncope se resuelve con medidas posturales."}, {"q": "El rango de temperatura de conservación de la mayoría de las vacunas es:", "o": ["De −20 a −10 °C", "De 0 a +4 °C", "De +8 a +15 °C", "De +2 a +8 °C"], "a": 3, "e": "El punto ideal es +5 °C. Se considera rotura de la cadena de frío cualquier registro inferior a +2 °C o superior a +8 °C."}, {"q": "Ante una rotura de la cadena de frío en el frigorífico del centro de salud, la enfermera debe:", "o": ["Poner las vacunas en cuarentena, mantenerlas entre +2 y +8 °C y notificarlo a Salud Pública", "Desechar inmediatamente todas las vacunas", "Seguir usando las vacunas si el frigorífico vuelve a enfriar", "Desechar solo las vacunas vivas"], "a": 0, "e": "La enfermera no desecha las vacunas por su cuenta: Salud Pública, con el laboratorio, decide si se destruyen o son válidas."}, {"q": "En la organización del frigorífico de vacunas es correcto:", "o": ["Guardar las vacunas más usadas en la puerta", "Almacenar junto a las vacunas muestras analíticas", "No colocar nunca vacunas en la puerta y dejar espacio entre las cajas y las paredes", "Sacar los viales de su envase para ahorrar espacio"], "a": 2, "e": "La puerta sufre las mayores oscilaciones térmicas. Además, las vacunas vivas liofilizadas son fotosensibles y deben permanecer en su envase opaco."}, {"q": "Las vacunas que se inutilizan sobre todo por la congelación son:", "o": ["La triple vírica y la varicela", "La BCG", "La vacuna oral del rotavirus", "Las inactivadas con adyuvante de aluminio, como la hexavalente"], "a": 3, "e": "La congelación hace precipitar el adyuvante de aluminio y destruye la vacuna (se valora con la prueba de agitación). Las vivas son más sensibles al calor y a la luz."}, {"q": "En un lactante de 10 meses, el lugar de elección para administrar una vacuna intramuscular es:", "o": ["El glúteo", "El vasto externo (tercio medio de la cara anterolateral del muslo)", "El deltoides", "La región ventroglútea exclusivamente"], "a": 1, "e": "En menores de 1-2 años se usa el vasto externo; el glúteo está desaconsejado (grasa abundante y riesgo de lesión del ciático). En niños mayores y adultos, el deltoides."}, {"q": "Respecto a la aspiración al administrar una vacuna intramuscular en el deltoides o el vasto externo:", "o": ["Es obligatorio aspirar 5 segundos", "No se recomienda aspirar: la inyección debe ser rápida", "Solo se aspira en lactantes", "Se aspira solo con vacunas vivas"], "a": 1, "e": "En esas zonas no hay grandes vasos; aspirar prolonga la permanencia de la aguja y aumenta el dolor sin aportar seguridad."}, {"q": "Si dos vacunas vivas atenuadas parenterales (triple vírica y varicela) no se administran el mismo día, deben separarse al menos:", "o": ["4 semanas", "1 semana", "2 semanas", "6 meses"], "a": 0, "e": "Si la segunda se pone antes de 28 días no se considera válida. El periodo de gracia de 4 días no se aplica a este intervalo."}, {"q": "Un adulto recibió hace 10 años dos dosis de vacuna de hepatitis B y nunca recibió la tercera. La actuación correcta es:", "o": ["Reiniciar la pauta completa de 3 dosis", "Hacer una serología y, si es negativa, reiniciar", "No vacunar, porque ya está protegido", "Administrar solo la dosis que falta"], "a": 3, "e": "Regla \"dosis puesta, dosis que cuenta\": las pautas nunca se reinician, solo se completan."}, {"q": "Respecto a la vacuna frente al rotavirus, es correcto que:", "o": ["Se administra por vía intramuscular a los 12 meses", "Es una vacuna inactivada", "Es oral y la primera dosis no debe darse después de las 14 semanas y 6 días de vida", "Puede iniciarse a cualquier edad en la infancia"], "a": 2, "e": "Es una vacuna viva atenuada oral. Iniciarla tarde aumenta el riesgo de invaginación intestinal."}, {"q": "La vacuna hexavalente protege frente a:", "o": ["Difteria, tétanos, tos ferina, poliomielitis, Haemophilus influenzae tipo b y hepatitis B", "Sarampión, rubeola, parotiditis, varicela, polio y hepatitis A", "Difteria, tétanos, tos ferina, neumococo, meningococo C y hepatitis B", "Difteria, tétanos, polio, rotavirus, Hib y hepatitis A"], "a": 0, "e": "Se administra a los 2, 4 y 11 meses (pauta 2 + 1)."}, {"q": "Un recién nacido de 3,5 kg debe recibir nirsevimab al inicio de la temporada de VRS. La dosis correcta es:", "o": ["200 mg IM", "100 mg IM", "25 mg IM", "50 mg IM"], "a": 3, "e": "Peso inferior a 5 kg: 50 mg; peso igual o superior a 5 kg: 100 mg."}, {"q": "Según el calendario de la Región de Murcia 2025-2026, la vacunación frente al VPH en inmunocompetentes es:", "o": ["Solo en chicas, con 3 dosis a los 14 años", "Solo en chicas, con 2 dosis a los 12 años", "En chicas y chicos, con una dosis única a los 12 años", "En adultos de 25 años con 2 dosis"], "a": 2, "e": "Se vacuna de forma sistemática a ambos sexos con pauta de dosis única; los inmunodeprimidos reciben 3 dosis."}, {"q": "Respecto a la vacuna frente al herpes zóster Shingrix, es correcto que:", "o": ["Es viva atenuada y está contraindicada en inmunodeprimidos", "Es recombinante adyuvada: se administran 2 dosis IM separadas al menos 2 meses y puede usarse en inmunodeprimidos", "Se administra en dosis única subcutánea", "Solo está indicada en menores de 50 años"], "a": 1, "e": "A diferencia de la antigua Zostavax (viva), Shingrix es inactivada y segura en inmunodepresión. En Murcia se capta a las cohortes de 65 y 80 años."}, {"q": "Tras completar la vacunación de hepatitis B, un profesional sanitario debe hacerse una serología para confirmar la inmunidad, que se considera adecuada si:", "o": ["Anti-HBs ≥ 10 mUI/ml entre 1 y 2 meses tras la última dosis", "HBsAg positivo al mes", "Anti-HBc positivo a los 6 meses", "Anti-HBs ≥ 1 mUI/ml a los 5 años"], "a": 0, "e": "La pauta es de 0, 1 y 6 meses, con control de anti-HBs 1-2 meses después de la última dosis."}, {"q": "Un paciente con estado vacunal antitetánico desconocido acude con una herida punzante contaminada con tierra. La profilaxis correcta es:", "o": ["No hacer nada si la herida se limpia bien", "Solo inmunoglobulina antitetánica", "Solo una dosis de vacuna Td", "Vacuna Td e inmunoglobulina antitetánica 250 UI en lugares anatómicos distintos"], "a": 3, "e": "En heridas tetanígenas con menos de 3 dosis o estado desconocido se combinan vacuna e IGT. En una herida limpia y menor basta la vacuna, sin IGT."}]},
18: {"tema": 18, "titulo": "Higiene en centros sanitarios. Antisépticos, desinfectantes y esterilización", "programa": "Higiene en centros sanitarios: conceptos generales, clasificación de Spaulding e higiene de manos. Antisépticos y desinfectantes. El servicio de esterilización. Preparación y tipos de material a esterilizar, métodos de esterilización y controles. Manipulación y conservación del material estéril.", "preguntas": [{"q": "La esterilización se define como el proceso que:", "o": ["Elimina la suciedad visible por arrastre", "Destruye los microorganismos en fase vegetativa sobre objetos inertes", "Reduce la flora de los tejidos vivos", "Destruye todas las formas de vida microbiana, incluidas las esporas"], "a": 3, "e": "La limpieza arrastra la suciedad, la desinfección destruye las formas vegetativas (sin garantizar las esporas) y la antisepsia actúa sobre tejidos vivos."}, {"q": "El nivel de aseguramiento de la esterilidad (SAL) exigido para considerar estéril un material es una probabilidad de microorganismo viable igual o inferior a:", "o": ["1 entre un millón (10⁻⁶)", "1 entre mil (10⁻³)", "1 entre cien (10⁻²)", "1 entre diez mil (10⁻⁴)"], "a": 0, "e": "La esterilidad se define de forma probabilística: SAL ≤ 10⁻⁶."}, {"q": "La aplicación de clorhexidina sobre la piel del paciente antes de canalizar una vía es un ejemplo de:", "o": ["Desinfección", "Antisepsia", "Esterilización", "Asepsia quirúrgica"], "a": 1, "e": "Antisepsia es la reducción microbiana sobre tejidos vivos con antisépticos. La desinfección se aplica a objetos inertes."}, {"q": "Según la clasificación de Spaulding, un endoscopio flexible (gastroscopio) es material:", "o": ["Crítico, que requiere esterilización en autoclave", "No crítico, que requiere limpieza", "Semicrítico, que requiere como mínimo desinfección de alto nivel", "Crítico, que requiere desinfección de bajo nivel"], "a": 2, "e": "Contacta con mucosas intactas y es termosensible, por lo que se procesa con desinfección de alto nivel."}, {"q": "Según Spaulding, una sonda vesical es material:", "o": ["No crítico", "Semicrítico", "Crítico", "De uso doméstico"], "a": 2, "e": "Penetra en una cavidad estéril (vejiga), por lo que debe ser estéril."}, {"q": "Respecto a la flora residente de la piel, es correcto que:", "o": ["Se elimina completamente con agua y jabón común", "Está formada por microorganismos como Staphylococcus epidermidis y solo se reduce con antisépticos", "Es la principal causa de infección cruzada", "Se adquiere al tocar superficies contaminadas"], "a": 1, "e": "La flora transitoria (adquirida por contacto) es la principal vía de infección cruzada y se elimina con agua y jabón; la residente vive en capas profundas."}, {"q": "Tras atender a un paciente con diarrea por Clostridioides difficile, la higiene de manos debe hacerse con:", "o": ["Agua y jabón", "Solución hidroalcohólica", "Alcohol de 96°", "Clorhexidina alcohólica sin agua"], "a": 0, "e": "El alcohol no inactiva las esporas; hay que eliminarlas mediante arrastre mecánico con agua y jabón."}, {"q": "La duración recomendada de la higiene de manos por fricción con solución hidroalcohólica es de:", "o": ["5 segundos", "40-60 segundos", "3-5 minutos", "20-30 segundos"], "a": 3, "e": "Fricción: 20-30 s hasta que seque al aire; lavado higiénico con agua y jabón: 40-60 s; lavado quirúrgico: 3-5 min."}, {"q": "Una enfermera ajusta la barandilla de la cama sin tocar al paciente. Según la OMS, debe realizar la higiene de manos porque corresponde al momento:", "o": ["Después del contacto con el entorno del paciente", "Antes de una tarea aséptica", "Antes del contacto con el paciente", "Después del riesgo de exposición a fluidos"], "a": 0, "e": "El quinto momento incluye tocar objetos del entorno inmediato del paciente aunque no se le toque a él."}, {"q": "Respecto al lavado quirúrgico de manos con agua y antiséptico, es correcto que:", "o": ["Dura 20-30 segundos", "Dura 3-5 minutos, con clorhexidina jabonosa al 4% o povidona al 7,5%, manteniendo las manos por encima de los codos", "Debe hacerse con cepillo duro en toda la piel", "Se secan las manos con aire caliente"], "a": 1, "e": "El cepillo solo se usa para uñas y espacios interdigitales; el secado se hace con compresa estéril de la mano al codo."}, {"q": "El antiséptico de elección para preparar la piel antes de insertar un catéter venoso central es:", "o": ["Povidona yodada acuosa al 10%", "Alcohol de 96°", "Clorhexidina alcohólica al 2%", "Agua oxigenada al 3%"], "a": 2, "e": "La clorhexidina alcohólica (> 0,5%, habitualmente 2%) actúa rápido y tiene efecto residual prolongado, por lo que supera a la povidona (proyecto Bacteriemia Zero)."}, {"q": "La clorhexidina está contraindicada en:", "o": ["La preparación de la piel antes de una vía periférica", "El lavado quirúrgico de manos", "El cuidado del cordón umbilical", "El oído con tímpano perforado y el contacto con meninges o tejido nervioso"], "a": 3, "e": "Es ototóxica si llega al oído medio y neurotóxica en contacto con el sistema nervioso central."}, {"q": "Respecto a la povidona yodada, es correcto que:", "o": ["Tiene un efecto residual superior a 24 horas", "Mantiene su actividad en presencia de sangre", "Es el antiséptico de elección en prematuros", "Necesita 2-3 minutos de secado para actuar y se inactiva con materia orgánica"], "a": 3, "e": "Si se pincha con la piel aún húmeda no ha actuado. Se evita en neonatos, embarazo, lactancia y tiroidopatías por la absorción de yodo."}, {"q": "La concentración de alcohol etílico más eficaz como antiséptico es:", "o": ["70%", "96%", "100%", "30%"], "a": 0, "e": "La desnaturalización proteica necesita agua; el alcohol puro deshidrata la pared sin matar eficazmente. Su efecto residual es nulo."}, {"q": "Para limpiar una úlcera profunda tunelizada, la irrigación a presión con agua oxigenada al 3%:", "o": ["Es la técnica de elección por su efecto mecánico", "Es adecuada si se diluye al 50%", "Está contraindicada por el riesgo de enfisema y embolia gaseosa", "Solo se permite en heridas infectadas por anaerobios"], "a": 2, "e": "La catalasa libera oxígeno de forma rápida; en cavidades cerradas el gas no encuentra salida."}, {"q": "¿Cuál de los siguientes microorganismos es el más fácil de destruir mediante desinfección química?", "o": ["Las esporas de Clostridioides difficile", "Los virus con envoltura lipídica, como el VIH", "Mycobacterium tuberculosis", "Los norovirus (virus sin envoltura)"], "a": 1, "e": "Escala de resistencia: priones > esporas > micobacterias > virus sin envoltura > hongos > bacterias vegetativas > virus con envoltura."}, {"q": "Para que un desinfectante se considere de nivel intermedio debe ser eficaz frente a:", "o": ["Mycobacterium tuberculosis", "Las esporas bacterianas", "Los priones", "Solo las bacterias vegetativas"], "a": 0, "e": "El nivel intermedio es tuberculocida pero no esporicida; el bajo no actúa frente a micobacterias ni esporas."}, {"q": "La inmersión de una hoja de laringoscopio en glutaraldehído al 2% durante 20 minutos consigue:", "o": ["Su esterilización química", "Una desinfección de alto nivel, pero no su esterilización", "Una desinfección de bajo nivel", "Solo su limpieza"], "a": 1, "e": "El glutaraldehído al 2% necesita 10-12 horas de inmersión para ser esporicida (esterilizante)."}, {"q": "Tras sumergir un endoscopio en ortoftalaldehído (OPA), sus canales se tiñen de color gris. Esto indica:", "o": ["Un defecto de fabricación", "Que el OPA está caducado", "Que la limpieza previa fue deficiente y quedaban restos de proteínas", "Que la temperatura era excesiva"], "a": 2, "e": "El OPA tiñe las proteínas residuales, por lo que pone en evidencia una limpieza mecánica insuficiente."}, {"q": "Para desinfectar un derrame de sangre en una superficie se recomienda hipoclorito sódico a:", "o": ["100 ppm", "500 ppm", "1.000 ppm", "10.000 ppm"], "a": 3, "e": "1.000 ppm es la dilución para superficies limpias de rutina; los derrames de fluidos biológicos requieren 10.000 ppm, en agua fría."}, {"q": "En la Unidad Central de Esterilización, la zona sucia de lavado debe mantenerse con:", "o": ["Presión positiva respecto a las zonas adyacentes", "La misma presión que la zona estéril", "Presión negativa respecto a las zonas adyacentes", "Las ventanas abiertas para ventilar"], "a": 2, "e": "El aire va de lo limpio a lo sucio: la zona sucia en negativa evita que salgan aerosoles; las zonas limpia y estéril están en positiva."}, {"q": "La limpieza por ultrasonidos del instrumental se basa en:", "o": ["El fenómeno de cavitación", "La alquilación de proteínas", "La oxidación por radicales libres", "La radiación gamma"], "a": 0, "e": "Las burbujas microscópicas implosionan sobre el instrumental y arrancan la suciedad. No se usa en ópticas, endoscopios flexibles ni motores."}, {"q": "Los parámetros habituales de esterilización por vapor en autoclave son:", "o": ["170 °C durante 1 hora", "134 °C durante 3-5 minutos o 121 °C durante 15-20 minutos", "55 °C durante 12 horas", "90 °C durante 1 minuto"], "a": 1, "e": "El vapor es el método de elección para el material que tolera el calor. 170 °C durante 1 hora corresponde al calor seco."}, {"q": "Para el instrumental empleado en un paciente con sospecha de enfermedad de Creutzfeldt-Jakob, el ciclo de autoclave recomendado es:", "o": ["121 °C durante 15 minutos", "134 °C durante 3 minutos", "Óxido de etileno a 37 °C", "134 °C durante al menos 18 minutos en autoclave de prevacío"], "a": 3, "e": "Los priones son las estructuras más resistentes y requieren un ciclo prolongado específico."}, {"q": "En la esterilización por plasma de peróxido de hidrógeno está prohibido introducir:", "o": ["Material de celulosa (papel, algodón, gasas, lino)", "Material plástico termosensible", "Envoltorios de Tyvek", "Instrumental metálico"], "a": 0, "e": "La celulosa absorbe el peróxido y aborta el ciclo; se usan envoltorios sintéticos (Tyvek o polipropileno)."}, {"q": "Respecto a la esterilización con óxido de etileno, es correcto que:", "o": ["El material puede usarse inmediatamente al terminar el ciclo", "Funciona a 134 °C", "Requiere un periodo de aireación de al menos 10-12 horas por su toxicidad", "No necesita humedad"], "a": 2, "e": "Es tóxico, cancerígeno y explosivo; los plásticos absorben el gas, por lo que hay que desgasificarlos antes de usarlos."}, {"q": "El test de Bowie-Dick:", "o": ["Certifica la esterilidad de cada paquete", "Evalúa la extracción del aire y la penetración del vapor en el autoclave de prevacío; se hace a diario con la cámara vacía", "Es un indicador biológico con esporas", "Se coloca en el centro del paquete más grande de la carga"], "a": 1, "e": "Es un indicador químico de clase 2. Se hace antes del primer ciclo del día, en la cámara vacía, en el fondo sobre el desagüe."}, {"q": "El indicador biológico utilizado para validar la esterilización por vapor en autoclave contiene esporas de:", "o": ["Bacillus atrophaeus", "Clostridioides difficile", "Staphylococcus aureus", "Geobacillus stearothermophilus"], "a": 3, "e": "Geobacillus stearothermophilus: vapor, plasma y formaldehído. Bacillus atrophaeus: óxido de etileno y calor seco."}, {"q": "Tras incubar un indicador biológico de un ciclo de autoclave, el medio vira de morado a amarillo. Esto significa que:", "o": ["El ciclo ha fallado porque han sobrevivido esporas y el lote no es estéril", "El ciclo ha sido correcto", "El indicador químico está caducado", "Debe repetirse la lectura a las 48 horas sin más medidas"], "a": 0, "e": "En los indicadores químicos se busca el viraje; en los biológicos, que no haya cambio de color. Un positivo obliga a retirar el lote."}, {"q": "Según el concepto de \"esterilidad orientada a eventos\":", "o": ["Todo material estéril caduca a los 30 días", "El material debe reesterilizarse cada semana", "La esterilidad se mantiene indefinidamente aunque el envoltorio esté mojado", "El material deja de ser estéril cuando sufre un evento que daña el envoltorio (rotura, humedad, aplastamiento)"], "a": 3, "e": "La esterilidad no se pierde por el mero paso del tiempo, sino por eventos. Se aplica además el sistema FIFO en el almacén."}]},
19: {"tema": 19, "titulo": "Infección nosocomial y aislamiento hospitalario. Gestión de residuos sanitarios. Salud medioambiental", "programa": "Infección nosocomial: concepto, cadena epidemiológica y epidemiología (EPINE). Medidas preventivas: precauciones estándar, EPI, higiene de manos y proyectos Zero. Aislamiento hospitalario: concepto, tipos y descripción. Gestión de residuos sanitarios: clasificación y transporte; gestión integral de residuos sanitarios de la Región de Murcia. Salud medioambiental: condicionantes biológicos, físicos y socioculturales.", "preguntas": [{"q": "Un paciente ingresado por una fractura presenta fiebre y síntomas urinarios a las 36 horas del ingreso. La infección se clasifica como:", "o": ["Nosocomial, porque el paciente ya está ingresado", "Comunitaria, porque aparece antes de las 48 horas del ingreso", "Ocupacional", "Nosocomial asociada a dispositivo en todos los casos"], "a": 1, "e": "Se considera nosocomial la que se manifiesta a partir de las 48-72 horas del ingreso; antes se asume que estaba en incubación al ingresar."}, {"q": "Una infección de localización quirúrgica, en una intervención sin implante, se considera relacionada con la cirugía si aparece dentro de:", "o": ["Las 48 horas siguientes", "Los 7 días siguientes", "Los 6 meses siguientes", "Los 30 días siguientes"], "a": 3, "e": "El periodo es de 30 días; si se ha colocado una prótesis o implante, el periodo de vigilancia se amplía."}, {"q": "El eslabón de la cadena epidemiológica más vulnerable y sobre el que se actúa con mayor eficacia para prevenir las IRAS es:", "o": ["El mecanismo de transmisión", "La susceptibilidad del huésped", "El reservorio", "El agente etiológico"], "a": 0, "e": "La transmisión se interrumpe de forma sencilla y coste-efectiva, sobre todo con la higiene de manos."}, {"q": "El estudio EPINE es:", "o": ["Un ensayo clínico aleatorizado sobre antisépticos", "Un estudio de cohortes de pacientes quirúrgicos", "Un estudio transversal de prevalencia de las infecciones nosocomiales en España", "Un registro de enfermedades de declaración obligatoria"], "a": 2, "e": "Lo coordina anualmente la Sociedad Española de Medicina Preventiva, Salud Pública e Higiene."}, {"q": "El microorganismo aislado con mayor frecuencia en las infecciones nosocomiales según el EPINE es:", "o": ["Escherichia coli", "Pseudomonas aeruginosa", "Staphylococcus aureus resistente a meticilina", "Candida albicans"], "a": 0, "e": "E. coli es el más frecuente, sobre todo en infecciones urinarias y bacteriemias de origen abdominal o urológico."}, {"q": "Las infecciones nosocomiales que asocian mayor letalidad son:", "o": ["Las infecciones urinarias", "Las bacteriemias y las infecciones asociadas a catéter", "Las infecciones de la herida quirúrgica superficial", "Las conjuntivitis"], "a": 1, "e": "Aunque no son las más frecuentes, las bacteriemias tienen la mayor morbimortalidad (sepsis y shock séptico)."}, {"q": "Las precauciones estándar deben aplicarse:", "o": ["Solo a pacientes con infección confirmada", "Solo en las unidades de cuidados intensivos", "Solo a pacientes con VIH o hepatitis", "A todos los pacientes, independientemente de su diagnóstico"], "a": 3, "e": "Se asume que toda sangre, fluido (salvo el sudor), piel no intacta y mucosa pueden transmitir infecciones."}, {"q": "En la retirada del equipo de protección individual, el primer elemento que debe quitarse es:", "o": ["La mascarilla", "La bata", "Los guantes", "Las gafas"], "a": 2, "e": "Se retira primero lo más contaminado (guantes), después gafas y bata, y por último la mascarilla, fuera de la habitación."}, {"q": "En un aislamiento aéreo, el respirador FFP2 del profesional debe retirarse:", "o": ["Lo primero, nada más terminar la atención", "Dentro de la habitación, junto a la cama", "Fuera de la habitación y en último lugar, tras cerrar la puerta", "Antes de quitarse los guantes"], "a": 2, "e": "Así se protege la vía aérea de las partículas suspendidas hasta salir; después, higiene de manos."}, {"q": "Según el proyecto Bacteriemia Zero, en el adulto se debe evitar la inserción de catéteres venosos centrales en la vena:", "o": ["Femoral, siendo de elección la subclavia", "Subclavia, siendo de elección la femoral", "Yugular interna, siendo de elección la femoral", "Basílica en todos los casos"], "a": 0, "e": "La zona inguinal está muy colonizada; la subclavia es la de menor riesgo de infección, seguida de la yugular interna."}, {"q": "Según el proyecto Neumonía Zero, la presión del neumotaponamiento del tubo endotraqueal debe mantenerse entre:", "o": ["5 y 10 cmH₂O", "20 y 30 cmH₂O", "40 y 50 cmH₂O", "60 y 80 cmH₂O"], "a": 1, "e": "Por debajo de 20 cmH₂O se producen microaspiraciones; por encima de 30 cmH₂O, isquemia de la mucosa traqueal."}, {"q": "¿Cuál de las siguientes medidas es INCORRECTA según el proyecto Neumonía Zero?", "o": ["Mantener el cabecero elevado a 30-45°", "Realizar higiene bucal con clorhexidina al 0,12-0,2%", "Reducir la sedación y valorar la extubación precoz", "Cambiar de forma rutinaria las tubuladuras del respirador cada 24 horas"], "a": 3, "e": "Las tubuladuras solo se cambian si están visiblemente sucias o averiadas; los cambios innecesarios abren el circuito."}, {"q": "Según el proyecto ITU Zero, la higiene del meato urinario en un paciente sondado debe realizarse con:", "o": ["Agua y jabón neutro, dentro del aseo diario", "Clorhexidina jabonosa al 4% cada 8 horas", "Povidona yodada al 10% tras cada vaciado", "Alcohol de 70°"], "a": 0, "e": "Los antisépticos de rutina en el meato alteran la flora periuretral y no reducen las infecciones."}, {"q": "La bolsa colectora de una sonda vesical debe colocarse:", "o": ["Por encima del nivel de la vejiga para facilitar el drenaje", "Por debajo del nivel de la vejiga y sin tocar el suelo", "Apoyada en el suelo junto a la cama", "Encima del colchón, junto al paciente"], "a": 1, "e": "Así se evita el reflujo de orina; además, el sistema debe permanecer cerrado y la sonda bien fijada."}, {"q": "Un paciente con sospecha de tuberculosis pulmonar bacilífera requiere aislamiento:", "o": ["De contacto", "Por gotas", "Protector", "Aéreo"], "a": 3, "e": "Sarampión, varicela y tuberculosis (\"SaVaTu\") se transmiten por partículas menores de 5 micras que permanecen suspendidas."}, {"q": "Un paciente con meningitis meningocócica requiere aislamiento:", "o": ["Aéreo", "De contacto", "Por gotas", "Protector"], "a": 2, "e": "Meningococo, Hib, tos ferina, gripe, difteria faríngea o Mycoplasma se transmiten por gotas mayores de 5 micras."}, {"q": "Ante un paciente con diarrea por Clostridioides difficile, son correctos:", "o": ["El aislamiento de contacto y la higiene de manos con agua y jabón", "El aislamiento aéreo con FFP2", "El aislamiento por gotas con mascarilla quirúrgica", "Solo la higiene con solución hidroalcohólica"], "a": 0, "e": "Se transmite por contacto y sus esporas resisten al alcohol, por lo que se requiere arrastre con agua y jabón."}, {"q": "La habitación de aislamiento aéreo debe disponer de:", "o": ["Presión positiva y puerta abierta", "Ventilación estándar y puerta abierta", "Presión positiva con aire HEPA", "Presión negativa, renovaciones de aire suficientes y puerta siempre cerrada"], "a": 3, "e": "La presión negativa impide que el aire contaminado salga al pasillo; el aire se expulsa al exterior o pasa por filtros HEPA."}, {"q": "En el aislamiento por gotas es correcto que:", "o": ["El personal debe usar siempre FFP3", "El personal usa mascarilla quirúrgica y la puerta puede permanecer abierta", "La habitación debe tener presión negativa", "No es necesaria ninguna mascarilla"], "a": 1, "e": "Las gotas caen a 1-1,5 m. Solo en procedimientos generadores de aerosoles se requiere FFP2."}, {"q": "Un paciente en aislamiento aéreo por tuberculosis debe trasladarse a radiología. El paciente debe llevar:", "o": ["Un respirador FFP2 con válvula de exhalación", "Ninguna mascarilla", "Una mascarilla quirúrgica", "Una pantalla facial sin mascarilla"], "a": 2, "e": "La mascarilla quirúrgica contiene las partículas en la fuente; una FFP2 con válvula dejaría salir el aire exhalado sin filtrar."}, {"q": "Respecto al aislamiento protector o inverso, es correcto que:", "o": ["La habitación debe estar en presión negativa", "Se indica en pacientes con tuberculosis", "Se permiten flores naturales para mejorar el ánimo", "La habitación está en presión positiva, se prohíben las plantas y en los traslados el paciente lleva FFP2"], "a": 3, "e": "Protege al paciente inmunodeprimido (neutropenia < 500/mm³, trasplantes, grandes quemados) de los patógenos del entorno, como Aspergillus."}, {"q": "En el aislamiento de contacto, la ubicación en cohortes consiste en:", "o": ["Compartir habitación con otro paciente colonizado o infectado por el mismo microorganismo", "Compartir habitación con cualquier paciente aislado", "Ubicar al paciente en una sala con presión negativa", "Agrupar a pacientes sin infección"], "a": 0, "e": "Nunca se deben mezclar pacientes con microorganismos o perfiles de resistencia distintos."}, {"q": "Los contenedores y bolsas de residuos peligrosos no deben llenarse por encima de:", "o": ["La mitad de su capacidad", "El 90% de su capacidad", "Las tres cuartas partes de su capacidad", "El borde superior"], "a": 2, "e": "El límite de 3/4 permite un cierre seguro y evita pinchazos y derrames."}, {"q": "Una aguja utilizada para inyectar una vacuna a una persona sana se clasifica como residuo del:", "o": ["Grupo I", "Grupo III", "Grupo II", "Grupo V"], "a": 1, "e": "Todo objeto punzante o cortante es grupo III por su riesgo físico, con independencia del paciente, y va en contenedor rígido."}, {"q": "En el Servicio Murciano de Salud, los restos de citostáticos y el material que ha estado en contacto con ellos se depositan en:", "o": ["Contenedor rígido azul (grupo VI), destinado a incineración", "Contenedor amarillo de punzantes (grupo III)", "Bolsa negra (grupo I)", "Bolsa de galga gruesa (grupo II)"], "a": 0, "e": "Los citostáticos son cancerígenos, mutágenos y teratógenos; se eliminan por incineración a alta temperatura."}, {"q": "Los pañales, el material de curas y los sistemas de suero sin sangre abundante ni citostáticos pertenecen al grupo:", "o": ["I", "II", "III", "IV"], "a": 1, "e": "Son residuos sanitarios no específicos: derivan de la asistencia pero no suponen riesgo infeccioso especial fuera del centro."}, {"q": "Un miembro inferior amputado se gestiona como:", "o": ["Residuo del grupo III en bolsa roja", "Residuo del grupo II", "Residuo citostático", "Grupo IV, según la normativa de policía sanitaria mortuoria (inhumación o cremación)"], "a": 3, "e": "Los cadáveres y restos humanos de entidad no se tratan como residuos sanitarios convencionales."}, {"q": "El tiempo máximo de permanencia de los residuos sanitarios peligrosos en el almacén final del hospital es de:", "o": ["12 horas", "30 días", "72 horas", "6 meses"], "a": 2, "e": "Además, deben evacuarse de las unidades asistenciales como máximo cada 12 horas."}, {"q": "Respecto al gas radón, es correcto que:", "o": ["Es un gas radiactivo de origen natural procedente del subsuelo granítico y la segunda causa de cáncer de pulmón tras el tabaco", "Es un residuo industrial de las centrales nucleares", "Es un contaminante biológico", "Solo se encuentra en zonas costeras"], "a": 0, "e": "Se acumula en sótanos y plantas bajas mal ventiladas."}, {"q": "La Unidad de Salud Medioambiental Pediátrica (PEHSU) del Hospital Virgen de la Arrixaca centra su actividad en:", "o": ["Los trabajadores expuestos a metales pesados", "Los residuos hospitalarios", "La población anciana institucionalizada", "Las embarazadas y la infancia"], "a": 3, "e": "Se centra en las ventanas de vulnerabilidad del desarrollo y utiliza la \"hoja verde\" para detectar riesgos ambientales."}]},
20: {"tema": 20, "titulo": "Administración de fármacos por diferentes vías. Cálculo de dosis. Medicación en el domicilio y paciente polimedicado", "programa": "Administración de fármacos por diferentes vías: fundamentos de seguridad, farmacocinética, medicamentos de alto riesgo y reacciones adversas; vías enterales, parenterales y tópicas. Cálculo de dosis y fluidoterapia. Administración de medicamentos en el domicilio y seguimiento de pacientes polimedicados: conciliación, deprescripción y adherencia.", "preguntas": [{"q": "La vía de administración con una biodisponibilidad del 100% por definición es la:", "o": ["Intravenosa", "Oral", "Sublingual", "Intramuscular"], "a": 0, "e": "La vía IV introduce el fármaco directamente en la circulación. Las vías enterales tienen menor biodisponibilidad por la absorción incompleta y el primer paso hepático."}, {"q": "¿Cuál de los siguientes grupos de fármacos tiene un índice terapéutico estrecho y requiere monitorizar niveles plasmáticos?", "o": ["Paracetamol, ibuprofeno y omeprazol", "Amoxicilina, cefazolina y clindamicina", "Digoxina, litio y fenitoína", "Loratadina, cetirizina y dexclorfeniramina"], "a": 2, "e": "El índice terapéutico (DL50/DE50) es pequeño: pequeñas variaciones de dosis producen toxicidad o ineficacia."}, {"q": "El registro de la administración de un medicamento debe realizarse:", "o": ["Al preparar la medicación, antes de entrar en la habitación", "Al final del turno, todo junto", "Cuando lo indique el médico", "Inmediatamente después de administrarlo"], "a": 3, "e": "Si el paciente lo rechaza, se registra el rechazo y su motivo. Nunca se registra una medicación preparada o administrada por otro profesional."}, {"q": "Respecto al cloruro potásico concentrado, es correcto que:", "o": ["Puede administrarse en bolo IV lento en hipopotasemias graves", "Debe administrarse siempre diluido y en perfusión, nunca en bolo IV directo", "Puede administrarse por vía intramuscular", "No se considera un medicamento de alto riesgo"], "a": 1, "e": "El KCl en bolo puede causar una parada cardiaca. Es un medicamento de alto riesgo según el ISMP."}, {"q": "Según la clasificación de Rawlins y Thompson, una hipoglucemia tras la administración de insulina es una reacción adversa de tipo:", "o": ["B (bizarre)", "A (augmented)", "C (chronic)", "D (delayed)"], "a": 1, "e": "Las de tipo A son las más frecuentes, predecibles y dependientes de la dosis, por exageración del efecto farmacológico."}, {"q": "El efecto rebote tras la suspensión brusca de un betabloqueante es una reacción adversa de tipo:", "o": ["A", "B", "C", "E"], "a": 3, "e": "Tipo E (end of use): aparece al suspender bruscamente un tratamiento crónico, como la abstinencia a opioides."}, {"q": "La única vía enteral que evita por completo el efecto de primer paso hepático es la:", "o": ["Sublingual", "Oral", "Rectal", "Sonda nasogástrica"], "a": 0, "e": "La mucosa sublingual drena a la vena cava superior sin pasar por la porta. Por eso se usa para la nitroglicerina en la angina."}, {"q": "Respecto a la vía rectal, es correcto que:", "o": ["Evita totalmente el efecto de primer paso hepático", "Tiene una absorción rápida y constante", "Evita el primer paso hepático solo de forma parcial (≈ 50%)", "Es de elección en las urgencias cardiológicas"], "a": 2, "e": "La vena hemorroidal superior drena a la porta, mientras que las medias e inferiores van a la cava. La absorción es errática."}, {"q": "Para administrar medicación por sonda nasogástrica, NO se debe:", "o": ["Lavar la sonda con agua antes y después", "Administrar cada fármaco por separado", "Triturar un comprimido de liberación prolongada", "Preferir las formas farmacéuticas líquidas"], "a": 2, "e": "Triturar formas retard o con cubierta entérica provoca una liberación masiva (toxicidad) o destruye la protección gástrica."}, {"q": "Al administrar medicación por sonda nasogástrica, el lavado de la sonda antes y después se realiza con:", "o": ["20-30 ml de agua", "2 ml de suero glucosado", "100 ml de agua", "Aire con jeringa de 50 ml"], "a": 0, "e": "Entre fármaco y fármaco se lavan 5-10 ml. El paciente debe estar incorporado 30-45° y seguir así un tiempo tras la administración."}, {"q": "En la administración intradérmica (por ejemplo, el Mantoux):", "o": ["Se inyecta a 90° con aguja larga", "Se usa un ángulo de 10-15° con el bisel hacia arriba, debe formarse una pápula y no se masajea", "Se masajea la zona para favorecer la absorción", "Se administran de 2 a 5 ml"], "a": 1, "e": "El volumen es de 0,1-0,3 ml, habitualmente en la cara anterior del antebrazo; el masaje alteraría la prueba."}, {"q": "Al administrar una heparina de bajo peso molecular en jeringa precargada:", "o": ["Se purga la burbuja de aire antes de inyectar", "Se masajea la zona durante un minuto", "Se aspira antes de inyectar", "No se purga la burbuja de aire ni se masajea la zona después"], "a": 3, "e": "La burbuja sella el trayecto y evita el reflujo y los hematomas; tras la punción solo se presiona suavemente sin frotar."}, {"q": "En la vía subcutánea, la zona con la absorción más rápida es:", "o": ["El abdomen (respetando unos 5 cm alrededor del ombligo)", "La cara anterior del muslo", "La región escapular", "La cara externa del brazo"], "a": 0, "e": "El muslo tiene una absorción más lenta (útil para insulinas basales nocturnas). Hay que rotar los puntos para evitar lipodistrofias."}, {"q": "La zona considerada más segura para la inyección intramuscular en adultos es la:", "o": ["Dorsoglútea", "Deltoidea", "Ventroglútea (técnica de Hochstetter)", "Cara posterior del muslo"], "a": 2, "e": "Carece de grandes vasos y nervios y tiene poco tejido graso. La dorsoglútea se desaconseja por el riesgo de lesionar el nervio ciático."}, {"q": "La técnica intramuscular en Z está especialmente indicada para administrar:", "o": ["Vacunas de calendario", "Insulina", "Heparina de bajo peso molecular", "Hierro parenteral"], "a": 3, "e": "Se usa con fármacos irritantes o que tiñen la piel; el desplazamiento de los tejidos sella el trayecto e impide el reflujo."}, {"q": "Ante un politraumatizado en shock hipovolémico, el catéter venoso periférico de elección es el de:", "o": ["24 G (amarillo)", "14 G (naranja)", "22 G (azul)", "20 G (rosa)"], "a": 1, "e": "En la escala Gauge, a menor número, mayor calibre y mayor flujo. En emergencias se usan 14 G o 16 G."}, {"q": "Para una transfusión de concentrado de hematíes programada en un adulto, se recomienda un catéter de:", "o": ["24 G", "18 G (verde)", "26 G", "22 G"], "a": 1, "e": "El 18 G permite un flujo adecuado sin hemolizar los hematíes; también puede usarse 20 G para ritmos lentos."}, {"q": "Ante la sospecha de extravasación de un citostático, la primera actuación es:", "o": ["Detener la infusión sin retirar el catéter e intentar aspirar el fármaco extravasado", "Retirar inmediatamente el catéter y masajear la zona", "Aumentar el ritmo para terminar la perfusión", "Aplicar calor en todos los casos"], "a": 0, "e": "Después se administra el antídoto si existe, se retira el catéter y se aplica frío (calor en los alcaloides de la vinca), se eleva el miembro y se informa."}, {"q": "Respecto a la vía intraósea, es correcto que:", "o": ["Solo admite sueros, no fármacos", "Requiere dosis dobles que la vía IV", "La tibia proximal es una zona de elección, se usan las mismas dosis que por vía IV y debe retirarse antes de 24 horas", "Puede mantenerse hasta 7 días"], "a": 2, "e": "Es la alternativa urgente cuando no hay acceso venoso; su permanencia prolongada aumenta el riesgo de osteomielitis y síndrome compartimental."}, {"q": "Tras instilar un colirio de timolol, para reducir su absorción sistémica se debe:", "o": ["Frotar el ojo con fuerza", "Instilar a continuación una pomada", "Inclinar la cabeza hacia delante", "Presionar el canto interno del ojo durante 1-2 minutos"], "a": 3, "e": "La oclusión del conducto nasolagrimal evita que el fármaco pase a la mucosa nasal. Entre colirios se esperan 5 minutos y las pomadas van al final."}, {"q": "Para instilar gotas óticas en un adulto, el pabellón auricular se tracciona:", "o": ["Hacia arriba y hacia atrás", "Hacia abajo y hacia atrás", "Hacia delante", "No es necesario traccionarlo"], "a": 0, "e": "En menores de 3 años se tracciona hacia abajo y atrás. Las gotas deben estar a temperatura corporal para evitar el vértigo."}, {"q": "Un paciente con un parche transdérmico de fentanilo debe evitar:", "o": ["Ducharse", "Cambiar la zona de aplicación", "Aplicar el parche sobre piel sin vello", "Aplicar calor local sobre el parche (mantas eléctricas, bolsas de agua caliente)"], "a": 3, "e": "El calor aumenta la absorción y puede causar una sobredosis con depresión respiratoria. Los parches de reservorio tampoco se cortan."}, {"q": "Hay que administrar 1.000 ml de suero en 12 horas con un sistema de macrogoteo (20 gotas/ml). El ritmo aproximado es de:", "o": ["14 gotas/min", "42 gotas/min", "28 gotas/min", "83 gotas/min"], "a": 2, "e": "Gotas/min = volumen / (3 × horas) = 1.000 / 36 ≈ 28 gotas/min (≈ 83 ml/h)."}, {"q": "Un ritmo de perfusión de 30 ml/h equivale, en un sistema de macrogoteo, a:", "o": ["30 gotas/min", "10 gotas/min", "90 gotas/min", "60 gotas/min"], "a": 1, "e": "1 gota/min = 3 ml/h, por lo que 30 ml/h = 10 gotas/min. En microgoteo, 1 microgota/min = 1 ml/h."}, {"q": "Se pauta noradrenalina a 0,1 µg/kg/min en un paciente de 80 kg. La dilución es de 20 mg en 100 ml (200 µg/ml). La bomba debe programarse a:", "o": ["24 ml/h", "0,24 ml/h", "8 ml/h", "2,4 ml/h"], "a": 3, "e": "ml/h = (0,1 × 80 × 60) / 200 = 480 / 200 = 2,4 ml/h."}, {"q": "La regla de Young para calcular la dosis pediátrica (2-12 años) es:", "o": ["[Edad en años / (edad en años + 12)] × dosis de adulto", "(Edad en meses / 150) × dosis de adulto", "(Peso en kg / 70) × dosis de adulto", "(Edad en años / 24) × dosis de adulto"], "a": 0, "e": "La de Fried usa la edad en meses entre 150 (lactantes) y la de Clark, el peso entre 70. La más exacta es la superficie corporal."}, {"q": "Respecto al botiquín domiciliario, es correcto aconsejar:", "o": ["Guardarlo en el cuarto de baño por su limpieza", "Guardarlo en un lugar fresco, seco y oscuro, fuera de la cocina y el baño", "Guardar la insulina de reserva en el congelador", "Tirar los blísteres vacíos al contenedor amarillo"], "a": 1, "e": "La humedad y los cambios de temperatura de baño y cocina deterioran los fármacos. Termolábiles a 2-8 °C sin congelar; envases y restos al Punto SIGRE."}, {"q": "La versión 3 (2023) de los criterios STOPP/START contiene:", "o": ["100 criterios en total", "80 criterios STOPP y 34 START", "190 criterios: 133 STOPP y 57 START", "57 criterios STOPP y 133 START"], "a": 2, "e": "STOPP indica fármacos que retirar y START tratamientos omitidos que iniciar, incluidas las vacunas (gripe, neumococo, zóster y COVID-19)."}, {"q": "En el test de Morisky-Green, el paciente se considera cumplidor si responde:", "o": ["NO, SÍ, NO, NO", "NO a las 4 preguntas", "SÍ a las 4 preguntas", "SÍ, NO, SÍ, SÍ"], "a": 0, "e": "La segunda pregunta (\"¿toma los medicamentos a la hora indicada?\") debe responderse SÍ; cualquier otra combinación indica incumplimiento."}, {"q": "El cuestionario de adherencia que incluye una pregunta específica sobre los olvidos durante el fin de semana es el:", "o": ["Test de Batalla", "Test de Morisky-Green", "Test de Haynes-Sackett", "Cuestionario SMAQ"], "a": 3, "e": "El SMAQ (6 preguntas) detecta las \"vacaciones terapéuticas\". El de Batalla evalúa el conocimiento de la enfermedad y el de Haynes-Sackett fija el umbral en el 80%."}, {"q": "En la imagen se representan las cuatro vías parenterales. ¿Con qué ángulo se administra la inyección intradérmica (n.º 4)?", "o": ["90°", "45°", "25-30°", "10-15°"], "a": 3, "e": "IM 90°; SC 45° (90° con aguja corta o pellizco); IV 25-30°; intradérmica 10-15° con el bisel hacia arriba, hasta formar una pápula.", "img": "img/preguntas/t20-angulos.jpg"}, {"q": "El catéter venoso periférico de este color, el estándar para fluidoterapia en el adulto, es de calibre:", "o": ["18 G", "20 G", "22 G", "24 G"], "a": 1, "e": "Rosa = 20 G. Naranja 14 G, gris 16 G, verde 18 G, azul 22 G, amarillo 24 G, violeta 26 G.", "img": "img/preguntas/cateter-rosa.svg"}]},
21: {"tema": 21, "titulo": "Clasificación de medicamentos, farmacocinética y farmacovigilancia. Uso racional y prescripción enfermera", "programa": "Clasificación general de medicamentos (sistema ATC). Absorción, distribución, metabolismo y eliminación. Efectos colaterales y reacciones adversas. Farmacovigilancia: reacciones adversas y su notificación (Tarjeta Amarilla). Uso racional del medicamento y adherencia. Indicación, uso y autorización de dispensación por enfermeras y protocolos del SMS.", "preguntas": [{"q": "La clasificación ATC (Anatómica, Terapéutica, Química) de los medicamentos es responsabilidad de:", "o": ["La Agencia Europea del Medicamento (EMA)", "La AEMPS", "La Organización Mundial de la Salud (OMS)", "El Ministerio de Sanidad"], "a": 2, "e": "La OMS gestiona y actualiza el código ATC a nivel internacional."}, {"q": "El código ATC de un principio activo consta de:", "o": ["7 niveles y 5 caracteres", "5 niveles y 7 caracteres", "3 niveles y 10 caracteres", "14 niveles y 14 caracteres"], "a": 1, "e": "Por ejemplo, A02BC01 (omeprazol): grupo anatómico (A), terapéutico (02), farmacológico (B), químico (C) y principio activo (01)."}, {"q": "En la clasificación ATC, las vacunas pertenecen al grupo:", "o": ["J (antiinfecciosos para uso sistémico)", "V (varios)", "L (antineoplásicos e inmunomoduladores)", "H (preparados hormonales sistémicos)"], "a": 0, "e": "El grupo J incluye antibacterianos, antivirales, inmunoglobulinas y vacunas."}, {"q": "En la clasificación ATC, el acenocumarol pertenece al grupo:", "o": ["C (sistema cardiovascular)", "N (sistema nervioso)", "M (sistema musculoesquelético)", "B (sangre y órganos hematopoyéticos)"], "a": 3, "e": "Actúa sobre la coagulación, por lo que se clasifica en el grupo B, como antitrombótico (B01AA07)."}, {"q": "La farmacocinética estudia:", "o": ["Lo que el organismo le hace al fármaco (absorción, distribución, metabolismo y eliminación)", "Lo que el fármaco le hace al organismo", "Solo el mecanismo de acción en los receptores", "La fabricación de los medicamentos"], "a": 0, "e": "La farmacodinamia, en cambio, estudia los efectos del fármaco sobre el organismo."}, {"q": "La fracción farmacológicamente activa de un fármaco en el plasma es:", "o": ["La unida a la albúmina", "La unida a la alfa-1-glucoproteína ácida", "La fracción libre", "La fracción conjugada en el hígado"], "a": 2, "e": "Solo la fracción libre atraviesa membranas, actúa sobre los receptores y se metaboliza o filtra; la unida a proteínas es un reservorio."}, {"q": "En un paciente con hipoalbuminemia grave que recibe fenitoína a dosis habituales:", "o": ["Hay que doblar la dosis porque faltan proteínas transportadoras", "El fármaco no tendrá efecto", "No cambia nada", "Aumenta la fracción libre del fármaco y el riesgo de toxicidad"], "a": 3, "e": "Con menos albúmina, más moléculas quedan libres y activas; puede ser necesario reducir la dosis."}, {"q": "Las reacciones de fase II del metabolismo hepático consisten en:", "o": ["Oxidación, reducción e hidrólisis mediante el citocromo P450", "La conjugación con sustancias endógenas como el ácido glucurónico", "La filtración glomerular", "La unión a proteínas plasmáticas"], "a": 1, "e": "La fase I modifica grupos funcionales (citocromo P450); la fase II conjuga y genera metabolitos polares, casi siempre inactivos."}, {"q": "La administración conjunta de un fármaco inhibidor enzimático del citocromo P450 con otro que se metaboliza por esa vía puede producir:", "o": ["Un fracaso terapéutico por destrucción acelerada del segundo fármaco", "La acumulación del segundo fármaco y riesgo de toxicidad", "Ningún efecto", "Un aumento de la excreción renal"], "a": 1, "e": "El inhibidor bloquea la enzima y el otro fármaco se acumula. El inductor, en cambio, acelera su metabolismo y causa fracaso terapéutico."}, {"q": "Ante una intoxicación grave por ácido acetilsalicílico, para favorecer su eliminación renal se debe:", "o": ["Acidificar la orina", "Restringir los líquidos", "Administrar diuréticos de asa sin más", "Alcalinizar la orina con bicarbonato sódico"], "a": 3, "e": "Al subir el pH urinario, el fármaco ácido se ioniza en el túbulo, no puede reabsorberse y se elimina por la orina (atrapamiento iónico)."}, {"q": "En la cinética de eliminación de orden cero:", "o": ["Las enzimas están saturadas y se elimina una cantidad constante por unidad de tiempo, como ocurre con el alcohol", "Se elimina un porcentaje constante por unidad de tiempo", "Es la cinética de la mayoría de los fármacos a dosis terapéuticas", "La velocidad de eliminación aumenta con la concentración"], "a": 0, "e": "En orden cero, aumentar la dosis produce acumulación (alcohol, fenitoína). En primer orden se elimina una fracción constante."}, {"q": "Tras iniciar un tratamiento con dosis repetidas, el estado de equilibrio estacionario se alcanza aproximadamente en:", "o": ["1 semivida", "2 semividas", "5 semividas", "10 semividas"], "a": 2, "e": "También se considera que un fármaco se ha eliminado casi por completo tras unas 5 semividas."}, {"q": "La diarrea por alteración de la flora intestinal tras tomar amoxicilina-clavulánico es un ejemplo de:", "o": ["Efecto colateral", "Efecto tóxico", "Efecto secundario", "Reacción de tipo B"], "a": 2, "e": "El efecto secundario es una consecuencia indirecta de la acción principal del fármaco."}, {"q": "La sequedad de boca y la retención urinaria producidas por un antihistamínico de primera generación son un ejemplo de:", "o": ["Efecto secundario", "Efecto tóxico", "Reacción de tipo F", "Efecto colateral"], "a": 3, "e": "El efecto colateral forma parte del propio mecanismo del fármaco (bloqueo muscarínico), pero en órganos distintos del objetivo."}, {"q": "Según la OMS, una reacción adversa a medicamentos es:", "o": ["Una respuesta nociva y no intencionada que aparece a las dosis utilizadas habitualmente", "Cualquier efecto producido por una sobredosis intencionada", "Un error de administración", "Cualquier efecto terapéutico del fármaco"], "a": 0, "e": "La definición excluye los errores de medicación y las sobredosis."}, {"q": "Un shock anafiláctico tras la administración de penicilina es una reacción adversa de tipo:", "o": ["A", "B", "C", "E"], "a": 1, "e": "Las de tipo B son impredecibles, no dependen de la dosis (inmunológicas o idiosincrásicas) y obligan a retirar el fármaco."}, {"q": "Las malformaciones congénitas causadas por la talidomida son una reacción adversa de tipo:", "o": ["A", "B", "C", "D"], "a": 3, "e": "Tipo D (delayed): aparecen tiempo después del tratamiento, como la teratogénesis y la carcinogénesis."}, {"q": "Una mujer que toma anticonceptivos orales queda embarazada tras recibir rifampicina. Se trata de una reacción adversa de tipo:", "o": ["A", "E", "F", "C"], "a": 2, "e": "Tipo F (failure): fallo terapéutico inesperado, en este caso por inducción enzimática."}, {"q": "La fase I de un ensayo clínico se caracteriza por:", "o": ["Realizarse en un pequeño grupo de voluntarios sanos para evaluar la seguridad y la dosis tolerada", "Realizarse en miles de pacientes para la autorización", "Ser el seguimiento tras la comercialización", "Evaluar la eficacia frente a placebo en enfermos"], "a": 0, "e": "La fase II evalúa la eficacia inicial en enfermos, la III confirma en miles de pacientes y la IV es la farmacovigilancia poscomercialización."}, {"q": "La farmacovigilancia poscomercialización, en la que participa la enfermería mediante la Tarjeta Amarilla, corresponde a la fase:", "o": ["I", "IV", "II", "III"], "a": 1, "e": "La fase IV detecta reacciones adversas raras o tardías en la población real."}, {"q": "El triángulo negro invertido (▼) en el prospecto de un medicamento significa que:", "o": ["Está sujeto a seguimiento adicional por las autoridades sanitarias", "Es un medicamento peligroso o inseguro", "Está en proceso de retirada", "Es un medicamento sin receta"], "a": 0, "e": "Se aplica a medicamentos de los que se necesita recoger más información de seguridad; no indica que sean más peligrosos."}, {"q": "Llevan obligatoriamente el triángulo negro invertido:", "o": ["Todos los genéricos", "Los medicamentos de uso hospitalario", "Los nuevos principios activos y los medicamentos biológicos autorizados desde el 1 de enero de 2011", "Los medicamentos con más de 5 años en el mercado"], "a": 2, "e": "También los autorizados de forma condicional o excepcional y aquellos a los que se exigen estudios posautorización."}, {"q": "La norma que regula actualmente la farmacovigilancia de medicamentos de uso humano en España es:", "o": ["La Ley 41/2002", "El RD 954/2015", "El RD 1093/2010", "El RD 577/2013"], "a": 3, "e": "El RD 577/2013 transpone la normativa europea y permite también que los ciudadanos notifiquen sospechas de RAM."}, {"q": "Al cumplimentar una Tarjeta Amarilla, el paciente se identifica mediante:", "o": ["Nombre, apellidos y DNI", "Sus iniciales, edad, sexo y peso", "Solo el número de historia clínica", "El nombre completo y la dirección"], "a": 1, "e": "Por protección de datos no se incluye la identidad completa. El peso ayuda a valorar posibles sobredosificaciones."}, {"q": "Es especialmente prioritario notificar mediante la Tarjeta Amarilla:", "o": ["Solo las reacciones descritas en la ficha técnica", "Únicamente las reacciones leves conocidas", "Las reacciones graves, las no descritas y las de medicamentos de reciente comercialización", "Solo las reacciones en adultos sanos"], "a": 2, "e": "También las que se presentan en niños, ancianos y embarazadas. Aunque falten datos, la notificación debe enviarse."}, {"q": "Según la OMS, el uso racional del medicamento implica que el paciente reciba:", "o": ["La medicación adecuada a sus necesidades, a la dosis y durante el tiempo adecuados, al menor coste posible", "Siempre el fármaco más nuevo", "La mayor cantidad posible de fármacos preventivos", "Solo fármacos sin receta"], "a": 0, "e": "Su incumplimiento favorece la polifarmacia irracional, la iatrogenia y las resistencias antimicrobianas."}, {"q": "La conciliación de la medicación debe realizarse:", "o": ["Solo una vez al año en Atención Primaria", "Únicamente al alta", "Solo si el paciente lo solicita", "Al ingreso, en los traslados entre unidades y al alta"], "a": 3, "e": "Al ingreso, preferentemente en las primeras 24 horas; en traslados, como el paso de UCI a planta, y al alta al domicilio."}, {"q": "El documento con el que una enfermera acreditada autoriza la dispensación de un medicamento o producto sanitario se denomina:", "o": ["Receta médica enfermera", "Orden de dispensación", "Informe de continuidad de cuidados", "Vale de farmacia"], "a": 1, "e": "Según el RD 954/2015, la receta médica es exclusiva de médicos, odontólogos y podólogos."}, {"q": "Para obtener la acreditación para la indicación de medicamentos en cuidados generales, la enfermera necesita:", "o": ["Un año de experiencia profesional o superar un curso de adaptación específico", "Diez años de experiencia", "Ser especialista en Enfermería Familiar y Comunitaria", "Una autorización del médico del centro"], "a": 0, "e": "Es el requisito previo establecido por el RD 954/2015, modificado por el RD 1302/2018."}, {"q": "En la consulta de estomaterapia se observa un estoma de color violáceo oscuro, casi negro. Según el protocolo del SMS, la actuación correcta es:", "o": ["Aplicar un apósito de plata", "Pautar una pomada barrera y revisar en una semana", "Cambiar el dispositivo por uno de dos piezas", "Derivar de forma urgente al cirujano, porque sugiere isquemia o necrosis"], "a": 3, "e": "Un estoma sano es rojo y húmedo. La coloración violácea o negra es una urgencia quirúrgica; también se derivan hernias, prolapsos, retracciones y estenosis."}]},
22: {"tema": 22, "titulo": "Indicación, uso y autorización de dispensación de medicamentos por enfermeras. RD 954/2015 y acreditación", "programa": "Actuación de enfermería en el uso y autorización de dispensación de medicamentos: Real Decreto 954/2015, de 23 de octubre, y su modificación por el RD 1302/2018. Acreditación de los enfermeros para la indicación, uso y autorización de dispensación de medicamentos y productos sanitarios de uso humano. Acreditación en el SMS, guías nacionales y protocolos regionales.", "preguntas": [{"q": "La competencia exclusiva del Estado sobre las bases de la sanidad y la legislación de productos farmacéuticos se recoge en:", "o": ["El artículo 43 de la Constitución", "El artículo 41 de la Constitución", "La Ley 44/2003", "El artículo 149.1.16.ª de la Constitución"], "a": 3, "e": "Por eso la regulación básica de la indicación enfermera es estatal; la ejecución (acreditación) corresponde a las comunidades autónomas."}, {"q": "El texto legal de rango superior vigente que ampara la indicación y autorización de dispensación por enfermeras es:", "o": ["El Real Decreto Legislativo 1/2015, texto refundido de la Ley de garantías y uso racional de los medicamentos", "La Ley 29/2006", "La Ley 14/1986", "La Ley 41/2002"], "a": 0, "e": "La Ley 29/2006 (modificada por la Ley 28/2009) fue derogada por el texto refundido de 2015."}, {"q": "La validez de una orden de dispensación para retirar el producto en la oficina de farmacia es, con carácter general, de:", "o": ["3 días hábiles", "1 mes", "10 días naturales desde su emisión o desde la fecha prevista de dispensación", "15 días hábiles"], "a": 2, "e": "Lo establece el RD 1718/2010 sobre receta médica y órdenes de dispensación."}, {"q": "Según el artículo 2 del RD 954/2015, los enfermeros acreditados pueden de forma autónoma:", "o": ["Prescribir cualquier medicamento sujeto a receta", "Indicar, usar y autorizar la dispensación de medicamentos no sujetos a prescripción médica y de productos sanitarios", "Emitir recetas médicas", "Modificar el principio activo de una prescripción médica"], "a": 1, "e": "Para estos productos basta la acreditación y el juicio clínico enfermero."}, {"q": "Para que una enfermera acreditada pueda indicar un medicamento sujeto a prescripción médica es necesario:", "o": ["Solo tener un año de experiencia", "La autorización verbal del supervisor", "Que exista una guía nacional validada y un protocolo autonómico, en un marco colaborativo", "Que el paciente lo solicite por escrito"], "a": 2, "e": "En general, el médico ha establecido antes el diagnóstico y la prescripción inicial; la enfermera hace el seguimiento según el protocolo."}, {"q": "Las guías para la indicación enfermera de medicamentos sujetos a prescripción las elabora:", "o": ["Un grupo de trabajo paritario de la Comisión Permanente de Farmacia del Consejo Interterritorial del SNS", "Exclusivamente el Consejo General de Enfermería", "Cada hospital de forma independiente", "La Organización Médica Colegial en solitario"], "a": 0, "e": "Participan el Ministerio, las comunidades autónomas, las mutualidades, el Consejo General de Enfermería y la OMC; las valida la Dirección General de Salud Pública y se publican en el BOE."}, {"q": "La sentencia del Tribunal Constitucional que anuló los aspectos del RD 954/2015 que invadían la competencia autonómica de acreditación es la:", "o": ["STC 37/2011", "STC 76/2018", "STC 154/2015", "STC 1/2020"], "a": 1, "e": "Tras ella se aprobó el RD 1302/2018, de 22 de octubre, que modificó el RD 954/2015."}, {"q": "Tras el RD 1302/2018, la administración por enfermeras de las vacunas del calendario y de las campañas de salud pública:", "o": ["Exige siempre prescripción médica individualizada", "Está prohibida para enfermeras no especialistas", "Solo puede hacerse en el hospital", "Solo precisa orden de dispensación enfermera, salvo que el paciente requiera una valoración médica individualizada"], "a": 3, "e": "Si el paciente presenta condiciones particulares (p. ej., anafilaxia previa o inmunosupresión grave), se requiere valoración médica."}, {"q": "Para obtener la acreditación como enfermero de cuidados generales se exige:", "o": ["Un año de experiencia profesional o superar un curso de adaptación gratuito", "Cinco años de experiencia en la sanidad pública", "Un máster oficial en farmacología", "Ser especialista en Enfermería Familiar y Comunitaria"], "a": 0, "e": "El curso de adaptación (ECTS) está pensado para quienes aún no tienen el año de experiencia."}, {"q": "Para computar el año de experiencia necesario para la acreditación:", "o": ["Solo cuentan las plazas en propiedad de la sanidad pública", "Solo cuentan los servicios en Atención Primaria", "Cuentan todos los servicios prestados, en centros públicos o privados", "Solo cuenta la experiencia posterior a 2015"], "a": 2, "e": "Se suman todos los servicios desde el primer nombramiento, incluidos clínicas privadas, concertadas o mutuas."}, {"q": "Respecto a la acreditación de los enfermeros, es correcto que:", "o": ["La concede el Ministerio de Sanidad a través del REPS", "La concede el colegio profesional", "Caduca cada 5 años", "La concede la comunidad autónoma y se inscribe en el Registro Estatal de Profesionales Sanitarios, lo que le da validez nacional"], "a": 3, "e": "La vigencia es indefinida, salvo suspensión o revocación por pérdida de requisitos, sanción firme o inhabilitación."}, {"q": "Una enfermera especialista en salud mental acreditada como tal puede indicar medicamentos sujetos a prescripción:", "o": ["De cualquier ámbito clínico, por su titulación superior", "Solo dentro de las guías y protocolos de su especialidad", "Solo productos sanitarios", "Ningún medicamento con receta"], "a": 1, "e": "Fuera de su especialidad actúa con las competencias de enfermera de cuidados generales."}, {"q": "En el Servicio Murciano de Salud, las resoluciones de acreditación de oficio del personal de enfermería las dicta:", "o": ["El Consejero de Salud directamente", "El Director Gerente del SMS, por delegación de la Consejería", "El Colegio Oficial de Enfermería de Murcia", "El Ministerio de Sanidad"], "a": 1, "e": "La primera resolución masiva se publicó en el BORM el 30 de enero de 2023 y se actualiza mensualmente."}, {"q": "El procedimiento 3460 de la sede electrónica de la CARM está destinado a:", "o": ["La acreditación a instancia de parte de enfermeras que trabajan en la sanidad privada o no constan en los registros del SMS", "La renovación anual de la acreditación del personal del SMS", "La notificación de reacciones adversas", "La solicitud de recetas médicas"], "a": 0, "e": "Se aporta un certificado de experiencia de la empresa o una declaración responsable (autónomos) y no tiene tasas."}, {"q": "En el procedimiento 3460 de la CARM, el plazo máximo de resolución y el sentido del silencio administrativo son:", "o": ["3 meses y silencio negativo", "1 mes y silencio negativo", "2 meses y silencio positivo", "6 meses y silencio positivo"], "a": 3, "e": "Contra la resolución puede interponerse recurso de alzada ante la Consejería de Salud en el plazo de un mes."}, {"q": "Según las guías nacionales de hipertensión y diabetes, la enfermera acreditada puede:", "o": ["Cambiar un IECA por un ARA-II si el paciente tiene tos", "Iniciar un tratamiento antidiabético sin diagnóstico médico", "Prorrogar el tratamiento crónico y ajustar la dosis dentro de los rangos definidos por el médico", "Retirar definitivamente la insulina"], "a": 2, "e": "Los cambios de grupo farmacológico o de diagnóstico son competencia médica; ante signos de alarma suspende y deriva."}, {"q": "La guía de quemaduras autoriza a la enfermera a usar corticoides tópicos:", "o": ["Solo para complicaciones como la hipergranulación, las reacciones alérgicas locales o las cicatrices hipertróficas y queloides", "Como tratamiento inicial de todas las quemaduras de primer grado", "Asociados siempre a antibióticos desde el primer día", "Nunca"], "a": 0, "e": "Pertenecen al grupo ATC D07AC; además hay que comprobar su financiación en BIFIMED."}, {"q": "En un paciente anticoagulado con acenocumarol por fibrilación auricular, el rango de INR objetivo habitual es:", "o": ["0,5-1", "1-1,5", "4-5", "2-3"], "a": 3, "e": "En portadores de válvulas mecánicas el objetivo puede ser 2,5-3,5. Sin anticoagulación, el INR es de 1."}, {"q": "Un paciente en tratamiento con acenocumarol presenta un INR de 1,5. Según la guía, la actuación es:", "o": ["Administrar vitamina K intravenosa", "Aumentar la dosis de acenocumarol según el algoritmo, porque está en rango subterapéutico", "Suspender el acenocumarol", "Mantener la misma dosis"], "a": 1, "e": "La vitamina K se emplea para revertir INR supraterapéuticos con riesgo de sangrado, no para un INR bajo."}, {"q": "La guía de deshabituación tabáquica regula la indicación enfermera de:", "o": ["Bupropión y nortriptilina", "Benzodiacepinas", "Vareniclina y citisiniclina", "Parches de nicotina exclusivamente"], "a": 2, "e": "Son agonistas parciales de los receptores nicotínicos: alivian la abstinencia y reducen la recompensa si el paciente fuma."}, {"q": "¿Cuál de los siguientes anestésicos locales es de tipo éster?", "o": ["Lidocaína", "Bupivacaína", "Tetracaína", "Mepivacaína"], "a": 2, "e": "Las amidas llevan una \"i\" antes de \"-caína\" (lidocaína, bupivacaína, mepivacaína); la tetracaína no."}, {"q": "Durante una infiltración de mepivacaína, el paciente refiere sabor metálico, zumbidos y hormigueo alrededor de la boca. La enfermera debe:", "o": ["Suspender la infiltración, iniciar soporte vital y avisar urgentemente al médico", "Aplicar lidocaína tópica y continuar", "Aumentar la dosis para terminar antes", "Esperar a que desaparezcan los síntomas"], "a": 0, "e": "Son signos de toxicidad sistémica por anestésicos locales (LAST), una urgencia vital."}, {"q": "La guía de infección del tracto urinario inferior permite a la enfermera indicar fosfomicina o nitrofurantoína:", "o": ["A cualquier paciente con disuria", "A embarazadas con bacteriuria", "A varones con prostatitis", "A mujeres adultas no gestantes con cistitis no complicada, si las resistencias locales de E. coli son bajas"], "a": 3, "e": "La gerencia del área debe certificar que las tasas de resistencia locales están dentro de los márgenes de seguridad."}, {"q": "En los protocolos del SMS, la intervención NIC 2390 corresponde a:", "o": ["Derivación", "Prescribir medicación", "Apoyo al cuidador principal", "Cuidados de las heridas"], "a": 1, "e": "NIC 8100 es derivación, 7040 apoyo al cuidador principal y 3660 cuidados de las heridas."}, {"q": "Según el protocolo de heridas del SMS, la escala que orienta hacia una infección profunda o con riesgo de osteomielitis es:", "o": ["STONES", "NERDS", "Braden", "Altemeier"], "a": 0, "e": "NERDS orienta hacia colonización crítica o infección superficial; STONES, hacia infección profunda."}, {"q": "Según el protocolo de ostomías del SMS, el riesgo nutricional del paciente ostomizado se valora con la escala:", "o": ["Gijón", "Barthel", "EVA", "NRS 2002"], "a": 3, "e": "Gijón valora el riesgo social, Barthel la capacidad para el autocuidado y EVA el dolor."}, {"q": "Según la clasificación de Altemeier que recoge el protocolo de heridas del SMS, una herida quirúrgica limpia-contaminada es de clase:", "o": ["I", "III", "II", "IV"], "a": 2, "e": "Clase I: limpia; II: limpia-contaminada; III: contaminada; IV: sucia o infectada."}, {"q": "Antes de aplicar bromelaína (NexoBrid) en una quemadura, el lecho debe estar libre de restos de sulfadiazina argéntica porque:", "o": ["Aumenta el dolor", "La plata inactiva la enzima", "Produce quemaduras químicas", "Retrasa la absorción sistémica de la plata"], "a": 1, "e": "El lecho debe estar húmedo, limpio y sin restos de antimicrobianos ni queratina."}, {"q": "Según el protocolo de quemaduras del SMS, la bromelaína (NexoBrid) puede aplicarse:", "o": ["En un máximo del 15% de la superficie corporal por sesión, durante 4 horas", "En hasta el 50% de la superficie corporal durante 24 horas", "En quemaduras faciales y perineales preferentemente", "En dos aplicaciones consecutivas si no se desbrida del todo"], "a": 0, "e": "Está indicada en quemaduras de 2.º grado profundo y 3.º; la dosis es de 2 g por cada 100 cm² y está contraindicada en alergia a la piña o la papaína."}, {"q": "Si un paciente presenta una reacción al apósito medicamentoso prescrito por el médico, la enfermera acreditada del SMS:", "o": ["Puede cambiar el principio activo en la receta electrónica", "Debe duplicar el tratamiento con otro apósito", "Debe esperar a la siguiente revisión", "No puede modificar el principio activo: suspende la indicación, registra y deriva al médico"], "a": 3, "e": "Además, debe notificar la sospecha de reacción adversa al Sistema Español de Farmacovigilancia lo antes posible."}]},
23: {"tema": 23, "titulo": "Alimentación y nutrición. Dietas terapéuticas. Cuidados en desnutrición, deshidratación, anorexia, bulimia y obesidad", "programa": "Alimentación y nutrición: nutrientes y clasificación de los alimentos. Elaboración de dietas y gasto energético. Dietas terapéuticas. Valoración, intervenciones y cuidados de enfermería a personas con problemas de desnutrición, deshidratación, anorexia, bulimia y obesidad. Soporte nutricional artificial.", "preguntas": [{"q": "¿Cuántas kilocalorías aporta un gramo de lípidos?", "o": ["4 kcal", "9 kcal", "7 kcal", "0 kcal"], "a": 1, "e": "Hidratos de carbono y proteínas aportan 4 kcal/g, el alcohol 7 kcal/g y las grasas 9 kcal/g. Vitaminas y minerales no aportan energía."}, {"q": "En una dieta equilibrada, los hidratos de carbono deben aportar aproximadamente:", "o": ["10-15% del valor calórico total", "30-35%", "70-80%", "50-55%"], "a": 3, "e": "Lípidos 30-35% y proteínas 10-15%; los azúcares simples no deben superar el 10%."}, {"q": "Un gran quemado en situación de hipercatabolismo presentará un balance nitrogenado:", "o": ["Positivo", "Neutro", "Negativo", "Imposible de calcular"], "a": 2, "e": "Elimina más nitrógeno del que ingiere por la destrucción de tejidos; necesita una dieta hiperproteica."}, {"q": "Son vitaminas liposolubles:", "o": ["A, D, E y K", "B1, B6 y B12", "C y ácido fólico", "Todas las del complejo B"], "a": 0, "e": "Se absorben con las grasas y se acumulan en el organismo, por lo que su exceso puede ser tóxico."}, {"q": "El tratamiento con isoniazida para la tuberculosis puede provocar el déficit de:", "o": ["Vitamina C", "Vitamina K", "Vitamina B6 (piridoxina)", "Vitamina A"], "a": 2, "e": "Se suplementa la piridoxina para prevenir la neuropatía periférica."}, {"q": "La pelagra, caracterizada por dermatitis, diarrea y demencia, se debe al déficit de:", "o": ["Tiamina", "Vitamina C", "Vitamina D", "Niacina (vitamina B3)"], "a": 3, "e": "El déficit de tiamina causa beriberi y encefalopatía de Wernicke; el de vitamina C, escorbuto; el de D, raquitismo."}, {"q": "Para absorberse, la vitamina B12 necesita:", "o": ["Unirse al factor intrínseco gástrico y absorberse en el íleon terminal", "Un medio alcalino en el duodeno", "La presencia de grasas en la dieta", "La acción de la vitamina C"], "a": 0, "e": "Su déficit (p. ej., tras gastrectomía o en la anemia perniciosa) produce anemia y daño neurológico."}, {"q": "Para mejorar la absorción de un suplemento oral de hierro se recomienda tomarlo:", "o": ["Con un vaso de leche", "En ayunas con zumo de naranja", "Con té o café", "Junto a un suplemento de calcio"], "a": 1, "e": "La vitamina C favorece la absorción del hierro no hemo; el calcio, los taninos y los fosfatos la reducen."}, {"q": "En la clasificación de los alimentos del programa EDALNU, el grupo 3 está formado por:", "o": ["Leche y derivados", "Carnes, pescados y huevos", "Cereales y azúcares", "Patatas, legumbres y frutos secos"], "a": 3, "e": "Es un grupo mixto (energía, proteína vegetal y fibra), con un sector propio de color naranja en la rueda."}, {"q": "El macronutriente con mayor efecto termogénico (gasto energético para su digestión y metabolismo) es:", "o": ["Los hidratos de carbono", "Las grasas", "Las proteínas", "El alcohol"], "a": 2, "e": "El efecto termogénico de los alimentos supone en torno al 10% del gasto total y es máximo con las proteínas."}, {"q": "Respecto a la ecuación de Harris-Benedict, es correcto que:", "o": ["Se usa en adultos, con el peso en kg, la altura en cm y la edad, y no está indicada en niños", "Es la ecuación de elección en lactantes", "La altura debe introducirse en metros", "No diferencia entre hombres y mujeres"], "a": 0, "e": "En niños se usan otras ecuaciones (Schofield, FAO/OMS). El resultado se multiplica por factores de actividad y estrés."}, {"q": "La dieta líquida clara no debe mantenerse sin suplementación más de:", "o": ["6 horas", "24-48 horas", "1 semana", "2 semanas"], "a": 1, "e": "Solo contiene líquidos transparentes (agua, caldos desgrasados, infusiones, zumos colados) y es muy deficitaria en proteínas y grasas."}, {"q": "A un paciente con úlcera péptica o gastritis aguda se le debe pautar una dieta:", "o": ["Blanda gástrica (sin picantes, fritos, café ni cítricos)", "Blanda mecánica", "Hiperproteica", "Rica en fibra"], "a": 0, "e": "La blanda mecánica solo modifica la textura (para masticar); la gástrica evita lo que irrita la mucosa o estimula el ácido."}, {"q": "Para reducir el riesgo de broncoaspiración en un paciente con disfagia tras un ictus, durante la deglución se le enseña a:", "o": ["Inclinar la cabeza hacia atrás", "Tumbarse en decúbito supino", "Hablar mientras traga", "Acercar la barbilla al pecho (maniobra chin-tuck)"], "a": 3, "e": "La extensión del cuello abre la vía aérea y favorece la aspiración; la flexión la protege. Además se adaptan las texturas con espesantes."}, {"q": "Un líquido espesado con textura miel se caracteriza porque:", "o": ["Cae formando un hilo fino y continuo", "Cae en gotas gruesas y no puede tomarse con pajita", "Mantiene su forma al invertir la cuchara", "Tiene la consistencia del agua"], "a": 1, "e": "Néctar: cae en hilo (vaso o pajita gruesa); miel: cae en gotas (sorbos o cuchara); pudin: mantiene la forma (solo cuchara)."}, {"q": "En la encefalopatía hepática grave y en la enfermedad renal crónica prediálisis suele pautarse una dieta:", "o": ["Hiperproteica", "Rica en fibra", "Hipoproteica", "Hipercalórica sin restricciones"], "a": 2, "e": "Se restringen las proteínas (20-40 g/día) para reducir el amoniaco o la urea, asegurando calorías suficientes y proteínas de alto valor biológico."}, {"q": "La dieta astringente que se pauta en una gastroenteritis aguda debe ser:", "o": ["Rica en verduras crudas", "Rica en cereales integrales", "Con abundante leche desnatada", "Pobre en residuos y sin lactosa"], "a": 3, "e": "La lactosa tiene efecto osmótico y empeora la diarrea. Se permiten plátano maduro, manzana asada y membrillo."}, {"q": "En la dieta por raciones para el paciente diabético, una ración equivale a:", "o": ["10 g de hidratos de carbono", "5 g de hidratos de carbono", "20 g de hidratos de carbono", "50 g de hidratos de carbono"], "a": 0, "e": "Se recomienda fraccionar la ingesta en 5-6 comidas y priorizar los hidratos complejos."}, {"q": "En la dieta sin gluten de la enfermedad celíaca están prohibidos:", "o": ["Arroz, maíz y quinoa", "Solo el trigo", "Trigo, avena, cebada y centeno", "Las legumbres"], "a": 2, "e": "Regla TACC. La avena se excluye en los manuales por la contaminación cruzada. Arroz, maíz y quinoa son seguros."}, {"q": "Según la OMS, un IMC de 32 kg/m² corresponde a:", "o": ["Sobrepeso", "Obesidad grado I", "Obesidad grado II", "Obesidad mórbida"], "a": 1, "e": "25-29,9 sobrepeso; 30-34,9 obesidad I; 35-39,9 obesidad II; ≥ 40 obesidad III o mórbida."}, {"q": "Para valorar si un soporte nutricional está siendo eficaz en los días siguientes a su inicio, el mejor marcador es:", "o": ["La albúmina", "El colesterol total", "La prealbúmina", "La hemoglobina"], "a": 2, "e": "La prealbúmina tiene una vida media de unos 2 días; la albúmina (≈ 20 días) refleja la desnutrición crónica y se altera con la inflamación."}, {"q": "Respecto al cribado NRS-2002, es correcto que:", "o": ["Es la herramienta de elección en la comunidad", "Solo se aplica a mayores de 80 años", "No tiene en cuenta la gravedad de la enfermedad", "Se usa en el hospital, suma un punto si el paciente tiene 70 años o más y una puntuación ≥ 3 indica riesgo"], "a": 3, "e": "MUST se usa en la comunidad, NRS-2002 en el hospital y MNA en mayores."}, {"q": "El sistema automático de cribado CONUT utiliza:", "o": ["Albúmina, colesterol total y recuento de linfocitos", "Peso, talla e IMC", "Prealbúmina, transferrina y triglicéridos", "Hemoglobina, ferritina y glucosa"], "a": 0, "e": "Cruza tres datos de las analíticas rutinarias y genera alertas de desnutrición en el hospital."}, {"q": "La desnutrición tipo kwashiorkor se caracteriza por:", "o": ["Extrema delgadez con albúmina normal", "Edemas, ascitis y descenso brusco de la albúmina", "Obesidad abdominal", "Hipercalcemia"], "a": 1, "e": "Es una desnutrición proteica aguda del estrés metabólico; el marasmo es calórico, con delgadez extrema y albúmina relativamente conservada."}, {"q": "En el síndrome de realimentación, la alteración bioquímica característica y más peligrosa es la:", "o": ["Hiperpotasemia", "Hipercalcemia", "Hipernatremia", "Hipofosfatemia"], "a": 3, "e": "El pico de insulina introduce fósforo, potasio y magnesio en las células; la hipofosfatemia causa fallo respiratorio y cardiaco."}, {"q": "Para prevenir el síndrome de realimentación en un paciente con desnutrición grave, la tiamina debe administrarse:", "o": ["Antes de iniciar la alimentación (unos 30 minutos)", "Mezclada en la primera bolsa de nutrición", "Solo si aparecen síntomas neurológicos", "A los 7 días del inicio"], "a": 0, "e": "Además se inicia con 10-15 kcal/kg/día, con pocos hidratos, y se sube progresivamente en 4-7 días controlando fósforo, potasio y magnesio."}, {"q": "En una deshidratación hipertónica (hipernatrémica), la corrección demasiado rápida del sodio puede provocar:", "o": ["Hipoglucemia", "Insuficiencia renal aguda inmediata", "Edema cerebral", "Hipertensión intracraneal benigna sin riesgo"], "a": 2, "e": "La reposición debe ser lenta y controlada. La deshidratación isotónica, la más frecuente, se trata con cristaloides isotónicos."}, {"q": "Es característico de la bulimia nerviosa:", "o": ["Amenorrea y lanugo con emaciación extrema", "Signo de Russell (callos en los nudillos) y alcalosis metabólica con hipopotasemia", "Bradicardia extrema y peso muy bajo", "Ausencia de conductas purgativas"], "a": 1, "e": "Las pacientes suelen tener normopeso; los vómitos causan erosión del esmalte, hipertrofia parotídea y riesgo de arritmias."}, {"q": "Un paciente operado de bypass gástrico presenta temblor, sudor frío y confusión 2 horas después de tomar un postre muy azucarado. Lo más probable es:", "o": ["Un síndrome de dumping tardío por hipoglucemia reactiva", "Un síndrome de dumping precoz", "Una fuga anastomótica", "Una deshidratación hipertónica"], "a": 0, "e": "El dumping precoz aparece a los 10-30 minutos (mecanismo osmótico: taquicardia, mareo, diarrea); el tardío, a las 1-3 horas por el pico de insulina."}, {"q": "Respecto a la nutrición parenteral total (hiperosmolar), es correcto que:", "o": ["Puede infundirse por cualquier vía periférica", "Por su luz pueden administrarse bolos de antibiótico", "Su complicación aguda más frecuente es la hipoglucemia", "Se administra por catéter venoso central, por una luz exclusiva"], "a": 3, "e": "Solo las soluciones de baja osmolaridad (< 800-900 mOsm/l) pueden ir por vía periférica. La complicación aguda más frecuente es la hiperglucemia."}]},
24: {"tema": 24, "titulo": "Promoción de la actividad física y la alimentación equilibrada. Consejo dietético. Plan de actividad física por subgrupos", "programa": "Promoción de la actividad física y la alimentación equilibrada. Consejo dietético básico. Consejo dietético intensivo. Plan de actividad física individualizado y estandarizado en subgrupos poblacionales: anciano, anciano frágil, enfermedades crónicas y postoperatorio. Otros subgrupos de cuidado: embarazo, infancia y oncología.", "preguntas": [{"q": "En España, la Estrategia NAOS (\"¡Come sano y muévete!\") está coordinada por:", "o": ["La Agencia Española de Seguridad Alimentaria y Nutrición (AESAN)", "La OMS", "Las consejerías de sanidad autonómicas", "La Sociedad Española de Nutrición Comunitaria"], "a": 0, "e": "Sus pilares son la nutrición y la actividad física y su población prioritaria, niños y jóvenes."}, {"q": "Según el método del plato de Harvard, las comidas principales deben distribuirse en:", "o": ["50% proteínas, 25% verduras y 25% hidratos", "33% de cada grupo", "50% hidratos, 25% grasas y 25% verduras", "50% verduras y hortalizas, 25% hidratos complejos integrales y 25% proteínas saludables"], "a": 3, "e": "Es una herramienta visual que simplifica el consejo dietético sin necesidad de contar calorías."}, {"q": "El aporte diario recomendado de fibra dietética en el adulto es de:", "o": ["5-10 g", "25-30 g", "60-70 g", "100 g"], "a": 1, "e": "Procede sobre todo de cereales integrales, legumbres, frutas y verduras (≥ 400 g/día de frutas y hortalizas)."}, {"q": "El gran ensayo español que avaló la dieta mediterránea en la reducción de eventos cardiovasculares es el:", "o": ["Framingham", "REGICOR", "PREDIMED", "SCORE"], "a": 2, "e": "La dieta mediterránea se basa en el aceite de oliva virgen extra, los vegetales, el pescado y las legumbres."}, {"q": "El consejo dietético básico en Atención Primaria se caracteriza por:", "o": ["Requerir una agenda programada de 20 minutos", "Realizarse solo en grupo", "Estar reservado a pacientes con obesidad mórbida", "Ser una intervención breve (≈ 5 minutos) y oportunista en cualquier contacto con el paciente"], "a": 3, "e": "Es de elección en pacientes en precontemplación o contemplación y en población general."}, {"q": "En el consejo dietético intensivo, la fase grupal consta de:", "o": ["Un único taller", "Un mínimo de 4 talleres y un máximo de 6", "10-12 talleres obligatorios", "Talleres semanales durante un año"], "a": 1, "e": "Va precedida de una sesión individual (sesión 0) y seguida de otra individual (sesión 5) y de un seguimiento de 12 meses."}, {"q": "Un paciente con obesidad afirma que come perfectamente y no piensa cambiar nada. Lo más adecuado es:", "o": ["Un consejo individual breve con enfoque de entrevista motivacional", "Incluirlo de inmediato en el taller grupal del consejo intensivo", "Darle una dieta hipocalórica estricta por escrito", "Derivarlo a cirugía bariátrica"], "a": 0, "e": "Está en precontemplación: incluirlo en un grupo de cambio sería contraproducente para él y para el grupo."}, {"q": "Tras los talleres del consejo dietético intensivo, el seguimiento del paciente se mantiene durante:", "o": ["1 mes", "3 meses", "12 meses, con revisiones al menos cada 3 meses", "5 años"], "a": 2, "e": "La obesidad y el sedentarismo son crónicos y recidivantes; además se refuerza con llamadas y en cualquier visita."}, {"q": "Un anciano obtiene 11 puntos en el MNA-SF. La actuación correcta es:", "o": ["Considerarlo bien nutrido y finalizar", "Iniciar nutrición parenteral", "Considerarlo en riesgo o desnutrido y completar la evaluación global del MNA", "Repetir el cribado al año"], "a": 2, "e": "12-14 puntos es normal; 11 o menos obliga a completar la segunda parte del MNA."}, {"q": "En el MNA, cuando no puede calcularse el IMC, se sustituye por el perímetro de la pantorrilla, cuyo punto de corte es:", "o": ["31 cm", "21 cm", "41 cm", "88 cm"], "a": 0, "e": "Menos de 31 cm suma 0 puntos (depleción muscular); 31 cm o más suma 3."}, {"q": "En el cribado MUST, el efecto de la enfermedad aguda puntúa si el paciente:", "o": ["Ha comido algo menos durante dos semanas", "Tiene más de 70 años", "Tiene un IMC superior a 30", "No ha ingerido o probablemente no ingerirá alimentos durante más de 5 días"], "a": 3, "e": "Los otros dos parámetros del MUST son el IMC y la pérdida de peso involuntaria en 3-6 meses."}, {"q": "Según la SEEDO, existe un riesgo cardiovascular muy elevado cuando el perímetro abdominal es superior a:", "o": ["94 cm en hombres y 80 cm en mujeres", "102 cm en hombres y 88 cm en mujeres", "120 cm en ambos sexos", "88 cm en hombres y 102 cm en mujeres"], "a": 1, "e": "Se mide en el punto medio entre el reborde costal inferior y la cresta ilíaca."}, {"q": "El principio FITT para prescribir ejercicio se refiere a:", "o": ["Frecuencia, intensidad, tiempo y tipo", "Fuerza, intensidad, técnica y tolerancia", "Flexibilidad, impacto, tiempo y temperatura", "Frecuencia cardiaca, índice, tensión y talla"], "a": 0, "e": "El ejercicio debe dosificarse con el mismo rigor que un fármaco."}, {"q": "Una persona de 60 años con una frecuencia cardiaca de reposo de 70 lpm debe entrenar al 60% de su FC de reserva. Según Karvonen, su frecuencia objetivo es:", "o": ["96 lpm", "160 lpm", "106 lpm", "124 lpm"], "a": 3, "e": "FC máxima = 220 − 60 = 160; reserva = 160 − 70 = 90; 90 × 0,6 = 54; 54 + 70 = 124 lpm."}, {"q": "La fórmula de Karvonen utiliza:", "o": ["La tensión arterial y la saturación de oxígeno", "El peso y la talla", "La edad (FC máxima), la frecuencia cardiaca de reposo y el porcentaje de intensidad", "El volumen sistólico"], "a": 2, "e": "Al incluir la FC de reposo, personaliza la intensidad según la condición física basal."}, {"q": "Un MET equivale a un consumo de oxígeno de:", "o": ["1 ml O₂/kg/min", "3,5 ml O₂/kg/min", "10 ml O₂/kg/min", "35 ml O₂/kg/min"], "a": 1, "e": "Es el gasto en reposo sentado. Ligera < 3 MET; moderada 3-6; vigorosa > 6."}, {"q": "Una actividad física de intensidad moderada se caracteriza por:", "o": ["3-6 MET; la persona puede mantener una conversación pero no cantar", "Menos de 3 MET; no modifica la respiración", "Más de 6 MET; no puede decir frases completas", "Superar el 90% de la FC máxima"], "a": 0, "e": "La prueba del habla es un método sencillo para estimar la intensidad."}, {"q": "La escala de Borg original (6-20) tiene la particularidad de que:", "o": ["Es la de elección para medir la disnea en la EPOC", "Sus valores son aleatorios", "Multiplicando por 10 la puntuación se estima aproximadamente la frecuencia cardiaca", "Solo se usa en niños"], "a": 2, "e": "La escala modificada (0-10) es la de elección para valorar disnea y fatiga en pacientes respiratorios, ancianos o crónicos."}, {"q": "En un paciente en tratamiento con betabloqueantes, para dosificar la intensidad del ejercicio es preferible utilizar:", "o": ["La frecuencia cardiaca máxima teórica", "La tensión arterial sistólica", "La fórmula de Karvonen", "La escala de percepción del esfuerzo de Borg"], "a": 3, "e": "Los betabloqueantes y la neuropatía autonómica alteran la respuesta de la frecuencia cardiaca."}, {"q": "Según los criterios de Fried, un anciano se considera frágil si presenta:", "o": ["1 criterio", "3 o más de los 5 criterios", "Una puntuación SPPB inferior a 12", "Más de 80 años"], "a": 1, "e": "Criterios: pérdida de peso involuntaria, agotamiento, baja actividad, marcha lenta y debilidad de prensión. Con 1-2 es prefrágil."}, {"q": "La batería SPPB (Short Physical Performance Battery) evalúa:", "o": ["Fuerza de prensión, peso y fatiga", "Equilibrio, velocidad de la marcha y levantarse de una silla 5 veces", "Estado cognitivo y del ánimo", "Riesgo de úlceras por presión"], "a": 1, "e": "Puntúa sobre 12 y permite asignar el pasaporte Vivifrail (A, B, C o D)."}, {"q": "Un anciano con una puntuación SPPB de 5 corresponde, según Vivifrail, al pasaporte:", "o": ["B (frágil)", "A (discapacidad)", "C (prefrágil)", "D (robusto)"], "a": 0, "e": "A: 0-3; B: 4-6; C: 7-9; D: 10-12. Se añade \"+\" si hay riesgo de caídas."}, {"q": "En el anciano frágil con riesgo de desnutrición que realiza ejercicio de fuerza, el aporte proteico recomendado es de:", "o": ["0,5 g/kg/día", "0,8 g/kg/día", "3 g/kg/día", "1,2-1,5 g/kg/día"], "a": 3, "e": "Los suplementos proteicos aprovechan mejor la síntesis muscular si se toman en los 30-60 minutos posteriores al ejercicio."}, {"q": "Un paciente con diabetes tipo 1 tiene una glucemia de 280 mg/dl con cetonas positivas antes de hacer ejercicio. La recomendación es:", "o": ["Hacer ejercicio vigoroso para bajar la glucemia", "Tomar 15 g de hidratos y empezar", "No hacer ejercicio, porque está contraindicado", "Hacer ejercicio ligero durante 2 horas"], "a": 2, "e": "Sin insulina suficiente, el ejercicio activa hormonas contrarreguladoras y empeora la cetoacidosis. Con < 90 mg/dl se toman 15 g de hidratos antes."}, {"q": "Durante la contracción muscular, la entrada de glucosa en el músculo a través de los GLUT-4:", "o": ["Es independiente de la insulina", "Requiere un pico de insulina", "Se bloquea", "Solo ocurre en ayunas"], "a": 0, "e": "Por eso el ejercicio mejora el control glucémico y puede producir hipoglucemias si no se ajusta la pauta."}, {"q": "En la rehabilitación cardiaca, la enfermera de Atención Primaria es la principal responsable de la:", "o": ["Fase I hospitalaria", "Fase II ambulatoria supervisada", "Fase III de mantenimiento comunitario", "Prueba de esfuerzo inicial"], "a": 2, "e": "La intensidad se pauta entre el 40% y el 70% de la FC de reserva y se detiene si el Borg modificado supera 5."}, {"q": "La técnica correcta de la espirometría de incentivo en el posoperatorio consiste en:", "o": ["Soplar con fuerza por la boquilla para elevar las bolas", "Inspirar lenta y profundamente por la boquilla y mantener el aire 3-5 segundos", "Realizar inspiraciones rápidas y repetidas", "Toser con la boquilla en la boca"], "a": 1, "e": "El objetivo es la inspiración máxima sostenida para reexpandir alvéolos; los dispositivos de volumen son superiores a los de flujo."}, {"q": "En una embarazada sin complicaciones, la recomendación de actividad física es:", "o": ["Reposo relativo durante todo el embarazo", "Deportes de contacto para mantener la forma", "Solo ejercicio en decúbito supino", "Al menos 150 minutos semanales de actividad aeróbica moderada, evitando el alto impacto"], "a": 3, "e": "Están contraindicados en caso de rotura de membranas, amenaza de parto prematuro, placenta previa persistente o preeclampsia."}, {"q": "La OMS recomienda que los niños y adolescentes de 5 a 17 años realicen:", "o": ["Un promedio de 60 minutos diarios de actividad moderada a vigorosa", "150 minutos semanales, como los adultos", "30 minutos dos veces por semana", "Solo actividades de fuerza"], "a": 0, "e": "Además deben incluir actividades de fortalecimiento muscular y óseo al menos 3 días por semana."}, {"q": "Ante un paciente en quimioterapia con fatiga oncológica intensa, la recomendación con más evidencia es:", "o": ["Reposo absoluto en cama", "Evitar cualquier movimiento hasta acabar el tratamiento", "Ejercicio anaeróbico intenso", "Ejercicio adaptado de intensidad ligera-moderada, preferentemente en los días valle entre ciclos"], "a": 3, "e": "El reposo prolongado agrava la fatiga; el ejercicio preserva la masa magra y ayuda a prevenir el linfedema."}]},
25: {"tema": 25, "titulo": "Valoración y cuidados de enfermería en personas con nutrición enteral y parenteral", "programa": "Valoración y cuidados de enfermería en personas con nutrición enteral y parenteral: desnutrición relacionada con la enfermedad, respuesta metabólica a la agresión, cribado y valoración nutricional, vías de acceso, sondas, verificación, tolerancia y cuidados de la nutrición enteral, fórmulas, nutrición parenteral periférica y central, seguridad, prevención de infecciones, complicaciones y síndrome de realimentación.", "preguntas": [{"q": "Un politraumatizado ingresa hipotenso, frío y mal perfundido (fase ebb de Cuthbertson). Respecto a la nutrición:", "o": ["Debe iniciarse nutrición enteral inmediata para mejorar la inmunidad", "Debe iniciarse nutrición parenteral total de inmediato", "Está contraindicada hasta su estabilización, por riesgo de isquemia mesentérica", "Debe darse una dieta oral hiperproteica"], "a": 2, "e": "En la fase de choque el flujo esplácnico está comprometido. La nutrición precoz se inicia en la fase flow, ya estabilizado."}, {"q": "Un paciente crítico con sepsis conserva su tejido graso pero presenta edemas generalizados, ascitis y una albúmina muy baja. Corresponde a:", "o": ["Kwashiorkor (desnutrición proteica aguda)", "Marasmo", "Estado nutricional normal", "Obesidad sarcopénica"], "a": 0, "e": "El marasmo es crónico y caquéctico, sin edemas; el kwashiorkor es agudo, por estrés, y su aspecto edematoso engaña."}, {"q": "El cribado nutricional de todo paciente que ingresa en un hospital debe realizarse:", "o": ["Solo si lo solicita el médico", "En las primeras 24-48 horas del ingreso", "Al alta", "Únicamente en mayores de 80 años"], "a": 1, "e": "Si el cribado es positivo, se realiza una valoración nutricional completa y se planifica el soporte."}, {"q": "En el NRS-2002, el paciente se considera en riesgo nutricional cuando:", "o": ["Su IMC es superior a 25", "Tiene más de 65 años", "Ha perdido peso en el último año", "La puntuación total es ≥ 3, sumando 1 punto si tiene 70 años o más"], "a": 3, "e": "Combina estado nutricional y gravedad de la enfermedad; es la herramienta de elección en el adulto hospitalizado."}, {"q": "En la herramienta MUST, una puntuación total de 2 o más indica:", "o": ["Riesgo bajo", "Riesgo medio", "Necesidad de repetir el cribado al año", "Riesgo alto de malnutrición"], "a": 3, "e": "0 riesgo bajo, 1 riesgo medio y ≥ 2 riesgo alto, que requiere intervención."}, {"q": "Un paciente de 78 años obtiene 9 puntos en el MNA-SF. Se interpreta como:", "o": ["Estado nutricional normal", "Riesgo de malnutrición", "Malnutrición establecida", "Puntuación no valorable"], "a": 1, "e": "12-14 normal; 8-11 riesgo de malnutrición; 0-7 malnutrición."}, {"q": "La valoración global subjetiva (VGS) se caracteriza por:", "o": ["Basarse en la albúmina y los linfocitos", "Ser un cribado automático informático", "Basarse en la anamnesis y la exploración física, clasificando en A, B o C", "Aplicarse solo en niños"], "a": 2, "e": "A: bien nutrido; B: desnutrición leve-moderada o sospecha; C: desnutrición grave."}, {"q": "Para comprobar si la nutrición artificial iniciada hace 5 días está siendo eficaz, el parámetro más útil es la:", "o": ["Prealbúmina, por su vida media de unos 2 días", "Albúmina", "Transferrina", "Hemoglobina"], "a": 0, "e": "La albúmina (≈ 21 días) refleja la desnutrición crónica y se altera con la inflamación; la transferrina sube en ferropenia y embarazo."}, {"q": "Es una contraindicación absoluta de la nutrición enteral:", "o": ["La obstrucción intestinal mecánica completa", "La disfagia tras un ictus", "La enfermedad de Crohn estable", "El paciente oncológico con anorexia"], "a": 0, "e": "También lo son el íleo paralítico grave, la hemorragia digestiva activa, la perforación, la peritonitis difusa y la isquemia mesentérica."}, {"q": "Cuando la nutrición enteral se prevé durante más de 4-6 semanas, el acceso de elección es:", "o": ["La sonda nasogástrica de PVC", "La sonda nasoyeyunal", "La gastrostomía endoscópica percutánea (PEG)", "La nutrición parenteral"], "a": 2, "e": "El uso prolongado de sondas nasales produce lesiones nasales, sinusitis y erosión esofágica."}, {"q": "Por una sonda nasoyeyunal la nutrición debe administrarse:", "o": ["En bolos de 300 ml cada 4 horas", "En infusión continua con bomba", "Por gravedad en bolos rápidos", "Solo de noche en bolo"], "a": 1, "e": "El intestino delgado no tiene función de reservorio; los bolos producen diarrea y dumping."}, {"q": "En la escala French de las sondas, una unidad equivale a:", "o": ["1 mm de diámetro interno", "3 mm de diámetro externo", "0,1 mm de diámetro", "0,33 mm de diámetro externo"], "a": 3, "e": "A mayor número French, mayor grosor. Las sondas de nutrición suelen ser de 8-12 Fr."}, {"q": "La sonda de Salem se caracteriza por:", "o": ["Ser de silicona fina para nutrición", "Tener una sola luz", "Tener doble luz, una de ellas como respiradero que evita succionar la mucosa gástrica", "Usarse para lavado gástrico con 30 Fr"], "a": 2, "e": "La de Levin tiene una sola luz; la de Ewald (25-30 Fr) se usa en lavados gástricos urgentes."}, {"q": "El método de referencia para confirmar la posición de una sonda nasogástrica antes de iniciar la nutrición es:", "o": ["La radiografía", "La auscultación epigástrica tras insuflar aire", "Pedir al paciente que hable", "Observar si salen burbujas al sumergir el extremo"], "a": 0, "e": "A pie de cama puede medirse el pH del aspirado (ácido < 4-5), teniendo en cuenta que los IBP lo alteran."}, {"q": "Respecto a la auscultación del aire insuflado para comprobar la sonda nasogástrica, es correcto que:", "o": ["Es el método de elección", "Es obligatoria en intubados", "Sustituye a la radiografía", "Está desaconsejada porque puede dar falsos positivos"], "a": 3, "e": "El sonido de una sonda mal colocada en el árbol bronquial puede transmitirse al epigastrio."}, {"q": "Un paciente con nutrición enteral continua a 60 ml/h tiene un residuo gástrico de 250 ml, sin distensión ni vómitos. Lo correcto es:", "o": ["Suspender la nutrición 24 horas", "Reinfundir el residuo y continuar al mismo ritmo", "Cambiar a nutrición parenteral", "Retirar la sonda"], "a": 1, "e": "El umbral actual de alarma es > 500 ml. Si el residuo preocupa, se valoran procinéticos antes de suspender."}, {"q": "En la nutrición enteral continua por bomba, la sonda debe lavarse con 20-30 ml de agua:", "o": ["Cada 4-6 horas", "Una vez al día", "Solo si se obstruye", "Cada 15 minutos"], "a": 0, "e": "También antes y después de cada toma intermitente y antes, entre y después de cada fármaco."}, {"q": "Respecto a la administración de fármacos en pacientes con nutrición enteral, es correcto:", "o": ["Mezclarlos todos en la bolsa de nutrición", "Triturar los comprimidos de liberación prolongada", "Administrarlos por separado, lavando la sonda entre ellos y sin añadirlos a la bolsa", "Introducir las cápsulas blandas enteras"], "a": 2, "e": "Añadirlos a la bolsa coagula las proteínas y obstruye la sonda; las formas retard y entéricas no se trituran."}, {"q": "Ante una diarrea en un paciente con nutrición enteral, antes de suspender la nutrición se debe:", "o": ["Diluir la fórmula al 50% siempre", "Pasar a una fórmula monomérica", "Suspenderla de inmediato", "Revisar los fármacos (sorbitol, antibióticos, laxantes) y descartar Clostridioides difficile"], "a": 3, "e": "Se puede reducir la velocidad o la concentración y valorar fibra soluble o fórmulas peptídicas."}, {"q": "En un paciente con EPOC grave retenedor de CO₂ que precisa nutrición enteral, la fórmula indicada es:", "o": ["Rica en hidratos de carbono", "Con mayor proporción de grasas y menos hidratos", "Hipoproteica", "Monomérica"], "a": 1, "e": "Los hidratos generan más CO₂ (mayor cociente respiratorio) y dificultan el destete."}, {"q": "La fórmula enteral específica para la insuficiencia hepática con encefalopatía es:", "o": ["Rica en aminoácidos aromáticos", "Hiperproteica estándar", "Rica en aminoácidos ramificados y pobre en aromáticos", "Rica en potasio"], "a": 2, "e": "Los aminoácidos aromáticos actúan como falsos neurotransmisores y favorecen la encefalopatía."}, {"q": "En una pancreatitis aguda grave con sonda yeyunal, la fórmula más adecuada es la:", "o": ["Oligomérica o peptídica", "Polimérica estándar", "Rica en grasas", "Hipoproteica renal"], "a": 0, "e": "El páncreas inflamado no aporta enzimas suficientes; los péptidos se absorben sin necesidad de digestión pancreática."}, {"q": "La nutrición parenteral periférica se caracteriza por:", "o": ["Admitir osmolaridades superiores a 1.500 mOsm/l", "Tener una osmolaridad inferior a 800 mOsm/l y una duración máxima de 7-10 días", "Poder mantenerse durante años", "Aportar más de 25 g de nitrógeno al día"], "a": 1, "e": "Las mezclas hiperosmolares requieren un catéter central con la punta en la vena cava superior."}, {"q": "La protección frente a la luz de las bolsas y sistemas de nutrición parenteral es obligatoria en:", "o": ["Todos los adultos del hospital", "Solo en pacientes oncológicos", "Solo si la bolsa contiene insulina", "Menores de 2 años"], "a": 3, "e": "La luz genera peróxidos a partir de lípidos y aminoácidos, especialmente dañinos en neonatos y lactantes."}, {"q": "Según Bacteriemia Zero, el apósito transparente del catéter venoso central se cambia:", "o": ["Cada 24 horas", "Cada 48 horas", "Cada 7 días, o antes si está sucio, húmedo o despegado", "Solo al retirar el catéter"], "a": 2, "e": "El apósito de gasa (sudoración o sangrado) se cambia cada 48 horas."}, {"q": "Los sistemas de infusión por los que pasa una nutrición parenteral con lípidos deben cambiarse:", "o": ["Cada 24 horas", "Cada 72 horas", "Cada 7 días", "Solo si se obstruyen"], "a": 0, "e": "Los lípidos son un medio de cultivo idóneo. Además, la luz de la nutrición es exclusiva y se desinfecta el conector antes de usarlo."}, {"q": "Ante un catéter venoso central que no refluye por sospecha de trombo, la actuación correcta es:", "o": ["Forzar el lavado con una jeringa de 2 ml", "Retirar siempre el catéter", "Administrar un bolo de heparina a presión", "No forzar con jeringas pequeñas e instilar uroquinasa según protocolo y aspirar"], "a": 3, "e": "Las jeringas pequeñas generan presiones que pueden romper el catéter; se usan jeringas de ≥ 10 ml."}, {"q": "La hipoglucemia de rebote en un paciente con nutrición parenteral central se produce sobre todo:", "o": ["Al iniciar la nutrición", "Al suspender bruscamente la infusión", "Al cambiar el apósito", "Al añadir lípidos"], "a": 1, "e": "Se previene reduciendo el ritmo a la mitad en las últimas 1-2 horas o con un suero glucosado al 10% al mismo ritmo."}, {"q": "Según los criterios NICE, es un criterio mayor de alto riesgo de síndrome de realimentación:", "o": ["IMC inferior a 16 kg/m²", "IMC inferior a 25 kg/m²", "Edad superior a 65 años", "Ayuno de 2 días"], "a": 0, "e": "Otros criterios mayores: pérdida de peso > 15% en 3-6 meses, ingesta mínima > 10 días o K, P o Mg bajos antes de alimentar."}, {"q": "Para prevenir el síndrome de realimentación en un paciente de alto riesgo, se recomienda:", "o": ["Aportar el 100% de los requerimientos desde el primer día", "Administrar la tiamina solo si aparecen síntomas", "Evitar los controles de fósforo", "Empezar con 10-15 kcal/kg/día, subir en 4-7 días y dar tiamina antes de la primera toma"], "a": 3, "e": "\"Start low, go slow\", con control diario de fósforo, magnesio y potasio durante las primeras 72 horas."}]},
26: {"tema": 26, "titulo": "Cuidados de enfermería en la gestante y la puérpera. Educación maternal. Lactancia natural", "programa": "Valoración y cuidados de enfermería en la mujer gestante: alimentación, higiene y cambios fisiológicos. Educación maternal. Problemas más frecuentes durante la gestación. Valoración y cuidados de enfermería en la puérpera: cambios fisiológicos y psicológicos. Lactancia natural.", "preguntas": [{"q": "La anemia fisiológica del embarazo se debe principalmente a:", "o": ["La falta de hierro en la dieta", "La hemodilución, porque el volumen plasmático aumenta más que la masa eritrocitaria", "La destrucción de hematíes por la placenta", "El déficit de ácido fólico"], "a": 1, "e": "El volumen plasmático aumenta en torno al 50% y la masa eritrocitaria un 20-30%, lo que reduce la hemoglobina y el hematocrito."}, {"q": "Respecto a la función renal en el embarazo, es correcto que:", "o": ["El filtrado glomerular disminuye", "La creatinina aumenta de forma fisiológica", "La creatinina disminuye, y un valor de 0,9-1 mg/dl puede indicar alteración renal", "La glucosuria es siempre diabetes"], "a": 2, "e": "El filtrado aumenta un 50%, por lo que creatinina, urea y ácido úrico bajan; la glucosuria puede ser fisiológica."}, {"q": "La hormona responsable de la relajación del músculo liso que causa pirosis, estreñimiento y estasis urinaria en el embarazo es:", "o": ["La progesterona", "La hCG", "La relaxina", "La prolactina"], "a": 0, "e": "La relaxina actúa sobre ligamentos y articulaciones (laxitud pélvica); la hCG mantiene el cuerpo lúteo."}, {"q": "La ganancia de peso recomendada durante el embarazo en una mujer con IMC previo normal es de:", "o": ["5-9 kg", "7-11,5 kg", "12,5-18 kg", "11,5-16 kg"], "a": 3, "e": "En el 2.º y 3.er trimestre, unos 0,4 kg por semana. Bajo peso: 12,5-18 kg; sobrepeso: 7-11,5 kg; obesidad: 5-9 kg."}, {"q": "Durante el primer trimestre del embarazo, el aporte energético recomendado:", "o": ["No aumenta respecto al previo", "Aumenta en 500 kcal/día", "Debe duplicarse", "Aumenta en 1.000 kcal/día"], "a": 0, "e": "Se recomiendan unas 340 kcal/día más en el 2.º trimestre y 452 kcal/día más en el 3.º, priorizando la calidad de los alimentos."}, {"q": "Está indicada la dosis alta de ácido fólico (5 mg/día) en una gestante:", "o": ["Sana, sin antecedentes", "Que fuma", "Con diabetes pregestacional o en tratamiento con antiepilépticos", "Mayor de 25 años"], "a": 2, "e": "También en antecedentes de defecto del tubo neural, obesidad o malabsorción. La dosis general es de 0,4 mg/día desde 1-3 meses antes hasta la semana 12."}, {"q": "Para prevenir la listeriosis, se debe aconsejar a la gestante evitar:", "o": ["La fruta lavada", "Los lácteos pasteurizados", "El pescado bien cocinado", "Los quesos de pasta blanda y lácteos no pasteurizados"], "a": 3, "e": "También los patés refrigerados y los pescados ahumados en frío. La toxoplasmosis se previene evitando carnes crudas y lavando bien frutas y verduras."}, {"q": "Por su contenido en mercurio, se recomienda a la gestante evitar:", "o": ["Las sardinas y los boquerones", "El pez espada, el atún rojo y el tiburón", "Todo el pescado azul", "El pescado blanco"], "a": 1, "e": "Los grandes depredadores acumulan metilmercurio; el pescado azul pequeño aporta DHA con poco riesgo."}, {"q": "El cribado de diabetes gestacional mediante el test de O'Sullivan se realiza, en gestantes sin factores de riesgo, en las semanas:", "o": ["24-28", "8-10", "35-37", "38-40"], "a": 0, "e": "En las semanas 35-37 se recoge el exudado vaginorrectal para el estreptococo del grupo B."}, {"q": "¿Cuál de las siguientes vacunas está contraindicada durante el embarazo?", "o": ["Tdpa", "Gripe inactivada", "Vacuna frente al VRS", "Triple vírica"], "a": 3, "e": "Las vacunas de virus vivos (triple vírica, varicela, fiebre amarilla) están contraindicadas. La Tdpa se pone en cada embarazo entre las semanas 27 y 36."}, {"q": "La profilaxis antenatal sistemática con gammaglobulina anti-D se administra:", "o": ["A todas las gestantes Rh positivas en la semana 12", "A las gestantes Rh negativas no sensibilizadas (Coombs indirecto negativo) en la semana 28", "Solo después del parto", "Al recién nacido Rh negativo"], "a": 1, "e": "Tras el parto se administra antes de 72 horas si el recién nacido es Rh positivo, y también ante eventos sensibilizantes."}, {"q": "El programa de educación maternal suele comenzar alrededor de la semana:", "o": ["8", "12", "28", "38"], "a": 2, "e": "Es el momento de mayor receptividad ante el parto. Suele constar de unas 8 sesiones."}, {"q": "En la educación maternal, la respiración jadeante se enseña para:", "o": ["Aumentar la fuerza del pujo", "Relajarse entre contracciones", "Evitar empujar antes de alcanzar la dilatación completa", "Acelerar la dilatación"], "a": 2, "e": "Pujar antes de la dilatación completa puede producir edema cervical."}, {"q": "Es característico de la hiperémesis gravídica:", "o": ["Pérdida de peso superior al 5%, cetonuria y alteraciones electrolíticas", "Náuseas matutinas sin pérdida de peso", "Acidosis metabólica por pérdida de bicarbonato", "Aparición exclusiva en el tercer trimestre"], "a": 0, "e": "Cursa con hipopotasemia, hiponatremia y alcalosis metabólica; hay riesgo de encefalopatía de Wernicke (tiamina)."}, {"q": "La preeclampsia se define por la aparición de:", "o": ["Edemas maleolares en el tercer trimestre", "TA ≥ 140/90 antes de la semana 12", "Glucosuria y poliuria", "TA ≥ 140/90 después de la semana 20 con proteinuria ≥ 300 mg/24 h o daño de órgano"], "a": 3, "e": "Se considera grave con TA ≥ 160/110 o signos como cefalea, escotomas, dolor epigástrico, plaquetopenia o alteración renal o hepática."}, {"q": "Durante la administración de sulfato de magnesio en una preeclampsia grave, la enfermera debe vigilar:", "o": ["Solo la glucemia", "La frecuencia respiratoria, el reflejo rotuliano y la diuresis, con gluconato cálcico disponible", "La temperatura cada 8 horas", "El peso diario exclusivamente"], "a": 1, "e": "Signos de toxicidad: FR < 12, abolición del reflejo rotuliano y diuresis < 30 ml/h. El antídoto es el gluconato cálcico."}, {"q": "En la sobrecarga oral de glucosa de 100 g, se diagnostica diabetes gestacional cuando:", "o": ["Dos o más valores están alterados", "Un solo valor está alterado", "La glucemia basal es mayor de 80 mg/dl", "El O'Sullivan es mayor de 120 mg/dl"], "a": 0, "e": "Valores límite: 105, 190, 165 y 145 mg/dl. Con un solo valor alterado se habla de intolerancia y se repite en 3-4 semanas."}, {"q": "La principal hormona responsable de la resistencia a la insulina en el embarazo es:", "o": ["La oxitocina", "La relaxina", "El lactógeno placentario humano", "La hormona antidiurética"], "a": 2, "e": "El embarazo es diabetogénico para asegurar el paso de glucosa al feto."}, {"q": "La complicación fetal más característica de la diabetes gestacional mal controlada es:", "o": ["El bajo peso al nacer", "La hipercalcemia fetal", "La anemia fetal", "La macrosomía"], "a": 3, "e": "El feto produce más insulina (hiperinsulinismo), que actúa como factor de crecimiento y retrasa la maduración pulmonar."}, {"q": "En el puerperio normal, el fondo uterino deja de palparse por vía abdominal hacia el:", "o": ["Día 2", "Día 10", "Día 30", "Día 45"], "a": 1, "e": "Tras el parto se palpa a la altura del ombligo (globo de Pinard) y desciende 1-2 cm al día."}, {"q": "La causa más frecuente de hemorragia posparto es:", "o": ["Los desgarros del canal del parto", "La retención de restos placentarios", "La atonía uterina", "Las coagulopatías"], "a": 2, "e": "Regla de las 4T: tono (≈ 70%), trauma (≈ 20%), tejido y trombina. Ante la atonía: masaje uterino y uterotónicos."}, {"q": "Una puérpera presenta un sangrado rojo y continuo con el útero duro y bien contraído. La causa más probable es:", "o": ["Una lesión del canal del parto (trauma)", "Una atonía uterina", "Una retención de orina", "Unos loquios normales"], "a": 0, "e": "Si el útero está contraído y sigue sangrando, hay que buscar desgarros o hematomas."}, {"q": "En una puérpera, el fondo uterino se palpa por encima del ombligo y desviado a la derecha. Lo primero es:", "o": ["Administrar oxitocina", "Comprobar y vaciar la vejiga, porque es probable un globo vesical", "Realizar un legrado", "Iniciar antibióticos"], "a": 1, "e": "La vejiga distendida desplaza el útero, impide su contracción y favorece la hemorragia."}, {"q": "Los loquios serosos, de color rosado o marrón, aparecen habitualmente entre los días:", "o": ["1 y 3", "15 y 30", "40 y 60", "4 y 10"], "a": 3, "e": "Rubra (días 1-3/4), serosa (días 4-10) y alba (desde la 2.ª semana). Si huelen mal, sospechar endometritis."}, {"q": "La tristeza puerperal (maternity blues) se caracteriza por:", "o": ["Aparecer hacia los días 3-5 y resolverse espontáneamente en menos de 2 semanas", "Durar más de 2 semanas con anhedonia", "Cursar con alucinaciones y delirios", "Requerir ingreso psiquiátrico"], "a": 0, "e": "Si dura más de 15 días hay que sospechar depresión posparto; la psicosis puerperal es una emergencia."}, {"q": "En la escala de depresión posparto de Edimburgo (EPDS), una puntuación de 1 en el ítem 10 (pensamientos de autolesión) obliga a:", "o": ["Repetir la escala al mes", "Nada, si la puntuación total es baja", "Una derivación urgente en menos de 24 horas", "Suspender la lactancia"], "a": 2, "e": "Cualquier respuesta distinta de 0 en el ítem 10 es una bandera roja. Una puntuación total ≥ 10 indica riesgo de depresión."}, {"q": "La prolactina, responsable de la producción de leche, se secreta en:", "o": ["La neurohipófisis", "La placenta", "El hipotálamo", "La adenohipófisis"], "a": 3, "e": "La oxitocina (eyección) procede de la neurohipófisis; la dopamina hipotalámica inhibe la prolactina."}, {"q": "En un agarre correcto al pecho se observa:", "o": ["La boca poco abierta y los labios hacia dentro", "El mentón pegado al pecho, la nariz libre y más areola visible por encima del labio superior", "Más areola visible por debajo del labio inferior", "Mejillas hundidas y chasquidos"], "a": 1, "e": "El agarre asimétrico, con la boca muy abierta y los labios evertidos, evita las grietas. Si duele, se rompe el vacío con un dedo y se recoloca."}, {"q": "Ante una ingurgitación mamaria bilateral con mamas pétreas y edematosas, la medida adecuada es:", "o": ["Aplicar frío y la técnica de presión inversa suavizante", "Aplicar calor intenso y masaje enérgico", "Suspender las tomas 24 horas", "Vendar las mamas"], "a": 0, "e": "El frío reduce el edema y la presión inversa ablanda la areola para facilitar el enganche; puede añadirse ibuprofeno."}, {"q": "Ante una mastitis puerperal unilateral con fiebre de 39 °C, la recomendación correcta es:", "o": ["Suspender la lactancia hasta que ceda la fiebre", "Dar solo el pecho sano", "Sustituir la lactancia por biberón", "Mantener la lactancia y vaciar bien el pecho afectado, junto con el tratamiento antibiótico"], "a": 3, "e": "El vaciado es la parte más importante del tratamiento. Si persiste una masa fluctuante, hay que descartar un absceso."}, {"q": "La imagen muestra a un lactante mamando. ¿Cómo se valora este agarre?", "o": ["Incorrecto: el mentón no debería tocar el pecho", "Incorrecto: la nariz debería quedar hundida en la mama", "Correcto: boca muy abierta, labios evertidos, mentón pegado al pecho y más areola visible por encima que por debajo", "Correcto solo si el bebé succiona de la punta del pezón"], "a": 2, "e": "Agarre asimétrico profundo: labios evertidos, mentón tocando el pecho, nariz libre, más areola visible arriba y el pezón llega al paladar blando. Succionar solo la punta del pezón produce grietas y mala transferencia de leche.", "img": "img/preguntas/t26-agarre.jpg"}]},
27: {"tema": 27, "titulo": "Cuidados de la mujer en el climaterio. Fomento de hábitos saludables. Educación para la salud individual y grupal", "programa": "Cuidados de la mujer en el climaterio: conceptos, fisiopatología, manifestaciones clínicas, valoración y escalas, plan de cuidados, tratamiento. Fomento de hábitos saludables. Educación para la salud individual y grupal y programa educativo. Cribados en Atención Primaria.", "preguntas": [{"q": "La menopausia se define como:", "o": ["El periodo de transición con irregularidad menstrual", "La aparición de sofocos", "Una FSH superior a 25 UI/l", "El cese definitivo de la menstruación, diagnosticado de forma retrospectiva tras 12 meses de amenorrea sin otra causa"], "a": 3, "e": "El climaterio es el proceso completo; la menopausia es solo la fecha de la última regla."}, {"q": "Se considera menopausia precoz o insuficiencia ovárica primaria cuando el cese menstrual ocurre antes de los:", "o": ["35 años", "40 años", "45 años", "50 años"], "a": 1, "e": "La edad media es de unos 50 años; se considera tardía por encima de los 55."}, {"q": "La etapa del climaterio en la que suelen presentarse más síntomas y peor calidad de vida es la:", "o": ["Premenopausia temprana", "Posmenopausia tardía", "Perimenopausia", "Etapa reproductiva tardía"], "a": 2, "e": "En la perimenopausia aparecen la irregularidad menstrual y los síntomas vasomotores."}, {"q": "El marcador más precoz del declive de la reserva ovárica es:", "o": ["La hormona antimülleriana (AMH)", "La FSH", "El estradiol", "La LH"], "a": 0, "e": "Primero baja la AMH, luego la inhibina B, después sube la FSH y por último cae el estradiol. La AMH no varía con el ciclo."}, {"q": "El perfil hormonal característico del estado menopáusico es:", "o": ["FSH baja y estradiol alto", "FSH y LH elevadas con estradiol bajo", "FSH normal y progesterona alta", "Prolactina elevada"], "a": 1, "e": "Al desaparecer el retrocontrol negativo de los estrógenos, la hipófisis aumenta las gonadotropinas: estado hipergonadotrópico e hipoestrogénico."}, {"q": "En la posmenopausia, el estrógeno predominante es:", "o": ["La estrona, producida por aromatización de andrógenos en el tejido adiposo", "El estradiol de origen ovárico", "El estriol placentario", "La progesterona"], "a": 0, "e": "A más tejido graso, más conversión periférica de androstendiona en estrona."}, {"q": "En una mujer posmenopáusica con obesidad, el exceso de estrona sin oposición de progesterona aumenta especialmente el riesgo de:", "o": ["Osteoporosis", "Cáncer de cérvix", "Hipotiroidismo", "Hiperplasia y cáncer de endometrio"], "a": 3, "e": "Sin ovulación no hay progesterona que frene el estímulo estrogénico sobre el endometrio."}, {"q": "En el síndrome genitourinario de la menopausia, el pH vaginal:", "o": ["Se vuelve más ácido (< 3)", "No se modifica", "Aumenta por encima de 5 por la pérdida de glucógeno y de lactobacilos", "Baja por exceso de lactobacilos"], "a": 2, "e": "Sin glucógeno desaparecen los lactobacilos de Döderlein y se pierde la acidez protectora; aumentan las infecciones."}, {"q": "Ante sofocos en una mujer perimenopáusica, una prueba obligada para el diagnóstico diferencial es:", "o": ["La TSH", "La amilasa", "La troponina", "El PSA"], "a": 0, "e": "La disfunción tiroidea puede producir una clínica superponible."}, {"q": "Según los criterios densitométricos de la OMS, existe osteoporosis cuando el T-score es:", "o": ["Superior a −1", "Entre −1 y −2,5", "Igual o inferior a −2,5", "Positivo"], "a": 2, "e": "Entre −1 y −2,5 es osteopenia; si además hay fractura por fragilidad, osteoporosis grave."}, {"q": "Tras la menopausia, el perfil lipídico se modifica de forma característica con:", "o": ["Aumento del HDL y descenso del LDL", "Descenso de todas las fracciones", "Sin cambios", "Descenso del HDL y aumento del LDL y los triglicéridos"], "a": 3, "e": "Junto a la grasa abdominal y la resistencia a la insulina, el riesgo cardiovascular de la mujer se iguala al del varón."}, {"q": "Respecto a la escala Cervantes, es correcto que:", "o": ["Mide el riesgo de fractura", "Mide la calidad de vida en la menopausia y una puntuación mayor indica peor calidad de vida", "Es un cribado de depresión", "Una puntuación alta indica mejor calidad de vida"], "a": 1, "e": "Está validada en población española; su versión corta tiene 16 ítems."}, {"q": "La herramienta FRAX de la OMS:", "o": ["Diagnostica la osteoporosis", "Calcula el riesgo absoluto de fractura a 10 años y puede usarse sin densitometría", "Mide la densidad mineral ósea", "Evalúa la calidad de vida"], "a": 1, "e": "Utiliza variables clínicas como la edad, el IMC, el tabaco, el alcohol, los corticoides y la fractura de cadera en los padres."}, {"q": "En la escala de ansiedad y depresión de Goldberg, se considera probable:", "o": ["Ansiedad con 4 o más respuestas afirmativas y depresión con 2 o más", "Ansiedad con 2 o más y depresión con 4 o más", "Ambas con 1 respuesta afirmativa", "Ambas con 9 respuestas afirmativas"], "a": 0, "e": "El umbral de la depresión es más bajo, lo que permite detectarla precozmente."}, {"q": "La ingesta diaria de calcio recomendada en una mujer de 55 años es de:", "o": ["500 mg", "800 mg", "1.200 mg", "2.000 mg"], "a": 2, "e": "Hasta los 50 años se recomiendan 1.000 mg/día; a partir de los 51, 1.200 mg/día, junto con vitamina D."}, {"q": "El consumo excesivo de sal y cafeína perjudica la salud ósea porque:", "o": ["Impiden la síntesis de vitamina D", "Bloquean los osteoblastos", "Aumentan la absorción de fósforo", "Aumentan la excreción urinaria de calcio"], "a": 3, "e": "Actúan como \"ladrones de calcio\" al favorecer su pérdida por la orina."}, {"q": "Respecto a las isoflavonas de soja en el climaterio, es correcto que:", "o": ["Actúan sobre el receptor estrogénico beta y su eficacia depende de la capacidad de la flora intestinal para producir equol", "Estimulan intensamente el endometrio", "Son eficaces en todas las mujeres por igual", "Están contraindicadas en todas las mujeres"], "a": 0, "e": "Pueden reducir los sofocos; solo un 30-50% de las mujeres occidentales produce equol."}, {"q": "El factor aislado más importante para prevenir caídas y fracturas en la mujer posmenopáusica es:", "o": ["La toma de isoflavonas", "El reposo", "El entrenamiento de fuerza contra resistencia", "La gimnasia hipopresiva"], "a": 2, "e": "El ejercicio aeróbico y de fuerza previene la pérdida ósea y mejora el equilibrio."}, {"q": "El hábito modificable que más adelanta la edad de la menopausia es:", "o": ["El consumo de café", "El sedentarismo", "La dieta vegetariana", "El tabaquismo"], "a": 3, "e": "La nicotina produce apoptosis folicular acelerada; además acelera la pérdida ósea."}, {"q": "En el tratamiento de la sequedad vaginal, la diferencia entre hidratantes y lubricantes es que:", "o": ["Ambos se usan solo durante el coito", "El hidratante se usa de forma continua para mejorar la mucosa y el lubricante a demanda durante el coito", "El lubricante contiene estrógenos", "El hidratante solo se usa antes del coito"], "a": 1, "e": "Los lubricantes deben ser preferentemente de base acuosa para no dañar el látex del preservativo."}, {"q": "Una mujer con útero que usa estrógenos vaginales a dosis bajas para el síndrome genitourinario:", "o": ["No necesita tomar progestágenos, por su absorción sistémica mínima", "Debe tomar progesterona oral siempre", "Debe realizarse una biopsia endometrial mensual", "Debe suspenderlos a los 3 meses obligatoriamente"], "a": 0, "e": "Son el tratamiento médico de primera elección del síndrome genitourinario aislado."}, {"q": "La terapia hormonal sistémica de la menopausia debe iniciarse, para ser segura, en mujeres:", "o": ["De cualquier edad", "Mayores de 65 años", "Menores de 60 años o con menos de 10 años desde la menopausia", "Solo tras 20 años de menopausia"], "a": 2, "e": "Es el tratamiento de elección de los sofocos moderados-graves dentro de esa ventana de oportunidad."}, {"q": "Es una contraindicación absoluta de la terapia hormonal sistémica de la menopausia:", "o": ["Los sofocos intensos", "Una hemorragia genital no filiada", "La osteopenia", "La edad de 52 años"], "a": 1, "e": "También el cáncer de mama o estrógeno-dependiente, el tromboembolismo venoso, la enfermedad arterial activa y la hepatopatía aguda grave."}, {"q": "En una mujer en tratamiento con tamoxifeno por cáncer de mama que presenta sofocos intensos, el fármaco de elección es:", "o": ["La terapia hormonal sistémica", "La paroxetina", "Los estrógenos orales", "La venlafaxina"], "a": 3, "e": "La paroxetina inhibe el CYP2D6 y reduce la eficacia del tamoxifeno, por lo que está contraindicada."}, {"q": "El fezolinetant es un tratamiento no hormonal de los sofocos que actúa como:", "o": ["Antagonista del receptor de neuroquinina 3 (NK3) en el hipotálamo", "Estrógeno sintético", "Inhibidor de la recaptación de serotonina", "Antiepiléptico"], "a": 0, "e": "Bloquea los receptores NK3 de las neuronas KNDy del centro termorregulador, sin actividad estrogénica."}, {"q": "En una entrevista educativa individual, la secuencia recomendada de técnicas es:", "o": ["Información, análisis y expresión", "Solo información", "Análisis, información y expresión", "Expresión (preguntas abiertas), análisis y, por último, información"], "a": 3, "e": "Empezar dando información es propio de un modelo paternalista. El silencio terapéutico es una técnica activa."}, {"q": "El tamaño recomendado de un taller grupal de educación para la salud en el climaterio es de:", "o": ["2-4 personas", "4-6 personas", "8-15 personas", "30-40 personas"], "a": 2, "e": "Con menos personas no se genera dinámica de grupo y con más no se garantiza la participación."}, {"q": "La técnica de la foto-palabra en un taller de climaterio pertenece al grupo de técnicas de:", "o": ["Desarrollo de habilidades", "Investigación en el aula, para aflorar ideas y sentimientos previos", "Exposición magistral", "Evaluación final"], "a": 1, "e": "La tormenta de ideas también es de investigación en el aula; el role-playing y los talleres prácticos son de desarrollo de habilidades."}, {"q": "En una mujer de 52 años, el cribado de cáncer de cérvix se realiza mediante:", "o": ["Determinación del VPH cada 5 años", "Citología anual", "Citología cada 3 años", "Colposcopia bienal"], "a": 0, "e": "Entre los 35 y los 65 años el cribado se basa en el test de VPH; a los 65 se da de alta si los resultados previos fueron negativos."}, {"q": "El cribado poblacional de cáncer de mama consiste en:", "o": ["Mamografía anual desde los 40 años", "Ecografía cada 3 años", "Autoexploración mensual como único método", "Mamografía cada 2 años entre los 50 y los 69 años"], "a": 3, "e": "El de cáncer colorrectal es la sangre oculta en heces cada 2 años entre los 50 y los 69 años."}]},
28: {"tema": 28, "titulo": "Valoración y cuidados de enfermería del recién nacido sano. Detección precoz de enfermedades endocrino-metabólicas. Parámetros de desarrollo y crecimiento. Respuesta evolutiva", "programa": "Adaptación extrauterina, atención inmediata en paritorio (piel con piel, clampaje, Apgar, profilaxis), valoración física y somatometría, Silverman-Anderson, edad gestacional (Capurro, Ballard), cuidados en planta y al alta, cribados neonatales (talón, hipoacusia, cardiopatías congénitas), crecimiento, reflejos arcaicos e hitos del desarrollo psicomotor.", "preguntas": [{"q": "Un recién nacido acaba de nacer y está cubierto de líquido amniótico sobre el abdomen materno. ¿Cuál es el principal mecanismo de pérdida de calor en ese momento?", "o": ["Radiación", "Conducción", "Evaporación", "Convección"], "a": 2, "e": "En el momento del nacimiento, con la piel mojada, la pérdida dominante es por evaporación; por eso la primera medida es secarlo con paños calientes y retirar los húmedos. Ya seco en la cuna, pasa a predominar la radiación."}, {"q": "Ante el frío, el recién nacido produce calor fundamentalmente mediante:", "o": ["El escalofrío o tiritona muscular", "La termogénesis no tiritante: metabolismo de la grasa parda estimulado por noradrenalina", "La vasodilatación periférica", "La glucogenólisis muscular por actividad voluntaria"], "a": 1, "e": "El neonato no tirita de forma eficaz. Produce calor por termogénesis química no tiritante: el sistema simpático libera noradrenalina, que activa la oxidación de la grasa parda (interescapular, nuca, axilas y zona perirrenal)."}, {"q": "El surfactante pulmonar, que evita el colapso alveolar al final de la espiración, es sintetizado por:", "o": ["Los neumocitos tipo I", "Los macrófagos alveolares", "Las células caliciformes bronquiales", "Los neumocitos tipo II"], "a": 3, "e": "El surfactante (fosfolípidos, sobre todo dipalmitoilfosfatidilcolina, y proteínas) lo producen los neumocitos tipo II. Su síntesis empieza hacia la semana 24 y alcanza la madurez funcional hacia las semanas 34-35."}, {"q": "El cierre funcional del conducto arterioso tras el nacimiento está mediado principalmente por:", "o": ["El aumento de la PaO₂ y el descenso de las prostaglandinas (PGE₂) placentarias", "El descenso de la PaO₂ y el aumento de las prostaglandinas", "El aumento de la presión en la aurícula derecha", "El cese del flujo de la vena umbilical"], "a": 0, "e": "El ductus se contrae por la subida de la presión parcial de oxígeno arterial y la caída de las prostaglandinas de origen placentario. El cese del flujo umbilical explica el cierre del conducto venoso, y el aumento de presión en la aurícula izquierda, el del agujero oval."}, {"q": "Un recién nacido a término de 12 horas de vida presenta tinte ictérico en piel y conjuntivas. ¿Cuál es la valoración correcta?", "o": ["Es una ictericia fisiológica por inmadurez de la glucuroniltransferasa", "Es normal si el niño realiza bien las tomas", "Se debe a la lactancia materna y no requiere actuación", "Se considera patológica y requiere determinar la bilirrubina de forma urgente"], "a": 3, "e": "Toda ictericia que aparece en las primeras 24 horas de vida es patológica por definición y exige estudio urgente (bilirrubina, test de Coombs). La fisiológica aparece después de las 24 horas, habitualmente al 2.º-3.er día, y desaparece hacia el 7.º-10.º."}, {"q": "El hijo de madre diabética mal controlada tiene alto riesgo de hipoglucemia en las primeras horas porque:", "o": ["Presenta hiperinsulinismo por hiperplasia de las células beta pancreáticas fetales", "Tiene un déficit congénito de insulina", "Sufre una resistencia periférica a la insulina", "Recibe un exceso de glucosa por la leche materna"], "a": 0, "e": "La hiperglucemia materna mantenida provoca en el feto hiperplasia de las células beta e hiperinsulinismo. Al cortar el cordón cesa el aporte de glucosa materna, pero la insulina sigue alta y la glucemia del neonato cae rápidamente."}, {"q": "¿Cuál es el parámetro más importante y de mayor valor pronóstico del test de Apgar?", "o": ["La coloración de la piel", "El tono muscular", "La respuesta refleja a estímulos", "La frecuencia cardíaca"], "a": 3, "e": "El ítem más importante del Apgar es el pulso (frecuencia cardíaca). El que más tarda en alcanzar los 2 puntos es la coloración, porque la acrocianosis es un fenómeno normal en las primeras horas."}, {"q": "Al minuto de vida, un neonato presenta cuerpo rosado con manos y pies cianóticos, frecuencia cardíaca de 130 lpm, mueca al estímulo, ligera flexión de extremidades y llanto fuerte. Su puntuación de Apgar es:", "o": ["5", "6", "7", "8"], "a": 2, "e": "Acrocianosis = 1; FC > 100 = 2; mueca = 1; ligera flexión = 1; llanto fuerte = 2. Total: 7, que corresponde a un neonato con adaptación normal (7-10)."}, {"q": "La profilaxis de la enfermedad hemorrágica del recién nacido a término se realiza con:", "o": ["Vitamina K1, 1 mg intramuscular en el vasto externo (cara anterolateral del muslo)", "Vitamina K1, 1 mg intramuscular en el cuadrante superoexterno del glúteo", "Vitamina K1, 1 mg intramuscular en el deltoides", "Vitamina D3, 400 UI por vía oral"], "a": 0, "e": "Se administra vitamina K1 (fitomenadiona) 1 mg IM en el vasto externo. La región glútea está prohibida en el neonato por el riesgo de lesionar el nervio ciático. El déficit afecta a los factores II, VII, IX y X."}, {"q": "Respecto a la profilaxis de la oftalmia neonatal, es correcto:", "o": ["El nitrato de plata al 1% (método de Credé) es el tratamiento de elección", "Se aplica pomada de eritromicina al 0,5% o tetraciclina al 1% desde el canto interno hacia el externo", "Debe lavarse el ojo con suero tras aplicar la pomada", "Solo se realiza si la madre tiene una infección gonocócica confirmada"], "a": 1, "e": "Se usa pomada de eritromicina 0,5% o tetraciclina 1% en el saco conjuntival inferior, del canto interno al externo, sin lavado posterior. El nitrato de plata está desaconsejado por la conjuntivitis química que produce."}, {"q": "El hijo de una madre con HBsAg positivo debe recibir:", "o": ["Solo la vacuna de la hepatitis B a los 2 meses, según el calendario", "Solo inmunoglobulina antihepatitis B en las primeras 72 horas", "La vacuna y la inmunoglobulina en la misma jeringa y el mismo muslo", "La vacuna de la hepatitis B y la inmunoglobulina específica en las primeras 12 horas, en lugares anatómicos distintos"], "a": 3, "e": "Si la madre es portadora (HBsAg positivo) o su estado es desconocido, el recién nacido recibe en las primeras 12 horas la primera dosis de vacuna y la inmunoglobulina específica (0,5 ml), por vía IM en muslos distintos. Si la madre es negativa, se sigue el calendario (2, 4 y 11 meses)."}, {"q": "¿En cuál de las siguientes situaciones NO está indicado el pinzamiento tardío del cordón y debe pinzarse de inmediato?", "o": ["Recién nacido a término vigoroso con llanto enérgico", "Recién nacido no vigoroso que precisa reanimación inmediata", "Parto vaginal de una madre primípara", "Recién nacido que va a iniciar el contacto piel con piel"], "a": 1, "e": "El clampaje tardío (1-3 minutos, al cesar el latido) es lo recomendado: aumenta los depósitos de hierro y en prematuros reduce la hemorragia intraventricular. Se pinza de inmediato si el niño necesita reanimación, hay desprendimiento de placenta o rotura del cordón."}, {"q": "En el test de Silverman-Anderson, una puntuación de 0 indica:", "o": ["Dificultad respiratoria grave", "Ausencia de dificultad respiratoria", "Dificultad respiratoria moderada", "Que el recién nacido precisa intubación"], "a": 1, "e": "En el Silverman, al contrario que en el Apgar, cuanto menos puntos mejor: 0 es ausencia de dificultad respiratoria, 1-3 leve, 4-6 moderada y 7-10 grave. La respiración en balancín (disociación toracoabdominal marcada) puntúa 2."}, {"q": "Tras un parto instrumental, aparece a las pocas horas una tumefacción craneal limitada al hueso parietal, que no cruza las suturas. Lo más probable es:", "o": ["Un cefalohematoma", "Un caput succedaneum", "Un moldeamiento cefálico fisiológico", "Una fontanela anterior abombada"], "a": 0, "e": "El cefalohematoma es una hemorragia subperióstica: respeta las suturas, aparece horas después y tarda semanas en resolverse; puede causar ictericia tardía. El caput succedaneum es un edema subcutáneo presente desde el nacimiento, que cruza las suturas y se reabsorbe en 24-48 horas."}, {"q": "En la exploración del cordón umbilical se observan solo una arteria y una vena. Esto:", "o": ["Es una variante normal sin repercusión", "Indica una infección del cordón", "Obliga a descartar malformaciones asociadas, sobre todo renales", "Predice una caída precoz del cordón"], "a": 2, "e": "El cordón normal tiene 2 arterias y 1 vena rodeadas por la gelatina de Wharton. La arteria umbilical única es un marcador que obliga a descartar malformaciones, especialmente genitourinarias (renales), cardiovasculares y cromosómicas."}, {"q": "La maniobra de Barlow para la detección de la displasia evolutiva de cadera consiste en:", "o": ["Abducción de las caderas con presión anterior sobre el trocánter para reducir una cadera luxada", "Extensión completa de las caderas con las rodillas juntas", "Rotación externa de las caderas en decúbito prono", "Aducción de las caderas flexionadas con presión hacia atrás para comprobar si la cadera es luxable"], "a": 3, "e": "Barlow es la maniobra luxante: aducción con presión axial posterior (la cadera inestable «bota» y sale). Ortolani es la reductora: abducción con presión anterior sobre el trocánter (la cadera luxada «entra» con un chasquido)."}, {"q": "Para estimar la edad gestacional de un prematuro de unas 25 semanas ingresado en la UCI neonatal, la herramienta más adecuada es:", "o": ["El método de Capurro somático", "El test de Nuevo Ballard", "El test de Apgar", "El test de Silverman-Anderson"], "a": 1, "e": "El Nuevo Ballard (12 criterios: 6 físicos y 6 neuromusculares) es fiable desde la semana 20 y es de elección en la prematuridad extrema. El Capurro pierde validez por debajo de las 29-30 semanas porque los signos físicos puntúan cero."}, {"q": "En España, el cuidado del cordón umbilical recomendado en el recién nacido sano es:", "o": ["Alcohol de 70° en cada cambio de pañal", "Clorhexidina al 4% de forma rutinaria", "Cura en seco: agua y jabón solo si se ensucia y secado meticuloso", "Povidona yodada dos veces al día hasta su caída"], "a": 2, "e": "En entornos con buenas condiciones higiénicas se recomienda la cura en seco. Los antisépticos de rutina retrasan la caída del cordón; la clorhexidina se reserva para países de baja renta, partos domiciliarios sin recursos y UCI neonatales."}, {"q": "Al preparar un biberón con fórmula en polvo, el agua debe estar a una temperatura de:", "o": ["Temperatura ambiente (≈ 25 °C) para no destruir vitaminas", "Unos 37 °C, la temperatura corporal", "Unos 40 °C, templada", "70 °C o más en el momento de añadir el polvo"], "a": 3, "e": "La fórmula en polvo no es estéril y puede contener Cronobacter sakazakii (meningitis, sepsis, enterocolitis). El agua hervida debe estar a ≥ 70 °C al mezclar el polvo; después se enfría antes de dárselo al niño."}, {"q": "Para prevenir el síndrome de muerte súbita del lactante, la postura recomendada para dormir es:", "o": ["Decúbito supino (boca arriba)", "Decúbito lateral para evitar la aspiración", "Decúbito prono", "Semisentado con almohada"], "a": 0, "e": "El decúbito supino es la única postura segura. El decúbito prono y el lateral (inestable, el niño rueda a prono) están desaconsejados. Colchón firme y cuna sin almohadas, cojines, peluches ni protectores."}, {"q": "La suplementación con vitamina D en el lactante consiste en:", "o": ["200 UI/día solo en los prematuros", "1.000 UI/día a todos los recién nacidos durante 6 meses", "400 UI/día a los menores de 12 meses alimentados con lactancia materna o mixta", "No es necesaria si recibe lactancia materna exclusiva"], "a": 2, "e": "Se recomiendan 400 UI/día de vitamina D3 a todos los menores de 12 meses con lactancia materna o mixta; con fórmula también, salvo que ingiera más de un litro al día, algo poco habitual."}, {"q": "Sobre la técnica de la prueba del talón, es correcto:", "o": ["Puncionar en el centro de la curvatura del talón", "Desechar la primera gota y puncionar en los laterales de la superficie plantar del talón", "Exprimir con fuerza el talón para obtener sangre rápidamente", "Aplicar varias gotas superpuestas en cada círculo"], "a": 1, "e": "Se punciona en los laterales del talón (el centro arriesga osteomielitis del calcáneo), se desecha la primera gota (diluida con líquido tisular), no se «ordeña» (hemólisis) y cada círculo se rellena con una sola gota que traspase el papel."}, {"q": "En el cribado neonatal de la fibrosis quística, el marcador que se determina en la prueba del talón es:", "o": ["La TSH", "La fenilalanina", "La 17-hidroxiprogesterona", "La tripsina inmunorreactiva (TIR)"], "a": 3, "e": "Fibrosis quística: tripsina inmunorreactiva (si está elevada, test del sudor). Hipotiroidismo congénito: TSH. Fenilcetonuria: fenilalanina. Hiperplasia suprarrenal congénita: 17-hidroxiprogesterona."}, {"q": "¿En qué recién nacido está indicado obtener una segunda muestra de la prueba del talón?", "o": ["En un neonato que ha recibido una transfusión de hematíes", "En un neonato a término alimentado con fórmula", "En un neonato nacido por cesárea", "En un neonato con ictericia fisiológica"], "a": 0, "e": "Se repite (≈ 15 días o al alta) en prematuros < 37 semanas o < 1.500 g (la TSH sube tarde), en transfundidos (la sangre del donante enmascara los resultados; si es posible, se toma antes de transfundir) y con nutrición parenteral (falsos positivos)."}, {"q": "Un prematuro ha estado 7 días en la UCI neonatal recibiendo gentamicina. Para el cribado de hipoacusia, lo correcto es:", "o": ["Realizar otoemisiones acústicas; si «pasa», se descarta la hipoacusia", "Realizar potenciales evocados auditivos de tronco cerebral como prueba inicial", "No realizar cribado hasta los 6 meses", "Realizar una audiometría tonal"], "a": 1, "e": "Las otoemisiones solo valoran la cóclea y no detectan la neuropatía auditiva retrococlear. En los niños con factores de riesgo (UCI neonatal > 5 días, aminoglucósidos, gran prematuridad, TORCH, exanguinotransfusión, meningitis) la prueba inicial son los potenciales evocados de tronco."}, {"q": "En el cribado de cardiopatías congénitas críticas con pulsioximetría, se considera resultado negativo (normal):", "o": ["SpO₂ ≥ 90% en la mano izquierda", "SpO₂ ≥ 95% en el pie, sin medir la mano", "SpO₂ ≥ 95% en la mano derecha y en un pie, con diferencia entre ambos ≤ 3%", "SpO₂ entre 90 y 94% en ambas extremidades"], "a": 2, "e": "Se mide en la mano derecha (preductal) y en un pie (postductal). Negativo: ≥ 95% en ambos con diferencia ≤ 3%. Positivo: ≤ 90%. Dudoso (repetir): 90-94% o diferencia > 3%."}, {"q": "Respecto al crecimiento del lactante sano, es correcto:", "o": ["Duplica el peso de nacimiento hacia los 4-5 meses y lo triplica al año", "Duplica el peso al año y lo triplica a los 2 años", "Pierde un 20% del peso los primeros días y lo recupera al mes", "La talla aumenta unos 10 cm durante el primer año"], "a": 0, "e": "Tras perder un 7-10% del peso los primeros 3-5 días (recuperado hacia el 10.º-14.º día), el lactante duplica el peso hacia los 4-5 meses y lo triplica al año. La talla aumenta unos 25 cm (≈ 50%) y el perímetro cefálico unos 12 cm el primer año."}, {"q": "Señale la afirmación correcta sobre el reflejo de Landau:", "o": ["No está presente al nacer; aparece hacia los 4 meses", "Su ausencia en un recién nacido de 48 horas indica parálisis cerebral", "Desaparece hacia el mes de vida", "Es un reflejo arcaico que se explora con la caída brusca de la cabeza"], "a": 0, "e": "El Landau no existe en el recién nacido: aparece a los 4 meses (extensión de tronco y cabeza en suspensión ventral) y persiste hasta el año o más. La caída brusca de la cabeza es la maniobra del reflejo de Moro."}, {"q": "Al explorar el reflejo de Moro, un recién nacido extiende con fuerza el brazo derecho pero mantiene el izquierdo flácido y pegado al cuerpo. Debe sospecharse:", "o": ["Una variante normal de la transición", "Una hipoglucemia", "Una fractura de clavícula izquierda o una parálisis braquial obstétrica", "Una ausencia fisiológica del reflejo por la edad"], "a": 2, "e": "El Moro es simétrico en el neonato sano. Un Moro asimétrico obliga a descartar fractura de clavícula homolateral (el traumatismo óseo obstétrico más frecuente) o lesión del plexo braquial (parálisis de Erb-Duchenne)."}, {"q": "Señale el hito del desarrollo correctamente relacionado con su edad aproximada:", "o": ["Sedestación estable sin apoyo a los 2 meses", "Sostén cefálico completo a los 9 meses", "Pinza fina pulgar-índice a los 4 meses", "Angustia ante la separación de la figura de apego hacia los 8 meses"], "a": 3, "e": "La angustia por separación aparece hacia los 8 meses. El sostén cefálico se logra a los 3-4 meses, la sedestación sin apoyo hacia los 7-8 meses y la pinza fina hacia los 10-12 meses."}, {"q": "La maniobra de la imagen (cadera en aducción y presión hacia atrás para intentar luxarla) es la de:", "o": ["Ortolani", "Barlow", "Galeazzi", "Moro"], "a": 1, "e": "Barlow = provocación: intenta luxar una cadera inestable (aducción + presión posterior). Ortolani = reducción: abducción con presión anterior, se nota el «clunk» de entrada. Galeazzi valora la dismetría de las rodillas en niños mayores.", "img": "img/preguntas/t28-barlow.jpg"}]},
29: {"tema": 29, "titulo": "Cuidados de enfermería en la infancia. Higiene y salud bucodental, alimentación, prevención de accidentes y malos tratos, y vacunación", "programa": "Cuidados de enfermería en la infancia: valoración, crecimiento y desarrollo psicomotor. Programa de salud bucodental (PADI) y flúor. Higiene, sueño seguro, lactancia y alimentación complementaria. Prevención de accidentes y sistemas de retención infantil. Detección de malos tratos y protocolo de Murcia. Vacunación infantil. Promoción de hábitos saludables.", "preguntas": [{"q": "En la revisión de un niño de 2 años, su talla se sitúa en el percentil 3, igual que en todos los controles previos. ¿Cuál es la interpretación correcta?", "o": ["Debe iniciarse un estudio de malabsorción de forma inmediata", "Un percentil bajo aislado y estable no es patológico; lo que alarma es cruzar percentiles o la caída de la velocidad de crecimiento", "Indica siempre un déficit de hormona del crecimiento", "Debe derivarse a endocrinología pediátrica de forma urgente"], "a": 1, "e": "El percentil es una medida de distribución, no de salud. Un niño que crece de forma constante en su carril, aunque sea el percentil 3, puede estar sano. Lo que orienta a patología es el cruce de percentiles en controles sucesivos o la desaceleración de la velocidad de crecimiento (cm/año)."}, {"q": "Respecto al test de Denver II, es correcto:", "o": ["Es un test de inteligencia que proporciona el cociente intelectual", "Evalúa únicamente la motricidad gruesa", "Solo se aplica a partir de los 6 años", "Valora la maduración en cuatro áreas: personal-social, motor fino-adaptativa, lenguaje y motor grueso"], "a": 3, "e": "El Denver II (como la tabla Haizea-Llevant) es una prueba de cribado del desarrollo, no de inteligencia. Explora cuatro áreas: personal-social, motor fino-adaptativa, lenguaje y motor grueso."}, {"q": "¿Cuál de los siguientes hallazgos constituye una señal de alarma del desarrollo psicomotor?", "o": ["No se sienta sin apoyo a los 5 meses", "No camina solo a los 12 meses", "No camina de forma autónoma a los 18 meses", "No ha gateado a los 9 meses"], "a": 2, "e": "La marcha autónoma suele adquirirse entre los 12 y 15 meses; no caminar a los 18 meses es una señal de alarma. La sedestación sin apoyo es esperable a los 6-7 meses (alarma a los 9) y el gateo puede no darse en niños sanos."}, {"q": "Sobre la erupción dentaria temporal, es correcto:", "o": ["El primer diente en salir es el primer molar, hacia los 4 meses", "El primer diente es el incisivo central superior, hacia los 3 meses", "Los caninos son los primeros en erupcionar, hacia los 6 meses", "El primer diente suele ser el incisivo central inferior, hacia los 6-8 meses"], "a": 3, "e": "La erupción comienza con el incisivo central inferior hacia los 6-8 meses. El orden es incisivos, primeros molares, caninos y segundos molares. Si a los 12-14 meses no ha salido ningún diente, se estudia (hipotiroidismo, raquitismo, displasias)."}, {"q": "¿Cuál de las siguientes prestaciones NO está incluida en el Programa de Atención Dental Infantil (PADI) de la Región de Murcia?", "o": ["La ortodoncia", "El sellado de fisuras de molares permanentes", "La revisión anual de la cavidad oral", "La extracción de dientes temporales"], "a": 0, "e": "El PADI incluye revisión anual, educación sanitaria, flúor tópico en alto riesgo, sellados, tartrectomía, obturaciones y endodoncias de dientes permanentes, extracciones y traumatismos. Nunca incluye la ortodoncia ni los empastes de dientes temporales."}, {"q": "Un niño de 8 años incluido en el PADI presenta una caries en un molar temporal. Según el programa:", "o": ["Se financia la obturación del molar temporal", "Se financia la endodoncia del molar temporal", "No se financia la obturación del diente temporal; sí su extracción si no es viable", "Se financia la colocación de una corona"], "a": 2, "e": "El PADI prioriza la dentición definitiva: las obturaciones y endodoncias solo se cubren en dientes permanentes. De los dientes temporales solo se financia la extracción."}, {"q": "Desde la erupción del primer diente hasta los 2 años, la recomendación de pasta dental es:", "o": ["No usar pasta fluorada hasta los 6 años", "Pasta de 1.000 ppm de flúor en cantidad mínima (grano de arroz)", "Pasta de 1.450 ppm en cantidad similar a un guisante", "Pasta de 500 ppm y enjuagar con abundante agua"], "a": 1, "e": "Desde el primer diente se usa pasta de 1.000 ppm en una cantidad mínima (grano de arroz). De 2 a 6 años, la cantidad de un guisante (1.000-1.450 ppm) y por encima de los 6 años, 1.450 ppm y 1-2 cm de pasta."}, {"q": "Sobre el cepillado dental en la infancia, es correcto:", "o": ["Tras el cepillado hay que enjuagar abundantemente con agua", "El cepillado más importante es el de la mañana", "La supervisión de los padres es necesaria solo hasta los 3 años", "Se debe escupir sin enjuagar y el cepillado nocturno es el más importante"], "a": 3, "e": "Tras el cepillado se escupe sin enjuagar para que el flúor actúe sobre el esmalte. El nocturno es el más importante porque durante el sueño disminuye la saliva. Los padres supervisan el cepillado hasta los 8 años aproximadamente."}, {"q": "Para prevenir la dermatitis del pañal se recomienda:", "o": ["Aplicar polvos de talco en cada cambio", "Usar toallitas con alcohol y perfume", "Cambios frecuentes, limpiar preferentemente con agua y dejar la zona al aire", "Espaciar los cambios para no irritar la piel"], "a": 2, "e": "La dermatitis del pañal se debe a la maceración y al contacto con heces y orina. Se previene con cambios frecuentes, limpieza con agua y aireación. El talco está contraindicado por el riesgo de inhalación y neumonitis química."}, {"q": "¿En cuál de estas situaciones está contraindicado el colecho?", "o": ["Madre que amamanta a su hijo", "Padres fumadores, aunque no fumen en la habitación", "Lactante a término sano", "Cama de adultos con colchón firme"], "a": 1, "e": "El colecho está contraindicado si los padres fuman (aunque no lo hagan en la habitación), han consumido alcohol, drogas o psicofármacos, si el bebé es prematuro o de bajo peso, o si se practica en sofás o sillones."}, {"q": "El calostro se caracteriza por:", "o": ["Ser la leche más rica en grasa y de mayor volumen", "Producirse a partir del día 15 posparto", "Tener un contenido muy bajo en inmunoglobulinas", "Su elevado contenido en IgA secretora y lactoferrina"], "a": 3, "e": "El calostro (3-5 primeros días) es espeso y amarillento, de poco volumen y muy rico en IgA secretora, lactoferrina y células defensivas (la «primera vacuna»). Facilita la expulsión del meconio. La leche de transición va del día 5 al 14 y la madura, desde el día 15."}, {"q": "Según la OMS, la recomendación de actividad física para niños y adolescentes es:", "o": ["Al menos 60 minutos diarios de intensidad moderada a vigorosa, con actividades de fortalecimiento muscular y óseo al menos 3 días por semana", "150 minutos semanales, que pueden concentrarse en el fin de semana", "30 minutos diarios de intensidad ligera", "Solo natación y ciclismo, por ser deportes sin impacto"], "a": 0, "e": "La OMS recomienda una media de 60 minutos diarios de actividad moderada a vigorosa y fortalecimiento muscular y óseo al menos 3 días por semana. El ejercicio del fin de semana no compensa el sedentarismo diario y, para el hueso, son mejores las actividades de impacto (Ley de Wolff)."}, {"q": "¿Cuál de las siguientes es una contraindicación verdadera de la lactancia materna?", "o": ["Mastitis materna", "Madre portadora de hepatitis B con el niño inmunizado", "Galactosemia clásica en el recién nacido", "Ictericia fisiológica del recién nacido"], "a": 2, "e": "Las contraindicaciones reales son muy pocas: VIH materno (en países desarrollados), HTLV I/II, galactosemia clásica del niño y consumo materno de drogas de abuso, antineoplásicos o radiofármacos. La mastitis y la hepatitis B (con el niño inmunizado) no contraindican la lactancia."}, {"q": "Las espinacas y las acelgas no deben ofrecerse antes del año de vida porque:", "o": ["Son muy alergénicas", "Pueden contener esporas de Clostridium botulinum", "Provocan una sobrecarga renal de proteínas", "Su contenido en nitratos puede causar metahemoglobinemia"], "a": 3, "e": "Los nitratos de las verduras de hoja verde se transforman en nitritos, que oxidan la hemoglobina a metahemoglobina (cianosis, «bebé azul»). El botulismo es el riesgo de la miel y la sobrecarga renal, el de la leche de vaca entera."}, {"q": "Respecto a los alimentos potencialmente alergénicos (huevo, pescado) en la alimentación complementaria, la recomendación actual es:", "o": ["Retrasarlos hasta los 12-18 meses para prevenir alergias", "No introducirlos antes de los 3 años", "Introducirlos sin retrasarlos, a partir de los 6 meses, para favorecer la tolerancia", "Evitarlos hasta los 2 años si hay antecedentes familiares de alergia"], "a": 2, "e": "Retrasar la introducción de los alérgenos no previene la alergia y puede aumentarla. Se recomienda introducirlos a partir de los 6 meses, de uno en uno, para inducir tolerancia. El gluten se introduce entre los 4 y 11 meses en pequeñas cantidades."}, {"q": "La primera causa de muerte accidental en los menores de 1 año es:", "o": ["La asfixia (atragantamiento o sueño inseguro)", "Los accidentes de tráfico", "El ahogamiento en piscinas", "Las intoxicaciones por medicamentos"], "a": 0, "e": "En el lactante predomina la asfixia: aspiración de cuerpos extraños, mala postura al dormir o colecho inseguro. A partir del año, la primera causa son los accidentes de tráfico; las intoxicaciones predominan entre 1 y 4 años."}, {"q": "Un niño de 2 años ha ingerido lejía. Los padres llaman al centro de salud. La indicación correcta es:", "o": ["Provocar el vómito para eliminar el tóxico", "Darle leche para neutralizar el cáustico", "Darle agua abundante para diluirlo", "No provocar el vómito, llamar al Servicio de Información Toxicológica y acudir al hospital con el envase"], "a": 3, "e": "Ante cáusticos nunca se provoca el vómito: el producto volvería a quemar el esófago y existe riesgo de aspiración. Tampoco se dan leche, agua ni remedios caseros. Se llama al Servicio de Información Toxicológica y se traslada al niño con el envase."}, {"q": "Para calcular la superficie corporal quemada en un lactante, el método más adecuado es:", "o": ["La regla de los 9 de Wallace", "La tabla de Lund y Browder", "La regla de la palma de la mano en todos los casos", "El índice de Baux"], "a": 1, "e": "La regla de los 9 no se ajusta a las proporciones del niño, cuya cabeza es mucho mayor (≈ 18-19% en el lactante). La tabla de Lund y Browder ajusta los porcentajes según la edad."}, {"q": "La normativa de sistemas de retención infantil R129 (i-Size) se caracteriza por:", "o": ["Clasificar las sillas por peso y permitir ir a favor de la marcha desde los 9 kg", "Clasificar las sillas por edad del niño", "Clasificar las sillas por altura y obligar a viajar a contramarcha al menos hasta los 15 meses", "Prohibir los anclajes ISOFIX"], "a": 2, "e": "La i-Size clasifica por estatura, obliga a la contramarcha hasta al menos los 15 meses (se recomienda hasta los 4 años), usa ISOFIX y exige pruebas de impacto lateral. La antigua R44/04 clasificaba por peso (grupos 0, 0+, I, II y III)."}, {"q": "En España, es obligatorio que los menores utilicen un sistema de retención infantil homologado cuando su estatura es:", "o": ["Igual o inferior a 135 cm", "Igual o inferior a 120 cm", "Igual o inferior a 150 cm, sin excepción", "Hasta los 12 años, con independencia de su estatura"], "a": 0, "e": "El SRI es obligatorio hasta los 135 cm. Entre 135 y 150 cm se puede usar el SRI o el cinturón del vehículo, aunque se recomienda mantener el elevador hasta los 150 cm."}, {"q": "Un lactante debe viajar, por una de las excepciones legales, en el asiento delantero en una silla a contramarcha. ¿Qué es imprescindible?", "o": ["Nada, la contramarcha ya es suficiente protección", "Que el niño pese más de 9 kg", "Girar la silla a favor de la marcha", "Desactivar el airbag frontal del pasajero"], "a": 3, "e": "Con una silla a contramarcha en el asiento delantero hay que desactivar el airbag frontal: su despliegue golpearía el respaldo de la silla con un traumatismo letal. Si no se puede desactivar, el niño no puede viajar en ese asiento."}, {"q": "Según la Ley Orgánica 8/2021 (LOPIVI), ante una sospecha de violencia sobre un menor, el profesional sanitario:", "o": ["Solo debe comunicarlo si tiene una certeza absoluta", "Tiene el deber de comunicar cualquier sospecha fundada, sin necesidad de pruebas concluyentes", "Debe hablar primero con la familia para que cesen los hechos", "Solo debe comunicarlo si el menor lo solicita"], "a": 1, "e": "La LOPIVI establece un deber de comunicación cualificado para los profesionales sanitarios: deben comunicar las sospechas fundadas sin esperar a tener pruebas. Avisar antes a la familia puede poner en riesgo al menor."}, {"q": "¿Cuál es la forma de maltrato infantil más frecuente?", "o": ["La violencia sexual", "El maltrato físico", "La negligencia", "El trastorno facticio aplicado a otro"], "a": 2, "e": "La negligencia es la tipología más prevalente (más de la mitad de las notificaciones): omisión de los cuidados básicos de alimentación, higiene, salud (vacunas, citas) o escolarización."}, {"q": "Un niño acude a urgencias con lesiones graves por castigo físico y los padres exigen llevárselo a casa. La actuación correcta es:", "o": ["Ingreso de protección del menor, parte de lesiones al Juzgado de Guardia y aviso a las Fuerzas y Cuerpos de Seguridad", "Darle el alta y citar a la familia en servicios sociales otro día", "Hablar con los padres y pedirles que no vuelva a ocurrir", "Respetar la decisión de los padres y registrarlo en la historia"], "a": 0, "e": "En situaciones urgentes o de riesgo inminente se trata al niño, se emite el parte de lesiones al Juzgado de Guardia, se avisa a la policía y se realiza un ingreso de protección: nunca se entrega el menor a sus presuntos agresores. Los casos no urgentes siguen la vía de la hoja de notificación y el trabajador social."}, {"q": "El síndrome del niño zarandeado se caracteriza por la tríada:", "o": ["Fracturas costales, quemaduras y hematomas", "Hemorragia subdural, hemorragias retinianas y edema cerebral", "Fiebre, exantema y adenopatías", "Hipotermia, bradicardia e hipotensión"], "a": 1, "e": "Las sacudidas violentas producen aceleración-desaceleración del encéfalo: hemorragia subdural, hemorragias retinianas y edema cerebral, a menudo sin lesiones externas visibles. Tiene alta mortalidad y secuelas."}, {"q": "Si la triple vírica y la varicela no se administran el mismo día, el intervalo mínimo entre ambas es de:", "o": ["4 semanas", "1 semana", "10 días", "No hay intervalo mínimo"], "a": 0, "e": "Dos vacunas vivas parenterales se administran el mismo día (en lugares distintos) o separadas al menos 4 semanas, para evitar la interferencia en la respuesta de la segunda. Entre vacunas inactivadas no hay intervalo mínimo."}, {"q": "Sobre la vacuna frente al rotavirus, es correcto:", "o": ["Es una vacuna inactivada intramuscular", "Es una vacuna oral de virus vivos cuya primera dosis debe darse antes de las 12 semanas de vida", "Puede iniciarse a cualquier edad durante el primer año", "Se administra a los 12 y 15 meses"], "a": 1, "e": "La vacuna del rotavirus es oral y de virus vivos atenuados (2, 4 y 6 meses en la pauta de 3 dosis). La primera dosis debe administrarse pronto (antes de las 12 semanas) porque iniciarla más tarde aumenta el riesgo de invaginación intestinal."}, {"q": "El nirsevimab, administrado a los lactantes frente al virus respiratorio sincitial:", "o": ["Es una vacuna de virus atenuados", "Estimula la producción de anticuerpos propios (inmunidad activa)", "Se administra en tres dosis orales", "Es un anticuerpo monoclonal que proporciona inmunidad pasiva"], "a": 3, "e": "El nirsevimab no es una vacuna: es un anticuerpo monoclonal de vida media prolongada que confiere inmunidad pasiva. Se administra en una dosis IM al inicio de la temporada o en la maternidad, con dosis según el peso."}, {"q": "Unos padres van a llevar a la playa a su bebé de 4 meses. La recomendación de fotoprotección es:", "o": ["No aplicar fotoprotector: mantenerlo a la sombra y protegerlo con ropa, gorro y sombrilla", "Aplicar un fotoprotector de filtro químico de factor 50", "Aplicar un fotoprotector de filtro físico cada 2 horas", "Exponerlo al sol solo en las horas centrales con crema"], "a": 0, "e": "En los menores de 6 meses no se usan fotoprotectores (piel muy fina, absorción y toxicidad): se evita el sol directo y se usan barreras físicas. De 6 meses a 3 años se usan filtros físicos (óxido de zinc, dióxido de titanio) y desde los 3 años pueden usarse químicos."}, {"q": "Respecto al uso de pantallas en la infancia, la recomendación correcta es:", "o": ["En menores de 2 años, exposición nula, salvo videollamadas con familiares", "En menores de 2 años, hasta 30 minutos diarios de contenido educativo", "Entre 2 y 5 años, hasta 3 horas diarias", "Es útil usarlas durante las comidas para que el niño coma mejor"], "a": 0, "e": "Antes de los 2 años el tiempo de pantalla debe ser cero (excepto videollamadas). De 2 a 5 años, máximo 1 hora al día, con contenidos de calidad y acompañados. Nunca durante las comidas (anulan la percepción de saciedad) ni como «chupete emocional»."}]},
30: {"tema": 30, "titulo": "Valoración y cuidados de enfermería del recién nacido enfermo, de bajo peso y prematuro. Insuficiencia respiratoria, problemas gastrointestinales, deshidratación y problemas derivados del ingreso hospitalario", "programa": "Valoración del recién nacido enfermo; clasificación y cuidados del prematuro (NIDCAP, hemorragia intraventricular, retinopatía); insuficiencia respiratoria neonatal; enterocolitis necrotizante, atresia de esófago, estenosis de píloro y defectos de pared; deshidratación; ictericia y fototerapia, sepsis, abstinencia, dolor e hipoglucemia; problemas derivados de la hospitalización infantil.", "preguntas": [{"q": "En el recién nacido, se define apnea como una pausa respiratoria:", "o": ["Superior a 10 segundos en cualquier caso", "Superior a 15 segundos aunque no haya otros signos", "Superior a 20 segundos, o de menor duración si se acompaña de bradicardia o cianosis", "De cualquier duración durante el sueño"], "a": 2, "e": "La apnea es la ausencia de flujo respiratorio durante más de 20 segundos, o menos tiempo si se acompaña de bradicardia (< 100 lpm) o cianosis central. Es típica del prematuro por inmadurez del centro respiratorio."}, {"q": "Un recién nacido con un peso al nacer de 1.350 g se clasifica como:", "o": ["Muy bajo peso al nacer", "Bajo peso al nacer", "Extremado bajo peso al nacer", "Peso adecuado si nace a término"], "a": 0, "e": "Bajo peso: < 2.500 g; muy bajo peso: < 1.500 g; extremado bajo peso: < 1.000 g. La clasificación por peso es independiente de la edad gestacional."}, {"q": "Un recién nacido de 27 semanas de gestación se clasifica como:", "o": ["Prematuro tardío", "Muy prematuro", "Prematuro moderado", "Prematuro extremo"], "a": 3, "e": "Prematuro extremo: < 28 semanas; muy prematuro: 28 a 31+6; prematuro tardío: 34 a 36+6. Pretérmino es todo nacido antes de las 37 semanas."}, {"q": "Según los cuidados centrados en el desarrollo (método NIDCAP), es correcto:", "o": ["Establecer horarios fijos de manipulación cada 2 horas", "Agrupar las intervenciones para respetar el sueño y mantener al niño en flexión con nidos de contención", "Mantener una iluminación intensa para vigilar mejor al niño", "Colocar al prematuro en extensión para facilitar la ventilación"], "a": 1, "e": "El NIDCAP individualiza el cuidado: control de luz y ruido (< 45 dB), mínima manipulación agrupando técnicas para no interrumpir el sueño, contención en flexión con las manos hacia la línea media y participación de la familia. Los horarios rígidos son contrarios a este modelo."}, {"q": "Respecto a la sacarosa oral como analgesia no farmacológica en el neonato, es correcto:", "o": ["Actúa como anestésico local sobre la piel del talón", "Debe administrarse inmediatamente después del procedimiento", "Se administra por vía intravenosa en bolo", "Se administra en la parte anterior de la lengua unos 2 minutos antes y actúa por un mecanismo central (opioides endógenos)"], "a": 3, "e": "La sacarosa al 20-24% se da en la parte anterior de la lengua unos 2 minutos antes del estímulo doloroso. El sabor dulce activa el sistema opioide endógeno: el efecto es central, no local. Se potencia con la succión no nutritiva o el método canguro."}, {"q": "En la clasificación de Papile, una hemorragia intraventricular que provoca dilatación de los ventrículos, sin afectación del parénquima, corresponde al grado:", "o": ["I", "II", "III", "IV"], "a": 2, "e": "Grado I: limitada a la matriz germinal; II: intraventricular sin dilatación; III: intraventricular con dilatación ventricular; IV: con infarto hemorrágico del parénquima."}, {"q": "Para prevenir la retinopatía de la prematuridad, en los prematuros de riesgo se recomienda mantener la saturación de oxígeno entre:", "o": ["98 y 100%", "90 y 94%", "80 y 85%", "85 y 88%"], "a": 1, "e": "La retinopatía se relaciona con la hiperoxia y sus fluctuaciones. Enfermería debe ajustar las alarmas para mantener la SpO₂ entre el 90 y el 94% y evitar la hiperoxia inadvertida."}, {"q": "La escala de Wood-Downes-Ferrés se utiliza fundamentalmente para valorar:", "o": ["La edad gestacional del recién nacido", "El dolor postoperatorio", "La extensión de la ictericia", "La gravedad de la obstrucción bronquial en la bronquiolitis o la crisis asmática"], "a": 3, "e": "Valora cianosis, ventilación, sibilancias, tiraje, FR y FC. Leve 1-3, moderada 4-7, grave 8-14. La dificultad respiratoria del recién nacido se valora con el Silverman-Anderson."}, {"q": "La enfermedad de la membrana hialina se debe principalmente a:", "o": ["Un déficit de surfactante pulmonar en el recién nacido prematuro", "La aspiración de meconio en el recién nacido postérmino", "El retraso en la reabsorción del líquido pulmonar tras una cesárea", "Una infección por estreptococo del grupo B"], "a": 0, "e": "El síndrome de dificultad respiratoria del prematuro se debe al déficit de surfactante: según la ley de Laplace, la alta tensión superficial colapsa los alvéolos al final de la espiración, con hipoxemia, hipercapnia y acidosis."}, {"q": "En el estudio del líquido amniótico, indica madurez pulmonar fetal:", "o": ["Un cociente lecitina/esfingomielina menor de 1,5", "Un cociente lecitina/esfingomielina igual a 1", "Un cociente lecitina/esfingomielina mayor de 2", "La ausencia de fosfatidilglicerol"], "a": 2, "e": "Un cociente L/E > 2 y la presencia de fosfatidilglicerol indican madurez pulmonar. Un cociente < 1,5 señala un alto riesgo de enfermedad de la membrana hialina."}, {"q": "Antes de administrar surfactante exógeno, conservado en nevera, la enfermera debe:", "o": ["Calentarlo en el microondas unos segundos", "Atemperarlo de forma pasiva, por ejemplo entre las manos", "Calentarlo al baño maría a 39 °C", "Administrarlo frío directamente para conservar sus propiedades"], "a": 1, "e": "El surfactante se conserva a 2-8 °C y se atempera de forma pasiva (entre las manos). El calor directo desnaturaliza sus proteínas y, administrado frío, es muy viscoso y puede obstruir la vía aérea."}, {"q": "Un recién nacido a término, nacido por cesárea electiva sin trabajo de parto, presenta a las pocas horas FR de 75 rpm con leve dificultad respiratoria que mejora en 48 horas con oxígeno de bajo flujo. Lo más probable es:", "o": ["Taquipnea transitoria del recién nacido", "Enfermedad de la membrana hialina", "Síndrome de aspiración meconial", "Apnea del prematuro"], "a": 0, "e": "La taquipnea transitoria se debe al retraso en la reabsorción del líquido pulmonar fetal, típica de la cesárea sin trabajo de parto. Es benigna y se resuelve en 24-72 horas. La aspiración meconial es propia del término o postérmino con sufrimiento fetal."}, {"q": "El tratamiento farmacológico de mantenimiento de la apnea del prematuro es:", "o": ["La adrenalina intravenosa", "El citrato de cafeína", "El surfactante endotraqueal", "La naloxona"], "a": 1, "e": "La apnea del prematuro se debe a la inmadurez del centro respiratorio: se trata con estimulación en el episodio agudo y citrato de cafeína (metilxantina) de mantenimiento."}, {"q": "En la enterocolitis necrotizante, el signo radiológico considerado patognomónico es:", "o": ["El neumoperitoneo", "La imagen de doble burbuja", "La neumatosis intestinal (gas en la pared del intestino)", "El abdomen sin aire"], "a": 2, "e": "La neumatosis intestinal define la ECN establecida (estadio II de Bell). El gas en la vena porta indica mayor gravedad y el neumoperitoneo (estadio IIIB) indica perforación y necesidad de cirugía."}, {"q": "Ante la sospecha de enterocolitis necrotizante en un prematuro, la actuación de enfermería incluye:", "o": ["Aumentar el volumen de las tomas con fórmula", "Controlar la temperatura por vía rectal cada 4 horas", "Colocar al niño en decúbito prono con el abdomen comprimido", "Dieta absoluta, sonda orogástrica abierta a bolsa y medición seriada del perímetro abdominal"], "a": 3, "e": "Se suspende la alimentación enteral, se coloca sonda orogástrica para descomprimir y se mide el perímetro abdominal cada turno. La temperatura rectal está prohibida por el riesgo de perforación. La leche materna es el principal factor protector."}, {"q": "Un recién nacido cuya madre tuvo polihidramnios presenta salivación espumosa abundante y, al intentar pasar una sonda gástrica, se encuentra un tope a unos 10 cm. Debe sospecharse:", "o": ["Estenosis hipertrófica de píloro", "Atresia de esófago", "Enterocolitis necrotizante", "Enfermedad de Hirschsprung"], "a": 1, "e": "La atresia de esófago se sospecha por polihidramnios, sialorrea espumosa e imposibilidad de pasar la sonda. El tipo más frecuente (III, 85%) tiene bolsa proximal ciega y fístula traqueal en el cabo distal."}, {"q": "Un lactante varón de 4 semanas presenta vómitos en proyectil no biliosos tras las tomas y hambre voraz. La alteración analítica esperable es:", "o": ["Acidosis metabólica hiperclorémica", "Acidosis respiratoria", "Alcalosis metabólica hipoclorémica e hipopotasémica", "Acidosis metabólica con hiperpotasemia"], "a": 2, "e": "Es una estenosis hipertrófica de píloro. Los vómitos gástricos pierden ácido clorhídrico: alcalosis metabólica hipoclorémica e hipopotasémica. Se corrige antes de la piloromiotomía de Ramstedt. Las diarreas, en cambio, producen acidosis."}, {"q": "La actuación inicial en paritorio ante un recién nacido con gastrosquisis es:", "o": ["Introducir piernas y abdomen en una bolsa de polietileno estéril, sin comprimir, y colocarlo en decúbito lateral derecho", "Envolver las asas con gasas secas estériles y comprimir para reintroducirlas", "Cubrir las asas con compresas empapadas en povidona yodada", "Reintroducir manualmente las asas en la cavidad abdominal"], "a": 0, "e": "Las asas no tienen saco protector: se introducen en una bolsa estéril transparente para limitar la pérdida de calor y líquidos, sin presionar, y se coloca al niño en decúbito lateral derecho para no acodar los vasos mesentéricos. Las gasas secas se adhieren y dañan la serosa."}, {"q": "Respecto al onfalocele, es correcto:", "o": ["Es un defecto paraumbilical derecho sin saco", "Contiene exclusivamente asas intestinales", "Raramente se asocia a otras malformaciones", "Es un defecto central cubierto por un saco y se asocia con frecuencia a otras malformaciones"], "a": 3, "e": "El onfalocele es central, en el anillo umbilical, cubierto por un saco (amnios y peritoneo) del que sale el cordón; puede contener hígado y en más de la mitad se asocia a cardiopatías, trisomías 13 y 18 o Beckwith-Wiedemann. La gastrosquisis es paraumbilical derecha, sin saco y suele ser aislada."}, {"q": "En la deshidratación hipertónica (hipernatrémica) del lactante, es correcto:", "o": ["El signo del pliegue está siempre muy marcado y el shock es precoz", "El pliegue puede ser poco llamativo y predominan los signos neurológicos; la corrección debe ser lenta", "Es el tipo de deshidratación más frecuente", "Debe corregirse el sodio rápidamente en pocas horas"], "a": 1, "e": "En la hipertónica el agua sale de las células al espacio vascular: el volumen circulante se mantiene y la piel parece conservada («pastosa»), pero hay irritabilidad, llanto agudo, hiperreflexia o convulsiones. Se corrige en 48-72 horas para evitar el edema cerebral. La más frecuente es la isotónica."}, {"q": "Un lactante con gastroenteritis está inquieto, con ojos hundidos, bebe con avidez y el pliegue cutáneo desaparece lentamente. Según la OMS, la pauta es:", "o": ["Plan A: seguir en casa con la alimentación habitual", "Plan C: bolos intravenosos de suero fisiológico", "Plan B: solución de rehidratación oral, 50-100 ml/kg en 4 horas, con supervisión", "Dieta absoluta durante 24 horas"], "a": 2, "e": "Son signos de deshidratación moderada («algo de deshidratación»): plan B, rehidratación oral en el centro sanitario con 50-100 ml/kg en 4 horas, en pequeños sorbos. El plan C (intravenoso) se reserva para la deshidratación grave."}, {"q": "En el shock hipovolémico por deshidratación (plan C), la expansión de volumen se realiza con:", "o": ["Bolos de suero fisiológico o Ringer lactato de 10-20 ml/kg en 10-20 minutos, reevaluando tras cada bolo", "Bolos de 50 ml/kg de suero fisiológico", "Suero glucosado al 5% a 5 ml/kg en una hora", "Solución de rehidratación oral a demanda"], "a": 0, "e": "Se usan cristaloides isotónicos (suero fisiológico al 0,9% o Ringer lactato) en bolos de 10-20 ml/kg lo más rápido posible (10-20 minutos), repitiendo según la perfusión (relleno capilar, pulsos, tensión)."}, {"q": "Según la escala de Kramer, una ictericia que alcanza palmas de las manos y plantas de los pies (zona 5) se corresponde con una bilirrubina aproximada de:", "o": ["5-6 mg/dl", "7-9 mg/dl", "10-12 mg/dl", "Más de 15 mg/dl"], "a": 3, "e": "La ictericia progresa en sentido cefalocaudal: zona 1 cabeza (≈ 5-6), 2 hasta el ombligo (≈ 7-9), 3 hasta las rodillas (≈ 10-12), 4 hasta los tobillos (≈ 13-15) y 5 palmas y plantas (> 15 mg/dl)."}, {"q": "Durante la fototerapia de un recién nacido, es un cuidado correcto:", "o": ["Aplicar aceite o crema hidratante para evitar la sequedad", "Proteger los ojos con un antifaz opaco y vigilar el balance hídrico y la temperatura", "Mantener al niño vestido para evitar la hipotermia", "Restringir los líquidos para evitar la sobrecarga"], "a": 1, "e": "El niño debe estar desnudo, con protección ocular continua (que se retira en las tomas), cambios posturales y control de la temperatura y del balance hídrico, porque aumentan las pérdidas insensibles. Las cremas y aceites están contraindicados por riesgo de quemaduras."}, {"q": "El microorganismo más frecuente en la sepsis neonatal precoz (transmisión vertical) es:", "o": ["Streptococcus agalactiae (estreptococo del grupo B)", "Staphylococcus epidermidis", "Candida albicans", "Pseudomonas aeruginosa"], "a": 0, "e": "La sepsis precoz (primeras 72 horas) se debe sobre todo al estreptococo del grupo B y a E. coli; su incidencia ha bajado con el cribado al final del embarazo y la profilaxis intraparto. En la tardía (nosocomial) predomina el estafilococo coagulasa negativo."}, {"q": "Ante la sospecha de sepsis en un recién nacido, la actuación prioritaria de enfermería es:", "o": ["Esperar a que aparezca fiebre para confirmar la sospecha", "Iniciar los antibióticos y extraer los cultivos al día siguiente", "Administrar antitérmicos y reevaluar en 6 horas", "Extraer los cultivos (hemocultivo, orina, LCR) antes de administrar la primera dosis de antibiótico"], "a": 3, "e": "Las muestras para cultivo deben obtenerse siempre antes de la primera dosis de antibioterapia empírica (habitualmente ampicilina + gentamicina). La fiebre es rara en el neonato: es más típica la hipotermia o la inestabilidad térmica."}, {"q": "La escala de Finnegan se utiliza para valorar:", "o": ["El dolor postoperatorio neonatal", "La edad gestacional", "El síndrome de abstinencia neonatal", "La dificultad respiratoria"], "a": 2, "e": "La escala de Finnegan cuantifica la gravedad de la abstinencia neonatal (llanto agudo, temblores, hipertonía, succión ávida e ineficaz, vómitos, diarrea, sudoración, bostezos, estornudos) y guía el tratamiento. Las medidas no farmacológicas (arrullo, poca luz y ruido, chupete) son de primera línea."}, {"q": "La escala de valoración del dolor específica para prematuros, que incluye un factor corrector por edad gestacional, es:", "o": ["PIPP", "FLACC", "COMFORT", "CRIES"], "a": 0, "e": "La PIPP (Premature Infant Pain Profile) combina FC, saturación y gestos faciales con corrección por edad gestacional. FLACC se usa en niños sin lenguaje verbal, COMFORT en UCI pediátrica y CRIES en el dolor postoperatorio neonatal."}, {"q": "Un recién nacido hijo de madre diabética presenta temblores y una glucemia capilar de 22 mg/dl. La actuación indicada es:", "o": ["Bolo intravenoso de suero glucosado al 10% a 2 ml/kg seguido de perfusión", "Ofrecer una toma y repetir la glucemia en 2 horas", "Administrar insulina subcutánea", "Bolo de suero glucosado al 50%"], "a": 0, "e": "La hipoglucemia sintomática o grave (< 25 mg/dl) es una urgencia: bolo IV de suero glucosado al 10% (2 ml/kg) y perfusión de mantenimiento. En la hipoglucemia leve asintomática se adelanta la toma y se repite la glucemia en 30-60 minutos."}, {"q": "Un niño de 2 años ingresado sin sus padres, tras varios días de llanto intenso, deja de protestar, se muestra apático y no quiere jugar ni comer. Se encuentra en la fase de:", "o": ["Protesta", "Adaptación normal al hospital", "Desapego", "Desesperación"], "a": 3, "e": "Según Bowlby y Robertson, la ansiedad de separación pasa por protesta (llanto, rechazo: signo de vínculo sólido), desesperación (apatía, anorexia: no es adaptación, es sufrimiento) y desapego (ignora a los padres cuando vuelven). Se previene con el alojamiento conjunto de los padres."}]},
31: {"tema": 31, "titulo": "Valoración y cuidados de enfermería en el niño hospitalizado. Procesos más frecuentes. Procedimientos y técnicas de enfermería relacionadas", "programa": "Valoración del niño hospitalizado (triángulo de evaluación pediátrica, constantes, dolor, Glasgow, PEWS). Bronquiolitis, asma, laringitis y cuerpo extraño. Cámara espaciadora. Deshidratación y fluidoterapia. Estenosis de píloro, apendicitis e invaginación. Meningitis y fiebre. RCP pediátrica, accesos vasculares e intraóseos, sondaje nasogástrico, punción lumbar y recogida de orina.", "preguntas": [{"q": "En el Triángulo de Evaluación Pediátrica, el lado que mejor refleja la oxigenación y perfusión cerebral y se considera el más importante es:", "o": ["La apariencia", "El trabajo respiratorio", "La circulación cutánea", "La frecuencia cardíaca"], "a": 0, "e": "La apariencia (regla TICLS: tono, interacción, consolabilidad, mirada y llanto/lenguaje) refleja la función del sistema nervioso central. El TEP se realiza solo mirando y escuchando, sin tocar al niño ni usar aparatos; la frecuencia cardíaca no forma parte de él."}, {"q": "Para valorar el dolor de un niño ingresado en la UCI pediátrica bajo bloqueo neuromuscular, la escala más adecuada es:", "o": ["FLACC", "NIPS", "Caras de Wong-Baker", "COMFORT, que incluye variables fisiológicas"], "a": 3, "e": "Las escalas conductuales (FLACC, NIPS) pierden su fiabilidad en el niño paralizado o sedado, porque no puede mostrar respuestas motoras. Se usan escalas que incorporan variables fisiológicas, como la COMFORT."}, {"q": "Para que un niño de 4 años autoevalúe la intensidad de su dolor, la escala más adecuada es:", "o": ["La escala visual analógica numérica de 0 a 10", "La escala de caras de Wong-Baker", "La escala NIPS", "La escala de Glasgow"], "a": 1, "e": "Desde los 3-4 años el niño puede señalar en la escala de caras (Wong-Baker) la que representa su dolor. La EVA numérica se usa a partir de los 7-8 años, cuando comprende la seriación; la NIPS es para neonatos."}, {"q": "En la escala de Glasgow, la respuesta motora de descerebración ante el dolor consiste en:", "o": ["Flexión anormal de las extremidades e indica lesión cortical", "Retirada normal del miembro estimulado", "Localización del estímulo doloroso", "Extensión anormal de las extremidades e indica lesión del tronco del encéfalo"], "a": 3, "e": "La descerebración es una extensión anormal (2 puntos) que indica daño en el tronco encefálico, con peor pronóstico que la decorticación (flexión anormal, 3 puntos), propia de lesiones por encima del tronco. Un Glasgow ≤ 8 indica intubación."}, {"q": "En el lactante ingresado por bronquiolitis aguda, es un cuidado de enfermería correcto:", "o": ["Realizar lavados nasales con suero fisiológico y aspiración suave antes de las tomas y del sueño", "Administrar salbutamol nebulizado de forma sistemática a todos los niños", "Mantener al lactante en decúbito supino plano", "Ofrecer tomas abundantes y espaciadas"], "a": 0, "e": "El tratamiento es de soporte: lavados nasales y aspiración suave antes de comer y dormir, cabecera elevada unos 30°, tomas fraccionadas (menos cantidad, más a menudo) y oxígeno si lo precisa. Si la taquipnea es muy intensa, se alimenta por sonda o vía IV."}, {"q": "El tipo de aislamiento indicado en un lactante ingresado por bronquiolitis es:", "o": ["Aislamiento aéreo con mascarilla FFP2 y habitación con presión negativa", "Aislamiento protector (inverso)", "Aislamiento de contacto y de gotas", "No requiere ningún tipo de aislamiento"], "a": 2, "e": "La bronquiolitis se transmite por contacto con secreciones y fómites y por gotas: se usan bata, guantes y mascarilla. Las pruebas complementarias de rutina no están indicadas en la bronquiolitis no complicada."}, {"q": "Un niño con una crisis asmática grave y sibilancias audibles a distancia deja de tener sibilancias, pero continúa con gran trabajo respiratorio. Esto indica:", "o": ["Mejoría de la crisis; puede valorarse el alta", "Obstrucción extrema con riesgo de parada cardiorrespiratoria inminente", "Que el salbutamol ha hecho efecto completo", "Que la crisis era de origen cardíaco"], "a": 1, "e": "El tórax silente indica que la obstrucción es tan intensa que no pasa aire suficiente para generar sibilancias. Es un signo de máxima gravedad que exige soporte inmediato, nunca un signo de mejoría."}, {"q": "La tríada clínica característica de la laringitis aguda (crup) es:", "o": ["Fiebre alta, babeo y disfagia", "Sibilancias espiratorias, tos y taquipnea", "Estridor espiratorio, tos productiva y fiebre", "Tos perruna, afonía y estridor inspiratorio"], "a": 3, "e": "El crup vírico (6 meses-3 años) cursa con tos perruna o metálica, afonía y estridor inspiratorio, con buen estado general y empeoramiento nocturno. El babeo, la fiebre alta y el aspecto tóxico orientan a epiglotitis."}, {"q": "El tratamiento de primera elección en la laringitis aguda es:", "o": ["Dexametasona en dosis única (oral, IM o IV)", "Salbutamol inhalado cada 20 minutos", "Antibióticos de amplio espectro", "Adrenalina nebulizada en todos los casos, incluso leves"], "a": 0, "e": "La dexametasona en dosis única (0,15-0,6 mg/kg, máximo 10 mg) reduce los ingresos. La budesonida nebulizada es una alternativa si vomita. La adrenalina nebulizada se reserva para las laringitis moderadas y graves."}, {"q": "Tras administrar adrenalina nebulizada a un niño con laringitis moderada que mejora rápidamente, la enfermera debe:", "o": ["Darle el alta de inmediato porque ha mejorado", "Repetir la adrenalina cada 15 minutos hasta el alta", "Mantenerlo en observación al menos 3-4 horas por el riesgo de reaparición del estridor", "Pautar adrenalina nebulizada en domicilio"], "a": 2, "e": "La adrenalina actúa por vasoconstricción de la mucosa subglótica: su efecto es rápido pero breve (≈ 2 horas). Al desaparecer puede reaparecer el estridor, por lo que el niño debe vigilarse al menos 3-4 horas."}, {"q": "Un lactante de 8 meses consciente presenta una obstrucción grave de la vía aérea por cuerpo extraño (tos ineficaz y silenciosa). La actuación correcta es:", "o": ["Realizar compresiones abdominales (maniobra de Heimlich)", "Aplicar 5 golpes interescapulares seguidos de 5 compresiones torácicas, repitiendo el ciclo", "Hacer un barrido digital a ciegas en la boca", "Esperar a que tosa espontáneamente"], "a": 1, "e": "En el lactante se alternan 5 golpes en la espalda (boca abajo sobre el antebrazo, cabeza más baja) y 5 compresiones torácicas. La maniobra de Heimlich está contraindicada en menores de 1 año por el riesgo de lesión hepática. El barrido a ciegas está prohibido."}, {"q": "Un niño de 3 años se atraganta, llora y tose con fuerza. La actuación correcta es:", "o": ["Realizar de inmediato la maniobra de Heimlich", "Darle 5 golpes en la espalda", "Hacerle beber agua para que pase el objeto", "Animarle a toser y vigilarle, sin realizar maniobras de desobstrucción"], "a": 3, "e": "Con tos eficaz (llora, tose con fuerza, respira) la obstrucción es leve: se anima a toser y se vigila, sin maniobras que puedan desplazar el objeto. Las maniobras se reservan para la tos ineficaz."}, {"q": "En la administración de un inhalador presurizado con cámara espaciadora, es correcto:", "o": ["Realizar una sola pulsación cada vez y esperar 30-60 segundos antes de la siguiente, agitando de nuevo el cartucho", "Pulsar dos o tres veces seguidas para ahorrar tiempo", "No es necesario agitar el cartucho", "Retirar la mascarilla inmediatamente después de la pulsación"], "a": 0, "e": "Se agita el cartucho, se sella bien la mascarilla, se realiza una única pulsación y el niño respira dentro de la cámara unos 10 segundos (5-6 respiraciones). Varias pulsaciones seguidas hacen que las partículas choquen y precipiten en la cámara."}, {"q": "Sobre la limpieza de la cámara espaciadora, es correcto:", "o": ["Lavarla diariamente con lejía", "Secar su interior frotando con un paño limpio", "Lavarla con agua tibia y jabón y dejarla secar al aire, sin frotar", "Limpiarla con alcohol después de cada uso"], "a": 2, "e": "Se lava una vez por semana con agua tibia y jabón neutro y se deja secar al aire. Frotar el plástico genera electricidad estática que atrae y retiene el fármaco, reduciendo la dosis que llega a los pulmones."}, {"q": "En la fase de mantenimiento de la rehidratación oral de un lactante con gastroenteritis, es correcto:", "o": ["Mantener una dieta absoluta de 24 horas", "Reintroducir precozmente su alimentación habitual, sin suspender la lactancia materna ni diluir los biberones", "Sustituir la solución de rehidratación por bebidas isotónicas deportivas", "Diluir la fórmula a la mitad durante una semana"], "a": 1, "e": "Tras la rehidratación (2-4 horas), se reintroduce pronto la alimentación normal, sin suspender la lactancia ni diluir la fórmula, y se reponen las pérdidas (≈ 10 ml/kg por deposición). Las bebidas deportivas y los refrescos son hiperosmolares y empeoran la diarrea."}, {"q": "Según la regla de Holliday-Segar, las necesidades basales de líquidos de un niño de 23 kg en 24 horas son:", "o": ["2.300 ml", "1.500 ml", "1.230 ml", "1.560 ml"], "a": 3, "e": "100 ml/kg por los primeros 10 kg (1.000 ml) + 50 ml/kg de 11 a 20 kg (500 ml) + 20 ml/kg por cada kg por encima de 20 (3 × 20 = 60 ml). Total: 1.560 ml/día."}, {"q": "Aplicando la regla 4-2-1, el ritmo de mantenimiento para un niño de 15 kg es de:", "o": ["50 ml/h", "60 ml/h", "45 ml/h", "75 ml/h"], "a": 0, "e": "4 ml/kg/h por los primeros 10 kg (40 ml/h) + 2 ml/kg/h por los 5 kg siguientes (10 ml/h) = 50 ml/h."}, {"q": "Un lactante con deshidratación grave ingresa sin haber orinado en las últimas 8 horas. Respecto al potasio en la fluidoterapia:", "o": ["Debe añadirse de entrada 20 mEq de cloruro potásico al suero", "Debe administrarse en bolo IV para corregir rápidamente las pérdidas", "No debe añadirse hasta comprobar que el niño orina", "Se administra siempre por vía oral"], "a": 2, "e": "En anuria el potasio no se elimina y puede producir hiperpotasemia con arritmias y parada cardíaca. Solo se añade a la fluidoterapia tras comprobar y registrar la diuresis."}, {"q": "En el preoperatorio de un lactante con estenosis hipertrófica de píloro, la prioridad es:", "o": ["Operar de inmediato, ya que es una emergencia quirúrgica", "Dieta absoluta, sonda gástrica y corrección de la deshidratación y la alcalosis antes de la cirugía", "Mantener tomas espesadas pequeñas y frecuentes", "Administrar bicarbonato intravenoso"], "a": 1, "e": "La cirugía (piloromiotomía de Ramstedt) no es una emergencia inmediata, pero sí lo es la corrección metabólica: dieta absoluta, sonda nasogástrica a bolsa y fluidoterapia con cloruro sódico para corregir la alcalosis hipoclorémica e hipopotasémica y la deshidratación."}, {"q": "Un lactante de 9 meses presenta crisis de llanto intenso con encogimiento de piernas alternando con periodos de decaimiento, vómitos y heces con sangre y moco «en jalea de grosella». Lo más probable es:", "o": ["Gastroenteritis aguda", "Estenosis hipertrófica de píloro", "Apendicitis aguda", "Invaginación intestinal"], "a": 3, "e": "Es el cuadro clásico de invaginación intestinal (ileocólica), la causa más frecuente de obstrucción entre los 3 meses y 6 años. Puede palparse una masa «en morcilla»; la ecografía muestra el signo de la diana y se trata con reducción hidrostática o neumática por enema."}, {"q": "En el posoperatorio de una apendicectomía, la medida más eficaz para prevenir el íleo paralítico y las atelectasias es:", "o": ["Mantener reposo absoluto en cama 72 horas", "Dieta absoluta prolongada", "La deambulación precoz y progresiva", "La sonda nasogástrica sistemática"], "a": 2, "e": "La movilización temprana estimula el peristaltismo, previene el íleo y favorece la expansión pulmonar. Los diagnósticos habituales son dolor agudo, riesgo de infección (cuidado de la herida y el drenaje) y deterioro de la movilidad."}, {"q": "En la meningitis bacteriana neonatal (menores de 1 mes), los gérmenes más frecuentes son:", "o": ["Neumococo y meningococo", "Estreptococo del grupo B, Escherichia coli y Listeria monocytogenes", "Haemophilus influenzae tipo b y Staphylococcus aureus", "Virus herpes y enterovirus"], "a": 1, "e": "En el neonato predominan los gérmenes de transmisión vertical (estreptococo del grupo B, E. coli y Listeria). Por encima de los 3 meses, los más frecuentes son el neumococo y el meningococo."}, {"q": "El líquido cefalorraquídeo característico de una meningitis bacteriana es:", "o": ["Turbio, con predominio de neutrófilos, glucosa muy baja y proteínas elevadas", "Claro, con predominio de linfocitos y glucosa normal", "Claro, con menos de 5 células y glucosa normal", "Hemático, con glucosa elevada"], "a": 0, "e": "Bacteriana: LCR turbio, muchas células con predominio de polimorfonucleares, hipoglucorraquia marcada (consumo bacteriano) y proteínas muy altas. Vírica: LCR claro, pocas células con linfocitos y glucosa normal."}, {"q": "La flexión involuntaria de caderas y rodillas al flexionar pasivamente el cuello del paciente se denomina signo de:", "o": ["Kernig", "Babinski", "Brudzinski", "Lasègue"], "a": 2, "e": "El signo de Brudzinski es la flexión refleja de caderas y rodillas al flexionar el cuello. El de Kernig es el dolor o resistencia al extender la rodilla con la cadera flexionada. Ambos son signos de irritación meníngea."}, {"q": "Un niño con varicela presenta fiebre de 39 °C. El antitérmico indicado es:", "o": ["Ibuprofeno, por su efecto antiinflamatorio", "Paracetamol", "Ácido acetilsalicílico", "Alternar ibuprofeno y paracetamol"], "a": 1, "e": "En la varicela se evita el ibuprofeno (y los AINE) por su asociación con infecciones invasivas graves por estreptococo del grupo A (fascitis necrotizante). El ácido acetilsalicílico está contraindicado en niños (síndrome de Reye). El indicado es el paracetamol."}, {"q": "Durante la RCP pediátrica, tras las insuflaciones de rescate, un lactante tiene una frecuencia cardíaca de 50 lpm con palidez, mala perfusión y sin respuesta. Debe:", "o": ["Iniciar compresiones torácicas", "Esperar a que la frecuencia baje de 40 lpm", "Administrar atropina antes de cualquier otra medida", "Seguir solo con ventilaciones aunque persista la mala perfusión"], "a": 0, "e": "Se inician compresiones si no hay signos de vida o si la FC es < 60 lpm con signos de mala perfusión. Si el niño está bien perfundido, la bradicardia se trata optimizando la ventilación y la oxigenación."}, {"q": "En la RCP pediátrica realizada por dos o más reanimadores profesionales, la relación compresiones/ventilaciones es:", "o": ["30:2", "5:1", "3:1", "15:2"], "a": 3, "e": "Con dos o más reanimadores sanitarios la relación es 15:2. Las compresiones se hacen en el tercio inferior del esternón, deprimiendo 1/3 del diámetro anteroposterior (≈ 4 cm en el lactante y 5 cm en el niño) a 100-120 por minuto."}, {"q": "Sobre la vía intraósea en el niño, es correcto:", "o": ["Solo permite administrar sueros, no fármacos", "Puede repetirse en el mismo hueso a las 2 horas", "Debe esperarse al menos 10 minutos de intentos de vía periférica antes de colocarla", "La localización habitual es la tibia proximal y está contraindicada en un hueso fracturado"], "a": 3, "e": "La vía intraósea se coloca si no se consigue una vía periférica rápidamente (≈ 90 s o 3 intentos) en una emergencia; habitualmente en la tibia proximal, por debajo de la tuberosidad. Permite cualquier fármaco o fluido. Está contraindicada en hueso fracturado, con punción previa en las 24 horas anteriores o con infección local."}, {"q": "Para calcular la longitud de inserción de una sonda nasogástrica en un niño, el método recomendado es:", "o": ["Nariz, lóbulo de la oreja y apéndice xifoides", "Nariz y apéndice xifoides directamente", "NEMU: nariz, lóbulo de la oreja y punto medio entre el xifoides y el ombligo", "Comisura bucal y ombligo"], "a": 2, "e": "El método NEMU es más preciso en pediatría y asegura que los orificios queden en el estómago. La regla del adulto (nariz-oreja-xifoides) tiende a dejar la sonda corta, en el esófago distal. La posición se comprueba con radiografía o con el pH del aspirado (≤ 5,5)."}, {"q": "En un lactante febril que no controla esfínteres, el método de elección para obtener un urocultivo fiable en urgencias es:", "o": ["El sondaje vesical", "La bolsa perineal adhesiva", "La recogida de orina exprimiendo el pañal", "La tira reactiva de la orina de la bolsa"], "a": 0, "e": "La bolsa adhesiva tiene una alta tasa de contaminación y solo sirve para descartar (tira o sedimento). El sondaje vesical es el método de elección para el urocultivo; la punción suprapúbica es la técnica más estéril (de elección en neonatos o cuando no se puede sondar)."}]},
32: {"tema": 32, "titulo": "Cuidados de enfermería en la adolescencia. Trastornos de la conducta alimentaria. Prevención de hábitos tóxicos", "programa": "Cuidados en la adolescencia: pubertad y escala de Tanner, desarrollo psicosocial, entrevista HEEADSSS, PANA, marco legal y confidencialidad, nutrición. Trastornos de la conducta alimentaria: DSM-5, valoración, cribado, criterios de ingreso, síndrome de realimentación y cuidados. Prevención de hábitos tóxicos: ESTUDES, programas de Murcia, CRAFFT, alcohol, vapeo, cannabis, cocaína, hipnosedantes y ciberriesgos.", "preguntas": [{"q": "En los varones, el primer signo físico del inicio de la pubertad es:", "o": ["La aparición de vello púbico", "El crecimiento del pene en longitud", "El aumento del volumen testicular por encima de 4 ml", "El cambio de la voz"], "a": 2, "e": "En el niño, el primer signo puberal es el aumento del volumen testicular (≥ 4 ml, Tanner II), que se mide con el orquidómetro de Prader, habitualmente entre los 9 y 14 años. El vello púbico y el crecimiento del pene son posteriores."}, {"q": "En las niñas, el primer signo del desarrollo puberal suele ser:", "o": ["La telarquia (botón mamario)", "La pubarquia (vello púbico)", "La menarquia", "El pico de crecimiento"], "a": 0, "e": "La telarquia (Tanner II mamario) es el primer signo puberal en la niña, entre los 8 y 13 años. La menarquia es un acontecimiento tardío de la pubertad."}, {"q": "Una adolescente presenta desarrollo mamario en estadio IV de Tanner y vello púbico en estadio II. El registro correcto es:", "o": ["Tanner IV global, igualando ambos parámetros", "Tanner II global, por el parámetro más inmaduro", "Tanner III, como media de ambos", "S4-P2, registrando cada parámetro por separado"], "a": 3, "e": "El desarrollo mamario (estrógenos) y el vello púbico (andrógenos suprarrenales) progresan de forma independiente: se registran por separado (S4-P2). Unificarlos invalida el registro."}, {"q": "La tendencia del adolescente a la impulsividad y la búsqueda de sensaciones se explica porque:", "o": ["La corteza prefrontal madura antes que el sistema límbico", "El sistema límbico (emociones y recompensa) madura antes que la corteza prefrontal (control de impulsos)", "La mielinización cerebral termina a los 12 años", "Disminuye la actividad del sistema de recompensa"], "a": 1, "e": "La maduración cerebral avanza de atrás hacia delante: el sistema límbico madura antes que la corteza prefrontal, responsable del juicio y la inhibición de impulsos. Esta asimetría favorece las conductas de riesgo."}, {"q": "Según Erikson, el conflicto psicosocial central de la adolescencia es:", "o": ["Identidad frente a confusión de roles", "Intimidad frente a aislamiento", "Laboriosidad frente a inferioridad", "Generatividad frente a estancamiento"], "a": 0, "e": "En la adolescencia el conflicto es identidad frente a confusión de roles: el adolescente se separa psicológicamente de los padres y busca validación en el grupo de iguales. Para Piaget, entra en el estadio de las operaciones formales."}, {"q": "Durante la entrevista HEEADSSS, un adolescente de 15 años cuenta que fuma cannabis los fines de semana. La actuación correcta de la enfermera es:", "o": ["Llamar inmediatamente a los padres para informarles", "Comunicarlo a la policía", "Mantener la confidencialidad y realizar una intervención de consejo sanitario", "Negarse a seguir atendiéndole sin la presencia de sus padres"], "a": 2, "e": "Las conductas de riesgo requieren intervención y consejo, pero están protegidas por la confidencialidad. El secreto solo se rompe ante un riesgo grave e inminente para la vida del menor o de terceros, o ante maltrato o abuso."}, {"q": "¿En cuál de las siguientes situaciones está justificado romper la confidencialidad de un adolescente?", "o": ["Si refiere que no usa preservativo", "Si cuenta que ha suspendido varias asignaturas", "Si reconoce que bebe alcohol los fines de semana", "Si expresa un plan estructurado de suicidio"], "a": 3, "e": "Al inicio de la entrevista se explican los límites de la confidencialidad: se rompe ante riesgo grave para la vida (ideación suicida con plan), riesgo para terceros, maltrato o abuso sexual."}, {"q": "Según la Ley 41/2002, un paciente de 16 años no emancipado que va a someterse a una cirugía programada sin riesgo grave:", "o": ["Necesita siempre la firma de ambos padres", "Presta él mismo el consentimiento; no cabe el consentimiento por representación", "Necesita autorización judicial", "Solo puede consentir si es menor maduro según el juez"], "a": 1, "e": "A partir de los 16 años, o si está emancipado, el paciente consiente por sí mismo. La excepción es la actuación de grave riesgo para su vida o salud, en la que consiente el representante legal tras oír al menor; los ensayos clínicos y la reproducción asistida requieren la mayoría de edad."}, {"q": "¿Para cuál de las siguientes actuaciones se exige la mayoría de edad civil (18 años) y no basta con tener 16?", "o": ["La vacunación", "Una cirugía programada", "Las técnicas de reproducción humana asistida", "Las curas de una herida"], "a": 2, "e": "Los ensayos clínicos y las técnicas de reproducción humana asistida se rigen por la mayoría de edad general (18 años). Para el resto de actuaciones sanitarias, a los 16 años el paciente consiente por sí mismo."}, {"q": "La ingesta recomendada de calcio entre los 9 y los 18 años es de:", "o": ["1.300 mg/día", "800 mg/día", "1.000 mg/día", "500 mg/día"], "a": 0, "e": "En la adolescencia se recomiendan 1.300 mg/día de calcio, más que en el adulto (1.000 mg/día), para alcanzar un buen pico de masa ósea, protector frente a la osteoporosis."}, {"q": "El aumento de las necesidades de hierro en el varón adolescente se debe principalmente a:", "o": ["Las pérdidas digestivas de sangre", "El mayor consumo de proteínas", "Las mismas pérdidas que en la mujer", "La expansión del volumen sanguíneo y el desarrollo de la masa muscular"], "a": 3, "e": "Los varones necesitan unos 11 mg/día de hierro por el aumento de la volemia y la síntesis de mioglobina para la masa muscular. Las mujeres necesitan unos 15 mg/día para compensar las pérdidas menstruales."}, {"q": "Una chica de 17 años con restricción alimentaria intensa, miedo a engordar e IMC de 15 mantiene menstruaciones regulares. Según el DSM-5:", "o": ["No puede diagnosticarse anorexia nerviosa porque no tiene amenorrea", "Puede diagnosticarse anorexia nerviosa, ya que la amenorrea dejó de ser un criterio", "Debe diagnosticarse bulimia nerviosa", "Debe clasificarse como un trastorno alimentario no especificado"], "a": 1, "e": "El DSM-5 eliminó la amenorrea como criterio de anorexia nerviosa. El diagnóstico se basa en la restricción con peso significativamente bajo, el miedo intenso a engordar y la alteración de la percepción del peso o la figura."}, {"q": "Según el DSM-5, una anorexia nerviosa con un IMC de 15,5 kg/m² se clasifica como:", "o": ["Leve", "Moderada", "Grave", "Extrema"], "a": 2, "e": "Gravedad de la anorexia en adultos según el IMC: leve ≥ 17; moderada 16-16,99; grave 15-15,99; extrema < 15 kg/m². En niños y adolescentes se usan percentiles equivalentes."}, {"q": "Para el diagnóstico de bulimia nerviosa según el DSM-5, los atracones y las conductas compensatorias deben producirse:", "o": ["Al menos una vez a la semana durante tres meses", "Al menos dos veces a la semana durante seis meses", "Al menos una vez al mes durante un año", "Diariamente durante un mes"], "a": 0, "e": "El DSM-5 redujo la frecuencia exigida a una vez por semana durante tres meses (antes eran dos veces por semana). La gravedad se gradúa por el número de conductas compensatorias semanales."}, {"q": "El trastorno por atracón se diferencia de la bulimia nerviosa en que:", "o": ["Los atracones no implican pérdida de control", "Solo aparece en varones", "El peso es siempre muy bajo", "No existen conductas compensatorias regulares (vómitos, laxantes, ayuno)"], "a": 3, "e": "En el trastorno por atracón hay atracones recurrentes con pérdida de control (al menos una vez por semana durante tres meses), pero sin conductas compensatorias; por eso tiende a asociarse con la obesidad."}, {"q": "El signo de Russell, propio de los pacientes con conductas purgativas, consiste en:", "o": ["Erosión del esmalte en la cara interna de los dientes", "Callosidades o erosiones en el dorso de la mano por provocarse el vómito", "Hipertrofia de las glándulas parótidas", "Vello fino en espalda y brazos"], "a": 1, "e": "El signo de Russell son callosidades o cicatrices en el dorso de la mano (articulaciones metacarpofalángicas) por el roce con los incisivos al inducir el vómito. La erosión dental es la perimólisis y el vello fino, el lanugo de la anorexia."}, {"q": "En una paciente con bulimia y vómitos autoinducidos frecuentes, la alteración analítica esperable es:", "o": ["Acidosis metabólica con hiperpotasemia", "Alcalosis respiratoria con hipercalcemia", "Alcalosis metabólica hipoclorémica con hipopotasemia", "Acidosis respiratoria con hipernatremia"], "a": 2, "e": "El vómito pierde ácido clorhídrico: alcalosis metabólica hipoclorémica con hipopotasemia, que puede alargar el QT y provocar arritmias graves. Es uno de los criterios de gravedad e ingreso."}, {"q": "En el cuestionario SCOFF de cribado de TCA, la sospecha es positiva a partir de:", "o": ["2 respuestas afirmativas", "1 respuesta afirmativa", "4 respuestas afirmativas", "5 respuestas afirmativas"], "a": 0, "e": "El SCOFF tiene 5 preguntas de sí/no (sentirse lleno hasta el malestar, perder el control sobre la comida, perder más de 6 kg en 3 meses, sentirse gordo, la comida domina la vida). Dos o más síes indican sospecha. En el EAT-26, más de 20 puntos indica alto riesgo."}, {"q": "El dato analítico más característico del síndrome de realimentación es:", "o": ["La hipernatremia", "La hiperpotasemia", "La hipercalcemia", "La hipofosfatemia"], "a": 3, "e": "Al reintroducir los hidratos de carbono, la insulina introduce en las células fósforo, potasio, magnesio y agua. La hipofosfatemia es el dato clave y causa fallo muscular, respiratorio y cardíaco; también hay hipopotasemia, hipomagnesemia y déficit de tiamina."}, {"q": "Para prevenir el síndrome de realimentación en una paciente con anorexia de alto riesgo, es correcto:", "o": ["Iniciar un aporte hipercalórico para recuperar peso cuanto antes", "Administrar tiamina antes de iniciar el aporte calórico y empezar con pocas calorías, aumentando lentamente", "Administrar glucosa intravenosa concentrada como primera medida", "Evitar los controles analíticos para no estresar a la paciente"], "a": 1, "e": "La regla es «empezar bajo e ir despacio» (10-15 kcal/kg/día y subir en 4-7 días), con tiamina antes de cualquier aporte de glucosa, suplementos de fósforo, potasio y magnesio y control diario de iones la primera semana."}, {"q": "El pesaje de una paciente ingresada por anorexia nerviosa debe realizarse:", "o": ["Con la bata hospitalaria tras el desayuno, mirando la báscula para darle control", "Al final del día, con ropa de calle", "Por la mañana, tras orinar, en ropa interior y de espaldas al visor de la báscula", "Solo cuando la paciente lo solicite"], "a": 2, "e": "Se pesa a primera hora, tras la micción (evita la «carga de agua»), en ropa interior (evita objetos ocultos) y de espaldas a la báscula, para reducir la fijación obsesiva con la cifra."}, {"q": "Ante el diagnóstico «trastorno de la imagen corporal» en una adolescente con anorexia que está ganando peso, la intervención correcta es:", "o": ["Evitar los comentarios sobre su aspecto físico y ayudarla a separar la apariencia de su valía personal", "Felicitarla diciéndole que ya se la ve mejor y ha engordado", "Pesarla delante de un espejo para que vea su evolución", "Dejar que negocie el contenido de la bandeja para que gane confianza"], "a": 0, "e": "Los comentarios sobre el aspecto («te veo mejor», «has cogido peso») los interpreta como que ha engordado y son iatrogénicos. Se trabaja la autoestima separando la apariencia de la valía personal. La dieta pautada no se negocia."}, {"q": "El cuestionario de cribado de consumo de alcohol y drogas recomendado en adolescentes es:", "o": ["El CAGE", "El test de Fagerström", "El test de Morisky-Green", "El CRAFFT"], "a": 3, "e": "El CRAFFT (12-21 años) es la herramienta de elección; dos o más respuestas afirmativas en la parte B indican alto riesgo. El CAGE no se recomienda en adolescentes por su baja sensibilidad. El Fagerström mide la dependencia de la nicotina."}, {"q": "Un adolescente de 15 años llega a urgencias en coma etílico. Además del riesgo de aspiración, el principal riesgo metabólico es:", "o": ["La hiperglucemia por los azúcares de las bebidas", "La hipoglucemia por bloqueo de la gluconeogénesis hepática", "La hiperpotasemia", "La hipercalcemia"], "a": 1, "e": "El etanol bloquea la gluconeogénesis y el adolescente tiene pocas reservas de glucógeno: riesgo de hipoglucemia grave. Se coloca en posición lateral de seguridad, se controla la glucemia y se protege del frío (la vasodilatación favorece la hipotermia)."}, {"q": "Un consumidor crónico de cannabis acude por vómitos incoercibles que, según refiere, mejoran con duchas de agua caliente. El tratamiento más adecuado es:", "o": ["Metoclopramida intravenosa", "Ondansetrón en dosis altas", "Fluidoterapia y aplicación de crema de capsaicina en el abdomen", "Dieta absoluta sin otra medida"], "a": 2, "e": "Es un síndrome de hiperémesis cannabinoide. Los antieméticos clásicos son poco eficaces. Se trata con sueroterapia y capsaicina tópica en el abdomen, que imita el efecto del agua caliente sobre los receptores TRPV1, además del abandono del consumo."}, {"q": "El flumazenilo está contraindicado en:", "o": ["La intoxicación aislada por benzodiacepinas en un paciente sin antecedentes", "La sedación por midazolam tras una endoscopia", "Cualquier paciente menor de 18 años", "La intoxicación mixta por benzodiacepinas y antidepresivos tricíclicos"], "a": 3, "e": "El flumazenilo revierte las benzodiacepinas, pero anula su efecto anticonvulsivante: está contraindicado en intoxicaciones mixtas con tricíclicos, en epilépticos y en la dependencia crónica de benzodiacepinas, por el riesgo de convulsiones graves."}, {"q": "La intoxicación aguda por cocaína se caracteriza por:", "o": ["Agitación, taquicardia, hipertensión, midriasis, sudoración y riesgo de infarto por vasoespasmo", "Miosis puntiforme, bradipnea y coma", "Bradicardia, hipotensión y somnolencia", "Hipotermia y piel seca"], "a": 0, "e": "La cocaína es un simpaticomimético (bloquea la recaptación de dopamina, noradrenalina y serotonina): agitación, verborrea, taquicardia, hipertensión, midriasis, sudoración, infarto por vasoespasmo y alucinaciones táctiles (Magnan). La miosis con bradipnea sugiere opioides."}, {"q": "Un adolescente presenta fatiga diurna y fracaso escolar porque pasa las noches con el móvil y la consola hasta las 4 de la madrugada. Este fenómeno se denomina:", "o": ["Nomofobia", "Vamping", "FOMO", "Sexting"], "a": 1, "e": "El vamping es el uso de pantallas durante la madrugada, que reduce el sueño; la luz azul inhibe la melatonina. La nomofobia es la angustia por estar sin móvil y el FOMO, la ansiedad por perderse lo que hacen los demás."}, {"q": "El término grooming hace referencia a:", "o": ["El acoso entre compañeros a través de redes sociales", "El envío de imágenes íntimas propias", "El miedo a quedarse sin el teléfono móvil", "Las acciones de un adulto para ganarse la confianza de un menor con fines sexuales o de extorsión"], "a": 3, "e": "El grooming lo realiza un adulto (a menudo con perfil falso) que crea un vínculo con el menor para obtener material íntimo o abusar de él. El acoso entre iguales por medios digitales es ciberbullying y el envío de imágenes propias, sexting."}, {"q": "Respecto al cigarrillo electrónico en adolescentes, es correcto:", "o": ["No es inocuo: suele contener nicotina, genera sustancias tóxicas y se asocia a lesión pulmonar aguda (EVALI)", "Solo emite vapor de agua sin riesgo para la salud", "No produce dependencia", "Es una alternativa recomendable para que los adolescentes no empiecen a fumar"], "a": 0, "e": "El aerosol del vapeo contiene nicotina (dependencia) y, al calentarse el propilenglicol y la glicerina, formaldehído y acroleína. Se asocia a EVALI. La encuesta ESTUDES muestra su gran expansión entre los estudiantes."}]},
33: {"tema": 33, "titulo": "Planificación familiar. Métodos anticonceptivos. Embarazos no deseados. Prevención de las enfermedades de transmisión sexual. Intervenciones de enfermería", "programa": "Planificación familiar, PIAM y Ley Orgánica 1/2023. Consejo anticonceptivo: índice de Pearl y criterios de elegibilidad de la OMS. Anticoncepción hormonal combinada y olvidos, solo gestágeno, implante, DIU, barrera, MELA, métodos naturales y esterilización. Anticoncepción de urgencia. Embarazo no deseado e IVE. Infecciones de transmisión sexual, PrEP, PEP, PERSEA y vacuna del VPH. Diagnósticos e intervenciones de enfermería. Programa CERCA.", "preguntas": [{"q": "El índice de Pearl expresa:", "o": ["El número de embarazos por cada 1.000 mujeres durante 5 años de uso", "El número de embarazos por cada 100 mujeres durante 1 año de uso de un método", "El porcentaje de mujeres que abandonan el método en el primer año", "El número de embarazos por cada 100 mujeres a lo largo de su vida fértil"], "a": 1, "e": "El índice de Pearl es el número de embarazos no planificados por cada 100 mujeres durante el primer año de uso de un método. Cuanto menor es, más eficaz es el método."}, {"q": "¿En qué métodos anticonceptivos apenas hay diferencia entre la eficacia (uso perfecto) y la efectividad (uso habitual)?", "o": ["La píldora combinada", "El preservativo masculino", "Los métodos naturales", "El DIU y el implante subdérmico"], "a": 3, "e": "Los métodos de larga duración (LARC: DIU e implante) no dependen de una acción diaria de la usuaria, por lo que su efectividad real es casi igual a su eficacia. En la píldora y el preservativo la diferencia es grande por los olvidos y errores."}, {"q": "Según los criterios médicos de elegibilidad de la OMS, una mujer de 37 años que fuma 20 cigarrillos al día y desea anticoncepción hormonal combinada se encuentra en la categoría:", "o": ["4: riesgo inaceptable, contraindicación absoluta", "1: sin restricciones", "2: los beneficios superan a los riesgos", "No existe ninguna restricción por el tabaco"], "a": 0, "e": "Tener 35 años o más y fumar 15 o más cigarrillos al día (las dos condiciones a la vez) es categoría 4 para los métodos con estrógenos. Puede usar métodos de solo gestágeno o DIU."}, {"q": "Una mujer de 25 años con migraña con aura solicita un anticonceptivo. Respecto a los métodos con estrógenos:", "o": ["Son categoría 2 por su edad", "Son categoría 1 si no fuma", "Son categoría 4: están contraindicados a cualquier edad", "Pueden utilizarse con controles de tensión arterial"], "a": 2, "e": "La migraña con aura es categoría 4 para los estrógenos a cualquier edad por el riesgo de ictus. También lo son los antecedentes de ictus, AIT o trombosis venosa."}, {"q": "El mecanismo de acción principal de la anticoncepción hormonal combinada es:", "o": ["La inhibición de la ovulación por supresión del pico de LH", "La acción espermicida directa", "La reacción inflamatoria endometrial", "Únicamente el espesamiento del moco cervical"], "a": 0, "e": "La combinación de estrógeno y gestágeno (píldora, parche o anillo) inhibe el eje hipotálamo-hipófisis-ovario y bloquea el pico de LH, impidiendo la ovulación. Secundariamente espesa el moco y altera el endometrio."}, {"q": "Entre los anticonceptivos combinados, el menor riesgo de tromboembolismo venoso se asocia al gestágeno:", "o": ["Drospirenona", "Desogestrel", "Gestodeno", "Levonorgestrel"], "a": 3, "e": "Los preparados con levonorgestrel (2.ª generación) tienen el menor riesgo de trombosis venosa; desogestrel, gestodeno y drospirenona (3.ª y 4.ª generación) tienen un riesgo mayor."}, {"q": "Una usuaria de píldora combinada se da cuenta de que olvidó la toma de ayer (retraso menor de 24 horas). Debe:", "o": ["Dejar el envase y esperar a la regla", "Tomar la píldora olvidada en cuanto lo recuerde, aunque coincidan dos el mismo día, sin necesidad de protección adicional", "Tomar la píldora olvidada y usar preservativo 7 días", "Tomar anticoncepción de urgencia siempre"], "a": 1, "e": "Ante el olvido de una sola píldora (retraso < 24 h) se toma en cuanto se recuerde y se sigue con normalidad; no hace falta método de barrera."}, {"q": "Si una usuaria olvida dos o más píldoras combinadas en la segunda semana del envase, la actuación correcta es:", "o": ["Tomar todas las píldoras olvidadas a la vez", "No hacer nada y continuar", "Tomar la última píldora olvidada, continuar el envase y usar preservativo durante 7 días", "Suspender la píldora hasta la siguiente regla"], "a": 2, "e": "Con dos o más olvidos (más de 48 h) se toma la última olvidada, se desechan las demás y se usa preservativo 7 días. Si ocurre en la primera semana con coito en los 5 días previos, se valora la anticoncepción de urgencia."}, {"q": "Si los olvidos de la píldora combinada ocurren en la tercera semana del envase, se recomienda:", "o": ["Terminar las píldoras activas y empezar el siguiente envase sin hacer la semana de descanso", "Hacer la semana de descanso de forma normal", "Abandonar el método", "Iniciar un envase nuevo tras 7 días de descanso"], "a": 0, "e": "Si los olvidos son en los últimos siete días de píldoras activas, se terminan las activas, se omite el descanso (o las placebo) y se empalma directamente con el envase siguiente."}, {"q": "Una usuaria de anillo vaginal se lo retiró en la segunda semana y lo ha tenido fuera 5 horas. Debe:", "o": ["Desecharlo y esperar a la regla", "Reinsertarlo sin más medidas", "Ponerse un parche hasta el siguiente ciclo", "Reinsertarlo de inmediato y usar preservativo durante 7 días"], "a": 3, "e": "El límite de seguridad del anillo es de 3 horas fuera. Si se supera en la 1.ª o 2.ª semana, se reinserta y se usa preservativo 7 días; en la 3.ª semana se coloca un anillo nuevo sin descanso. En el parche el límite es de 48 horas."}, {"q": "Una usuaria de parche anticonceptivo detecta que lleva 3 días despegado. La actuación correcta es:", "o": ["Volver a pegar el mismo parche sin más medidas", "Aplicar un parche nuevo, que pasa a ser el nuevo día 1 del ciclo, y usar preservativo 7 días", "Esperar al día de cambio habitual", "No hacer nada, ya que el parche mantiene la protección una semana"], "a": 1, "e": "Si el parche ha estado despegado 48 horas o más (o no se sabe cuánto), se inicia un ciclo nuevo con un parche nuevo (nuevo día 1 y nuevo día de cambio) y se usa preservativo 7 días. Si fue menos de 48 h, basta con volver a pegarlo o poner uno nuevo."}, {"q": "La causa más frecuente de retirada precoz del implante subdérmico de etonogestrel es:", "o": ["El aumento de peso", "La cefalea", "Las alteraciones del patrón de sangrado", "El acné"], "a": 2, "e": "El implante (3 años, Pearl ≈ 0,05) provoca un patrón de sangrado impredecible: amenorrea en ≈ 20% y sangrado infrecuente o irregular en ≈ 50%. Informar antes de la inserción mejora la continuidad."}, {"q": "Una portadora de DIU es diagnosticada de enfermedad inflamatoria pélvica leve. La actuación recomendada es:", "o": ["Iniciar antibióticos sin retirar el DIU y retirarlo solo si no mejora en 72 horas", "Retirar el DIU de inmediato antes de dar antibióticos", "No tratar y vigilar", "Sustituir el DIU por otro nuevo"], "a": 0, "e": "No es necesario retirar el DIU de entrada: se pauta antibioterapia y se retira si no hay mejoría en 72 horas. El riesgo de EIP es mayor en los primeros 20 días tras la inserción."}, {"q": "En la revisión de una portadora de DIU no se visualizan ni se palpan los hilos. La actuación indicada es:", "o": ["Tranquilizarla; es normal y no requiere más", "Insertar otro DIU", "Pautar anticoncepción de urgencia de forma sistemática", "Realizar una ecografía transvaginal para localizar el dispositivo"], "a": 3, "e": "La pérdida de los hilos puede indicar expulsión, desplazamiento o perforación: se comprueba la ubicación con ecografía. La expulsión es más frecuente el primer año de uso."}, {"q": "Respecto al preservativo masculino de látex, es correcto:", "o": ["Puede utilizarse con vaselina como lubricante", "Es el único método que ofrece doble protección (embarazo e ITS) y debe usarse con lubricantes acuosos o de silicona", "No protege frente al VIH", "Debe colocarse justo antes de la eyaculación"], "a": 1, "e": "El preservativo es el único método con doble protección. Los lubricantes oleosos (aceites, vaselina, cremas) dañan el látex y aumentan el riesgo de rotura; deben usarse lubricantes acuosos o de silicona."}, {"q": "Tras el coito, el diafragma debe permanecer colocado:", "o": ["30 minutos", "1 hora", "Entre 6 y 8 horas, sin superar las 24 horas", "Al menos 48 horas"], "a": 2, "e": "El diafragma se usa siempre con espermicida y se mantiene 6-8 horas después de la última eyaculación para asegurar la muerte de los espermatozoides, pero nunca más de 24 horas por el riesgo de síndrome de shock tóxico."}, {"q": "Una madre con lactancia materna exclusiva y amenorrea desea seguir con el método MELA. Su bebé tiene 7 meses. La enfermera le indica que:", "o": ["Puede seguir con el MELA mientras no tenga la regla", "El MELA es eficaz hasta el año si la lactancia es exclusiva", "El MELA solo pierde eficacia si aparece la menstruación", "El MELA ya no es válido porque el bebé tiene más de 6 meses; debe usar otro método compatible con la lactancia"], "a": 3, "e": "El MELA exige los tres criterios a la vez: lactancia exclusiva o casi exclusiva (sin pausas de más de 4 h de día ni 6 h de noche), amenorrea y bebé menor de 6 meses. Si falla uno, hay que pasar a un método compatible (gestágeno, implante o DIU)."}, {"q": "En el método de la temperatura basal, la elevación de 0,2-0,5 °C:", "o": ["Se produce después de la ovulación por efecto de la progesterona y permite confirmar que ya ha ocurrido", "Se produce antes de la ovulación y permite predecirla", "Se debe a los estrógenos de la fase folicular", "Indica el inicio de la menstruación"], "a": 0, "e": "La progesterona del cuerpo lúteo tiene efecto termogénico: la temperatura sube tras la ovulación. Sirve para confirmar que ya se ha producido, no para predecirla. En el método Billings, el moco fértil es filante y cristaliza en helecho."}, {"q": "A un varón se le ha realizado una vasectomía. Debe informársele de que:", "o": ["Es eficaz desde el mismo día de la intervención", "Debe usar otro método hasta tener un seminograma negativo, habitualmente a los 3 meses o tras unas 20 eyaculaciones", "Es eficaz a partir de la primera semana", "No necesita ningún control posterior"], "a": 1, "e": "Tras la vasectomía quedan espermatozoides en la vía seminal: no es eficaz hasta comprobar un seminograma sin espermatozoides (≈ 3 meses o 20 eyaculaciones). La ligadura de trompas es eficaz desde la intervención."}, {"q": "El plazo máximo de uso del levonorgestrel 1,5 mg como anticoncepción de urgencia es de:", "o": ["12 horas", "24 horas", "72 horas", "7 días"], "a": 2, "e": "El levonorgestrel es más eficaz cuanto antes se toma (idealmente en 24 h) y puede usarse hasta 72 horas. El ulipristal y el DIU de cobre pueden usarse hasta 120 horas (5 días)."}, {"q": "El método más eficaz de anticoncepción de urgencia, cuya eficacia no se ve afectada por el peso de la mujer, es:", "o": ["El levonorgestrel 1,5 mg", "El ulipristal 30 mg", "Una doble dosis de píldora combinada", "El DIU de cobre insertado en los 5 días siguientes"], "a": 3, "e": "El DIU de cobre insertado en los 5 días posteriores al coito no protegido es el método poscoital más eficaz, no pierde eficacia con el sobrepeso y además queda como anticonceptivo de larga duración."}, {"q": "Una mujer ha tomado ulipristal como anticoncepción de urgencia y quiere empezar a tomar la píldora. Debe:", "o": ["Esperar 5 días para iniciar la píldora y usar preservativo mientras tanto", "Empezar la píldora el mismo día", "Esperar a la segunda regla", "No puede usar anticoncepción hormonal en 6 meses"], "a": 0, "e": "El ulipristal es un modulador de los receptores de progesterona: los gestágenos tomados enseguida pueden anular su efecto. Se esperan 5 días para empezar el método hormonal (con preservativo). Tras levonorgestrel, en cambio, se puede empezar en el acto."}, {"q": "Respecto al mecanismo de acción de la anticoncepción de urgencia oral, es correcto:", "o": ["Provoca el aborto de un embarazo implantado", "Retrasa o impide la ovulación y no tiene efecto abortivo", "Destruye el óvulo fecundado", "Es teratógena si falla"], "a": 1, "e": "Actúa antes de la fecundación, retrasando o bloqueando el pico de LH y la ovulación. No actúa sobre un embarazo ya implantado ni es teratógena. No debe usarse como método habitual."}, {"q": "Según la legislación vigente, la interrupción voluntaria del embarazo a petición de la mujer, sin necesidad de alegar causa, puede realizarse:", "o": ["Hasta la semana 12, tras 3 días de reflexión", "Hasta la semana 22", "Hasta la semana 14, sin periodo obligatorio de reflexión", "En cualquier momento de la gestación"], "a": 2, "e": "A petición de la mujer, hasta la semana 14; la LO 1/2023 suprimió los 3 días de reflexión. Por grave riesgo materno o graves anomalías fetales, hasta la semana 22; más allá, solo por anomalías incompatibles con la vida o enfermedad fetal extremadamente grave e incurable."}, {"q": "Según la Ley Orgánica 1/2023, una chica de 16 años que solicita una interrupción voluntaria del embarazo:", "o": ["Puede decidir por sí misma, sin consentimiento de sus representantes legales", "Necesita siempre el consentimiento de ambos progenitores", "Necesita autorización judicial", "Debe esperar a cumplir 18 años"], "a": 0, "e": "La LO 1/2023 reconoce a las mujeres de 16 y 17 años la capacidad de decidir la IVE (y el acceso a la anticoncepción) sin el consentimiento de sus representantes legales."}, {"q": "En la interrupción farmacológica del embarazo precoz (hasta la semana 9), la pauta habitual es:", "o": ["Misoprostol y, una semana después, mifepristona", "Solo misoprostol intramuscular", "Oxitocina intravenosa", "Mifepristona 200 mg oral y, a las 24-48 horas, misoprostol 800 mcg"], "a": 3, "e": "La mifepristona (antiprogestágeno) detiene la gestación; el misoprostol (análogo de prostaglandina), a las 24-48 h, provoca las contracciones y la expulsión. El dolor se trata con ibuprofeno y se hace un control a los 15-21 días."}, {"q": "Sobre la infección por Chlamydia trachomatis, es correcto:", "o": ["Siempre produce un exudado purulento abundante", "Es la ITS bacteriana más frecuente, a menudo asintomática, y una causa principal de EIP e infertilidad tubárica", "Se manifiesta con un chancro indoloro", "Produce un exantema en palmas y plantas"], "a": 1, "e": "La clamidia es la ITS más prevalente y suele ser asintomática; al no tratarse, asciende y causa EIP, dolor pélvico crónico e infertilidad de origen tubárico. El exudado purulento es típico de la gonorrea y el chancro y el exantema palmoplantar, de la sífilis."}, {"q": "La lesión característica de la sífilis primaria es:", "o": ["Un chancro blando y doloroso", "Vesículas agrupadas dolorosas", "Un chancro duro e indoloro", "Verrugas exofíticas"], "a": 2, "e": "La sífilis primaria cursa con un chancro duro e indoloro. El chancro blando y doloroso es el chancroide (Haemophilus ducreyi); las vesículas dolorosas, el herpes; las verrugas, el VPH 6 y 11. La sífilis secundaria produce un exantema en palmas y plantas."}, {"q": "Respecto a la profilaxis postexposición (PEP) frente al VIH, es correcto:", "o": ["Se toma de forma continua en personas VIH negativas con alta exposición", "Puede iniciarse en cualquier momento tras la exposición", "Se administra en dosis única", "Debe iniciarse lo antes posible, no más tarde de 72 horas, y mantenerse 28 días"], "a": 3, "e": "La PEP es una urgencia: cuanto antes mejor (idealmente en las primeras horas) y nunca después de 72 horas, con 28 días de antirretrovirales. La toma continua en personas VIH negativas con alta exposición es la PrEP, que requiere controles trimestrales."}, {"q": "En el programa CERCA de la Región de Murcia, a una mujer de 40 años le corresponde como cribado de cáncer de cérvix:", "o": ["Test de VPH de alto riesgo cada 5 años", "Citología anual", "Citología cada 3 años", "No le corresponde cribado"], "a": 0, "e": "Entre los 25 y 34 años se hace citología cada 3 años; entre los 35 y 65 años, test de VPH de alto riesgo cada 5 años. Antes de los 35, la infección transitoria por VPH es tan frecuente que el test daría muchos falsos positivos."}]},
34: {"tema": 34, "titulo": "Perspectiva de género en el proceso de salud/enfermedad. Morbilidad diferencial. Protocolo sanitario ante la violencia de género. Plan de Acción Regional. Malos tratos en el niño, la mujer y el anciano", "programa": "Perspectiva de género en el proceso salud/enfermedad. Morbilidad diferencial: biología, medio ambiente, pobreza, violencia, condiciones de trabajo y salud ocupacional. Protocolo para la actuación sanitaria ante la violencia de género. Plan de Acción Regional contra la violencia de género. Detección y prevención de malos tratos en el niño, la mujer y el anciano.", "preguntas": [{"q": "En el análisis de la salud con perspectiva de género, el término «género» se refiere a:", "o": ["Las características cromosómicas y hormonales de cada persona", "Las construcciones sociales, roles y expectativas que cada cultura asigna a hombres y mujeres", "Las diferencias anatómicas de los órganos reproductores", "La orientación sexual de la persona"], "a": 1, "e": "El sexo remite a las características biológicas (genéticas, hormonales, anatómicas); el género, a las construcciones sociales, roles, tareas y expectativas asignadas de forma desigual a hombres y mujeres."}, {"q": "La paradoja de la morbilidad diferencial entre sexos se resume en que las mujeres:", "o": ["Viven menos años y con peor salud", "Tienen la misma esperanza de vida y la misma morbilidad que los hombres", "Viven menos años pero con mejor calidad de vida", "Viven más años, pero con mayor carga de enfermedad crónica, dolor, discapacidad y trastornos mentales"], "a": 3, "e": "«Las mujeres viven más, pero viven peor»: tienen mayor esperanza de vida, pero soportan más enfermedad crónica, dolor, discapacidad y problemas de salud mental a lo largo de la vida."}, {"q": "La mayor reactividad inmunitaria de las mujeres explica su mayor prevalencia de:", "o": ["Enfermedades autoinmunes como el lupus o la artritis reumatoide", "Sepsis graves", "Infecciones agudas", "Cardiopatía isquémica precoz"], "a": 0, "e": "La respuesta inmunitaria más intensa confiere a las mujeres más resistencia frente a infecciones, pero explica la mayor prevalencia de enfermedades autoinmunes (lupus, artritis reumatoide, esclerosis múltiple, tiroiditis de Hashimoto)."}, {"q": "Respecto al infarto agudo de miocardio en la mujer, es correcto:", "o": ["Siempre se presenta con dolor opresivo irradiado al brazo izquierdo", "Su diagnóstico es más precoz que en el varón", "Con frecuencia se presenta de forma atípica (disnea, fatiga, dolor epigástrico o interescapular), lo que retrasa el diagnóstico", "Es excepcional antes de los 80 años"], "a": 2, "e": "En la mujer el infarto se presenta a menudo de forma atípica, sin el dolor opresivo clásico, con disnea, fatiga o dolor epigástrico o interescapular confundido con dispepsia o ansiedad. Esto retrasa el diagnóstico y la reperfusión."}, {"q": "La tasa AROPE es un indicador que mide:", "o": ["El riesgo de pobreza o exclusión social", "La carga física de la movilización de pacientes", "El riesgo psicosocial de la doble presencia", "La sobrecarga del cuidador"], "a": 0, "e": "La tasa AROPE (At Risk Of Poverty or social Exclusion) mide el riesgo de pobreza o exclusión. Los hogares monomarentales con menores a cargo encabezan este indicador, reflejo de la feminización de la pobreza."}, {"q": "Para evaluar el riesgo por movilización manual de pacientes en las unidades hospitalarias se utiliza:", "o": ["El cuestionario CoPsoQ-istas21", "La escala de Zarit", "El índice EASI", "El índice MAPO"], "a": 3, "e": "El índice MAPO (Movimentazione e Assistenza Pazienti Ospedalieri) evalúa el riesgo por movilización de pacientes, un riesgo ergonómico frecuente en sectores feminizados como la enfermería."}, {"q": "La «doble presencia» como riesgo psicosocial laboral se refiere a:", "o": ["Trabajar en dos centros sanitarios a la vez", "Asumir a la vez las exigencias del trabajo remunerado y del trabajo doméstico y de cuidados", "Tener dos turnos consecutivos de trabajo", "Compartir la consulta con otro profesional"], "a": 1, "e": "La doble presencia es la necesidad de responder a la vez a las exigencias del empleo y del trabajo doméstico y de cuidados. Se evalúa con el CoPsoQ-istas21 y genera una sobrecarga alostática (fatiga crónica, fibromialgia, insomnio, consumo de ansiolíticos)."}, {"q": "Las barreras invisibles que dificultan el acceso de las mujeres a los puestos directivos se denominan:", "o": ["Segregación horizontal", "Doble presencia", "Segregación vertical o «techo de cristal»", "Feminización de la pobreza"], "a": 2, "e": "La segregación vertical (techo de cristal) limita el acceso de las mujeres a la alta dirección aunque el sector sanitario esté muy feminizado. La segregación horizontal concentra a las mujeres en determinados sectores (sanidad, educación, cuidados)."}, {"q": "El ciclo de la violencia descrito por Leonore Walker consta de:", "o": ["Tres fases: acumulación de tensión, explosión violenta y luna de miel o reconciliación", "Cuatro fases, la última de calma independiente", "Dos fases: agresión y perdón", "Cinco fases que terminan en la separación"], "a": 0, "e": "El ciclo original de Walker (1979) tiene solo tres fases: acumulación de tensión, explosión (agresión) y luna de miel (arrepentimiento). La aparente calma forma parte de la fase de reconciliación, no de una cuarta fase."}, {"q": "En el ciclo de Walker, la fase en la que el agresor se arrepiente y promete cambiar, y en la que la víctima suele retirar denuncias, es la:", "o": ["Acumulación de tensión", "Explosión violenta", "Fase de separación", "Luna de miel o reconciliación"], "a": 3, "e": "En la luna de miel el agresor muestra arrepentimiento y afecto, lo que refuerza el vínculo traumático y favorece que la víctima retire denuncias o abandone tratamientos; después el ciclo vuelve a empezar."}, {"q": "Según la Ley Orgánica 1/2004, se considera violencia de género la ejercida sobre la mujer por:", "o": ["Cualquier familiar con el que conviva", "Solo su marido, si conviven en el mismo domicilio", "Quien sea o haya sido su cónyuge o pareja, aunque no hayan convivido", "Cualquier persona desconocida en la vía pública"], "a": 2, "e": "La LO 1/2004 protege frente a la violencia ejercida por quien sea o haya sido cónyuge o pareja sentimental, con independencia de que haya existido convivencia (incluye novios y exparejas)."}, {"q": "La violencia vicaria se define como:", "o": ["La violencia ejercida sobre los hijos menores para causar daño y sufrimiento a la madre", "La violencia entre compañeros de trabajo", "La agresión a vecinos de la víctima", "La violencia de los hijos hacia sus padres"], "a": 0, "e": "En la violencia vicaria el agresor daña a los hijos (u otros allegados menores) como instrumento para causar un dolor irreparable a la mujer."}, {"q": "Respecto a los derechos de las víctimas de violencia de género, el acceso a la asistencia social integral (atención psicológica, acogida):", "o": ["Requiere sentencia judicial firme", "Requiere haber presentado una denuncia", "Solo se concede a mujeres sin ingresos", "No exige la presentación de denuncia"], "a": 3, "e": "La asistencia social integral es un derecho independiente de la denuncia penal. La ayuda económica de pago único sí está condicionada a tener rentas bajas y especiales dificultades para encontrar empleo."}, {"q": "Una enfermera del SMS víctima de violencia de género falta a un turno por una crisis derivada del maltrato. Según la LO 1/2004:", "o": ["Se le abrirá expediente hasta que haya sentencia", "La falta se justifica con el informe de los servicios sociales o de los servicios de salud", "Debe recuperar el turno obligatoriamente", "Solo se justifica si presenta una orden de alejamiento"], "a": 1, "e": "Las faltas de asistencia o de puntualidad motivadas por la situación de violencia se consideran justificadas cuando así lo determinen los servicios sociales o los servicios de salud, sin esperar a una resolución judicial."}, {"q": "Una mujer atendida en urgencias por lesiones causadas por su pareja no quiere denunciar. Respecto al parte de lesiones:", "o": ["No debe emitirse sin el consentimiento de la paciente", "Solo se emite si las lesiones son graves", "Es obligatorio emitirlo y remitirlo al juzgado, aunque la mujer no quiera denunciar", "Lo emite únicamente la policía"], "a": 2, "e": "El profesional sanitario que atiende lesiones que pueden constituir delito tiene la obligación legal de emitir el parte de lesiones y remitirlo al juzgado de guardia; no depende de la voluntad de la paciente. Debe informarla de ello."}, {"q": "Tras valorar a una mujer víctima de violencia, la enfermera aprecia un riesgo vital inminente (el agresor tiene armas y la ha amenazado de muerte). La actuación correcta es:", "o": ["No dejarla salir del centro, protegerla en una zona segura y avisar de inmediato al 112", "Darle el alta con folletos informativos y aconsejarle que llame al 112 desde casa", "Citarla en trabajo social la semana siguiente", "Llamar a su pareja para mediar"], "a": 0, "e": "Ante riesgo vital inminente, la mujer (y sus hijos) no debe salir del centro: se la protege en un área segura y el propio personal avisa a las Fuerzas y Cuerpos de Seguridad (112), además de emitir el parte de lesiones."}, {"q": "En urgencias, el acompañante de una paciente responde por ella de forma hostil e impide que hable. Según el protocolo, la enfermera debe:", "o": ["Enfrentarse a él y exigirle que salga del box", "Llamar a seguridad para expulsarlo inmediatamente", "Atenderla con él presente para no generar conflicto", "Usar un pretexto técnico (por ejemplo, un ECG o el triaje) para atender a la mujer a solas"], "a": 3, "e": "No se debe confrontar directamente a un posible maltratador, porque aumenta el riesgo para la mujer y el personal. Se usa un pretexto técnico neutro para quedarse a solas con ella y poder explorar la situación."}, {"q": "¿Cuál de los siguientes es un indicador de sospecha de violencia de género en la consulta?", "o": ["Acudir puntualmente a todas las revisiones", "Hiperfrecuentación por síntomas inespecíficos o inicio tardío del control del embarazo", "Una analítica normal", "Acudir siempre sola a la consulta"], "a": 1, "e": "Son indicadores la hiperfrecuentación (o el abandono de tratamientos y citas), el dolor crónico inespecífico, las ITS de repetición, el control prenatal tardío, los síntomas depresivos o ansiosos y la presencia de una pareja controladora."}, {"q": "La aplicación sistemática del WAST-corto en consulta para detectar casos de violencia corresponde al nivel de prevención:", "o": ["Primaria", "Primordial", "Secundaria", "Terciaria"], "a": 2, "e": "La prevención secundaria busca la detección precoz (cribados como WAST-corto o EASI). La primaria evita que la violencia ocurra (educación en igualdad) y la terciaria trata las secuelas y evita la revictimización."}, {"q": "Las dos preguntas del WAST-corto exploran:", "o": ["Si ha recibido golpes o agresiones sexuales en el último año", "El consumo de alcohol de la pareja y la existencia de armas", "La presencia de hijos y la situación económica", "La tensión en la relación de pareja y la dificultad para resolver las discusiones"], "a": 3, "e": "El WAST-corto no pregunta directamente por agresiones: explora la cantidad de tensión en la relación y la dificultad para resolver las discusiones (mucha, alguna, ninguna). Es una aproximación sutil."}, {"q": "En la validación española del WAST-corto se obtuvo un valor predictivo negativo del 98,1% y un valor predictivo positivo del 40,2%. Esto significa que:", "o": ["Un resultado positivo confirma el diagnóstico de violencia de género", "Un resultado negativo permite descartar la violencia con alta probabilidad, pero un positivo debe confirmarse con una entrevista", "La prueba no sirve para el cribado", "Tiene muchos falsos negativos"], "a": 1, "e": "Con una sensibilidad del 91,4% y un VPN del 98,1%, un resultado negativo descarta casi con seguridad. Por su VPP moderado (40,2%), un positivo no es un diagnóstico y obliga a confirmar en la fase de identificación. El patrón de referencia fue el Index of Spouse Abuse (ISA)."}, {"q": "La escala HITS de cribado de violencia en la pareja evalúa:", "o": ["Únicamente la violencia sexual", "La sobrecarga del cuidador", "El daño físico, los insultos, las amenazas y los gritos", "El maltrato a personas mayores"], "a": 2, "e": "HITS es el acrónimo de Hurt (daño físico), Insult (insultos), Threaten (amenazas) y Scream (gritos), en los últimos 12 meses. La versión E-HITS añade una pregunta sobre violencia sexual."}, {"q": "La escala de cribado de violencia clásicamente utilizada en el embarazo y las consultas obstétricas es:", "o": ["La AAS (Abuse Assessment Screen)", "La escala de Zarit", "El índice EASI", "El test de Barthel"], "a": 0, "e": "El AAS se usa en ginecología, obstetricia y maternidad y presta especial atención a la aparición o agravamiento de la violencia durante la gestación, un periodo de gran vulnerabilidad."}, {"q": "La norma autonómica de la Región de Murcia en materia de igualdad y violencia de género es la:", "o": ["Ley 3/2021 de Salud de la Región de Murcia", "Ley Orgánica 3/2007 de igualdad efectiva", "Ley 41/2002 de autonomía del paciente", "Ley 7/2007, de 4 de abril, para la Igualdad entre Mujeres y Hombres y de Protección contra la Violencia de Género"], "a": 3, "e": "En Murcia rige la Ley 7/2007, de 4 de abril, que impone el principio de transversalidad de la perspectiva de género en las políticas públicas. Se complementa con el Pacto Regional contra la Violencia de Género."}, {"q": "Respecto a la red CAVI de la Región de Murcia, es correcto:", "o": ["Solo atiende a mujeres que han presentado denuncia", "Ofrece atención psicológica, social y jurídica a mujeres víctimas sin exigir denuncia previa", "Es un registro informático de casos de maltrato infantil", "Es una unidad de la Guardia Civil"], "a": 1, "e": "Los Centros de Atención Especializada para Mujeres Víctimas de Violencia de Género (CAVI) prestan atención psicológica, social y jurídica sin exigir la interposición de denuncia."}, {"q": "En la Región de Murcia, el SEMA es:", "o": ["El registro unificado de maltrato infantil", "La unidad policial de atención a la mujer", "Un servicio de atención psicológica a los menores expuestos a la violencia de género", "Un cuestionario de cribado de violencia"], "a": 2, "e": "El SEMA es un recurso de atención psicológica para reparar el daño emocional de los hijos e hijas expuestos a la violencia de género. El registro de maltrato infantil es el RUMI; UFAM y EMUME son unidades de Policía Nacional y Guardia Civil."}, {"q": "En la escala de Zarit, una puntuación de 60 en el cuidador principal de un paciente con Alzheimer indica:", "o": ["Ausencia de sobrecarga", "Sobrecarga leve", "Que el paciente sufre maltrato", "Sobrecarga intensa"], "a": 3, "e": "La escala de Zarit (22 ítems, 0-88 puntos) indica: ≤ 46 sin sobrecarga, 47-55 sobrecarga leve y ≥ 56 sobrecarga intensa. La sobrecarga intensa obliga a movilizar ayudas, respiro familiar y apoyo para prevenir la negligencia o el maltrato."}, {"q": "En el índice EASI de sospecha de maltrato a personas mayores, un anciano con MMSE de 26 responde «sí» solo a la primera pregunta (depende de otros para tareas básicas). Esto indica:", "o": ["Que no hay sospecha de maltrato: la pregunta 1 no puntúa, solo valora la dependencia", "Sospecha de maltrato y obligación de emitir parte judicial", "Maltrato confirmado", "Que no puede aplicarse el EASI"], "a": 0, "e": "La pregunta 1 del EASI explora la dependencia y no puntúa para maltrato. La sospecha se establece con un «sí» en cualquiera de las preguntas 2 a 6 (negligencia, abuso emocional, económico, físico o sexual, y la observación del profesional). Se aplica si el MMSE es ≥ 24."}, {"q": "El síndrome de Münchausen por poderes se clasifica como:", "o": ["Negligencia o abandono pasivo", "Maltrato médico infantil: el cuidador provoca, inventa o exagera síntomas en el niño", "Maltrato emocional por rechazo", "Un trastorno del niño sin implicación del cuidador"], "a": 1, "e": "Es un maltrato activo (maltrato médico infantil): el cuidador, a menudo la madre, induce o falsifica síntomas en el niño, que es sometido a pruebas y tratamientos innecesarios. No es una negligencia, que es la forma más frecuente de maltrato infantil."}, {"q": "En Murcia, un caso registrado en la Hoja de Notificación de Riesgo y Maltrato Infantil como nivel leve requiere:", "o": ["Mantener al niño en su hogar con un seguimiento coordinado entre pediatría, escuela y servicios sociales", "Retirar la custodia de forma inmediata", "Avisar a la policía para separar al niño de la familia", "Archivar el caso sin más actuaciones"], "a": 0, "e": "La respuesta se gradúa: en el nivel leve el niño sigue en casa con seguimiento coordinado; en el moderado intervienen los programas comunitarios para corregir las habilidades parentales; solo en el grave se activa la protección de menores, fiscalía y policía con separación del niño."}]},
35: {"tema": 35, "titulo": "Valoración y cuidados de enfermería en pacientes con procesos infectocontagiosos. Hepatitis, tuberculosis, SIDA. Otros procesos infecciosos. Procedimientos y técnicas. Medidas de prevención y control", "programa": "Cadena epidemiológica y mecanismos de transmisión. Hepatitis víricas, serología del VHB y vacunación. Tuberculosis: Mantoux, efecto booster, IGRA, tratamiento, toxicidad y recogida de esputo. VIH/SIDA y profilaxis postexposición ocupacional (VIH, VHB, VHC). IRAS: EPINE, Clostridioides difficile, SARM y código sepsis. Aislamientos. Hemocultivos, EPI y gestión de residuos.", "preguntas": [{"q": "Un brote de Acinetobacter transmitido a través de las barandillas de las camas y los fonendoscopios de la planta. Estos objetos actúan como:", "o": ["Vectores", "Reservorios", "Fómites", "Huéspedes susceptibles"], "a": 2, "e": "Un fómite es un objeto inanimado que actúa como intermediario en la transmisión indirecta por contacto. Un vector es siempre un ser vivo (mosquito, garrapata)."}, {"q": "La transmisión por gotas se caracteriza por partículas:", "o": ["Mayores de 5 micras que caen rápidamente y alcanzan distancias cortas (≈ 1 metro)", "Menores de 5 micras que permanecen suspendidas en el aire", "Que se transmiten solo por fómites", "Que requieren habitación con presión negativa"], "a": 0, "e": "Las gotas de Flügge (> 5 µm) caen por gravedad y recorren distancias cortas, por lo que basta la mascarilla quirúrgica al acercarse. Los núcleos de Wells (≤ 5 µm) quedan suspendidos y requieren aislamiento aéreo."}, {"q": "¿Cuál de las siguientes hepatitis víricas nunca evoluciona a la cronicidad?", "o": ["Hepatitis B", "Hepatitis A", "Hepatitis C", "Hepatitis D"], "a": 1, "e": "La hepatitis A (fecal-oral) nunca cronifica y deja inmunidad permanente; la E tampoco suele cronificar. Las hepatitis B, C y D, de transmisión sanguínea, pueden cronificar."}, {"q": "La hepatitis vírica de transmisión fecal-oral que puede tener una mortalidad elevada en embarazadas durante el tercer trimestre es la:", "o": ["Hepatitis A", "Hepatitis B", "Hepatitis C", "Hepatitis E"], "a": 3, "e": "La hepatitis E, asociada a aguas contaminadas, suele ser autolimitada, pero en embarazadas del tercer trimestre puede causar un fallo hepático fulminante con una mortalidad de hasta el 20%."}, {"q": "El virus de la hepatitis D (delta) se caracteriza por:", "o": ["Ser un virus defectivo que necesita el HBsAg del VHB para infectar", "Transmitirse por vía fecal-oral", "Ser la causa más frecuente de hepatitis aguda", "Disponer de una vacuna específica propia"], "a": 0, "e": "El VHD es un virus ARN defectivo que necesita la envoltura (HBsAg) del VHB. Solo infecta a personas con VHB: coinfección (a la vez) o sobreinfección en un portador crónico (más grave). La vacuna del VHB protege indirectamente."}, {"q": "Respecto a la cronificación de la hepatitis B, es correcto:", "o": ["Es mayor en los adultos que en los niños", "Es igual a cualquier edad", "Es superior al 90% cuando la infección se adquiere en el periodo neonatal por vía vertical", "No cronifica nunca"], "a": 2, "e": "El riesgo de cronificación es inversamente proporcional a la edad: más del 90% en neonatos infectados por vía vertical y menos del 5% en adultos inmunocompetentes."}, {"q": "Una persona vacunada correctamente frente a la hepatitis B, sin contacto previo con el virus, presentará en la serología:", "o": ["HBsAg positivo y anti-HBc positivo", "Solo anti-HBs positivo", "Anti-HBs y anti-HBc positivos", "Anti-HBc IgM positivo"], "a": 1, "e": "La vacuna solo contiene HBsAg, por lo que genera únicamente anti-HBs. La presencia de anti-HBc indica contacto con el virus natural (infección pasada o actual)."}, {"q": "En el periodo ventana de la hepatitis B aguda, cuando el HBsAg ya no se detecta y el anti-HBs aún no ha aparecido, el único marcador que revela la infección es:", "o": ["HBeAg", "Anti-HBe", "Anti-HBs", "Anti-HBc IgM"], "a": 3, "e": "En el periodo ventana solo es positivo el anti-HBc IgM, marcador de infección aguda o reciente. Por eso un HBsAg negativo no descarta al 100% una infección aguda."}, {"q": "Se diagnostica hepatitis B crónica cuando el HBsAg permanece positivo durante más de:", "o": ["6 meses", "1 mes", "3 semanas", "2 años"], "a": 0, "e": "La persistencia del HBsAg más de 6 meses define la infección crónica, que predispone a cirrosis y hepatocarcinoma. El HBeAg indica replicación activa y alta contagiosidad."}, {"q": "La pauta estándar de vacunación frente a la hepatitis B en adultos es:", "o": ["2 dosis a los 0 y 6 meses en el glúteo", "Dosis única subcutánea", "3 dosis intramusculares en el deltoides a los 0, 1 y 6 meses", "Una dosis anual de recuerdo"], "a": 2, "e": "Se administran 3 dosis IM en el deltoides (0, 1 y 6 meses). Es eficaz si el anti-HBs supera 10 mUI/ml a los 1-2 meses de la última dosis; en inmunocompetentes no se necesitan recuerdos. La vacuna de la hepatitis A sí se da en 2 dosis (0 y 6-12 meses)."}, {"q": "La técnica correcta de administración de la prueba de Mantoux es:", "o": ["0,5 ml de PPD por vía subcutánea en el deltoides", "0,1 ml de PPD por vía intramuscular", "0,1 ml de PPD por vía subcutánea con el bisel hacia abajo", "0,1 ml de PPD por vía intradérmica en la cara anterior del antebrazo, con el bisel hacia arriba"], "a": 3, "e": "Se inyectan 0,1 ml de tuberculina (PPD) por vía intradérmica en la cara anterior del tercio medio del antebrazo, con el bisel hacia arriba, formando una pápula con aspecto de piel de naranja. No se debe frotar ni tapar."}, {"q": "La lectura de la prueba de Mantoux se realiza:", "o": ["A las 24 horas, midiendo el eritema", "A las 48-72 horas, midiendo el diámetro transversal de la induración", "A la semana, midiendo el diámetro longitudinal del eritema", "A los 30 minutos, como en las pruebas alérgicas"], "a": 1, "e": "Se lee a las 48-72 horas midiendo solo la induración (no el eritema) en su diámetro transversal al eje del brazo. El Mantoux diagnostica infección, no enfermedad activa."}, {"q": "En un cribado laboral, una enfermera tiene un primer Mantoux de 0 mm y, al repetirlo a las dos semanas, de 12 mm. Esto se interpreta como:", "o": ["Efecto booster: infección o vacunación BCG antigua, no un contagio reciente", "Una conversión por contagio reciente en el hospital", "Tuberculosis activa que requiere aislamiento", "Un error de técnica sin significado"], "a": 0, "e": "En infectados antiguos o vacunados con BCG la reactividad puede haberse debilitado: la primera prueba la «recuerda» y la segunda sale positiva. Indica infección o vacunación previa, no una infección reciente. Por eso se hace la prueba en dos etapas al inicio del cribado."}, {"q": "La principal ventaja de los test IGRA (como el QuantiFERON) frente al Mantoux es que:", "o": ["Diagnostican la enfermedad activa", "Se leen a las 72 horas en la piel", "No se ven alterados por la vacunación previa con BCG", "No necesitan extracción de sangre"], "a": 2, "e": "Los IGRA son análisis de sangre que miden el interferón gamma liberado por los linfocitos ante antígenos muy específicos del bacilo, por lo que no dan falsos positivos por la BCG. Como el Mantoux, detectan infección, no enfermedad."}, {"q": "La pauta estándar de tratamiento de la tuberculosis pulmonar activa sensible es:", "o": ["Isoniacida en monoterapia durante 9 meses", "Rifampicina durante 4 meses", "Isoniacida y rifapentina semanal durante 3 meses", "2 meses de isoniacida, rifampicina, pirazinamida y etambutol, seguidos de 4 meses de isoniacida y rifampicina"], "a": 3, "e": "La pauta clásica dura 6 meses: 2HRZE (fase intensiva) + 4HR (continuación). Las pautas con un solo fármaco o las cortas de 4R o 3HP se usan en la infección latente, no en la enfermedad activa."}, {"q": "Para prevenir la neuropatía periférica producida por la isoniacida se administra:", "o": ["Vitamina B12", "Piridoxina (vitamina B6)", "Ácido fólico", "Tiamina (vitamina B1)"], "a": 1, "e": "La isoniacida interfiere con el metabolismo de la vitamina B6 y puede causar neuropatía periférica (hormigueos y entumecimiento); se previene con piridoxina."}, {"q": "Una paciente en tratamiento con rifampicina debe ser informada de que:", "o": ["La orina, el sudor y las lágrimas pueden teñirse de color rojo-anaranjado y puede disminuir la eficacia de los anticonceptivos hormonales", "Debe tomar vitamina B6 para evitar la neuritis óptica", "Puede producirle gota", "Debe evitar el sol por fotosensibilidad grave"], "a": 0, "e": "La rifampicina tiñe los fluidos corporales de rojo-anaranjado (inofensivo; mancha las lentillas blandas) y es un potente inductor enzimático que reduce la eficacia de anticonceptivos orales y antirretrovirales. La gota se asocia a la pirazinamida."}, {"q": "El efecto adverso característico del etambutol es:", "o": ["La hiperuricemia", "La ototoxicidad", "La neuritis óptica con alteración en la distinción de los colores rojo y verde", "La coloración anaranjada de la orina"], "a": 2, "e": "El etambutol puede producir neuritis óptica retrobulbar (pérdida de agudeza visual y discromatopsia rojo-verde): requiere control oftalmológico. La pirazinamida produce hiperuricemia y la estreptomicina, ototoxicidad."}, {"q": "Para la recogida de una muestra de esputo para baciloscopia, la enfermera debe indicar al paciente que:", "o": ["Se cepille los dientes con pasta y use un colutorio antes de expectorar", "Recoja la saliva acumulada en la boca", "Tome la muestra por la noche tras la cena", "Se enjuague solo con agua y expectore a primera hora de la mañana tras una tos profunda"], "a": 3, "e": "Se recogen 3 muestras en días consecutivos, a primera hora y en ayunas. El enjuague se hace solo con agua: la pasta y los colutorios pueden destruir los bacilos y dar falsos negativos. Se busca moco bronquial, no saliva."}, {"q": "Un paciente con infección por VIH se considera en fase SIDA cuando presenta:", "o": ["Carga viral detectable", "Un recuento de linfocitos CD4 inferior a 200/mm³ o una enfermedad definitoria de SIDA", "Un recuento de CD4 inferior a 500/mm³ sin más", "Fiebre de más de una semana"], "a": 1, "e": "La fase SIDA se define por CD4 < 200/mm³ o por la aparición de enfermedades definitorias (neumonía por Pneumocystis, toxoplasmosis cerebral, retinitis por CMV, sarcoma de Kaposi, tuberculosis extrapulmonar, etc.)."}, {"q": "Tras un pinchazo accidental con una aguja usada en un paciente, la primera medida local correcta es:", "o": ["Dejar sangrar la herida sin exprimirla, lavarla con agua y jabón y aplicar un antiséptico", "Succionar la herida para extraer el posible virus", "Exprimir con fuerza la zona durante varios minutos", "Aplicar lejía sobre la herida"], "a": 0, "e": "Se favorece el sangrado sin exprimir ni succionar, se lava con agua y jabón y se aplica un antiséptico (povidona yodada o clorhexidina). En mucosas se lava con abundante suero o agua. Después se notifica de inmediato el accidente."}, {"q": "Respecto a la profilaxis postexposición ocupacional frente al VIH, es correcto:", "o": ["Puede iniciarse hasta 2 semanas después del accidente", "Se administra en dosis única", "Debe iniciarse lo antes posible, no más allá de 72 horas, y mantenerse 28 días", "Solo está indicada si el trabajador no está vacunado"], "a": 2, "e": "La PPE debe empezarse idealmente en las primeras 2-4 horas y nunca después de 72 h, con triple terapia antirretroviral durante 28 días. No existe vacuna frente al VIH."}, {"q": "Una enfermera vacunada frente a la hepatitis B, con un título documentado de anti-HBs de 120 mUI/ml, sufre un pinchazo con una aguja de un paciente HBsAg positivo. Respecto al VHB, debe:", "o": ["Recibir inmunoglobulina antihepatitis B", "Revacunarse con tres dosis", "Recibir inmunoglobulina y una dosis de vacuna", "No precisa ninguna profilaxis frente al VHB"], "a": 3, "e": "Si el trabajador es un vacunado respondedor (anti-HBs ≥ 10 mUI/ml) está protegido y no necesita nada. Si no está vacunado o no responde, se administra inmunoglobulina (mejor en 24 h, máximo 7 días) y vacuna en lugares distintos."}, {"q": "Tras un accidente biológico con un paciente fuente con hepatitis C, la actuación correcta es:", "o": ["Administrar inmunoglobulina específica frente al VHC", "Seguimiento con PCR del ARN del VHC a las 3-6 semanas y tratamiento precoz con antivirales si se positiviza", "Vacunar frente al VHC", "Iniciar antivirales de acción directa de forma profiláctica durante 28 días"], "a": 1, "e": "No existe vacuna, inmunoglobulina ni profilaxis postexposición frente al VHC. Se hace un seguimiento molecular y, si hay infección, se trata precozmente con antivirales de acción directa, que logran la curación."}, {"q": "Tras atender a un paciente con diarrea por Clostridioides difficile, la higiene de manos correcta es:", "o": ["Lavado con agua y jabón por arrastre mecánico, porque las esporas resisten al alcohol", "Fricción con solución hidroalcohólica durante 20 segundos", "Basta con quitarse los guantes", "Aplicar lejía diluida en las manos"], "a": 0, "e": "Las esporas de C. difficile no se destruyen con alcohol. Se deben lavar las manos con agua y jabón (arrastre mecánico), mantener aislamiento de contacto y desinfectar las superficies con hipoclorito (lejía)."}, {"q": "El protocolo de descolonización de un portador nasal de SARM consiste en:", "o": ["Vancomicina intravenosa durante 10 días", "Aislamiento aéreo y mascarilla FFP2", "Mupirocina al 2% nasal tres veces al día y duchas con clorhexidina al 4% durante 5 días", "Lavados nasales con suero fisiológico"], "a": 2, "e": "El portador asintomático de SARM se descoloniza con pomada nasal de mupirocina al 2% (3 veces al día) y duchas corporales con clorhexidina al 4% durante 5 días. El SARM requiere aislamiento de contacto."}, {"q": "Los criterios de la escala qSOFA para identificar a pacientes con infección de mal pronóstico son:", "o": ["Fiebre > 38 °C, leucocitosis y taquicardia", "Lactato > 2, plaquetas bajas y bilirrubina alta", "Saturación < 90%, diuresis baja y fiebre", "Frecuencia respiratoria ≥ 22, alteración del nivel de conciencia y presión sistólica ≤ 100 mmHg"], "a": 3, "e": "El qSOFA es positivo con 2 o más criterios clínicos: FR ≥ 22 rpm, alteración de la conciencia (Glasgow < 15) y PAS ≤ 100 mmHg. Activa el código sepsis: lactato, hemocultivos antes del antibiótico, antibiótico IV y fluidos (30 ml/kg) si hay hipotensión o lactato ≥ 4."}, {"q": "Un paciente ingresa con sospecha de tuberculosis pulmonar bacilífera. El aislamiento indicado es:", "o": ["De contacto, con bata y guantes", "Aéreo, en habitación individual con puerta cerrada y presión negativa, con mascarilla FFP2/FFP3 para el personal", "De gotas, con mascarilla quirúrgica al acercarse a menos de 1 metro", "Protector, con presión positiva"], "a": 1, "e": "La tuberculosis pulmonar o laríngea, el sarampión y la varicela requieren aislamiento aéreo: habitación individual, puerta cerrada, presión negativa con filtro HEPA, y FFP2/FFP3 colocada antes de entrar. Si sale de la habitación, el paciente lleva mascarilla quirúrgica."}, {"q": "Un paciente con neutropenia grave (< 500 neutrófilos/mm³) tras un trasplante de médula requiere:", "o": ["Aislamiento protector, en habitación con presión positiva y filtro HEPA", "Aislamiento aéreo con presión negativa", "Aislamiento de contacto con material exclusivo", "Ningún tipo de aislamiento"], "a": 0, "e": "El aislamiento protector o inverso protege al paciente del entorno: presión positiva (el aire filtrado sale hacia el pasillo), higiene de manos, bata, mascarilla, gorro y calzas, y prohibición de flores, plantas, fruta con piel o ensaladas crudas."}, {"q": "Al extraer hemocultivos con palomilla y sistema de vacío, el orden de llenado de los frascos es:", "o": ["Primero el anaerobio, porque es el más importante", "Es indiferente el orden", "Primero el anaerobio y después el aerobio, como con la jeringa", "Primero el aerobio y después el anaerobio, para que el aire del tubo de la palomilla vaya al frasco aerobio"], "a": 3, "e": "Con palomilla y vacío, el aire del tubo pasaría al primer frasco: por eso se llena primero el aerobio y después el anaerobio. Con jeringa, en cambio, se inocula primero el anaerobio para no introducir el aire que queda al final del émbolo."}]},
36: {"tema": 36, "titulo": "Cuidados de enfermería a pacientes al final de la vida. Principales problemas. Dolor y escalas de medida. Duelo. Apoyo al cuidador principal y familia. Cuidados en procesos crónicos", "programa": "Valoración y cuidados de enfermería a pacientes al final de la vida. Principales problemas. Dolor: características y escalas de medida. Duelo: tipos y manifestaciones. Apoyo al cuidador principal y familia. Valoración y cuidados de enfermería a pacientes con procesos crónicos.", "preguntas": [{"q": "El concepto de «dolor total» de Cicely Saunders incluye las dimensiones:", "o": ["Somática y visceral", "Física, emocional, social y espiritual", "Aguda y crónica", "Nociceptiva y neuropática"], "a": 1, "e": "Cicely Saunders, fundadora del movimiento hospice, describió el dolor total: el sufrimiento al final de la vida tiene dimensiones física, emocional o psicológica, social y espiritual, que deben atenderse a la vez."}, {"q": "¿Cuál de los siguientes es un principio de los cuidados paliativos?", "o": ["Prolongar la supervivencia por todos los medios", "Centrarse exclusivamente en el paciente, sin incluir a la familia", "Priorizar las pruebas diagnósticas hasta el final", "No acelerar ni retrasar el momento de la muerte"], "a": 3, "e": "Los cuidados paliativos afirman la vida, consideran la muerte un proceso natural, no pretenden acelerarla ni retrasarla, priorizan la calidad de vida, integran lo psicológico y espiritual y apoyan a la familia durante la enfermedad y el duelo."}, {"q": "En la herramienta NECPAL, la «pregunta sorpresa» que se formula el profesional es:", "o": ["¿Le sorprendería que este paciente falleciese en los próximos 12 meses?", "¿Le sorprendería que el paciente mejorase con tratamiento?", "¿Le sorprendería que falleciese en la próxima semana?", "¿Le sorprendería que el paciente pidiese la eutanasia?"], "a": 0, "e": "Si la respuesta es «no me sorprendería», se valoran indicadores objetivos generales (deterioro nutricional, funcional, cognitivo, ingresos repetidos) y específicos de la enfermedad. La pregunta sorpresa no se usa de forma aislada."}, {"q": "Un paciente con insuficiencia cardíaca en clase IV de la NYHA con ingresos repetidos. Respecto a los cuidados paliativos:", "o": ["No puede recibirlos porque no tiene cáncer", "Solo puede recibirlos si además tiene un tumor", "Puede ser identificado con necesidades paliativas: el NECPAL incluye enfermedades crónicas no oncológicas", "Solo pueden recibirlos los menores de 65 años"], "a": 2, "e": "Herramientas como el NECPAL se diseñaron precisamente para identificar necesidades paliativas en enfermedades crónicas avanzadas no oncológicas (insuficiencia cardíaca, EPOC, demencia, etc.)."}, {"q": "En la escala ECOG, un paciente que pasa encamado o sentado más del 50% de las horas de vigilia y tiene muy limitado el autocuidado corresponde al grado:", "o": ["1", "3", "0", "5"], "a": 1, "e": "ECOG 0: actividad normal; 3: encamado o sentado más del 50% del día; 4: encamado totalmente; 5: fallecido. Un Karnofsky de 40 equivale aproximadamente a un ECOG 3."}, {"q": "Un paciente en situación de agonía presenta estertores audibles a distancia. La actuación de enfermería más adecuada es:", "o": ["Aspirar secreciones por vía nasofaríngea profunda cada 2 horas", "Colocarlo en decúbito supino plano", "Aumentar la sueroterapia para fluidificar las secreciones", "Colocarlo en decúbito lateral o Sims con la cabeza algo elevada y administrar butilbromuro de escopolamina SC según pauta"], "a": 3, "e": "Se recurre al drenaje postural (decúbito lateral o Sims) y a un anticolinérgico SC (butilbromuro de escopolamina, que no atraviesa la barrera hematoencefálica). La aspiración profunda es ineficaz, molesta y aumenta las secreciones; el exceso de sueros las empeora."}, {"q": "Como medida no farmacológica para aliviar la disnea en un paciente al final de la vida se recomienda:", "o": ["Mantener la habitación cerrada y caldeada", "Colocarle en decúbito supino plano", "Dirigir una corriente de aire fresco a la cara (ventilador o abanico)", "Restringir la presencia de la familia"], "a": 2, "e": "El aire fresco sobre la cara estimula receptores del trigémino y reduce la sensación de ahogo. Se acompaña de ambiente fresco y ventilado y, farmacológicamente, de morfina como primera línea."}, {"q": "El fármaco de primera línea para el delirium en el paciente en fase terminal es:", "o": ["El haloperidol", "La morfina", "El diazepam", "El fenobarbital"], "a": 0, "e": "El haloperidol es el fármaco de primera elección. Si hay agitación intensa o refractaria se usa la levomepromazina, más sedante, y si fracasan los neurolépticos, el midazolam."}, {"q": "Un síntoma refractario se define como aquel que:", "o": ["Requiere tratamiento intensivo, pero acaba respondiendo", "No puede ser controlado adecuadamente con los tratamientos disponibles, aplicados por expertos, en un plazo razonable", "Molesta a la familia del paciente", "Aparece en la última semana de vida"], "a": 1, "e": "El síntoma refractario no se controla con los tratamientos disponibles en un tiempo razonable; el síntoma difícil requiere un abordaje intensivo pero acaba respondiendo. La sedación paliativa solo está indicada ante síntomas refractarios."}, {"q": "El fármaco de primera elección para la sedación paliativa es:", "o": ["La morfina", "El fenobarbital", "El propofol", "El midazolam"], "a": 3, "e": "El midazolam (SC o IV) es el fármaco de elección. La levomepromazina se usa si predomina el delirium, el fenobarbital es de tercera línea (en vía e infusor propios) y el propofol se reserva al hospital."}, {"q": "Un paciente con dolor tratado con morfina presenta, en sus últimas horas, angustia y disnea refractarias. Respecto a la sedación, es correcto:", "o": ["Subir la morfina hasta que el paciente quede dormido", "Retirar la morfina y sustituirla por midazolam", "Mantener la morfina a su dosis para el dolor o la disnea y añadir un sedante como el midazolam", "Sedar con tramadol"], "a": 2, "e": "Los opioides no se usan para inducir la sedación: subirlos buscando el sueño produce neurotoxicidad (mioclonías, hiperalgesia, delirium). Se mantienen a su dosis (para evitar abstinencia y controlar el síntoma) y se añade el sedante."}, {"q": "La decisión de no iniciar o retirar tratamientos de soporte vital que ya no aportan beneficio al paciente se denomina:", "o": ["Limitación o adecuación del esfuerzo terapéutico", "Eutanasia", "Sedación paliativa", "Obstinación terapéutica"], "a": 0, "e": "La limitación (adecuación) del esfuerzo terapéutico permite que la muerte llegue por la evolución natural de la enfermedad y evita la obstinación terapéutica. La eutanasia, en cambio, provoca la muerte de forma intencionada a petición del paciente."}, {"q": "Según la Ley 41/2002, el documento de instrucciones previas puede otorgarlo:", "o": ["Cualquier menor a partir de 12 años", "Solo el médico responsable", "La familia en nombre del paciente inconsciente", "Una persona mayor de edad, capaz y libre"], "a": 3, "e": "Las instrucciones previas las otorga una persona mayor de edad, capaz y libre, para que se cumplan cuando no pueda expresar su voluntad; puede designar un representante como interlocutor con el equipo."}, {"q": "La norma que regula la eutanasia en España es la:", "o": ["Ley Orgánica 3/2021", "Ley 41/2002", "Ley 16/2003", "Ley Orgánica 1/2023"], "a": 0, "e": "La Ley Orgánica 3/2021 de regulación de la eutanasia exige ser mayor de edad, capaz y consciente, con nacionalidad o residencia legal, y sufrir una enfermedad grave e incurable o un padecimiento grave, crónico e imposibilitante. Contempla la administración directa por el profesional o la prescripción para autoadministración."}, {"q": "Un paciente refiere dolor abdominal difuso, mal localizado, de tipo cólico, acompañado de náuseas y sudoración. Se trata de un dolor:", "o": ["Somático", "Neuropático", "Visceral", "Irruptivo incidental"], "a": 2, "e": "El dolor visceral es difuso, mal localizado, cólico o referido y suele acompañarse de cortejo vegetativo. El somático está bien localizado (por ejemplo, óseo) y el neuropático se describe como quemazón o descargas."}, {"q": "Un paciente con infiltración tumoral de un plexo nervioso describe su dolor como quemazón y descargas eléctricas. Además de los analgésicos, suele requerir:", "o": ["Únicamente paracetamol", "Fármacos coadyuvantes como gabapentina, pregabalina o antidepresivos", "Antiinflamatorios a dosis altas exclusivamente", "Corticoides tópicos"], "a": 1, "e": "El dolor neuropático (lesión del sistema nervioso: quemazón, descargas, alodinia) responde mal a los analgésicos convencionales y requiere coadyuvantes (anticonvulsivantes como gabapentina o pregabalina, antidepresivos)."}, {"q": "Un paciente con morfina de liberación prolongada cada 12 horas refiere que el dolor reaparece de forma progresiva una o dos horas antes de cada toma. Se trata de:", "o": ["Dolor irruptivo incidental, que se trata con rescates", "Dolor neuropático", "Dolor irruptivo espontáneo", "Fallo de final de dosis, que obliga a ajustar la dosis basal"], "a": 3, "e": "El dolor que aparece antes de la siguiente dosis pautada indica fallo de final de dosis y requiere aumentar la dosis basal (o acortar el intervalo). El dolor irruptivo incidental es previsible (movilizaciones, curas) y se trata con rescates."}, {"q": "Respecto a la escala visual analógica (EVA), es correcto:", "o": ["Es una línea de 10 cm sin números; de 4 a 6 indica dolor moderado", "Es una escala de caras para niños menores de 2 años", "Se basa en la observación de la conducta del paciente", "Su puntuación máxima es 20"], "a": 0, "e": "La EVA es una línea de 10 cm sin números entre «sin dolor» y «el peor dolor imaginable». Interpretación: 1-3 leve, 4-6 moderado, 7-10 intenso. Requiere capacidad de abstracción del paciente."}, {"q": "Para valorar el dolor en una persona con demencia avanzada que no puede comunicarse verbalmente, una escala validada es:", "o": ["La EVA", "La escala numérica", "La PAINAD", "La escala verbal descriptiva"], "a": 2, "e": "La PAINAD (Pain Assessment in Advanced Dementia) valora respiración, vocalización, expresión facial, lenguaje corporal y consolabilidad (0-10). Las escalas EVA, numérica y verbal exigen que el paciente se comunique."}, {"q": "De las escalas de dolor para pacientes no comunicativos, la que incluye cambios fisiológicos (pulso, tensión, temperatura) y cambios físicos (lesiones) es la:", "o": ["Escala de Campbell", "Escala PAINAD", "Escala FLACC", "Escala de Abbey"], "a": 3, "e": "La escala de Abbey valora 6 parámetros, entre ellos los cambios fisiológicos y físicos; el dolor es grave a partir de 14 puntos. Campbell y PAINAD son conductuales y puntúan de 0 a 10."}, {"q": "En un infusor subcutáneo para un paciente paliativo, ¿qué fármaco debe administrarse por separado por su incompatibilidad con la mayoría de las mezclas?", "o": ["La morfina", "La dexametasona", "El midazolam", "El haloperidol"], "a": 1, "e": "La dexametasona tiende a precipitar con otros fármacos y se administra sola. Morfina, midazolam, haloperidol, butilbromuro de escopolamina y metoclopramida suelen ser compatibles en el mismo infusor. El diazepam no se administra por vía SC."}, {"q": "Según la escalera analgésica de la OMS, es incorrecto asociar:", "o": ["Un opioide débil con un opioide potente", "Un opioide potente con paracetamol", "Un opioide débil con un AINE", "Un coadyuvante en cualquier escalón"], "a": 0, "e": "No se combinan opioides débiles (tramadol, codeína) con potentes (morfina, fentanilo) porque compiten por los mismos receptores. Sí pueden asociarse los fármacos del primer escalón y los coadyuvantes."}, {"q": "Los opioides potentes del tercer escalón de la OMS (como la morfina) se caracterizan por:", "o": ["Tener techo terapéutico", "Indicarse solo en el dolor leve", "No tener techo terapéutico: la dosis adecuada es la que controla el dolor con efectos tolerables", "No poder administrarse por vía subcutánea"], "a": 2, "e": "Los fármacos del primer y segundo escalón tienen techo terapéutico; los opioides potentes no: se ajustan hasta controlar el dolor con efectos adversos asumibles. El cuarto escalón incluye técnicas invasivas (bloqueos, vía epidural o intratecal)."}, {"q": "Según Kübler-Ross, la fase en la que el paciente intenta negociar, a menudo en secreto, para posponer o revertir lo que ocurre es la de:", "o": ["Negación", "Pacto o negociación", "Ira", "Aceptación"], "a": 1, "e": "Las fases de Kübler-Ross son negación, ira, pacto, depresión y aceptación, y no siempre se suceden en ese orden. En el pacto la persona intenta negociar un aplazamiento a cambio de promesas."}, {"q": "Según el modelo de tareas de Worden, prescribir ansiolíticos de forma sistemática al doliente desde el primer día para que «no sufra» puede dificultar la tarea de:", "o": ["Aceptar la realidad de la pérdida", "Adaptarse a un medio sin el fallecido", "Recolocar emocionalmente al fallecido", "Elaborar y experimentar el dolor de la pérdida"], "a": 3, "e": "La tarea II de Worden exige sentir y elaborar el dolor. Evitarlo con medicación excesiva, trabajo frenético o tóxicos perpetúa el duelo y favorece el duelo crónico. Las tareas son: aceptar, elaborar, adaptarse y recolocar."}, {"q": "Una mujer acude repetidamente a urgencias por dolores físicos sin causa orgánica tras el fallecimiento de su marido, sin relacionarlos con la pérdida. Se trata de un duelo:", "o": ["Anticipado", "Normal", "Enmascarado", "Crónico"], "a": 2, "e": "En el duelo enmascarado las emociones no se viven conscientemente y se expresan como síntomas físicos o conductas que la persona no relaciona con la pérdida. El anticipado empieza antes de la muerte y el crónico se estanca años con la misma intensidad."}, {"q": "Según la CIE-11, el trastorno por duelo prolongado requiere una duración superior a:", "o": ["6 meses tras el fallecimiento", "1 mes", "3 meses", "5 años"], "a": 0, "e": "El trastorno por duelo prolongado (añoranza persistente, dolor emocional intenso e incapacidad para retomar la vida) exige más de 6 meses según la CIE-11 y más de 12 meses según el DSM-5-TR."}, {"q": "En la versión abreviada de 7 ítems de la escala de Zarit, la sobrecarga intensa se establece a partir de:", "o": ["46 puntos", "17 puntos", "56 puntos", "88 puntos"], "a": 1, "e": "En la versión abreviada (7 ítems) el punto de corte es 17. En la versión completa de 22 ítems (0-88): ≤ 46 sin sobrecarga, 47-55 leve y ≥ 56 intensa."}, {"q": "Según los criterios de Ollero, un paciente se considera pluripatológico cuando:", "o": ["Tiene más de 75 años", "Toma más de 5 fármacos al día", "Presenta tres enfermedades crónicas de la misma categoría clínica", "Presenta enfermedades crónicas incluidas en dos o más categorías clínicas distintas"], "a": 3, "e": "La definición exige enfermedades de dos o más categorías distintas de Ollero (cardíaca, renal-autoinmune, respiratoria, digestiva, neurológica, arteriopatía-diabetes, oncohematológica...). Tres patologías del mismo bloque no lo convierten en pluripatológico."}, {"q": "En el test de Pfeiffer, un anciano con estudios primarios comete 9 errores. Esto indica:", "o": ["Deterioro cognitivo grave", "Función cognitiva normal, porque la puntuación es alta", "Deterioro cognitivo leve", "Que debe repetirse sin corrección"], "a": 0, "e": "El Pfeiffer cuenta errores: 0-2 normal, 3-4 leve, 5-7 moderado y 8-10 deterioro grave. Se resta 1 error si la persona no tiene estudios y se suma 1 si tiene estudios superiores. En el MEC de Lobo, en cambio, se cuentan aciertos."}]},
37: {"tema": 37, "titulo": "Desarrollo de la conducta humana. Tipos de personalidad. Hábitos. Motivación. Factores socioculturales y salud. Componentes psicosociales y de adaptación del paciente hospitalizado. Intervención de enfermería", "programa": "Desarrollo de la conducta humana: etapas del desarrollo. Tipos de personalidad. Hábitos. Motivación. Factores socioculturales: su incidencia en la salud. Componentes psicosociales y de adaptación del paciente hospitalizado. Intervención de enfermería.", "preguntas": [{"q": "Un paciente hipertenso solo toma la medicación si la enfermera le ofrece una recompensa o cuando nota el alivio inmediato de su cefalea. Según Kohlberg, su razonamiento moral corresponde al:", "o": ["Estadio 4: orden social y autoridad", "Estadio 6: principios éticos universales", "Estadio 2: individualismo e intercambio instrumental", "Estadio 3: aprobación interpersonal"], "a": 2, "e": "Actuar a cambio de un beneficio o recompensa es propio del estadio 2 (nivel preconvencional). En el estadio 4 la persona cumple porque respeta las normas y el orden establecido."}, {"q": "Según Kohlberg, el nivel de razonamiento moral que alcanzan los adolescentes y la mayoría de los adultos es el:", "o": ["Convencional", "Preconvencional", "Posconvencional", "Sensoriomotor"], "a": 0, "e": "El nivel convencional (estadios 3 y 4: aprobación de los demás y orden social) es el de la mayoría de adolescentes y adultos. El posconvencional (contrato social y principios universales) solo lo alcanza una minoría."}, {"q": "René Spitz atribuyó el «hospitalismo» observado en lactantes institucionalizados a:", "o": ["Las infecciones nosocomiales por la mala higiene", "La deprivación afectiva y la ausencia de una figura de apego estable", "La desnutrición calórica", "Factores genéticos"], "a": 1, "e": "Spitz demostró que los lactantes enfermaban y morían pese a recibir buena higiene y nutrición: la causa era la falta de afecto y de una figura de apego. Sus estudios fueron la base de la teoría del apego de Bowlby."}, {"q": "La depresión anaclítica descrita por Spitz aparece en:", "o": ["Adolescentes con fracaso escolar", "Ancianos institucionalizados", "Lactantes nacidos prematuros", "Niños pequeños separados bruscamente de su madre tras haber establecido un vínculo con ella"], "a": 3, "e": "La depresión anaclítica surge tras la separación brusca de la figura de apego en un niño que ya tenía un vínculo: apatía, llanto, retraimiento, pérdida de peso, retraso y más infecciones."}, {"q": "Según Piaget, el egocentrismo intelectual y el pensamiento simbólico son característicos de la etapa:", "o": ["Preoperacional (2-7 años)", "Sensoriomotora (0-2 años)", "De las operaciones concretas (7-11 años)", "De las operaciones formales (desde los 11-12 años)"], "a": 0, "e": "En la etapa preoperacional el niño domina el lenguaje y el símbolo, pero es egocéntrico y no comprende la conservación. La permanencia del objeto se adquiere en la sensoriomotora y el pensamiento abstracto, en las operaciones formales."}, {"q": "Según Erikson, la crisis psicosocial de la vejez es:", "o": ["Confianza frente a desconfianza", "Identidad frente a confusión de roles", "Intimidad frente a aislamiento", "Integridad del yo frente a desesperación"], "a": 3, "e": "Erikson describe 8 crisis a lo largo de la vida. En la senectud se plantea la integridad del yo frente a la desesperación, que influye en la aceptación de la enfermedad y la muerte."}, {"q": "Según la teoría de los somatotipos de Sheldon, el ectomorfo (delgado y frágil) se asocia a un temperamento:", "o": ["Viscerotónico: sociable y amante de la comodidad", "Cerebrotónico: introvertido, sensible y aprensivo", "Somatotónico: enérgico y competitivo", "Pícnico: ciclotímico"], "a": 1, "e": "Sheldon relacionó el endomorfo con el temperamento viscerotónico, el mesomorfo con el somatotónico y el ectomorfo con el cerebrotónico. Estas teorías biotipológicas están hoy superadas."}, {"q": "Un paciente hospitalizado exige que su ropa de cama esté perfectamente alineada y que se respeten estrictamente sus horarios, como forma habitual de ser, sin vivirlo con angustia. Esto orienta a:", "o": ["Trastorno obsesivo-compulsivo (TOC) de ansiedad", "Trastorno límite de la personalidad", "Trastorno obsesivo-compulsivo de la personalidad, de carácter egosintónico", "Trastorno esquizoide"], "a": 2, "e": "El trastorno obsesivo-compulsivo de la personalidad (anancástico) es un patrón de perfeccionismo, rigidez y control vivido como propio (egosintónico). El TOC cursa con obsesiones y compulsiones que generan angustia (egodistónico). Conviene pactar con el paciente cierto control de sus rutinas."}, {"q": "Ante un paciente con trastorno límite de la personalidad que amenaza con autolesionarse si no se le permite saltarse las normas de visita, la actuación de enfermería adecuada es:", "o": ["Establecer límites firmes y uniformes por parte de todo el equipo y vigilar el riesgo de autolesión", "Ceder a sus peticiones para evitar su sufrimiento", "Negociar con cada profesional por separado", "Ignorar las amenazas"], "a": 0, "e": "En los trastornos del grupo B (límite, antisocial) el equipo debe mantener límites firmes y una comunicación unificada, sin ceder al chantaje (refuerza la conducta) y vigilando el riesgo real de autolesión."}, {"q": "Según el DSM-5-TR, el trastorno de la personalidad por evitación pertenece al grupo:", "o": ["A (raros o excéntricos)", "B (dramáticos o emocionales)", "Es un trastorno de ansiedad, no de personalidad", "C (ansiosos o temerosos)"], "a": 3, "e": "Grupo A: paranoide, esquizoide, esquizotípico. Grupo B: antisocial, límite, histriónico, narcisista. Grupo C: evitación, dependiente y obsesivo-compulsivo de la personalidad."}, {"q": "El patrón de conducta tipo A, descrito por Friedman y Rosenman, se caracteriza por:", "o": ["Conformismo y supresión de la ira", "Competitividad, prisa, impaciencia y hostilidad, y se asocia a cardiopatía isquémica", "Afectividad negativa e inhibición social", "Tranquilidad y disfrute del ocio"], "a": 1, "e": "El patrón A (competitividad, urgencia temporal, impaciencia y hostilidad) es un factor de riesgo de cardiopatía isquémica; la hostilidad es su componente más dañino. El patrón B, tranquilo, es protector."}, {"q": "El patrón de conducta tipo C (Temoshok) se caracteriza por conformismo, complacencia y supresión de las emociones negativas. Se asocia a:", "o": ["Ser la causa directa del cáncer", "Mayor riesgo de infarto por hostilidad", "Peor pronóstico y progresión más rápida del cáncer, por inmunosupresión", "Mayor esperanza de vida"], "a": 2, "e": "La inhibición emocional mantenida eleva el cortisol y deprime la inmunidad (células NK), lo que se asocia a peor evolución del cáncer. No se considera la causa del tumor."}, {"q": "El patrón de conducta tipo D (Denollet) se define por la combinación de:", "o": ["Afectividad negativa e inhibición social", "Hostilidad y prisa", "Conformismo y deseo de agradar", "Extraversión y búsqueda de sensaciones"], "a": 0, "e": "El tipo D («distressed») combina afectividad negativa (ansiedad, tristeza, preocupación) e inhibición social (no expresa sus emociones). Sufre en silencio y tiene más mortalidad tras el infarto."}, {"q": "En el modelo de Lazarus y Folkman, la evaluación en la que el paciente valora si un diagnóstico supone un daño, una amenaza o un desafío es la:", "o": ["Evaluación secundaria", "Reevaluación", "Fase de alarma", "Evaluación primaria"], "a": 3, "e": "La evaluación primaria responde a «¿qué significa esto para mí?» (daño, amenaza o desafío); la secundaria, a «¿con qué recursos cuento?»; la reevaluación corrige según los resultados."}, {"q": "Un paciente con diabetes recién diagnosticada pide información, planifica sus comidas y organiza sus controles. Utiliza un afrontamiento:", "o": ["Centrado en la emoción", "Centrado en el problema", "Por negación", "Por evitación"], "a": 1, "e": "El afrontamiento centrado en el problema actúa sobre la fuente del estrés (informarse, planificar, cambiar hábitos). El centrado en la emoción intenta regular el malestar, sobre todo cuando la situación no puede cambiarse."}, {"q": "Ante una situación que el paciente valora como inmodificable (por ejemplo, una amputación ya realizada), el tipo de afrontamiento que suele predominar es el:", "o": ["Centrado en el problema", "Instrumental", "Centrado en la emoción", "Preconvencional"], "a": 2, "e": "Cuando la situación no se puede cambiar, el afrontamiento se orienta a regular la respuesta emocional (relajación, reinterpretación positiva, expresión del llanto o, de forma desadaptativa, negación o abuso de fármacos). Folkman añadió además el afrontamiento centrado en el significado."}, {"q": "Las fases del síndrome general de adaptación de Hans Selye son:", "o": ["Alarma, resistencia y agotamiento", "Negación, ira y aceptación", "Precontemplación, acción y mantenimiento", "Evaluación primaria, secundaria y reevaluación"], "a": 0, "e": "Selye describió una respuesta inespecífica al estrés en tres fases: alarma (simpático, adrenalina), resistencia (cortisol) y agotamiento (inmunosupresión, úlceras de estrés)."}, {"q": "En el síndrome general de adaptación, la liberación mantenida de cortisol con hiperglucemia caracteriza la fase de:", "o": ["Alarma", "Agotamiento inicial", "Reevaluación", "Resistencia"], "a": 3, "e": "En la fase de resistencia el estresor persiste y se activa el eje hipotálamo-hipófisis-suprarrenal (cortisol). La fase de alarma depende del simpático y la adrenalina; el agotamiento llega cuando se consumen las reservas."}, {"q": "Un paciente recién operado refiere un dolor de 8 sobre 10 en la EVA. Según la jerarquía de Maslow, la enfermera debe:", "o": ["Aprovechar para hacer la educación sanitaria del alta", "Controlar primero el dolor y educar después", "Hablarle de sus objetivos de autorrealización", "Posponer la analgesia hasta terminar la educación"], "a": 1, "e": "Las necesidades fisiológicas (como el alivio del dolor) deben cubrirse antes que las superiores. Con dolor intenso, el paciente no puede atender ni aprender: primero analgesia y después educación."}, {"q": "En el modelo transteórico de Prochaska y DiClemente, la persona que es consciente de su problema y sopesa los pros y contras de cambiar, con ambivalencia, está en la fase de:", "o": ["Contemplación", "Precontemplación", "Acción", "Mantenimiento"], "a": 0, "e": "En la contemplación la persona reconoce el problema pero duda. En la precontemplación no piensa cambiar en los próximos 6 meses; en la preparación decide hacerlo en los próximos 30 días."}, {"q": "En el modelo transteórico, un fumador que ha decidido dejarlo en los próximos 30 días y ya ha pedido cita en la consulta de deshabituación está en la fase de:", "o": ["Contemplación", "Mantenimiento", "Preparación", "Recaída"], "a": 2, "e": "La preparación (o determinación) es la decisión de actuar de forma inminente (próximos 30 días) con primeros pasos concretos. Después vienen la acción y el mantenimiento."}, {"q": "En el modelo transteórico, se considera que una persona está en la fase de mantenimiento cuando el nuevo hábito se ha sostenido:", "o": ["Durante una semana", "Durante un mes", "Durante tres meses", "Durante más de seis meses"], "a": 3, "e": "El mantenimiento se alcanza cuando el cambio se ha sostenido más de 6 meses; el objetivo es prevenir recaídas. La recaída se considera parte normal del proceso y no debe juzgarse."}, {"q": "El Informe Lalonde (1974) agrupó los determinantes de la salud en:", "o": ["Edad, sexo y genética", "Biología humana, medio ambiente, estilo de vida y sistema sanitario", "Factores individuales, familiares y laborales", "Nivel de renta, educación y vivienda"], "a": 1, "e": "Lalonde describió cuatro grandes determinantes: biología humana, medio ambiente, estilo de vida y organización del sistema sanitario."}, {"q": "Según los datos clásicos derivados del modelo de Lalonde (Dever), el estilo de vida:", "o": ["Explica alrededor del 43% de la mortalidad y recibe en torno al 1,5% del gasto", "Explica el 11% de la mortalidad y recibe el 90% del gasto", "No influye en la mortalidad", "Recibe la mayor parte del gasto sanitario"], "a": 0, "e": "Es la paradoja clásica: el estilo de vida explica ≈ 43% de la mortalidad pero recibe ≈ 1,5% del gasto, mientras que el sistema sanitario explica ≈ 11% y absorbe ≈ 90%. Justifica la inversión en prevención y educación para la salud."}, {"q": "En el modelo de Dahlgren y Whitehead, el apoyo de la familia, los amigos y las buenas relaciones con los compañeros de trabajo pertenecen a la capa de:", "o": ["Edad, sexo y factores hereditarios", "Estilos de vida individuales", "Redes sociales y comunitarias", "Condiciones socioeconómicas, culturales y ambientales generales"], "a": 2, "e": "Las redes sociales y comunitarias (familia, amistades, relaciones laborales, participación comunitaria) actúan como amortiguador del estrés. La capa de condiciones de vida y trabajo incluye factores materiales como vivienda, alimentación, agua o empleo."}, {"q": "Según Leininger, cuando una práctica cultural del paciente puede adaptarse al tratamiento mediante el diálogo, la enfermera realiza una:", "o": ["Reestructuración de los cuidados culturales", "Preservación de los cuidados culturales", "Imposición del cuidado biomédico", "Acomodación o negociación de los cuidados culturales"], "a": 3, "e": "Leininger propone tres modos de acción: preservación (mantener prácticas beneficiosas), acomodación o negociación (adaptarlas al tratamiento) y reestructuración (modificar las perjudiciales con respeto). Su modelo gráfico es el del Sol Naciente."}, {"q": "Una anciana presenta ansiedad, irritabilidad, insomnio y confusión tras ser trasladada de su domicilio a una residencia. El diagnóstico NANDA más adecuado es:", "o": ["Deterioro de la memoria", "Síndrome de estrés del traslado", "Riesgo de caídas", "Desesperanza"], "a": 1, "e": "El síndrome de estrés del traslado (00114) describe la alteración física y psicosocial tras un cambio de entorno, frecuente en ancianos: ansiedad, ira, soledad, depresión, insomnio y confusión."}, {"q": "En el modelo de Callista Roy, el ruido de los monitores que impide dormir a un paciente ingresado es un estímulo:", "o": ["Focal", "Residual", "Contextual", "Interdependiente"], "a": 2, "e": "El estímulo focal es el que afronta directamente la persona; los contextuales son los demás factores del entorno que influyen (ruido, luces, ausencia de familia); los residuales son creencias o experiencias previas de efecto incierto."}, {"q": "Los cuatro modos de adaptación del modelo de Callista Roy son:", "o": ["Fisiológico, autoconcepto, función del rol e interdependencia", "Alarma, resistencia, agotamiento y recuperación", "Preservación, acomodación, reestructuración y repatronaje", "Precontemplación, contemplación, acción y mantenimiento"], "a": 0, "e": "Roy considera a la persona un sistema adaptativo que responde a estímulos focales, contextuales y residuales a través de cuatro modos: fisiológico-físico, autoconcepto, función del rol e interdependencia."}, {"q": "Un anciano va a ser trasladado de la planta de agudos a una unidad de media estancia. La intervención NIC indicada para prevenir su malestar es:", "o": ["Prevención de caídas", "Potenciación de la autoestima", "Planificación del alta", "Disminución del estrés por traslado"], "a": 3, "e": "La NIC Disminución del estrés por traslado (5350) incluye preparar e informar con antelación al paciente y la familia y facilitar que se familiarice con el nuevo entorno."}]},
38: {"tema": 38, "titulo": "Cuidados de enfermería a personas con problemas de salud mental. Otras alteraciones psíquicas. Prevención del suicidio. Valoración familiar y social. Apoyo al cuidador. Drogodependencias. Plan Nacional sobre Drogas", "programa": "Valoración y cuidados de enfermería a personas con problemas de salud mental. Otras alteraciones psíquicas. Prevención y control ante el riesgo del suicidio. Valoración de la situación familiar y social. El apoyo al cuidador principal y familia. Drogodependencias. Plan Nacional sobre Drogas: generalidades.", "preguntas": [{"q": "En el examen del estado mental, la percepción de un objeto o estímulo que no existe en la realidad se denomina:", "o": ["Ilusión", "Alucinación", "Idea delirante", "Idea sobrevalorada"], "a": 1, "e": "La alucinación es una percepción sin objeto real; la ilusión es la deformación de un estímulo real. El delirio es una alteración del contenido del pensamiento (creencia falsa e irreductible)."}, {"q": "El paso muy rápido de un tema a otro en el discurso, sin llegar a concluir el anterior, se denomina:", "o": ["Bloqueo del pensamiento", "Bradilalia", "Disgregación", "Fuga de ideas"], "a": 3, "e": "La fuga de ideas es típica de la manía. La disgregación es la pérdida del hilo asociativo, el bloqueo es la interrupción brusca del pensamiento y la bradilalia, la lentitud del habla."}, {"q": "La sensación subjetiva de inquietud motora que obliga al paciente a moverse constantemente, frecuente con antipsicóticos, se denomina:", "o": ["Acatisia", "Catatonía", "Distonía aguda", "Discinesia tardía"], "a": 0, "e": "La acatisia es una inquietud motora subjetiva y forma parte de los síntomas extrapiramidales, junto a la distonía aguda, el parkinsonismo y la discinesia tardía."}, {"q": "Respecto a la ansiedad en las taxonomías enfermeras, es correcto que:", "o": ["«Nivel de ansiedad» es un diagnóstico NANDA", "«Ansiedad» es una intervención NIC", "«Nivel de ansiedad» (1211) es un resultado NOC y «Ansiedad» (00146) es un diagnóstico NANDA", "Ambos son resultados NOC"], "a": 2, "e": "Ansiedad (00146) y Estrés por sobrecarga (00177) son diagnósticos NANDA-I; Nivel de ansiedad (1211) y Nivel de estrés (1212) son resultados NOC que miden su evolución."}, {"q": "Ante un paciente con agitación psicomotriz, la primera medida que debe intentarse es:", "o": ["La contención verbal (desescalada)", "La contención mecánica inmediata", "La contención farmacológica intramuscular", "El aislamiento en una habitación cerrada con llave"], "a": 0, "e": "La escalada es: contención verbal (tono calmado, distancia de seguridad, ofrecer opciones), medidas ambientales y medicación oral voluntaria, contención farmacológica y, solo si todo fracasa o hay urgencia vital, contención mecánica."}, {"q": "Durante una contención mecánica, el paciente debe quedar:", "o": ["En decúbito prono para evitar la aspiración", "En decúbito lateral con la cama plana", "En sedestación sin sujeciones", "En decúbito supino con la cabecera de la cama elevada"], "a": 3, "e": "Se sujeta en decúbito supino con la cabecera elevada (el manual indica 45°) para prevenir la broncoaspiración, salvo contraindicación. El decúbito prono está contraindicado por riesgo de asfixia."}, {"q": "Respecto a la indicación de la contención mecánica, es correcto:", "o": ["Es una decisión exclusiva de la enfermera que no precisa registro", "La indica el médico por escrito, aunque en una urgencia extrema enfermería puede iniciarla y avisar de inmediato al médico", "Puede aplicarse como castigo ante conductas inadecuadas", "Puede mantenerse indefinidamente para comodidad del equipo"], "a": 1, "e": "La contención es una medida excepcional, proporcionada y lo más breve posible. La indicación es médica y debe registrarse; en caso de riesgo inminente, enfermería puede iniciarla y comunicarlo inmediatamente al médico. Nunca es un castigo."}, {"q": "En un paciente tratado con sales de litio, se considera tóxica una litemia superior a:", "o": ["0,3 mEq/l", "0,6 mEq/l", "1,5 mEq/l", "5 mEq/l"], "a": 2, "e": "El rango terapéutico de mantenimiento es 0,6-1,2 mEq/l y por encima de 1,5 mEq/l aparece toxicidad (temblor grosero, ataxia, disartria, diarrea, vómitos, confusión). El litio tiene un margen terapéutico estrecho."}, {"q": "A un paciente en tratamiento con litio que presenta edemas leves se le debe aconsejar:", "o": ["Mantener una ingesta normal de sal y una buena hidratación", "Una dieta sin sal estricta", "Restringir los líquidos", "Tomar diuréticos por su cuenta"], "a": 0, "e": "La deshidratación y las dietas pobres en sodio hacen que el riñón reabsorba más litio y precipitan la intoxicación. El paciente debe mantener una ingesta de sal y líquidos normal y constante."}, {"q": "Un paciente en tratamiento con un IMAO debe evitar alimentos ricos en tiramina, como:", "o": ["Leche y yogur fresco", "Arroz y pasta", "Pollo y pescado frescos", "Quesos curados, embutidos, ahumados y vino tinto"], "a": 3, "e": "Los IMAO impiden la degradación de la tiramina, cuya acumulación provoca crisis hipertensivas graves. Deben evitarse quesos curados, embutidos, ahumados, conservas, habas, cerveza y vino tinto."}, {"q": "Un paciente tratado con haloperidol presenta una crisis oculógira y tortícolis. El fármaco de elección para revertirla es:", "o": ["Flumazenilo", "Biperideno intramuscular", "Naloxona", "Más dosis de haloperidol"], "a": 1, "e": "Las distonías agudas son síntomas extrapiramidales de los antipsicóticos típicos y se tratan con anticolinérgicos, siendo el biperideno IM el de elección en urgencias."}, {"q": "Un paciente con antipsicóticos presenta fiebre alta, rigidez muscular «en tubo de plomo», sudoración, tensión inestable y alteración de la conciencia. Debe sospecharse:", "o": ["Discinesia tardía", "Acatisia", "Síndrome neuroléptico maligno", "Intoxicación por litio"], "a": 2, "e": "El síndrome neuroléptico maligno, potencialmente mortal, cursa con hipertermia, rigidez, inestabilidad autonómica y alteración del nivel de conciencia. Es una urgencia que obliga a suspender el antipsicótico."}, {"q": "El predictor clínico más potente de suicidio consumado es:", "o": ["Un intento de suicidio previo", "Ser mujer", "Estar casado", "Tener una edad entre 25 y 35 años"], "a": 0, "e": "El intento previo es el factor predictor más potente. La depresión es el trastorno más asociado, y también aumentan el riesgo el sexo masculino, el alcohol, la falta de apoyo social, las pérdidas y las enfermedades crónicas."}, {"q": "Según la escala SAD PERSONS, una puntuación de 5-6 indica:", "o": ["Riesgo bajo: alta sin seguimiento", "Riesgo moderado: solo seguimiento por su médico de familia", "Ausencia de riesgo", "Que se recomienda el ingreso hospitalario, sobre todo si no tiene apoyo social"], "a": 3, "e": "SAD PERSONS: 0-2 alta con seguimiento; 3-4 seguimiento estrecho y derivación preferente; 5-6 ingreso recomendado; 7-10 ingreso obligado e inmediato."}, {"q": "En la escala SAD PERSONS, la letra «O» corresponde a:", "o": ["Obesidad", "Plan organizado (método definido y acceso a él)", "Ocupación laboral", "Orientación temporoespacial"], "a": 1, "e": "Las letras son: Sexo masculino, Age (edad), Depresión, Previo intento, Etanol, Racionalidad perdida, Soporte social escaso, Organized plan (plan organizado), No spouse (sin pareja) y Sickness (enfermedad). Cada ítem presente suma 1 punto."}, {"q": "En el Código Riesgo Suicida del Servicio Murciano de Salud, cuando un paciente atendido por un intento de suicidio no precisa ingreso:", "o": ["Se le da el alta sin seguimiento específico", "Se le cita en su centro de salud dentro de seis meses", "Se activa el código al alta para garantizar una cita preferente y seguimiento proactivo en su centro de salud mental", "Se le deriva solo a urgencias si vuelve a intentarlo"], "a": 2, "e": "Tras la estabilización y la valoración por psiquiatría, si no hay criterio de ingreso se activa el Código Riesgo Suicida, que asegura una cita preferente y un seguimiento proactivo en el centro de salud mental, para reducir la repetición y garantizar la continuidad asistencial."}, {"q": "El cuestionario Apgar familiar de Smilkstein:", "o": ["Valora mediante 5 preguntas la satisfacción del paciente con el funcionamiento de su familia", "Es una escala de vitalidad del recién nacido", "Mide la sobrecarga del cuidador", "Valora el riesgo social de los mayores de 65 años"], "a": 0, "e": "El Apgar familiar explora Adaptación, Participación, Grado de crecimiento, Afecto y Resolución. Se puntúa de 0 a 10: 7-10 familia normofuncional, 4-6 disfunción leve y 0-3 disfunción grave."}, {"q": "La escala de valoración sociofamiliar de Gijón valora en las personas mayores:", "o": ["La capacidad para las actividades básicas de la vida diaria", "El deterioro cognitivo", "El riesgo de úlceras por presión", "La situación familiar, económica, la vivienda, las relaciones sociales y los apoyos"], "a": 3, "e": "La escala de Gijón es heteroadministrada y valora cinco áreas (situación familiar, económica, vivienda, relaciones sociales y apoyos), cada una de 1 a 5, con un total de 5 a 25 puntos: a mayor puntuación, mayor riesgo social."}, {"q": "En la escala de recursos sociales OARS (Duke), se consideran recursos sociales buenos cuando:", "o": ["El paciente vive solo y no recibe visitas", "Existe al menos una persona dispuesta a cuidarle de forma indefinida", "Solo cuenta con ayuda ocasional", "Tiene ingresos superiores al salario mínimo"], "a": 1, "e": "Recursos buenos o excelentes: hay alguien dispuesto a cuidarle indefinidamente; medianamente deteriorados: alguien puede cuidarle unas 6 semanas; muy deteriorados: solo ayuda ocasional; y sin recursos."}, {"q": "La hija de una paciente con demencia manifiesta agotamiento físico y emocional por los cuidados. El diagnóstico NANDA adecuado es:", "o": ["Riesgo de cansancio del rol de cuidador", "Afrontamiento familiar comprometido sin más", "Cansancio del rol de cuidador", "Deterioro parental"], "a": 2, "e": "Si el agotamiento ya está presente, el diagnóstico es Cansancio del rol de cuidador (00061). Riesgo de cansancio del rol de cuidador (00062) se usa cuando hay factores de vulnerabilidad pero aún no hay agotamiento."}, {"q": "En la escala de sobrecarga de Zarit original de 22 ítems, el rango de puntuación es:", "o": ["De 0 a 88 puntos", "De 22 a 110 puntos", "De 0 a 22 puntos", "De 0 a 100 puntos"], "a": 0, "e": "Cada ítem se puntúa de 0 (nunca) a 4 (casi siempre): 22 × 4 = 88. Interpretación: ≤ 46 sin sobrecarga, 47-55 leve y ≥ 56 intensa."}, {"q": "Según su efecto sobre el sistema nervioso central, la cocaína se clasifica como:", "o": ["Depresora", "Perturbadora o alucinógena", "Hipnosedante", "Estimulante"], "a": 3, "e": "Depresoras: alcohol, opiáceos, hipnosedantes. Estimulantes: cocaína, anfetaminas, nicotina, cafeína. Perturbadoras: LSD, cannabis, psilocibina."}, {"q": "Respecto a la escala CIWA-Ar para la valoración de la abstinencia alcohólica, es correcto:", "o": ["Incluye la frecuencia cardíaca, la tensión arterial y la temperatura", "No incluye constantes vitales: valora 10 síntomas y signos como temblor, sudoración, ansiedad o alucinaciones", "Tiene una puntuación máxima de 10", "Solo puede aplicarse a pacientes plenamente colaboradores"], "a": 1, "e": "La CIWA-Ar valora 10 ítems (nueve de 0 a 7 y la orientación de 0 a 4; máximo 67) y no incluye constantes vitales. Requiere poca colaboración del paciente. Con puntuaciones moderadas o graves se tratan con benzodiacepinas y se reevalúa con frecuencia."}, {"q": "El tratamiento del síndrome de abstinencia alcohólica moderado-grave se basa en:", "o": ["Antipsicóticos en monoterapia", "Naloxona intravenosa", "Benzodiacepinas (diazepam, lorazepam) y aporte de tiamina", "Disulfiram"], "a": 2, "e": "Las benzodiacepinas tienen tolerancia cruzada con el alcohol y previenen las convulsiones y el delirium tremens; se asocia tiamina (B1). El disulfiram se usa en la deshabituación, no en la abstinencia aguda."}, {"q": "La tríada clásica de la intoxicación por opiáceos es:", "o": ["Depresión respiratoria, disminución del nivel de conciencia y miosis puntiforme", "Taquicardia, hipertensión y midriasis", "Hipertermia, rigidez y sudoración", "Temblor, alucinaciones visuales y convulsiones"], "a": 0, "e": "Los opiáceos producen bradipnea o apnea, estupor o coma y miosis puntiforme. Se trata con soporte ventilatorio y naloxona. La midriasis con taquicardia e hipertensión orienta a estimulantes como la cocaína."}, {"q": "Un paciente con sobredosis de heroína recupera la conciencia tras recibir naloxona. La actuación correcta es:", "o": ["Darle el alta inmediata, ya que ha revertido", "Administrar flumazenilo de forma preventiva", "Retirar la monitorización", "Mantenerlo en observación porque la naloxona tiene una vida media corta y puede reaparecer la depresión respiratoria"], "a": 3, "e": "La naloxona dura 30-60 minutos, menos que el opiáceo. Al desaparecer su efecto puede producirse una resedación con apnea, por lo que el paciente debe seguir vigilado."}, {"q": "En los programas de mantenimiento con agonistas opioides, el fármaco más utilizado es:", "o": ["La naloxona", "La metadona, administrada por vía oral con dispensación supervisada", "La naltrexona intravenosa", "El fentanilo transdérmico"], "a": 1, "e": "La metadona es un agonista opioide de larga duración que, administrada por vía oral bajo supervisión, controla el craving y la abstinencia sin producir la euforia de la heroína."}, {"q": "La encuesta EDADES del Observatorio Español de las Drogas y las Adicciones se dirige a:", "o": ["Estudiantes de 14 a 18 años", "Mayores de 65 años", "Población general de 15 a 64 años residente en hogares", "Únicamente a personas en tratamiento"], "a": 2, "e": "EDADES es una encuesta bienal a la población general de 15 a 64 años. ESTUDES, también bienal, se dirige a estudiantes de enseñanzas secundarias de 14 a 18 años."}, {"q": "Una intervención educativa dirigida a un grupo de adolescentes que ya consumen cannabis los fines de semana, sin criterios de dependencia, es prevención:", "o": ["Universal", "Selectiva", "Primordial", "Indicada"], "a": 3, "e": "La prevención universal se dirige a toda la población; la selectiva, a grupos vulnerables que aún no consumen (por ejemplo, hijos de padres alcohólicos); la indicada, a personas que ya consumen o tienen problemas iniciales, para frenar la progresión."}, {"q": "Según las encuestas del Plan Nacional sobre Drogas, la droga ilegal más consumida en España es:", "o": ["El cannabis", "La cocaína", "El éxtasis", "La heroína"], "a": 0, "e": "Las sustancias más consumidas son el alcohol, el tabaco y los hipnosedantes (con predominio femenino); el cannabis es la droga ilegal más consumida. El PNSD se creó en 1985 y su Delegación depende del Ministerio de Sanidad."}]},
39: {"tema": 39, "titulo": "Cuidados de enfermería a personas con problemas neurológicos. Accidente cerebrovascular, epilepsia. Alzheimer y demencias. Otros problemas del sistema nervioso. Procedimientos y técnicas", "programa": "Valoración y cuidados de enfermería a personas con problemas neurológicos: accidente cerebrovascular, epilepsia. Alzheimer y demencias. Otros problemas del sistema nervioso (Parkinson, esclerosis múltiple, ELA, miastenia, Guillain-Barré). Procedimientos y técnicas de enfermería (hipertensión intracraneal).", "preguntas": [{"q": "Un paciente tras un ictus habla con fluidez pero emplea palabras sin sentido y no comprende lo que se le dice. Presenta una afasia:", "o": ["Motora o de Broca, por lesión frontal", "Global por lesión occipital", "Sensitiva o de Wernicke, por lesión temporal", "Disartria por lesión cerebelosa"], "a": 2, "e": "La afasia de Wernicke (lóbulo temporal) es sensitiva: el habla es fluida pero sin sentido y no hay comprensión. La de Broca (lóbulo frontal) es motora: comprende pero no puede expresarse."}, {"q": "En la escala de Glasgow, la respuesta motora en extensión anormal ante el dolor (descerebración) puntúa:", "o": ["2", "3", "4", "5"], "a": 0, "e": "Respuesta motora: 6 obedece, 5 localiza, 4 retirada, 3 flexión anormal (decorticación), 2 extensión (descerebración), 1 ninguna."}, {"q": "En un traumatismo craneoencefálico, se considera grave una puntuación en la escala de Glasgow de:", "o": ["14-15", "12-13", "9-13", "8 o menos"], "a": 3, "e": "Leve: 14-15; moderado: 9-13; grave: ≤ 8, indicación de asegurar la vía aérea mediante intubación."}, {"q": "En un paciente neurocrítico, la aparición brusca de una diferencia de tamaño pupilar mayor de 1 mm sugiere:", "o": ["Una intoxicación por opiáceos", "Compresión del III par por posible herniación cerebral", "Un efecto normal de la sedación", "Una lesión del VII par craneal"], "a": 1, "e": "La anisocoria aguda > 1 mm puede indicar compresión del III par (motor ocular común) por herniación. Los opiáceos producen miosis puntiforme bilateral."}, {"q": "Al explorar el XII par craneal (hipogloso) en un paciente con una lesión de ese nervio, al sacar la lengua esta se desvía:", "o": ["Hacia el lado afectado", "Hacia el lado sano", "Hacia arriba", "No se desvía"], "a": 0, "e": "Por la debilidad del lado afectado, la lengua protruida se desvía hacia el lado de la lesión. El IX y X pares se valoran con la elevación del velo y el reflejo nauseoso."}, {"q": "En la escala de Daniels, un músculo que realiza el movimiento venciendo la gravedad pero no una resistencia añadida puntúa:", "o": ["1", "2", "3", "5"], "a": 2, "e": "Daniels: 0 sin contracción; 1 contracción sin movimiento; 2 movimiento sin vencer la gravedad; 3 vence la gravedad; 4 vence una resistencia moderada; 5 fuerza normal."}, {"q": "En la escala de Cincinnati para la detección prehospitalaria del ictus, la activación del Código Ictus está indicada cuando:", "o": ["Están presentes los tres signos", "Hay al menos un signo positivo (asimetría facial, caída del brazo o alteración del habla)", "La NIHSS es superior a 20", "El TC confirma la lesión"], "a": 1, "e": "La presencia de un solo signo de Cincinnati da alta sospecha de ictus y basta para activar el Código Ictus. La NIHSS (0-42) se aplica en el hospital para graduar la gravedad y decidir la reperfusión."}, {"q": "La ventana terapéutica general para la fibrinólisis intravenosa en el ictus isquémico es de:", "o": ["Hasta 4,5 horas desde el inicio de los síntomas", "Hasta 1 hora", "Hasta 12 horas", "Hasta 72 horas"], "a": 0, "e": "La fibrinólisis IV se administra hasta 4,5 horas desde el inicio; la trombectomía mecánica, hasta 6 horas (ampliable a 24 h en pacientes seleccionados con neuroimagen avanzada)."}, {"q": "En el Código Ictus, el tiempo objetivo entre la llegada al hospital y el inicio de la fibrinólisis («puerta-aguja») es:", "o": ["Menos de 10 minutos", "Menos de 25 minutos", "Menos de 60 minutos", "Menos de 3 horas"], "a": 2, "e": "Tiempos de calidad: puerta-médico < 10 min, puerta-TC < 25 min y puerta-aguja < 60 min (idealmente < 45)."}, {"q": "Respecto a la tensión arterial en la fase aguda del ictus isquémico, es correcto:", "o": ["Debe reducirse rápidamente a cifras normales en todos los casos", "Debe mantenerse por debajo de 120/80 mmHg", "Hay que inducir hipotensión para proteger el cerebro", "No debe reducirse bruscamente, salvo que supere los umbrales de seguridad (por ejemplo, > 185/110 mmHg para la fibrinólisis)"], "a": 3, "e": "La hipertensión reactiva ayuda a perfundir la penumbra isquémica: no se baja bruscamente. Para administrar fibrinólisis la TA debe ser < 185/110 mmHg."}, {"q": "Antes de iniciar la tolerancia oral en un paciente con ictus, la enfermera debe:", "o": ["Administrar un vaso de agua para comprobar que traga", "Realizar un cribado de disfagia validado, como el método de exploración clínica volumen-viscosidad (MECV-V)", "Colocar siempre una sonda nasogástrica", "Ofrecer una dieta con dobles texturas"], "a": 1, "e": "La disfagia es frecuente y causa neumonía aspirativa. Antes de dar nada por boca se realiza un cribado validado (MECV-V o test del agua); si aparece tos, voz húmeda o desaturación > 3%, se suspende la vía oral."}, {"q": "En un paciente con disfagia tras un ictus que puede comer por boca, es una medida correcta:", "o": ["Comer sentado a 90° y mantener esa postura 30-45 minutos tras la ingesta, masticando por el lado sano", "Comer en decúbito supino", "Tomar líquidos sin espesar para facilitar la deglución", "Ofrecer sopas con fideos (dobles texturas)"], "a": 0, "e": "Se usan espesantes y purés homogéneos (sin dobles texturas), bocados pequeños, masticación por el lado sano, flexión cervical al tragar y sedestación a 90° durante y 30-45 minutos después de comer. Se revisa la boca por si quedan restos en el lado parético."}, {"q": "Para movilizar en la cama a un paciente con hemiplejia tras un ictus, debe evitarse:", "o": ["Los cambios posturales cada 2-3 horas", "El uso de cojines para evitar la rotación externa de la cadera", "Traccionar del brazo hemipléjico, por el riesgo de subluxación del hombro", "La sedestación precoz si está estable"], "a": 2, "e": "El hombro hemipléjico es vulnerable a la subluxación: nunca se tira del brazo afectado. Se mantiene la alineación (cojín trocantéreo, férula antiequino), cambios posturales y movilización precoz."}, {"q": "Según la ILAE, se establece el diagnóstico de epilepsia cuando hay:", "o": ["Una única crisis provocada por fiebre alta", "Una crisis por hipoglucemia", "Una crisis por abstinencia alcohólica", "Al menos dos crisis no provocadas separadas más de 24 horas"], "a": 3, "e": "Se diagnostica epilepsia con al menos dos crisis no provocadas separadas más de 24 h, o una crisis no provocada con alta probabilidad de recurrencia (≥ 60%) por hallazgos en el EEG o la neuroimagen. Las crisis provocadas por una causa reversible no son epilepsia."}, {"q": "En una crisis tónico-clónica generalizada, se considera que se ha iniciado un estatus epiléptico y debe administrarse tratamiento de rescate a partir de:", "o": ["1 minuto", "5 minutos", "30 minutos", "60 minutos"], "a": 1, "e": "El tiempo t1 es de 5 minutos para las crisis tónico-clónicas y de 10 minutos para las focales con alteración de la conciencia. A partir de t2 (30 minutos en las generalizadas) aumenta el riesgo de daño neuronal irreversible."}, {"q": "Ante un paciente que presenta una crisis tónico-clónica, la actuación correcta de enfermería es:", "o": ["Proteger al paciente del entorno, colocar algo blando bajo la cabeza, cronometrar la crisis y, al ceder, colocarlo en posición lateral de seguridad", "Introducir un depresor lingual para evitar que se trague la lengua", "Sujetar con fuerza las extremidades", "Darle agua para que se recupere"], "a": 0, "e": "Se protege de golpes, se afloja la ropa y se cronometra. No se sujeta (riesgo de fracturas y luxaciones) ni se introduce nada en la boca (lesiones y fracturas dentales). Al ceder la fase tónica, se coloca en lateral de seguridad."}, {"q": "El tratamiento de primera línea del estatus epiléptico son:", "o": ["La fenitoína intravenosa", "El propofol en perfusión", "Las benzodiacepinas (midazolam, diazepam o lorazepam)", "El sulfato de magnesio"], "a": 2, "e": "Primero benzodiacepinas (midazolam IM, bucal o intranasal; diazepam IV o rectal; lorazepam IV). Si no ceden, antiepilépticos IV (valproico, levetiracetam, lacosamida, fenitoína) y, si es refractario, coma anestésico en UCI. El magnesio es para la eclampsia."}, {"q": "En una gestante con eclampsia tratada con sulfato de magnesio, el primer signo clínico de toxicidad es:", "o": ["La taquicardia", "La hipertensión", "La fiebre", "La desaparición del reflejo rotuliano"], "a": 3, "e": "La abolición del reflejo rotuliano es el primer signo de hipermagnesemia; después aparecen depresión respiratoria (< 12 rpm) y oliguria. Se suspende la perfusión y se administra gluconato cálcico al 10% IV lento."}, {"q": "En las mujeres epilépticas en edad fértil debe evitarse, por ser el antiepiléptico más teratógeno:", "o": ["La lamotrigina", "El ácido valproico", "El levetiracetam", "El ácido fólico"], "a": 1, "e": "El valproato se asocia a defectos del tubo neural y alteraciones del neurodesarrollo. Se prefieren lamotrigina o levetiracetam y se suplementa con ácido fólico (5 mg/día) desde 1-3 meses antes de la concepción."}, {"q": "Un paciente con deterioro cognitivo presenta fluctuaciones marcadas de la atención, alucinaciones visuales muy vívidas desde el inicio y signos parkinsonianos. Lo más probable es:", "o": ["Enfermedad de Alzheimer", "Demencia vascular", "Demencia con cuerpos de Lewy", "Demencia frontotemporal"], "a": 2, "e": "La demencia con cuerpos de Lewy se caracteriza por fluctuaciones, alucinaciones visuales precoces, parkinsonismo y una gran sensibilidad a los neurolépticos, que pueden empeorarla gravemente."}, {"q": "En la enfermedad de Alzheimer, es característico:", "o": ["El inicio brusco con empeoramiento en escalones", "Los cambios de personalidad antes que la memoria, en menores de 50 años", "La alteración de la conciencia desde el inicio", "El inicio insidioso con fallo de la memoria reciente y déficit de acetilcolina"], "a": 3, "e": "El Alzheimer (60-70% de las demencias) tiene placas de beta-amiloide y ovillos de tau, déficit de acetilcolina e inicio insidioso con amnesia reciente. La evolución en escalones es propia de la vascular y los cambios de conducta precoces, de la frontotemporal."}, {"q": "Un paciente con Alzheimer presenta un episodio de agitación nocturna de aparición reciente. Lo primero que debe hacer la enfermera es:", "o": ["Descartar causas orgánicas como infección urinaria, dolor, fecaloma o retención de orina", "Aplicar una contención mecánica", "Administrar un neuroléptico a dosis altas", "Discutir con el paciente sus ideas delirantes"], "a": 0, "e": "Ante síntomas conductuales nuevos se descartan primero causas orgánicas (delirium añadido). Después se aplican medidas no farmacológicas: entorno seguro y bien iluminado, rutinas, validación emocional y no confrontar los delirios."}, {"q": "Respecto a la administración de levodopa en la enfermedad de Parkinson, es correcto:", "o": ["Tomarla junto con comidas ricas en proteínas para mejorar su absorción", "El horario puede variar sin consecuencias", "Administrarla con horario exacto y alejada de las comidas proteicas", "Tomarla siempre con leche"], "a": 2, "e": "Los aminoácidos de la dieta compiten con la levodopa en su absorción: se toma 30-45 minutos antes o 2 horas después de las comidas, con horario estricto para evitar las fluctuaciones on-off."}, {"q": "En la esclerosis múltiple, el fenómeno de Uhthoff consiste en:", "o": ["La mejoría de los síntomas con el calor", "La aparición de temblor de reposo", "La pérdida de memoria reciente", "El empeoramiento de los síntomas neurológicos con el aumento de la temperatura corporal"], "a": 3, "e": "El calor (baños calientes, sol, fiebre) empeora la conducción en los axones desmielinizados. Se aconseja evitar los baños calientes y tratar la fiebre. La esclerosis múltiple afecta sobre todo a mujeres jóvenes y cursa en brotes."}, {"q": "En la esclerosis lateral amiotrófica (ELA), suelen conservarse:", "o": ["La sensibilidad y los movimientos oculares", "La fuerza de las extremidades", "La deglución en fases avanzadas", "La función respiratoria hasta el final"], "a": 0, "e": "La ELA destruye las motoneuronas superiores e inferiores (atrofia, fasciculaciones, disfagia, fallo respiratorio), pero conserva la sensibilidad y los movimientos oculares, que permiten la comunicación con sistemas de seguimiento ocular."}, {"q": "En un paciente con miastenia gravis, es correcto:", "o": ["La debilidad mejora con el ejercicio y empeora con el reposo", "Administrar la piridostigmina con horario exacto unos 30-45 minutos antes de las comidas y evitar aminoglucósidos y magnesio IV", "Los aminoglucósidos son los antibióticos de elección", "La piridostigmina se administra después de comer para evitar náuseas"], "a": 1, "e": "La miastenia produce debilidad fluctuante que empeora con el esfuerzo y por la tarde. La piridostigmina antes de comer permite masticar y tragar con menos riesgo de aspiración. Los aminoglucósidos, el magnesio IV y los betabloqueantes empeoran la transmisión neuromuscular."}, {"q": "En el síndrome de Guillain-Barré, el hallazgo característico del líquido cefalorraquídeo es:", "o": ["Pleocitosis con predominio de neutrófilos", "Disociación albúmino-citológica: proteínas elevadas con recuento celular normal", "Glucosa muy disminuida", "LCR hemático"], "a": 1, "e": "El Guillain-Barré es una polineuropatía aguda autoinmune (a menudo tras Campylobacter jejuni) con parálisis ascendente y arreflexia. La prioridad de enfermería es vigilar la capacidad vital para intubar a tiempo."}, {"q": "La tríada de Cushing, signo de hipertensión intracraneal grave, consiste en:", "o": ["Hipotensión, taquicardia y taquipnea", "Fiebre, rigidez de nuca y fotofobia", "Midriasis bilateral, hipotermia y bradipnea", "Hipertensión arterial, bradicardia y alteraciones del patrón respiratorio"], "a": 3, "e": "La tríada de Cushing (HTA con presión diferencial amplia, bradicardia y respiración irregular) indica riesgo de herniación. La hipotensión con taquicardia orienta a shock hipovolémico."}, {"q": "La presión de perfusión cerebral se calcula como:", "o": ["Presión arterial media menos presión intracraneal (PAM − PIC)", "Presión intracraneal menos presión arterial media", "Presión sistólica más presión intracraneal", "Presión venosa central menos PIC"], "a": 0, "e": "PPC = PAM − PIC; el objetivo es mantenerla por encima de 60 mmHg. Para controlar la PIC: cabecera a 30°, cabeza neutra, sedoanalgesia, terapia hiperosmolar y aspiraciones breves con preoxigenación."}, {"q": "En un paciente portador de un drenaje ventricular externo, antes de movilizarlo para el aseo la enfermera debe:", "o": ["Bajar la cámara al suelo", "Elevar la cámara por encima de la cabeza", "Retirar el drenaje", "Pinzar temporalmente el sistema para evitar un vaciado brusco de LCR"], "a": 3, "e": "Antes de cualquier movilización se cierra el drenaje para evitar un vaciado descontrolado de LCR (colapso ventricular, sangrado). El cero se calibra a la altura del trago (agujero de Monro) y se mantiene la asepsia."}, {"q": "Paciente con TCE: la pupila derecha está dilatada y no reacciona a la luz, como en la imagen. Este hallazgo sugiere compresión del par craneal:", "o": ["II (óptico)", "III (motor ocular común)", "IV (troclear)", "VI (motor ocular externo)"], "a": 1, "e": "El III par lleva las fibras parasimpáticas que contraen la pupila; su compresión por herniación uncal da midriasis arreactiva del mismo lado. Es un signo de alarma neuroquirúrgica.", "img": "img/preguntas/pupilas-anisocoria.svg"}]},
40: {"tema": 40, "titulo": "Cuidados de enfermería a personas con problemas respiratorios. Insuficiencia respiratoria aguda, EPOC. Otros problemas broncopulmonares. Oxigenoterapia y otras técnicas. Ventilación mecánica invasiva y no invasiva. Oxigenación extracorpórea", "programa": "Valoración y cuidados de enfermería a personas con problemas respiratorios: insuficiencia respiratoria aguda, EPOC. Otros problemas broncopulmonares. Procedimientos de enfermería: oxigenoterapia y otras técnicas. Ventilación mecánica invasiva y no invasiva. Sistemas de oxigenación extracorpórea.", "preguntas": [{"q": "Un paciente con cetoacidosis diabética presenta una respiración profunda, rápida y ruidosa, sin pausas. Se trata de una respiración de:", "o": ["Cheyne-Stokes", "Biot", "Kussmaul", "Paradójica"], "a": 2, "e": "La respiración de Kussmaul es la compensación respiratoria de la acidosis metabólica (elimina CO₂). Cheyne-Stokes se asocia a insuficiencia cardíaca y Biot a lesión bulbar."}, {"q": "La respiración en la que el abdomen se hunde durante la inspiración indica:", "o": ["Una respiración normal en el adulto", "Una acidosis metabólica", "Una lesión del cerebelo", "Fatiga diafragmática con necesidad de soporte ventilatorio inmediato"], "a": 3, "e": "La respiración paradójica es un signo de agotamiento del diafragma y de parada respiratoria inminente."}, {"q": "El índice paquetes-año de un paciente que fuma 20 cigarrillos al día desde hace 30 años es:", "o": ["600", "30", "20", "1,5"], "a": 1, "e": "Paquetes-año = (cigarrillos al día × años fumando) / 20 = (20 × 30) / 20 = 30."}, {"q": "En la palpación torácica, las vibraciones vocales están aumentadas en:", "o": ["La condensación pulmonar (neumonía)", "El derrame pleural", "El neumotórax", "El enfisema"], "a": 0, "e": "El tejido consolidado transmite mejor el sonido. El líquido (derrame) y el aire (neumotórax) actúan de barrera y las disminuyen."}, {"q": "El ruido respiratorio adventicio de tono grave, producido por secreciones en los bronquios grandes, que se modifica con la tos, es:", "o": ["El crepitante", "El estridor", "El roce pleural", "El roncus"], "a": 3, "e": "Los roncus se deben a secreciones en bronquios de gran calibre y se modifican con la tos. Los crepitantes aparecen al final de la inspiración (neumonía, edema), y el roce pleural no cambia con la tos."}, {"q": "Un ruido inspiratorio agudo, intenso y audible sin fonendoscopio indica:", "o": ["Broncoespasmo de pequeñas vías", "Obstrucción de la vía aérea superior, que es una urgencia vital", "Secreciones en bronquios grandes", "Inflamación pleural"], "a": 1, "e": "El estridor es un ruido inspiratorio por obstrucción de la vía aérea superior (cuerpo extraño, edema laríngeo, epiglotitis, crup) y constituye una urgencia. Las sibilancias, espiratorias, indican broncoespasmo."}, {"q": "La insuficiencia respiratoria se define gasométricamente, a nivel del mar y respirando aire ambiente, por una PaO₂ inferior a:", "o": ["60 mmHg", "80 mmHg", "90 mmHg", "40 mmHg"], "a": 0, "e": "PaO₂ < 60 mmHg (que corresponde a una SatO₂ de alrededor del 90%). Si además la PaCO₂ supera 45-50 mmHg, la insuficiencia es hipercápnica (tipo II)."}, {"q": "El mecanismo de hipoxemia que no mejora significativamente al aumentar la FiO₂ y requiere presión positiva para abrir los alvéolos es:", "o": ["El desequilibrio ventilación/perfusión", "La hipoventilación alveolar", "La altitud", "El efecto shunt (cortocircuito)"], "a": 3, "e": "En el shunt la sangre atraviesa alvéolos colapsados o llenos de líquido: el oxígeno no llega a ellos. Necesita CPAP/PEEP para reclutar alvéolos. El desequilibrio V/Q, el mecanismo más frecuente, responde bien al oxígeno."}, {"q": "La insuficiencia respiratoria tipo II (hipercápnica) se caracteriza por:", "o": ["PaO₂ baja con PaCO₂ normal o baja", "PaO₂ < 60 mmHg con PaCO₂ elevada (> 45-50 mmHg)", "PaO₂ normal con PaCO₂ baja", "Solo alteración del pH"], "a": 1, "e": "La tipo II es un fallo de la «bomba» ventilatoria (EPOC, sobredosis, enfermedades neuromusculares). La tipo I (hipoxémica) se debe a problemas del parénquima, como la neumonía o el edema."}, {"q": "El diagnóstico NANDA que se centra en la alteración de la oxigenación o de la eliminación de CO₂ en la membrana alveolocapilar, objetivable mediante gasometría, es:", "o": ["Patrón respiratorio ineficaz", "Limpieza ineficaz de las vías aéreas", "Deterioro del intercambio de gases", "Intolerancia a la actividad"], "a": 2, "e": "El deterioro del intercambio de gases (00030) se refiere a la sangre arterial (hipoxemia, hipercapnia). El patrón respiratorio ineficaz (00032) describe cómo mueve el aire el paciente (taquipnea, musculatura accesoria)."}, {"q": "En un paciente con EPOC retenedor de CO₂, el objetivo de saturación de oxígeno es:", "o": ["88-92%", "95-100%", "100%", "Por debajo del 85%"], "a": 0, "e": "En los retenedores crónicos de CO₂ se busca una SatO₂ del 88-92% para no suprimir el estímulo respiratorio y evitar la hipercapnia. El sistema de elección es la mascarilla Venturi."}, {"q": "Un paciente con neumonía del pulmón derecho presenta hipoxemia. Para mejorar la oxigenación, se le debe colocar:", "o": ["En decúbito lateral derecho", "En decúbito prono", "En Trendelenburg", "En decúbito lateral izquierdo, con el pulmón sano abajo"], "a": 3, "e": "En la afectación unilateral, el pulmón sano en posición declive recibe más perfusión por gravedad y mejora la relación ventilación/perfusión. En la afectación bilateral se prefiere Fowler alto."}, {"q": "El diagnóstico de EPOC se confirma mediante espirometría cuando el cociente FEV1/FVC posbroncodilatador es:", "o": ["Mayor de 0,80", "Menor de 0,70", "Igual a 1", "Mayor de 0,70 con FVC baja"], "a": 1, "e": "Un FEV1/FVC < 0,70 tras broncodilatador indica obstrucción persistente. Un cociente normal o alto con FVC baja sugiere un patrón restrictivo, como en la fibrosis pulmonar."}, {"q": "Para valorar el grado de control del asma en las últimas 4 semanas se utiliza el cuestionario ACT. Indica asma no controlada una puntuación:", "o": ["Superior a 10", "Igual a 25", "Inferior a 20", "Superior a 20"], "a": 2, "e": "En el ACT, una puntuación inferior a 20 indica asma no controlada y obliga a revisar la técnica inhalatoria y la adherencia. El CAT, en cambio, valora el impacto de la EPOC (≥ 10 = muy sintomático)."}, {"q": "En la EPOC, los corticoides inhalados se reservan para pacientes con fenotipo eosinofílico o asma asociada porque:", "o": ["Son el tratamiento de base de todos los pacientes con EPOC", "Producen taquicardia", "Curan la enfermedad", "Aumentan el riesgo de neumonía"], "a": 3, "e": "La base del tratamiento de mantenimiento son los broncodilatadores de larga duración (LAMA, LABA). Los corticoides inhalados se asocian a mayor riesgo de neumonía, por lo que se usan solo en agudizadores eosinofílicos (≥ 300/µl) o con asma."}, {"q": "Para valorar la dependencia física de la nicotina en un fumador se utiliza:", "o": ["El test de Richmond", "El test de Fagerström", "La escala mMRC", "El cuestionario CAT"], "a": 1, "e": "El test de Fagerström mide la dependencia (≥ 7 = alta) y el de Richmond, la motivación para dejar de fumar. Dejar de fumar es la intervención más eficaz para frenar la caída del FEV1 en la EPOC."}, {"q": "Según los criterios de Anthonisen, los síntomas de una exacerbación de la EPOC son:", "o": ["Aumento de la disnea, aumento del volumen del esputo y esputo purulento", "Fiebre, cefalea y mialgias", "Dolor torácico, hemoptisis y síncope", "Edemas, ortopnea y ascitis"], "a": 0, "e": "Los tres criterios de Anthonisen son más disnea, más volumen de esputo y purulencia; esta última orienta a la necesidad de antibiótico. Todo paciente debe tener un plan de acción escrito."}, {"q": "En la prueba broncodilatadora, el resultado se considera positivo (reversibilidad, propia del asma) cuando el FEV1 aumenta:", "o": ["Un 5% respecto al valor basal", "Un 12% sin importar el volumen", "100 ml sin importar el porcentaje", "Al menos un 12% y 200 ml respecto al valor basal"], "a": 3, "e": "Se administran 400 µg de salbutamol con cámara y se repite la espirometría a los 15-20 minutos; es positiva si el FEV1 mejora al menos un 12% y 200 ml."}, {"q": "Un paciente de 70 años con neumonía está orientado, con urea de 30 mg/dl, FR de 32 rpm y TA de 120/70 mmHg. Su puntuación CURB-65 y la actitud son:", "o": ["2 puntos: indicación de ingreso hospitalario", "1 punto: tratamiento domiciliario", "0 puntos: tratamiento domiciliario", "4 puntos: ingreso en UCI"], "a": 0, "e": "Suma 1 punto por FR ≥ 30 y 1 punto por edad ≥ 65 años = 2 puntos, que indica ingreso hospitalario. 0-1: domicilio; ≥ 3: valorar UCI."}, {"q": "La fibrosis pulmonar produce en la espirometría un patrón:", "o": ["Obstructivo con FEV1/FVC < 0,70", "Normal", "Restrictivo, con disminución de la FVC y cociente FEV1/FVC normal o elevado", "Mixto con predominio obstructivo"], "a": 2, "e": "La fibrosis hace el pulmón rígido: cae la capacidad vital forzada y el cociente FEV1/FVC se mantiene o aumenta. A la auscultación se oyen crepitantes secos en «velcro»."}, {"q": "Respecto a la técnica de la espirometría forzada, es correcto:", "o": ["Se realiza con el paciente tumbado y sin pinza nasal", "Se pide una espiración lenta y suave", "Con pinza nasal, tras una inspiración máxima se realiza una espiración explosiva mantenida al menos 6 segundos", "Basta con una sola maniobra"], "a": 2, "e": "El paciente, sentado y con pinza nasal, inspira al máximo y espira de forma explosiva y mantenida (≥ 6 s). Se necesitan al menos 3 maniobras aceptables con una diferencia < 150 ml entre las dos mejores, sin superar 8 intentos."}, {"q": "El sistema de oxigenoterapia que proporciona una FiO₂ fija y exacta, de elección en el paciente con EPOC retenedor de CO₂, es:", "o": ["La mascarilla Venturi", "Las gafas nasales a 6 l/min", "La mascarilla con reservorio", "La mascarilla simple"], "a": 0, "e": "La Venturi es un sistema de alto flujo con FiO₂ constante e independiente del patrón respiratorio. Las gafas y la mascarilla simple dan una FiO₂ variable; el reservorio (10-15 l/min) se reserva para emergencias."}, {"q": "Respecto a la cánula nasal de alto flujo, es correcto:", "o": ["Administra oxígeno frío y seco a 4 l/min", "Administra hasta 60 l/min de gas calentado y humidificado, con efecto PEEP y lavado del espacio muerto", "Solo puede utilizarse en pacientes intubados", "No requiere vigilar la condensación de las tubuladuras"], "a": 1, "e": "La cánula de alto flujo administra hasta 60 l/min a 34-37 °C con 100% de humedad, genera cierta PEEP y lava el espacio muerto. Su eficacia se valora con el índice ROX (SpO₂/FiO₂ y FR). Hay que vigilar la piel y la condensación."}, {"q": "Respecto a la técnica de los inhaladores, es correcto:", "o": ["Con el cartucho presurizado se inspira de forma rápida y enérgica", "Con el polvo seco se inspira lentamente", "Con el cartucho presurizado la inspiración debe ser lenta y profunda, seguida de una apnea de unos 10 segundos; con el polvo seco, rápida y enérgica", "Después de inhalar corticoides no es necesario enjuagarse la boca"], "a": 2, "e": "El MDI requiere inspiración lenta y apnea de 10 s (mejor con cámara); el DPI depende del flujo del paciente y exige una inspiración rápida y enérgica. Tras los corticoides inhalados hay que enjuagar la boca para prevenir candidiasis y disfonía."}, {"q": "La percusión torácica (clapping) está contraindicada en:", "o": ["Las bronquiectasias con abundantes secreciones", "La fibrosis quística", "La neumonía en resolución", "La hemoptisis activa, las fracturas costales y las coagulopatías"], "a": 3, "e": "El clapping (mano ahuecada) ayuda a despegar secreciones, pero está contraindicado en hemoptisis, fracturas costales y trastornos de la coagulación. Las vibraciones se aplican durante la espiración."}, {"q": "Respecto al cuidado de un drenaje pleural con sello de agua, es correcto:", "o": ["Pinzar el tubo durante todos los traslados", "Colocar el colector por encima del nivel del tórax", "Mantener el colector vertical y por debajo del tórax, sin pinzar el tubo en los traslados", "El burbujeo continuo en el sello de agua es normal y no requiere atención"], "a": 2, "e": "El colector debe estar siempre por debajo del tórax. Pinzar en los traslados puede provocar un neumotórax a tensión. La oscilación indica permeabilidad y el burbujeo, fuga aérea."}, {"q": "Respecto a la ventilación mecánica no invasiva, es correcto:", "o": ["Es de elección en el paciente en coma sin reflejo de deglución", "Requiere un paciente consciente y colaborador, y se debe proteger el puente nasal con un apósito hidrocoloide antes de colocar la mascarilla", "Debe apretarse el arnés al máximo para evitar cualquier fuga", "Aumenta el riesgo de neumonía respecto a la intubación"], "a": 1, "e": "La VMNI exige un paciente despierto, colaborador y con reflejos de protección; en coma está indicada la intubación. La complicación más frecuente son las lesiones por presión: se previenen con hidrocoloide antes de poner la mascarilla y sin apretar en exceso."}, {"q": "En la ventilación mecánica invasiva con estrategia protectora, el volumen corriente se programa a:", "o": ["6-8 ml/kg de peso corporal ideal", "10-12 ml/kg de peso real", "15 ml/kg de peso real", "2-3 ml/kg de peso ideal"], "a": 0, "e": "El volumen corriente se calcula sobre el peso ideal (no el real, sobre todo en obesos) para evitar el volutrauma."}, {"q": "Según el proyecto Neumonía Zero, la presión del neumotaponamiento del tubo endotraqueal debe mantenerse:", "o": ["Entre 20 y 30 cmH₂O", "Por debajo de 15 cmH₂O", "Por encima de 40 cmH₂O", "Entre 5 y 10 cmH₂O"], "a": 0, "e": "Por debajo de 20 cmH₂O se favorece la microaspiración y por encima de 30 cmH₂O, la isquemia de la mucosa traqueal. Otras medidas: cabecera a 30-45°, higiene bucal con clorhexidina, aspiración subglótica, no cambiar tubuladuras de rutina y aspirar a demanda."}, {"q": "Respecto a la oxigenación por membrana extracorpórea (ECMO), es correcto:", "o": ["La modalidad veno-venosa da soporte cardíaco y respiratorio", "La modalidad veno-arterial solo da soporte respiratorio", "Si sube el CO₂, se debe aumentar el volumen corriente del respirador", "La modalidad veno-venosa da soporte solo respiratorio, y la veno-arterial, respiratorio y circulatorio"], "a": 3, "e": "La ECMO VV requiere que el corazón funcione; la VA se usa en shock cardiogénico o parada refractaria y obliga a vigilar la isquemia de la pierna canulada. Si sube el CO₂ se aumenta el gas de barrido; el ventilador se mantiene en reposo pulmonar."}, {"q": "En el esquema, el ruido n.º 1, agudo, inspiratorio y originado en la vía aérea superior (laringe-tráquea), es:", "o": ["Sibilancias", "Estridor", "Roncus", "Crepitantes"], "a": 1, "e": "Estridor: obstrucción de la vía aérea alta (laringitis, epiglotitis, cuerpo extraño), se oye sin fonendo. Sibilancias: bronquios pequeños, sobre todo espiratorias (asma, EPOC).", "img": "img/preguntas/t40-ruidos.jpg"}, {"q": "El ruido n.º 4, discontinuo, que se produce en los alvéolos al reabrirse (como frotar un mechón de pelo junto al oído), típico de la insuficiencia cardiaca o la neumonía, es:", "o": ["Crepitantes", "Roce pleural", "Sibilancias", "Estridor"], "a": 0, "e": "Crepitantes (estertores finos): apertura de alvéolos con líquido o exudado, al final de la inspiración, en las bases (ICC, neumonía, fibrosis).", "img": "img/preguntas/t40-ruidos.jpg"}, {"q": "El ruido n.º 5, que se origina en las hojas pleurales inflamadas, suena como cuero que roza y no se modifica con la tos, es:", "o": ["Roncus", "Crepitantes", "Roce (frote) pleural", "Estridor"], "a": 2, "e": "Roce pleural: pleuritis; en ambas fases respiratorias y desaparece si se acumula derrame. Los roncus (secreciones en bronquios grandes) sí cambian con la tos.", "img": "img/preguntas/t40-ruidos.jpg"}, {"q": "Botella de gas medicinal con la ojiva completamente blanca. Contiene:", "o": ["Aire medicinal", "Oxígeno", "Óxido nitroso", "Dióxido de carbono"], "a": 1, "e": "Ojiva blanca = oxígeno (UNE-EN 1089-3). Aire medicinal: blanco y negro; N₂O: azul; CO₂: gris.", "img": "img/preguntas/botella-oxigeno.svg"}]},
41: {"tema": 41, "titulo": "Cuidados de enfermería a personas con problemas cardiovasculares. Insuficiencia cardiaca, infarto de miocardio, hipertensión arterial. Otros problemas cardiovasculares. Procedimientos y técnicas", "programa": "Valoración y cuidados de enfermería a personas con problemas cardiovasculares: insuficiencia cardiaca, infarto de miocardio, hipertensión arterial. Otros problemas cardiovasculares (valvulopatías, arteriopatía periférica, fibrilación auricular). Procedimientos y técnicas: ECG, presión arterial, monitorización hemodinámica y soporte vital avanzado.", "preguntas": [{"q": "La auscultación de un tercer ruido cardiaco (R3, ritmo de galope) en un adulto se asocia a:", "o": ["Un hallazgo normal", "Insuficiencia cardiaca con sobrecarga de volumen", "Estenosis pulmonar", "Cierre de las válvulas semilunares"], "a": 1, "e": "El R3 en el adulto es patológico y sugiere insuficiencia cardiaca. R1 corresponde al cierre de mitral y tricúspide, R2 al de aórtica y pulmonar, y R4 indica rigidez ventricular."}, {"q": "El latido apical (choque de la punta) se palpa normalmente en:", "o": ["El 2.º espacio intercostal derecho", "El 3.er espacio intercostal paraesternal izquierdo", "La línea axilar media en el 7.º espacio", "El 5.º espacio intercostal izquierdo, en la línea medioclavicular"], "a": 3, "e": "Su desplazamiento hacia la línea axilar anterior sugiere cardiomegalia o dilatación del ventrículo izquierdo."}, {"q": "Se considera insuficiencia cardiaca con fracción de eyección reducida cuando la FEVI es:", "o": ["≤ 40%", "Entre 41 y 49%", "≥ 50%", "≥ 70%"], "a": 0, "e": "FEVI ≤ 40%: IC con FE reducida (disfunción sistólica); 41-49%: ligeramente reducida; ≥ 50%: conservada (disfunción diastólica)."}, {"q": "En un paciente con insuficiencia cardiaca tratado con espironolactona, la enfermera debe vigilar especialmente:", "o": ["La hipopotasemia", "Las infecciones genitales", "La hiperpotasemia", "La hipoglucemia"], "a": 2, "e": "Los antagonistas de la aldosterona (espironolactona, eplerenona) retienen potasio. Los iSGLT2 se asocian a infecciones genitales y la furosemida, a hipopotasemia."}, {"q": "En el seguimiento de un paciente con insuficiencia cardiaca, es un signo de alarma que requiere valoración urgente:", "o": ["Una pérdida de peso de 1 kg en una semana", "Una tensión arterial de 120/70 mmHg", "Una frecuencia cardiaca de 70 lpm", "Un aumento de peso de más de 2 kg en 3 días"], "a": 3, "e": "El aumento rápido de peso indica retención de líquidos y descompensación. Se educa en el peso diario, la restricción de sal y la detección de disnea, ortopnea y edemas."}, {"q": "Ante un paciente con dolor torácico sugestivo de síndrome coronario agudo, el ECG de 12 derivaciones debe realizarse:", "o": ["En los primeros 10 minutos desde el primer contacto", "En la primera hora", "Tras obtener el resultado de la troponina", "Solo si el dolor persiste más de 30 minutos"], "a": 0, "e": "El ECG precoz (≤ 10 min) permite identificar la elevación del ST e iniciar la reperfusión urgente."}, {"q": "Para descartar o confirmar un infarto sin elevación del ST, la guía ESC 2023 recomienda:", "o": ["La CK-MB seriada cada 6 horas", "La mioglobina", "La troponina de alta sensibilidad con algoritmo 0 h/1 h", "Solo el ECG seriado"], "a": 2, "e": "El biomarcador de elección es la troponina de alta sensibilidad, con extracción a la llegada (hora 0) y exactamente a la hora (o algoritmo 0 h/2 h)."}, {"q": "Se diagnostica un infarto con elevación del ST cuando el ECG muestra:", "o": ["Descenso del ST en una sola derivación", "Elevación persistente del ST en al menos dos derivaciones contiguas", "Una onda T invertida aislada", "Un PR alargado"], "a": 1, "e": "La elevación del ST en ≥ 2 derivaciones contiguas indica oclusión coronaria completa y obliga a reperfusión urgente."}, {"q": "En el IAM con elevación del ST, la estrategia de reperfusión de elección es:", "o": ["La fibrinólisis en todos los casos", "El tratamiento conservador", "La cirugía de revascularización urgente", "La angioplastia primaria, si puede realizarse en menos de 120 minutos, preferentemente por vía radial"], "a": 3, "e": "La angioplastia primaria es de elección si se puede hacer en < 120 min; la vía radial reduce el sangrado. Si no es posible, se administra fibrinólisis y se traslada a un centro con hemodinámica."}, {"q": "En un paciente con síndrome coronario agudo y saturación de oxígeno del 96%, respecto a la oxigenoterapia:", "o": ["No está indicada; solo se administra si la SatO₂ es inferior al 90%", "Debe administrarse siempre a alto flujo", "Debe administrarse con mascarilla de reservorio", "Debe administrarse a 2 l/min de forma sistemática"], "a": 0, "e": "El oxígeno de rutina ya no se recomienda: solo si hay hipoxemia (SatO₂ < 90%), porque puede producir vasoconstricción coronaria y más daño."}, {"q": "Los nitratos están contraindicados en un paciente con síndrome coronario agudo que presenta:", "o": ["Dolor torácico persistente", "Hipertensión arterial", "Sospecha de infarto de ventrículo derecho con hipotensión", "Frecuencia cardiaca de 80 lpm"], "a": 2, "e": "Los nitratos se suspenden si hay hipotensión, bradicardia significativa o infarto de ventrículo derecho, que depende de la precarga."}, {"q": "La complicación arrítmica más frecuente y letal en las primeras horas del infarto agudo de miocardio es:", "o": ["La fibrilación auricular", "La fibrilación ventricular", "El bloqueo de rama derecha", "La bradicardia sinusal"], "a": 1, "e": "La fibrilación ventricular primaria es la principal causa de muerte súbita precoz: obliga a monitorización continua del ritmo."}, {"q": "Según la guía ESC 2024, unas cifras de presión arterial de 132/84 mmHg se clasifican como:", "o": ["Presión arterial no elevada", "Hipertensión de grado 1", "Hipertensión de grado 2", "Presión arterial elevada"], "a": 3, "e": "La ESC 2024 distingue PA no elevada (< 120/70), PA elevada (120-139/70-89) e hipertensión (≥ 140/90). En la PA elevada se empieza con cambios de estilo de vida durante unos 3 meses."}, {"q": "Para confirmar el diagnóstico de hipertensión arterial, la guía ESC 2024 recomienda:", "o": ["Mediciones fuera de la consulta mediante MAPA de 24 horas o AMPA domiciliaria", "Una única medición en consulta", "La medición en el brazo izquierdo exclusivamente", "Una analítica con perfil lipídico"], "a": 0, "e": "Las mediciones fuera de la consulta evitan errores por hipertensión de bata blanca o enmascarada. Enfermería instruye en el uso correcto de los dispositivos."}, {"q": "La recomendación de ingesta de sal para un paciente hipertenso es:", "o": ["Menos de 10 g/día", "Eliminar totalmente la sal", "Menos de 5 g/día (unos 2 g de sodio)", "Menos de 15 g/día"], "a": 2, "e": "Además de limitar la sal, se recomienda dieta DASH rica en potasio, 150 minutos semanales de ejercicio aeróbico, mantener el IMC entre 20 y 25, limitar el alcohol (< 100 g/semana) y no fumar."}, {"q": "La causa más frecuente de falsa resistencia (seudorresistencia) en la hipertensión arterial es:", "o": ["El hiperaldosteronismo", "La falta de adherencia al tratamiento", "La estenosis de la arteria renal", "El feocromocitoma"], "a": 1, "e": "Antes de diagnosticar una HTA resistente hay que descartar la falta de adherencia, la mala técnica de medida, el manguito inadecuado o la falta de reposo. La entrevista motivacional ayuda a mejorar la adherencia."}, {"q": "En una estenosis valvular aórtica, el ventrículo izquierdo se adapta inicialmente mediante:", "o": ["Hipertrofia concéntrica por aumento de la poscarga", "Dilatación por aumento de la precarga", "Disminución de su grosor", "Aumento del volumen de la aurícula derecha"], "a": 0, "e": "La estenosis dificulta la apertura y aumenta la poscarga (hipertrofia concéntrica); la insuficiencia provoca reflujo, aumenta la precarga y dilata el ventrículo. En la estenosis aórtica grave del anciano puede optarse por la TAVI."}, {"q": "Un índice tobillo-brazo de 0,75 indica:", "o": ["Normalidad", "Arterias calcificadas e incompresibles", "Un error de técnica", "Enfermedad arterial periférica"], "a": 3, "e": "Un ITB ≤ 0,90 confirma la enfermedad arterial periférica; > 1,40 sugiere arterias incompresibles (rigidez, calcificación). Se calcula con la sistólica más alta de cada tobillo dividida entre la más alta de los brazos."}, {"q": "En un paciente con enfermedad arterial periférica y claudicación intermitente, es correcto aconsejar:", "o": ["Reposo absoluto para evitar el dolor", "Aplicar bolsas de agua caliente en los pies", "Dejar de fumar y caminar hasta el umbral del dolor, descansar y repetir", "Usar calzado ajustado para mejorar la circulación"], "a": 2, "e": "El ejercicio supervisado favorece la circulación colateral. Dejar de fumar es prioritario. Se educa en el cuidado de los pies y se evita el calor directo por el riesgo de quemaduras."}, {"q": "En la prevención del ictus en la fibrilación auricular, es correcto:", "o": ["La aspirina es una alternativa adecuada a la anticoagulación", "La anticoagulación se decide según la escala CHA₂DS₂-VASc, y los antiagregantes no deben sustituirla", "Ningún paciente con FA necesita anticoagulación", "La anticoagulación solo se indica en menores de 65 años"], "a": 1, "e": "La FA favorece trombos en la orejuela izquierda e ictus cardioembólicos. La escala CHA₂DS₂-VASc orienta la anticoagulación (antivitamina K o anticoagulantes directos); la aspirina no es una alternativa."}, {"q": "Al realizar un ECG, el electrodo de color rojo de las derivaciones de los miembros se coloca en:", "o": ["La muñeca derecha", "La muñeca izquierda", "El tobillo izquierdo", "El tobillo derecho"], "a": 0, "e": "Rojo: brazo derecho; amarillo: brazo izquierdo; verde: pierna izquierda; negro: pierna derecha (tierra)."}, {"q": "La derivación precordial V1 se coloca en:", "o": ["El 5.º espacio intercostal, línea medioclavicular izquierda", "El 5.º espacio intercostal, línea axilar media", "El 4.º espacio intercostal, en el borde paraesternal derecho", "El 4.º espacio intercostal, en el borde paraesternal izquierdo"], "a": 2, "e": "V1: 4.º EIC paraesternal derecho; V2: 4.º EIC paraesternal izquierdo; V3: entre V2 y V4; V4: 5.º EIC línea medioclavicular; V5: línea axilar anterior; V6: línea axilar media."}, {"q": "Ante un IAM inferior con hipotensión, para valorar la afectación del ventrículo derecho se realiza:", "o": ["La derivación V7", "Un ECG a 50 mm/s", "Las derivaciones V7-V9", "La derivación V4R"], "a": 3, "e": "Las derivaciones derechas (sobre todo V4R) detectan el infarto de ventrículo derecho. Las posteriores (V7-V9) detectan el infarto posterior, que se sospecha por descenso del ST en V1-V3."}, {"q": "La velocidad estándar del papel en un ECG es de:", "o": ["10 mm/s", "25 mm/s", "50 mm/s", "100 mm/s"], "a": 1, "e": "La velocidad estándar es 25 mm/s (50 mm/s para taquicardias) y la calibración, 10 mm = 1 mV. Cada cuadrado pequeño equivale a 0,04 s y cada grande, a 0,20 s."}, {"q": "Si al tomar la tensión arterial se utiliza un manguito demasiado pequeño para el brazo del paciente, se obtendrán:", "o": ["Cifras falsamente elevadas", "Cifras falsamente bajas", "Cifras correctas", "Solo se altera la diastólica a la baja"], "a": 0, "e": "El manguito pequeño sobreestima la PA y el grande la infraestima. La cámara debe cubrir aproximadamente el 40% del ancho y el 80% de la circunferencia del brazo."}, {"q": "En la medición de la presión arterial por el método auscultatorio, la presión diastólica corresponde a:", "o": ["La fase I de Korotkoff (aparición del primer ruido)", "La fase II (ruidos soplantes)", "La fase V de Korotkoff (desaparición de los ruidos)", "La fase III (ruidos intensos)"], "a": 2, "e": "La fase I marca la sistólica y la fase V (desaparición), la diastólica. Se infla 20-30 mmHg por encima de la sistólica palpada y se desinfla a 2-3 mmHg por segundo."}, {"q": "Para medir la presión venosa central, el transductor debe situarse a la altura del eje flebostático, que se localiza en:", "o": ["El 2.º espacio intercostal, línea medioclavicular", "La apófisis xifoides", "El 5.º espacio intercostal, línea axilar anterior", "El 4.º espacio intercostal, en la línea axilar media"], "a": 3, "e": "El eje flebostático corresponde a la aurícula derecha. Si el transductor queda por encima, las presiones salen falsamente bajas y, por debajo, altas. Se hace el cero abriendo al aire y se lee al final de la espiración."}, {"q": "Respecto al mantenimiento de una línea arterial radial, es correcto:", "o": ["Puede administrarse medicación en bolo por ella", "El sistema se mantiene permeable con un presurizador a 300 mmHg y lavado continuo, y nunca se administra medicación por la arteria", "No es necesario valorar la circulación colateral antes de canalizarla", "El presurizador se mantiene a 100 mmHg"], "a": 1, "e": "La bolsa presurizada a 300 mmHg aporta un lavado continuo de unos 3 ml/h que evita la coagulación. Antes de canalizar la radial se realiza el test de Allen. La medicación por vía arterial puede causar necrosis."}, {"q": "En una parada cardiaca en fibrilación ventricular, según el algoritmo de SVA del ERC, la primera dosis de adrenalina se administra:", "o": ["Tras la tercera descarga, repitiéndose cada 3-5 minutos", "Antes de la primera descarga", "Nunca en los ritmos desfibrilables", "Tras la primera descarga, cada minuto"], "a": 0, "e": "En los ritmos desfibrilables: descarga y RCP inmediata sin comprobar pulso; adrenalina 1 mg y amiodarona 300 mg tras la tercera descarga. En asistolia y AESP, la adrenalina se da en cuanto se disponga de acceso vascular."}, {"q": "Durante la RCP, una vez que el paciente está intubado, la secuencia correcta es:", "o": ["Mantener ciclos 30:2", "Ventilar a 20 respiraciones por minuto", "Detener las compresiones para cada ventilación", "Compresiones continuas a 100-120/min y unas 10 ventilaciones por minuto, sin hiperventilar"], "a": 3, "e": "Con vía aérea avanzada las compresiones no se interrumpen y se ventila unas 10 veces por minuto. La hiperventilación aumenta la presión intratorácica y reduce el retorno venoso."}, {"q": "En la colocación de los electrodos precordiales de la imagen, el electrodo rojo (V1) se coloca en el:", "o": ["4.º espacio intercostal, borde paraesternal derecho", "4.º espacio intercostal, borde paraesternal izquierdo", "5.º espacio intercostal, línea medioclavicular izquierda", "5.º espacio intercostal, línea axilar media"], "a": 0, "e": "V1 4.º EIC paraesternal derecho (rojo), V2 4.º EIC paraesternal izquierdo (amarillo), V3 entre V2 y V4 (verde), V4 5.º EIC medioclavicular (marrón), V5 axilar anterior (negro), V6 axilar media (violeta).", "img": "img/preguntas/t41-electrodos.jpg"}, {"q": "Paciente de 78 años con palpitaciones y este trazado (RR irregular, sin ondas P). ¿Cuál es la complicación principal que hay que prevenir?", "o": ["Hipoglucemia", "Bloqueo AV completo", "Embolia sistémica (ictus)", "Hiperpotasemia"], "a": 2, "e": "Fibrilación auricular: la aurícula no se contrae y se forman trombos (orejuela izquierda). Se valora la anticoagulación con la escala CHA₂DS₂-VASc.", "img": "img/preguntas/ecg-fa.svg"}, {"q": "¿Qué ritmo muestra este trazado, con la línea de base en «dientes de sierra»?", "o": ["Fibrilación auricular", "Taquicardia ventricular", "Ritmo sinusal", "Flutter auricular"], "a": 3, "e": "Flutter: ondas F regulares a ≈ 300/min, en dientes de sierra en II, III y aVF. Con conducción 2:1 la FC suele ser ≈ 150 lpm; aquí, 4:1 (≈ 75 lpm).", "img": "img/preguntas/ecg-flutter.svg"}, {"q": "Dolor torácico opresivo de 30 minutos con este trazado en II, III y aVF. ¿Qué actuación es prioritaria?", "o": ["Activar el Código Infarto para la reperfusión urgente", "Repetir el ECG en 24 horas", "Administrar adenosina en bolo", "Cardioversión sincronizada"], "a": 0, "e": "Elevación del ST en derivaciones inferiores = IAMCEST inferior: reperfusión (ICP primaria) cuanto antes. En el inferior, registrar también V3R-V4R (ventrículo derecho).", "img": "img/preguntas/ecg-elevacion-st.svg"}, {"q": "Trazado con ondas P y QRS disociados, sin relación entre ellos, y QRS anchos a ≈ 35 lpm. El diagnóstico es:", "o": ["BAV de 1.er grado", "BAV de 2.º grado Mobitz I", "Fibrilación auricular lenta", "BAV completo (3.er grado)"], "a": 3, "e": "Disociación AV completa con ritmo de escape ventricular lento y ancho: riesgo de síncope (Stokes-Adams). Tratamiento: marcapasos.", "img": "img/preguntas/ecg-bav3.svg"}, {"q": "En este ritmo sinusal aparece un latido adelantado, ancho, sin P previa y seguido de una pausa. Es una:", "o": ["Extrasístole auricular", "Extrasístole ventricular", "Onda P bloqueada", "Taquicardia ventricular"], "a": 1, "e": "Extrasístole ventricular: QRS prematuro y ancho, sin P, con pausa compensadora completa. Tres o más seguidas a > 100 lpm = taquicardia ventricular.", "img": "img/preguntas/ecg-extrasistole.svg"}]},
42: {"tema": 42, "titulo": "Cuidados de enfermería a personas con problemas renales. Insuficiencia renal aguda. Otros problemas renales y urológicos. Procedimientos y técnicas. Cateterismo vesical", "programa": "Valoración y cuidados de enfermería a personas con problemas en el sistema renal: insuficiencia renal aguda. Otros problemas renales y urológicos. Procedimientos y técnicas de enfermería. Cateterismo vesical: concepto, indicaciones y contraindicaciones del sondaje vesical.", "preguntas": [{"q": "En una gestante en el segundo trimestre, una creatinina sérica de 0,9 mg/dl debe interpretarse como:", "o": ["Un valor normal para cualquier adulto", "Un posible deterioro del filtrado, ya que en el embarazo la creatinina normal es más baja (0,4-0,6 mg/dl)", "Un valor bajo por hiperfiltración", "Un valor que solo importa en el tercer trimestre"], "a": 1, "e": "En el embarazo el filtrado glomerular aumenta hasta un 50% y la creatinina normal desciende. Un valor considerado normal en la población general puede indicar una lesión renal oculta en la gestante."}, {"q": "A la percusión, una vejiga distendida por retención urinaria (globo vesical) produce un sonido:", "o": ["Timpánico", "Hiperresonante", "Metálico", "Mate"], "a": 3, "e": "La vejiga llena de orina es mate; el timpanismo es propio del gas intestinal."}, {"q": "En la escala de Godet, un edema con fóvea de unos 4 mm que tarda 10-15 segundos en recuperarse corresponde al grado:", "o": ["2+", "1+", "3+", "4+"], "a": 0, "e": "Regla práctica: grado × 2 = milímetros. 1+ ≈ 2 mm; 2+ ≈ 4 mm (10-15 s); 3+ ≈ 6 mm (hasta 1 min); 4+ ≥ 8 mm (2-5 min)."}, {"q": "El parámetro más fiable para valorar la sobrecarga de volumen o la deshidratación en un paciente renal es:", "o": ["La diuresis de un día aislado", "El color de la orina", "El peso diario en ayunas, con la misma báscula y ropa", "La sed referida por el paciente"], "a": 2, "e": "El balance hídrico tiene errores (vómitos no medidos, sudor). El peso diario en las mismas condiciones es el mejor indicador: 1 kg equivale aproximadamente a 1 litro de líquido."}, {"q": "Para la recogida de orina de 24 horas, el paciente debe:", "o": ["Desechar la primera micción del primer día y recoger todas las siguientes, incluida la primera del día siguiente", "Recoger solo la primera orina de la mañana", "Recoger la primera micción del primer día y desechar la del día siguiente", "Recoger una muestra cada 6 horas"], "a": 0, "e": "La primera orina del día 1 se desecha y, desde ese momento, se recoge toda la orina durante 24 horas, incluida la primera micción del día 2 a la misma hora. El recipiente se mantiene refrigerado."}, {"q": "Tras una biopsia renal percutánea, los cuidados de enfermería incluyen:", "o": ["Deambulación inmediata para prevenir trombosis", "Decúbito prono durante 24 horas", "Alta inmediata si la punción ha sido fácil", "Reposo en decúbito supino durante unas 24 horas, control de constantes y vigilancia de hematuria"], "a": 3, "e": "La punción se hace en decúbito prono, pero el reposo posterior es en decúbito supino para comprimir la zona. La taquicardia o la hipotensión pueden indicar un sangrado retroperitoneal."}, {"q": "La causa más frecuente de insuficiencia renal aguda es la:", "o": ["Posrenal por obstrucción", "Prerrenal por hipoperfusión renal", "Necrosis tubular por tóxicos", "Glomerulonefritis aguda"], "a": 1, "e": "La prerrenal (hipovolemia, bajo gasto, sepsis) es la más frecuente; el riñón está sano y produce una orina concentrada y pobre en sodio. Si se corrige a tiempo, se recupera sin secuelas."}, {"q": "Según los criterios KDIGO, una lesión renal aguda en estadio 1 se define por:", "o": ["Creatinina tres veces la basal", "Anuria de más de 12 horas", "Aumento de la creatinina de al menos 0,3 mg/dl o diuresis < 0,5 ml/kg/h durante más de 6 horas", "Necesidad de diálisis"], "a": 2, "e": "Estadio 1: +0,3 mg/dl o 1,5-1,9 veces la basal, o diuresis < 0,5 ml/kg/h 6-12 h. Estadio 2: 2-2,9 veces o < 0,5 ml/kg/h ≥ 12 h. Estadio 3: ≥ 3 veces, ≥ 4 mg/dl, diálisis, < 0,3 ml/kg/h ≥ 24 h o anuria ≥ 12 h."}, {"q": "En un paciente con insuficiencia renal aguda oligúrica, la restricción de líquidos suele calcularse como:", "o": ["La diuresis del día anterior más las pérdidas insensibles", "3 litros al día en todos los casos", "500 ml al día fijos", "La mitad de la diuresis del día anterior"], "a": 0, "e": "Se repone lo que se pierde: diuresis previa más pérdidas insensibles (≈ 0,5 ml/kg/h, más si hay fiebre o taquipnea), con peso diario y balance estricto."}, {"q": "Es una indicación de depuración extrarrenal urgente en la insuficiencia renal aguda:", "o": ["Una creatinina de 1,5 mg/dl", "Una diuresis de 1.000 ml/día", "Una hiperpotasemia de 4,8 mEq/l", "Una hiperpotasemia superior a 6,5 mEq/l con alteraciones en el ECG"], "a": 3, "e": "Regla AEIOU: acidosis grave (pH < 7,2), electrolitos (K > 6,5 con cambios en el ECG), intoxicaciones, sobrecarga de volumen (edema agudo de pulmón refractario) y uremia (encefalopatía, pericarditis)."}, {"q": "En un paciente en shock séptico con noradrenalina que necesita depuración renal, la técnica de elección es:", "o": ["La hemodiálisis intermitente convencional", "Una técnica de reemplazo renal continua (hemofiltración o hemodiafiltración venovenosa continua)", "La diálisis peritoneal de urgencia", "El trasplante renal urgente"], "a": 1, "e": "Las técnicas continuas extraen líquidos y solutos lentamente durante 24 h y se toleran mejor en pacientes hemodinámicamente inestables; la hemodiálisis convencional puede empeorar la hipotensión."}, {"q": "Para reducir el contenido de potasio de las verduras y patatas en un paciente con enfermedad renal crónica, se recomienda:", "o": ["Freírlas a alta temperatura", "Consumirlas crudas", "Dejarlas en remojo y realizar doble cocción, desechando el agua", "Cocinarlas al vapor sin agua"], "a": 2, "e": "El potasio pasa al agua: el remojo y la doble cocción, tirando el agua, reducen su contenido y el riesgo de hiperpotasemia."}, {"q": "Un paciente con enfermedad renal crónica toma un quelante del fósforo (sevelámero). Debe tomarlo:", "o": ["Con las comidas", "En ayunas al levantarse", "Antes de acostarse, lejos de las comidas", "Solo cuando note picor"], "a": 0, "e": "Los quelantes se unen al fósforo de los alimentos en el tubo digestivo: sin comida no actúan. Se toman con las comidas."}, {"q": "El criterio analítico indispensable del síndrome nefrótico en el adulto es:", "o": ["Hematuria con cilindros hemáticos", "Creatinina superior a 4 mg/dl", "Glucosuria", "Proteinuria superior a 3,5 g en 24 horas"], "a": 3, "e": "El síndrome nefrótico cursa con proteinuria masiva, hipoalbuminemia, edemas generalizados (anasarca) e hiperlipidemia. La hematuria con cilindros es propia del nefrítico."}, {"q": "Un niño presenta tras una faringitis orina oscura con hematuria, hipertensión arterial, oliguria y edema palpebral. Sugiere:", "o": ["Síndrome nefrótico", "Síndrome nefrítico", "Cólico nefrítico", "Infección urinaria baja"], "a": 1, "e": "El síndrome nefrítico es inflamatorio: hematuria con cilindros hemáticos, HTA por expansión de volumen, oliguria e insuficiencia renal aguda, con edema moderado sobre todo periorbitario."}, {"q": "En el tratamiento del cólico nefrítico, es una actuación correcta de enfermería:", "o": ["Aplicar frío local en la zona lumbar", "Restringir los líquidos de forma estricta", "Administrar AINE intravenosos según pauta, aplicar calor local y filtrar la orina para recoger el cálculo", "Mantener al paciente inmóvil en posición fetal"], "a": 2, "e": "Los AINE son la primera línea (opioides si no ceden), con antieméticos. El calor local relaja el uréter y se filtra la orina para analizar el cálculo. El paciente con cólico típicamente no encuentra postura."}, {"q": "A un paciente con litiasis de ácido úrico se le recomienda limitar:", "o": ["Las proteínas animales ricas en purinas (vísceras, marisco, carnes rojas)", "El agua", "Las frutas y verduras frescas", "Los cereales integrales"], "a": 0, "e": "En la litiasis úrica se limitan las purinas. En la de oxalato cálcico (la más frecuente) se evitan espinacas, remolacha, frutos secos, chocolate o té. En todas, beber para orinar más de 2 litros al día."}, {"q": "Un anciano previamente orientado presenta de forma brusca desorientación y agitación. Como primera sospecha, la enfermera debe descartar:", "o": ["Una enfermedad de Alzheimer", "Un ictus en todos los casos", "Un trastorno psicótico primario", "Una infección urinaria"], "a": 3, "e": "En el anciano la infección urinaria puede manifestarse de forma atípica, solo con confusión, agitación, anorexia o deterioro funcional."}, {"q": "Según la guía de indicación enfermera de 2024 para la infección urinaria baja no complicada en mujeres adultas, uno de los tratamientos de primera línea es:", "o": ["Ciprofloxacino durante 14 días", "Fosfomicina 3 g en dosis única", "Amoxicilina-clavulánico intravenoso", "Gentamicina intramuscular"], "a": 1, "e": "Se puede indicar fosfomicina 3 g en dosis única (por la noche, en ayunas) o nitrofurantoína 100 mg cada 12 h con comida durante 5-7 días, siempre que no haya fiebre, dolor lumbar ni embarazo."}, {"q": "Un paciente operado de RTUP con lavado vesical continuo refiere dolor suprapúbico intenso; hay fugas alrededor de la sonda y no sale líquido a la bolsa. Lo primero es:", "o": ["Administrar un analgésico y reevaluar", "Aumentar el ritmo del lavado", "Detener la entrada de suero y realizar un lavado manual con jeringa para desobstruir el coágulo", "Retirar la sonda"], "a": 2, "e": "Son signos de obstrucción por coágulos: hay que parar la irrigación y desobstruir con lavado manual. Si el lavado fluye y hay dolor, se trata de espasmos vesicales y se administra un antiespasmódico."}, {"q": "Un adolescente presenta dolor testicular súbito e intenso de madrugada, con el testículo ascendido y ausencia de reflejo cremastérico. La actuación correcta es:", "o": ["Considerarlo una urgencia quirúrgica: la destorsión debe hacerse en menos de 6 horas", "Pautar antibiótico por epididimitis", "Citarlo en consulta de urología en una semana", "Aplicar calor y observar"], "a": 0, "e": "Es la sospecha de torsión testicular: el retraso más allá de 6 horas compromete la viabilidad del testículo. El signo de Prehn es negativo (el dolor no alivia al elevarlo), a diferencia de la epididimitis."}, {"q": "Un politraumatizado con fractura de pelvis presenta sangre en el meato urinario. Respecto al sondaje vesical:", "o": ["Se debe sondar con una sonda de menor calibre", "Se debe sondar con más lubricante", "Se debe usar una sonda de Tiemann", "No se debe sondar: hay que avisar al médico por sospecha de rotura uretral"], "a": 3, "e": "La uretrorragia tras un traumatismo pélvico sugiere rotura de uretra y contraindica el sondaje uretral; puede necesitarse una talla suprapúbica. También se evita sondar en prostatitis aguda o uretritis purulenta."}, {"q": "El balón de una sonda Foley debe inflarse con:", "o": ["Suero fisiológico", "Agua destilada estéril", "Aire", "Solución glucosada"], "a": 1, "e": "Se usa agua destilada (10-20 ml según el fabricante). El suero fisiológico puede cristalizar y bloquear la válvula, impidiendo desinflar el balón. Antes de inflar se avanzan 2-3 cm tras ver salir orina."}, {"q": "En un varón con hiperplasia prostática importante en el que no progresa una sonda Foley convencional, la sonda indicada es la:", "o": ["Nélaton", "Couvelaire", "Tiemann, de punta curva y olivada", "Malecot"], "a": 2, "e": "La Tiemann (o la Mercier) tiene la punta curva para franquear la uretra prostática. La Nélaton es para sondaje intermitente, la Couvelaire para hematuria con coágulos y la Malecot es quirúrgica."}, {"q": "Al sondar a un paciente con un globo vesical de unos 1.500 ml, la enfermera debe:", "o": ["Vaciar la vejiga de una vez lo más rápido posible", "No vaciarla hasta que lo indique el urólogo", "Vaciar solo 100 ml y retirar la sonda", "Vaciar de forma fraccionada, pinzando la sonda tras cada 250-500 ml"], "a": 3, "e": "La descompresión brusca puede provocar hematuria ex vacuo e hipotensión. Se vacía por fases, pinzando y esperando unos minutos entre ellas."}, {"q": "Una puérpera a las 4 horas del parto sangra abundantemente; el útero está alto, blando y desviado a la derecha, y no ha orinado desde el parto. La primera actuación es:", "o": ["Realizar un sondaje vesical evacuador", "Administrar un antitérmico", "Colocarla en Trendelenburg sin más", "Esperar a que orine espontáneamente a las 12 horas"], "a": 0, "e": "La vejiga llena desplaza el útero e impide su contracción, causando atonía y hemorragia. Se vacía con sondaje intermitente (Nélaton). Si no hay micción espontánea a las 6 horas, hay que actuar."}, {"q": "Durante un lavado vesical continuo, si el líquido de drenaje sale rojo intenso con coágulos, la enfermera debe:", "o": ["Cerrar el lavado", "Aumentar el ritmo de infusión del suero", "Disminuir el ritmo de infusión", "Retirar la sonda de tres vías"], "a": 1, "e": "A más sangre, más velocidad de lavado para que no se formen coágulos; si el líquido sale rosado claro, se ralentiza el goteo."}, {"q": "Un paciente con urostomía tipo Bricker presenta abundante moco en la bolsa de orina. Esto se debe a:", "o": ["Una infección urinaria grave", "Una obstrucción del estoma", "Que el conducto está formado por íleon, que produce moco de forma normal", "Un rechazo del estoma"], "a": 2, "e": "En la técnica de Bricker la orina sale a través de un segmento de íleon: el moco es un hallazgo normal. La placa se recorta ajustada a la mucosa para proteger la piel."}, {"q": "En el brazo portador de una fístula arteriovenosa para hemodiálisis, es correcto:", "o": ["Tomar la tensión arterial en él para controlar la fístula", "Extraer las analíticas de esa vena porque está más dilatada", "Canalizar vías periféricas si la urgencia lo requiere", "Comprobar el frémito (palpación) y el soplo (auscultación) y no tomar la tensión, extraer sangre ni canalizar vías en él"], "a": 3, "e": "La fístula se protege: no tomar TA, no extraer sangre, no canalizar vías ni llevar relojes o pesos. La desaparición súbita del thrill y del soplo indica trombosis."}, {"q": "En un paciente en diálisis peritoneal, la aparición de un líquido de drenaje turbio sugiere:", "o": ["Peritonitis: se guarda la bolsa para cultivo y se avisa", "Un hallazgo normal tras las comidas", "Exceso de calentamiento del líquido", "Deshidratación"], "a": 0, "e": "El efluente turbio es el signo de alarma de peritonitis. El líquido de diálisis se calienta a 37 °C con calor seco, nunca en microondas ni al baño maría."}]},
43: {"tema": 43, "titulo": "Cuidados de enfermería a personas con problemas del sistema músculo-esquelético. Principales problemas del aparato locomotor. Vendajes, inmovilizaciones y otras técnicas", "programa": "Valoración y cuidados de enfermería a personas con problemas en el sistema músculo-esquelético. Principales problemas del aparato locomotor (artrosis, artritis, osteoporosis, fracturas, síndrome compartimental). Procedimientos de enfermería: vendajes, inmovilizaciones, tracciones y ayudas a la marcha.", "preguntas": [{"q": "La sínfisis del pubis es un ejemplo de articulación de tipo:", "o": ["Sinartrosis", "Diartrosis", "Anfiartrosis", "Sinovial"], "a": 2, "e": "Las anfiartrosis tienen movilidad limitada y están unidas por fibrocartílago (sínfisis del pubis, discos intervertebrales). Las sinartrosis son inmóviles (suturas craneales) y las diartrosis o sinoviales son las más móviles."}, {"q": "Un dolor articular que empeora en reposo, despierta por la noche y se acompaña de rigidez matutina de más de una hora es característico de:", "o": ["Un proceso inflamatorio como la artritis reumatoide", "La artrosis", "Una tendinitis mecánica", "Una contractura muscular"], "a": 0, "e": "El dolor inflamatorio empeora con la inactividad y produce rigidez prolongada. El dolor mecánico (artrosis) empeora con el uso y mejora con el reposo, con rigidez de menos de 30 minutos."}, {"q": "La deformidad en la que las rodillas se juntan y los tobillos se separan («en X») se denomina:", "o": ["Genu varo", "Genu recurvatum", "Pie equino", "Genu valgo"], "a": 3, "e": "En el genu valgo las rodillas se juntan y los tobillos se separan; en el genu varo las rodillas se separan (piernas arqueadas). Ambas alteran la carga sobre el cartílago."}, {"q": "La marcha en estepaje, con «pie caído», se debe típicamente a una lesión del:", "o": ["Nervio mediano", "Nervio peroneo", "Cerebelo", "Nervio femoral"], "a": 1, "e": "La parálisis del nervio peroneo impide la flexión dorsal del pie. La marcha festinante es propia del Parkinson y la espástica en segador, de lesiones de la vía piramidal."}, {"q": "En la escala de Tinetti de equilibrio y marcha, una puntuación inferior a 19 indica:", "o": ["Riesgo alto de caídas", "Riesgo bajo de caídas", "Equilibrio normal", "Riesgo moderado de caídas"], "a": 0, "e": "La puntuación máxima es 28: 25-28 riesgo bajo, 19-24 moderado y menos de 19 alto."}, {"q": "El reflejo rotuliano explora las raíces nerviosas:", "o": ["C5-C6", "C7", "L3-L4", "S1"], "a": 2, "e": "Bicipital C5-C6, tricipital C7, rotuliano L3-L4 y aquíleo S1. Una respuesta 4+ con clonus sugiere lesión de primera motoneurona."}, {"q": "La maniobra de Lasègue (elevación de la pierna extendida en decúbito supino) es positiva cuando aparece dolor radicular entre los 30° y 70°, lo que indica:", "o": ["Rotura del ligamento cruzado anterior", "Síndrome del túnel carpiano", "Debilidad del glúteo medio", "Irritación o compresión del nervio ciático"], "a": 3, "e": "El Lasègue valora la irritación radicular del ciático (L4-S1). El túnel carpiano se explora con Tinel y Phalen, los cruzados con el cajón y el glúteo medio con el Trendelenburg."}, {"q": "La maniobra que consiste en mantener ambas muñecas en flexión forzada durante 60 segundos para reproducir parestesias es la de:", "o": ["Tinel", "Phalen", "Lasègue", "Ortolani"], "a": 1, "e": "La maniobra de Phalen y el signo de Tinel (percutir el nervio mediano en la muñeca) se usan para el síndrome del túnel carpiano."}, {"q": "En la maniobra de Trendelenburg, si al apoyarse sobre la pierna derecha desciende la pelvis del lado izquierdo, existe debilidad del:", "o": ["Glúteo mayor izquierdo", "Cuádriceps derecho", "Glúteo medio derecho (lado de apoyo)", "Psoas izquierdo"], "a": 2, "e": "El glúteo medio del lado de apoyo es el que estabiliza la pelvis; si está débil, cae la hemipelvis contraria."}, {"q": "Los nódulos de Heberden de la artrosis de manos se localizan en las articulaciones:", "o": ["Interfalángicas distales", "Interfalángicas proximales", "Metacarpofalángicas", "Radiocarpianas"], "a": 0, "e": "Heberden en las interfalángicas distales y Bouchard en las proximales. La artritis reumatoide afecta típicamente a las metacarpofalángicas y el carpo."}, {"q": "En la educación de un paciente con gonartrosis de la rodilla derecha, es correcto recomendar:", "o": ["Llevar el bastón en la mano derecha", "Realizar deportes de alto impacto para fortalecer el cartílago", "Aplicar frío de forma continua", "Perder peso, ejercicio de bajo impacto para fortalecer el cuádriceps y usar el bastón en la mano izquierda"], "a": 3, "e": "La reducción de peso es la medida más eficaz. El bastón se lleva en la mano contraria a la articulación afectada. El calor alivia la rigidez; el frío se reserva para los brotes inflamatorios."}, {"q": "La deformidad en «cuello de cisne» de la artritis reumatoide consiste en:", "o": ["Flexión de la interfalángica proximal e hiperextensión de la distal", "Hiperextensión de la interfalángica proximal y flexión de la distal", "Desviación de los dedos hacia el lado radial", "Nódulos en las interfalángicas distales"], "a": 1, "e": "Cuello de cisne: hiperextensión de la IFP y flexión de la IFD. En ojal (boutonnière): flexión de la IFP e hiperextensión de la IFD. También es típica la desviación cubital de los dedos."}, {"q": "En un paciente con artritis reumatoide que va a iniciar tratamiento biológico, la enfermera debe:", "o": ["Administrarle vacunas de virus vivos durante el tratamiento", "Recomendarle reposo absoluto permanente", "Comprobar y actualizar las vacunas (neumococo, gripe, hepatitis B) antes de iniciarlo y evitar las vacunas vivas durante el tratamiento", "Suspender cualquier vacunación"], "a": 2, "e": "Los biológicos y FAME son inmunosupresores: hay que vacunar antes, evitar vacunas vivas y educar en la detección precoz de infecciones y en la técnica de autoinyección."}, {"q": "Según la OMS, se diagnostica osteoporosis en la densitometría cuando el T-score es:", "o": ["Igual o inferior a −2,5", "Entre −1 y −2,5", "Superior a −1", "Superior a +2,5"], "a": 0, "e": "T-score ≥ −1 normal; entre −1 y −2,5 osteopenia; ≤ −2,5 osteoporosis. La causa secundaria más importante es el uso prolongado de corticoides."}, {"q": "Para la toma de alendronato oral semanal, la enfermera debe indicar:", "o": ["Tomarlo con el desayuno y un vaso de leche", "Tomarlo antes de acostarse", "Tomarlo con zumo de naranja para mejorar su absorción", "Tomarlo en ayunas al levantarse con un vaso lleno de agua y permanecer erguido sin comer ni tumbarse 30-60 minutos"], "a": 3, "e": "Los bisfosfonatos se absorben muy poco y pueden dañar el esófago: en ayunas, con agua (no leche, zumo ni agua mineral), y sin tumbarse ni tomar nada durante 30-60 minutos."}, {"q": "Para la prevención de la osteoporosis, el tipo de ejercicio más recomendado es:", "o": ["La natación exclusivamente", "El ejercicio con carga e impacto moderado, como caminar a paso ligero o subir escaleras", "El reposo para evitar fracturas", "Los estiramientos sin carga"], "a": 1, "e": "El impacto y la carga mecánica estimulan a los osteoblastos (ley de Wolff). En la artrosis, en cambio, se prefieren los ejercicios de bajo impacto."}, {"q": "Ante una fractura abierta, es correcto que:", "o": ["Es una urgencia quirúrgica que requiere antibiótico precoz, desbridamiento y profilaxis antitetánica", "Puede tratarse de forma diferida en consulta", "Solo requiere una inmovilización con yeso cerrado", "No necesita antibiótico si no sangra"], "a": 0, "e": "La comunicación del foco con el exterior conlleva un riesgo alto de osteomielitis: urgencia quirúrgica con antibioterapia, limpieza y profilaxis antitetánica."}, {"q": "En la consolidación de una fractura, la fase en la que se forma un tejido fibrocartilaginoso que todavía no es visible en la radiografía ni soporta carga es la de:", "o": ["Hematoma", "Callo duro", "Callo blando", "Remodelación"], "a": 2, "e": "Fases: hematoma e inflamación, callo blando (2-3 semanas, radiotransparente), callo duro (3-10 semanas, visible) y remodelación (meses o años)."}, {"q": "Una anciana se cae en casa y presenta la pierna derecha acortada, en rotación externa e imposibilidad para moverla. Debe sospecharse:", "o": ["Una luxación de rodilla", "Un esguince de tobillo", "Una lumbalgia aguda", "Una fractura de cadera"], "a": 3, "e": "La tríada acortamiento, rotación externa e impotencia funcional es típica de la fractura de cadera. Las intracapsulares tienen riesgo de necrosis avascular y las extracapsulares sangran más."}, {"q": "En el postoperatorio de una prótesis de cadera, para prevenir la luxación se debe:", "o": ["Animar al paciente a cruzar las piernas", "Evitar la aducción (no cruzar las piernas), usar cojín abductor y evitar flexionar la cadera más de 90°", "Sentarlo en sillas bajas", "Mantener la cadera en flexión máxima"], "a": 1, "e": "La aducción y la flexión mayor de 90° (sillas bajas, inclinarse hacia delante) favorecen la luxación de la prótesis. Se moviliza precozmente y se vigila el sangrado."}, {"q": "A las 48 horas de una fractura de fémur, un paciente presenta disnea con hipoxemia, confusión y petequias en tórax y axilas. Debe sospecharse:", "o": ["Un síndrome de embolia grasa", "Una neumonía aspirativa", "Un síndrome compartimental", "Una reacción alérgica"], "a": 0, "e": "La embolia grasa aparece a las 24-72 h de fracturas de huesos largos o pelvis con la tríada respiratoria, neurológica y petequial. La prevención principal es inmovilizar pronto la fractura."}, {"q": "El signo más precoz de un síndrome compartimental es:", "o": ["La ausencia de pulso distal", "La parálisis de los dedos", "Un dolor desproporcionado que no cede con analgésicos y aumenta con el estiramiento pasivo", "La cianosis generalizada"], "a": 2, "e": "El dolor desproporcionado y con el estiramiento pasivo es el primer signo, seguido de parestesias. La desaparición del pulso es muy tardía: el músculo se necrosa antes."}, {"q": "Ante la sospecha de síndrome compartimental en una pierna con yeso circular, la actuación inicial de enfermería es:", "o": ["Elevar la pierna por encima del nivel del corazón", "Aplicar más compresión", "Administrar analgesia y reevaluar al día siguiente", "Aflojar o abrir vendajes y bivalvar el yeso, mantener la extremidad a la altura del corazón y avisar para una posible fasciotomía"], "a": 3, "e": "Hay que liberar la presión externa de inmediato. En el síndrome compartimental instaurado no se eleva la extremidad (empeora la perfusión). El tratamiento definitivo es la fasciotomía urgente."}, {"q": "Un recién nacido tras una distocia de hombros mantiene el brazo en aducción y rotación interna («propina de camarero»), con reflejo de prensión conservado. Sugiere:", "o": ["Parálisis braquial inferior de Klumpke", "Parálisis braquial superior de Erb-Duchenne (C5-C6)", "Fractura de fémur", "Lesión medular"], "a": 1, "e": "La parálisis de Erb (C5-C6) es la más frecuente y conserva la prensión. La de Klumpke (C8-T1) produce mano en garra, sin prensión, y puede asociar síndrome de Horner."}, {"q": "Para vestir a un recién nacido con una parálisis braquial obstétrica, se debe enseñar a los padres a:", "o": ["Introducir primero el brazo lesionado al vestirlo y sacar primero el brazo sano al desvestirlo", "Introducir primero el brazo sano", "Levantarlo siempre por las axilas", "Mantener el brazo afectado colgando"], "a": 0, "e": "Así se evita traccionar el brazo afectado. Durante las primeras semanas se puede sujetar la manga a la ropa sobre el pecho."}, {"q": "Al aplicar un vendaje en una extremidad, es correcto:", "o": ["Vendar desde la raíz del miembro hacia los dedos", "Cubrir completamente los dedos", "Vendar de distal a proximal, acolchar las prominencias óseas y dejar los dedos visibles", "Aplicar la máxima tensión en la parte proximal"], "a": 2, "e": "El vendaje de distal a proximal favorece el retorno venoso y evita el efecto torniquete. Los dedos visibles permiten vigilar color, temperatura, relleno capilar y edema."}, {"q": "El tipo de vendaje indicado para cubrir un muñón de amputación o la cabeza (capelina) es el:", "o": ["Vendaje en ocho", "Vendaje en espiral", "Vendaje de Velpeau", "Vendaje recurrente"], "a": 3, "e": "El recurrente cubre extremos (muñones, cabeza). El vendaje en ocho se usa en articulaciones (tobillo, rodilla, codo) y el de Velpeau, en luxaciones de hombro o fracturas de húmero proximal."}, {"q": "En un paciente con tracción esquelética, es un cuidado correcto:", "o": ["Mantener las pesas colgando libremente, sin apoyarlas en el suelo ni en la cama", "Retirar las pesas para el aseo", "Apoyar las pesas en el suelo durante la noche", "Añadir peso si el paciente se queja de dolor"], "a": 0, "e": "Las pesas deben colgar libres para mantener la tracción, sin quitar ni añadir peso sin orden médica. Se curan los puntos de inserción con técnica estéril (riesgo de osteomielitis) y se usa el trapecio para moverse."}, {"q": "En una gestante de 30 semanas politraumatizada inmovilizada en tablero espinal, para evitar la compresión aortocava se debe:", "o": ["Mantenerla en decúbito supino estricto", "Inclinar el tablero 15-30° hacia la izquierda o desplazar manualmente el útero a la izquierda", "Colocarla en Trendelenburg", "Inclinarla hacia la derecha"], "a": 1, "e": "En decúbito supino el útero comprime la cava y la aorta, con hipotensión y sufrimiento fetal. Se inclina a la izquierda con una cuña bajo la cadera derecha o se desplaza el útero manualmente."}, {"q": "Un paciente con una lesión en la pierna izquierda utiliza muletas. Para subir escaleras debe:", "o": ["Subir primero las muletas y la pierna afectada", "Subir las dos piernas a la vez sin muletas", "Subir de espaldas", "Subir primero la pierna sana y después las muletas y la pierna afectada"], "a": 3, "e": "Regla: «la buena sube al cielo, la mala baja al infierno»: se sube primero con la pierna sana y se baja primero con las muletas y la pierna afectada. El peso se apoya en las manos, no en las axilas (riesgo de lesión del nervio radial)."}, {"q": "La alineación de los miembros inferiores de la imagen (rodillas que se juntan y tobillos separados) corresponde a:", "o": ["Genu varo", "Genu recurvatum", "Genu valgo", "Alineación normal"], "a": 2, "e": "Genu valgo: rodillas juntas, tobillos separados («en X»); fisiológico entre los 3 y 6 años. Genu varo: rodillas separadas («en paréntesis»), fisiológico hasta los 2 años.", "img": "img/preguntas/t43-valgo.jpg"}]},
44: {"tema": 44, "titulo": "Cuidados de enfermería a personas con problemas gastrointestinales. Principales problemas del aparato digestivo. Ostomías. Técnicas y procedimientos", "programa": "Valoración y cuidados de enfermería a personas con problemas gastrointestinales. Principales problemas del aparato digestivo (esófago, estómago, intestino, vía biliar, hígado y páncreas). Ostomías. Procedimientos: sondaje nasogástrico, enemas, fecalomas y recogida de muestras de heces.", "preguntas": [{"q": "¿Cuál es el orden correcto de la exploración física del abdomen?", "o": ["Inspección, palpación, percusión y auscultación", "Palpación, percusión, inspección y auscultación", "Inspección, auscultación, percusión y palpación", "Auscultación, inspección, palpación y percusión"], "a": 2, "e": "En el abdomen se ausculta antes de percutir y palpar, porque la manipulación altera los ruidos hidroaéreos: inspección, auscultación, percusión y palpación."}, {"q": "Según la escala de Bristol, las heces de tipo 6-7 corresponden a:", "o": ["Heces de diarrea (pastosas o acuosas)", "Heces de estreñimiento (trozos duros)", "Heces normales con forma de salchicha lisa", "Esteatorrea"], "a": 0, "e": "La escala de Bristol tiene 7 tipos: los tipos 1-2 indican estreñimiento (trozos duros o grumos), los 3-4 son normales y los 6-7 corresponden a diarrea."}, {"q": "Las heces negras, brillantes, pegajosas y malolientes, con aspecto de alquitrán, se denominan:", "o": ["Hematoquecia", "Rectorragia", "Esteatorrea", "Melena"], "a": 3, "e": "La melena se debe a sangre digerida y suele indicar una hemorragia digestiva alta. La rectorragia es sangre roja brillante por el ano y la hematoquecia, sangre roja mezclada con las heces."}, {"q": "La interrupción brusca de la inspiración profunda por dolor al palpar bajo el reborde costal derecho es el signo de:", "o": ["Blumberg, propio de la irritación peritoneal", "Murphy, característico de la colecistitis aguda", "Rovsing, propio de la apendicitis", "Cullen, propio de la pancreatitis"], "a": 1, "e": "El signo de Murphy es típico de la colecistitis aguda. El Blumberg es el dolor a la descompresión brusca; el Rovsing, dolor en la FID al presionar la FII; y el Cullen, la equimosis periumbilical."}, {"q": "Un paciente presenta disfagia para sólidos y líquidos desde el inicio, regurgitación nocturna de alimentos no digeridos y un esofagograma en «pico de pájaro». La prueba que confirma el diagnóstico es:", "o": ["La manometría esofágica", "La pH-metría de 24 horas", "La ecografía abdominal", "El test del aliento"], "a": 0, "e": "Es una acalasia: el esfínter esofágico inferior no se relaja y falta el peristaltismo. La manometría es la prueba definitiva. La disfagia motora afecta a sólidos y líquidos desde el principio; la mecánica, primero a sólidos."}, {"q": "Ante un niño que ha ingerido lejía, la actuación correcta es:", "o": ["Inducir el vómito lo antes posible", "Darle vinagre o zumo de limón para neutralizar el álcali", "No inducir el vómito, no hacer lavado gástrico ni neutralizar, y vigilar la vía aérea", "Hacer un lavado gástrico con sonda de Faucher"], "a": 2, "e": "Con cáusticos, el vómito, el lavado y la neutralización vuelven a quemar la mucosa o producen calor. Se protege la vía aérea, se da analgesia y se hace endoscopia en las primeras 24-48 h. La secuela tardía típica es la estenosis."}, {"q": "La tríada de Mackler (vómitos, dolor torácico intenso y enfisema subcutáneo) es característica de:", "o": ["El síndrome de Mallory-Weiss", "La acalasia", "La hernia de hiato paraesofágica", "El síndrome de Boerhaave"], "a": 3, "e": "El síndrome de Boerhaave es la rotura espontánea del esófago tras vómitos violentos. El Mallory-Weiss es solo un desgarro de la mucosa, que sangra pero no perfora."}, {"q": "El esófago de Barrett:", "o": ["Es la causa más frecuente de disfagia orofaríngea", "Es una metaplasia intestinal por reflujo crónico y una lesión premaligna de adenocarcinoma", "Se asocia sobre todo al carcinoma epidermoide del tercio superior", "Es una complicación de la ingesta de cáusticos que obliga a dilatar"], "a": 1, "e": "Por el reflujo ácido crónico, el epitelio escamoso distal se transforma en epitelio intestinal (metaplasia). Es premaligno y predispone al adenocarcinoma del tercio distal. El epidermoide se asocia al alcohol y al tabaco."}, {"q": "Es típico de la úlcera duodenal:", "o": ["Dolor epigástrico 2-3 horas después de comer o de madrugada, que mejora al ingerir alimento", "Dolor precoz tras las comidas que empeora al comer y lleva a la anorexia", "Que deba biopsiarse siempre porque maligniza con frecuencia", "Que su causa principal sea el grupo sanguíneo A"], "a": 0, "e": "En la úlcera duodenal la comida amortigua el ácido y alivia el dolor. La úlcera gástrica duele pronto y empeora con la ingesta, y debe biopsiarse siempre para descartar un cáncer. Las duodenales casi nunca malignizan."}, {"q": "¿Cuál es la complicación más frecuente de la úlcera péptica?", "o": ["La perforación", "La estenosis pilórica", "La malignización", "La hemorragia digestiva"], "a": 3, "e": "La hemorragia (hematemesis o melena) es la complicación más frecuente. La perforación produce dolor súbito y abdomen en tabla, y la obstrucción pilórica, vómitos tardíos con alcalosis metabólica."}, {"q": "Se considera hemorragia digestiva alta la que se origina:", "o": ["Por encima de la válvula ileocecal", "En cualquier punto del intestino delgado", "Por encima del ángulo de Treitz", "Por encima del esfínter anal interno"], "a": 2, "e": "La HDA nace en el esófago, el estómago o el duodeno, por encima del ángulo de Treitz. Su causa más frecuente es la úlcera péptica; también las varices y el Mallory-Weiss."}, {"q": "En un paciente con hemorragia digestiva alta e inestabilidad hemodinámica, una de las primeras actuaciones de enfermería es:", "o": ["Iniciar dieta líquida para proteger la mucosa", "Canalizar dos vías venosas periféricas de grueso calibre (14-18 G)", "Colocar al paciente en decúbito prono", "Administrar un enema de limpieza"], "a": 1, "e": "Dos vías gruesas permiten reponer la volemia con rapidez. Se monitoriza la hemodinámica por el riesgo de shock hipovolémico y se prepara la endoscopia urgente."}, {"q": "Para el estudio de sangre oculta en heces se recomienda:", "o": ["Recoger muestras de tres deposiciones en días distintos, tomando porciones de diferentes zonas", "Una sola muestra de la primera deposición de la mañana", "Recoger las heces de 72 horas en un único recipiente", "Tomar la muestra solo de la superficie de la deposición"], "a": 0, "e": "El sangrado puede ser intermitente, por eso se recogen tres deposiciones en días distintos y porciones de varios sitios de cada muestra. La recogida de 72 horas es para cuantificar la grasa (Van de Kamer)."}, {"q": "La causa más frecuente de obstrucción mecánica del intestino delgado es:", "o": ["El cáncer colorrectal", "El vólvulo de sigma", "El íleo biliar", "Las bridas o adherencias posquirúrgicas"], "a": 3, "e": "En el intestino delgado predominan las adherencias, seguidas de las hernias. En el intestino grueso la causa principal es el cáncer colorrectal, y después la diverticulitis y el vólvulo de sigma."}, {"q": "Para hacer un lavado gástrico, el paciente se coloca en:", "o": ["Decúbito lateral derecho", "Decúbito prono", "Decúbito lateral izquierdo", "Trendelenburg con decúbito supino"], "a": 2, "e": "El decúbito lateral izquierdo (con la cabeza algo más baja) reduce el paso del contenido al duodeno y protege frente a la broncoaspiración. Se usa una sonda gruesa tipo Faucher."}, {"q": "En la diverticulitis aguda, está contraindicado en la fase aguda:", "o": ["El TAC abdominal con contraste", "La colonoscopia", "La fluidoterapia intravenosa", "La antibioterapia de amplio espectro"], "a": 1, "e": "La colonoscopia y el enema opaco pueden perforar un colon inflamado; se hacen pasadas unas 6 semanas para descartar un cáncer. El TAC es la prueba de imagen de elección."}, {"q": "Es característico de la enfermedad de Crohn:", "o": ["La afectación transmural y segmentaria, que favorece fístulas y estenosis", "La afectación exclusiva del colon y el recto", "La afectación continua desde el recto", "Que el tabaco tenga un efecto protector"], "a": 0, "e": "El Crohn puede afectar cualquier tramo de la boca al ano, sobre todo el íleon terminal, con zonas sanas intercaladas y todo el espesor de la pared. El tabaco lo empeora. Las demás opciones describen la colitis ulcerosa."}, {"q": "Respecto a la colitis ulcerosa, es correcto que:", "o": ["Produce con frecuencia fístulas perianales", "Afecta a todo el espesor de la pared intestinal", "La cirugía no es curativa porque recidiva en el intestino delgado", "Comienza en el recto y se extiende de forma continua, con diarrea sanguinolenta y tenesmo"], "a": 3, "e": "La colitis ulcerosa afecta solo a la mucosa del colon y el recto, de forma continua. Su complicación más temida en el brote es el megacolon tóxico. La proctocolectomía es curativa."}, {"q": "La tríada de Charcot, típica de la colangitis aguda, está formada por:", "o": ["Dolor en cinturón, vómitos y fiebre", "Ictericia, coluria y acolia", "Fiebre con escalofríos, dolor en hipocondrio derecho e ictericia", "Fiebre, hipotensión y confusión"], "a": 2, "e": "Si a la tríada de Charcot se suman hipotensión y alteración mental, se habla de péntada de Reynolds (sepsis biliar grave). El tratamiento clave es drenar la vía biliar, generalmente por CPRE."}, {"q": "Una vesícula biliar palpable e indolora en un paciente con ictericia (signo de Courvoisier-Terrier) hace sospechar:", "o": ["Colecistitis aguda litiásica", "Cáncer de la cabeza del páncreas", "Cólico biliar simple", "Hepatitis aguda vírica"], "a": 1, "e": "Un tumor de la cabeza del páncreas obstruye el colédoco poco a poco: la vesícula se distiende sin inflamarse y la ictericia es indolora. En la litiasis la vesícula suele estar fibrosada y duele."}, {"q": "En la pancreatitis aguda, la enzima sérica más específica para el diagnóstico es:", "o": ["La lipasa", "La amilasa", "La fosfatasa alcalina", "La GGT"], "a": 0, "e": "Se diagnostica con una amilasa y/o lipasa por encima de 3 veces el valor normal, y la lipasa es la más específica. Las causas principales son la litiasis biliar y el alcohol."}, {"q": "El objetivo terapéutico de la lactulosa en la encefalopatía hepática es conseguir:", "o": ["Una deposición cada 48 horas", "Diarrea líquida abundante", "Que el paciente no haga deposiciones para reducir proteínas", "Unas 2-3 deposiciones blandas al día"], "a": 3, "e": "La lactulosa acidifica la luz intestinal, reduce la absorción de amoníaco y acelera su eliminación. El estreñimiento, las hemorragias digestivas y las infecciones precipitan la encefalopatía."}, {"q": "En una paracentesis evacuadora de más de 5 litros en un paciente cirrótico, para prevenir la disfunción circulatoria se administra:", "o": ["Suero glucosado al 5% 1 litro por cada litro extraído", "Furosemida intravenosa", "Albúmina intravenosa, unos 6-8 g por litro de líquido ascítico extraído", "Plasma fresco congelado"], "a": 2, "e": "La reposición con albúmina evita la hipovolemia efectiva tras extraer mucho líquido. Antes de la punción el paciente debe vaciar la vejiga, y la evacuación debe ser lenta, controlando la tensión arterial."}, {"q": "Tras una biopsia hepática percutánea, el paciente debe colocarse en:", "o": ["Decúbito lateral izquierdo durante 30 minutos", "Decúbito lateral derecho durante al menos 2 horas", "Sedestación para facilitar la respiración", "Trendelenburg durante 6 horas"], "a": 1, "e": "El decúbito lateral derecho comprime el punto de punción con el propio peso y favorece la hemostasia. Durante la punción se pide al paciente que mantenga la apnea tras una espiración."}, {"q": "El método más fiable para comprobar a pie de cama la posición gástrica de una SNG antes de administrar nutrición es:", "o": ["Medir el pH del aspirado (inferior a 5,5) y, si hay duda, radiografía", "Auscultar el epigastrio mientras se insufla aire", "Introducir el extremo en un vaso de agua y ver si burbujea", "Comprobar que el paciente puede hablar"], "a": 0, "e": "La auscultación tras insuflar aire no es fiable. El pH ácido del aspirado orienta a una posición gástrica, y la radiografía es la prueba de confirmación cuando hay dudas o en las sondas finas de nutrición."}, {"q": "En un paciente portador de una sonda de Sengstaken-Blakemore, ¿qué material debe estar siempre a pie de cama?", "o": ["Un aspirador de secreciones portátil sin conexión", "Una bolsa de nutrición enteral", "Una pinza de Kocher para pinzar la sonda gástrica", "Unas tijeras para cortar la sonda y desinflar los balones si obstruye la vía aérea"], "a": 3, "e": "Si el balón esofágico migra hacia la faringe puede asfixiar al paciente: hay que cortar los cabos para desinflar los balones al instante. El balón esofágico se mantiene a 25-45 mmHg."}, {"q": "La sonda nasogástrica de tipo Salem se caracteriza por:", "o": ["Tener una sola luz con orificio distal y cuatro laterales", "Ser de calibre muy grueso para lavados en intoxicaciones", "Tener doble luz, una de drenaje y otra de ventilación que evita que se adhiera a la mucosa", "Tener tres luces y dos balones"], "a": 2, "e": "La Levin tiene una luz, la Faucher es gruesa y sirve para lavados gástricos, y la Sengstaken-Blakemore tiene tres luces y dos balones para taponar varices esofágicas."}, {"q": "¿Qué ostomía de eliminación tiene mayor riesgo de deshidratación y alteraciones hidroelectrolíticas?", "o": ["La colostomía sigmoidea", "La ileostomía", "La colostomía descendente", "La urostomía de Bricker"], "a": 1, "e": "La ileostomía elimina heces líquidas y continuas, ricas en enzimas, porque el colon ya no absorbe el agua. Por eso la piel se irrita mucho y se pierden agua, sodio y potasio. No es irrigable."}, {"q": "Un estoma intestinal en buen estado debe tener un aspecto:", "o": ["Rojo brillante, húmedo y ligeramente protruyente", "Pálido y seco", "Violáceo o negruzco", "Hundido por debajo del nivel de la piel"], "a": 0, "e": "Un estoma pálido o negruzco indica isquemia o necrosis, y uno hundido (retracción) favorece las fugas. Un leve sangrado al roce es normal. La bolsa se vacía cuando está a 1/3-1/2 de su capacidad."}, {"q": "La lavativa de Harris se utiliza para:", "o": ["Ablandar las heces duras con aceite", "Administrar contraste de bario", "Administrar medicación que se debe retener 20-30 minutos", "Favorecer la expulsión de gases de la parte final del colon y el recto (efecto carminativo)"], "a": 3, "e": "La lavativa de Harris es carminativa: sirve para expulsar gases. Los enemas de retención (oleoso, medicamentoso u opaco) deben mantenerse unos 20-30 minutos, y los de limpieza buscan vaciar el colon."}, {"q": "La imagen muestra una hernia de hiato en la que el fondo gástrico asciende junto al esófago mientras la unión gastroesofágica permanece en su sitio. Es de tipo:", "o": ["II (paraesofágica o por rodamiento)", "I (por deslizamiento)", "Hernia de Morgagni", "Hernia inguinal indirecta"], "a": 0, "e": "Tipo I (deslizamiento, la más frecuente): sube la unión gastroesofágica, se asocia a reflujo. Tipo II (paraesofágica): la unión queda en su sitio y asciende el fondo; riesgo de vólvulo y estrangulación (cirugía).", "img": "img/preguntas/t44-hernia.jpg"}, {"q": "Hemorroides internas que prolapsan con la defecación y precisan reducción manual, como en la imagen. ¿Qué grado tienen?", "o": ["Grado I", "Grado II", "Grado III", "Grado IV"], "a": 2, "e": "Grado I: no prolapsan (sangrado). II: prolapsan y se reducen solas. III: requieren reducción manual. IV: prolapso permanente e irreductible.", "img": "img/preguntas/t44-hemorroides.jpg"}, {"q": "La imagen muestra un estoma en el colon ascendente (lado derecho del abdomen). ¿Qué heces cabe esperar?", "o": ["Formadas y sólidas", "Ausencia total de heces", "Duras, cada 3 días", "Líquidas o semilíquidas y más irritantes para la piel"], "a": 3, "e": "Cuanto más proximal el estoma, más líquidas e irritantes las heces (más enzimas, menos absorción de agua). Ascendente e ileostomía: líquidas; sigmoidea (la más frecuente): formadas.", "img": "img/preguntas/t44-colostomia.jpg"}]},
45: {"tema": 45, "titulo": "Valoración y cuidados de enfermería a personas con problemas de los órganos de los sentidos. Principales problemas. Procedimientos y técnicas de enfermería", "programa": "Valoración y cuidados de enfermería a personas con problemas de los órganos de los sentidos (vista, oído, tacto, gusto y olfato). Principales problemas: glaucoma, cataratas, desprendimiento de retina, DMAE, defectos de refracción, Ménière, tapón de cerumen y neuropatía. Procedimientos: instilación de colirios, lavado ocular y lavado ótico.", "preguntas": [{"q": "Los corpúsculos de Pacini son receptores cutáneos especializados en detectar:", "o": ["El frío", "La presión profunda y la vibración", "El calor", "El tacto fino de las yemas de los dedos"], "a": 1, "e": "Pacini detecta la presión profunda y la vibración; Meissner, el tacto fino; Ruffini, el calor; Krause, el frío; y las terminaciones nerviosas libres, el dolor."}, {"q": "El gusto del tercio posterior de la lengua se transmite por el nervio:", "o": ["Facial (VII par)", "Trigémino (V par)", "Hipogloso (XII par)", "Glosofaríngeo (IX par)"], "a": 3, "e": "El facial recoge el gusto de los 2/3 anteriores, el glosofaríngeo el del 1/3 posterior y el vago el de la epiglotis y la faringe. El hipogloso es motor de la lengua."}, {"q": "Para valorar el olfato no deben usarse sustancias como el amoníaco o el alcohol porque:", "o": ["Estimulan el nervio trigémino y falsean la prueba del I par", "Lesionan de forma permanente el epitelio olfatorio", "Su olor no es reconocible por la mayoría de pacientes", "Estimulan en exceso el sistema límbico"], "a": 0, "e": "Los irritantes estimulan las terminaciones del trigémino (dolor, irritación), no el nervio olfatorio. Se usan aromas conocidos (café, vainilla, menta), explorando cada fosa por separado con los ojos cerrados."}, {"q": "La escala de Snellen para valorar la agudeza visual lejana se realiza con el paciente situado a:", "o": ["1 metro", "35-40 centímetros", "6 metros", "10 metros"], "a": 2, "e": "Snellen se hace a 6 metros (20 pies), con cada ojo por separado y sin presionar el ojo tapado. El resultado normal es 20/20 o 1,0. La tarjeta de 35-40 cm es la de Jaeger, para la visión cercana."}, {"q": "La escala de Jaeger se utiliza principalmente para:", "o": ["Valorar la visión cercana y detectar la presbicia", "Detectar el daltonismo", "Medir la presión intraocular", "Valorar el campo visual periférico"], "a": 0, "e": "Jaeger valora la lectura de cerca con una tarjeta a 35-40 cm y detecta la presbicia, que aparece a partir de los 40-45 años. Las discromatopsias se detectan con el test de Ishihara."}, {"q": "Para visualizar con el otoscopio el conducto auditivo externo de un niño menor de 3 años, el pabellón auricular se tracciona:", "o": ["Hacia arriba y hacia atrás", "Hacia arriba y hacia delante", "Hacia delante sin tracción", "Hacia abajo y hacia atrás"], "a": 3, "e": "En el niño pequeño el conducto es corto y recto: se tira hacia abajo y atrás. En el adulto (y a partir de los 3 años) se tira hacia arriba y atrás para rectificar la curvatura del conducto."}, {"q": "En la prueba de Weber, el sonido se lateraliza hacia el oído enfermo cuando existe:", "o": ["Una hipoacusia neurosensorial", "Una hipoacusia de transmisión o conductiva (por ejemplo, un tapón de cerumen)", "Una audición normal", "Una presbiacusia bilateral simétrica"], "a": 1, "e": "En la hipoacusia conductiva el oído afectado no recibe el ruido ambiental que tapa la vibración ósea, y el sonido se oye en él. En la neurosensorial se lateraliza al oído sano."}, {"q": "Un resultado de Rinne positivo indica:", "o": ["Que la vía ósea es mejor que la aérea", "Una hipoacusia de transmisión", "Que la vía aérea es mejor que la ósea, lo que ocurre en la audición normal o en la hipoacusia neurosensorial", "Una perforación timpánica"], "a": 2, "e": "Un Rinne positivo (VA > VO) es fisiológico, pero también aparece en la hipoacusia neurosensorial. Un Rinne negativo (VO > VA) indica hipoacusia de transmisión."}, {"q": "En la exploración del pie diabético con el monofilamento de Semmes-Weinstein:", "o": ["Se usa un monofilamento de 1 gramo aplicado sobre las callosidades", "Se pide al paciente que mire mientras se aplica para que avise", "Se desliza el filamento sobre la piel durante 5 segundos", "Se usa el de 10 gramos (5.07), aplicado en perpendicular hasta que se doble en forma de «C» durante 1 segundo"], "a": 3, "e": "El de 10 g (5.07) es el estándar para la sensibilidad protectora. Se evitan las callosidades y el paciente tiene los ojos cerrados. Si no lo percibe, es un pie de riesgo."}, {"q": "Para explorar la sensibilidad vibratoria en el pie se utiliza un diapasón de:", "o": ["128 Hz", "512 Hz", "1.024 Hz", "64 Hz"], "a": 0, "e": "El diapasón de 128 Hz se apoya en prominencias óseas (cabeza del primer metatarsiano, maléolo). La pérdida de la vibración es un signo precoz de neuropatía. El de 512 Hz se usa para Weber y Rinne."}, {"q": "Los valores normales de la presión intraocular se sitúan entre:", "o": ["5 y 8 mmHg", "10 y 21 mmHg", "25 y 35 mmHg", "40 y 60 mmHg"], "a": 1, "e": "Por encima de 21 mmHg aumenta el riesgo de dañar el nervio óptico (glaucoma). En el glaucoma agudo de ángulo cerrado la PIO puede superar los 50-60 mmHg."}, {"q": "Un paciente acude a urgencias con dolor ocular intenso irradiado a la cabeza, ojo rojo, halos alrededor de las luces, pupila en midriasis media arrefléxica, náuseas y vómitos. Debe sospecharse:", "o": ["Glaucoma agudo de ángulo cerrado", "Catarata madura", "Conjuntivitis bacteriana", "Gastroenteritis con conjuntivitis asociada"], "a": 0, "e": "El cierre brusco del ángulo dispara la PIO. Es una urgencia que se trata con fármacos para bajar la presión e iridotomía con láser. Los vómitos pueden despistar hacia un cuadro digestivo."}, {"q": "En el glaucoma crónico de ángulo abierto, la alteración visual característica es:", "o": ["El escotoma central con metamorfopsia", "El dolor ocular brusco con ojo rojo", "La pérdida progresiva del campo visual periférico («visión en túnel»)", "La visión de destellos y una cortina negra"], "a": 2, "e": "Es el tipo más frecuente: indoloro y silencioso, afecta primero a la periferia. El escotoma central es propio de la DMAE, y los destellos con cortina, del desprendimiento de retina."}, {"q": "En un paciente con glaucoma de ángulo estrecho están contraindicados los colirios:", "o": ["Betabloqueantes", "Análogos de las prostaglandinas", "Lágrimas artificiales", "Midriáticos como la atropina"], "a": 3, "e": "Al dilatar la pupila, el iris se pliega hacia el ángulo y puede cerrarlo, desencadenando un glaucoma agudo. Los betabloqueantes y las prostaglandinas son tratamientos del glaucoma."}, {"q": "Entre las recomendaciones al alta tras una cirugía de cataratas es correcto indicar:", "o": ["Limpiar las secreciones del ángulo externo hacia el interno", "Evitar durante unas semanas los esfuerzos de tipo Valsalva y agacharse doblando la cintura", "Dormir sobre el lado del ojo operado", "Frotar suavemente el ojo si nota arenilla"], "a": 1, "e": "La maniobra de Valsalva y agacharse aumentan la PIO. Se limpia con suero y gasa estéril del ángulo interno al externo, sin frotar ni presionar el ojo, y se duerme boca arriba o sobre el lado no operado con protector."}, {"q": "La visión de destellos luminosos, «moscas volantes» y una sombra en forma de cortina que avanza por el campo visual es típica de:", "o": ["El desprendimiento de retina", "La DMAE seca", "El glaucoma de ángulo abierto", "La catarata"], "a": 0, "e": "Las fotopsias y las miodesopsias son los síntomas iniciales, y el «telón negro» marca la progresión del desprendimiento. Es una urgencia quirúrgica, sobre todo si amenaza la mácula."}, {"q": "Un paciente operado de desprendimiento de retina lleva una burbuja de gas intraocular (SF6). Es imprescindible advertirle que:", "o": ["Debe dormir siempre boca arriba", "Puede viajar en avión si lleva el ojo tapado", "La burbuja desaparece en 24 horas", "No debe volar ni subir a gran altitud mientras quede gas en el ojo"], "a": 3, "e": "Con la altitud baja la presión atmosférica y el gas se expande (ley de Boyle), lo que puede disparar la PIO y causar isquemia y ceguera. Además debe mantener la posición que indique el cirujano, a menudo boca abajo."}, {"q": "El factor de riesgo modificable más importante de la degeneración macular asociada a la edad (DMAE) es:", "o": ["La miopía", "La hipertensión ocular", "El tabaquismo", "El uso de lentes de contacto"], "a": 2, "e": "El tabaco cuadruplica el riesgo y acelera la DMAE, la principal causa de ceguera irreversible en mayores de 65 años en los países desarrollados. Produce pérdida de visión central."}, {"q": "El tratamiento de elección de la DMAE húmeda o exudativa es:", "o": ["Las inyecciones intravítreas periódicas de fármacos anti-VEGF", "La facoemulsificación", "La iridotomía con láser", "Los colirios de timolol"], "a": 0, "e": "Los anti-VEGF frenan la neovascularización. Antes de la punción se instila povidona yodada al 5%, y después se vigila la PIO y la aparición de una endoftalmitis. La forma seca no tiene tratamiento curativo."}, {"q": "En la miopía:", "o": ["El globo ocular es corto y la imagen se forma detrás de la retina", "El globo ocular es largo y la imagen se forma delante de la retina", "El cristalino pierde elasticidad con la edad", "La curvatura de la córnea es irregular"], "a": 1, "e": "El miope ve mal de lejos y tiene más riesgo de desprendimiento de retina. La hipermetropía es un ojo corto (imagen detrás), la presbicia es la pérdida de elasticidad del cristalino y el astigmatismo, una córnea irregular."}, {"q": "La tríada clínica característica de la enfermedad de Ménière es:", "o": ["Otalgia, otorrea y fiebre", "Vértigo posicional breve sin síntomas auditivos", "Hipoacusia de transmisión, autofonía y plenitud ótica", "Vértigo rotatorio, acúfenos e hipoacusia neurosensorial fluctuante"], "a": 3, "e": "Se debe a un hidrops endolinfático. Las crisis duran de 20 minutos a horas, con náuseas, vómitos y nistagmo. El vértigo sin hipoacusia orienta a una neuronitis vestibular, y la autofonía con plenitud, a un tapón."}, {"q": "La intervención educativa más importante de enfermería para prevenir las crisis en la enfermedad de Ménière es:", "o": ["Una dieta rica en potasio", "Aumentar la ingesta de café para mejorar el riego", "Una dieta hiposódica, evitando también el glutamato monosódico", "Una dieta hiperproteica"], "a": 2, "e": "Reducir la sal disminuye la retención de líquidos y la presión endolinfática. También se recomienda limitar la cafeína, el alcohol y el tabaco y beber agua de forma regular a lo largo del día."}, {"q": "Si un paciente tose mientras se le explora o se le lava el conducto auditivo externo, se debe a la estimulación de:", "o": ["La rama auricular del nervio vago (nervio de Arnold)", "El nervio facial", "El nervio trigémino", "El nervio vestibular"], "a": 0, "e": "La rama auricular del vago inerva parte del conducto auditivo externo. Al estimularla se produce un reflejo de tos. Es una pregunta clásica de examen."}, {"q": "La contraindicación absoluta para hacer un lavado de oído para extraer un tapón de cerumen es:", "o": ["Que el tapón sea duro", "La sospecha o confirmación de una perforación de la membrana timpánica", "Que el paciente sea mayor de 65 años", "Que el paciente use audífonos"], "a": 1, "e": "Tampoco se debe lavar si hay cirugía de oído, drenajes transtimpánicos u otitis aguda con supuración: en esos casos se deriva para limpieza en seco. Un tapón duro se ablanda antes con gotas cerumenolíticas durante 2-3 días."}, {"q": "En el lavado ótico el agua debe estar a unos 37 °C porque, si está fría o caliente:", "o": ["Endurece el tapón de cerumen", "Puede quemar la piel del conducto", "Disminuye la eficacia del arrastre", "Produce vértigo, náuseas y nistagmo por un reflejo calórico vestibular"], "a": 3, "e": "La diferencia de temperatura estimula los canales semicirculares, igual que en la prueba calórica. En diabéticos e inmunodeprimidos se usa suero estéril para evitar una otitis externa maligna por Pseudomonas."}, {"q": "Durante el lavado ótico, el chorro de agua debe dirigirse hacia:", "o": ["El centro de la membrana timpánica", "La pared inferior del conducto", "La pared posterosuperior del conducto auditivo externo", "Directamente sobre el tapón con la cánula introducida a fondo"], "a": 2, "e": "El agua choca con la pared, rodea el tapón y lo empuja hacia fuera. Nunca se dirige directamente al tímpano. Si no sale tras 3-4 intentos, se detiene y se mantienen las gotas unos días."}, {"q": "Tras instilar un colirio con posibles efectos sistémicos (por ejemplo, un betabloqueante), la enfermera debe:", "o": ["Presionar suavemente el ángulo interno del ojo (punto lagrimal) durante 30-60 segundos", "Pedir al paciente que parpadee con fuerza varias veces", "Frotar el párpado para repartir el fármaco", "Aplicar a continuación una pomada para que el fármaco no se pierda"], "a": 0, "e": "La oclusión del punto lagrimal impide que el fármaco pase a la mucosa nasal y a la sangre. Entre colirios distintos se esperan 5-10 minutos, la pomada va siempre al final y los envases multidosis se desechan a los 28 días."}, {"q": "Un paciente en tratamiento con timolol en colirio refiere disnea y sibilancias. Lo más probable es que se deba a:", "o": ["Una reacción alérgica local al conservante", "Un glaucoma agudo", "Una sobreinfección respiratoria sin relación con el fármaco", "El efecto sistémico del betabloqueante, contraindicado en asma y EPOC"], "a": 3, "e": "El timolol absorbido por vía nasolagrimal puede causar broncoespasmo, bradicardia e hipotensión. Por eso está contraindicado en asmáticos y en la EPOC y se presiona el lagrimal tras instilarlo."}, {"q": "Ante una salpicadura de un producto cáustico en un ojo, la primera medida de enfermería es:", "o": ["Tapar el ojo con un apósito y avisar al oftalmólogo", "Irrigar de inmediato con suero fisiológico o agua abundante, de forma continua, desde el ángulo interno al externo", "Neutralizar el producto con una solución de pH contrario", "Instilar un anestésico tópico y esperar la valoración"], "a": 1, "e": "El daño químico depende del tiempo de contacto: se lava sin demora con 1-3 litros, evertiendo el párpado superior. El flujo de dentro afuera evita contaminar el ojo sano y el conducto lagrimal."}, {"q": "En la educación sobre el cuidado de los pies de un paciente con neuropatía diabética, respecto a la hidratación se debe recomendar:", "o": ["Aplicar la crema sobre todo entre los dedos", "No usar nunca crema hidratante", "Aplicar crema en la planta y el dorso, evitando siempre los espacios interdigitales", "Mantener los pies en remojo 20 minutos antes de la crema"], "a": 2, "e": "La crema entre los dedos favorece la maceración y las micosis. Además se secan bien los espacios interdigitales, se comprueba el agua con el codo, se inspecciona el pie a diario y se usan calcetines de algodón claros."}, {"q": "En la prueba de Weber de la imagen el sonido se lateraliza hacia el oído enfermo. Esto indica una hipoacusia:", "o": ["Neurosensorial del oído enfermo", "De transmisión (conductiva) del oído enfermo", "Neurosensorial del oído sano", "Es un resultado normal"], "a": 1, "e": "Weber: diapasón de 512 Hz en el vértex. Conductiva (tapón, otitis): se oye más en el oído enfermo (falta el enmascaramiento del ruido ambiental). Neurosensorial: se lateraliza al oído sano.", "img": "img/preguntas/t45-weber.jpg"}]},
46: {"tema": 46, "titulo": "Valoración y cuidados de enfermería a personas con problemas oncológicos. Principales problemas. Procedimientos y técnicas de enfermería", "programa": "Valoración y cuidados de enfermería a personas con problemas oncológicos. Principales problemas (mucositis, neutropenia febril, náuseas y vómitos, dolor, astenia, urgencias oncológicas). Procedimientos: accesos venosos centrales, administración y manipulación de citostáticos, extravasación, residuos y radioterapia.", "preguntas": [{"q": "Según la escala ECOG, un paciente oncológico que pasa en la cama más de la mitad del día y tiene el autocuidado muy limitado tiene un grado:", "o": ["0", "1", "2", "3"], "a": 3, "e": "En el ECOG 2 el paciente está en cama menos del 50% del día y es capaz de cuidarse; en el ECOG 3, más del 50% y con autocuidado limitado. En el ECOG más puntos significa peor estado; en Karnofsky, más porcentaje significa mejor estado."}, {"q": "La escala HADS (Hospital Anxiety and Depression Scale) es adecuada en el paciente oncológico porque:", "o": ["Valora el estado nutricional del anciano", "Excluye los síntomas físicos para que la toxicidad del tratamiento no falsee el resultado", "Mide la intensidad del dolor en pacientes no colaboradores", "Valora el riesgo de úlceras por presión"], "a": 1, "e": "La HADS tiene 14 ítems (7 de ansiedad y 7 de depresión) y no incluye fatiga ni insomnio, que la quimioterapia ya produce. El MNA valora la nutrición en el anciano y PAINAD el dolor en no colaboradores."}, {"q": "Un tumor clasificado como G4 o anaplásico es aquel que:", "o": ["Es indiferenciado: sus células no se parecen al tejido de origen y tiene peor pronóstico", "Está bien diferenciado y crece lentamente", "No ha atravesado la membrana basal", "Tiene metástasis a distancia"], "a": 0, "e": "El grado mira la diferenciación celular al microscopio: G1 es bien diferenciado (mejor pronóstico) y G4, indiferenciado. La extensión (membrana basal, ganglios, metástasis) se expresa con el estadio TNM."}, {"q": "En la clasificación TNM, un carcinoma «in situ» (Tis) se caracteriza por:", "o": ["Tener afectación ganglionar regional", "Corresponder siempre a un estadio IV", "No haber atravesado la membrana basal, por lo que todavía no puede metastatizar", "Ser un tumor que no se puede evaluar"], "a": 2, "e": "El carcinoma in situ no ha invadido el tejido profundo ni tiene acceso a vasos sanguíneos o linfáticos, y es el estadio más curable. M1 indica metástasis (estadio IV) y Tx, que el tumor no se puede evaluar."}, {"q": "Se considera neutropenia febril la presencia de:", "o": ["Leucocitos < 4.000/mm³ y febrícula de 37,5 °C", "Neutrófilos < 500/mm³ (o < 1.000 con descenso previsto) y fiebre > 38,3 °C, o > 38 °C mantenida 1 hora", "Plaquetas < 50.000/mm³ y fiebre", "Neutrófilos < 1.500/mm³ sin fiebre"], "a": 1, "e": "Es una urgencia oncológica por el riesgo de shock séptico. Se pone al paciente en aislamiento protector y se activa el protocolo de inmediato."}, {"q": "Ante un paciente neutropénico que presenta un pico febril, el orden de actuación correcto es:", "o": ["Extraer hemocultivos (periféricos y de cada luz del catéter) y después iniciar antibioterapia empírica en la primera hora", "Iniciar el antibiótico y, si persiste la fiebre a las 24 h, extraer hemocultivos", "Administrar un antitérmico y esperar la evolución", "Retirar el catéter central y cultivar la punta antes de cualquier otra medida"], "a": 0, "e": "Los cultivos se sacan antes del antibiótico para no negativizarlos, pero el antibiótico de amplio espectro no debe retrasarse más allá de la primera hora."}, {"q": "En un paciente con neutropenia y trombopenia por quimioterapia está contraindicado:", "o": ["La higiene bucal con cepillo extrasuave", "El uso de maquinilla eléctrica para afeitarse", "El lavado de manos de las visitas", "Tomar la temperatura por vía rectal o administrar supositorios y enemas"], "a": 3, "e": "La vía rectal puede lesionar la mucosa, favorecer la translocación bacteriana y producir sangrado. Tampoco se permiten plantas o flores en la habitación ni alimentos crudos de riesgo."}, {"q": "En un paciente con mucositis oral que recibe radioterapia de cabeza y cuello, está indicado:", "o": ["Usar colutorios comerciales con alcohol", "Hacer enjuagues con clorhexidina varias veces al día", "Hacer enjuagues frecuentes con suero fisiológico o bicarbonato y usar un cepillo extrasuave", "Suspender la higiene bucal hasta que cure"], "a": 2, "e": "El alcohol y la clorhexidina irritan aún más la mucosa radiada. Se puede usar lidocaína viscosa antes de comer y hay que vigilar las placas blanquecinas de candidiasis."}, {"q": "Para reducir las náuseas inducidas por la quimioterapia, se recomienda:", "o": ["Ofrecer comidas frías o templadas, en pequeñas cantidades y repartidas en varias tomas", "Hacer tres comidas abundantes al día", "Servir la comida muy caliente para estimular el apetito", "Beber abundantes líquidos durante las comidas"], "a": 0, "e": "El olor de la comida caliente favorece la náusea. Los líquidos se toman entre horas y conviene quedarse incorporado tras comer. Los vómitos diferidos (más de 24 h) son típicos del cisplatino."}, {"q": "Un paciente oncológico describe un dolor urente, con sensación de descarga eléctrica y hormigueo. El tratamiento coadyuvante más indicado es:", "o": ["Ibuprofeno a dosis altas", "Pregabalina, gabapentina o amitriptilina", "Butilescopolamina", "Paracetamol en monoterapia"], "a": 1, "e": "Es un dolor neuropático, que responde mal a los opioides y a los AINE. Los antidepresivos tardan 2-4 semanas en hacer efecto analgésico."}, {"q": "Un paciente con el dolor basal controlado presenta dolor intenso cada vez que se le cura la herida. La actuación de enfermería más adecuada es:", "o": ["Aumentar la dosis de los parches de fentanilo", "Retrasar las curas hasta que desaparezca el dolor", "Administrar la medicación de rescate solo si el dolor supera 8 en la EVA", "Administrar la analgesia de rescate pautada unos 15-30 minutos antes de la cura"], "a": 3, "e": "Es un dolor irruptivo incidental, previsible por un desencadenante conocido, así que hay que anticiparse. El dolor que aparece justo antes de la siguiente toma (fallo de final de dosis) obliga en cambio a reajustar la pauta basal."}, {"q": "Respecto a la astenia o fatiga tumoral, es correcto que:", "o": ["Mejora claramente con el reposo absoluto en cama", "Es un síntoma poco frecuente en oncología", "No cede con el descanso y se beneficia del ejercicio aeróbico moderado y de técnicas de conservación de la energía", "Su etiqueta NANDA es «Deterioro de la movilidad física»"], "a": 2, "e": "Es el síntoma más frecuente y la etiqueta NANDA adecuada es «Fatiga». Hay que descartar causas tratables como la anemia. El reposo absoluto desacondiciona al paciente."}, {"q": "La etiqueta diagnóstica NANDA correcta para un paciente con neutropenia profunda tras la quimioterapia es:", "o": ["Riesgo de infección", "Infección", "Neutropenia febril", "Deterioro de la inmunidad"], "a": 0, "e": "«Infección» y «neutropenia febril» son diagnósticos médicos. En el paciente inmunodeprimido, enfermería formula «Riesgo de infección (00004)», con intervenciones de protección contra las infecciones."}, {"q": "Para puncionar un reservorio venoso subcutáneo (Port-a-Cath) se utiliza:", "o": ["Una aguja intramuscular convencional en ángulo de 45°", "Un catéter venoso periférico del 18 G", "Una palomilla metálica estándar", "Una aguja de bisel no cortante tipo Huber o Gripper, introducida a 90° hasta tocar el fondo de la cámara"], "a": 3, "e": "El bisel tangencial separa las fibras de silicona sin cortarlas, de modo que la membrana sigue sellando. Antes se desinfecta con clorhexidina al 2% y se deja secar."}, {"q": "En el manejo de catéteres centrales se recomienda usar jeringas de 10 ml o más porque:", "o": ["Permiten administrar más heparina", "Las jeringas pequeñas generan más presión dentro del catéter y pueden romperlo", "Las jeringas pequeñas no son estériles", "Así se reduce el número de punciones"], "a": 1, "e": "A menor diámetro del émbolo, mayor presión para la misma fuerza. Ante una resistencia nunca se fuerza: si hay un trombo, se usan fibrinolíticos según la prescripción."}, {"q": "El objetivo de pinzar el catéter mientras se inyecta el último medio mililitro de la solución de sellado (cierre con presión positiva) es:", "o": ["Aumentar la concentración de heparina en la punta", "Comprobar que el catéter no está roto", "Evitar el reflujo de sangre hacia la punta del catéter y su oclusión", "Disminuir el riesgo de embolia gaseosa al retirar la aguja"], "a": 2, "e": "Al retirar la jeringa se genera un vacío que aspira sangre hacia la punta, donde se forma un coágulo. Se combina con el lavado pulsátil (push-pause), que arrastra los restos adheridos a la pared."}, {"q": "En un paciente que ya no recibe tratamiento pero conserva el reservorio subcutáneo, el lavado y sellado de mantenimiento se hace, según el protocolo del manual:", "o": ["Cada 4-6 semanas", "Cada 24 horas", "Cada 7 días", "Solo cuando vaya a usarse de nuevo"], "a": 0, "e": "El reservorio inactivo se mantiene permeable con lavado de suero y sellado con heparina diluida cada 4-6 semanas. En el PICC, en cambio, el apósito y los conectores se cambian cada 7 días."}, {"q": "En un PICC con apósito transparente de poliuretano, el apósito y los bioconectores se cambian:", "o": ["Cada 24 horas", "Cada 48 horas", "Cada 30 días", "Cada 7 días, o antes si el apósito está húmedo, sucio o despegado"], "a": 3, "e": "Con apósito de gasa el cambio es cada 48 horas. Antes de usar el conector se frota al menos 15 segundos con clorhexidina-alcohol (scrub the hub). El PICC se fija con dispositivos adhesivos, sin suturas."}, {"q": "Un catéter central está ocluido por un coágulo. Según la prescripción, para desobstruirlo se utiliza:", "o": ["Heparina sódica a alta concentración", "Uroquinasa (fibrinolítico)", "Lavado a presión con una jeringa de 2 ml", "Suero glucosado al 5%"], "a": 1, "e": "La heparina previene la formación del trombo pero no lo disuelve. Nunca se debe forzar con presión, porque el catéter puede romperse o el trombo puede embolizar."}, {"q": "Para prevenir la cistitis hemorrágica que produce la ciclofosfamida se administra:", "o": ["Ácido folínico", "Dexrazoxano", "Mesna, junto con abundante hidratación", "Hialuronidasa"], "a": 2, "e": "La acroleína, un metabolito de la ciclofosfamida y la ifosfamida, irrita la vejiga, y el mesna la neutraliza. El ácido folínico es el rescate del metotrexato y el dexrazoxano protege frente a las antraciclinas."}, {"q": "Un paciente nota sensación de ahogo y hormigueos al beber agua fría de la nevera tras recibir quimioterapia. El fármaco más probable es:", "o": ["Oxaliplatino", "Doxorrubicina", "Bleomicina", "Ciclofosfamida"], "a": 0, "e": "El oxaliplatino causa una neurotoxicidad que desencadena el frío (disestesias en las manos y en la garganta). Se recomiendan bebidas templadas y usar guantes para coger cosas frías."}, {"q": "La cardiotoxicidad irreversible, relacionada con la dosis total acumulada y que obliga a controlar la FEVI, es característica de:", "o": ["El trastuzumab", "La vincristina", "El cisplatino", "La doxorrubicina (antraciclinas)"], "a": 3, "e": "La cardiotoxicidad de las antraciclinas es acumulativa e irreversible. La del trastuzumab es reversible y no depende de la dosis acumulada. Las antraciclinas tiñen la orina de rojo."}, {"q": "El paclitaxel requiere:", "o": ["Administración por vía intratecal", "Protección de la luz y administración en bolo rápido", "Premedicación con corticoide y antihistamínico, y equipos de infusión sin PVC con filtro", "Rescate con ácido folínico a las 24 horas"], "a": 2, "e": "Su diluyente (Cremophor EL) provoca reacciones de hipersensibilidad y libera tóxicos de los plásticos de PVC. Los alcaloides de la vinca, en cambio, son mortales por vía intratecal."}, {"q": "Ante la sospecha de extravasación de un citostático vesicante, la primera actuación es:", "o": ["Retirar el catéter de inmediato y comprimir con fuerza", "Detener la infusión sin retirar el catéter y aspirar por él el fármaco que quede", "Aplicar un vendaje compresivo y continuar la infusión más despacio", "Lavar la vía con 20 ml de suero para arrastrar el fármaco"], "a": 1, "e": "Se para la infusión, se aspira el tóxico por la propia vía y después se retira. Está prohibido comprimir o vendar, porque se extiende el fármaco. Se marca el borde de la zona afectada y se eleva el miembro."}, {"q": "En la extravasación de vincristina, la medida local indicada es:", "o": ["Aplicar calor seco local y hialuronidasa perilesional", "Aplicar frío local y DMSO tópico", "Administrar dexrazoxano intravenoso", "Aplicar compresión y frío intenso continuo"], "a": 0, "e": "En los alcaloides de la vinca y los taxanos interesa dispersar el fármaco: el calor vasodilata y la hialuronidasa abre la matriz tisular. En las antraciclinas se aplica frío (confinar), DMSO y dexrazoxano."}, {"q": "En la limpieza de un derrame de citostáticos se debe:", "o": ["Aplicar lejía pura directamente sobre el derrame", "Recoger los cristales con las manos usando doble guante", "Absorber el líquido presionando con fuerza desde el centro hacia fuera", "Absorber sin presionar desde la periferia al centro, recoger los cristales con pinzas y limpiar con detergente alcalino y agua"], "a": 3, "e": "La lejía puede generar vapores y reacciones. Se usa el kit de derrames con EPI completo (FFP3, gafas, bata, doble guante y calzas) y todo el material va al contenedor de citostáticos."}, {"q": "El método de eliminación final de los residuos citostáticos (clase VI del Decreto 48/2003 de Murcia) es:", "o": ["La esterilización en autoclave", "La desinfección química", "La incineración a alta temperatura", "El depósito en vertedero controlado"], "a": 2, "e": "Solo la incineración por encima de unos 1.000 °C destruye la actividad del fármaco. Los contenedores son herméticos, de un solo uso y nunca se compactan. Los residuos biosanitarios de clase III sí pueden esterilizarse."}, {"q": "En el tratamiento de la hipercalcemia maligna, la actuación correcta es:", "o": ["Administrar tiazidas para forzar la diuresis desde el principio", "Hidratar primero con abundante suero fisiológico y, una vez hidratado el paciente, administrar furosemida", "Restringir los líquidos para evitar sobrecarga", "Administrar suplementos de calcio y vitamina D"], "a": 1, "e": "La hipercalcemia deshidrata por poliuria, así que primero se repone volumen (3-6 L/24 h) y después se da un diurético de asa. Las tiazidas aumentan el calcio. También se administran bisfosfonatos."}, {"q": "En un paciente con síndrome de vena cava superior, una medida de enfermería correcta es:", "o": ["Mantenerlo en Fowler o semi-Fowler y evitar canalizar vías, extraer sangre o tomar la TA en los brazos", "Colocarlo en decúbito supino estricto", "Canalizar dos vías gruesas en las extremidades superiores", "Colocarlo en Trendelenburg para mejorar el retorno venoso"], "a": 0, "e": "La compresión de la cava impide el retorno venoso de la mitad superior del cuerpo (disnea, ingurgitación yugular, edema en esclavina). Las punciones se hacen en los miembros inferiores. La compresión medular, en cambio, exige decúbito supino."}, {"q": "En un paciente que recibe radioterapia externa, respecto a las cremas hidratantes en la zona irradiada, se debe recomendar:", "o": ["Aplicar crema abundante justo antes de cada sesión para proteger la piel", "No usar ninguna crema durante todo el tratamiento", "Aplicar alcohol o colonia para refrescar la piel", "Aplicarlas después de la sesión y nunca en las 2-3 horas previas"], "a": 3, "e": "La piel debe entrar en la sesión limpia y seca: la crema previa aumenta la dosis en la piel (efecto bolus) y la quemadura. Se lava con agua tibia y jabón neutro y se seca a toques. En la teleterapia el paciente no es radiactivo."}]},
47: {"tema": 47, "titulo": "Valoración y cuidados de enfermería a personas con problemas endocrinológicos. Diabetes. Otros problemas. Procedimientos y técnicas de enfermería", "programa": "Valoración y cuidados de enfermería a personas con problemas endocrinológicos. Diabetes mellitus: diagnóstico, complicaciones agudas y crónicas, pie diabético, insulinoterapia y educación. Otros problemas: tiroides, suprarrenales, paratiroides e hipófisis. Procedimientos y técnicas de enfermería.", "preguntas": [{"q": "Es criterio diagnóstico de diabetes mellitus, confirmado en un segundo día:", "o": ["Una glucemia plasmática en ayunas igual o superior a 126 mg/dl", "Una glucemia en ayunas igual o superior a 100 mg/dl", "Una HbA1c igual o superior al 5,7%", "Una glucemia a las 2 h de la SOG igual o superior a 140 mg/dl"], "a": 0, "e": "Los criterios son glucemia basal ≥ 126 mg/dl, SOG con 75 g a las 2 h ≥ 200, HbA1c ≥ 6,5% o glucemia al azar ≥ 200 con síntomas (esta última no necesita confirmación). Los valores de 100, 5,7% y 140 corresponden a prediabetes."}, {"q": "La hemoglobina glucosilada (HbA1c) refleja el control glucémico de:", "o": ["Los últimos 7 días", "Las últimas 2-3 semanas", "Los últimos 2-3 meses", "El último año"], "a": 2, "e": "Se relaciona con la vida media del hematíe (unos 90-120 días). En el seguimiento del diabético se determina cada 3-6 meses. No sirve para la reclasificación posparto."}, {"q": "Sobre el test de O'Sullivan para el cribado de la diabetes gestacional, es correcto que:", "o": ["Requiere un ayuno de 8-14 horas", "Se administran 100 g de glucosa y se extrae sangre a las 3 horas", "Un resultado positivo confirma el diagnóstico de diabetes gestacional", "Se administran 50 g de glucosa sin necesidad de ayuno y se extrae sangre a la hora; es positivo si ≥ 140 mg/dl"], "a": 3, "e": "Se hace de forma universal en la semana 24-28. Durante la hora de espera la gestante permanece en reposo y sin fumar. Si es positivo, se confirma con una SOG de 100 g."}, {"q": "En la sobrecarga oral con 100 g de glucosa en la gestante, el diagnóstico de diabetes gestacional se establece cuando:", "o": ["Un solo valor está alterado", "Dos o más valores están alterados", "La glucemia basal supera los 85 mg/dl", "Los cuatro valores están alterados"], "a": 1, "e": "Con un solo valor alterado se habla de intolerancia y se repite la prueba. Se determina la glucemia basal y a la 1, 2 y 3 horas. En la estrategia de un paso con 75 g (IADPSG), en cambio, basta un solo valor."}, {"q": "Un paciente obeso presenta un oscurecimiento aterciopelado de la piel del cuello que no desaparece al lavarse. Este signo sugiere:", "o": ["Enfermedad de Addison", "Síndrome de Cushing", "Hipotiroidismo", "Resistencia a la insulina (acantosis nigricans)"], "a": 3, "e": "La acantosis nigricans en cuello y axilas es un marcador de resistencia a la insulina y de riesgo de DM2. La hiperpigmentación del Addison aparece en pliegues palmares, cicatrices y mucosas."}, {"q": "Un paciente diabético consciente y capaz de tragar tiene una glucemia capilar de 55 mg/dl. La actuación correcta es:", "o": ["Darle 15 g de hidratos de carbono de absorción rápida y repetir la glucemia a los 15 minutos", "Administrar glucagón intramuscular", "Darle un bocadillo de pan integral", "Administrar insulina rápida y esperar"], "a": 0, "e": "Es la regla de los 15: si la glucemia sigue por debajo de 70 mg/dl se repite el ciclo. Cuando se normaliza, se dan hidratos de absorción lenta para evitar que recaiga. El glucagón se reserva para el paciente inconsciente."}, {"q": "Ante un diabético inconsciente por hipoglucemia en su domicilio, la actuación indicada es:", "o": ["Darle zumo azucarado poco a poco", "Ponerle azúcar debajo de la lengua", "Administrar glucagón IM o SC y colocarlo en posición lateral de seguridad", "Esperar a que recupere la conciencia para darle hidratos"], "a": 2, "e": "Sin conciencia está contraindicada la vía oral por riesgo de broncoaspiración. El glucagón se reconstituye antes de inyectarlo y puede producir vómitos, de ahí la PLS. Al despertar se le dan hidratos de carbono por boca."}, {"q": "El glucagón puede ser ineficaz para tratar una hipoglucemia grave en un paciente:", "o": ["Con diabetes tipo 1 joven", "Alcohólico crónico o con hepatopatía avanzada", "Que ha hecho ejercicio intenso", "Que está en tratamiento con insulina basal"], "a": 1, "e": "El glucagón actúa liberando el glucógeno del hígado (glucogenólisis). Si no hay reservas hepáticas, no hay glucosa que liberar y es necesario administrar glucosa intravenosa hipertónica."}, {"q": "Un joven con diabetes tipo 1 llega a urgencias con respiración rápida y profunda, aliento afrutado, vómitos y dolor abdominal. Debe sospecharse:", "o": ["Cetoacidosis diabética", "Estado hiperosmolar hiperglucémico", "Hipoglucemia grave", "Acidosis láctica por metformina"], "a": 0, "e": "La respiración de Kussmaul compensa la acidosis metabólica, y el olor a manzana o quitaesmalte se debe a la acetona. La cetoacidosis aparece por un déficit absoluto de insulina, a menudo tras suspenderla durante una enfermedad."}, {"q": "El estado hiperosmolar hiperglucémico se caracteriza por:", "o": ["Acidosis metabólica grave con cetonuria intensa", "Aparecer sobre todo en niños con diabetes tipo 1", "Glucemias en torno a 250 mg/dl con respiración de Kussmaul", "Glucemia muy alta (> 600 mg/dl), deshidratación profunda y alteración de la conciencia, sin cetosis significativa"], "a": 3, "e": "Es típico del anciano con DM2. La poca insulina que conserva frena la cetogénesis, pero no la hiperglucemia, que provoca una diuresis osmótica intensa. Puede simular un ictus."}, {"q": "Ante un paciente en cetoacidosis diabética, la primera medida terapéutica es:", "o": ["La perfusión de insulina rápida intravenosa", "La administración de bicarbonato", "La rehidratación intravenosa con suero salino isotónico al 0,9%", "La administración de insulina NPH subcutánea"], "a": 2, "e": "Lo primero es restaurar la volemia. Después, o a la vez, se repone potasio y se inicia la insulina regular en perfusión IV. Se coloca sonda vesical para medir la diuresis horaria."}, {"q": "¿Qué tipo de insulina puede administrarse por vía intravenosa en perfusión continua?", "o": ["La insulina NPH", "La insulina rápida o regular", "La insulina glargina", "Las insulinas premezcladas"], "a": 1, "e": "Solo la insulina regular (humana rápida) se usa por vía IV. Las insulinas intermedias, basales y premezcladas son exclusivamente subcutáneas."}, {"q": "En el tratamiento de la cetoacidosis, el potasio debe reponerse de forma precoz porque:", "o": ["El paciente siempre llega con hiperpotasemia grave", "El potasio mejora la acción de la insulina", "Previene la aparición de cetonas", "La insulina y la corrección de la acidosis introducen el potasio en las células, con riesgo de hipopotasemia y arritmias"], "a": 3, "e": "Aunque el potasio inicial sea normal o alto (la acidosis lo saca de las células), en cuanto se pone insulina entra en la célula y cae en sangre. Por eso se monitoriza y se repone KCl desde el principio."}, {"q": "En la exploración de la sensibilidad protectora del pie diabético con monofilamento:", "o": ["Se usa el de 10 g, aplicado en perpendicular hasta que se doble, y nunca sobre callosidades o úlceras", "Se usa el de 5 g, aplicado sobre las zonas con más callo", "Se arrastra el filamento por la planta durante 5 segundos", "Se explora únicamente el dorso del pie"], "a": 0, "e": "Se exploran las cabezas del 1.º, 3.º y 5.º metatarsiano y los pulpejos, con el paciente con los ojos cerrados. La hiperqueratosis invalida la prueba. La sensibilidad vibratoria se valora con un diapasón de 128 Hz."}, {"q": "Un pie diabético caliente, con pulsos pedios presentes, una úlcera indolora en la cabeza del primer metatarsiano rodeada de callo, corresponde a:", "o": ["Un pie isquémico", "Una gangrena localizada", "Un pie neuropático", "Una trombosis venosa profunda"], "a": 2, "e": "El pie neuropático conserva los pulsos, es indoloro y ulcera en las zonas de presión plantar. El isquémico es frío y pálido, no tiene pulsos, duele y ulcera en zonas distales como los dedos y los bordes."}, {"q": "Según la clasificación de Wagner, una úlcera profunda del pie diabético con osteomielitis corresponde al grado:", "o": ["0", "1", "2", "3"], "a": 3, "e": "Grado 2: úlcera profunda que llega a tendón o cápsula sin afectar el hueso. Grado 3: profunda con absceso u osteomielitis. Grados 4 y 5: gangrena localizada y extensa."}, {"q": "En la educación para el cuidado de los pies de un paciente diabético, respecto al corte de uñas se recomienda:", "o": ["Cortarlas en forma curva, apurando las esquinas", "Cortarlas rectas y limar los bordes", "Cortarlas con cuchilla después del baño", "No cortarlas nunca y esperar a que se rompan"], "a": 1, "e": "El corte curvo favorece la uña encarnada. Tampoco se deben usar callicidas ni cuchillas en los callos (derivar al podólogo). El agua se comprueba con el codo o un termómetro."}, {"q": "La zona de inyección subcutánea de insulina con absorción más rápida es:", "o": ["El abdomen, respetando unos 5 cm alrededor del ombligo", "La cara anterolateral del muslo", "El cuadrante superoexterno de la nalga", "El deltoides"], "a": 0, "e": "El orden de velocidad es abdomen > brazos > muslos > nalgas. Las zonas más lentas son adecuadas para las insulinas basales. La rotación evita la lipohipertrofia, que hace la absorción errática."}, {"q": "Sobre la conservación de la insulina, es correcto que:", "o": ["Las plumas sin empezar pueden guardarse en el congelador para que duren más", "La pluma en uso debe guardarse siempre en la nevera", "La pluma en uso puede mantenerse a temperatura ambiente, protegida del calor y la luz, durante unas 4 semanas", "Una vez abierta, la insulina caduca a las 48 horas"], "a": 2, "e": "Las plumas sin empezar se guardan en la nevera a 2-8 °C, nunca congeladas (la proteína se desnaturaliza y hay que desecharla). A temperatura ambiente la inyección duele menos."}, {"q": "Los sistemas de monitorización continua de glucosa (sensores) miden la glucosa en:", "o": ["La sangre capilar", "La sangre venosa", "El sudor", "El líquido intersticial"], "a": 3, "e": "Como miden en el líquido intersticial, van con un retraso de unos 5-10 minutos respecto a la sangre. Si la glucosa baja muy deprisa, se confirma con una glucemia capilar. El tiempo en rango objetivo es 70-180 mg/dl."}, {"q": "Un paciente insulinizado presenta hiperglucemias al despertar. Se le mide la glucemia a las 3:00 h y se detecta una hipoglucemia. Se trata de:", "o": ["El fenómeno del alba", "El efecto Somogyi", "Un estado hiperosmolar", "Una resistencia a la insulina nocturna"], "a": 1, "e": "El efecto Somogyi es una hiperglucemia de rebote tras una hipoglucemia nocturna por exceso de insulina: hay que reducir la dosis nocturna. En el fenómeno del alba la glucemia de las 3:00 h es normal o alta, y la dosis se aumenta o se retrasa."}, {"q": "La enfermera debe indicar que la insulina ultrarrápida (lispro, aspart) se administre:", "o": ["Justo antes de empezar a comer", "Una hora antes de la comida", "Al acostarse", "Dos horas después de la comida"], "a": 0, "e": "Empieza a actuar en 5-15 minutos. La insulina regular humana tarda 30-60 minutos, por lo que se pone unos 30 minutos antes de comer."}, {"q": "Sobre la administración de levotiroxina, se debe educar al paciente para que:", "o": ["La tome con el desayuno para evitar molestias gástricas", "La tome junto con el suplemento de hierro o calcio", "La tome por la noche con un vaso de leche", "La tome en ayunas, solo con agua, y espere antes de desayunar"], "a": 3, "e": "Su absorción es delicada: se espera antes del desayuno (el manual indica 60 minutos) y se separa al menos 4 horas del hierro, el calcio y los antiácidos. Hay que vigilar signos de sobredosis como taquicardia, insomnio o temblor."}, {"q": "Un paciente en tratamiento con tiamazol consulta por fiebre alta repentina y dolor de garganta intenso. Hay que sospechar:", "o": ["Un hipotiroidismo iatrogénico", "Una tormenta tiroidea", "Una agranulocitosis por el antitiroideo", "Una reacción alérgica leve"], "a": 2, "e": "La agranulocitosis es el efecto adverso más grave de los antitiroideos. Se debe instruir al paciente para que, ante fiebre u odinofagia, acuda de inmediato a urgencias para hacerse un hemograma."}, {"q": "En un paciente con tormenta tiroidea e hipertermia de 41 °C, está contraindicado administrar:", "o": ["Medidas físicas de enfriamiento", "Ácido acetilsalicílico (salicilatos)", "Betabloqueantes", "Sueroterapia intravenosa"], "a": 1, "e": "Los salicilatos desplazan a las hormonas tiroideas de sus proteínas de transporte y aumentan la fracción libre activa. En el coma mixedematoso, en cambio, lo contraindicado es el recalentamiento activo rápido."}, {"q": "Un paciente recién operado de tiroidectomía refiere hormigueo alrededor de los labios. La enfermera debe sospechar:", "o": ["Una hipocalcemia por lesión de las glándulas paratiroides, y comprobar el signo de Chvostek", "Una lesión del nervio laríngeo recurrente", "Una crisis tirotóxica", "Un efecto normal de la anestesia"], "a": 0, "e": "Las paratiroides están pegadas al tiroides y pueden lesionarse en la cirugía. Chvostek: espasmo facial al percutir el nervio facial. Trousseau: espasmo del carpo al inflar el manguito. El estridor o la disfonía orientan al nervio recurrente o al edema."}, {"q": "En la enfermedad de Addison es característico encontrar:", "o": ["Hipernatremia e hipopotasemia", "Hiperglucemia mantenida", "Obesidad troncal y estrías violáceas", "Hiponatremia, hiperpotasemia e hiperpigmentación cutánea"], "a": 3, "e": "La falta de aldosterona hace perder sodio y retener potasio, y el exceso de ACTH estimula los melanocitos. Además hay tendencia a la hipoglucemia y a la hipotensión. La obesidad troncal con estrías es propia del Cushing."}, {"q": "Ante una crisis addisoniana con shock, la actuación de enfermería prioritaria es administrar:", "o": ["Noradrenalina como único tratamiento", "Levotiroxina intravenosa", "Hidrocortisona intravenosa en bolo (habitualmente 100 mg) y sueros isotónicos", "Furosemida intravenosa"], "a": 2, "e": "La crisis se desencadena por infecciones, cirugía o la suspensión brusca de los corticoides. Sin cortisol, el shock no responde a vasoactivos. No se debe esperar a la confirmación analítica."}, {"q": "En el control preoperatorio de la hipertensión de un feocromocitoma:", "o": ["Se empieza con betabloqueantes", "Se inicia primero el bloqueo alfa-adrenérgico y después, si hace falta, el beta", "Se recomienda palpar el abdomen para localizar el tumor", "No se trata la tensión hasta la cirugía"], "a": 1, "e": "Un betabloqueante sin bloqueo alfa previo deja sin oposición la vasoconstricción alfa y desencadena una crisis hipertensiva. Palpar el abdomen puede liberar catecolaminas. Tras la cirugía se vigilan la hipotensión y la hipoglucemia."}, {"q": "El cuidado de enfermería prioritario en un paciente con síndrome de secreción inadecuada de ADH (SIADH) es:", "o": ["La restricción hídrica (menos de 800-1.000 ml/día)", "Asegurar una ingesta abundante de agua", "Administrar desmopresina", "Administrar suero glucosado al 5% en perfusión rápida"], "a": 0, "e": "En el SIADH se retiene agua y aparece una hiponatremia dilucional, con riesgo de edema cerebral (vigilancia neurológica). En la diabetes insípida ocurre lo contrario: poliuria masiva, hay que asegurar el agua y se da desmopresina."}, {"q": "Al percutir delante del trago, sobre el nervio facial, se contrae la comisura bucal del mismo lado (signo de Chvostek). Indica:", "o": ["Hipercalcemia", "Hipocalcemia", "Hiperpotasemia", "Hiponatremia"], "a": 1, "e": "Chvostek y Trousseau (espasmo carpopedal al inflar el manguito) son signos de hipocalcemia, típica tras tiroidectomía por lesión de las paratiroides. Riesgo de laringoespasmo: gluconato cálcico IV.", "img": "img/preguntas/t47-chvostek.jpg"}, {"q": "En el esquema de zonas de inyección de insulina, la zona coloreada en verde (abdomen) es la de absorción:", "o": ["Más lenta", "Intermedia", "Nula", "Más rápida"], "a": 3, "e": "Velocidad de absorción: abdomen (rápida) > brazos > muslos > nalgas (lenta). Rotar dentro de la misma zona, separar los pinchazos ≈ 1 cm y respetar 2-3 cm alrededor del ombligo para evitar lipodistrofias.", "img": "img/preguntas/t47-insulina.jpg"}]},
48: {"tema": 48, "titulo": "Conceptos de urgencia y emergencia. Sistemas de respuesta a la urgencia y emergencia. Clasificación de pacientes en urgencias", "programa": "Conceptos de urgencia y emergencia. Sistemas de respuesta a la urgencia y emergencia (Gerencia 061 de la Región de Murcia). Clasificación de pacientes en urgencias: RAC, sistemas de triaje estructurado (ESI, Manchester, SET-MAT) y triaje en incidentes de múltiples víctimas.", "preguntas": [{"q": "Según la OMS, la urgencia se define como la aparición fortuita de un problema de causa diversa y gravedad variable que:", "o": ["Pone en peligro inminente la vida del paciente", "Requiere siempre traslado en soporte vital avanzado", "Genera la conciencia de una necesidad inminente de atención en quien lo sufre o en su familia", "Compromete la viabilidad de un órgano"], "a": 2, "e": "La definición de la OMS tiene un fuerte componente subjetivo: la percepción del paciente o la familia. El riesgo vital inminente o para la viabilidad de un órgano define la emergencia."}, {"q": "Se considera emergencia la situación que:", "o": ["Pone en peligro inminente la vida del paciente o la viabilidad de un órgano y requiere atención en minutos", "El paciente percibe como urgente aunque no tenga riesgo", "Puede atenderse en las siguientes 24 horas", "Se atiende en atención primaria en horario ordinario"], "a": 0, "e": "En la emergencia el tiempo es el principal determinante del pronóstico. Son ejemplos la parada cardiorrespiratoria, el infarto, el ictus, la anafilaxia y la hemorragia exanguinante."}, {"q": "La norma que incluye en la cartera de servicios comunes del SNS la atención de urgencia, con la clasificación de pacientes (triaje) para priorizar la asistencia, es:", "o": ["La Ley 14/1986, General de Sanidad", "El Real Decreto 1030/2006", "La Ley 44/2003, de Ordenación de las Profesiones Sanitarias", "El Real Decreto 1093/2010"], "a": 1, "e": "El anexo IV del RD 1030/2006 regula la atención urgente las 24 horas, dentro y fuera de los centros: atención telefónica y regulación, evaluación inicial, triaje, procedimientos y transporte sanitario."}, {"q": "Según la Ley 41/2002, se pueden realizar intervenciones clínicas indispensables sin el consentimiento del paciente cuando:", "o": ["El paciente lo rechaza por escrito", "El médico lo considera conveniente por razones organizativas", "Se trata de un paciente mayor de 65 años", "Existe un riesgo inmediato grave para su integridad física o psíquica y no es posible conseguir su autorización"], "a": 3, "e": "Tienen que darse ambos requisitos a la vez. Cuando las circunstancias lo permitan, se consulta a los familiares o personas vinculadas de hecho con el paciente."}, {"q": "En la Región de Murcia, la Unidad Médica de Emergencias (UME) es:", "o": ["Un recurso móvil de soporte vital avanzado, con médico, enfermero y técnico en emergencias sanitarias", "Un centro de salud que abre por las tardes", "Un consultorio situado en una pedanía aislada", "Un recurso de transporte sanitario no asistido"], "a": 0, "e": "La UME atiende in situ las emergencias con riesgo vital. Los SUAP son dispositivos fijos de urgencias extrahospitalarias, y los PAC y PEA dan cobertura en comarcas periféricas y zonas aisladas."}, {"q": "El objetivo principal del triaje en un servicio de urgencias es:", "o": ["Emitir un diagnóstico médico de sospecha", "Ordenar a los pacientes por orden de llegada", "Gestionar el riesgo clínico priorizando la atención según la urgencia fisiológica", "Asignar la atención según las camas disponibles"], "a": 2, "e": "El triaje no diagnostica: clasifica para que los pacientes que necesitan medidas salvavidas sean atendidos de inmediato y el resto espere un tiempo seguro. La disponibilidad de recursos no determina el nivel."}, {"q": "Durante el triaje, una mujer con lesiones que no encajan con lo que relata acude con un acompañante que responde por ella y no la deja hablar. La actuación de enfermería más adecuada es:", "o": ["Preguntarle directamente delante del acompañante si sufre malos tratos", "Pedir al acompañante de forma tajante que abandone el servicio", "Asignarle el nivel más bajo y que la valore el médico", "Separar al acompañante con un pretexto clínico rutinario (ECG, constantes, normas del box) y entrevistarla a solas"], "a": 3, "e": "El box de triaje debe ser un espacio seguro. Nunca se confronta al presunto agresor. Tras la entrevista a solas se activan los protocolos institucionales y se emite el parte de lesiones si procede."}, {"q": "Según los estándares de SEMES, el box de triaje debe tener una superficie mínima de:", "o": ["3 m²", "6 m²", "12 m²", "20 m²"], "a": 1, "e": "El mínimo es de 6 m² (óptimo, 9 m²). El box se sitúa a la entrada del servicio, con contacto visual con admisión y la sala de espera, y dispone de camilla, silla de ruedas, ordenador, monitor y glucómetro."}, {"q": "Entre los indicadores de calidad del triaje (SEMES), el índice de fugas de pacientes ya clasificados que se marchan sin ser atendidos debe ser:", "o": ["Inferior al 2%", "Inferior al 10%", "Inferior al 15%", "Inferior al 25%"], "a": 0, "e": "Las fugas antes del triaje deben ser inferiores al 4% y las de pacientes ya triados, inferiores al 2%. El tiempo desde la llegada hasta el inicio del triaje debe ser menor de 10 minutos en al menos el 85% de los casos."}, {"q": "Es una intervención propia del triaje avanzado de enfermería:", "o": ["Pautar morfina intravenosa a un paciente con dolor intenso", "Diagnosticar una fractura de radio", "Administrar paracetamol oral según protocolo a un paciente con dolor moderado", "Dar el alta a un paciente con una cefalea leve"], "a": 2, "e": "El triaje avanzado permite actuaciones protocolizadas antes de la valoración médica: analgesia oral, antitérmicos, petición de radiografías, inmovilización con frío o tira de orina. Pautar morfina IV o diagnosticar exceden sus competencias."}, {"q": "Para prevenir agresiones de un paciente agitado en el box de triaje, la enfermera debe:", "o": ["Cerrar la puerta del box para evitar que el paciente se escape", "Acercarse a menos de 50 cm para transmitir confianza", "Contradecir sus ideas delirantes para reorientarle", "Situarse siempre más cerca de la salida que el paciente"], "a": 3, "e": "La vía de escape debe quedar libre. Se mantiene una distancia de 1-2 metros, una postura no amenazante y un tono sereno. Si hay riesgo inminente de agresión, se interrumpe el triaje y se activa el protocolo de paciente violento."}, {"q": "El Índice de Severidad de Emergencia (ESI) se caracteriza por:", "o": ["Basarse en 52 diagramas de flujo de motivos de consulta", "No fijar tiempos de espera concretos y clasificar a los pacientes estables según los recursos que se prevé que consumirán", "Exigir un programa informático llamado e-PAT", "Tener solo tres niveles de prioridad"], "a": 1, "e": "El ESI estadounidense tiene 5 niveles y se basa en la agudeza (niveles 1 y 2) y en la previsión de recursos (niveles 3 a 5). Los 52 diagramas son del Manchester y el e-PAT es el software del SET."}, {"q": "Según el ESI, un paciente estable que precisará una analítica de sangre y orina y una radiografía de tórax se clasifica en el nivel:", "o": ["3, porque se prevén dos recursos", "4, porque se prevé un solo recurso", "5, porque no consume recursos", "2, porque es de alto riesgo"], "a": 0, "e": "La analítica de sangre y la de orina cuentan juntas como un solo recurso de laboratorio, y la radiografía es otro: en total dos, que corresponden al nivel 3. Un recurso es el nivel 4 y ninguno, el nivel 5."}, {"q": "En el sistema ESI, NO se considera un recurso:", "o": ["La radiografía", "La medicación intravenosa", "La sutura de una laceración compleja", "La administración de medicación por vía oral"], "a": 3, "e": "Tampoco son recursos la historia y la exploración, la férula o el vendaje simple, las muletas, la vacuna antitetánica, la cura simple, retirar puntos ni hacer una receta."}, {"q": "En el ESI, se considera intervención salvavidas inmediata que asigna el nivel 1:", "o": ["Realizar un TAC urgente", "Canalizar una vía venosa periférica", "La desfibrilación", "Extraer una analítica completa"], "a": 2, "e": "También lo son la intubación, la ventilación asistida, el marcapasos externo, la descompresión torácica con aguja, los fluidos masivos y fármacos como la adrenalina, la atropina, la adenosina o la naloxona. El TAC, la vía periférica y la analítica no lo son."}, {"q": "El Sistema de Triaje de Manchester se estructura en:", "o": ["52 diagramas de flujo basados en el motivo de consulta, con discriminadores generales y específicos", "Más de 600 motivos de consulta gestionados con el software e-PAT", "La previsión del número de recursos", "Tres colores: rojo, amarillo y verde"], "a": 0, "e": "Una vez elegido el diagrama, se recorren los discriminadores de arriba abajo, empezando por el nivel más grave, y se asigna el nivel del primero que se cumple. 49 de los 52 diagramas sirven también para pediatría."}, {"q": "En el Sistema de Triaje de Manchester, el nivel 2 (muy urgente) se asocia al color:", "o": ["Rojo, con atención inmediata", "Naranja, con un tiempo máximo de 10 minutos", "Amarillo, con un tiempo máximo de 60 minutos", "Verde, con un tiempo máximo de 120 minutos"], "a": 1, "e": "Los niveles del Manchester son: rojo (inmediato), naranja (10 min), amarillo (60 min), verde (120 min) y azul (240 min)."}, {"q": "En el Sistema de Triaje de Manchester, el color azul corresponde al nivel:", "o": ["2, muy urgente, 10 minutos", "3, urgente, 60 minutos", "4, estándar, 120 minutos", "5, no urgente, 240 minutos"], "a": 3, "e": "Es una trampa clásica: el nivel 4 es verde y el nivel 5 es azul. Se suelen intercambiar en las opciones de respuesta."}, {"q": "El Sistema Español de Triaje (SET), basado en el Modelo Andorrano, se caracteriza por:", "o": ["No tener tiempos de atención asociados", "Basarse en el número de recursos previstos", "Requerir un programa informático de ayuda a la decisión (e-PAT)", "Tener solo 3 niveles de prioridad"], "a": 2, "e": "El SET-MAT, recomendado por SEMES, cruza cientos de motivos de consulta con discriminantes como las constantes, el dolor o el nivel de conciencia, lo que hace imprescindible el software e-PAT."}, {"q": "La fiabilidad de un sistema de triaje, entendida como la concordancia entre dos profesionales que clasifican al mismo paciente, se mide con:", "o": ["El índice kappa", "La sensibilidad", "El valor predictivo positivo", "El índice de Barthel"], "a": 0, "e": "Un kappa de 0,6-0,8 indica buena concordancia y por encima de 0,8, excelente. La validez, en cambio, se refiere a si el sistema clasifica bien la gravedad real (ingresos, recursos, mortalidad)."}, {"q": "El sistema de triaje que, según el manual, presenta una tasa relevante de infratriaje en mayores de 65 años por no captar bien las presentaciones atípicas es:", "o": ["El ESI", "El Manchester", "El SET-MAT", "El CTAS"], "a": 1, "e": "En el anciano son frecuentes los infartos indoloros o las sepsis sin fiebre, que el algoritmo del Manchester detecta peor. El infratriaje (asignar menos gravedad de la real) es el principal riesgo para la seguridad del paciente."}, {"q": "En un incidente de múltiples víctimas, el principio que rige la clasificación es:", "o": ["Atender primero siempre al más grave, aunque no sea recuperable", "Atender por orden de llegada de los equipos", "Iniciar RCP en todas las víctimas en parada", "Conseguir el mayor beneficio para el mayor número de víctimas con los recursos disponibles"], "a": 3, "e": "En las catástrofes se aplica una filosofía utilitarista: no se gastan recursos ni tiempo en maniobras fútiles. En el primer triaje no se hace RCP."}, {"q": "Según el método START, una víctima de un accidente múltiple que puede caminar por sí misma se clasifica como:", "o": ["Rojo", "Amarillo", "Verde", "Negro"], "a": 2, "e": "La marcha autónoma es el primer paso: si camina, es verde y no se valora nada más en ese momento. Se agrupa a estas víctimas en un punto de reunión seguro."}, {"q": "Aplicando el método START, un adulto que no respira, que sigue sin respirar tras la apertura manual de la vía aérea, se clasifica como:", "o": ["Negro", "Rojo", "Amarillo", "Verde"], "a": 0, "e": "Si respira tras abrir la vía aérea, se clasifica como rojo; si no, negro. En el adulto no se hacen ventilaciones de rescate en el primer triaje. En el niño (JumpSTART) se palpa el pulso y, si lo tiene, se dan 5 ventilaciones."}, {"q": "Según el método START, una víctima que no camina y respira a 34 respiraciones por minuto se clasifica como:", "o": ["Verde", "Amarillo", "Negro", "Rojo"], "a": 3, "e": "Una frecuencia respiratoria superior a 30 rpm indica rojo. También son rojo un relleno capilar de más de 2 segundos, la ausencia de pulso radial y no obedecer órdenes sencillas."}, {"q": "En el método START, una víctima que no camina, respira a 20 rpm, tiene un relleno capilar inferior a 2 segundos y obedece órdenes sencillas se clasifica como:", "o": ["Rojo", "Amarillo", "Verde", "Negro"], "a": 1, "e": "No camina, pero la respiración, la perfusión y el estado mental son adecuados: su atención puede demorarse algunas horas sin riesgo vital inminente."}, {"q": "En el triaje pediátrico de catástrofes (JumpSTART), ante un niño que no respira tras abrir la vía aérea pero tiene pulso palpable, se debe:", "o": ["Clasificarlo directamente como negro", "Clasificarlo como amarillo", "Administrar 5 ventilaciones de rescate y reevaluar", "Iniciar compresiones torácicas"], "a": 2, "e": "La parada infantil suele ser de origen respiratorio. Si respira tras las 5 ventilaciones, es rojo; si no, negro. En el niño también es rojo una frecuencia respiratoria menor de 15 o mayor de 45 rpm."}, {"q": "En la sectorización de un incidente de múltiples víctimas, el Puesto Médico Avanzado (PMA) se sitúa en:", "o": ["La zona templada o área de socorro", "La zona caliente o área de rescate", "La zona fría o área base", "El hospital de referencia"], "a": 0, "e": "En el PMA se hace el segundo triaje y se estabiliza a los pacientes. En la zona caliente se hace el primer triaje y el rescate, y en la zona fría están el puesto de mando y la noria de evacuación con las ambulancias."}, {"q": "En el método de triaje SHORT, la «T» (taponar hemorragias):", "o": ["Es el último paso y solo se aplica a las víctimas clasificadas como rojas", "Obliga a reclasificar a la víctima como roja", "Solo puede hacerla personal médico", "Se aplica en cualquier momento al detectar una hemorragia exanguinante y no cambia la clasificación"], "a": 3, "e": "SHORT es un método español pensado también para intervinientes no sanitarios: Sale caminando (verde), Habla y Obedece (amarillo), Respira (rojo; si no respira tras abrir la vía aérea, negro) y Taponar en cualquier momento."}, {"q": "En una transferencia con la técnica SAER, la información «es hipertenso, toma anticoagulantes y es alérgico a la penicilina» corresponde al apartado:", "o": ["Situación", "Antecedentes", "Evaluación", "Recomendación"], "a": 1, "e": "SAER (SBAR): Situación (qué ocurre ahora), Antecedentes (historia relevante), Evaluación (constantes y estado actual) y Recomendación (qué propone o necesita el paciente)."}]},
49: {"tema": 49, "titulo": "Valoración y cuidados de enfermería ante situaciones críticas. Politraumatizados, quemados, shock, intoxicaciones. Otras situaciones críticas", "programa": "Valoración y cuidados de enfermería ante situaciones críticas: politraumatizados, quemados, shock e intoxicaciones. Otras situaciones críticas: síndrome coronario agudo, edema agudo de pulmón, crisis hipertensivas, estatus epiléptico, anafilaxia, donación en asistolia y parada cardiorrespiratoria.", "preguntas": [{"q": "En la sistemática X-ABCDE del paciente politraumatizado, la «X» hace referencia a:", "o": ["La radiografía cervical urgente", "El control de la hemorragia externa exanguinante, que se aborda antes que la vía aérea", "La exposición completa del paciente", "La inmovilización con tabla espinal"], "a": 1, "e": "Una hemorragia masiva mata en minutos, así que se controla primero con compresión directa o torniquete. Después siguen la A (vía aérea con control cervical), la B, la C, la D y la E (exposición y prevención de la hipotermia)."}, {"q": "En un paciente politraumatizado, la apertura de la vía aérea debe realizarse mediante:", "o": ["La maniobra frente-mentón con hiperextensión del cuello", "La flexión del cuello", "La rotación lateral de la cabeza", "La tracción mandibular, sin hiperextender el cuello"], "a": 3, "e": "Se asume que existe una lesión cervical hasta demostrar lo contrario. Se coloca un collarín rígido y un inmovilizador tetracameral y, si hay que intubar, se mantiene la estabilización manual en línea."}, {"q": "En la reposición de volumen del politraumatizado con hemorragia, la hipotensión permisiva busca mantener una PAS de 80-90 mmHg, excepto en:", "o": ["El traumatismo craneoencefálico grave", "La fractura de fémur", "El traumatismo abdominal cerrado", "El paciente anciano anticoagulado"], "a": 0, "e": "Los grandes volúmenes diluyen los factores de coagulación, enfrían al paciente y desprenden los coágulos. En el TCE grave, en cambio, se necesita una presión mayor para mantener la perfusión cerebral."}, {"q": "La llamada «tríada letal» del paciente traumatizado está formada por:", "o": ["Hipotensión, taquicardia y oliguria", "Hipoxia, hipercapnia y acidosis", "Hipotermia, coagulopatía y acidosis metabólica", "Hipoglucemia, hipotermia y bradicardia"], "a": 2, "e": "Cada elemento empeora a los otros dos. Por eso, en la E del ABCDE se desviste al paciente para explorarlo y se le tapa enseguida con mantas o sistemas de calor."}, {"q": "Está contraindicado colocar una sonda nasogástrica en un politraumatizado que presenta:", "o": ["Distensión abdominal", "Vómitos", "Fractura de fémur", "Hematoma retroauricular (signo de Battle) y salida de líquido claro por la nariz"], "a": 3, "e": "El signo de Battle y la rinolicuorrea sugieren una fractura de la base del cráneo, y la sonda podría entrar en la cavidad craneal: se usa la vía orogástrica. Si hay sangre en el meato, lo que está contraindicado es el sondaje vesical."}, {"q": "Un paciente traumatizado obtiene una puntuación de 11 en el Revised Trauma Score (RTS). Esto indica:", "o": ["Alta prioridad: asistencia urgente", "Baja prioridad: asistencia demorable", "Situación agónica", "Que debe clasificarse como negro"], "a": 0, "e": "El RTS suma Glasgow, PAS y frecuencia respiratoria (0-12). Con 12 la asistencia es demorable, con 11 es urgente, de 3 a 10 inmediata, y por debajo de 3 indica una situación agónica."}, {"q": "Según la regla de los 9 de Wallace, un adulto con quemaduras de segundo grado en todo el tronco anterior y en todo el brazo izquierdo tiene una superficie quemada de:", "o": ["18%", "27%", "36%", "45%"], "a": 1, "e": "El tronco anterior vale 18% y cada brazo, 9%: 18 + 9 = 27%. La cabeza vale 9%, el tronco posterior 18%, cada pierna 18% y el periné 1%. En niños se usan las tablas de Lund-Browder."}, {"q": "Un paciente tiene una quemadura solar (primer grado) en toda la espalda y una quemadura con flictenas (segundo grado) en todo el brazo derecho. La superficie que se usa para calcular la reposición de líquidos es:", "o": ["27%", "18%", "9%", "36%"], "a": 2, "e": "Las quemaduras de primer grado (eritema) no se cuentan para la reposición. Solo se suma el brazo con quemadura de segundo grado: 9%."}, {"q": "La fórmula de Parkland para la reposición de líquidos en el gran quemado es:", "o": ["4 ml × kg de peso × % de superficie quemada en 24 h, administrando la mitad en las primeras 8 horas", "2 ml × kg × % de superficie quemada, todo en la primera hora", "30 ml/kg en bolo", "1.500 ml/m² al día repartidos en 24 horas"], "a": 0, "e": "Se usa Ringer lactato: la mitad del volumen en las primeras 8 horas y la otra mitad en las 16 siguientes. La reposición se ajusta con la diuresis horaria (0,5-1 ml/kg/h en el adulto)."}, {"q": "Un paciente sufre una quemadura extensa a las 14:00 h y llega al hospital a las 17:00 h. Según la fórmula de Parkland, la primera mitad del volumen calculado debe haberse administrado:", "o": ["Antes de las 20:00 h", "En las 8 horas siguientes a su llegada, es decir, antes de la 01:00 h", "Antes de las 18:00 h", "Antes de las 22:00 h"], "a": 3, "e": "Las primeras 8 horas se cuentan desde el momento del accidente, no desde la llegada. Desde las 14:00 h, el plazo termina a las 22:00 h: quedan 5 horas para administrar el 50% del volumen."}, {"q": "En un gran quemado con dolor intenso, la vía de administración de los opioides debe ser:", "o": ["Intramuscular", "Intravenosa", "Subcutánea", "Rectal"], "a": 1, "e": "El edema hace que la absorción IM o SC sea errática: el fármaco se acumula y puede pasar de golpe a la sangre cuando el edema se reabsorbe. La analgesia se administra antes de las curas."}, {"q": "Un paciente con una lesión medular cervical presenta hipotensión con bradicardia y la piel caliente. Se trata probablemente de un shock:", "o": ["Hipovolémico", "Cardiogénico", "Neurogénico", "Obstructivo"], "a": 2, "e": "La lesión por encima de T4 interrumpe el control simpático: hay vasodilatación sin taquicardia compensadora. En los demás tipos de shock suele aparecer taquicardia."}, {"q": "El vasopresor de primera elección en el shock séptico es:", "o": ["La noradrenalina", "La dopamina", "La dobutamina", "La adrenalina"], "a": 0, "e": "Se inicia si la hipotensión persiste durante o tras la reposición de volumen, con el objetivo de una PAM ≥ 65 mmHg. Si no basta, se añade vasopresina o adrenalina; la dobutamina se reserva para la disfunción miocárdica."}, {"q": "Ante un paciente con sospecha de shock séptico, el orden correcto de actuación es:", "o": ["Administrar el antibiótico y extraer hemocultivos a las 24 horas", "Esperar el resultado del lactato antes de iniciar cualquier tratamiento", "Iniciar vasopresores antes de los líquidos", "Extraer hemocultivos y administrar el antibiótico de amplio espectro en la primera hora"], "a": 3, "e": "Los cultivos se sacan antes del antibiótico, sin retrasarlo. Además se mide el lactato y, si hay hipotensión o lactato ≥ 4 mmol/L, se administran 30 ml/kg de cristaloides."}, {"q": "Para hacer un lavado gástrico en una intoxicación, el paciente se coloca en:", "o": ["Decúbito supino con la cabecera a 45°", "Decúbito lateral derecho", "Decúbito lateral izquierdo con ligero Trendelenburg", "Sedestación"], "a": 2, "e": "Esta posición dificulta el paso del contenido al duodeno y protege frente a la aspiración. Se usa una sonda gruesa (Faucher) y está indicado sobre todo dentro de la primera hora tras la ingesta."}, {"q": "El lavado gástrico está contraindicado en la intoxicación por:", "o": ["Derivados del petróleo (hidrocarburos) y cáusticos", "Benzodiacepinas en la primera hora", "Antidepresivos tricíclicos", "Salicilatos"], "a": 0, "e": "Con cáusticos hay riesgo de perforación, y con hidrocarburos, de neumonitis por aspiración. Tampoco se hace si el Glasgow es inferior a 8 o falta el reflejo nauseoso sin la vía aérea aislada."}, {"q": "El carbón activado NO es eficaz en la intoxicación por:", "o": ["Paracetamol", "Litio", "Benzodiacepinas", "Antidepresivos tricíclicos"], "a": 1, "e": "El carbón no adsorbe metales (litio, hierro, plomo), alcoholes, cáusticos ni hidrocarburos. Es el método de descontaminación de elección para la mayoría de fármacos, idealmente en la primera hora."}, {"q": "Un paciente presenta midriasis, taquicardia, piel roja, caliente y seca, retención urinaria y agitación con alucinaciones. Corresponde al síndrome:", "o": ["Colinérgico", "Opioide", "Simpaticomimético", "Anticolinérgico"], "a": 3, "e": "Lo causan la atropina, los antidepresivos tricíclicos o los antihistamínicos. El simpaticomimético (cocaína, anfetaminas) también produce midriasis y taquicardia, pero con sudoración abundante."}, {"q": "El antídoto de la intoxicación por paracetamol es:", "o": ["La N-acetilcisteína", "El flumazenilo", "La deferoxamina", "La naloxona"], "a": 0, "e": "La N-acetilcisteína evita la necrosis hepática que produce el metabolito tóxico del paracetamol. El flumazenilo revierte las benzodiacepinas, la deferoxamina quela el hierro y la naloxona antagoniza los opioides."}, {"q": "Tras revertir con naloxona una sobredosis de heroína, el paciente debe seguir vigilado porque:", "o": ["La naloxona produce hipertensión grave", "La naloxona provoca hipoglucemia", "La naloxona tiene una vida media más corta que muchos opioides y el paciente puede volver a sedarse", "La naloxona causa siempre convulsiones"], "a": 2, "e": "Puede requerir dosis repetidas o perfusión continua, sobre todo con opioides de acción prolongada (metadona, fentanilo en parches). Con el flumazenilo, el riesgo son las convulsiones en consumidores crónicos."}, {"q": "En un paciente con síndrome coronario agudo, el oxígeno está indicado cuando:", "o": ["Siempre, a alto flujo", "Solo si hay dolor torácico", "Solo durante el traslado", "Solo si la saturación de oxígeno es inferior al 90%"], "a": 3, "e": "La hiperoxia puede producir vasoconstricción coronaria. Lo prioritario es hacer un ECG de 12 derivaciones en menos de 10 minutos y vigilar el ritmo por el riesgo de fibrilación ventricular."}, {"q": "Ante un edema agudo de pulmón cardiogénico, la posición más adecuada es:", "o": ["Decúbito supino con las piernas elevadas", "Sentado con las piernas colgando", "Trendelenburg", "Decúbito lateral izquierdo"], "a": 1, "e": "Con las piernas colgando se retiene sangre en ellas y disminuye el retorno venoso (precarga). Además se usa VMNI (CPAP o BiPAP), furosemida IV y nitroglicerina IV."}, {"q": "Un paciente con sospecha de ictus isquémico, que no va a recibir fibrinólisis, tiene una TA de 200/100 mmHg. La actuación correcta respecto a la tensión es:", "o": ["No bajarla, salvo que supere 220/120 mmHg", "Bajarla de inmediato por debajo de 140/90 mmHg", "Administrar nitroprusiato en bolo", "Reducir la PAM un 50% en la primera hora"], "a": 0, "e": "En el ictus isquémico se permite una TA alta para mantener la perfusión de la zona en riesgo. Si se va a fibrinolisar, debe estar por debajo de 185/110. En la disección aórtica, en cambio, se baja de forma rápida (PAS < 120)."}, {"q": "La fenitoína intravenosa para el estatus epiléptico debe diluirse:", "o": ["En suero glucosado al 5%", "En Ringer lactato con glucosa", "Solo en suero fisiológico al 0,9%", "En agua para inyección sin diluir más"], "a": 2, "e": "La fenitoína precipita en suero glucosado y puede formar cristales y émbolos o producir flebitis. Hoy el levetiracetam es una alternativa de segunda línea muy utilizada por su seguridad."}, {"q": "Un paciente lleva 6 minutos convulsionando y no se consigue canalizar una vía venosa. El fármaco y la vía más adecuados son:", "o": ["Diazepam intramuscular", "Fenitoína oral", "Levetiracetam subcutáneo", "Midazolam intramuscular o intranasal"], "a": 3, "e": "El diazepam IM se absorbe de forma lenta y errática, por lo que no se usa. Durante la crisis se protege la cabeza, no se fuerza la apertura de la boca ni se sujeta al paciente, y se cronometra la duración."}, {"q": "El tratamiento de primera línea de la anafilaxia en un adulto es:", "o": ["Dexclorfeniramina intravenosa", "Adrenalina intramuscular 0,5 mg (ampolla 1:1.000) en la cara anterolateral del muslo", "Hidrocortisona intravenosa", "Adrenalina subcutánea en el deltoides"], "a": 1, "e": "Se puede repetir a los 5-15 minutos. Antihistamínicos y corticoides son coadyuvantes y no deben retrasarla. Al paciente se le mantiene tumbado con las piernas elevadas, sin levantarlo de golpe."}, {"q": "En la clasificación de Maastricht modificada, la donación en asistolia controlada, tras la limitación del tratamiento de soporte vital, corresponde al tipo:", "o": ["I", "II", "III", "IV"], "a": 2, "e": "Tipo I: fallecido a la llegada. Tipo II: RCP infructuosa. Tipo III: asistolia controlada (tras LTSV o prestación de ayuda para morir). Tipo IV: parada en un paciente en muerte encefálica. Tras la asistolia se esperan 5 minutos sin tocar al paciente."}, {"q": "En la RCP básica del adulto, las compresiones torácicas deben realizarse:", "o": ["A 100-120 por minuto y con una profundidad de 5-6 cm, permitiendo la reexpansión completa del tórax", "A 60-80 por minuto y con una profundidad de 3-4 cm", "A más de 140 por minuto para mejorar el gasto", "A 100 por minuto y con una profundidad de 8 cm"], "a": 0, "e": "Se comprime en el centro del pecho con una relación 30:2 y sin interrumpir más de 10 segundos para ventilar. Las respiraciones agónicas (gasping) no son respiración normal."}, {"q": "En una parada con fibrilación ventricular, la primera dosis de adrenalina (1 mg IV) se administra:", "o": ["Antes de la primera descarga", "Tras la primera descarga", "Solo si la FV pasa a asistolia", "Tras la tercera descarga y luego cada 3-5 minutos"], "a": 3, "e": "En ritmos desfibrilables la prioridad es la desfibrilación. Tras la tercera descarga se dan adrenalina 1 mg y amiodarona 300 mg, y amiodarona 150 mg tras la quinta. En la asistolia y la AESP, la adrenalina va en cuanto haya acceso vascular."}, {"q": "En la RCP pediátrica con dos o más reanimadores sanitarios, la relación compresiones/ventilaciones es:", "o": ["30:2", "15:2", "5:1", "3:1"], "a": 1, "e": "En el niño se empieza con 5 ventilaciones de rescate, porque la parada suele ser de origen respiratorio. Se comprime 1/3 del diámetro torácico y la desfibrilación es de 4 J/kg."}, {"q": "Paciente que no responde y no respira con normalidad. ¿Qué ritmo muestra el monitor?", "o": ["Fibrilación ventricular", "Asistolia", "Actividad eléctrica sin pulso", "Fibrilación auricular rápida"], "a": 0, "e": "FV: actividad caótica sin QRS. Ritmo desfibrilable: descarga inmediata y RCP 2 min; adrenalina 1 mg y amiodarona 300 mg tras la 3.ª descarga.", "img": "img/preguntas/ecg-fv.svg"}, {"q": "Parada cardiaca con este ritmo (confirmado en dos derivaciones y con la ganancia adecuada). La actuación correcta es:", "o": ["Desfibrilar tres veces seguidas", "Cardioversión sincronizada", "RCP y adrenalina 1 mg IV lo antes posible", "Amiodarona 300 mg IV"], "a": 2, "e": "Asistolia = ritmo no desfibrilable: compresiones de calidad, adrenalina 1 mg cada 3-5 min desde el principio y buscar causas reversibles (4H y 4T).", "img": "img/preguntas/ecg-asistolia.svg"}, {"q": "Paciente sin pulso con este ritmo (taquicardia regular de QRS anchos a ≈ 180 lpm). ¿Qué se debe hacer?", "o": ["Cardioversión sincronizada", "Desfibrilación (no sincronizada) y RCP", "Adenosina 6 mg en bolo", "Maniobras vagales"], "a": 1, "e": "TV sin pulso = ritmo desfibrilable, igual que la FV. La cardioversión sincronizada se reserva para la TV con pulso e inestable.", "img": "img/preguntas/ecg-tv.svg"}, {"q": "Paciente en coma, con 6 respiraciones por minuto y las pupilas de la imagen. El antídoto de primera elección es:", "o": ["Flumazenilo", "N-acetilcisteína", "Atropina", "Naloxona"], "a": 3, "e": "Miosis puntiforme + depresión respiratoria + coma = intoxicación por opiáceos: naloxona (IV, IM o intranasal), vigilando la resedación porque dura menos que el opioide.", "img": "img/preguntas/pupilas-miosis.svg"}, {"q": "Paciente confuso con las pupilas de la imagen, piel seca y caliente, enrojecimiento, taquicardia y retención urinaria. ¿Qué toxíndrome sugiere?", "o": ["Opioide", "Colinérgico (organofosforados)", "Anticolinérgico", "Sedante-hipnótico"], "a": 2, "e": "Anticolinérgico (antihistamínicos, tricíclicos, atropina): midriasis, piel seca y roja, hipertermia, retención urinaria y delirio. El simpaticomimético también da midriasis pero con sudoración.", "img": "img/preguntas/pupilas-midriasis.svg"}]},
50: {"tema": 50, "titulo": "Valoración y cuidados de enfermería del paciente quirúrgico. Preoperatorio e intraoperatorio", "programa": "Valoración y cuidados de enfermería del paciente quirúrgico en el preoperatorio (valoración, preparación, ayuno, medicación, consentimiento) y en el intraoperatorio (bloque quirúrgico, listado de verificación, funciones de enfermería, monitorización, posiciones, seguridad, asepsia, instrumental, suturas y anestesia).", "preguntas": [{"q": "La fase preoperatoria finaliza:", "o": ["Cuando el paciente ingresa en el hospital", "Cuando el paciente entra en el área quirúrgica", "Tras la firma del consentimiento informado", "Cuando el paciente es trasladado a la mesa quirúrgica"], "a": 3, "e": "El preoperatorio comienza con la decisión de operar y termina con el traslado a la mesa de quirófano, donde empieza el intraoperatorio."}, {"q": "Según las recomendaciones actuales de ayuno preoperatorio, los líquidos claros (agua, zumo sin pulpa) pueden tomarse hasta:", "o": ["2 horas antes de la anestesia", "4 horas antes", "6 horas antes", "8 horas antes"], "a": 0, "e": "Líquidos claros, 2 h; leche materna, 4 h; comida ligera o leche de fórmula, 6 h; comida copiosa o grasa, 8 h. El ayuno prolongado aumenta la resistencia a la insulina inducida por el estrés."}, {"q": "Si es necesario eliminar el vello de la zona quirúrgica, se recomienda:", "o": ["Rasurar con cuchilla la noche anterior", "Usar crema depilatoria 24 horas antes", "Usar una cortadora eléctrica (clíper) inmediatamente antes de la intervención", "Rasurar con cuchilla en el propio quirófano"], "a": 2, "e": "La cuchilla produce microabrasiones que se colonizan y aumentan la infección del sitio quirúrgico. Como norma, el vello no se elimina salvo que interfiera con la intervención."}, {"q": "¿Qué fármaco se suspende habitualmente 24-48 horas antes de una cirugía por el riesgo de acidosis láctica?", "o": ["El bisoprolol", "La metformina", "La levotiroxina", "El salbutamol inhalado"], "a": 1, "e": "La glucemia se controla después con insulina según la glucemia capilar. Los betabloqueantes, los tiroideos, los antiepilépticos y los inhaladores se mantienen para evitar efectos rebote."}, {"q": "La profilaxis antibiótica quirúrgica con cefazolina debe administrarse:", "o": ["Dentro de los 60 minutos previos a la incisión", "En la planta, unas 3 horas antes de bajar a quirófano", "Al finalizar la intervención", "Durante las 24 horas previas"], "a": 0, "e": "Así hay niveles tisulares máximos en el momento del corte. La vancomicina y las fluoroquinolonas se inician hasta 120 minutos antes por su infusión lenta. Se redosifica si la cirugía dura más de 4 horas o el sangrado supera 1.500 ml."}, {"q": "Respecto al consentimiento informado quirúrgico, la función de la enfermera es:", "o": ["Explicar los riesgos de la intervención y recoger la firma", "Firmar como testigo en lugar del paciente", "Cumplimentar un único documento para cirugía y anestesia", "Comprobar que existen los documentos firmados y avisar al médico si el paciente tiene dudas"], "a": 3, "e": "Informar y recoger la firma corresponde al médico responsable. Cirugía y anestesia tienen documentos separados, y el paciente puede revocar el consentimiento por escrito en cualquier momento sin justificarlo."}, {"q": "En la zona del bloque quirúrgico donde es obligatorio el uso de mascarilla, además del pijama, gorro y calzado específico, es:", "o": ["La zona negra", "La zona gris", "La zona blanca (quirófano)", "La zona de recepción de pacientes"], "a": 2, "e": "En la zona negra se puede circular con ropa de calle o pijama hospitalario; la gris exige pijama quirúrgico, gorro y calzado o calzas; en la blanca se añade la mascarilla."}, {"q": "En el listado de verificación quirúrgica de la OMS, la «pausa quirúrgica» (time out) se realiza:", "o": ["Antes de la inducción anestésica", "Antes de la incisión cutánea", "Antes de que el paciente salga del quirófano", "Al llegar a la URPA"], "a": 1, "e": "La entrada (sign in) se hace antes de la inducción, la pausa antes de la incisión y la salida (sign out) antes de que el paciente abandone el quirófano. En la pausa se confirma, entre otras cosas, la profilaxis antibiótica."}, {"q": "Durante la fase de salida del listado de verificación, el recuento de gasas no coincide. La actuación correcta es:", "o": ["Cerrar y anotarlo en la historia", "Buscar la gasa en los cubos de basura y continuar", "Repetir el recuento solo al día siguiente", "Avisar al equipo y solicitar una radiografía intraoperatoria antes del cierre"], "a": 3, "e": "El recuento evita dejar un cuerpo extraño (oblito). Se hace al inicio, al cerrar cavidades y al cerrar la piel. En la salida también se verifica el etiquetado de las muestras."}, {"q": "El recuento de gasas, compresas, agujas e instrumental en el quirófano es responsabilidad de:", "o": ["La enfermera instrumentista y la enfermera circulante", "La enfermera instrumentista exclusivamente", "El cirujano principal", "El anestesiólogo"], "a": 0, "e": "Es una responsabilidad compartida. La circulante, además, custodia y etiqueta las muestras y registra los lotes de los implantes."}, {"q": "La maniobra de Sellick consiste en:", "o": ["Presionar el cartílago tiroides para ver mejor la glotis", "Elevar la mandíbula para abrir la vía aérea", "Presionar el cartílago cricoides para ocluir el esófago y reducir el riesgo de broncoaspiración", "Hiperextender el cuello para facilitar la intubación"], "a": 2, "e": "La hace la enfermera de anestesia en la intubación de secuencia rápida y la mantiene hasta que se infla el balón del tubo. La presión sobre el tiroides para mejorar la visión es la maniobra BURP."}, {"q": "El método más fiable para confirmar de inmediato que el tubo endotraqueal está en la tráquea es:", "o": ["La pulsioximetría", "La capnografía (ETCO₂)", "La auscultación del epigastrio", "La radiografía de abdomen"], "a": 1, "e": "Si no aparece onda de capnografía, el tubo probablemente está en el esófago. Una caída brusca del ETCO₂ sugiere desconexión, TEP o parada, y un aumento progresivo, hipoventilación o hipertermia maligna."}, {"q": "Antes de canalizar la arteria radial para monitorizar la presión arterial invasiva, se debe realizar:", "o": ["El test de Allen, para comprobar la circulación colateral por la arteria cubital", "El test de Trendelenburg", "La maniobra de Valsalva", "La prueba de Mantoux"], "a": 0, "e": "Se comprimen las arterias radial y cubital y se libera la cubital: si la mano recupera el color en 10-15 segundos, la circulación colateral es suficiente."}, {"q": "Durante el mantenimiento de una anestesia general, el valor del índice biespectral (BIS) que se busca es:", "o": ["90-100", "70-80", "0-20", "40-60"], "a": 3, "e": "Un BIS de 90-100 corresponde al paciente despierto y por debajo de 40 la anestesia es excesivamente profunda. Antes de colocar el sensor se limpia la frente con alcohol."}, {"q": "En la posición de litotomía, la compresión de la cabeza del peroné contra las perneras puede lesionar:", "o": ["El nervio cubital", "El nervio ciático poplíteo externo (peroneo), con pie caído", "El plexo braquial", "El nervio femoral"], "a": 1, "e": "Las perneras deben estar bien acolchadas. Además, las piernas se suben y se bajan despacio y a la vez, porque al bajarlas puede aparecer una hipotensión brusca."}, {"q": "En decúbito supino con los brazos en los apoyabrazos, la abducción no debe superar los 90° para evitar:", "o": ["Una úlcera en el sacro", "La compresión ocular", "La lesión del plexo braquial", "El síndrome compartimental de la pierna"], "a": 2, "e": "En supino se protegen además el occipucio, las escápulas, los codos, el sacro y los talones. En prono, los puntos de riesgo son la frente, los ojos, el acromion, las rodillas y los dedos de los pies."}, {"q": "Se considera hipotermia perioperatoria inadvertida una temperatura central inferior a:", "o": ["36 °C", "37 °C", "35 °C", "34 °C"], "a": 0, "e": "La mayor caída se produce en la primera hora tras la inducción. La hipotermia aumenta el sangrado, la isquemia miocárdica y la infección del sitio quirúrgico; se previene con precalentamiento, mantas de aire caliente y calentadores de fluidos."}, {"q": "La placa neutra del bisturí eléctrico monopolar debe colocarse:", "o": ["Sobre una prominencia ósea para mejor contacto", "Sobre una cicatriz antigua", "Junto a la prótesis metálica del paciente", "Sobre una masa muscular amplia y bien vascularizada, lo más cerca posible del campo quirúrgico"], "a": 3, "e": "Se evitan las prominencias óseas, las cicatrices, el tejido graso, el vello (se recorta) y las prótesis metálicas, porque la corriente se concentraría y produciría quemaduras."}, {"q": "En un paciente portador de marcapasos, el sistema de electrocirugía más seguro es:", "o": ["El monopolar con la placa sobre el tórax", "El monopolar a máxima potencia", "El bipolar, que no necesita placa neutra", "Cualquiera, el marcapasos no se ve afectado"], "a": 2, "e": "En el bipolar la corriente solo pasa entre las dos puntas de la pinza. Si se usa el monopolar, el circuito entre el bisturí y la placa no debe atravesar el corazón ni el generador."}, {"q": "Si se produce fuego dentro del tubo endotraqueal durante una cirugía de vía aérea, la primera actuación es:", "o": ["Retirar inmediatamente el tubo endotraqueal", "Aumentar el oxígeno al 100%", "Echar suero por el tubo sin retirarlo", "Esperar a que se extinga solo"], "a": 0, "e": "Después se corta el flujo de gases y se vierte suero frío en la vía aérea. Para que haya fuego se necesita comburente (O₂, N₂O), una fuente de ignición y combustible, como los antisépticos alcohólicos mal secados."}, {"q": "Una muestra para biopsia intraoperatoria (por congelación) debe enviarse:", "o": ["En formol al 10%", "En fresco, sin ningún fijador", "En alcohol de 70°", "En suero glucosado"], "a": 1, "e": "El formol impide la congelación y el diagnóstico rápido. Las piezas para estudio diferido se fijan en formol al 10% (10 veces el volumen de la pieza), y las de microbiología nunca llevan formol."}, {"q": "La tijera de Metzenbaum se caracteriza por:", "o": ["Usarse para cortar hilos de sutura y gasas", "Ser una pinza de hemostasia", "Ser un separador autoestático", "Ser fina y ligera, diseñada para disecar tejidos blandos, y no debe usarse para cortar hilos"], "a": 3, "e": "La tijera de Mayo, más fuerte, se usa para cortar hilos y tejidos duros. Cortar hilos con la Metzenbaum la deja sin filo."}, {"q": "De los siguientes calibres de hilo de sutura, ¿cuál es el más fino?", "o": ["0", "2/0", "6/0", "3/0"], "a": 2, "e": "Cuantos más ceros, menor diámetro. Los hilos 6/0 o más finos se usan en microcirugía, anastomosis vasculares y suturas faciales."}, {"q": "Según la clasificación ASA, una mujer embarazada sin otras enfermedades corresponde a:", "o": ["ASA II", "ASA I", "ASA III", "ASA IV"], "a": 0, "e": "El embarazo, el tabaquismo o la obesidad no mórbida se consideran enfermedad sistémica leve (ASA II). La obesidad mórbida es ASA III, el infarto en los últimos 3 meses ASA IV y el donante en muerte encefálica ASA VI."}, {"q": "La clasificación de Mallampati se valora:", "o": ["Durante la laringoscopia, con el paciente anestesiado", "Con el paciente sentado y despierto, con la boca abierta y la lengua fuera, sin fonar", "Con el paciente en decúbito supino y el cuello en hiperextensión", "Tras la extubación en la URPA"], "a": 1, "e": "Es predictiva: la clase IV (solo se ve el paladar duro) anticipa una intubación difícil. Decir «aaah» eleva el paladar y falsea el resultado. La escala de Cormack-Lehane se valora durante la laringoscopia."}, {"q": "El signo más precoz de hipertermia maligna durante una anestesia general es:", "o": ["La fiebre por encima de 40 °C", "La bradicardia extrema", "La hipotensión aislada", "La elevación brusca e inexplicable del ETCO₂ y la rigidez del masetero"], "a": 3, "e": "La fiebre es un signo tardío. Se suspenden los halogenados y la succinilcolina, se ventila con O₂ al 100% y se administra dantroleno, que se reconstituye con 60 ml de agua estéril, nunca con suero."}, {"q": "La cefalea pospunción dural tras una anestesia intradural se caracteriza por:", "o": ["Ser constante e independiente de la postura", "Aparecer solo en decúbito", "Empeorar al incorporarse o ponerse de pie y mejorar al tumbarse", "Acompañarse siempre de fiebre"], "a": 2, "e": "Se debe a la fuga de LCR por el orificio de la duramadre. Se previene con agujas finas de punta de lápiz. El efecto adverso más inmediato de las técnicas neuroaxiales es la hipotensión."}, {"q": "Está contraindicado usar anestésico local con adrenalina (vasoconstrictor) para infiltrar:", "o": ["Un dedo de la mano", "La piel del abdomen", "La espalda", "El muslo"], "a": 0, "e": "En zonas de circulación terminal (dedos, pene, punta de la nariz, lóbulo de la oreja) puede producir isquemia y necrosis. En el resto de zonas, la adrenalina prolonga el efecto y reduce la toxicidad sistémica."}, {"q": "Según el código de colores ISO para el etiquetado de jeringas en anestesia, los relajantes musculares se identifican con el color:", "o": ["Amarillo", "Azul", "Gris", "Rojo"], "a": 3, "e": "Hipnóticos en amarillo, opioides en azul, vasopresores en violeta, anticolinérgicos en verde, anestésicos locales en gris y reversores del bloqueo con rayas rojas y blancas. La etiqueta lleva el principio activo, la concentración y las iniciales de quien la prepara."}, {"q": "Según el proyecto Infección Quirúrgica Zero, el antiséptico de elección para preparar la piel del campo quirúrgico es:", "o": ["La povidona yodada acuosa", "La clorhexidina alcohólica al 2%", "El alcohol de 70° solo", "El agua oxigenada"], "a": 1, "e": "El paquete IQZ incluye profilaxis antibiótica en los 60 minutos previos, clorhexidina alcohólica al 2%, eliminación del vello solo con cortadora eléctrica si hace falta, normotermia y glucemia por debajo de 180 mg/dl."}, {"q": "En la técnica de la imagen la aguja fina atraviesa la duramadre y llega al espacio subaracnoideo, donde sale LCR. Es la anestesia:", "o": ["Epidural", "Intradural (raquídea o espinal)", "De plexo braquial", "Local infiltrativa"], "a": 1, "e": "Intradural: L3-L4 o L4-L5 (por debajo del cono medular), sale LCR; complicación típica: cefalea pospunción (mejora en decúbito). La epidural no atraviesa la dura (aguja de Tuohy, pérdida de resistencia, catéter).", "img": "img/preguntas/t50-raquidea.jpg"}]},
51: {"tema": 51, "titulo": "El paciente trasplantado. Valoración y cuidados del paciente donante y del receptor. Acondicionamiento. Aislamiento. Atención a la familia del paciente donante", "programa": "El paciente trasplantado: valoración y cuidados del donante (muerte encefálica y asistolia) y del receptor (renal, hepático, cardíaco). Rechazo e inmunosupresión. Acondicionamiento en el trasplante de progenitores hematopoyéticos. Aislamiento protector. Atención a la familia del donante.", "preguntas": [{"q": "En España, el órgano sólido que se trasplanta con más frecuencia es:", "o": ["El hígado", "El corazón", "El riñón", "El pulmón"], "a": 2, "e": "El trasplante renal es con diferencia el más frecuente, seguido del hepático. El trasplante intestinal es el menos habitual."}, {"q": "Según la Ley 30/1979, sobre extracción y trasplante de órganos, en la donación de fallecidos rige:", "o": ["El consentimiento expreso por escrito del donante en todos los casos", "El consentimiento presunto, aunque en la práctica siempre se consulta a la familia", "La decisión exclusiva del equipo médico", "La autorización judicial previa"], "a": 1, "e": "Se considera donante a quien no haya dejado constancia de su oposición en vida, pero la entrevista familiar es siempre parte del proceso y se respeta su decisión. La ley se basa también en el altruismo y la gratuidad."}, {"q": "Respecto a la relación entre la familia del donante y el receptor, el modelo español establece que:", "o": ["Pueden conocerse si ambas partes lo desean", "Pueden intercambiar cartas firmadas a través del hospital", "La familia del donante elige al receptor", "Se garantiza el anonimato absoluto entre ambos"], "a": 3, "e": "El anonimato es uno de los principios del sistema, junto con el altruismo, la gratuidad y la equidad en el acceso a la lista de espera."}, {"q": "En la donación de un riñón de donante vivo, la evaluación psicológica y psiquiátrica del donante:", "o": ["La realiza un equipo independiente del equipo quirúrgico", "La realiza el cirujano que hará la extracción", "No es obligatoria si el donante es familiar", "La realiza la familia del receptor"], "a": 0, "e": "Su objetivo es asegurar que la decisión es libre y altruista, sin presiones ni compensación económica, y que el donante entiende los riesgos."}, {"q": "Según la clasificación de Maastricht modificada, la donación en asistolia controlada tras la limitación del tratamiento de soporte vital corresponde al tipo:", "o": ["I", "III", "II", "IV"], "a": 1, "e": "Los tipos I (fallecido a la llegada) y II (RCP infructuosa) son asistolia no controlada. El III es controlado, tras LTSV o prestación de ayuda para morir, y el IV es la parada en un paciente en muerte encefálica."}, {"q": "En el diagnóstico de muerte encefálica, el test de apnea se considera positivo cuando:", "o": ["La saturación de oxígeno baja del 90%", "Aparece bradicardia al desconectar el respirador", "El paciente respira con una PaCO₂ de 40 mmHg", "No hay ningún movimiento respiratorio con una PaCO₂ superior a 60 mmHg"], "a": 3, "e": "El diagnóstico clínico exige además coma arreactivo (Glasgow 3) y ausencia de todos los reflejos del tronco del encéfalo. Las pruebas instrumentales (EEG, Doppler) se usan cuando hay factores que dificultan la exploración."}, {"q": "Según el RD 1723/2012, el período de observación para diagnosticar la muerte encefálica en un paciente con encefalopatía anóxica es de:", "o": ["24 horas", "6 horas", "1 hora", "72 horas"], "a": 0, "e": "Si hay una lesión destructiva conocida, el período es de 6 horas; en la anoxia, de 24 horas. Puede acortarse si se realizan pruebas instrumentales que lo confirmen."}, {"q": "Un donante en muerte encefálica presenta una frecuencia cardíaca de 40 lpm. La administración de atropina:", "o": ["Es el tratamiento de elección", "Debe hacerse a dosis dobles", "Es ineficaz, porque no hay tono vagal tras la muerte del tronco del encéfalo", "Está indicada siempre antes de iniciar dopamina"], "a": 2, "e": "La atropina actúa bloqueando el nervio vago, que en la muerte encefálica ya no funciona. La segunda fase de la ME cursa con vasoplejía, hipotensión, bradicardia y poiquilotermia."}, {"q": "En el mantenimiento del donante en muerte encefálica, la presión arterial media debe mantenerse:", "o": ["Por debajo de 50 mmHg para proteger los pulmones", "Por encima de 60 mmHg (idealmente 70-90 mmHg)", "Por encima de 110 mmHg", "No tiene objetivo concreto"], "a": 1, "e": "Otros objetivos son una diuresis superior a 1 ml/kg/h, PEEP de 5-8 cmH₂O, glucemia de 120-180 mg/dl, cabecera elevada a 30° y evitar la hipotermia."}, {"q": "La terapia hormonal habitual en el mantenimiento del donante en muerte encefálica incluye:", "o": ["Corticoides (metilprednisolona), hormona tiroidea e insulina", "Desmopresina, glucagón y adrenalina", "Estrógenos, insulina y calcio", "Hidrocortisona, potasio y heparina"], "a": 0, "e": "La necrosis cerebral afecta a la hipófisis. La desmopresina no forma parte de la pauta de rutina: se añade solo si aparece una diabetes insípida."}, {"q": "Un donante en muerte encefálica presenta de forma brusca una diuresis de 600 ml/h de orina muy diluida con hipernatremia. Hay que sospechar:", "o": ["Un rechazo hiperagudo", "Una insuficiencia renal aguda", "Un exceso de sueroterapia", "Una diabetes insípida neurogénica, que se trata con desmopresina"], "a": 3, "e": "Al dejar de secretarse ADH, el riñón no puede concentrar la orina. Se reponen fluidos hipotónicos y se administra desmopresina, ajustando según la diuresis horaria."}, {"q": "En la donación de órganos tras la prestación de ayuda para morir, es correcto que:", "o": ["La donación es obligatoria para recibir la prestación", "Si el paciente revoca la donación pierde el derecho a la prestación", "La medicación se administra en el quirófano o en una sala anexa, para reducir la isquemia caliente", "Siempre debe realizarse en el domicilio"], "a": 2, "e": "Los dos procesos son independientes: el paciente puede revocar la donación en cualquier momento sin perjuicio. La canulación y la heparina antemortem se hacen con consentimiento específico y bajo sedación."}, {"q": "La escala MELD, usada para priorizar la lista de espera de trasplante hepático, incluye:", "o": ["Bilirrubina, creatinina e INR", "Albúmina, ascitis y encefalopatía", "Transaminasas, sodio y plaquetas", "Edad, peso y grupo sanguíneo"], "a": 0, "e": "Son tres parámetros objetivos de laboratorio y predicen la mortalidad a 3 meses. La escala Child-Pugh incluye además datos clínicos: albúmina, ascitis y encefalopatía."}, {"q": "Un riñón procedente de un donante fallecido tiene un KDPI del 90%. Esto significa que:", "o": ["Debe desecharse siempre por inviable", "Es un donante con criterios expandidos, que puede ser una buena opción para receptores mayores", "Es el injerto de mejor calidad posible", "Solo puede trasplantarse a niños"], "a": 1, "e": "Un KDPI alto indica menor duración prevista del injerto, pero aceptarlo reduce el tiempo en lista de espera y en diálisis, lo que beneficia a determinados receptores."}, {"q": "Según el modelo Alicante para la entrevista familiar en la donación, es correcto:", "o": ["Comunicar la muerte y pedir la donación en el mismo momento", "Explicar con detalle el EEG a la familia en estado de shock", "Plantear la donación mientras la familia está en fase de negación", "Comunicar primero la muerte, ofrecer después apoyo emocional y solo entonces plantear la donación, sin mezclar las fases"], "a": 3, "e": "No se pasa a la fase siguiente hasta que la anterior se ha asimilado. En la fase de shock no se dan datos técnicos: se acompaña, se respetan los silencios y se tolera la ira."}, {"q": "Según las fases del duelo de Kübler-Ross, no es adecuado plantear la donación cuando la familia está en fase de:", "o": ["Aceptación", "Tristeza o depresión reactiva", "Negación o ira", "Asimilación de la pérdida"], "a": 2, "e": "En negación o ira la respuesta suele ser una negativa. Hay que acompañar a la familia hasta que empiece a asimilar la pérdida, y garantizar la restitución estética del cuerpo."}, {"q": "En el trasplante renal, el riñón donado se implanta habitualmente en:", "o": ["La fosa ilíaca (implante heterotópico), sin extirpar los riñones propios", "La fosa lumbar, en el lugar del riñón enfermo", "El espacio retroperitoneal posterior", "La cavidad torácica"], "a": 0, "e": "Los vasos renales se anastomosan a los ilíacos y el uréter se reimplanta en la vejiga. Al estar en la fosa ilíaca, el dolor y la hinchazón del injerto en esa zona pueden indicar rechazo."}, {"q": "En el postoperatorio inmediato del trasplante renal con poliuria intensa, la reposición de líquidos se pauta habitualmente:", "o": ["Con restricción hídrica para no sobrecargar el injerto", "Con un volumen fijo de 500 ml/día", "Solo por vía oral", "En relación 1:1 con la diuresis de la hora anterior"], "a": 3, "e": "La reposición 1:1 evita la hipovolemia. Se vigila también la permeabilidad de la sonda vesical para evitar coágulos que tensen la sutura ureteral."}, {"q": "Tras un trasplante hepático, la salida de bilis clara y acuosa por el tubo de Kehr sugiere:", "o": ["Una función hepática excelente", "Daño isquémico o fallo primario del injerto", "Un exceso de sueroterapia", "Que el tubo debe retirarse ya"], "a": 1, "e": "Una bilis densa, dorada o verdosa indica que el hígado funciona. La «bilis blanca» sugiere fallo del injerto, que puede requerir un retrasplante urgente."}, {"q": "Un paciente con trasplante cardíaco reciente tiene en reposo una frecuencia cardíaca de 100 lpm sin otros signos. Esto se debe a:", "o": ["Un rechazo agudo", "Una hipovolemia", "La denervación del corazón trasplantado, que pierde el freno vagal", "Un efecto adverso del tacrolimus"], "a": 2, "e": "Además, una isquemia no producirá dolor anginoso, y la atropina no corrige las bradicardias: se usan marcapasos epicárdicos temporales."}, {"q": "De los siguientes órganos, el que tolera menos tiempo de isquemia fría es:", "o": ["El corazón", "El hígado", "El páncreas", "El riñón"], "a": 0, "e": "Corazón, 4-6 horas; pulmón, 4-8 horas; hígado y páncreas, 12-15 horas; riñón, 24-36 horas."}, {"q": "El rechazo hiperagudo del injerto:", "o": ["Aparece años después del trasplante", "Está mediado por linfocitos T y responde a corticoides", "Es el tipo de rechazo más frecuente", "Se produce en minutos u horas por anticuerpos preformados y obliga a retirar el órgano"], "a": 3, "e": "Hoy es muy raro gracias a la prueba cruzada previa. El rechazo agudo celular (1-6 meses, linfocitos T) es el más frecuente y se trata con bolos de metilprednisolona; el crónico aparece tras años."}, {"q": "En un paciente con trasplante renal, el rechazo agudo se manifiesta típicamente con:", "o": ["Poliuria e hipotensión", "Oliguria, fiebre, dolor e hinchazón en la zona del injerto, aumento de peso, HTA y ascenso de la creatinina", "Hipoglucemia y bradicardia", "Ausencia total de síntomas y creatinina normal"], "a": 1, "e": "El riñón atacado deja de filtrar, así que el rechazo cursa con oliguria, nunca con poliuria. El diagnóstico se confirma con biopsia del injerto."}, {"q": "La hiperplasia gingival y la hipertricosis son efectos adversos característicos de:", "o": ["El micofenolato", "El tacrolimus", "La ciclosporina", "El sirolimus"], "a": 2, "e": "La ciclosporina también es nefrotóxica y produce HTA. El tacrolimus causa temblor y diabetes postrasplante, el micofenolato diarrea, y el sirolimus hiperlipemia y mala cicatrización."}, {"q": "En un paciente trasplantado tratado con azatioprina está contraindicado administrar:", "o": ["Alopurinol, por el riesgo de aplasia medular", "Paracetamol", "Omeprazol", "Insulina"], "a": 0, "e": "El alopurinol impide la degradación de la azatioprina y la eleva hasta niveles tóxicos, con mielotoxicidad grave."}, {"q": "La extracción de sangre para determinar los niveles de tacrolimus debe hacerse:", "o": ["Dos horas después de la dosis", "En cualquier momento del día", "Después del desayuno", "Justo antes de la dosis de la mañana (nivel valle)"], "a": 3, "e": "Tacrolimus y ciclosporina tienen un margen terapéutico estrecho y muchas interacciones, por lo que se ajustan según el nivel valle."}, {"q": "En un paciente trasplantado en tratamiento inmunosupresor está contraindicada la vacuna:", "o": ["Antigripal inactivada", "Antineumocócica", "Triple vírica (sarampión, rubeola y parotiditis)", "Frente a la hepatitis B"], "a": 2, "e": "Las vacunas de virus vivos atenuados (triple vírica, varicela, fiebre amarilla) pueden causar una enfermedad diseminada en el inmunodeprimido. Las vacunas inactivadas sí pueden administrarse."}, {"q": "Durante la infusión de progenitores hematopoyéticos criopreservados (día 0), el paciente refiere olor a ajo en el aliento. Esto se debe a:", "o": ["El conservante DMSO; es esperable y basta con informar al paciente", "Una reacción hemolítica grave", "Una infección por hongos", "Una contaminación de la bolsa"], "a": 0, "e": "El DMSO evita que las células se rompan al congelarse. También puede causar sabor metálico, bradicardia o hipotensión, por lo que se premedica y se monitoriza. La orina puede verse rojiza."}, {"q": "La tríada clásica de la enfermedad injerto contra huésped aguda tras un trasplante alogénico de progenitores es:", "o": ["Fiebre, tos y disnea", "Afectación de la piel (exantema), el hígado (ictericia) y el intestino (diarrea)", "Hipertensión, edemas y proteinuria", "Cefalea, vómitos y rigidez de nuca"], "a": 1, "e": "Las células del donante atacan los tejidos del receptor. El exantema suele empezar en palmas y plantas y la diarrea puede ser muy abundante."}, {"q": "La habitación de aislamiento protector para un paciente en aplasia tras un trasplante de progenitores debe tener:", "o": ["Presión negativa y ventanas abiertas", "Presión negativa y filtros HEPA", "Presión neutra y plantas para mejorar el ánimo", "Presión positiva respecto al pasillo y filtros HEPA"], "a": 3, "e": "La presión positiva hace que el aire salga de la habitación y no entre el contaminado, y los filtros HEPA retienen las esporas de Aspergillus. La presión negativa se usa para pacientes contagiosos, como en la tuberculosis."}]},
52: {"tema": 52, "titulo": "Cuidados de enfermería en pacientes postquirúrgicos", "programa": "Cuidados de enfermería en pacientes postquirúrgicos: vigilancia postanestésica, recuperación intensificada, drenajes quirúrgicos y torácicos, cicatrización y curas, terapia de presión negativa, cirugía mayor ambulatoria, cirugía menor y continuidad de cuidados al alta.", "preguntas": [{"q": "Según los protocolos de recuperación intensificada (ERAS / vía RICA), tras la cirugía se recomienda:", "o": ["Iniciar la tolerancia oral de forma precoz, sin esperar a auscultar ruidos intestinales", "Mantener dieta absoluta hasta la expulsión de gases", "Colocar sonda nasogástrica de rutina", "Mantener reposo en cama 48 horas"], "a": 0, "e": "La alimentación precoz protege la mucosa intestinal. ERAS también promueve la movilización el mismo día, la analgesia multimodal ahorradora de opioides y la retirada precoz de sondas y drenajes."}, {"q": "Para que un paciente pueda salir de la URPA tras una anestesia general, en la escala de Aldrete debe obtener:", "o": ["Al menos 5 puntos", "Al menos 7 puntos", "9 o más puntos", "Exactamente 12 puntos"], "a": 2, "e": "Aldrete valora actividad, respiración, circulación, conciencia y coloración o saturación, cada uno de 0 a 2 (máximo 10). En CMA, para el alta a domicilio se usa además la escala PADSS."}, {"q": "La escala de Bromage se utiliza para valorar:", "o": ["El nivel de sedación", "El bloqueo motor de las extremidades inferiores tras una anestesia raquídea o epidural", "El dolor postoperatorio", "El riesgo de úlceras por presión"], "a": 1, "e": "Grado 0: eleva la pierna extendida (sin bloqueo). Grado 1: flexiona las rodillas. Grado 2: solo mueve los pies. Grado 3: bloqueo completo. Se exige el grado 0 para movilizar o dar el alta."}, {"q": "En el postoperatorio inmediato de un paciente intervenido con anestesia raquídea, la posición indicada para prevenir la cefalea pospunción es:", "o": ["Fowler", "Trendelenburg", "Decúbito prono", "Decúbito supino, habitualmente sin almohada"], "a": 3, "e": "La cefalea se debe a la fuga de LCR por el orificio de la duramadre y empeora al incorporarse. La posición de Fowler se reserva para cirugías de cabeza, cuello y tórax."}, {"q": "Tras una tiroidectomía, la posición más adecuada es:", "o": ["Trendelenburg", "Decúbito prono", "Fowler o semi-Fowler", "Kraske"], "a": 2, "e": "Con la cabecera elevada disminuyen la congestión venosa y el edema cervical, y mejora la ventilación. Hay que vigilar la aparición de un hematoma que comprima la vía aérea."}, {"q": "Un drenaje plano de látex que se fija con un punto y se atraviesa con un imperdible estéril en su extremo exterior es un drenaje de:", "o": ["Penrose", "Redón", "Jackson-Pratt", "Kehr"], "a": 0, "e": "El Penrose funciona por capilaridad. El imperdible evita que se deslice hacia el interior de la cavidad. Como el líquido sale a la piel, hay que vigilar la maceración."}, {"q": "Durante el protocolo de pinzamiento de un tubo de Kehr, el paciente refiere dolor en el hipocondrio derecho, orina color coñac y heces blanquecinas. La actuación correcta es:", "o": ["Registrarlo y mantener el pinzamiento", "Aumentar el tiempo de pinzamiento", "Retirar el tubo", "Despinzar el drenaje y avisar al cirujano"], "a": 3, "e": "La coluria, la acolia, el dolor, la ictericia o la fiebre indican que la bilis no pasa bien al duodeno. Antes de retirar el Kehr se hace una colangiografía de control."}, {"q": "En los drenajes tipo sumidero (Saratoga), la luz abierta a la atmósfera sirve para:", "o": ["Instilar antibióticos", "Evitar el «efecto ventosa» que dañaría los tejidos adyacentes", "Medir la presión intraabdominal", "Recoger muestras para cultivo"], "a": 1, "e": "La entrada de aire filtrado rompe el vacío extremo. El Abramson añade una tercera luz para irrigar suero de forma continua mientras se aspira."}, {"q": "El drenaje Jackson-Pratt se caracteriza por:", "o": ["Funcionar por capilaridad", "Ser un tubo en T para la vía biliar", "Tener un reservorio en forma de pera que se comprime para generar un vacío de baja presión", "Necesitar aspiración de pared de alta presión"], "a": 2, "e": "La enfermera comprime el bulbo y cierra el tapón antes de soltarlo. El Redón, en cambio, trabaja con un frasco de vacío de alta presión."}, {"q": "En un sistema de drenaje torácico, la oscilación del nivel de líquido de la cámara de sello de agua con los movimientos respiratorios indica:", "o": ["Una fuga aérea", "Que hay que cambiar el sistema", "Un neumotórax a tensión", "Que el tubo está permeable"], "a": 3, "e": "Si la oscilación cesa de forma brusca, el tubo puede estar obstruido o acodado. Si desaparece poco a poco a lo largo de los días, suele significar que el pulmón se ha reexpandido."}, {"q": "La presencia de burbujeo continuo en la cámara de sello de agua de un drenaje torácico indica:", "o": ["Una fuga de aire del paciente (por ejemplo, fístula broncopleural)", "Que la aspiración funciona correctamente", "Que la cámara de recolección está llena", "Un funcionamiento normal en todos los casos"], "a": 0, "e": "El burbujeo en la cámara de control de aspiración de los modelos húmedos sí es normal: indica que la aspiración está activa. Un burbujeo prolongado e intenso en el sello de agua es patológico."}, {"q": "Un paciente con drenaje torácico debe trasladarse a radiología. La actuación correcta es:", "o": ["Pinzar el tubo durante el traslado", "No pinzarlo y mantener el sistema vertical y por debajo del nivel del tórax", "Desconectar el sistema y taponar el tubo", "Colocar el sistema sobre el abdomen del paciente"], "a": 1, "e": "El tubo no se pinza de rutina. Solo se pinza para cambiar el sistema, tras instilar medicación intrapleural, en una hemorragia masiva hasta el quirófano o como prueba antes de retirarlo, por indicación médica."}, {"q": "Si se pinza el tubo torácico de un paciente con una fuga aérea activa, se puede producir:", "o": ["Un hemotórax", "Una atelectasia leve sin importancia", "Un derrame pleural", "Un neumotórax a tensión"], "a": 3, "e": "El aire no puede salir y se acumula en la pleura: disnea, hipotensión, desviación del mediastino y enfisema subcutáneo. Por eso nunca se pinza si hay burbujeo en el sello de agua."}, {"q": "Se considera signo de alarma de sangrado activo en un drenaje torácico un débito hemático superior a:", "o": ["50 ml en 24 horas", "100 ml en 12 horas", "200 ml/hora durante 3 horas seguidas", "500 ml en la primera semana"], "a": 2, "e": "Este volumen puede requerir una toracotomía urgente. Las muestras del líquido se obtienen por el puerto del tubo con una jeringa, nunca desconectando el sistema."}, {"q": "En la cicatrización, el colágeno que predomina en la fase proliferativa y el que lo sustituye en la fase de maduración son, respectivamente:", "o": ["Tipo III y tipo I", "Tipo I y tipo III", "Tipo II y tipo IV", "Tipo IV y tipo II"], "a": 0, "e": "El fibroblasto produce colágeno tipo III inmaduro, que se sustituye por colágeno tipo I, más resistente. Aun así, la cicatriz recupera como máximo un 80% de la fuerza del tejido original."}, {"q": "El cierre de una herida por tercera intención (primario diferido) consiste en:", "o": ["Suturar la herida de inmediato", "Dejar la herida abierta unos días para controlar la infección o el edema y suturarla después", "Dejar que cicatrice por granulación desde el fondo sin suturar nunca", "Cubrirla con un injerto cutáneo inmediato"], "a": 1, "e": "En la primera intención se aproximan los bordes de inmediato. En la segunda, la herida se deja abierta y granula desde el fondo, como en las úlceras y los abscesos drenados."}, {"q": "El desbridamiento autolítico se caracteriza por:", "o": ["Ser el más rápido", "Requerir bisturí y anestesia", "Usar enzimas como la colagenasa", "Ser lento, selectivo e indoloro, y se favorece con hidrogeles en ambiente húmedo"], "a": 3, "e": "El desbridamiento quirúrgico o cortante es el más rápido. En el esquema TIME, la T se refiere al tejido no viable (necrosis o esfacelos)."}, {"q": "La escala REEDA para valorar la herida quirúrgica evalúa:", "o": ["Enrojecimiento, edema, equimosis, exudado (drenaje) y aproximación de los bordes", "Respiración, edema, eritema, dolor y apetito", "Riesgo, exudado, extensión, dolor y antigüedad", "Rubor, eritema, escara, dehiscencia y absceso"], "a": 0, "e": "Cada ítem se puntúa de 0 a 3, y una puntuación de 0 indica una curación óptima. Las dos E corresponden a edema y equimosis; la D, al exudado (discharge)."}, {"q": "Está contraindicada la terapia de presión negativa (VAC) en:", "o": ["Una herida quirúrgica dehiscente limpia", "Una úlcera con tejido de granulación", "Una herida con tejido necrótico sin desbridar o con vasos sanguíneos expuestos", "Una herida con exudado abundante"], "a": 2, "e": "Tampoco se aplica en la osteomielitis no tratada, en fístulas no exploradas ni si hay cáncer en el lecho. La esponja se recorta al tamaño exacto de la herida, sin tocar la piel sana."}, {"q": "La presión negativa terapéutica estándar con la que suele iniciarse la terapia VAC es de unos:", "o": ["25 mmHg", "125 mmHg", "300 mmHg", "500 mmHg"], "a": 1, "e": "Al principio suele programarse en modo continuo. El film adhesivo debe sobrepasar unos 3-5 cm la piel sana para conseguir un sellado hermético."}, {"q": "Para una incisión quirúrgica profunda que afecta al tejido subcutáneo y la fascia, la etiqueta NANDA más adecuada es:", "o": ["Deterioro de la integridad cutánea (00046)", "Riesgo de deterioro de la integridad cutánea", "Riesgo de infección", "Deterioro de la integridad tisular (00044)"], "a": 3, "e": "El deterioro de la integridad cutánea se limita a la epidermis y la dermis (abrasiones, UPP de categoría I-II). El de la integridad tisular afecta a planos profundos (UPP de categoría III-IV, incisiones profundas)."}, {"q": "Tras drenar un absceso cutáneo, la actuación correcta es:", "o": ["Suturar la incisión para evitar infecciones", "Aplicar un vendaje compresivo y cerrar con grapas", "Dejar la herida abierta con una mecha para que cierre por segunda intención", "Cerrarla con adhesivo tisular"], "a": 2, "e": "Antes se rompen los tabiques internos y se lava la cavidad; si el pus es fétido, por anaerobios, se puede irrigar con agua oxigenada. La incisión se hace en la zona de máxima fluctuación, siguiendo las líneas de Langer."}, {"q": "Es un criterio de exclusión social para la cirugía mayor ambulatoria:", "o": ["No disponer de un adulto responsable que lo acompañe las primeras 24 horas", "Vivir a 30 minutos del hospital", "Ser ASA II", "Tener teléfono en el domicilio"], "a": 0, "e": "El paciente debe vivir a menos de 1 hora del hospital y estar acompañado por un adulto las primeras 24 horas. Los pacientes ASA I y II son los candidatos ideales; ASA IV y V quedan excluidos."}, {"q": "En cirugía mayor ambulatoria, la escala que se usa para decidir el alta al domicilio es:", "o": ["La escala de Aldrete", "La escala PADSS, con 9 o más puntos", "La escala de Bromage", "La escala de Glasgow"], "a": 1, "e": "La PADSS valora constantes vitales, deambulación, náuseas y vómitos, dolor y sangrado. La Aldrete se usa para salir de la URPA hacia la unidad de readaptación al medio."}, {"q": "En CMA, la micción espontánea antes del alta es obligatoria especialmente cuando:", "o": ["El paciente es menor de 40 años", "Se ha usado anestesia general con mascarilla laríngea", "La cirugía duró menos de 30 minutos", "Se ha empleado raquianestesia o se trata de cirugía urológica o ginecológica"], "a": 3, "e": "El bloqueo simpático residual puede producir retención urinaria. Las principales causas de ingreso no deseado en CMA son las náuseas y vómitos y el dolor mal controlado."}, {"q": "La dosis máxima de lidocaína sin vasoconstrictor para la infiltración local en un adulto es de aproximadamente:", "o": ["4,5 mg/kg (sin superar unos 300 mg)", "1 mg/kg", "7 mg/kg", "15 mg/kg"], "a": 0, "e": "Con adrenalina, la dosis máxima sube a unos 7 mg/kg. Antes de infiltrar se aspira con el émbolo para no inyectar dentro de un vaso, y nunca se usa vasoconstrictor en dedos, nariz, orejas ni pene."}, {"q": "En cirugía menor, la incisión elíptica para extirpar una lesión cutánea debe:", "o": ["Ser perpendicular a las líneas de Langer", "Tener una relación longitud/anchura de 1:1", "Ser paralela a las líneas de Langer, con una relación longitud/anchura de unos 3:1", "Hacerse siempre en forma de cruz"], "a": 2, "e": "Así se reduce la tensión de la cicatriz y se evitan las «orejas de perro» en los extremos. La pieza extirpada se envía en formol al 10% a anatomía patológica."}, {"q": "Los puntos de sutura de la cara se retiran habitualmente a los:", "o": ["2 días", "4-5 días", "10-12 días", "14-21 días"], "a": 1, "e": "La cara está muy vascularizada y cicatriza rápido. El cuero cabelludo, a los 7-8 días; el tronco, a los 8-10; la espalda y los brazos, a los 10-12; y las piernas y articulaciones, a los 10-14."}, {"q": "El informe de cuidados de enfermería al alta (ICEA) se caracteriza por:", "o": ["Resumir el diagnóstico y el tratamiento médico", "Ser un documento opcional", "Elaborarse únicamente en atención primaria", "Describir las necesidades de cuidados y el grado de dependencia del paciente con lenguaje NANDA-NOC-NIC"], "a": 3, "e": "Lo cumplimenta la enfermera de planta e incluye la conciliación de la medicación. En el SMS se redacta en SELENE, se consulta en primaria a través de Ágora y se entrega una copia impresa al paciente."}, {"q": "La cuidadora principal de un paciente con Alzheimer obtiene 58 puntos en la escala de Zarit. Esto indica:", "o": ["Sobrecarga intensa", "Ausencia de sobrecarga", "Sobrecarga leve", "Que la escala no es aplicable"], "a": 0, "e": "Por debajo de 47 puntos no hay sobrecarga, de 47 a 55 es leve y a partir de 56 es intensa. La enfermera gestora de casos busca prevenir la claudicación del cuidador."}]},
53: {"tema": 53, "titulo": "Manejo de heridas. Cuidados generales de la piel", "programa": "Manejo de heridas y cuidados generales de la piel: cicatrización, preparación del lecho (TIMERS), escalas de riesgo, úlceras por presión, lesiones por humedad y por adhesivos, úlceras venosas y arteriales, pie diabético, úlceras neoplásicas y quemaduras.", "preguntas": [{"q": "Respecto al masaje de las prominencias óseas en pacientes con riesgo de úlceras por presión, es correcto que:", "o": ["Debe hacerse en cada cambio postural para activar la circulación", "Está contraindicado, porque aumenta el daño de los capilares en tejidos ya comprometidos", "Solo se recomienda si hay eritema que no blanquea", "Se hace con alcohol para endurecer la piel"], "a": 1, "e": "Las prominencias óseas no se masajean. Se recomiendan la higiene con jabón de pH ligeramente ácido, el secado a toques, la hidratación y los ácidos grasos hiperoxigenados en zonas de riesgo."}, {"q": "Para limpiar una herida con una presión eficaz y segura (1-4 kg/cm²) se recomienda usar:", "o": ["Gasas frotando con fuerza", "Una jeringa de 5 ml sin aguja", "Un chorro directo del grifo", "Una jeringa de 20-35 ml con aguja o catéter de 0,9 mm"], "a": 3, "e": "Esta presión arrastra detritus y bacterias sin dañar el tejido de granulación. Se usa suero fisiológico o agua."}, {"q": "Al tratar una úlcera, no se deben combinar en la misma cura:", "o": ["La colagenasa y un apósito de plata, porque la plata inactiva la colagenasa", "El hidrogel y un apósito secundario", "El suero fisiológico y un alginato", "La película barrera y un apósito de espuma"], "a": 0, "e": "La plata, útil frente a la infección y el biofilm, inactiva la colagenasa, que se usa para el desbridamiento enzimático."}, {"q": "La puntuación máxima posible de la escala de Braden es:", "o": ["24", "20", "23", "18"], "a": 2, "e": "Tiene 6 subescalas: cinco puntúan de 1 a 4 y la de fricción y cizallamiento solo de 1 a 3. Por eso el rango es de 6 a 23."}, {"q": "En la escala de Braden se considera riesgo alto de úlceras por presión una puntuación de:", "o": ["17 o más", "15-16", "13-14", "12 o menos"], "a": 3, "e": "Con 13-14 el riesgo es moderado y con 15-16, bajo (en mayores de 75 años, hasta 18). En Braden, menos puntos significan más riesgo."}, {"q": "En la escala de Norton modificada (INSALUD), se considera que el riesgo es mínimo o inexistente con una puntuación:", "o": ["De 5 a 9", "Mayor de 14", "De 10 a 12", "De 13 a 14"], "a": 1, "e": "Valora estado físico, estado mental, actividad, movilidad e incontinencia (5-20 puntos). De 5 a 9 el riesgo es muy alto, de 10 a 12 alto y de 13 a 14 medio."}, {"q": "A diferencia de las escalas de Braden y Norton, en la escala EMINA:", "o": ["A mayor puntuación, mayor riesgo", "No se valora la incontinencia", "Solo se usa en neonatos", "Se valora la fricción en primer lugar"], "a": 0, "e": "EMINA (Estado mental, Movilidad, Incontinencia, Nutrición y Actividad) puntúa de 0 a 3 cada ítem, con la lógica inversa. No incluye la fricción."}, {"q": "La escala Braden Q, adaptación pediátrica, añade respecto a la de adultos la valoración de:", "o": ["La edad gestacional", "El peso al nacer", "La perfusión tisular y la oxigenación", "El estado mental"], "a": 2, "e": "Es su séptima subescala. En neonatos se usa la escala NSRAS y en cuidados paliativos, la Hunters-Hill."}, {"q": "Una ampolla de contenido seroso sobre el sacro producida por la presión corresponde, según el GNEAUPP, a una úlcera por presión de categoría:", "o": ["I", "III", "IV", "II"], "a": 3, "e": "La categoría II incluye la úlcera superficial de lecho rosado y las flictenas, intactas o rotas. La I es el eritema no blanqueable con piel intacta."}, {"q": "Una zona de piel intacta de color granate o púrpura sobre el talón, que puede abrirse con rapidez, corresponde a:", "o": ["Una sospecha de lesión de tejidos profundos", "Una UPP de categoría I", "Una dermatitis asociada a la incontinencia", "Una úlcera venosa"], "a": 0, "e": "La lesión de tejidos profundos refleja daño isquémico bajo la piel por presión o cizalla. La categoría I es un eritema rojo que no blanquea."}, {"q": "Las úlceras por presión en las mucosas causadas por dispositivos (tubo endotraqueal, SNG):", "o": ["Se clasifican siempre como categoría II", "No se estadian con el sistema de categorías I-IV", "Se clasifican como no estadiables", "Se tratan con hidrocoloides"], "a": 1, "e": "Las mucosas no tienen estrato córneo ni una dermis comparable a la de la piel, por lo que los consensos indican no clasificarlas con las categorías I-IV."}, {"q": "Ante una escara negra, seca, estable y sin signos de infección en el talón, la actuación correcta es:", "o": ["Desbridamiento cortante inmediato", "Aplicar colagenasa y apósito oclusivo", "No desbridarla, porque protege el calcáneo, y vigilar signos de infección", "Aplicar hidrogel bajo un hidrocoloide para ablandarla"], "a": 2, "e": "En el talón la escara seca actúa como una barrera natural. Solo se desbrida si aparecen signos de infección: fluctuación, exudado purulento, eritema o calor."}, {"q": "En la prevención de úlceras por presión, al colocar al paciente en decúbito lateral, la inclinación recomendada es de:", "o": ["30°", "90°", "60°", "180°"], "a": 0, "e": "Un decúbito lateral a 90° concentra la presión en el trocánter. Los cambios posturales se hacen cada 2-4 horas en pacientes encamados, combinados con superficies especiales."}, {"q": "Respecto al uso de dispositivos en forma de rosco o flotador para aliviar la presión, es correcto que:", "o": ["Son la medida de elección en el sacro", "Se recomiendan en pacientes sentados", "Solo se usan en pacientes con riesgo bajo", "Están contraindicados porque producen un efecto torniquete"], "a": 3, "e": "El anillo comprime la circulación alrededor de la zona y genera edema e isquemia en el centro. Para riesgo alto se usan superficies dinámicas de aire alternante."}, {"q": "El hidrocoloide está contraindicado en:", "o": ["Las úlceras de categoría II con poco exudado", "La prevención de lesiones por fricción", "Las heridas infectadas", "Las úlceras superficiales limpias"], "a": 2, "e": "Es un apósito oclusivo que favorece el crecimiento de anaerobios y hongos en una herida infectada. En heridas con infección se usan apósitos antimicrobianos, como la plata."}, {"q": "El apósito de alginato está indicado especialmente en heridas:", "o": ["Secas con escara", "Con exudado moderado o abundante, y tiene además efecto hemostático", "Con tejido de epitelización y sin exudado", "Infectadas por anaerobios, como apósito oclusivo"], "a": 1, "e": "Al contactar con el exudado forma un gel absorbente. En una herida seca se adhiere y duele al retirarlo; para heridas secas o necróticas se usa hidrogel."}, {"q": "El parámetro analítico más útil para valorar cambios nutricionales recientes en un paciente con úlceras es:", "o": ["La prealbúmina", "La albúmina", "La hemoglobina", "El colesterol total"], "a": 0, "e": "La prealbúmina tiene una vida media de 2-3 días; la albúmina, de unos 20 días, y además baja con la inflamación. Las necesidades de proteínas aumentan con la gravedad de la úlcera (hasta 1,5-2 g/kg/día)."}, {"q": "Una lesión eritematosa difusa, simétrica «en espejo» en ambas nalgas y la cara interna de los muslos en un paciente incontinente sugiere:", "o": ["Una UPP de categoría I", "Una lesión de tejidos profundos", "Una úlcera arterial", "Una dermatitis asociada a la incontinencia, que se trata con productos barrera"], "a": 3, "e": "La humedad y las enzimas de orina y heces alcalinizan el pH de la piel. La UPP aparece sobre prominencias óseas. La DAI no se trata con apósitos húmedos, sino con barreras (óxido de zinc, películas)."}, {"q": "Para prevenir lesiones al retirar un esparadrapo o un apósito adhesivo, se debe tirar:", "o": ["Rápido y hacia arriba, a 90°", "En contra del sentido del vello", "Lentamente, a 180° (paralelo a la piel), sujetando la piel adyacente", "Tras secar la zona con alcohol"], "a": 2, "e": "Así se previenen las lesiones por adhesivos (MARSI). También ayuda no tensar el esparadrapo al pegarlo, usar películas barrera y elegir adhesivos de silicona en pieles frágiles."}, {"q": "Una úlcera de la pierna localizada por encima del maléolo interno, superficial, con mucho exudado y piel perilesional de color ocre, es probablemente:", "o": ["Una úlcera venosa", "Una úlcera arterial", "Una úlcera neuropática", "Una úlcera por presión"], "a": 0, "e": "El color ocre se debe al depósito de hemosiderina. El dolor mejora al elevar las piernas y el tratamiento de base es la compresión, tras descartar arteriopatía con el ITB."}, {"q": "Un paciente con una úlcera en un dedo del pie refiere que, por la noche, para aliviar el dolor, tiene que sacar la pierna de la cama y dejarla colgando. Esto orienta a:", "o": ["Una insuficiencia venosa", "Una isquemia arterial", "Una dermatitis de contacto", "Una úlcera por humedad"], "a": 1, "e": "En la isquemia el dolor empeora en reposo y al elevar la pierna, y mejora en declive. La úlcera arterial suele ser distal, con bordes en sacabocados, lecho pálido y pulsos ausentes."}, {"q": "Un paciente diabético de larga evolución presenta un índice tobillo-brazo de 1,4. Esto indica:", "o": ["Una circulación normal", "Una isquemia crítica", "Una arteriopatía leve", "Probables arterias calcificadas e incompresibles; hay que valorar con otras pruebas, como el índice dedo-brazo"], "a": 3, "e": "Un ITB mayor de 1,3 es un falso valor de normalidad, frecuente en la diabetes y la insuficiencia renal. El rango normal es 0,9-1,3."}, {"q": "Un índice tobillo-brazo inferior a 0,5 indica:", "o": ["Normalidad hemodinámica", "Insuficiencia venosa", "Isquemia crítica, en la que está contraindicada la compresión", "Que puede aplicarse un vendaje elástico multicapa"], "a": 2, "e": "Requiere derivación a cirugía vascular. El vendaje elástico de presión constante solo se usa con ITB mayor de 0,8."}, {"q": "Según la ley de Laplace aplicada al vendaje compresivo, la presión ejercida es mayor:", "o": ["En las zonas de menor perímetro, como el tobillo", "En el muslo", "Donde hay menos capas de venda", "Donde la venda está menos tensa"], "a": 0, "e": "La presión es proporcional a la tensión y al número de capas, e inversamente proporcional al radio. Por eso es máxima en el tobillo y decrece hacia el muslo, favoreciendo el retorno venoso."}, {"q": "Ante una úlcera arterial con escara necrótica seca en un pie sin pulsos e isquemia crítica, la actuación de enfermería correcta es:", "o": ["Desbridamiento cortante para estimular la granulación", "Mantener la necrosis seca, aplicar antiséptico, no desbridar y derivar a cirugía vascular", "Aplicar calor local para vasodilatar", "Elevar la pierna por encima del corazón"], "a": 1, "e": "Cortar sobre un tejido sin riego puede convertir una gangrena seca en húmeda. La pierna se mantiene horizontal o en ligero declive y se evitan las fuentes de calor directo."}, {"q": "En la clasificación de la Universidad de Texas del pie diabético, el estadio de peor pronóstico es el D, que corresponde a:", "o": ["Lesión limpia", "Infección sin isquemia", "Isquemia sin infección", "Isquemia e infección a la vez"], "a": 3, "e": "La escala cruza la profundidad (grados 0-III) con el estadio: A limpia, B infectada, C isquémica, D isquémica e infectada. En Wagner, la osteomielitis marca el grado 3."}, {"q": "Para controlar el mal olor de una úlcera neoplásica se utiliza habitualmente:", "o": ["Colagenasa", "Alcohol de 70°", "Metronidazol tópico y apósitos de carbón activado", "Hidrocoloide oclusivo"], "a": 2, "e": "El olor se debe a bacterias anaerobias. El apósito de carbón no debe recortarse. El objetivo en estas úlceras es el confort; el dolor puede tratarse con morfina en hidrogel."}, {"q": "Una quemadura con flictenas, lecho rosado-rojo húmedo y muy dolorosa es de:", "o": ["Segundo grado superficial", "Primer grado", "Segundo grado profundo", "Tercer grado"], "a": 0, "e": "La de primer grado es un eritema sin flictenas, la de segundo grado profundo tiene un lecho blanquecino-moteado y duele menos, y la de tercer grado es indolora, con piel acartonada."}, {"q": "Según los criterios de la American Burn Association recogidos en el manual, el volumen inicial de Ringer lactato en un adulto con quemadura eléctrica se calcula como:", "o": ["2 ml × kg × %SCQ", "1 ml × kg × %SCQ", "30 ml/kg fijos", "4 ml × kg × %SCQ"], "a": 3, "e": "En las quemaduras térmicas y químicas, la ABA propone empezar con 2 ml. En las eléctricas se mantienen 4 ml por la rabdomiólisis. En ambos casos, la mitad se da en las 8 primeras horas desde el accidente."}, {"q": "Debe derivarse a una unidad de quemados a un adulto con:", "o": ["Una quemadura solar en la espalda", "Una quemadura de segundo grado en ambas manos", "Una quemadura de segundo grado superficial del 3% en un muslo", "Una flictena de 2 cm en el antebrazo"], "a": 1, "e": "Se derivan las quemaduras en cara, manos, pies, genitales o grandes articulaciones, las de más del 15% en adultos (10% en niños), las de tercer grado de más del 2%, las eléctricas, las químicas, las circunferenciales y las que tienen inhalación."}, {"q": "Lesión por presión con pérdida total del grosor de la piel y grasa subcutánea visible, sin exposición de hueso, tendón ni músculo, como la de la imagen. ¿Qué categoría tiene?", "o": ["Categoría I", "Categoría II", "Categoría III", "Categoría IV"], "a": 2, "e": "I: eritema no blanqueable con piel intacta. II: pérdida parcial (ampolla o úlcera superficial). III: pérdida total de la piel, se ve grasa, puede haber tunelizaciones. IV: hueso, tendón o músculo expuestos.", "img": "img/preguntas/t53-upp.jpg"}]},
54: {"tema": 54, "titulo": "Seguridad del paciente. Sistemas de notificación de incidentes. Calidad de la asistencia sanitaria. Indicadores de calidad. Humanización de los servicios sanitarios", "programa": "Seguridad del paciente: conceptos, estrategia y prácticas seguras. Sistemas de notificación de incidentes (SiNASP). Calidad de la asistencia sanitaria: modelo de Donabedian, ciclo de mejora y dimensiones. Indicadores de calidad. Humanización de los servicios sanitarios (Proyecto HU-CI, comunicación de malas noticias).", "preguntas": [{"q": "La OMS define la seguridad del paciente como:", "o": ["La ausencia total de errores en la asistencia", "La responsabilidad exclusiva del médico sobre los errores", "El cumplimiento de la normativa de prevención de riesgos laborales", "La reducción del riesgo de daño innecesario asociado a la atención sanitaria hasta un mínimo aceptable"], "a": 3, "e": "La seguridad del paciente es una dimensión clave de la calidad asistencial. Asume que el riesgo cero no existe y busca reducirlo al mínimo aceptable."}, {"q": "Una enfermera detecta, justo antes de administrarla, que la medicación preparada corresponde a otro paciente con apellidos similares. Este suceso es:", "o": ["Un cuasi-incidente", "Un incidente sin daño", "Un evento adverso", "Un evento centinela"], "a": 0, "e": "El error se interceptó antes de llegar al paciente. Si hubiera llegado sin causar daño sería un incidente sin daño, y si hubiera causado daño, un evento adverso."}, {"q": "Por error se administra a un paciente una dosis de insulina rápida que no le correspondía, pero no presenta hipoglucemia ni otro efecto. Se trata de:", "o": ["Un cuasi-incidente", "Una circunstancia de riesgo", "Un incidente sin daño", "Un evento centinela"], "a": 2, "e": "La clave es si el error llegó al paciente. Aquí llegó, pero no le produjo daño. La circunstancia de riesgo es una situación con potencial de daño en la que aún no ha ocurrido ningún incidente."}, {"q": "La aparición de una úlcera por presión de categoría II durante el ingreso por inmovilización prolongada se clasifica como:", "o": ["Un evento centinela", "Un evento adverso", "Un cuasi-incidente", "Una circunstancia de riesgo"], "a": 1, "e": "Es un daño derivado de la asistencia, no de la enfermedad de base. El evento centinela se reserva para la muerte o el daño grave y permanente."}, {"q": "La realización de una intervención quirúrgica en el lado equivocado del cuerpo es un ejemplo de:", "o": ["Evento centinela", "Incidente sin daño", "Cuasi-incidente", "Circunstancia de riesgo"], "a": 0, "e": "Los eventos centinela (cirugía en el lado erróneo, potasio en bolo, suicidio de un paciente ingresado) exigen investigación inmediata mediante un análisis causa-raíz."}, {"q": "Una unidad de hospitalización con una ratio enfermera/paciente muy por debajo de lo recomendado, en la que aún no ha ocurrido ningún incidente, representa:", "o": ["Un evento adverso", "Un cuasi-incidente", "Un incidente sin daño", "Una circunstancia de riesgo o condición latente"], "a": 3, "e": "Las condiciones latentes son fallos del diseño u organización del sistema con potencial de causar daño. Identificarlas permite actuar antes de que ocurra un incidente."}, {"q": "Para la identificación inequívoca del paciente antes de administrar un fármaco, la enfermera debe:", "o": ["Preguntar «¿es usted el señor Martínez?»", "Pedirle que diga su nombre completo y fecha de nacimiento y contrastarlo con la pulsera", "Comprobar solo el número de cama", "Fiarse de la identificación del celador"], "a": 1, "e": "La pregunta cerrada es peligrosa: un paciente confuso puede asentir por error. La pulsera de identificación se coloca desde el ingreso."}, {"q": "Es un medicamento de alto riesgo que requiere doble verificación independiente antes de su administración:", "o": ["El paracetamol oral", "El omeprazol oral", "El cloruro potásico concentrado intravenoso", "El suero fisiológico"], "a": 2, "e": "También son de alto riesgo las insulinas, los anticoagulantes, los opioides y los citostáticos. Un error con ellos puede causar daño grave o la muerte."}, {"q": "En la técnica de comunicación estructurada SBAR (SAER), la letra «R» corresponde a:", "o": ["Recomendación: qué acción se propone o qué necesita el paciente", "Registro de constantes", "Riesgo de caídas", "Revisión de la medicación"], "a": 0, "e": "S es la situación actual, B (A en SAER) los antecedentes, A (E en SAER) la evaluación del profesional y R la recomendación. Se usa en los cambios de turno, traslados y avisos."}, {"q": "En la escala de Downton para el riesgo de caídas, se considera riesgo alto una puntuación:", "o": ["Igual a 0", "Inferior a 12", "Igual o superior a 45", "Superior a 2"], "a": 3, "e": "En Downton, a más puntos, más riesgo. En la escala de Morse el riesgo alto es a partir de 45, y en la de Braden de UPP menos puntos significan más riesgo (alto si ≤ 12)."}, {"q": "El análisis modal de fallos y efectos (AMFE) es una herramienta de gestión de riesgos de carácter:", "o": ["Retrospectivo, tras un evento centinela", "Exclusivamente económico", "Prospectivo, para anticipar qué puede fallar antes de implantar un proceso o una tecnología", "Sancionador"], "a": 2, "e": "El análisis causa-raíz, en cambio, es retrospectivo: se aplica tras un evento grave para averiguar por qué fallaron las barreras."}, {"q": "Tras un evento centinela, la metodología indicada para identificar las causas que lo originaron es:", "o": ["El análisis causa-raíz, por ejemplo con un diagrama de Ishikawa", "El AMFE", "La encuesta de satisfacción", "El ciclo PDCA sin análisis previo"], "a": 0, "e": "El análisis causa-raíz es retrospectivo y busca los fallos del sistema. El diagrama de Ishikawa o de espina de pez agrupa las causas en personas, métodos, materiales y entorno."}, {"q": "Uno de los principios básicos del SiNASP es:", "o": ["La obligatoriedad legal de notificar", "La no punibilidad: la información no puede usarse para sancionar", "La identificación pública del profesional que cometió el error", "Su uso para la evaluación del desempeño"], "a": 1, "e": "El SiNASP es voluntario, no punitivo, confidencial y permite el anonimato. Busca aprender de los fallos del sistema, no buscar culpables."}, {"q": "De las siguientes situaciones, la que NO debe notificarse en el SiNASP, sino tramitarse por vía disciplinaria o judicial, es:", "o": ["Un cuasi-incidente de medicación", "Una caída sin lesión de un paciente", "Un error de identificación detectado a tiempo", "La administración intencionada de un sedante no prescrito a un paciente molesto"], "a": 3, "e": "Se excluyen las infracciones intencionadas, los sabotajes, los abusos a pacientes y el ejercicio bajo los efectos del alcohol o drogas."}, {"q": "En la matriz de riesgo SAC, un incidente clasificado como SAC 1:", "o": ["Corresponde a un fallo administrativo sin impacto", "No requiere análisis", "Supone un riesgo extremo y obliga a un análisis causa-raíz urgente", "Equivale siempre a un cuasi-incidente"], "a": 2, "e": "La matriz cruza la probabilidad con la gravedad. SAC 1 es riesgo extremo (muerte o daño permanente) y SAC 4, riesgo bajo, donde se agrupan los cuasi-incidentes y los fallos administrativos."}, {"q": "Según el modelo de Donabedian, la ratio enfermera/paciente de una unidad es un indicador de:", "o": ["Estructura", "Proceso", "Resultado", "Satisfacción"], "a": 0, "e": "La estructura incluye los recursos humanos y materiales y la organización. El proceso es lo que se hace y cómo se hace, y el resultado, el efecto sobre la salud del paciente."}, {"q": "«Porcentaje de pacientes ingresados con la escala de Braden registrada al ingreso» es un indicador de:", "o": ["Estructura", "Resultado", "Satisfacción", "Proceso"], "a": 3, "e": "Registrar que la enfermera hace la valoración o aplica un protocolo mide el proceso. La aparición de UPP o de caídas mide el resultado."}, {"q": "La prevalencia de úlceras por presión adquiridas durante el ingreso es un indicador de:", "o": ["Estructura", "Resultado", "Proceso", "Accesibilidad"], "a": 1, "e": "Mide el efecto final de los cuidados en el paciente. Se calcula como pacientes con UPP en el momento del corte entre pacientes evaluados, por 100."}, {"q": "Una técnica de cura que acelera la epitelización en pacientes reales atendidos en su domicilio en atención primaria demuestra su:", "o": ["Eficacia", "Eficiencia", "Efectividad", "Legitimidad"], "a": 2, "e": "La eficacia se mide en condiciones ideales o experimentales (ensayo clínico); la efectividad, en la práctica real; y la eficiencia relaciona el resultado con el coste."}, {"q": "La dimensión de la calidad que relaciona los resultados obtenidos con los costes y recursos empleados es la:", "o": ["Eficiencia", "Eficacia", "Aceptabilidad", "Equidad"], "a": 0, "e": "La optimización es el punto de máximo equilibrio entre beneficio y coste, la aceptabilidad la adecuación a las preferencias del paciente y la equidad el reparto justo según la necesidad."}, {"q": "El orden de las fases del ciclo de mejora continua de Deming (PDCA) es:", "o": ["Hacer, planificar, actuar y verificar", "Verificar, planificar, hacer y actuar", "Actuar, verificar, planificar y hacer", "Planificar, hacer, verificar y actuar"], "a": 3, "e": "Es un ciclo circular y continuo: tras actuar (estandarizar la mejora o corregir), se vuelve a planificar para seguir mejorando."}, {"q": "La tasa de incidencia de caídas en pacientes hospitalizados se expresa habitualmente como:", "o": ["Caídas por cada 100 camas", "Caídas por cada 1.000 días de estancia", "Caídas por cada enfermera", "Porcentaje de pacientes que se caen al año"], "a": 1, "e": "Expresarla por días de estancia permite comparar unidades de distinto tamaño. Las tasas de UPP y de flebitis se expresan en porcentaje (× 100)."}, {"q": "La característica de un indicador de calidad que implica que dos observadores distintos obtengan el mismo resultado al medir la misma situación es la:", "o": ["Validez", "Sensibilidad", "Fiabilidad", "Relevancia"], "a": 2, "e": "La validez es medir lo que se pretende medir; la sensibilidad, detectar cambios; la especificidad, captar solo lo que depende de la intervención; y la factibilidad, que los datos sean fáciles de obtener."}, {"q": "Para obtener una muestra de orina en un paciente con sonda vesical permanente, lo correcto es:", "o": ["Puncionar el puerto de toma de muestras, previa desinfección, sin abrir el circuito", "Desconectar la sonda de la bolsa y recoger la orina", "Tomar la orina de la bolsa colectora", "Retirar la sonda y recoger la primera micción"], "a": 0, "e": "Abrir el circuito cerrado es la principal puerta de entrada de microorganismos y aumenta las infecciones urinarias asociadas a la sonda."}, {"q": "La higiene diaria del meato urinario en un paciente sondado se realiza con:", "o": ["Clorhexidina jabonosa al 4%", "Povidona yodada", "Alcohol de 70°", "Agua y jabón neutro"], "a": 3, "e": "Los antisépticos de rutina alteran la flora protectora y no reducen las infecciones."}, {"q": "En el Proyecto HU-CI, la minimización del uso de sujeciones mecánicas pertenece a la línea estratégica de:", "o": ["Cuidados al profesional", "Bienestar del paciente", "Infraestructura humanizada", "Síndrome post-UCI"], "a": 1, "e": "Esta línea incluye también el control del dolor, la sedación ligera y el respeto del sueño. Los cuidados al profesional se centran en el burnout del personal."}, {"q": "La línea del Proyecto HU-CI que aborda las secuelas físicas, cognitivas y psicológicas de los supervivientes tras el alta de la UCI es:", "o": ["Cuidados al profesional", "UCI de puertas abiertas", "Prevención, manejo y seguimiento del síndrome post-UCI", "Comunicación"], "a": 2, "e": "Incluye la debilidad adquirida, los problemas tras el delirio y el estrés postraumático, con consultas de seguimiento multidisciplinares. La línea de cuidados al profesional trata el burnout y la fatiga por compasión."}, {"q": "En el manual de buenas prácticas del Proyecto HU-CI, las prácticas se clasifican en los niveles:", "o": ["Básica, avanzada y excelente", "Bronce, plata y oro", "Inicial, medio y superior", "A, B y C"], "a": 0, "e": "Son unas 160 buenas prácticas certificables. Las básicas son de cumplimiento obligatorio y las excelentes representan el máximo nivel de humanización."}, {"q": "En el protocolo EPICEE (SPIKES) de comunicación de malas noticias, la primera «E» corresponde a:", "o": ["Empatía", "Escucha activa", "Estrategia", "Entorno"], "a": 3, "e": "Primero se prepara el entorno: lugar privado, sin interrupciones y sentados a la misma altura. Las dos E finales son la empatía y la estrategia o resumen."}, {"q": "Antes de comunicar un diagnóstico grave, preguntar al paciente «¿qué le han contado los médicos hasta ahora?» corresponde, en el protocolo EPICEE, a la fase de:", "o": ["Entorno", "Percepción", "Invitación", "Conocimiento"], "a": 1, "e": "Después, en la invitación, se averigua cuánta información desea recibir, respetando su derecho a no saber. Solo entonces se da la noticia (conocimiento), se responde a las emociones (empatía) y se plantea el plan (estrategia)."}]},
55: {"tema": 55, "titulo": "Atención de enfermería a personas en situación de dependencia. Ley 39/2006, de Promoción de la Autonomía Personal y Atención a las personas en situación de dependencia. Coordinación sociosanitaria", "programa": "Atención de enfermería a personas en situación de dependencia. Ley 39/2006, de 14 de diciembre: SAAD, grados, catálogo de servicios y prestaciones, cuidador no profesional y procedimiento. Instrumentos de valoración (BVD, EVE y escalas geriátricas). Coordinación sociosanitaria en la Región de Murcia.", "preguntas": [{"q": "La Ley de Promoción de la Autonomía Personal y Atención a las personas en situación de dependencia es la:", "o": ["Ley 39/2006, de 14 de noviembre", "Ley 41/2002, de 14 de noviembre", "Ley 39/2006, de 14 de diciembre", "Ley 39/2007, de 15 de diciembre"], "a": 2, "e": "Se la conoce como el «cuarto pilar del Estado del bienestar» y desarrolla los artículos 49 y 50 de la Constitución. Las fechas de noviembre son trampas habituales."}, {"q": "La Ley 39/2006 crea, como red de utilización pública que integra centros y servicios públicos y privados concertados:", "o": ["El Sistema para la Autonomía y Atención a la Dependencia (SAAD)", "El Instituto de Mayores y Servicios Sociales", "El Consejo Interterritorial del SNS", "La Red de Servicios Sociales Comunitarios"], "a": 0, "e": "El SAAD reúne recursos de la Administración General del Estado y de las comunidades autónomas, y permite concertar con entidades privadas y del tercer sector."}, {"q": "El nivel mínimo de protección del SAAD:", "o": ["Lo financia exclusivamente cada comunidad autónoma", "Lo pagan íntegramente los usuarios", "Se establece por convenio entre el Estado y la comunidad", "Lo garantiza y financia íntegramente la Administración General del Estado"], "a": 3, "e": "El nivel acordado se financia mediante convenios entre el Estado y cada comunidad, que aporta al menos lo mismo. El nivel adicional lo añade cada comunidad con sus propios fondos."}, {"q": "Según la Ley 39/2006, la dependencia se define como:", "o": ["La capacidad de tomar decisiones propias sobre cómo vivir", "El estado de carácter permanente en que la persona, por edad, enfermedad o discapacidad, precisa la ayuda de otras personas para las actividades básicas de la vida diaria", "La necesidad de ayuda temporal tras una intervención quirúrgica", "La pérdida de capacidad para manejar el dinero y el teléfono"], "a": 1, "e": "La capacidad de controlar y tomar decisiones propias es la definición de autonomía. Manejar el dinero o el teléfono son actividades instrumentales, que no determinan el grado."}, {"q": "Una persona que necesita ayuda para varias actividades básicas de la vida diaria dos o tres veces al día, sin requerir el apoyo permanente de un cuidador, tiene una dependencia de:", "o": ["Grado I, moderada", "Grado III, gran dependencia", "Sin grado", "Grado II, severa"], "a": 3, "e": "Grado I: ayuda al menos una vez al día. Grado II: dos o tres veces al día. Grado III: varias veces al día con apoyo indispensable y continuo de otra persona."}, {"q": "La gran dependencia (grado III) se caracteriza por:", "o": ["Necesitar ayuda varias veces al día y el apoyo indispensable y continuo de otra persona", "Necesitar ayuda una vez al día", "Necesitar ayuda solo para tareas domésticas", "Necesitar apoyo intermitente para la autonomía personal"], "a": 0, "e": "Corresponde a 75-100 puntos en el BVD. Los niveles que la ley establecía dentro de cada grado se suprimieron."}, {"q": "Un solicitante obtiene 49 puntos en el Baremo de Valoración de la Dependencia. Le corresponde:", "o": ["Sin grado", "Grado II", "Grado I", "Grado III"], "a": 2, "e": "De 0 a 24 puntos no hay grado; de 25 a 49, grado I; de 50 a 74, grado II; y de 75 a 100, grado III. Con 50 puntos ya sería grado II."}, {"q": "El grado de dependencia se determina valorando:", "o": ["Únicamente las actividades instrumentales (teléfono, compras, transporte)", "La necesidad de ayuda en las actividades básicas de la vida diaria", "Solo el diagnóstico médico", "Los ingresos económicos de la persona"], "a": 1, "e": "Las actividades instrumentales sirven para la valoración clínica (escala de Lawton), pero los grados de la ley se basan en las actividades básicas."}, {"q": "Según la filosofía de la Ley 39/2006, en el catálogo del SAAD:", "o": ["Los servicios tienen prioridad y las prestaciones económicas son excepcionales", "Las prestaciones económicas tienen prioridad", "Solo existen prestaciones económicas", "La residencia es siempre el primer recurso"], "a": 0, "e": "Además, el principio de permanencia en el entorno da prioridad a los recursos que permiten seguir viviendo en el domicilio."}, {"q": "El servicio de teleasistencia del catálogo del SAAD:", "o": ["Es incompatible con cualquier otro servicio", "Solo se concede a grandes dependientes", "Es compatible con el resto de servicios y prestaciones, salvo con la atención residencial", "Sustituye a la ayuda a domicilio"], "a": 2, "e": "La residencia ya garantiza la supervisión las 24 horas. Por regla general, la atención residencial es incompatible con la ayuda a domicilio, el centro de día y las prestaciones económicas."}, {"q": "La prestación económica vinculada al servicio se concede cuando:", "o": ["Un familiar cuida al dependiente en casa", "Se contrata un asistente personal para estudiar o trabajar", "El dependiente renuncia a todos los servicios", "Existe derecho a un servicio, pero no hay plaza en la red pública o concertada, para pagar un centro privado acreditado"], "a": 3, "e": "La prestación de cuidados en el entorno familiar compensa al cuidador no profesional, y la de asistencia personal financia la contratación de un asistente que favorezca una vida independiente."}, {"q": "Para ser reconocido como cuidador no profesional, se exige tener con la persona dependiente un parentesco por consanguinidad, afinidad o adopción:", "o": ["Hasta el segundo grado", "Hasta el tercer grado", "Hasta el cuarto grado", "Sin límite de parentesco"], "a": 1, "e": "También debe ser mayor de 18 años, tener capacidad para cuidar y no ser dependiente. El tercer grado incluye tíos, sobrinos, bisabuelos y bisnietos."}, {"q": "Un anciano dependiente es cuidado por su primo hermano. ¿Cumple este el requisito de parentesco para ser cuidador no profesional?", "o": ["No, porque los primos son parientes de cuarto grado", "Sí, porque es familia directa", "Sí, si convive con él", "Sí, porque es pariente de segundo grado"], "a": 0, "e": "La ley exige parentesco hasta el tercer grado inclusive. Los hermanos son de segundo grado y los tíos y sobrinos, de tercero."}, {"q": "El plazo máximo para resolver el reconocimiento de la situación de dependencia y el programa individual de atención es de:", "o": ["1 mes", "3 meses", "12 meses", "6 meses"], "a": 3, "e": "Si se supera, la persona tiene derecho a percibir con efectos retroactivos las cantidades correspondientes desde que venció el plazo."}, {"q": "Si una persona con dependencia reconocida y PIA en vigor se traslada de forma permanente a otra comunidad autónoma, la comunidad de origen mantiene la prestación durante:", "o": ["15 días", "6 meses", "60 días", "1 año"], "a": 2, "e": "Ese plazo permite que la comunidad de destino estudie el caso y apruebe un nuevo programa individual de atención con sus propios recursos."}, {"q": "Es una causa legal para revisar el grado de dependencia:", "o": ["La mejoría o el empeoramiento de la situación de dependencia", "El cambio de opinión del usuario sobre el recurso que prefiere", "El cambio de médico de familia", "El paso de un año desde la resolución"], "a": 0, "e": "Las otras causas son el error de diagnóstico o en la aplicación del baremo y el cambio de la situación personal o del entorno que obligue a modificar el PIA, por ejemplo, el fallecimiento del cuidador."}, {"q": "Sobre el Baremo de Valoración de la Dependencia (BVD), es correcto que:", "o": ["Lo rellena el propio solicitante en su domicilio", "Lo aplica un profesional mediante observación directa, a partir de los 3 años, valorando 47 tareas en 10 actividades", "Se aplica a menores de 3 años", "Da una puntuación de 1, 2 o 3"], "a": 1, "e": "Lo regula el RD 174/2011. En la Región de Murcia lo aplican los valoradores del IMAS en el entorno habitual de la persona, con el informe de salud del médico de atención primaria."}, {"q": "Para valorar la dependencia en un niño de 18 meses se utiliza:", "o": ["El Baremo de Valoración de la Dependencia, sobre 100 puntos", "El índice de Barthel", "La escala de Lawton", "La Escala de Valoración Específica (EVE)"], "a": 3, "e": "La EVE se aplica de 0 a 35 meses y otorga directamente 1, 2 o 3 puntos, que corresponden a los grados I, II y III."}, {"q": "En el índice de Barthel, las actividades que pueden puntuar hasta 15 puntos son:", "o": ["Comer y vestirse", "Bañarse y arreglarse", "El traslado cama-sillón y la deambulación", "La continencia urinaria y fecal"], "a": 2, "e": "Comer, vestirse, deposición, micción, retrete y escaleras valen hasta 10, y baño y arreglarse, 5. El máximo es 100, o 90 en un paciente autónomo en silla de ruedas."}, {"q": "Una puntuación inferior a 20 en el índice de Barthel indica:", "o": ["Dependencia total", "Dependencia leve", "Dependencia moderada", "Independencia"], "a": 0, "e": "60 o más es dependencia leve, 40-55 moderada, 20-35 grave y menos de 20, total."}, {"q": "En el índice de Katz, la categoría G significa:", "o": ["Independencia en todas las funciones", "Dependencia solo en el baño", "Dependencia en una función", "Dependencia en las seis funciones"], "a": 3, "e": "Katz clasifica con letras de la A (independiente en todas) a la G. Valora baño, vestido, uso del retrete, movilidad, continencia y alimentación."}, {"q": "La escala de Lawton y Brody valora:", "o": ["Las actividades básicas de la vida diaria", "Las actividades instrumentales de la vida diaria, que son las primeras en deteriorarse con el deterioro cognitivo", "El riesgo de úlceras por presión", "La sobrecarga del cuidador"], "a": 1, "e": "Tiene 8 ítems (teléfono, compras, comida, hogar, ropa, transporte, medicación y dinero), con una puntuación de 0 a 8. Se le atribuye un sesgo de género en algunos ítems."}, {"q": "La puntuación máxima del Mini-Examen Cognoscitivo (MEC) de Lobo es de:", "o": ["30 puntos", "10 puntos", "35 puntos", "100 puntos"], "a": 2, "e": "El MMSE original de Folstein tiene 30 puntos. El MEC se corrige según la edad y la escolaridad y una puntuación de 23 o menos sugiere deterioro cognitivo."}, {"q": "Un paciente comete 6 errores en el cuestionario de Pfeiffer. Esto indica:", "o": ["Deterioro cognitivo moderado", "Función cognitiva normal", "Deterioro cognitivo leve", "Deterioro cognitivo grave"], "a": 0, "e": "En el Pfeiffer se cuentan los errores: 0-2 normal, 3-4 leve, 5-7 moderado y 8-10 grave. Se permite un error más si no tiene estudios y uno menos con estudios superiores."}, {"q": "En la escala sociofamiliar de Gijón, indica riesgo social alto una puntuación:", "o": ["Inferior a 5", "De 7 a 9", "Igual a 10", "Superior a 15"], "a": 3, "e": "Valora 5 áreas (situación familiar, económica, vivienda, relaciones sociales y apoyos) de 1 a 5, con un rango de 5 a 25."}, {"q": "Una cuidadora obtiene 18 puntos en la versión abreviada de 7 ítems de la escala de Zarit. Esto indica:", "o": ["Ausencia de sobrecarga", "Sobrecarga intensa", "Sobrecarga leve", "Que debe repetirse con la versión completa"], "a": 1, "e": "La versión abreviada (7-35 puntos) es dicotómica: 17 o más indica sobrecarga intensa. En la completa (22 ítems), 47-55 es leve y 56 o más, intensa."}, {"q": "La función principal de la enfermera gestora de casos del SMS es:", "o": ["Hacer las curas y extracciones diarias en el domicilio", "Sustituir al médico de familia", "Gestionar la complejidad y coordinar recursos y niveles asistenciales para el paciente con dependencia grave", "Aplicar el baremo oficial de dependencia"], "a": 2, "e": "Valora en el domicilio con los patrones de Gordon (el más alterado suele ser actividad-ejercicio), activa vías rápidas, gestiona material y oxígeno y coordina con el IMAS. Los cuidados de rutina los presta la enfermera de atención primaria."}, {"q": "En la alimentación de un paciente dependiente con disfagia se recomienda:", "o": ["Evitar las dobles texturas, como la sopa de fideos o el yogur con trozos", "Ofrecer líquidos sin espesar para facilitar el paso", "Comer en decúbito supino", "Usar pajita para los líquidos"], "a": 0, "e": "Las dobles texturas aumentan el riesgo de aspiración. Se usan alimentos de textura homogénea y espesantes hasta la viscosidad segura (néctar, miel o pudin) y se cuida la higiene oral antes y después."}, {"q": "Tras la ingesta, un paciente con disfagia debe permanecer:", "o": ["Tumbado en decúbito supino para descansar", "En Trendelenburg", "En decúbito prono", "Incorporado, a unos 45°, durante al menos 45 minutos"], "a": 3, "e": "Durante la comida debe estar sentado a 90°. Tumbarlo justo después favorece el reflujo y la neumonía por aspiración, principal causa de muerte en el gran dependiente."}, {"q": "El convenio especial de la Seguridad Social para cuidadores no profesionales NO protege:", "o": ["La jubilación", "El desempleo", "La incapacidad permanente", "La muerte y supervivencia derivada de enfermedad común"], "a": 1, "e": "Tampoco protege la incapacidad temporal. Se tramita con el formulario TA-0040 ante la Tesorería General de la Seguridad Social, aportando la resolución y el PIA."}]},
56: {"tema": 56, "titulo": "Participación en la formación sanitaria especializada y de grado en enfermería. Formación y desarrollo profesional continuo", "programa": "Participación en la formación de grado en enfermería (EEES, plan de estudios, prácticas, figuras docentes) y en la formación sanitaria especializada (especialidades, residencia, tutor, comisión de docencia y evaluación). Formación continuada, acreditación y desarrollo profesional: diplomas de acreditación y carrera profesional.", "preguntas": [{"q": "En el Espacio Europeo de Educación Superior, un crédito ECTS equivale a:", "o": ["10 horas de clase teórica", "Entre 25 y 30 horas de trabajo total del estudiante", "50 horas de prácticas clínicas", "Una semana de prácticas"], "a": 1, "e": "El ECTS mide todo el trabajo del alumno: clases, prácticas, seminarios, tutorías y estudio autónomo. Una asignatura de 6 ECTS supone 150-180 horas."}, {"q": "Según la Orden CIN/2134/2008, el título de Grado en Enfermería tiene una carga de:", "o": ["180 créditos ECTS en 3 años", "300 créditos ECTS en 5 años", "200 créditos ECTS en 4 años", "240 créditos ECTS en 4 años"], "a": 3, "e": "Son 60 ECTS por curso. La antigua diplomatura duraba 3 años y se sustituyó por el grado tras la integración en el EEES."}, {"q": "El módulo de formación básica común del Grado en Enfermería tiene una carga de:", "o": ["60 ECTS", "30 ECTS", "90 ECTS", "120 ECTS"], "a": 0, "e": "Incluye anatomía, fisiología, bioquímica, psicología, estadística y otras materias básicas, y se imparte sobre todo en los primeros cursos."}, {"q": "El módulo de prácticas tuteladas y Trabajo Fin de Grado del Grado en Enfermería suma:", "o": ["36 ECTS", "60 ECTS", "90 ECTS", "120 ECTS"], "a": 2, "e": "Es el bloque con más peso. Según el manual, el TFG supone 6 ECTS y el resto corresponde a las prácticas clínicas."}, {"q": "Según el RD 1125/2003, las calificaciones del grado se expresan:", "o": ["En una escala de 0 a 10 con un decimal, junto con su calificación cualitativa", "En una escala de 0 a 100", "Solo como apto o no apto", "En letras de la A a la F"], "a": 0, "e": "0-4,9 suspenso; 5-6,9 aprobado; 7-8,9 notable; 9-10 sobresaliente. Un 4,9 es suspenso y no se redondea."}, {"q": "La mención de matrícula de honor puede concederse a alumnos con una calificación:", "o": ["De notable, sin límite de número", "De 8,5 o más, hasta el 10% de los alumnos", "De 10, sin límite", "De 9 o más, hasta un máximo del 5% de los matriculados"], "a": 3, "e": "Si hay menos de 20 alumnos matriculados en la asignatura, puede concederse una sola matrícula de honor."}, {"q": "En una asignatura con 15 alumnos matriculados, el número máximo de matrículas de honor que se puede conceder es:", "o": ["Ninguna", "Una", "Dos", "Tres"], "a": 1, "e": "El límite general es el 5% de los matriculados, pero cuando hay menos de 20 alumnos se permite una matrícula de honor."}, {"q": "Según el RD 1558/1986 de conciertos entre universidades e instituciones sanitarias, la universidad que imparta Enfermería debe disponer al menos de:", "o": ["Un centro de salud", "Dos hospitales", "Un hospital y tres centros de atención primaria universitarios", "Tres hospitales y un centro de salud"], "a": 2, "e": "La LOPS establece además que toda la estructura asistencial del sistema sanitario debe estar disponible para la docencia."}, {"q": "La figura del colaborador docente en las prácticas de grado se caracteriza por ser:", "o": ["Un profesor titular de la universidad", "Un profesor asociado con contrato a tiempo parcial con la universidad", "Un estudiante de cursos superiores", "Una enfermera asistencial de la unidad que supervisa al estudiante sin vínculo contractual con la universidad"], "a": 3, "e": "Actúa como modelo de rol en el día a día de las prácticas. Su labor se reconoce con certificados que puntúan como mérito y en la carrera profesional. El profesor asociado sí tiene contrato con la universidad."}, {"q": "Si un estudiante de grado comete un error de dosificación durante sus prácticas, es correcto que:", "o": ["La responsabilidad de la supervisión y de la seguridad del paciente recae en el profesional que lo tutela", "La responsabilidad es exclusiva del estudiante", "Nadie es responsable por ser un alumno en formación", "La responsabilidad es exclusiva de la universidad"], "a": 0, "e": "El estudiante no tiene habilitación legal para ejercer: cualquier técnica debe hacerla bajo supervisión directa del profesional que lo tutela."}, {"q": "La norma que estableció el catálogo de especialidades de enfermería es el:", "o": ["RD 183/2008", "RD 1146/2006", "RD 450/2005", "RD 639/2015"], "a": 2, "e": "El RD 183/2008 organiza la formación especializada, el RD 1146/2006 regula la relación laboral del residente y el RD 639/2015, los diplomas de acreditación."}, {"q": "La duración del programa de formación como residente (EIR) en las especialidades de enfermería es de:", "o": ["1 año", "2 años", "3 años", "4 años"], "a": 1, "e": "Las siete especialidades del RD 450/2005 duran 2 años a tiempo completo, incluida la de matrona."}, {"q": "La especialidad de enfermería que figura en el RD 450/2005 pero no cuenta con programa formativo ni plazas EIR es la de:", "o": ["Cuidados médico-quirúrgicos", "Enfermería geriátrica", "Enfermería del trabajo", "Enfermería pediátrica"], "a": 0, "e": "Las demás (matrona, salud mental, del trabajo, familiar y comunitaria, pediátrica y geriátrica) están desarrolladas y convocan plazas cada año."}, {"q": "La relación laboral especial de residencia (jornada, guardias, descansos y retribuciones del residente) está regulada por el:", "o": ["RD 450/2005", "RD 183/2008", "RD 589/2022", "RD 1146/2006"], "a": 3, "e": "Entre otras cosas, establece un descanso mínimo de 12 horas consecutivas entre jornadas."}, {"q": "El RD 183/2008 regula principalmente:", "o": ["El plan de estudios del Grado en Enfermería", "Las prestaciones de la Ley de Dependencia", "Los órganos docentes de la formación sanitaria especializada (comisión de docencia, jefe de estudios, tutores) y la evaluación del residente", "La carrera profesional del personal estatutario"], "a": 2, "e": "Es la norma organizativa de la formación sanitaria especializada. El plan de estudios del grado lo regula la Orden CIN/2134/2008."}, {"q": "La Comisión de Docencia de un centro con formación especializada está presidida por:", "o": ["El jefe de estudios de formación especializada", "El director gerente del área", "El director de enfermería", "El tutor más antiguo"], "a": 0, "e": "La comisión es un órgano colegiado que organiza la formación y supervisa el cumplimiento de los programas. El jefe de estudios dirige la planificación y la gestión de la docencia especializada."}, {"q": "Según el RD 183/2008, cada tutor puede tener asignados como máximo:", "o": ["2 residentes", "5 residentes", "10 residentes", "Sin límite"], "a": 1, "e": "En un área de capacitación específica, el tutor solo puede tener un especialista en formación."}, {"q": "En la evaluación anual del residente, la calificación oficial la otorga:", "o": ["El tutor, mediante su informe", "El colaborador docente de la última rotación", "El propio residente", "El Comité de Evaluación"], "a": 3, "e": "El tutor informa y el comité califica. El informe anual del tutor es el instrumento básico para la valoración, pero no es la calificación."}, {"q": "El Comité de Evaluación debe reunirse para la evaluación anual del residente:", "o": ["En los 30 días posteriores al fin del año formativo", "Al inicio del año formativo", "En los 15 días anteriores a la conclusión del año formativo", "Solo al final de la residencia"], "a": 2, "e": "Lo preside el jefe de estudios e incluye al tutor del residente, un especialista del centro y un vocal designado por la comunidad autónoma."}, {"q": "Una evaluación anual negativa no recuperable del residente supone:", "o": ["La extinción del contrato", "La repetición automática del año completo", "Una amonestación sin consecuencias", "La promoción al año siguiente con un plan de mejora"], "a": 0, "e": "Se produce por faltas de asistencia injustificadas, falta de aprovechamiento o insuficiencias insalvables. En la negativa recuperable, el contrato se prorroga con un programa de recuperación."}, {"q": "El instrumento en el que el residente registra sus rotaciones, sesiones y actividades, que sirve para la evaluación formativa, es:", "o": ["El expediente académico", "El libro del residente", "El Plan Individual de Formación", "El informe anual del tutor"], "a": 1, "e": "El Plan Individual de Formación lo elabora el tutor para adaptar el programa oficial al residente, y el informe anual del tutor es la base de la evaluación anual."}, {"q": "Según la Ley 44/2003 (LOPS), la formación continuada de los profesionales sanitarios es:", "o": ["Voluntaria y sin efectos", "Exclusivamente un deber", "Exclusivamente un derecho", "Un derecho y un deber"], "a": 3, "e": "Como derecho, los centros deben facilitar el acceso a la formación; como deber, el profesional debe mantener actualizada su competencia."}, {"q": "Los créditos de formación continuada de una actividad acreditada por la comisión de una comunidad autónoma:", "o": ["Solo son válidos en esa comunidad", "Solo son válidos en el centro organizador", "Tienen validez en todo el territorio nacional", "Caducan a los dos años"], "a": 2, "e": "El sistema de acreditación garantiza que los créditos se reconozcan en toda España, en bolsas de trabajo, traslados y carrera profesional."}, {"q": "En la Comisión de Formación Continuada de la Región de Murcia (Decreto 223/2006), el secretario:", "o": ["Asiste con voz pero sin voto", "Tiene voto de calidad en caso de empate", "Preside la comisión", "No asiste a las sesiones"], "a": 0, "e": "La comisión está adscrita a la Consejería de Sanidad y se encarga del asesoramiento en materia de formación y de la acreditación de actividades."}, {"q": "A diferencia del crédito ECTS, el crédito de formación continuada (CFC) se calcula:", "o": ["Igual que el ECTS, a razón de 25-30 horas", "Solo según el número de alumnos", "Según el precio de la matrícula", "Con un criterio mixto: un componente cuantitativo (horas lectivas) ponderado por un componente cualitativo"], "a": 3, "e": "Como orientación, un CFC equivale a unas 10 horas lectivas, pero su valor final depende de la evaluación de la calidad de la actividad."}, {"q": "Uno de los apartados que se valoran en la evaluación cualitativa de una actividad para acreditarla como formación continuada es:", "o": ["El precio de la matrícula", "La pertinencia de la actividad respecto a las necesidades del sistema sanitario", "La categoría de la entidad organizadora", "El número de patrocinadores"], "a": 1, "e": "Los cinco apartados son objetivos, organización, pertinencia, metodología y evaluación. Se valoran más las metodologías activas como la simulación o el aprendizaje basado en problemas."}, {"q": "Los diplomas de acreditación y de acreditación avanzada, que certifican la competencia en un área funcional específica, están regulados por el:", "o": ["RD 450/2005", "RD 183/2008", "RD 639/2015", "RD 1125/2003"], "a": 2, "e": "Reconocen la experiencia y la formación de un profesional en un área concreta, como los cuidados paliativos, pero no equivalen a una especialidad."}, {"q": "En el Servicio Murciano de Salud, la carrera profesional del personal estatutario se ampara en:", "o": ["La Ley 5/2001 de personal estatutario del SMS, con un grado inicial y niveles I a IV", "La Orden CIN/2134/2008", "El RD 1146/2006", "La Ley 39/2006"], "a": 0, "e": "Se desarrolla con acuerdos de la Mesa Sectorial de Sanidad. Se valoran la actividad asistencial, la formación, la docencia e investigación y el compromiso con la organización."}, {"q": "Para ascender de un nivel de carrera profesional al siguiente en el SMS, además de los méritos, se exige una permanencia mínima en el nivel anterior de:", "o": ["1 año", "2 años", "3 años", "5 años"], "a": 3, "e": "El tiempo mínimo es un requisito previo: sin cumplirlo no se pueden baremar los méritos."}, {"q": "En los niveles más altos de la carrera profesional, el peso de la evaluación se desplaza hacia:", "o": ["La simple asistencia a cursos", "La actividad docente e investigadora (tutor EIR, colaborador docente, publicaciones)", "La antigüedad sin otros méritos", "Las horas extraordinarias realizadas"], "a": 1, "e": "Se espera que el profesional pase de receptor a emisor de conocimiento, liderando la docencia y la investigación."}]}
};
